# ════════════════════════════════════════════════════════════════════════════
# Lymphatic-pulse helpers (GUI-agnostic; reused by _open_recon_pulse_analyzer)
# Operate on a working 2D stack `proj` of shape (T, H, W). All spatial outputs
# are in µm at the user-supplied px_um; time outputs in seconds at fps Hz.
# ════════════════════════════════════════════════════════════════════════════
def _recon_proj_2d(vol_HWDT, mode, z_sel=None, z_range=None):
    """Reduce (H, W, D, T) -> proj (T, H, W). mode in {'slice', 'mip'}.
    'slice': proj[t] = vol[:, :, z_sel, t]. 'mip': proj[t] = vol[:, :, z0:z1+1, t].max(2)."""
    H, W, D, T = vol_HWDT.shape
    if mode == 'slice':
        z = max(0, min(int(z_sel), D - 1))
        return np.ascontiguousarray(vol_HWDT[:, :, z, :].transpose(2, 0, 1))
    elif mode == 'mip':
        z0, z1 = z_range
        z0 = max(0, min(int(z0), D - 1)); z1 = max(z0, min(int(z1), D - 1))
        return np.ascontiguousarray(vol_HWDT[:, :, z0:z1 + 1, :].max(axis=2).transpose(2, 0, 1))
    raise ValueError(f"unknown projection mode: {mode!r}")


def _focus_score_2d(img2d, method='var_laplacian'):
    """Higher = sharper. var-of-Laplacian (3x3) for fast in-focus detection."""
    from scipy import ndimage as _ndi
    a = np.asarray(img2d, np.float32)
    if method == 'var_laplacian':
        lap = _ndi.laplace(a)
        return float(np.var(lap))
    # Tenengrad gradient energy
    gx = _ndi.sobel(a, axis=1); gy = _ndi.sobel(a, axis=0)
    return float(np.mean(gx * gx + gy * gy))


def _auto_best_focus_depth(vol_HWDT, mask=None):
    """Pick z that maximizes focus score on the time-mean frame
    (optionally restricted to the boolean mask)."""
    D = vol_HWDT.shape[2]
    scores = np.empty(D, np.float64)
    for z in range(D):
        m = vol_HWDT[:, :, z, :].mean(axis=2)
        if mask is not None and mask.any():
            mm = m[mask]
            scores[z] = _focus_score_2d(mm.reshape(-1, 1)) if mm.ndim == 1 else _focus_score_2d(mm)
        else:
            scores[z] = _focus_score_2d(m)
    return int(np.argmax(scores)), scores


def _sample_along_polyline(pts_xy, n_samples):
    """Resample an ordered polyline at N equally arc-spaced points.
    pts_xy: (M,2) array of (x,y). Returns (centers Nx2, tangents Nx2 unit, arclen N in px)."""
    P = np.asarray(pts_xy, float)
    if P.ndim != 2 or P.shape[0] < 2:
        return None, None, None
    seg = np.diff(P, axis=0)                         # (M-1, 2)
    seg_len = np.hypot(seg[:, 0], seg[:, 1])         # (M-1,)
    cum = np.concatenate([[0.0], np.cumsum(seg_len)])
    total = float(cum[-1])
    if total < 1e-9:
        return None, None, None
    targets = np.linspace(0.0, total, int(max(2, n_samples)))
    centers = np.empty((len(targets), 2), float)
    tangents = np.empty((len(targets), 2), float)
    for i, td in enumerate(targets):
        # find segment containing td
        k = int(np.searchsorted(cum, td, side='right') - 1)
        k = max(0, min(k, len(seg) - 1))
        t = (td - cum[k]) / (seg_len[k] + 1e-12)
        centers[i] = P[k] + t * seg[k]
        # tangent = local segment direction (forward); unit-normalize
        tv = seg[k] / (seg_len[k] + 1e-12)
        tangents[i] = tv
    return centers, tangents, targets


def _perp_profile(img2d, center_xy, tangent_xy, length_px, n_samples=None):
    """Bilinear-interp 1D intensity profile perpendicular to ``tangent_xy`` through
    ``center_xy``, length ``length_px`` (centered). Uses scipy.ndimage.map_coordinates.
    Returns the 1D profile (length n_samples, default = round(length_px) + 1)."""
    from scipy.ndimage import map_coordinates
    cx, cy = float(center_xy[0]), float(center_xy[1])
    tx, ty = float(tangent_xy[0]), float(tangent_xy[1])
    # perpendicular unit vector (rotate tangent 90 CCW): (-ty, tx)
    px, py = -ty, tx
    L = float(length_px)
    n = int(round(L) + 1) if n_samples is None else int(n_samples)
    s = np.linspace(-L / 2.0, L / 2.0, n)
    xs = cx + s * px
    ys = cy + s * py
    # map_coordinates uses (row, col) = (y, x)
    prof = map_coordinates(img2d, np.vstack([ys, xs]), order=1, mode='nearest')
    return prof.astype(np.float32)


def _fwhm_from_profile(profile, frac=0.5):
    """Width (px) at ``frac × (max − base)`` of a 1D profile. Base = min over the
    profile; peak = max. Linear-interpolate left/right crossings; NaN if invalid."""
    p = np.asarray(profile, float)
    if p.size < 3:
        return float('nan')
    base = float(p.min()); peak = float(p.max())
    if peak - base < 1e-9:
        return float('nan')
    thr = base + frac * (peak - base)
    above = p >= thr
    if not above.any():
        return float('nan')
    # locate the contiguous run that contains the global argmax (the main peak)
    pk = int(np.argmax(p))
    # left crossing: rightmost i < pk where above[i] is False  ->  interp i..i+1
    li = pk
    while li > 0 and above[li - 1]:
        li -= 1
    # ri: leftmost i > pk where above[i] is False
    ri = pk
    while ri < len(p) - 1 and above[ri + 1]:
        ri += 1
    # left interp
    if li == 0:
        left = 0.0
    else:
        y0, y1 = p[li - 1], p[li]
        left = (li - 1) + (thr - y0) / (y1 - y0 + 1e-12)
    # right interp
    if ri == len(p) - 1:
        right = float(len(p) - 1)
    else:
        y0, y1 = p[ri], p[ri + 1]
        right = ri + (thr - y0) / (y1 - y0 + 1e-12)
    w = float(right - left)
    return w if w > 0 else float('nan')


def _diameter_kymograph(proj_THW, centers, tangents, profile_len_px, fwhm_frac, px_um):
    """For each centerline sample point and frame, FWHM lumen width in µm.
    Returns diam_um[N, T]."""
    T = proj_THW.shape[0]; N = centers.shape[0]
    diam_um = np.full((N, T), np.nan, np.float32)
    for t in range(T):
        img = proj_THW[t]
        for i in range(N):
            prof = _perp_profile(img, centers[i], tangents[i], profile_len_px)
            w_px = _fwhm_from_profile(prof, fwhm_frac)
            if w_px == w_px:                          # not NaN
                diam_um[i, t] = w_px * px_um
    return diam_um


def _intensity_kymograph_band(proj_THW, centers, band_half_px, px_um):
    """Mean intensity in a small (2r+1)x(2r+1) box around each centerline point,
    per frame. Returns intens[N, T]. (Simple, robust; the full polyline-band
    version is fine but this matches each sampled point directly.)"""
    T, H, W = proj_THW.shape
    N = centers.shape[0]; r = max(0, int(band_half_px))
    intens = np.zeros((N, T), np.float32)
    cx = centers[:, 0].astype(int); cy = centers[:, 1].astype(int)
    for i in range(N):
        x = cx[i]; y = cy[i]
        x0, x1 = max(0, x - r), min(W, x + r + 1)
        y0, y1 = max(0, y - r), min(H, y + r + 1)
        if x1 > x0 and y1 > y0:
            intens[i] = proj_THW[:, y0:y1, x0:x1].mean(axis=(1, 2))
    return intens


def _pulse_metrics_from_trace(trace, fps, hp_window_s=5.0, prom_mult=0.5,
                              dist_s=0.3, savgol_w=7):
    """Generic pulse-detection from a 1D trace. savgol smooth -> high-pass detrend
    (uniform_filter1d of size hp_window_s*fps) -> find_peaks(prom=prom_mult*std,
    distance=dist_s*fps) -> hilbert envelope. Returns a dict with all arrays
    + scalar metrics. ``hp_window_s`` is the SECONDS scale of the slow drift to
    remove (5 s default suits lymphatic pulse; 2 s suits cardiac)."""
    from scipy.signal import savgol_filter, find_peaks, hilbert
    from scipy import ndimage as _ndi
    x = np.asarray(trace, float)
    n = len(x); fps = float(fps)
    if n < 3:
        return dict(n=n, fps=fps, signal_hp=x, envelope=x, peaks=np.array([], int),
                    intervals=np.array([]), rates_bpm=np.array([]),
                    amps=np.array([]), peak_times_s=np.array([]),
                    freq_cpm=float('nan'), interval_s_mean=float('nan'))
    w = int(max(3, savgol_w)); w |= 1                # odd
    w = min(w, n if n % 2 else n - 1)
    try:
        x_sm = savgol_filter(x, w, min(3, w - 1))
    except Exception:
        x_sm = _ndi.uniform_filter1d(x, max(3, w))
    hp = max(3, int(round(hp_window_s * fps)))
    x_hp = x_sm - _ndi.uniform_filter1d(x_sm, size=hp)
    pk, _ = find_peaks(x_hp, distance=max(1, int(round(dist_s * fps))),
                       prominence=np.std(x_hp) * prom_mult + 1e-12)
    env = np.abs(hilbert(x_hp - x_hp.mean()))
    t_ax = np.arange(n) / fps
    if len(pk) >= 2:
        intervals = np.diff(pk) / fps
        rates_bpm = 60.0 / intervals                   # generic 'bpm' = events/min
        amps = x_hp[pk[:-1]]
        peak_times_s = t_ax[pk[:-1]]
        freq_cpm = float(60.0 / np.mean(intervals)) if intervals.size else float('nan')
        interval_s_mean = float(np.mean(intervals))
    else:
        intervals = np.array([]); rates_bpm = np.array([])
        amps = np.array([]); peak_times_s = np.array([])
        freq_cpm = float('nan'); interval_s_mean = float('nan')
    return dict(n=n, fps=fps, t_s=t_ax, signal_hp=x_hp, envelope=env,
                peaks=pk, intervals=intervals, rates_bpm=rates_bpm,
                amps=amps, peak_times_s=peak_times_s,
                freq_cpm=freq_cpm, interval_s_mean=interval_s_mean,
                hp_window_s=float(hp_window_s), prom_mult=float(prom_mult),
                dist_s=float(dist_s), savgol_w=int(w))


def _velocity_from_kymograph(kymo, fps, px_um):
    """Per-point peak times -> linear fit position(µm) vs time(s).
    Returns (velocity_um_s, slope_residual_um, direction_sign). The kymograph is
    (N_pts, T) with arc-length increasing along axis 0. Velocity sign: +
    distal-direction propagation (peak appears later at larger arc-length)."""
    from scipy.signal import find_peaks
    N, T = kymo.shape
    if N < 3 or T < 5:
        return float('nan'), float('nan'), 0
    # For each point row, take the strongest peak time (in seconds)
    peak_t_s = np.full(N, np.nan)
    for i in range(N):
        row = kymo[i]
        if not np.isfinite(row).any():
            continue
        rrow = row - np.nanmean(row)
        rrow = np.nan_to_num(rrow, nan=0.0)
        pk, _ = find_peaks(rrow, prominence=np.nanstd(rrow) * 0.4 + 1e-9)
        if len(pk):
            peak_t_s[i] = pk[int(np.argmax(rrow[pk]))] / fps
    valid = np.isfinite(peak_t_s)
    if valid.sum() < 3:
        return float('nan'), float('nan'), 0
    pos_um = np.arange(N) * (kymo.shape[0] and (1.0))   # placeholder; caller sets via px_um
    pos_um = np.linspace(0.0, (N - 1), N)               # in "sample index"; caller passes arclen
    # We don't know arclen here directly; use point index * mean_spacing_um instead via px_um.
    # Caller should pass kymo computed at fixed arc spacing → here we assume arclen is uniform
    # and pass px_um as the spacing PER SAMPLE step (i.e., total_len_um / (N-1)).
    pos_um = np.arange(N) * float(px_um)
    coeffs, residuals, *_ = np.polyfit(pos_um[valid], peak_t_s[valid], 1, full=True)
    slope_s_per_um = float(coeffs[0])                   # s/µm
    if abs(slope_s_per_um) < 1e-12:
        return float('nan'), float('nan'), 0
    v_um_s = 1.0 / slope_s_per_um
    direction = int(np.sign(v_um_s))
    resid = float(residuals[0]) if len(residuals) else float('nan')
    return float(v_um_s), resid, direction


def _velocity_from_xcorr(trace_prox, trace_dist, sep_um, fps):
    """Lag (s) of distal vs proximal trace via normalized cross-correlation.
    velocity_um_s = sep_um / lag_s. Direction: sign(lag) = anterograde if lag > 0
    (distal peaks after proximal). Returns (velocity_um_s, lag_s, direction)."""
    a = np.asarray(trace_prox, float); b = np.asarray(trace_dist, float)
    if a.size < 5 or b.size < 5 or a.size != b.size:
        return float('nan'), float('nan'), 0
    a = a - a.mean(); b = b - b.mean()
    norm = (np.linalg.norm(a) * np.linalg.norm(b)) + 1e-12
    corr = np.correlate(b, a, mode='full') / norm
    lag = int(np.argmax(corr)) - (len(a) - 1)
    lag_s = lag / float(fps)
    if abs(lag_s) < 1.0 / fps:                          # sub-sample / undefined
        return float('inf'), lag_s, 0
    v = float(sep_um) / lag_s
    return float(v), float(lag_s), int(np.sign(lag_s))


def _time_color_projection(proj_THW):
    """HSV-coded projection: hue = argmax-over-time (∈[0,1]), value = max intensity,
    saturation = 1. Returns (H, W, 3) RGB float in [0,1]."""
    from matplotlib.colors import hsv_to_rgb
    if proj_THW.ndim != 3:
        return None
    T = proj_THW.shape[0]
    if T < 2:
        return None
    idx = np.argmax(proj_THW, axis=0).astype(np.float32) / max(T - 1, 1)
    val = np.max(proj_THW, axis=0)
    val = (val - val.min()) / (val.max() - val.min() + 1e-9)
    hsv = np.stack([idx, np.ones_like(val), val], axis=-1)
    return hsv_to_rgb(hsv)


def _fps_from_name(path, default=None):
    """Best-effort parse of an acquisition rate token like '_100hz' / '20Hz'
    from a filename. Returns float Hz, or `default` if no token is found."""
    import os, re
    m = re.search(r'(\d+(?:\.\d+)?)\s*hz', os.path.basename(str(path)), re.IGNORECASE)
    return float(m.group(1)) if m else default


def _smooth_velocity_for_display(s_um, v_raw, smooth_um=25.0,
                                 dense_step_um=1.0, method='pchip'):
    """DISPLAY ONLY: build a smooth, dense velocity-vs-arclength curve for
    rendering. Does NOT affect exported quantitative velocity metrics — the
    caller keeps `v_raw` untouched and uses `v_display` only for coloring.

    Parameters
    ----------
    s_um   : (M,) arclength positions (µm), possibly sparse/unsorted.
    v_raw  : (M,) raw velocity values (µm/s) at those positions.
    smooth_um : Gaussian smoothing length along arclength (µm). 0 disables
                smoothing (≈ the un-smoothed interpolated curve).
    dense_step_um : arclength step (µm) of the dense render grid.
    method : 'pchip' (monotonic shape-preserving) else linear.

    Returns (s_dense, v_interp, v_display, meta). If input is degenerate,
    returns (None, None, None, meta) with meta['ok'] = False.
    """
    import numpy as _np
    s = _np.asarray(s_um, float); v = _np.asarray(v_raw, float)
    meta = dict(ok=False, method=str(method), smooth_um=float(smooth_um),
                dense_step_um=float(dense_step_um), n_raw=int(s.size),
                clipped=False, note="display smoothing only; quantitative "
                                    "metrics unchanged")
    fin = _np.isfinite(s) & _np.isfinite(v)
    s = s[fin]; v = v[fin]
    if s.size < 2:
        return None, None, None, meta
    order = _np.argsort(s)
    s = s[order]; v = v[order]
    # de-duplicate identical arclengths (PCHIP requires strictly increasing x)
    keep = _np.concatenate(([True], _np.diff(s) > 1e-9))
    s = s[keep]; v = v[keep]
    if s.size < 2:
        return None, None, None, meta
    step = max(float(dense_step_um), 1e-6)
    s_dense = _np.arange(float(s[0]), float(s[-1]) + step, step)
    if s_dense.size < 2:
        s_dense = _np.linspace(float(s[0]), float(s[-1]), 2)
    # shape-preserving interpolation (monotone), fallback to linear
    v_interp = None
    if str(method) == 'pchip':
        try:
            from scipy.interpolate import PchipInterpolator as _Pchip
            v_interp = _Pchip(s, v)(s_dense)
        except Exception:
            v_interp = None
    if v_interp is None:
        v_interp = _np.interp(s_dense, s, v)
    v_interp = _np.asarray(v_interp, float)
    # DISPLAY-ONLY Gaussian smoothing along arclength
    v_display = v_interp.copy()
    if float(smooth_um) > 0 and s_dense.size >= 3:
        try:
            from scipy.ndimage import gaussian_filter1d as _gf1
            sigma = float(smooth_um) / step
            v_display = _gf1(v_interp, sigma=max(sigma, 1e-6), mode='nearest')
            meta['sigma_samples'] = float(sigma)
        except Exception:
            v_display = v_interp.copy()
    # anti-overshoot clip to the raw finite range (or robust P1/P99 if the
    # raw has outliers). DISPLAY ONLY.
    v_fin = v[_np.isfinite(v)]
    if v_fin.size:
        lo, hi = float(v_fin.min()), float(v_fin.max())
        p1, p99 = _np.percentile(v_fin, [1, 99])
        if (hi - lo) > 4.0 * (p99 - p1 + 1e-9):     # heavy-tailed → robustify
            lo, hi = float(p1), float(p99); meta['clipped'] = True
        v_display = _np.clip(v_display, lo, hi)
        meta['clip_lo'] = lo; meta['clip_hi'] = hi
    meta['ok'] = True; meta['n_dense'] = int(s_dense.size)
    return s_dense, v_interp, v_display, meta


def _extend_v_of_s(s_grid, v_grid, s_lo, s_hi, mode='taper', taper_um=150.0,
                   floor=0.0, step_um=0.5, hard_max=None):
    """DISPLAY: extend a MEASURED v(s) curve across the FULL vessel arclength.

    The measured span [s_grid[0], s_grid[-1]] usually covers only the picked flow line.
    Outside it, the old code painted a single constant -> a flat color and an abrupt edge.
    Here we continue the curve with C1 continuity (value AND slope match at the edge) and
    report a confidence that decays with extrapolation distance, so downstream rendering can
    desaturate the extrapolated region instead of pretending it was measured.

    mode : 'taper'  v_edge + k*d*exp(-(d/taper)^2)  -> slope-continuous, relaxes to v_edge
           'linear' v_edge + k*d                    -> unbounded; clipped to [floor,hard_max]
           'hold'   v_edge                          -> continuous value, zero slope
           'none'   NaN                             -> caller renders neutral gray (honest)

    Returns (s_dense, v_dense, conf_dense); conf == 1 inside the measured span.
    """
    s_grid = np.asarray(s_grid, float); v_grid = np.asarray(v_grid, float)
    if s_grid.size == 0:
        return None, None, None
    s_lo = float(min(s_lo, s_grid[0])); s_hi = float(max(s_hi, s_grid[-1]))
    n = max(2, int(np.ceil((s_hi - s_lo) / max(1e-6, float(step_um)))) + 1)
    sd = np.linspace(s_lo, s_hi, n)
    if s_grid.size == 1:
        vd = np.full(n, float(v_grid[0])); cd = np.full(n, 0.5); cd[:] = 0.5
        return sd, vd, cd

    # inside: shape-preserving PCHIP (no overshoot); fall back to linear interp
    try:
        from scipy.interpolate import PchipInterpolator as _P
        f_in = _P(s_grid, v_grid, extrapolate=False)
        v_in = f_in(sd)
    except Exception:
        v_in = np.interp(sd, s_grid, v_grid, left=np.nan, right=np.nan)

    def _edge_slope(s, v, at_start):
        k_n = max(3, int(0.2 * s.size))
        ss = s[:k_n] if at_start else s[-k_n:]
        vv = v[:k_n] if at_start else v[-k_n:]
        if ss.size < 2 or np.ptp(ss) < 1e-9: return 0.0
        return float(np.polyfit(ss, vv, 1)[0])

    k0 = _edge_slope(s_grid, v_grid, True)
    k1 = _edge_slope(s_grid, v_grid, False)
    v0, v1 = float(v_grid[0]), float(v_grid[-1])
    tau = max(1e-6, float(taper_um))

    vd = v_in.copy(); cd = np.ones(n)
    lo_m = sd < s_grid[0]; hi_m = sd > s_grid[-1]
    for m_, s_edge, v_edge, k in ((lo_m, s_grid[0], v0, k0),
                                  (hi_m, s_grid[-1], v1, k1)):
        if not m_.any(): continue
        d = sd[m_] - s_edge                     # negative on the low side
        if mode == 'none':
            vd[m_] = np.nan; cd[m_] = 0.0
        elif mode == 'hold':
            vd[m_] = v_edge
            cd[m_] = np.exp(-(np.abs(d) / tau) ** 2)
        elif mode == 'linear':
            vd[m_] = v_edge + k * d
            cd[m_] = np.exp(-(np.abs(d) / tau) ** 2)
        else:                                    # 'taper' (default)
            vd[m_] = v_edge + k * d * np.exp(-(d / tau) ** 2)
            cd[m_] = np.exp(-(np.abs(d) / tau) ** 2)
    ok = np.isfinite(vd)
    if floor is not None: vd[ok] = np.maximum(vd[ok], float(floor))
    if hard_max is not None: vd[ok] = np.minimum(vd[ok], float(hard_max))
    cd = np.clip(cd, 0.15, 1.0)
    cd[~np.isfinite(vd)] = 0.0
    return sd, vd, cd


# ── Robust line-fit + FWHM kernels (single implementation, shared by the recon
#    analyzer's peak-trajectory fit AND the Pulse Flow bolus-kinetics pipeline) ──
def _ransac_line(t, s, thr=0.0, min_samples=3, max_trials=200, seed=0):
    """Numpy-only RANSAC for y = m*x + b. thr<=0 -> auto (MAD of OLS residuals).
    Returns (slope, intercept, inlier_mask)."""
    t = np.asarray(t, float); s = np.asarray(s, float)
    n = int(t.size)
    if n < 2:
        return float('nan'), float('nan'), np.zeros(n, dtype=bool)
    if thr is None or thr <= 0:
        try:
            m0, b0 = np.polyfit(t, s, 1); r0 = s - (m0 * t + b0)
            mad = float(np.median(np.abs(r0 - np.median(r0))))
            thr = max(1e-9, 2.5 * 1.4826 * (mad if mad > 0 else float(np.std(r0)) + 1e-9))
        except Exception:
            thr = 1.0
    rng = np.random.default_rng(seed)
    best_inliers = None; best_slope = 0.0; best_int = 0.0
    k_sample = max(2, min(int(min_samples), n))
    for _ in range(int(max_trials)):
        idx = rng.choice(n, size=k_sample, replace=False)
        try:
            slope_i, int_i = np.polyfit(t[idx], s[idx], 1)
        except Exception:
            continue
        resid = np.abs(s - (slope_i * t + int_i))
        inlier = resid <= thr
        if best_inliers is None or int(inlier.sum()) > int(best_inliers.sum()):
            best_inliers = inlier
            best_slope, best_int = float(slope_i), float(int_i)
    if best_inliers is None or int(best_inliers.sum()) < 2:
        slope, intercept = np.polyfit(t, s, 1)
        resid = np.abs(s - (slope * t + intercept))
        return float(slope), float(intercept), (resid <= thr)
    try:
        slope, intercept = np.polyfit(t[best_inliers], s[best_inliers], 1)
        best_slope, best_int = float(slope), float(intercept)
    except Exception:
        pass
    return best_slope, best_int, best_inliers


def _robust_line_fit(t, s, method='ransac', thr=0.0, min_samples=3, max_trials=200):
    """Robust slope of s(t). method: ransac|theilsen|huber|ols.
    Returns dict(slope, intercept, inliers, method, thr, r2, se_slope, n).
    r2 / se_slope are computed on the INLIERS. sklearn is optional."""
    t = np.asarray(t, float); s = np.asarray(s, float)
    n = int(t.size)
    if n < 2:
        return dict(slope=float('nan'), intercept=float('nan'),
                    inliers=np.zeros(n, bool), method='none', thr=0.0,
                    r2=float('nan'), se_slope=float('nan'), n=n)
    slope_ols, int_ols = np.polyfit(t, s, 1)
    resid_ols = s - (slope_ols * t + int_ols)
    mad = float(np.median(np.abs(resid_ols)))
    if thr is None or thr <= 0:
        thr = max(1.0, 2.5 * 1.4826 * (mad if mad > 0 else float(np.std(resid_ols))))
    slope = intercept = None; mask = None; method_used = 'ols'
    if method == 'ransac':
        try:
            from sklearn.linear_model import RANSACRegressor, LinearRegression
            r = RANSACRegressor(estimator=LinearRegression(), residual_threshold=thr,
                                min_samples=max(2, int(min_samples)),
                                max_trials=int(max_trials), random_state=0)
            r.fit(t.reshape(-1, 1), s)
            slope = float(r.estimator_.coef_[0]); intercept = float(r.estimator_.intercept_)
            mask = r.inlier_mask_.astype(bool); method_used = 'ransac(sklearn)'
        except Exception:
            slope, intercept, mask = _ransac_line(t, s, thr, min_samples=int(min_samples),
                                                  max_trials=int(max_trials))
            method_used = 'ransac(pure)'
    elif method == 'theilsen':
        try:
            from sklearn.linear_model import TheilSenRegressor
            r = TheilSenRegressor(random_state=0); r.fit(t.reshape(-1, 1), s)
            slope = float(r.coef_[0]); intercept = float(r.intercept_)
            resid = s - (slope * t + intercept); mad2 = float(np.median(np.abs(resid)))
            mask = np.abs(resid) <= max(thr, 2.5 * 1.4826 * mad2); method_used = 'theilsen'
        except Exception:
            slope = None
    elif method == 'huber':
        try:
            from sklearn.linear_model import HuberRegressor
            r = HuberRegressor(); r.fit(t.reshape(-1, 1), s)
            slope = float(r.coef_[0]); intercept = float(r.intercept_)
            if hasattr(r, 'outliers_'):
                mask = ~r.outliers_.astype(bool)
            else:
                resid = s - (slope * t + intercept); mad2 = float(np.median(np.abs(resid)))
                mask = np.abs(resid) <= max(thr, 2.5 * 1.4826 * mad2)
            method_used = 'huber'
        except Exception:
            slope = None
    if slope is None:
        slope, intercept = float(slope_ols), float(int_ols)
        mask = np.abs(resid_ols) <= max(thr, 2.5 * 1.4826 * mad); method_used = 'ols'
    mask = np.asarray(mask, bool)
    ni = int(mask.sum())
    if ni >= 2:
        ti = t[mask]; si = s[mask]; pred = slope * ti + intercept
        ss_res = float(np.sum((si - pred) ** 2))
        ss_tot = float(np.sum((si - si.mean()) ** 2)) + 1e-12
        r2 = 1.0 - ss_res / ss_tot
        sxx = float(np.sum((ti - ti.mean()) ** 2)) + 1e-12
        se_slope = float(np.sqrt(ss_res / max(ni - 2, 1)) / np.sqrt(sxx))
    else:
        r2 = float('nan'); se_slope = float('nan')
    return dict(slope=float(slope), intercept=float(intercept), inliers=mask,
                method=method_used, thr=float(thr), r2=r2, se_slope=se_slope, n=n)


def _fwhm_profile(b, arclen_um, pk_i):
    """Linear-interpolated FWHM (µm) of an arclength profile around index pk_i.
    NaN if the profile is too flat."""
    b = np.asarray(b, float); s = np.asarray(arclen_um, float)
    if b.size < 3 or pk_i < 0 or pk_i >= b.size:
        return float('nan')
    base = float(np.nanmin(b)); peak = float(b[pk_i])
    if peak - base < 1e-12:
        return float('nan')
    half = base + 0.5 * (peak - base)
    li = pk_i
    while li > 0 and b[li - 1] >= half:
        li -= 1
    if li == 0:
        left_s = s[0]
    else:
        y0, y1 = b[li - 1], b[li]
        tt = (half - y0) / (y1 - y0 + 1e-12)
        left_s = s[li - 1] + tt * (s[li] - s[li - 1])
    ri = pk_i
    while ri < b.size - 1 and b[ri + 1] >= half:
        ri += 1
    if ri == b.size - 1:
        right_s = s[-1]
    else:
        y0, y1 = b[ri], b[ri + 1]
        tt = (half - y0) / (y1 - y0 + 1e-12)
        right_s = s[ri] + tt * (s[ri + 1] - s[ri])
    w = float(right_s - left_s)
    return w if w > 0 else float('nan')


def file_index(boundaries, t):
    """Index of the file containing frame t. `boundaries` = [0, n0, n0+n1, ..., T]."""
    import bisect
    return max(0, bisect.bisect_right(list(boundaries), int(t)) - 1)


def same_file(boundaries, *ts):
    """True iff every frame index in `ts` lies inside the same file."""
    f = file_index(boundaries, ts[0])
    return all(file_index(boundaries, t) == f for t in ts[1:])


# ── Source-file → ROOT map (built-in 10-file acquisition example) ────────────
SOURCE_FILES_DEFAULT = [
    ("record_30012026_182138_a",  1834), ("record_30012026_182311_b",  1035),
    ("record_30012026_182403_c",  1905), ("record_30012026_182539_d",  1650),
    ("record_30012026_182703_e",  3612), ("record_30012026_183004_f0", 4378),
    ("record_30012026_183344_g",  2443), ("record_30012026_183547_h",  3872),
    ("record_30012026_183901_i0", 4378), ("record_30012026_184241_j",  3872),
]
PULSES_DEFAULT = {  # per-file, 1-based inclusive
    "a":[(550,750)], "b":[(956,1035)], "c":[(780,860),(1750,1830)], "d":[(1550,1650)],
    "e":[(3530,3612)], "f0":[(2050,2350)], "g":[(2300,2443)], "h":[(3650,3872)],
    "i0":[(900,1000)], "j":[(3450,3650)],
}

def build_source_root_map(files):
    """files = [(name, nframes), ...] in acquisition order. Returns
    dict(boundaries=[0,n0,n0+n1,...,T], T, offsets={tag:offset}, order=[tags]).
    tag = the label after the last '_' (e.g. '..._f0' -> 'f0')."""
    off = {}; b = [0]; c = 0; order = []
    for name, n in files:
        tag = name.split('_')[-1]; order.append(tag); off[tag] = c; c += int(n); b.append(c)
    return dict(boundaries=b, T=c, offsets=off, order=order)


def pulses_to_root(pulses, srcmap, fps, one_based=True):
    """Map per-file 1-based-inclusive windows to ROOT. Returns a list of dicts sorted by
    t_center_s.  r0 = offset[tag] + (a - (1 if one_based else 0))."""
    out = []
    for tag, wins in pulses.items():
        base = srcmap['offsets'].get(tag)
        if base is None: continue
        for (a, bnd) in wins:
            r0 = base + (a - (1 if one_based else 0))
            r1 = base + (bnd - (1 if one_based else 0)) + (1 if one_based else 0)
            out.append(dict(tag=tag, local_a=a, local_b=bnd, root_t0=r0, root_t1=r1,
                            root_file=file_index(srcmap['boundaries'], r0),
                            t0_s=r0 / fps, t1_s=(r1 - 1) / fps,
                            t_center_s=((r0 + r1 - 1) / 2) / fps, dur=(bnd - a + 1)))
    out.sort(key=lambda d: d['t_center_s'])
    return out


import re as _re
def clip_name_to_root(source_tiff, srcmap):
    """Recover a truncated clip's ROOT start frame from its filename.
    Expects '<tag>_..._truncated_<lo>_<hi>_...' (tag = file label, e.g. 'a', 'f0'; the clip
    JSON is often saved as f_/i_ but source_tiff keeps the full f0/i0 name). `srcmap` from
    build_source_root_map (offsets keyed by tag). Returns dict(tag, lo, hi, offset, clip_root0)
    or None.  clip_root0 = offset[tag] + (lo-1)   (lo is 1-based)."""
    base = os.path.splitext(os.path.basename(source_tiff or ''))[0]
    offs = (srcmap or {}).get('offsets', {})
    m = _re.match(r'([A-Za-z0-9]+?)_.*?truncated_(\d+)_(\d+)', base)
    if not m:
        m2 = _re.match(r'([A-Za-z0-9]+?)_', base)
        tag = m2.group(1) if m2 else None
        if tag not in offs: return None
        return dict(tag=tag, lo=1, hi=None, offset=int(offs[tag]), clip_root0=int(offs[tag]))
    tag, lo, hi = m.group(1), int(m.group(2)), int(m.group(3))
    if tag not in offs:                                # f0/i0 vs f/i: accept both spellings
        alt = tag + '0'
        tag = alt if alt in offs else (tag[:-1] if (tag[-1:] == '0' and tag[:-1] in offs) else tag)
    off = offs.get(tag)
    if off is None: return None
    return dict(tag=tag, lo=lo, hi=hi, offset=int(off), clip_root0=int(off) + (lo - 1))


# ── Frame-provenance contract ────────────────────────────────────────────────
# Every stack carries a `frame_map` (local index -> ROOT frame index). Array indexing
# always uses LOCAL indices; all timing/reporting uses ROOT indices (root_time = frame_map[i]/fps).
def make_root_map(T):
    """Identity map for a root stack: local i -> root i."""
    return np.arange(int(T), dtype=np.int64)


def compose_map(parent_map, local_idx):
    """New frame_map after extracting `local_idx` from a stack whose map is `parent_map`.
    Composition is what makes repeated extractions work: the map always points at the ROOT."""
    return np.asarray(parent_map, np.int64)[np.asarray(local_idx, np.int64)]


def invert_map(frame_map, root_T):
    """root index -> local index, or -1 where the root frame is absent. int32[root_T]."""
    fm = np.asarray(frame_map, np.int64)
    inv = np.full(int(root_T), -1, np.int32)
    ok = (fm >= 0) & (fm < int(root_T))
    inv[fm[ok]] = np.arange(fm.size, dtype=np.int32)[ok]
    return inv


def runs_from_root(root_idx):
    """Contiguous runs of a sorted root-index array -> [(r0, r1)] half-open (r1 exclusive)."""
    r = np.asarray(root_idx, np.int64)
    if r.size == 0:
        return []
    brk = np.where(np.diff(r) != 1)[0]
    starts = np.concatenate([[0], brk + 1])
    ends = np.concatenate([brk, [r.size - 1]])
    return [(int(r[s]), int(r[e]) + 1) for s, e in zip(starts, ends)]


def _huber_affine(x, y, iters=5, c=1.345):
    """Robust y ≈ a*x + b by IRLS (Huber). Returns (a, b, r2, n)."""
    x = np.asarray(x, float).ravel(); y = np.asarray(y, float).ravel()
    m = np.isfinite(x) & np.isfinite(y)
    x, y = x[m], y[m]
    if x.size < 8:
        return (1.0, 0.0, 0.0, int(x.size))
    w = np.ones_like(x)
    a = b = 0.0
    for _ in range(iters):
        W = w.sum(); mx = (w * x).sum() / W; my = (w * y).sum() / W
        sxx = (w * (x - mx) ** 2).sum(); sxy = (w * (x - mx) * (y - my)).sum()
        a = sxy / (sxx + 1e-12); b = my - a * mx
        r = y - (a * x + b)
        s = 1.4826 * np.median(np.abs(r - np.median(r))) + 1e-12
        u = np.abs(r) / (c * s); w = np.where(u <= 1.0, 1.0, 1.0 / np.maximum(u, 1e-9))
    r = y - (a * x + b)
    ss = np.sum((y - y.mean()) ** 2) + 1e-12
    return (float(a), float(b), float(1.0 - np.sum(r * r) / ss), int(x.size))


def _qq_affine(x_samp, y_samp, qlo=2.0, qhi=98.0, nq=25):
    """Distribution-based affine match (drift-insensitive): fit the quantiles of y against the
    quantiles of x. Returns (a, b)."""
    qs = np.linspace(qlo, qhi, nq)
    qx = np.percentile(np.asarray(x_samp, float), qs)
    qy = np.percentile(np.asarray(y_samp, float), qs)
    a, b, _, _ = _huber_affine(qx, qy)
    return float(a), float(b)


def _monotone_lut(x_src, x_ref, K=12, qlo=0.5, qhi=99.9):
    """Quantile map taking SOURCE intensities onto REFERENCE intensities.
    Returns (xk, yk) knots with xk strictly increasing. K=2 -> affine-like; K>=64 -> histogram
    matching. Apply with np.interp(frame, xk, yk)."""
    q = np.linspace(qlo, qhi, int(max(2, K)))
    xk = np.percentile(np.asarray(x_src, float), q)
    yk = np.percentile(np.asarray(x_ref, float), q)
    # enforce strict monotonicity (dedupe ties, then cumulative max)
    for i in range(1, xk.size):
        if xk[i] <= xk[i - 1]: xk[i] = xk[i - 1] + 1e-6
    yk = np.maximum.accumulate(yk)
    return xk.astype(np.float64), yk.astype(np.float64)


def _apply_lut(a, xk, yk):
    """Clamped monotone LUT. Values outside the knot range are held at the end knots."""
    return np.interp(np.asarray(a, np.float32), xk, yk,
                     left=float(yk[0]), right=float(yk[-1])).astype(np.float32)


def _lut_local_gain(xk, yk):
    """min/max of dy/dx over the knots — the local gain a nonlinear map applies.
    Report it: values far from 1 mean the map distorts intensity linearity."""
    g = np.diff(yk) / np.maximum(np.diff(xk), 1e-9)
    return float(np.nanmin(g)), float(np.nanmax(g))


def _extend_knots(xk, yk, xlo=0.0, xhi=1e7):
    """Add LINEAR-TAIL knots below xk[0] and above xk[-1] so a LUT built on quiet frames does not
    CLAMP (and thus flatten) bolus-bright pixels that exceed the quiet intensity range. The tails
    continue the end-segment slopes; monotonicity is preserved."""
    xk = np.asarray(xk, float); yk = np.asarray(yk, float)
    if xk.size < 2: return xk, yk
    xs = list(xk); ys = list(yk)
    if xk[0] > xlo:
        s0 = (yk[1] - yk[0]) / max(xk[1] - xk[0], 1e-9)
        xs = [xlo] + xs; ys = [yk[0] - s0 * (xk[0] - xlo)] + ys
    if xk[-1] < xhi:
        s1 = (yk[-1] - yk[-2]) / max(xk[-1] - xk[-2], 1e-9)
        xs = xs + [xhi]; ys = ys + [yk[-1] + s1 * (xhi - xk[-1])]
    xk2 = np.asarray(xs, float); yk2 = np.asarray(ys, float)
    for i in range(1, xk2.size):
        if xk2[i] <= xk2[i - 1]: xk2[i] = xk2[i - 1] + 1e-6
    yk2 = np.maximum.accumulate(yk2)
    return xk2, yk2


def parse_frame_ranges(text, half_open=True):
    """Parse pasted frame ranges, one per line. Accepts `a-b`, `a-b` (en/em dash), `a:b`, `a..b`,
    `a b`, `a,b`. Blank lines are ignored; anything after `#` is kept as the row's note.
    Returns [(t0, t1, note)] with t1 EXCLUSIVE. half_open=True: `2783-3293` -> 2783..3292 (510
    frames); half_open=False: -> 2783..3293 (511 frames). Raises ValueError(line#, text)."""
    import re
    rows = []
    for ln, raw in enumerate(str(text).splitlines(), 1):
        line = raw
        note = ''
        if '#' in line:
            i = line.index('#'); note = line[i + 1:].strip(); line = line[:i]
        line = line.strip()
        if not line:
            continue
        s = line.replace('–', '-').replace('—', '-').replace('..', '-')
        s = s.replace(':', '-').replace(',', '-')
        parts = [p for p in re.split(r'[-\s]+', s.strip()) if p != '']
        if len(parts) != 2:
            raise ValueError(f"line {ln}: expected 'start-end', got {raw!r}")
        try:
            a = int(round(float(parts[0]))); b = int(round(float(parts[1])))
        except Exception:
            raise ValueError(f"line {ln}: non-numeric range {raw!r}")
        t1 = b if half_open else b + 1
        rows.append((a, t1, note))
    return rows


def validate_frame_ranges(rows, T, boundaries, guard=0, min_dur=1, max_n=10):
    """Validate parsed rows (each (t0, t1, note)) against a stack of T frames. Returns a list of
    dicts (t0, t1, n, file, note, flags). Nothing is modified; the caller decides Clamp/Drop/Keep.
    duration_outlier: robust z = |n - median(n)| / (1.4826 * max(MAD(n), 1)) > 3."""
    import numpy as _np
    bounds = list(boundaries) if boundaries else [0, T]
    ns = _np.array([max(0, int(t1) - int(t0)) for (t0, t1, _n) in rows], float)
    med = float(_np.median(ns)) if ns.size else 0.0
    mad = float(_np.median(_np.abs(ns - med))) if ns.size else 0.0
    denom = 1.4826 * max(mad, 1.0)
    interior = [int(b) for b in bounds[1:-1]]
    out = []
    for i, (t0, t1, note) in enumerate(rows):
        t0 = int(t0); t1 = int(t1); n = t1 - t0; flags = []
        if t0 < 0 or t1 < 0:
            flags.append('negative')
        if t1 > T or t0 >= T:
            flags.append('out_of_range')
        if n < int(min_dur):
            flags.append('too_short')
        fi0 = file_index(bounds, max(0, min(t0, T - 1)))
        fi1 = file_index(bounds, max(0, min(t1 - 1, T - 1)))
        if fi0 != fi1:
            flags.append('crosses_boundary')
        if guard and interior:
            for b in interior:
                if t0 < b + guard and t1 > b - guard:
                    flags.append('in_guard'); break
        for j in range(i):
            pt0, pt1, _ = rows[j]
            if not (t1 <= pt0 or t0 >= pt1):
                flags.append('overlap'); break
        z = abs(n - med) / denom if denom > 0 else 0.0
        if z > 3.0:
            flags.append('duration_outlier')
        if i >= int(max_n):
            flags.append('over_max')
        out.append(dict(t0=t0, t1=t1, n=n, file=fi0, note=note, z=float(z), flags=flags))
    return out


def resolve_frame_ranges(rows, T, boundaries, guard=0, min_dur=1, policy='clip'):
    """Turn parsed rows (each (t0, t1, note)) into usable, single-file segments.

    policy='clip' (default): a range crossing an interior boundary is TRUNCATED at that boundary
      (t1 = min(t1, boundaries[f+1] - guard)); the start is pushed to max(t0, boundaries[f] + guard)
      when f > 0; out-of-range ends are clamped to T - guard_end (guard_end = guard for the last file).
    policy='split': the range is split into one guard-trimmed segment per file it touches.
    policy='drop' : a crossing/invalid row is dropped.
    policy='keep' : the row is kept and marked excluded.

    Returns [dict(t0, t1, n, file, note, orig=(t0,t1), actions=[...], flags=[...], include)].
    `actions` records every change. A resolved row shorter than min_dur is dropped
    ('drop_too_short'). Durations are re-checked for 'duration_outlier' AFTER resolution."""
    import numpy as _np
    bounds = list(boundaries) if boundaries else [0, T]
    nf = len(bounds) - 1

    def _trim_one(t0, t1, fi, note, orig):
        """Trim a (t0,t1) known to live mostly in file fi to that file's guarded interior."""
        actions = []
        f0, f1 = bounds[fi], bounds[fi + 1]
        lo = f0 + (guard if fi > 0 else 0)
        hi = f1 - (guard if fi < nf - 1 else guard)      # guard_end = guard for the last file too
        nt0 = max(int(t0), lo); nt1 = min(int(t1), hi)
        if nt0 != int(t0):
            actions.append('trim_guard')
        if int(t1) > f1:
            actions.append('clip_boundary')
        elif nt1 != int(t1):
            actions.append('clip_end' if fi == nf - 1 else 'clip_boundary')
        return nt0, nt1, actions

    resolved = []
    for (rt0, rt1, note) in rows:
        rt0 = int(rt0); rt1 = int(rt1); orig = (rt0, rt1)
        a0 = max(0, min(rt0, T)); a1 = max(0, min(rt1, T))
        fi0 = file_index(bounds, max(0, min(a0, T - 1)))
        fi1 = file_index(bounds, max(0, min(a1 - 1, T - 1)))
        pieces = []                                       # list of (t0,t1,fi,actions)
        if policy == 'drop' and (fi0 != fi1 or rt1 > T or rt0 < 0):
            resolved.append(dict(t0=a0, t1=a1, n=max(0, a1 - a0), file=fi0, note=note,
                                 orig=orig, actions=['drop'], flags=['dropped'], include=False))
            continue
        if policy == 'keep':
            nt0, nt1, act = _trim_one(a0, min(a1, bounds[fi0 + 1]), fi0, note, orig)
            resolved.append(dict(t0=nt0, t1=nt1, n=max(0, nt1 - nt0), file=fi0, note=note,
                                 orig=orig, actions=(act or []) + ['keep_excluded'],
                                 flags=['excluded'], include=False))
            continue
        if policy == 'split':
            for fi in range(fi0, fi1 + 1):
                seg0 = max(a0, bounds[fi]); seg1 = min(a1, bounds[fi + 1])
                nt0, nt1, act = _trim_one(seg0, seg1, fi, note, orig)
                if fi0 != fi1:
                    act = list(act) + ['split']
                pieces.append((nt0, nt1, fi, act))
        else:                                             # 'clip'
            nt0, nt1, act = _trim_one(a0, min(a1, bounds[fi0 + 1]), fi0, note, orig)
            if a1 > bounds[fi0 + 1] and 'clip_boundary' not in act:
                act = list(act) + ['clip_boundary']
            pieces.append((nt0, nt1, fi0, act))
        for (nt0, nt1, fi, act) in pieces:
            if nt1 - nt0 < int(min_dur):
                resolved.append(dict(t0=nt0, t1=nt1, n=max(0, nt1 - nt0), file=fi, note=note,
                                     orig=orig, actions=list(act) + ['drop_too_short'],
                                     flags=['dropped'], include=False))
            else:
                resolved.append(dict(t0=nt0, t1=nt1, n=nt1 - nt0, file=fi, note=note,
                                     orig=orig, actions=list(act), flags=[], include=True))
    # re-check duration outliers AFTER resolution (only over kept rows)
    kept = [r for r in resolved if r['include']]
    ns = _np.array([r['n'] for r in kept], float)
    if ns.size:
        med = float(_np.median(ns)); mad = float(_np.median(_np.abs(ns - med)))
        denom = 1.4826 * max(mad, 1.0)
        for r in kept:
            z = abs(r['n'] - med) / denom if denom > 0 else 0.0
            r['z'] = float(z)
            if z > 3.0:
                r['flags'] = list(r['flags']) + ['duration_outlier']
    return resolved


def _save_fig_dialog(fig, parent=None, default_stem="figure"):
    """Open save dialog (PDF default; SVG / PNG @ 300 dpi). vector preferred."""
    p = filedialog.asksaveasfilename(
        parent=parent, title="Save figure",
        initialfile=default_stem, defaultextension=".pdf",
        filetypes=[("PDF", "*.pdf"), ("SVG", "*.svg"), ("PNG", "*.png")])
    if not p:
        return None
    fig.savefig(p, dpi=300, bbox_inches='tight',
                facecolor=fig.get_facecolor())
    return p


def _save_data_dialog(parent=None, default_stem="data", arrays=None,
                      tidy_csv=None, metrics_csv=None):
    """Saves both <stem>.npz (arrays) and (optional) tidy/metrics CSVs."""
    import csv as _csv
    p = filedialog.asksaveasfilename(
        parent=parent, title="Save data bundle",
        initialfile=default_stem, defaultextension=".npz",
        filetypes=[("NPZ + CSV", "*.npz"), ("All", "*.*")])
    if not p:
        return None
    stem, _ = os.path.splitext(p)
    if arrays:
        np.savez(stem + ".npz", **{k: np.asarray(v) for k, v in arrays.items()
                                    if v is not None})
    if tidy_csv:                                          # list[dict] with consistent keys
        keys = list(tidy_csv[0].keys()) if tidy_csv else []
        with open(stem + ".csv", "w", newline="") as f:
            w = _csv.DictWriter(f, keys); w.writeheader()
            for row in tidy_csv: w.writerow(row)
    if metrics_csv:
        keys = list(metrics_csv[0].keys()) if metrics_csv else []
        with open(stem + "_metrics.csv", "w", newline="") as f:
            w = _csv.DictWriter(f, keys); w.writeheader()
            for row in metrics_csv: w.writerow(row)
    return stem


# ════════════════════════════════════════════════════════════════════════════
# Nature-style plotting helpers (analyzer-scoped — context-managed so other
# tools' figures are not restyled). Colorblind-safe Okabe–Ito palette.
# Editable-text vector output (svg.fonttype='none', pdf.fonttype=42).
# ════════════════════════════════════════════════════════════════════════════
OKABE_ITO = ['#000000', '#E69F00', '#56B4E9', '#009E73',
             '#F0E442', '#0072B2', '#D55E00', '#CC79A7']

NATURE_RCPARAMS = {
    'font.family':       'sans-serif',
    'font.sans-serif':   ['Arial', 'Helvetica', 'DejaVu Sans'],
    'pdf.fonttype':      42,           # TrueType embed (editable text in Illustrator)
    'ps.fonttype':       42,
    'svg.fonttype':      'none',       # keep text as <text>, not outlined to <path>
    'axes.labelsize':    7,
    'xtick.labelsize':   6, 'ytick.labelsize': 6,
    'legend.fontsize':   6,
    'axes.linewidth':    0.75,
    'lines.linewidth':   1.0,
    'xtick.direction':  'out', 'ytick.direction': 'out',
    'xtick.major.size': 2.5,  'ytick.major.size': 2.5,
    'xtick.major.width': 0.75, 'ytick.major.width': 0.75,
    'axes.spines.top':  False, 'axes.spines.right': False,
    'axes.grid':        False,
    'savefig.dpi':       300,
    'savefig.bbox':     'tight',
    'savefig.pad_inches': 0.02,
}


class apply_nature_style:
    """Context manager that applies NATURE_RCPARAMS for the duration of the
    ``with`` block and restores the prior rcParams on exit. Use ONLY around
    analyzer-figure creation so other tools' styling is unaffected::

        with apply_nature_style():
            fig = Figure(figsize=nature_figsize_in('double', 3.0), dpi=300)
            ax = fig.add_subplot(111); ...
    """
    def __enter__(self):
        import matplotlib.pyplot as _plt
        self._old = dict(_plt.rcParams)
        _plt.rcParams.update(NATURE_RCPARAMS)
        return self
    def __exit__(self, *exc):
        import matplotlib.pyplot as _plt
        _plt.rcParams.update(self._old)
        return False


def nature_figsize_in(cols='double', height_in=None):
    """Return (w_in, h_in) sized to Nature column widths.
    cols ∈ {'single' 89 mm, '1.5' 120 mm, 'double' 183 mm}.
    height_in defaults to 0.55 × width (golden-ish landscape)."""
    w_mm = {'single': 89.0, '1.5': 120.0, 'double': 183.0}[cols]
    w_in = w_mm / 25.4
    return (w_in, float(height_in) if height_in is not None else w_in * 0.55)


def panel_letter(ax, letter, x=-0.12, y=1.05, fontsize=8):
    """Bold lowercase panel letter (a, b, c, ...) at the top-left of an axes."""
    ax.text(x, y, letter, transform=ax.transAxes,
            fontsize=fontsize, fontweight='bold', va='bottom', ha='right')


def despine_lr(*axes):
    """Hide top + right spines on each axes (no-op for image axes whose spines
    are already invisible)."""
    for ax in axes:
        for s in ('top', 'right'):
            ax.spines[s].set_visible(False)


def slim_colorbar(im, ax, label, n_ticks=4, fraction=0.025, pad=0.02):
    """Thin (~2.5% of axes) colorbar with ≤n_ticks ticks and a small unit label."""
    from matplotlib.ticker import MaxNLocator
    cb = ax.figure.colorbar(im, ax=ax, fraction=fraction, pad=pad)
    cb.set_label(label)
    cb.outline.set_linewidth(0.75)
    cb.locator = MaxNLocator(int(n_ticks))
    cb.update_ticks()
    cb.ax.tick_params(labelsize=6, length=2.0, width=0.6)
    return cb


# ════════════════════════════════════════════════════════════════════════════
# Motion-artifact helpers (translation-only rigid registration + gap-aware
# pulse metrics). Estimation runs on a CLAHE-enhanced copy for robustness;
# shifts are applied to the LINEAR measurement frames.
# ════════════════════════════════════════════════════════════════════════════
def _trapz(y, x=None, dx=1.0):
    """The old numpy trapezoidal alias was removed in NumPy 2.0 (renamed to
    numpy.trapezoid). Version-safe wrapper picking whichever exists."""
    f = getattr(np, "trapezoid", None) or getattr(np, "trapz", None)
    if f is None:
        from scipy.integrate import trapezoid as f
    return f(y, x=x, dx=dx) if x is not None else f(y, dx=dx)


def _clahe_u8(img01):
    """Convert a [0,1] float frame to a CLAHE-enhanced uint8 — for shift
    estimation only (NEVER for measurement)."""
    import cv2
    u8 = (np.clip(np.asarray(img01, np.float32), 0, 1) * 255).astype(np.uint8)
    cl = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
    return cl.apply(u8)


def estimate_motion(proj_THW, ref_idx=None, enhance_for_estimation=True,
                    roi_xyxy=None, upsample=10):
    """Per-frame rigid translation via phase_cross_correlation.

    Parameters
    ----------
    proj_THW : (T, H, W) float in [0,1].
    ref_idx  : None ⇒ robust temporal median frame; int ⇒ explicit reference;
               str 'median'|'first'|'last' for convenience.
    enhance_for_estimation : run CLAHE on each frame before correlation.
    roi_xyxy : optional (x0, y0, x1, y1) bbox in image coords to restrict
               cross-correlation to a window around the vessel.
    upsample : float, sub-pixel upsampling factor for phase_cross_correlation.

    Returns
    -------
    dict with keys:
        shifts  : (T, 2) float, (dy, dx) such that the frame should be shifted
                  by (-dy, -dx) to align onto the reference.
        quality : (T,) float in [0..1], the cross-correlation peak quality.
        ref_idx : int — the chosen reference frame index.
        ref_method : str — 'median' | 'index'
    """
    from skimage.registration import phase_cross_correlation
    proj = np.asarray(proj_THW, np.float32)
    T, H, W = proj.shape

    # Reference
    if ref_idx is None or (isinstance(ref_idx, str) and ref_idx == 'median'):
        ref = np.median(proj, axis=0)
        ref_idx_eff = -1; ref_method = 'median'
    elif isinstance(ref_idx, str):
        ri = {'first': 0, 'last': T - 1}.get(ref_idx, 0)
        ref = proj[ri]; ref_idx_eff = int(ri); ref_method = 'index'
    else:
        ri = max(0, min(int(ref_idx), T - 1))
        ref = proj[ri]; ref_idx_eff = int(ri); ref_method = 'index'

    # Optional ROI restriction
    if roi_xyxy is not None:
        x0, y0, x1, y1 = (int(v) for v in roi_xyxy)
        x0 = max(0, min(x0, W - 1)); x1 = max(x0 + 1, min(x1, W))
        y0 = max(0, min(y0, H - 1)); y1 = max(y0 + 1, min(y1, H))
        ref_e = ref[y0:y1, x0:x1]
        slicer = (slice(y0, y1), slice(x0, x1))
    else:
        ref_e = ref; slicer = (slice(None), slice(None))

    ref_in = _clahe_u8(ref_e).astype(np.float32) if enhance_for_estimation else ref_e

    shifts = np.zeros((T, 2), np.float32)
    quality = np.zeros(T, np.float32)
    for t in range(T):
        mov = proj[t][slicer]
        mov_in = _clahe_u8(mov).astype(np.float32) if enhance_for_estimation else mov
        try:
            sh, error, _ = phase_cross_correlation(
                ref_in, mov_in, upsample_factor=int(upsample),
                normalization=None)
            shifts[t] = sh                                # (dy, dx)
            # phase_cross_correlation `error` ∈ [0,1]; high error = bad. Convert
            # to a 0..1 "quality" (1 = perfect) by clamping 1-error.
            quality[t] = float(np.clip(1.0 - float(error), 0.0, 1.0))
        except Exception:
            shifts[t] = (0.0, 0.0); quality[t] = 0.0
    return dict(shifts=shifts, quality=quality,
                ref_idx=int(ref_idx_eff), ref_method=ref_method,
                roi_xyxy=tuple(roi_xyxy) if roi_xyxy else None)


def apply_shifts(proj_THW, shifts, spline_order=1, mode='nearest'):
    """Apply per-frame (dy, dx) translations from estimate_motion to align each
    frame to the reference. The shifts dict returned by phase_cross_correlation
    is the shift you APPLY DIRECTLY to the moving frame — i.e. if the frame is
    offset by (+5, +0) relative to the reference, phase_cross_correlation
    returns (-5, 0) and ``scipy.ndimage.shift(frame, (-5, 0))`` undoes the
    offset. Translation-only — NEVER affine/elastic."""
    from scipy.ndimage import shift as _shift
    proj = np.asarray(proj_THW, np.float32)
    out = np.empty_like(proj)
    for t in range(proj.shape[0]):
        dy, dx = float(shifts[t, 0]), float(shifts[t, 1])
        out[t] = _shift(proj[t], shift=(dy, dx), order=int(spline_order),
                        mode=mode, prefilter=(int(spline_order) > 1))
    return out


def auto_motion_mask(shifts, method='mad', k=3.0, pct=95.0,
                     quality=None, qmin=0.05):
    """Return a boolean (T,) valid-frame mask. True = KEEP, False = EXCLUDE.

    method='mad'        : exclude |displacement| > median + k×MAD
    method='percentile' : exclude top (100-pct)% of |displacement|
    method='manual'     : nothing auto-excluded (caller adds intervals)
    quality + qmin      : optional, ALSO exclude where quality < qmin
    """
    sh = np.asarray(shifts, float)
    mag = np.hypot(sh[:, 0], sh[:, 1])
    T = mag.size
    if method == 'mad':
        med = float(np.median(mag))
        mad = float(np.median(np.abs(mag - med)) + 1e-12)
        thr = med + float(k) * 1.4826 * mad
        valid = mag <= thr
    elif method == 'percentile':
        thr = float(np.percentile(mag, float(pct)))
        valid = mag <= thr
    else:
        valid = np.ones(T, bool)
    if quality is not None and qmin > 0:
        valid &= (np.asarray(quality, float) >= float(qmin))
    return valid


def contiguous_runs(valid_mask):
    """Return list of (start, end_inclusive) for each contiguous True run."""
    m = np.asarray(valid_mask, bool)
    if m.size == 0:
        return []
    edges = np.diff(np.concatenate([[False], m, [False]]).astype(int))
    starts = np.where(edges == 1)[0]
    ends   = np.where(edges == -1)[0] - 1
    return [(int(s), int(e)) for s, e in zip(starts, ends)]


def parse_intervals(spec, T):
    """Parse "120-160, 540-590" into a list of (lo, hi_inclusive) tuples,
    clamped to [0, T-1]. Single frames ("42") accepted too. Reuses the same
    syntax as layered_export.parse_frame_spec."""
    if spec is None:
        return []
    out = []
    s = str(spec).strip().replace('..', '-').replace('/', ':')
    if not s:
        return []
    import re as _re
    for token in _re.split(r'\s*,\s*', s):
        if not token:
            continue
        token = token.partition(':')[0]                 # drop any step suffix
        if '-' in token:
            try:
                a, b = token.split('-', 1); a, b = int(a), int(b)
            except ValueError:
                continue
            if a > b: a, b = b, a
            a = max(0, min(a, int(T) - 1)); b = max(0, min(b, int(T) - 1))
            out.append((a, b))
        else:
            try:
                v = int(token)
            except ValueError:
                continue
            v = max(0, min(v, int(T) - 1))
            out.append((v, v))
    # merge overlapping/adjacent
    out.sort()
    merged = []
    for lo, hi in out:
        if merged and lo <= merged[-1][1] + 1:
            merged[-1] = (merged[-1][0], max(merged[-1][1], hi))
        else:
            merged.append((lo, hi))
    return merged


def _pulse_metrics_gap_aware(trace, fps, valid_mask=None, hp_window_s=5.0,
                              prom_mult=0.5, dist_s=0.3, savgol_w=7,
                              min_run_s=2.0):
    """Run :func:`_pulse_metrics_from_trace` on each contiguous valid run and
    concatenate, so no inter-peak interval crosses an excluded gap.

    Returns a dict with the same keys as ``_pulse_metrics_from_trace``, plus:
        n_excluded (int)  — # of frames marked invalid
        n_runs (int)
        valid_duration_s (float)
        run_indices : list[(start, end_inclusive)]
    """
    x = np.asarray(trace, float)
    n = x.size; fps = float(fps)
    if valid_mask is None:
        valid_mask = np.ones(n, bool)
    valid_mask = np.asarray(valid_mask, bool)[:n]
    runs = contiguous_runs(valid_mask)
    min_len = max(1, int(round(min_run_s * fps)))
    runs = [r for r in runs if (r[1] - r[0] + 1) >= min_len]

    # accumulators
    all_peaks_global = []
    all_intervals   = []
    all_rates_bpm   = []
    all_amps        = []
    all_peak_times  = []
    # rebuilt signal/envelope (NaN outside valid runs) for plotting
    sig_hp = np.full(n, np.nan, float)
    env    = np.full(n, np.nan, float)

    for (s, e) in runs:
        seg = x[s:e + 1]
        m = _pulse_metrics_from_trace(np.nan_to_num(seg, nan=float(np.nanmean(seg))),
                                       fps, hp_window_s=hp_window_s,
                                       prom_mult=prom_mult, dist_s=dist_s,
                                       savgol_w=savgol_w)
        sig_hp[s:e + 1] = m['signal_hp']
        env[s:e + 1]    = m['envelope']
        if m['peaks'].size:
            pk = m['peaks'].astype(int) + s
            all_peaks_global.append(pk)
        if m['intervals'].size:
            all_intervals.append(m['intervals'])
            all_rates_bpm.append(m['rates_bpm'])
            all_amps.append(m['amps'])
            all_peak_times.append(m['peak_times_s'] + s / fps)

    cat = lambda L: (np.concatenate(L) if L else np.array([]))
    peaks         = np.sort(cat(all_peaks_global).astype(int))
    intervals     = cat(all_intervals)
    rates_bpm     = cat(all_rates_bpm)
    amps          = cat(all_amps)
    peak_times_s  = cat(all_peak_times)

    valid_duration_s = float(np.sum(valid_mask)) / fps
    interval_s_mean  = float(np.mean(intervals)) if intervals.size else float('nan')
    freq_cpm         = (60.0 / interval_s_mean) if intervals.size and interval_s_mean > 0 else float('nan')

    return dict(n=n, fps=fps, t_s=np.arange(n) / fps,
                signal_hp=sig_hp, envelope=env,
                peaks=peaks, intervals=intervals, rates_bpm=rates_bpm,
                amps=amps, peak_times_s=peak_times_s,
                freq_cpm=freq_cpm, interval_s_mean=interval_s_mean,
                n_excluded=int(np.sum(~valid_mask)),
                n_runs=int(len(runs)),
                valid_duration_s=valid_duration_s,
                run_indices=runs,
                hp_window_s=float(hp_window_s), prom_mult=float(prom_mult),
                dist_s=float(dist_s), savgol_w=int(savgol_w))


def _velocity_from_xcorr_gap_aware(diam_NT, valid_mask, sep_um, fps,
                                    min_run_s=2.0):
    """Cross-correlation velocity computed on the LONGEST contiguous valid run.
    Returns (v_um_s, lag_s, direction, used_run=(s,e))."""
    runs = contiguous_runs(np.asarray(valid_mask, bool))
    if not runs:
        return float('nan'), float('nan'), 0, None
    min_len = max(2, int(round(min_run_s * fps)))
    runs = [r for r in runs if (r[1] - r[0] + 1) >= min_len]
    if not runs:
        return float('nan'), float('nan'), 0, None
    s, e = max(runs, key=lambda r: r[1] - r[0])
    prox = diam_NT[0,  s:e + 1]
    dist = diam_NT[-1, s:e + 1]
    v, lag, d = _velocity_from_xcorr(np.nan_to_num(prox, nan=float(np.nanmean(prox))),
                                       np.nan_to_num(dist, nan=float(np.nanmean(dist))),
                                       sep_um, fps)
    return v, lag, d, (s, e)


# ════════════════════════════════════════════════════════════════════════════
# Bolus dynamics — saturation handling, dynamic signal D(t), optical flow,
# front tracking, temporal arrival projection. The bright dye-filled lumen is
# flat (sensor and/or loader-clip saturated); motion lives at the FRONT and in
# the temporal derivative. All velocity outputs are in µm/s.
# ════════════════════════════════════════════════════════════════════════════
def detect_saturation(proj_THW, mode='max', pct=99.5, eps=1e-6):
    """Per-frame saturation map. ``mode='max'`` flags pixels at-or-near the
    per-frame max; ``mode='percentile'`` flags pixels >= the given percentile.
    Returns (sat_mask_THW: bool, per_frame_frac: (T,) float, total_frac: float)."""
    proj = np.asarray(proj_THW, np.float32)
    T = proj.shape[0]
    if mode == 'percentile':
        thr = np.percentile(proj, float(pct))
        sat = proj >= thr
    else:                                                # 'max'
        per_max = proj.reshape(T, -1).max(axis=1)        # (T,)
        sat = proj >= (per_max[:, None, None] - eps)
    per_frame = sat.reshape(T, -1).mean(axis=1).astype(np.float32)
    return sat, per_frame, float(sat.mean())


def compute_dynamic_signal(proj_THW, mode='diff_dt', dt=1, win_t=11,
                           sigma_xy=1.0, bg_mode='none', bg_pct=5.0,
                           polarity='signed'):
    """Per-frame dynamic signal D(t,y,x) that emphasises moving fronts and
    suppresses static saturated bulk.

    Pipeline:
        1) optional spatial Gaussian smooth (sigma_xy) per frame,
        2) optional temporal smoothing (window win_t, uniform mean),
        3) per-frame BG subtraction ('percentile' floor or 'none'),
        4) one of:
            mode='diff_dt'             : I(t) - I(t-dt)
            mode='diff_rolling'        : I(t) - rolling_mean(I[t-win:t+win])
            mode='derivative_smoothed' : ∂I/∂t after a temporal Gaussian smooth,
        5) polarity: 'signed' | 'absolute' | 'leading' (max(D,0)) | 'trailing' (max(-D,0)).
    """
    from scipy.ndimage import gaussian_filter, uniform_filter1d, gaussian_filter1d
    I = np.asarray(proj_THW, np.float32).copy()
    T = I.shape[0]
    # (1) spatial smooth
    if sigma_xy and float(sigma_xy) > 0:
        for t in range(T):
            I[t] = gaussian_filter(I[t], sigma=float(sigma_xy), mode='nearest')
    # (2) temporal smooth (uniform mean over win_t, win_t=1 = no-op)
    win_t = int(max(1, win_t))
    if win_t > 1 and mode != 'derivative_smoothed':
        I = uniform_filter1d(I, size=win_t, axis=0, mode='nearest')
    # (3) BG subtraction (per frame)
    if bg_mode == 'percentile':
        for t in range(T):
            pos = I[t]
            pos = pos[pos > 0]
            floor = float(np.percentile(pos, float(bg_pct))) if pos.size else 0.0
            I[t] = np.clip(I[t] - floor, 0, None)
    # (4) temporal differencing
    if mode == 'diff_dt':
        d = int(max(1, dt))
        D = np.zeros_like(I)
        D[d:] = I[d:] - I[:-d]
    elif mode == 'diff_rolling':
        win = int(max(2, win_t))
        baseline = uniform_filter1d(I, size=win, axis=0, mode='nearest')
        D = I - baseline
    elif mode == 'derivative_smoothed':
        # temporal Gaussian smooth + first derivative along axis 0
        sigma_t = max(1.0, win_t / 2.0)
        D = gaussian_filter1d(I, sigma=sigma_t, order=1, axis=0, mode='nearest')
    else:
        raise ValueError(f"unknown dynamic-signal mode: {mode!r}")
    # (5) polarity
    if polarity == 'absolute':
        D = np.abs(D)
    elif polarity == 'leading':
        D = np.maximum(D, 0)
    elif polarity == 'trailing':
        D = np.maximum(-D, 0)
    # else 'signed' — keep as is
    return D.astype(np.float32)


def _build_centerline_band_mask(H, W, centers, band_half_px):
    """Boolean mask of pixels within `band_half_px` of the polyline center
    samples — used to restrict optical-flow / front-tracking to the vessel."""
    from scipy.ndimage import distance_transform_edt
    cmask = np.zeros((H, W), bool)
    cx = np.clip(centers[:, 0].astype(int), 0, W - 1)
    cy = np.clip(centers[:, 1].astype(int), 0, H - 1)
    cmask[cy, cx] = True
    dist = distance_transform_edt(~cmask)
    return dist <= float(band_half_px)


def compute_optical_flow(proj_THW, method='farneback', use_clahe_for_flow=True,
                          farneback_kw=None):
    """Dense optical flow between consecutive frames. Returns flow array of
    shape (T-1, H, W, 2) where the last axis is (vy, vx) in PIXELS / FRAME.

    method='farneback'  : cv2.calcOpticalFlowFarneback (always available).
    method='tvl1'       : cv2.optflow.DualTVL1OpticalFlow_create() — needs
                          opencv-contrib; falls back to Farneback + warns.
    use_clahe_for_flow  : run CLAHE on a COPY used only for flow estimation
                          (improves tracking at low contrast; does NOT affect
                          reported amplitudes — velocity is motion-based).
    """
    import cv2
    proj = np.asarray(proj_THW, np.float32)
    T, H, W = proj.shape
    if T < 2:
        return np.zeros((0, H, W, 2), np.float32)
    # 8-bit conversion (cv2 flow algorithms require uint8)
    def _u8(img01):
        return (np.clip(img01, 0, 1) * 255).astype(np.uint8)
    if use_clahe_for_flow:
        cl = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
        u8 = np.stack([cl.apply(_u8(proj[t])) for t in range(T)])
    else:
        u8 = np.stack([_u8(proj[t]) for t in range(T)])
    fk = dict(pyr_scale=0.5, levels=3, winsize=15, iterations=3,
              poly_n=5, poly_sigma=1.2, flags=0)
    if farneback_kw:
        fk.update(farneback_kw)
    tvl1 = None
    if method == 'tvl1':
        try:
            tvl1 = cv2.optflow.DualTVL1OpticalFlow_create()
        except Exception:
            print("[flow] cv2.optflow not available — falling back to Farneback "
                  "(install opencv-contrib-python to enable TV-L1).")
            tvl1 = None
    flow = np.empty((T - 1, H, W, 2), np.float32)
    for t in range(T - 1):
        if tvl1 is not None:
            f = tvl1.calc(u8[t], u8[t + 1], None)
        else:
            f = cv2.calcOpticalFlowFarneback(u8[t], u8[t + 1], None, **fk)
        # cv2 returns (vx, vy) per pixel; pack as (vy, vx) for consistency
        flow[t, :, :, 0] = f[..., 1]       # vy
        flow[t, :, :, 1] = f[..., 0]       # vx
    return flow


def project_flow_onto_centerline(flow_T1HW2, centers, tangents,
                                  band_mask=None, sat_mask_THW=None,
                                  grad_min=None, source_for_grad=None,
                                  px_um=1.0, fps=1.0):
    """For each frame and centerline sample point, project the local flow vector
    onto the unit tangent and convert to µm/s.

    Returns:
        v_tan_um_s  : (T-1, N) tangential speed
        v_mag_um_s  : (T-1, N) flow magnitude
        valid_mask  : (T-1, N) bool — pixel was inside band, non-saturated, gradient>thr.
    """
    flow = np.asarray(flow_T1HW2, np.float32)
    Tm1, H, W, _ = flow.shape
    N = centers.shape[0]
    cy = np.clip(centers[:, 1].astype(int), 0, H - 1)
    cx = np.clip(centers[:, 0].astype(int), 0, W - 1)
    v_tan = np.zeros((Tm1, N), np.float32)
    v_mag = np.zeros((Tm1, N), np.float32)
    valid = np.ones((Tm1, N), bool)
    # gradient mask (drop flat regions — flow is ambiguous there)
    if grad_min is not None and source_for_grad is not None:
        from scipy.ndimage import sobel
        src = np.asarray(source_for_grad, np.float32)
        gx = sobel(src.mean(axis=0), axis=1)
        gy = sobel(src.mean(axis=0), axis=0)
        gmag = np.hypot(gx, gy)
        thr = float(grad_min) * float(np.std(gmag))
        gmask_pt = gmag[cy, cx] >= thr
    else:
        gmask_pt = np.ones(N, bool)
    bmask_pt = np.ones(N, bool) if band_mask is None else band_mask[cy, cx]
    for t in range(Tm1):
        fy = flow[t, cy, cx, 0]; fx = flow[t, cy, cx, 1]
        v_tan[t] = (fy * tangents[:, 1] + fx * tangents[:, 0]) * fps * px_um
        v_mag[t] = np.hypot(fy, fx) * fps * px_um
        ok = bmask_pt & gmask_pt
        if sat_mask_THW is not None and t < sat_mask_THW.shape[0]:
            ok &= ~sat_mask_THW[t, cy, cx]
        valid[t] = ok
    v_tan[~valid] = np.nan
    v_mag[~valid] = np.nan
    return v_tan, v_mag, valid


def front_position_along_centerline(D_THW, centers, tangents, band_half_px,
                                     threshold_k=2.0, px_um=1.0,
                                     polarity='leading'):
    """Per-frame leading-edge position along the centerline.

    For each frame t:
        1) sample D in a small (2r+1)² window around each centerline point
           (mean) → D_line[t, i] of shape (T, N),
        2) define threshold = k × std(D_line[t]),
        3) front index = first i (left-to-right) where D_line[t, i] crosses
           the threshold (fallback to argmax if no crossing),
        4) front position (µm) = arclen_um[front_index].

    Returns (front_um (T,), D_line (T, N), arclen_um (N,)).
    """
    proj = np.asarray(D_THW, np.float32)
    T, H, W = proj.shape
    N = centers.shape[0]
    # arclen_um: cumulative arc length from centers
    seg = np.diff(centers, axis=0)
    arclen_px = np.concatenate([[0.0], np.cumsum(np.hypot(seg[:, 0], seg[:, 1]))])
    arclen_um = arclen_px * float(px_um)
    r = max(0, int(band_half_px))
    cx = np.clip(centers[:, 0].astype(int), 0, W - 1)
    cy = np.clip(centers[:, 1].astype(int), 0, H - 1)
    D_line = np.zeros((T, N), np.float32)
    for t in range(T):
        for i in range(N):
            x = cx[i]; y = cy[i]
            x0, x1 = max(0, x - r), min(W, x + r + 1)
            y0, y1 = max(0, y - r), min(H, y + r + 1)
            if x1 > x0 and y1 > y0:
                D_line[t, i] = proj[t, y0:y1, x0:x1].mean()
    front_um = np.full(T, np.nan, np.float32)
    for t in range(T):
        row = D_line[t]
        if polarity == 'leading':
            sig = np.maximum(row, 0)
        elif polarity == 'trailing':
            sig = np.maximum(-row, 0)
        elif polarity == 'absolute':
            sig = np.abs(row)
        else:
            sig = row
        s = float(np.nanstd(sig))
        if not np.isfinite(s) or s < 1e-12:
            continue
        thr = float(threshold_k) * s
        above = sig >= thr
        if above.any():
            idx = int(np.argmax(above))                   # first True
        else:
            idx = int(np.argmax(sig))
        front_um[t] = arclen_um[idx]
    return front_um, D_line, arclen_um


def temporal_arrival_projection(D_THW, fps, min_mag_k=1.0, polarity='leading'):
    """Per-pixel time-of-arrival map (Fig 2c analog).

    For each pixel, t_arrival = argmax_t leading(D[t]); brightness = peak
    magnitude (min-max normalised). Pixels with magnitude < min_mag_k × σ(mag)
    are blacked out (no arrival). Returns:
        rgb (H, W, 3) HSV→RGB float in [0,1]
        t_arrival_s (H, W) float, in seconds
        magnitude (H, W) float, peak magnitude (before normalisation)
    """
    from matplotlib.colors import hsv_to_rgb
    D = np.asarray(D_THW, np.float32)
    T, H, W = D.shape
    if T < 2:
        return None, None, None
    if polarity == 'leading':
        sig = np.maximum(D, 0)
    elif polarity == 'trailing':
        sig = np.maximum(-D, 0)
    elif polarity == 'absolute':
        sig = np.abs(D)
    else:
        sig = D
    idx = np.argmax(sig, axis=0)
    magnitude = sig.max(axis=0)
    # blank out low-magnitude pixels
    msig = float(np.nanstd(magnitude))
    if msig > 1e-12 and min_mag_k > 0:
        magnitude = np.where(magnitude >= float(min_mag_k) * msig,
                              magnitude, 0.0)
    mmax = float(np.nanmax(magnitude))
    val = magnitude / mmax if mmax > 0 else magnitude
    hue = idx.astype(np.float32) / max(T - 1, 1)
    hsv = np.stack([hue, np.ones_like(val), val], axis=-1)
    rgb = hsv_to_rgb(hsv)
    t_arrival_s = idx.astype(np.float32) / float(fps)
    return rgb.astype(np.float32), t_arrival_s, magnitude.astype(np.float32)


# ════════════════════════════════════════════════════════════════════════════
# Lymphatic pulse batch — HEADLESS scientific core shared by the Pulse Flow
# Analyzer ("Lymphatic mode") and callable programmatically. Reuses the
# analyzer-agnostic kernels above; NEVER opens a window or reads Tk state.
# Quantitative measurements run on the LINEAR/raw (optionally translation-only
# motion-corrected) stack passed in — never on CLAHE/gamma display images.
# ════════════════════════════════════════════════════════════════════════════
def _bootstrap_ci(vals, n_boot=2000, ci=95.0, seed=0):
    """Percentile bootstrap CI for the mean. Returns (lo, hi); NaN if n<3."""
    a = np.asarray(vals, float); a = a[np.isfinite(a)]
    if a.size < 3:
        return float('nan'), float('nan')
    rng = np.random.RandomState(int(seed))
    boots = a[rng.randint(0, a.size, size=(int(n_boot), a.size))].mean(axis=1)
    lo = float(np.percentile(boots, (100.0 - ci) / 2.0))
    hi = float(np.percentile(boots, 100.0 - (100.0 - ci) / 2.0))
    return lo, hi


def _msd_stats(vals):
    """mean, SD (ddof=1), SEM, CV, median, IQR, n over finite values."""
    a = np.asarray(vals, float); a = a[np.isfinite(a)]
    n = int(a.size)
    if n == 0:
        return dict(n=0, mean=float('nan'), sd=float('nan'), sem=float('nan'),
                    cv=float('nan'), median=float('nan'), iqr=float('nan'))
    mean = float(a.mean())
    sd = float(a.std(ddof=1)) if n > 1 else 0.0
    sem = float(sd / np.sqrt(n)) if n > 1 else 0.0
    cv = float(sd / abs(mean)) if abs(mean) > 1e-12 else float('nan')
    q1, q3 = (np.percentile(a, [25, 75]) if n > 1 else (a[0], a[0]))
    return dict(n=n, mean=mean, sd=sd, sem=sem, cv=cv,
                median=float(np.median(a)), iqr=float(q3 - q1))


def _rise_decay_times(trace, fps):
    """10-90% rise and 90-10% decay times (s) around the trace peak.
    Returns (rise_s, decay_s); NaN when undefined."""
    x = np.asarray(trace, float)
    if x.size < 3:
        return float('nan'), float('nan')
    base = float(np.percentile(x, 10)); pk_i = int(np.argmax(x))
    amp = float(x[pk_i] - base)
    if amp <= 1e-12:
        return float('nan'), float('nan')
    lo_l, hi_l = base + 0.1 * amp, base + 0.9 * amp
    rise = float('nan'); decay = float('nan')
    # rise: last crossing of 10% then 90% before the peak
    try:
        seg = x[:pk_i + 1]
        i10 = np.where(seg <= lo_l)[0]
        i90 = np.where(seg >= hi_l)[0]
        if i10.size and i90.size:
            rise = (int(i90[0]) - int(i10[-1])) / float(fps)
            if rise < 0:
                rise = float('nan')
    except Exception:
        pass
    try:
        seg = x[pk_i:]
        j90 = np.where(seg >= hi_l)[0]
        j10 = np.where(seg <= lo_l)[0]
        if j90.size and j10.size:
            decay = (int(j10[0]) - int(j90[-1])) / float(fps)
            if decay < 0:
                decay = float('nan')
    except Exception:
        pass
    return rise, decay


def _kymo_peak_trajectory(kymo, fps):
    """Per-arclength-point strongest-peak time (s). Returns (N,) with NaN
    where no peak is found. Same rule as `_velocity_from_kymograph`."""
    from scipy.signal import find_peaks
    N, T = kymo.shape
    pt = np.full(N, np.nan, float)
    for i in range(N):
        row = kymo[i]
        if not np.isfinite(row).any():
            continue
        r = np.nan_to_num(row - np.nanmean(row), nan=0.0)
        pk, _ = find_peaks(r, prominence=np.nanstd(r) * 0.4 + 1e-9)
        if len(pk):
            pt[i] = pk[int(np.argmax(r[pk]))] / float(fps)
    return pt


def _classify_direction(v_um_s, min_speed=1.0):
    """anterograde (+, distal-ward) / retrograde (-) / stall / undefined."""
    if v_um_s is None or not np.isfinite(v_um_s):
        return 'undefined'
    if abs(v_um_s) < float(min_speed):
        return 'stall'
    return 'anterograde' if v_um_s > 0 else 'retrograde'


def run_lymphatic_pulse_batch_core(stack_THW, centerlines, fps, px_um,
                                   boundaries=None, file_names=None,
                                   bg_rois=None, settings=None):
    """Headless lymphatic-pulse batch analysis on a LINEAR (optionally
    translation-only motion-corrected) 2D stack.

    Parameters
    ----------
    stack_THW : (T, H, W) float — the raw/corrected measurement stack.
    centerlines : one (M,2) x/y polyline proximal->distal, or a list of them
                  (up to 3 used). Each is resampled to ``settings['n_points']``.
    fps, px_um : acquisition rate (Hz) and pixel size (µm/px).
    boundaries : optional sorted frame cut-points [b0, b1, ... bK] delimiting
                 cycles when ``cycle_mode='file_boundary'`` (1 file = 1 cycle).
    file_names : optional list of per-cycle file names.
    bg_rois    : optional per-frame background trace (T,) subtracted from the
                 intensity kymograph, OR None.
    settings   : optional dict (see defaults below).

    Returns a dict (see module header / task spec) with per-line results,
    per-cycle rows, summary rows, QC rows, arrays_for_npz and full metadata.
    """
    import datetime as _dt
    S = dict(n_points=60, band_half_px=3, diameter=True, profile_len_px=21,
             fwhm_frac=0.5, hp_window_s=5.0, prom_mult=0.5, dist_s=0.3,
             savgol_w=7, cycle_mode='file_boundary', min_cycle_frames=5,
             min_speed_um_s=1.0, dyn_mode='diff_dt', front_threshold_k=2.0,
             valid_mask=None, motion_corrected=False, motion_settings=None,
             motion_shifts=None, hierarchy=None)
    if settings:
        S.update(settings)

    stack = np.asarray(stack_THW, np.float32)
    if stack.ndim != 3:
        raise ValueError("stack_THW must be (T, H, W)")
    T, H, W = stack.shape
    fps = float(fps); px_um = float(px_um)
    N_PTS = int(S['n_points']); BAND = int(S['band_half_px'])

    if isinstance(centerlines, np.ndarray):
        centerlines = [centerlines]
    centerlines = [np.asarray(c, float) for c in (centerlines or [])
                   if c is not None and len(c) >= 2][:3]

    valid_mask = S['valid_mask']
    if valid_mask is None:
        valid_mask = np.ones(T, bool)
    valid_mask = np.asarray(valid_mask, bool)[:T]
    n_excluded = int(np.sum(~valid_mask))

    bg_trace = None
    if bg_rois is not None:
        try:
            _b = np.asarray(bg_rois, float).ravel()
            if _b.size == T:
                bg_trace = _b
        except Exception:
            bg_trace = None

    shifts = None
    if S.get('motion_shifts') is not None:
        try:
            shifts = np.asarray(S['motion_shifts'], float).reshape(-1, 2)
        except Exception:
            shifts = None

    # ── cycle segmentation ──────────────────────────────────────────────
    def _cycles_from_boundaries(bnds):
        out = []
        b = sorted(int(x) for x in bnds)
        for i in range(len(b) - 1):
            s, e = b[i], b[i + 1]
            if (e - s) >= int(S['min_cycle_frames']):
                out.append((s, e))
        return out

    def _cycles_from_peaks(trace):
        m = _pulse_metrics_from_trace(trace, fps, hp_window_s=S['hp_window_s'],
                                      prom_mult=S['prom_mult'],
                                      dist_s=S['dist_s'], savgol_w=S['savgol_w'])
        pk = np.asarray(m.get('peaks', []), int)
        out = []
        for i in range(len(pk) - 1):
            s, e = int(pk[i]), int(pk[i + 1])
            if (e - s) >= int(S['min_cycle_frames']):
                out.append((s, e))
        return out

    per_line = {}
    kymo_intensity = {}; kymo_diameter = {}; dynamic_signal = {}
    front_position_um = {}; peak_trajectory = {}
    arrival_projection = None
    qc_rows = []

    for li, cl in enumerate(centerlines):
        centers, tangents, arclen_px = _sample_along_polyline(cl, N_PTS)
        if centers is None:
            qc_rows.append(dict(line_id=li, flag='CENTERLINE_TOO_SHORT',
                                detail=f"{len(cl)} pts"))
            continue
        arclen_um = arclen_px * px_um
        total_um = float(arclen_um[-1])
        spacing_um = total_um / max(N_PTS - 1, 1)
        sep_um = total_um

        kymo = _intensity_kymograph_band(stack, centers, BAND, px_um)   # (N,T)
        if bg_trace is not None:
            kymo = kymo - bg_trace[None, :]
        along_mean = np.nanmean(kymo, axis=0)                           # (T,)

        # diameter kymograph (optional; only kept if mostly finite)
        diam = None; diam_ok = False
        if bool(S['diameter']):
            try:
                diam = _diameter_kymograph(stack, centers, tangents,
                                           int(S['profile_len_px']),
                                           float(S['fwhm_frac']), px_um)
                finite_frac = float(np.isfinite(diam).mean())
                diam_ok = finite_frac >= 0.5
                if not diam_ok:
                    qc_rows.append(dict(line_id=li, flag='DIAMETER_UNRELIABLE',
                                        detail=f"finite={finite_frac:.2f}"))
            except Exception as _e:
                qc_rows.append(dict(line_id=li, flag='DIAMETER_FAILED',
                                    detail=str(_e)))
                diam = None; diam_ok = False

        # dynamic signal along the line + front position + arrival map
        D_line = None; front_um = None
        try:
            D = compute_dynamic_signal(stack, mode=str(S['dyn_mode']))
            front_um, D_line, _al = front_position_along_centerline(
                D, centers, tangents, BAND,
                threshold_k=float(S['front_threshold_k']), px_um=px_um)
            if arrival_projection is None:
                rgb, t_arr, mag = temporal_arrival_projection(D, fps)
                arrival_projection = rgb
        except Exception as _e:
            qc_rows.append(dict(line_id=li, flag='DYNAMIC_SIGNAL_FAILED',
                                detail=str(_e)))

        # pulse metrics (gap-aware if frames excluded)
        if n_excluded > 0:
            pm = _pulse_metrics_gap_aware(along_mean, fps, valid_mask=valid_mask,
                                          hp_window_s=S['hp_window_s'],
                                          prom_mult=S['prom_mult'],
                                          dist_s=S['dist_s'], savgol_w=S['savgol_w'])
        else:
            pm = _pulse_metrics_from_trace(along_mean, fps,
                                           hp_window_s=S['hp_window_s'],
                                           prom_mult=S['prom_mult'],
                                           dist_s=S['dist_s'], savgol_w=S['savgol_w'])

        v_slope, slope_resid, dir_slope = _velocity_from_kymograph(
            kymo, fps, spacing_um)
        v_xcorr, lag_s, dir_xcorr = _velocity_from_xcorr(
            kymo[0], kymo[-1], sep_um, fps)
        traj = _kymo_peak_trajectory(kymo, fps)

        kymo_intensity[li] = kymo
        if diam_ok:
            kymo_diameter[li] = diam
        if D_line is not None:
            dynamic_signal[li] = D_line
        if front_um is not None:
            front_position_um[li] = front_um
        peak_trajectory[li] = traj
        per_line[li] = dict(
            line_id=li, n_points=N_PTS, total_arclen_um=total_um,
            spacing_um=spacing_um, centers=centers, tangents=tangents,
            arclen_um=arclen_um, along_mean=along_mean, pulse_metrics=pm,
            velocity_slope_um_s=float(v_slope),
            velocity_xcorr_um_s=float(v_xcorr), lag_s=float(lag_s),
            direction=_classify_direction(v_slope, S['min_speed_um_s']),
            diameter_ok=bool(diam_ok))

    # primary line for cycle segmentation / dynamic outputs
    prim = per_line.get(sorted(per_line)[0]) if per_line else None

    # ── cycle segmentation on the primary line's along-mean ──────────────
    cycle_mode = str(S['cycle_mode'])
    if cycle_mode == 'file_boundary' and boundaries and len(boundaries) >= 2:
        cycles = _cycles_from_boundaries(boundaries)
    elif prim is not None:
        cycle_mode = 'auto_peaks'
        cycles = _cycles_from_peaks(prim['along_mean'])
    else:
        cycles = []

    # ── per-cycle metrics (primary line) ─────────────────────────────────
    cycle_rows = []
    if prim is not None:
        pk = kymo_intensity[prim['line_id']]
        along = prim['along_mean']
        fr = front_position_um.get(prim['line_id'])
        dm = kymo_diameter.get(prim['line_id'])
        for ci, (s, e) in enumerate(cycles):
            tr = along[s:e]
            if tr.size < 2:
                continue
            base = float(np.percentile(tr, 10))
            pk_rel = int(np.argmax(tr)); pk_i = s + pk_rel
            amp = float(tr[pk_rel] - base)
            auc = float(np.clip(tr - base, 0, None).sum() / fps)
            # FWHM duration (frames -> s)
            fwhm_px = _fwhm_from_profile(tr, 0.5)
            fwhm_s = float(fwhm_px / fps) if fwhm_px == fwhm_px else float('nan')
            rise_s, decay_s = _rise_decay_times(tr, fps)
            # diameter
            dmin = dmax = dfrac = float('nan')
            if dm is not None:
                dseg = np.nanmean(dm[:, s:e], axis=0)
                if np.isfinite(dseg).any():
                    dmin = float(np.nanmin(dseg)); dmax = float(np.nanmax(dseg))
                    dfrac = float((dmax - dmin) / dmax) if dmax > 0 else float('nan')
            # front / distance
            fs = fe = dist_um = float('nan')
            if fr is not None and e <= fr.size:
                seg = fr[s:e]
                if np.isfinite(seg).any():
                    fs = float(np.nanmin(seg)); fe = float(np.nanmax(seg))
                    dist_um = float(fe - fs)
            # per-cycle velocity
            kc = pk[:, s:e]
            vsl, _, _ = _velocity_from_kymograph(kc, fps, prim['spacing_um'])
            vxc, lagc, _ = _velocity_from_xcorr(kc[0], kc[-1],
                                                prim['total_arclen_um'], fps)
            vfrac = float(np.mean(valid_mask[s:e])) if e <= valid_mask.size else 1.0
            msh = xsh = float('nan')
            if shifts is not None and e <= shifts.shape[0]:
                mag = np.hypot(shifts[s:e, 0], shifts[s:e, 1])
                msh = float(mag.mean()); xsh = float(mag.max())
            flags = []
            if (e - s) < int(S['min_cycle_frames']):
                flags.append('TOO_FEW_FRAMES')
            if vfrac < 0.5:
                flags.append('HIGH_MOTION')
            if not np.isfinite(vsl) and not np.isfinite(vxc):
                flags.append('LOW_R2')
            if bg_trace is None:
                flags.append('NO_BG')
            direction = _classify_direction(
                vsl if np.isfinite(vsl) else vxc, S['min_speed_um_s'])
            cycle_rows.append(dict(
                cycle_id=ci,
                file_name=(file_names[ci] if (file_names and ci < len(file_names))
                           else f"cycle_{ci}"),
                start_frame=int(s), end_frame=int(e),
                duration_s=float((e - s) / fps),
                peak_frame=int(pk_i), peak_time_s=float(pk_i / fps),
                amplitude=amp, baseline=base, auc_above_baseline=auc,
                fwhm_duration_s=fwhm_s, rise_10_90_s=rise_s,
                decay_90_10_s=decay_s,
                diameter_min_um=dmin, diameter_max_um=dmax,
                fractional_diameter_change=dfrac,
                front_start_um=fs, front_end_um=fe, distance_travelled_um=dist_um,
                velocity_slope_um_s=float(vsl), velocity_xcorr_um_s=float(vxc),
                lag_s=float(lagc), direction=direction,
                valid_frame_fraction=vfrac, mean_shift_px=msh, max_shift_px=xsh,
                quality_flags=";".join(flags)))

    # ── statistical summary ──────────────────────────────────────────────
    def _col(key):
        return [r[key] for r in cycle_rows]

    summary_rows = []
    key_metrics = ['amplitude', 'baseline', 'auc_above_baseline',
                   'duration_s', 'fwhm_duration_s', 'velocity_slope_um_s',
                   'velocity_xcorr_um_s', 'distance_travelled_um',
                   'fractional_diameter_change']
    for m in key_metrics:
        st = _msd_stats(_col(m)) if cycle_rows else _msd_stats([])
        lo, hi = (_bootstrap_ci(_col(m)) if (cycle_rows and st['n'] >= 3)
                  else (float('nan'), float('nan')))
        summary_rows.append(dict(metric=m, **st, ci95_lo=lo, ci95_hi=hi))

    # ── biological interpretation indices ────────────────────────────────
    n_cycles = len(cycle_rows)
    periods = np.diff([r['peak_time_s'] for r in cycle_rows]) if n_cycles >= 2 else np.array([])
    rhythm_cv = (float(np.std(periods, ddof=1) / np.mean(periods))
                 if periods.size >= 2 and np.mean(periods) > 0 else float('nan'))
    amps = np.array(_col('amplitude'), float) if cycle_rows else np.array([])
    bases = np.array(_col('baseline'), float) if cycle_rows else np.array([])
    with np.errstate(divide='ignore', invalid='ignore'):
        contractility = float(np.nanmean(np.where(bases > 0, amps / bases, np.nan))) \
            if cycle_rows else float('nan')
    aucs = np.array(_col('auc_above_baseline'), float) if cycle_rows else np.array([])
    dists = np.array(_col('distance_travelled_um'), float) if cycle_rows else np.array([])
    transport = float(np.nanmean(aucs * dists)) if cycle_rows else float('nan')
    dirs = _col('direction') if cycle_rows else []
    ante = dirs.count('anterograde'); retro = dirs.count('retrograde')
    stall = dirs.count('stall')
    valid_vel = sum(1 for r in cycle_rows
                    if np.isfinite(r['velocity_slope_um_s'])
                    or np.isfinite(r['velocity_xcorr_um_s']))
    bio = dict(
        n_cycles=n_cycles, rhythmicity_cv_period=rhythm_cv,
        contractility_index=contractility, transport_index=transport,
        propagation_reliability=(valid_vel / n_cycles if n_cycles else float('nan')),
        anterograde_fraction=(ante / n_cycles if n_cycles else float('nan')),
        retrograde_fraction=(retro / n_cycles if n_cycles else float('nan')),
        stall_fraction=(stall / n_cycles if n_cycles else float('nan')),
        artifact_burden=(n_excluded / T if T else float('nan')))

    # ── arrays for NPZ ───────────────────────────────────────────────────
    arrays = dict(valid_mask=valid_mask.astype(np.uint8),
                  boundaries=np.asarray(boundaries if boundaries else [], int))
    if shifts is not None:
        arrays['motion_shifts'] = shifts
    for li, k in kymo_intensity.items():
        arrays[f'kymo_intensity_L{li}'] = k
    for li, k in kymo_diameter.items():
        arrays[f'kymo_diameter_L{li}'] = k
    for li, f in front_position_um.items():
        arrays[f'front_um_L{li}'] = f
    for li, d in dynamic_signal.items():
        arrays[f'dyn_line_L{li}'] = d
    for li, L in per_line.items():
        arrays[f'centerline_L{li}'] = L['centers']
        arrays[f'arclen_um_L{li}'] = L['arclen_um']
    if arrival_projection is not None:
        arrays['arrival_projection'] = arrival_projection

    hier = dict(animal_id='', vessel_id='', recording_id='', condition='')
    if S.get('hierarchy'):
        hier.update({k: v for k, v in S['hierarchy'].items() if k in hier})

    metadata = dict(
        created=_dt.datetime.now().isoformat(timespec='seconds'),
        fps=fps, px_um=px_um, T=int(T), H=int(H), W=int(W),
        n_lines=len(per_line), n_points=N_PTS, band_half_px=BAND,
        cycle_mode=cycle_mode, n_cycles=n_cycles,
        motion_corrected=bool(S['motion_corrected']),
        motion_settings=(S['motion_settings'] or {}),
        n_excluded_frames=n_excluded,
        pulse_defaults=dict(hp_window_s=S['hp_window_s'],
                            prom_mult=S['prom_mult'], dist_s=S['dist_s'],
                            savgol_w=S['savgol_w']),
        centerlines=[np.asarray(c, float).tolist() for c in centerlines],
        hierarchy=hier, biological=bio)

    return dict(
        kymo_intensity=kymo_intensity, kymo_diameter=kymo_diameter,
        dynamic_signal=dynamic_signal, arrival_projection=arrival_projection,
        front_position_um=front_position_um, peak_trajectory=peak_trajectory,
        velocity_slope_um_s={li: L['velocity_slope_um_s']
                             for li, L in per_line.items()},
        velocity_xcorr_um_s={li: L['velocity_xcorr_um_s']
                             for li, L in per_line.items()},
        pulse_metrics={li: L['pulse_metrics'] for li, L in per_line.items()},
        per_line=per_line, cycle_metrics_rows=cycle_rows,
        summary_rows=summary_rows, qc_rows=qc_rows,
        biological=bio, arrays_for_npz=arrays, metadata=metadata)


# ════════════════════════════════════════════════════════════════════════════
# Respiration removal — produce a breathing-cleaned working stack proj_resp
# from the LINEAR/high-headroom data. Distinct from the existing motion
# module's REGISTER (translation) + EXCLUDE: this is a TEMPORAL component
# removal that KEEPS all frames. Apply after optional rigid registration.
# ════════════════════════════════════════════════════════════════════════════
def respiration_surrogate(proj_THW, source='global_mean', motion_shifts=None,
                          roi_xyxy=None):
    """1D breathing surrogate vs time. Returns (T,) float32.

    source='global_mean'  : mean intensity per frame (in roi_xyxy if given)
    source='motion_disp'  : |shifts| per frame (requires motion_shifts (T,2))
    source='pca1'         : 1st PCA component over (T, H*W) (centred per pixel)
    """
    proj = np.asarray(proj_THW, np.float32)
    T = proj.shape[0]
    if source == 'motion_disp':
        if motion_shifts is None:
            return np.zeros(T, np.float32)
        sh = np.asarray(motion_shifts, np.float32)
        return np.hypot(sh[:, 0], sh[:, 1]).astype(np.float32)
    # window
    if roi_xyxy is not None:
        x0, y0, x1, y1 = (int(v) for v in roi_xyxy)
        x0 = max(0, x0); y0 = max(0, y0)
        x1 = min(proj.shape[2], x1); y1 = min(proj.shape[1], y1)
        sub = proj[:, y0:y1, x0:x1]
    else:
        sub = proj
    if source == 'pca1':
        # Centre per pixel, take leading temporal mode via SVD on (T, P)
        flat = sub.reshape(T, -1).astype(np.float64)
        flat -= flat.mean(axis=0, keepdims=True)
        # economy SVD: U (T, k) Σ V^T (k, P)
        try:
            U, S, _ = np.linalg.svd(flat, full_matrices=False)
            surr = (U[:, 0] * S[0]).astype(np.float32)
        except Exception:
            surr = sub.reshape(T, -1).mean(axis=1).astype(np.float32)
        return surr
    # default = global mean
    return sub.reshape(T, -1).mean(axis=1).astype(np.float32)


def detect_breathing_band(surrogate, fps, min_hz=0.5, max_hz=None,
                          n_harmonics=3, prominence_mult=0.1):
    """Locate the dominant breathing peak in the surrogate's power spectrum.
    Returns dict(freqs, power, f_fund, harmonics, lymphatic_band)."""
    from scipy.signal import find_peaks
    x = np.asarray(surrogate, float)
    n = x.size; fps = float(fps)
    if n < 8:
        return dict(freqs=np.array([0.0]), power=np.array([0.0]),
                    f_fund=float('nan'), harmonics=[],
                    lymphatic_band=(0.05, 0.5))
    xz = x - x.mean()
    spec = np.abs(np.fft.rfft(xz)) ** 2
    freqs = np.fft.rfftfreq(n, d=1.0 / fps)
    if max_hz is None:
        max_hz = fps / 2.0
    band = (freqs >= float(min_hz)) & (freqs <= float(max_hz))
    f_fund = float('nan'); harmonics = []
    if band.any():
        prom = float(spec[band].std()) * float(prominence_mult)
        idx, _ = find_peaks(spec * band, prominence=max(prom, 1e-12))
        if idx.size:
            kf = int(idx[int(np.argmax(spec[idx]))])
            f_fund = float(freqs[kf])
            harmonics = [float(f_fund * (h + 2)) for h in range(int(n_harmonics) - 1)
                         if (f_fund * (h + 2)) <= float(max_hz)]
    return dict(freqs=freqs, power=spec, f_fund=f_fund, harmonics=harmonics,
                lymphatic_band=(0.05, 0.5))


def remove_breathing_notch(proj_THW, fps, f_fund, harmonics=None,
                           bw_hz=0.4, order=4):
    """Per-pixel notch along time at the breathing fundamental + harmonics.

    Uses :func:`scipy.signal.iirnotch` per harmonic (a 2nd-order biquad with
    Q = f0/bw) — much sharper and more stable than a high-order Butterworth
    bandstop, especially when the breathing band sits close to the lymphatic
    band (e.g. 1 Hz vs 0.05-0.5 Hz). When ``order > 1``, we apply the same
    notch ``order`` times in cascade for a deeper drop without widening it.
    ``order`` retained for backward compatibility (caller-tunable depth).
    Vectorised: filtfilt applied to (T, H*W)."""
    from scipy.signal import iirnotch, filtfilt
    proj = np.asarray(proj_THW, np.float32)
    T, H, W = proj.shape
    if not np.isfinite(f_fund) or f_fund <= 0:
        return proj.copy()
    nyq = fps / 2.0
    freqs = [float(f_fund)] + [float(h) for h in (harmonics or [])]
    flat = proj.reshape(T, -1).astype(np.float64)
    depth = max(1, int(order))
    for f in freqs:
        w0 = f / nyq                                     # normalised (0..1, where 1 = Nyquist)
        if not (0 < w0 < 1):
            continue
        Q = float(f) / max(float(bw_hz), 1e-6)
        try:
            b, a = iirnotch(w0=w0, Q=Q)
            for _ in range(depth):
                flat = filtfilt(b, a, flat, axis=0, method='gust')
        except Exception:
            continue
    return flat.reshape(T, H, W).astype(np.float32)


def remove_breathing_regression(proj_THW, surrogate, include_quadrature=True):
    """Per-pixel projection-removal of ``surrogate`` (+ Hilbert quadrature)
    from each pixel time series. Vectorised via least-squares on (T, H*W)."""
    from scipy.signal import hilbert
    proj = np.asarray(proj_THW, np.float32)
    T, H, W = proj.shape
    surr = np.asarray(surrogate, float) - float(np.mean(surrogate))
    cols = [surr]
    if include_quadrature:
        try:
            q = np.imag(hilbert(surr))
            cols.append(q)
        except Exception:
            pass
    X = np.stack(cols, axis=1)                        # (T, k)
    Xt = X.T
    XtX_inv = np.linalg.pinv(Xt @ X)
    flat = proj.reshape(T, -1).astype(np.float64)
    coefs = XtX_inv @ (Xt @ flat)                     # (k, P)
    flat -= X @ coefs
    return flat.reshape(T, H, W).astype(np.float32)


def respiratory_phase(surrogate, fps):
    """Hilbert-transform phase (radians, -π..π) of the surrogate."""
    from scipy.signal import hilbert
    x = np.asarray(surrogate, float) - float(np.mean(surrogate))
    analytic = hilbert(x)
    return np.angle(analytic).astype(np.float32)


def snap_to_phase(frame_indices, phase, target=0.0, tol=0.1):
    """For each requested frame index, return the nearest-in-time frame whose
    respiratory phase is within ``tol`` of ``target`` (in radians). Falls back
    to the original index if no candidate within tol exists within ±50 frames."""
    out = []
    phase = np.asarray(phase, float)
    T = phase.size
    for f in frame_indices:
        f0 = max(0, min(int(f), T - 1))
        d = np.abs(((phase - target + np.pi) % (2 * np.pi)) - np.pi)
        win = 50
        lo = max(0, f0 - win); hi = min(T, f0 + win + 1)
        seg = d[lo:hi]
        cand = np.where(seg <= float(tol))[0]
        if cand.size:
            # pick the candidate closest in TIME to f0
            best_local = cand[int(np.argmin(np.abs(cand + lo - f0)))]
            out.append(int(best_local + lo))
        else:
            out.append(f0)
    return out


# ════════════════════════════════════════════════════════════════════════════
# Bolus-blob extraction — vessel-constrained moving-front map per selected
# frame, with arclength projection for quantitative metrics.
# ════════════════════════════════════════════════════════════════════════════
def selected_frame_difference(proj_THW, frame_indices, mode='consecutive',
                              ref_idx=None, rolling_window=11, dt=1,
                              sigma_xy=1.0, polarity='leading'):
    """Per-pair difference at each selected frame. Returns dict[t_k] -> (H,W).

    mode:
        'consecutive'      : D_k = I[t_k] - I[t_{k-1}]  (skip first)
        'fixed_ref'        : D_k = I[t_k] - I[ref_idx]
        'rolling_baseline' : D_k = I[t_k] - mean(I[t_k-w..t_k+w])
    polarity: 'signed' | 'absolute' | 'leading' (max(D,0)) | 'trailing' (max(-D,0))
    """
    from scipy.ndimage import gaussian_filter, uniform_filter1d
    proj = np.asarray(proj_THW, np.float32)
    T, H, W = proj.shape
    frames = sorted({int(f) for f in frame_indices if 0 <= int(f) < T})
    if not frames:
        return {}
    def _smooth(img):
        return gaussian_filter(img, sigma=float(sigma_xy), mode='nearest') if sigma_xy > 0 else img
    out = {}
    if mode == 'fixed_ref':
        if ref_idx is None: ref_idx = frames[0]
        ref = _smooth(proj[max(0, min(int(ref_idx), T - 1))])
        for t in frames:
            d = _smooth(proj[t]) - ref
            out[t] = _polar(d, polarity)
    elif mode == 'rolling_baseline':
        win = int(max(2, rolling_window))
        baseline = uniform_filter1d(proj, size=win, axis=0, mode='nearest')
        for t in frames:
            d = _smooth(proj[t]) - _smooth(baseline[t])
            out[t] = _polar(d, polarity)
    else:                                              # 'consecutive'
        dtv = int(max(1, dt))
        prev = None
        for t in frames:
            if prev is None:
                prev = t; continue
            d = _smooth(proj[t]) - _smooth(proj[max(0, prev - 0)])  # prev frame in selection
            out[t] = _polar(d, polarity)
            prev = t
    return out


def _polar(d, polarity):
    if polarity == 'absolute':  return np.abs(d).astype(np.float32)
    if polarity == 'leading':   return np.maximum(d, 0).astype(np.float32)
    if polarity == 'trailing':  return np.maximum(-d, 0).astype(np.float32)
    return d.astype(np.float32)                        # 'signed'


def vessel_mask_from_centerline(H, W, centers, half_width_px):
    """Boolean mask of pixels within ``half_width_px`` of the polyline samples."""
    from scipy.ndimage import distance_transform_edt
    m = np.zeros((H, W), bool)
    cx = np.clip(centers[:, 0].astype(int), 0, W - 1)
    cy = np.clip(centers[:, 1].astype(int), 0, H - 1)
    m[cy, cx] = True
    dist = distance_transform_edt(~m)
    return dist <= float(half_width_px)


def vessel_mask_from_mip(proj_THW, percentile=85.0):
    """Boolean mask from a percentile threshold on the time-MIP."""
    proj = np.asarray(proj_THW, np.float32)
    mip = proj.max(axis=0)
    thr = float(np.percentile(mip, float(percentile)))
    return mip >= thr


def extract_bolus_blob(D_HW, vessel_mask, sigma_smooth=1.0, morph_radius=1,
                       threshold_mode='percentile', thr_value=80.0):
    """Filled blob region from a per-frame positive-D map, restricted to the
    vessel mask. Smoothing → mask → thresholding → morphological open+close.

    Returns (blob_mask (H,W) bool, blob_signal (H,W) float — the in-vessel
    smoothed D values, NaN outside the vessel)."""
    from scipy.ndimage import gaussian_filter, binary_opening, binary_closing, generate_binary_structure
    d = np.maximum(np.asarray(D_HW, np.float32), 0)
    if sigma_smooth and sigma_smooth > 0:
        d = gaussian_filter(d, sigma=float(sigma_smooth), mode='nearest')
    d_in = np.where(vessel_mask, d, 0.0)
    if threshold_mode == 'percentile':
        v_in = d_in[vessel_mask & np.isfinite(d_in)]
        if v_in.size:
            thr = float(np.percentile(v_in, float(thr_value)))
        else:
            thr = 0.0
    else:                                               # 'absolute'
        thr = float(thr_value)
    mask = (d_in > thr) & vessel_mask
    r = max(0, int(morph_radius))
    if r > 0:
        st = generate_binary_structure(2, 2)
        for _ in range(r):
            mask = binary_opening(mask, st)
        for _ in range(r):
            mask = binary_closing(mask, st)
    blob_signal = np.where(vessel_mask, d, np.nan)
    return mask, blob_signal


def arclength_profile(D_pos_HW, centers, tangents, px_um, cross_half_px=6):
    """For each centerline sample, integrate ``D_pos_HW`` across the local
    perpendicular cross-section (full width = 2*cross_half_px + 1 px), giving
    a 1D arclength profile b(s) in (N,) units of D × px (raw integral)."""
    from scipy.ndimage import map_coordinates
    D = np.asarray(D_pos_HW, np.float32)
    H, W = D.shape
    N = centers.shape[0]
    L = 2 * int(cross_half_px) + 1
    s = np.linspace(-float(cross_half_px), float(cross_half_px), L)
    b = np.zeros(N, np.float32)
    for i in range(N):
        cx, cy = float(centers[i, 0]), float(centers[i, 1])
        tx, ty = float(tangents[i, 0]), float(tangents[i, 1])
        px, py = -ty, tx                                # perpendicular unit
        xs = cx + s * px
        ys = cy + s * py
        prof = map_coordinates(D, np.vstack([ys, xs]), order=1, mode='nearest')
        b[i] = float(np.nansum(prof))
    return b


def pulse_arclength_core(proj, frames, cl, n_pts, band_px, pxu, mode='consecutive',
                         ref_idx=None, sigma_xy=1.0, tau=1, rolling_window=11,
                         sat=None, polarity='leading'):
    """CANONICAL recon arclength pipeline — the single source shared by the recon window
    (`_compute_pulse_arclength`) and the manual batch (`_recon_block`).

    difference (`selected_frame_difference`) -> optional saturation NaN-mask ->
    b(s,t) = `arclength_profile(max(D,0), centers, tangents, pxu, band)` ->
    per-column s*(t)=arclen[argmax(b)], amp_at_star, fwhm.  NO prominence gate here (that is a
    fit-time choice, applied by `recon_velocity_from_arclength`).  Does not change the math."""
    proj = np.asarray(proj, np.float32)
    T = proj.shape[0]
    pm = proj
    if tau and int(tau) > 1:
        from scipy.ndimage import uniform_filter1d
        pm = uniform_filter1d(proj, size=int(tau), axis=0, mode='nearest')
    frames = sorted({int(f) for f in frames if 0 <= int(f) < T})
    Dmap = selected_frame_difference(pm, frames, mode=mode, ref_idx=ref_idx,
                                     rolling_window=rolling_window, dt=1,
                                     sigma_xy=float(sigma_xy), polarity=polarity)

    def _satmask(d, t):
        if sat is None or t >= np.asarray(sat).shape[0]:
            return d
        m = np.asarray(sat)[min(t, np.asarray(sat).shape[0] - 1)]
        if not m.any():
            return d
        out = d.astype(np.float32, copy=True); out[m] = np.nan
        return out

    present = [t for t in frames if Dmap.get(t) is not None]
    cl = np.asarray(cl, float) if cl is not None else None
    have_cl = cl is not None and len(cl) >= 2
    b_profiles = []; arclen_um = None; centers = tangents = None
    if have_cl:
        centers, tangents, arclen_px = _sample_along_polyline(cl, int(n_pts))
        arclen_um = arclen_px * float(pxu)
        for t in present:
            d = _satmask(Dmap[t], t)
            b = arclength_profile(np.maximum(np.nan_to_num(d, nan=0.0), 0),
                                  centers, tangents, float(pxu), cross_half_px=int(band_px))
            b_profiles.append(b)
    s_star_um = np.zeros(len(present), np.float32)
    amp_at_star = np.zeros(len(present), np.float32)
    fwhm_um = np.full(len(present), np.nan, np.float32)
    if have_cl and b_profiles:
        for k, b in enumerate(b_profiles):
            pk = int(np.argmax(b))
            s_star_um[k] = float(arclen_um[pk]); amp_at_star[k] = float(b[pk])
            fwhm_um[k] = _fwhm_profile(b, arclen_um, pk)
    B = np.stack(b_profiles, axis=1) if b_profiles else None
    return dict(present=present, mode=mode, Dmap=Dmap, sat_mask=_satmask,
                centers=centers, tangents=tangents, arclen_um=arclen_um,
                have_cl=have_cl, b_profiles=b_profiles, B=B, kymo=B,
                s_star_um=s_star_um, amp_at_star=amp_at_star, fwhm_um=fwhm_um)


def _local_speed_from_arclength(t_s, s_star_um, m_s_slope, r2,
                                win=3, lo_frac=0.25, hi_frac=4.0):
    """Per-sample propagation speed in µm/s, consistent with the pulse fit.
    v(t) = d s*/dt via a short-window robust slope (NOT 1/slope, NOT gradient-with-floor).
    Points are clamped to [lo_frac, hi_frac]*|m_s_slope| for DISPLAY only so a single-frame
    s* jump (a tracking artifact) cannot paint a non-physical value; the returned array is
    for coloring, and the reported scalar speed remains the fit's m_s (unchanged)."""
    t = np.asarray(t_s, float); s = np.asarray(s_star_um, float)
    if t.size < 2:
        return np.zeros_like(t)
    w = max(2, int(win)); v = np.full(t.size, np.nan)
    for i in range(t.size):
        a = max(0, i - w // 2); b = min(t.size, a + w)
        if b - a >= 2 and np.ptp(t[a:b]) > 0:
            v[i] = np.polyfit(t[a:b], s[a:b], 1)[0]
    v = np.abs(v)                                      # magnitude for a speed map
    m = abs(float(m_s_slope))
    if m > 0:
        v = np.clip(v, lo_frac * m, hi_frac * m)       # DISPLAY clamp only
    v = np.nan_to_num(v, nan=m)
    return v.astype(np.float32)


def _nice_bar_length_um(ax, px_um, frac=0.2):
    """Pick a round scale-bar length (1/2/5 ×10^k µm) close to `frac` of the axes width."""
    xlo, xhi = ax.get_xlim(); W_um = abs(xhi - xlo) * float(px_um)
    import math
    target = max(1.0, frac * W_um)
    k = 10 ** math.floor(math.log10(target)); base = target / k
    nice = 1 if base < 2 else (2 if base < 5 else 5)
    return nice * k


def recon_velocity_from_arclength(res, fps, method='ransac', prom=0.0,
                                  thr=0.0, min_samples=3, max_trials=200):
    """LITERAL recon velocity for one interval, from `pulse_arclength_core` output.
    t = present/fps, s = s_star_um; keep columns with amp_at_star >= prom*max(amp) (prom=0 keeps
    all — the recon fit applies no prominence gate); fit s(t) with `_robust_line_fit`. FWHM is
    reported, not required. Returns slope/se/r2/inliers/keep/transport/direction and the arrays."""
    present = np.asarray(res.get('present', []), float)
    s = np.asarray(res.get('s_star_um', []), float)
    amp = np.asarray(res.get('amp_at_star', []), float)
    fps = float(fps)
    keep = np.zeros(present.size, bool)
    if present.size >= 2 and s.size == present.size:
        fin = np.isfinite(s)
        if amp.size == present.size and np.isfinite(amp).any() and prom and prom > 0:
            keep = fin & (amp >= float(prom) * float(np.nanmax(amp)))
        else:
            keep = fin
    t = present / max(fps, 1e-9)
    tk = t[keep]; sk = s[keep]; n_kept = int(keep.sum())
    slope = se = r2 = float('nan'); inl = np.zeros(present.size, bool); n_used = 0
    if n_kept >= 2:
        fit = _robust_line_fit(tk, sk, method=method, thr=thr,
                               min_samples=min_samples, max_trials=max_trials)
        slope = float(fit['slope']); r2 = float(fit['r2']); se = float(fit['se_slope'])
        im = np.asarray(fit['inliers'], bool); kidx = np.where(keep)[0]
        if kidx.size == im.size: inl[kidx[im]] = True
        n_used = int(im.sum())
    transport = float(sk[-1] - sk[0]) if n_kept >= 2 else float('nan')
    direction = ('antegrade' if (np.isfinite(slope) and slope > 0)
                 else ('retrograde' if np.isfinite(slope) else '-'))
    return dict(slope_um_s=slope, se=se, r2=r2, n_used=n_used, n_kept=n_kept,
                inliers=inl, keep=keep, t_keep=tk, s_keep=sk, direction=direction,
                transport_um=transport, s_star_um=s, amp=amp, fwhm=res.get('fwhm_um'),
                arclen_um=res.get('arclen_um'))


def build_pulse_results_doc(proj, intervals, cl, *, fps, px_um, N, band, diff, prom, fit,
                            frame_map, root=None, source_tiff='', image_shape=None,
                            normalization='as_in_tiff', drift_applied=None, sat=None,
                            tiff_sha1=''):
    """Single source for the recon->PulseFlow backup file. Runs the CANONICAL pipeline
    (`pulse_arclength_core` + `recon_velocity_from_arclength`) on each LOCAL interval, maps the
    present frames to ROOT via `frame_map`, and returns a `recon_pulse_v1` document.  Records the
    provenance the importer needs to avoid the five mismatch risks (shape/frame-map/normalization/
    drift/direction).  Does NOT modify the kernels."""
    proj = np.asarray(proj, np.float32); T = int(proj.shape[0])
    fm = np.asarray(frame_map, np.int64) if frame_map is not None else np.arange(T, np.int64)
    root_time_valid = bool(fm.size == T and not np.array_equal(fm, np.arange(T, dtype=np.int64)))
    cl = np.asarray(cl, float)
    bounds = list((root or {}).get('boundaries', [0, int((root or {}).get('T', T))])) or [0, T]
    out = []
    for k, (t0, t1) in enumerate(intervals):
        t0 = int(t0); t1 = int(t1)
        frames = list(range(t0, t1))
        res = pulse_arclength_core(proj, frames, cl, n_pts=int(N), band_px=int(band),
                                   pxu=float(px_um), mode=str(diff), sigma_xy=0.0, sat=sat)
        vel = recon_velocity_from_arclength(res, float(fps), method=str(fit), prom=float(prom))
        present = np.asarray(res.get('present', []), int)
        amp = np.asarray(res.get('amp_at_star', []), float)
        if present.size:
            tpk_local = int(present[int(np.nanargmax(amp))]) if np.isfinite(amp).any() else int(present[0])
        else:
            tpk_local = (t0 + t1) // 2
        def _r(i): return int(fm[int(np.clip(i, 0, fm.size - 1))])
        root_present = [ _r(i) for i in present.tolist() ]
        out.append(dict(
            idx=k, local_t0=t0, local_t1=t1, present_local=present.tolist(),
            present_root=root_present,
            root_t0=_r(t0), root_t1=_r(t1 - 1) + 1,
            t_peak_local=tpk_local, t_peak_root=_r(tpk_local),
            root_file=int(file_index(bounds, _r(tpk_local))),
            v_um_s=float(vel['slope_um_s']), se=float(vel['se']), r2=float(vel['r2']),
            n_used=int(vel['n_used']), n_kept=int(vel['n_kept']),
            direction=vel['direction'], transport_um=float(vel['transport_um']),
            s_star_um=np.asarray(res.get('s_star_um', []), float).tolist(),
            amp_at_star=amp.tolist(),
            fwhm_um=np.asarray(res.get('fwhm_um', []), float).tolist(),
            arclen_um=np.asarray(res.get('arclen_um', []), float).tolist()))
    return dict(
        schema='recon_pulse_v1', source_tiff=str(source_tiff), tiff_sha1=str(tiff_sha1),
        image_shape=list(image_shape or [int(proj.shape[1]), int(proj.shape[2])]),
        centerline=cl.tolist(), direction_convention='antegrade=+ along prox->dist',
        fps=float(fps), px_um=float(px_um), N=int(N), band=int(band), diff_mode=str(diff),
        prom=float(prom), fit=str(fit), sat_setting=('on' if sat is not None else 'off'),
        normalization=str(normalization),
        drift_applied=(bool(drift_applied) if drift_applied is not None else None),
        frame_map=fm.tolist(), root=root, root_time_valid=root_time_valid,
        intervals=out, n_intervals=len(out))


def pulse_results_to_rows(doc):
    """Convert a `recon_pulse_v1` document's intervals into rows in the SAME shape the Pulse Flow
    aggregation consumes (v_bolus/se/r2/t0_root/t1_root/t_peak_root/root_file/quality/has_fit).
    NO recomputation — the recon session already ran the literal pipeline."""
    rows = []
    for it in doc.get('intervals', []):
        v = it.get('v_um_s', float('nan')); r2 = it.get('r2', float('nan'))
        has_fit = bool(np.isfinite(v))
        passed = bool(has_fit and np.isfinite(r2) and r2 >= 0.5)
        rows.append(dict(
            idx=it.get('idx'), t0=it.get('local_t0'), t1=it.get('local_t1'),
            t0_root=it.get('root_t0'), t1_root=it.get('root_t1'), t_peak_root=it.get('t_peak_root'),
            root_file=it.get('root_file', 0), v_bolus=v, slope=v, se=it.get('se', float('nan')),
            r2=r2, n_gated=it.get('n_kept', 0), n_used=it.get('n_used', 0),
            direction=it.get('direction', '-'), transport_um=it.get('transport_um', float('nan')),
            has_fit=has_fit, passed=passed, quality=('PASS' if passed else 'LOW'),
            include=True, source='recon_import', uid='recon_import'))
    return rows


def bolus_profile_metrics(b_s, arclen_um):
    """Centroid (µm), FWHM width (µm), peak position (µm), total mass (sum)."""
    b = np.asarray(b_s, float); s = np.asarray(arclen_um, float)
    if b.size == 0 or not np.isfinite(b).any() or float(b.sum()) <= 0:
        return dict(centroid_s_um=float('nan'), width_um=float('nan'),
                    peak_s_um=float('nan'), total_mass=0.0, valid=False)
    centroid = float(np.sum(b * s) / np.sum(b))
    peak_i   = int(np.argmax(b))
    peak_s   = float(s[peak_i])
    # FWHM: linear-interp left/right crossings at half-max
    half = 0.5 * float(b[peak_i])
    above = b >= half
    if not above.any():
        width = float('nan')
    else:
        li = peak_i
        while li > 0 and above[li - 1]:
            li -= 1
        ri = peak_i
        while ri < b.size - 1 and above[ri + 1]:
            ri += 1
        # interp
        if li == 0:
            left_s = s[0]
        else:
            y0, y1 = b[li - 1], b[li]
            t = (half - y0) / (y1 - y0 + 1e-12)
            left_s = s[li - 1] + t * (s[li] - s[li - 1])
        if ri == b.size - 1:
            right_s = s[-1]
        else:
            y0, y1 = b[ri], b[ri + 1]
            t = (half - y0) / (y1 - y0 + 1e-12)
            right_s = s[ri] + t * (s[ri + 1] - s[ri])
        width = float(right_s - left_s)
    return dict(centroid_s_um=centroid, width_um=width, peak_s_um=peak_s,
                total_mass=float(np.sum(b)), valid=True)


class _Tooltip:
    """Lightweight hover tooltip for a Tk widget. Shows after `delay` ms, wraps at `wrap` px,
    follows the pointer, hides on <Leave>/<ButtonPress>/focus-out. One instance per widget;
    safe if the widget is destroyed. Uses a Toplevel with overrideredirect (no window chrome)."""
    def __init__(self, widget, textfn, delay=450, wrap=360):
        self.w = widget; self.textfn = textfn if callable(textfn) else (lambda: textfn)
        self.delay = delay; self.wrap = wrap; self.tip = None; self._after = None
        widget.bind("<Enter>", self._schedule, add="+")
        widget.bind("<Leave>", self._hide, add="+")
        widget.bind("<ButtonPress>", self._hide, add="+")
        widget.bind("<Motion>", self._move, add="+")

    def _schedule(self, _e=None):
        self._cancel()
        self._after = self.w.after(self.delay, self._show)

    def _show(self):
        try:
            txt = self.textfn()
        except Exception:
            txt = ""
        if not txt or self.tip is not None:
            return
        try:
            x = self.w.winfo_pointerx() + 14; y = self.w.winfo_pointery() + 18
        except Exception:
            return
        self.tip = tk.Toplevel(self.w); self.tip.wm_overrideredirect(True)
        try: self.tip.attributes("-topmost", True)
        except Exception: pass
        lbl = tk.Label(self.tip, text=txt, justify="left", wraplength=self.wrap,
                       background="#ffffe0", foreground="#111", relief="solid", borderwidth=1,
                       font=("Segoe UI", 8), padx=6, pady=4)
        lbl.pack(); self.tip.wm_geometry(f"+{x}+{y}")

    def _move(self, e=None):
        if self.tip is not None and e is not None:
            try: self.tip.wm_geometry(f"+{e.x_root + 14}+{e.y_root + 18}")
            except Exception: pass

    def _hide(self, _e=None):
        self._cancel()
        if self.tip is not None:
            try: self.tip.destroy()
            except Exception: pass
            self.tip = None

    def _cancel(self):
        if self._after is not None:
            try: self.w.after_cancel(self._after)
            except Exception: pass
            self._after = None


