        ttk.Button(btn_frame, text="💓 Lymphatic Pulse Analysis",
                   command=self._open_recon_pulse_analyzer).pack(side=tk.LEFT, padx=5)

        ttk.Button(btn_frame2, text="🧩 Stitch Tool",
                   command=self._open_stitch_tool).pack(side=tk.LEFT, padx=5)

        ttk.Separator(btn_frame2, orient=tk.VERTICAL).pack(side=tk.LEFT, fill=tk.Y, padx=8)

        ttk.Button(btn_frame2, text="🔇 Denoise",
                   command=self._open_denoise_gui).pack(side=tk.LEFT, padx=5)

        ttk.Separator(btn_frame2, orient=tk.VERTICAL).pack(side=tk.LEFT, fill=tk.Y, padx=8)

        ttk.Button(btn_frame2, text="📊 Pulse Flow Analyzer",
                   command=self._open_pulse_analyzer).pack(side=tk.LEFT, padx=5)

        # ── Log output ──
        log_frame = ttk.LabelFrame(self.root, text="Log")
        log_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)

        self.log_text = tk.Text(log_frame, height=15, wrap=tk.WORD,
                                font=('Consolas', 9))
        self.log_text.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

