        ttk.Label(_rf1, text="min prom:").pack(side=tk.LEFT, padx=(4, 1))
        _e = ttk.Entry(_rf1, textvariable=fit_min_prom_var, width=4)
        _e.pack(side=tk.LEFT); _add_tt(_e,
            "각 frame의 peak/max_b 최소 비율 — 이보다 약한 peak은 fit에서 제외")
        ttk.Label(_rf1, text="k·MAD:").pack(side=tk.LEFT, padx=(4, 1))
        _e = ttk.Entry(_rf1, textvariable=fit_kmad_var, width=4)
        _e.pack(side=tk.LEFT); _add_tt(_e,
            "peak ≥ median + k·MAD 조건 — 값이 클수록 잡음 배경 대비 강한 peak만 통과")
        _rf2 = ttk.Frame(pfdf); _rf2.pack(fill=tk.X, padx=4)
        ttk.Label(_rf2, text="RANSAC thr:").pack(side=tk.LEFT)
        _e = ttk.Entry(_rf2, textvariable=fit_ransac_thr_var, width=5)
        _e.pack(side=tk.LEFT); _add_tt(_e,
            "residual_threshold (µm). 0 = auto (2.5 · 1.4826 · MAD of OLS residuals)")
        ttk.Label(_rf2, text="min samples:").pack(side=tk.LEFT, padx=(4, 1))
        _e = ttk.Entry(_rf2, textvariable=fit_ransac_min_var, width=3)
        _e.pack(side=tk.LEFT); _add_tt(_e, "RANSAC min_samples")
        ttk.Label(_rf2, text="trials:").pack(side=tk.LEFT, padx=(4, 1))
        _e = ttk.Entry(_rf2, textvariable=fit_ransac_trials_var, width=5)
        _e.pack(side=tk.LEFT); _add_tt(_e, "RANSAC max_trials")
        _rf3 = ttk.Frame(pfdf); _rf3.pack(fill=tk.X, padx=4)
