        # ─────────────────────────── helpers (closures) ───────────────────────────
        def _rebuild_proj():
            import traceback as _tb
            try:
                mode = mode_var.get()
                if mode == 'slice':
                    st['z_sel'] = int(z_var.get())
                    z_lbl.config(text=f"{st['z_sel']}/{D-1}")
                    st['proj'] = _recon_proj_2d(vol, 'slice', z_sel=st['z_sel'])
                    status_v.set(f"Proj rebuilt: slice z={st['z_sel']}, shape {st['proj'].shape}")
                else:
                    z0 = max(0, min(int(z0_var.get()), D - 1))
                    z1 = max(z0, min(int(z1_var.get()), D - 1))
                    st['z0'], st['z1'] = z0, z1
                    st['proj'] = _recon_proj_2d(vol, 'mip', z_range=(z0, z1))
                    status_v.set(f"Proj rebuilt: MIP z=[{z0}..{z1}], shape {st['proj'].shape}")
                st['proj_mode'] = mode
                st['signal_bbox_cached'] = None          # MIP changed
                _redraw()
            except Exception as _e:
                self._log(f"[_rebuild_proj] FAILED:\n{_tb.format_exc()}")
                try:
                    status_v.set(f"Rebuild proj FAILED: {type(_e).__name__}: {_e}"[:180])
                except Exception: pass
                messagebox.showerror("Rebuild proj",
                    f"{type(_e).__name__}: {_e}\nSee log for full traceback.")

        def _auto_focus():
            # Restrict to polyline neighbourhood if drawn; else full frame
            mask = None
            if st['centerline'] is not None and len(st['centerline']) >= 2:
                from cv2 import fillPoly as _fp
                m = np.zeros((H, W), np.uint8)
                exp = _expand_line(st['centerline'], int(band_var.get()) * 2 + 1)
                if exp is not None:
                    _fp(m, [exp], 1)
                mask = m > 0
            z, scores = _auto_best_focus_depth(vol, mask=mask)
            z_var.set(z); z_lbl.config(text=f"{z}/{D-1}")
            mode_var.set('slice')
            _rebuild_proj()
            status_v.set(f"Auto best-focus z={z} (mask: {'ROI' if mask is not None else 'full'})")

        def _expand_line(pts, width):
            # local copy (so this helper does not depend on the outer tiff
            # analyzer's closure being open)
            if pts is None or len(pts) < 2: return None
            hw = max(1, int(width)) // 2
            upper, lower = [], []
            for i in range(len(pts) - 1):
                dx = pts[i + 1][0] - pts[i][0]; dy = pts[i + 1][1] - pts[i][1]
                L = float(np.hypot(dx, dy))
                if L == 0: continue
                nx, ny = -dy / L * hw, dx / L * hw
                upper.append([int(pts[i][0] + nx), int(pts[i][1] + ny)])
                lower.append([int(pts[i][0] - nx), int(pts[i][1] - ny)])
            if not upper: return None
            upper.append([int(pts[-1][0] + nx), int(pts[-1][1] + ny)])
            lower.append([int(pts[-1][0] - nx), int(pts[-1][1] - ny)])
            return np.array(upper + lower[::-1], dtype=np.int32)

        # NOTE: `MAX_LINES`, `LINE_COLORS`, `st['centerlines']`,
        # `st['active_line']`, `st['include_lines']`, and `_sync_active_line`
        # are all initialized UP-FRONT (right after the `st = {...}` dict
        # above), so every panel below can reference them safely.

        # ── canvas drawing / display ──
        def _start_draw():
            st['drawing'] = True; st['temp_pts'] = []
            status_v.set(f"Draw line {int(st.get('active_line',0))+1}: "
                          f"click points, double-click to finish")

        def _clear_polyline():
            a = int(st.get('active_line', 0))
            st['centerlines'][a] = None
            st['temp_pts'] = []
            st['signal_bbox_cached'] = None              # centerline removed
            _sync_active_line()
            _redraw()

        # ── Manual vessel-line pick (user defines the primary polyline) ──
        def _start_pick_vessel_line():
            st['picking_vessel'] = True
            st['manual_vessel_pts'] = []
            try:
                status_v.set("Set vessel line: click ≥2 points on the "
                             "canvas, double-click to finish.")
            except Exception: pass

        def _clear_manual_vessel_line():
            st['manual_vessel_pts'] = []
            st['manual_vessel_line'] = None
            st['picking_vessel'] = False
            try:
                status_v.set("Manual vessel line cleared.")
            except Exception: pass
            try: _redraw()
            except Exception: pass

        # ── Interactive align window: shows the SAME rendered struct_2d
        # background + live bolus preview.  Click ≥ 2 points along the
        # vessel; on Apply, stores the polyline as `st['manual_vessel_line']`
        # so the next render places the bolus by fraction on that line.
        # Shared safety wrapper: any callback that throws will log a full
        # traceback + surface a messagebox with the real exception, so
        # the Align window can NEVER silently vanish or misfire.
        def _align_safe(fn_name, fn, *args, **kwargs):
            import traceback as _tb
            try:
                return fn(*args, **kwargs)
            except Exception as _e:
                tb = _tb.format_exc()
                self._log(f"[align] {fn_name} FAIL:\n{tb}")
                try:
                    messagebox.showerror("Align",
                        f"{fn_name} failed:\n{type(_e).__name__}: {_e}\n\n"
                        f"See log for full traceback.")
                except Exception: pass
                return None

        def _open_align_on_rendered():
            import traceback as _tb
            # Wrap the ENTIRE body — including window creation, event
            # handlers, and finalization — so any exception surfaces as a
            # traceback log + messagebox instead of a silent vanish.
            win = None
            try:
                _open_align_on_rendered_impl_start = True
                from matplotlib.figure import Figure
                from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            except Exception as e:
                self._log(f"[align] matplotlib import failed:\n"
                          f"{_tb.format_exc()}")
                messagebox.showerror("Align",
                    f"matplotlib missing: {e}"); return
            # Bulletproof against a stale crop offset from a prior figure
            # so the main line the user draws here lands EXACTLY on the
            # final vessel in mip_bolus / velocity_map (no drift).
            st['_bosf_crop'] = (0, 0)
            # Self-sufficient: build line0 info in-window if a prior
            # "Show MIP + bolus" render hasn't cached it yet. Removes the
            # old "run first" gate so the align window opens directly.
            line0 = st.get('_bosf_line0_info')
            if not line0:
                try:
                    pk0 = _compute_pulse_arclength()
                    if (pk0 is None or not pk0.get('have_cl')
                            or len(pk0.get('present', [])) < 2):
                        messagebox.showwarning("Align",
                            "Need a centerline + ≥2 tracked pulse frames.\n"
                            "Draw the centerline and enter pulse frames in "
                            "the analyzer's left panel, then try again.")
                        return
                    _fps = float(fps_var.get())
                    line0 = dict(
                        s_star_um=np.asarray(pk0['s_star_um'],
                                             dtype=np.float32).copy(),
                        arclen_um=np.asarray(pk0['arclen_um'],
                                             dtype=np.float32).copy(),
                        t_s=np.asarray(
                            [f / max(_fps, 1e-9) for f in pk0['present']],
                            dtype=np.float32),
                        centers=np.asarray(pk0['centers'],
                                           dtype=np.float32).copy(),
                        m_s=0.0, b_s=0.0,
                    )
                    st['_bosf_line0_info'] = line0
                    self._log("[align] built _bosf_line0_info in-window "
                              "(no prior mip_bolus render needed)")
                except Exception as _e_l0:
                    self._log(f"[align] line0 build failed: {_e_l0}\n"
                              f"{_tb.format_exc()}")
                    messagebox.showwarning("Align",
                        f"Could not build line info: {_e_l0}"); return
            # ── SAVE the segmented bolus movement (pattern) so it can be
            # replayed along ANY user-drawn line. Pure movement pattern =
            # normalized arclength fraction f(t) = (s*(t)−s0)/(s1−s0) over
            # the tracked times t_s. Decoupled from any polyline geometry.
            try:
                _al_min0 = float(line0['arclen_um'][0])
                _al_span0 = max(1e-6, float(line0['arclen_um'][-1]
                                             - line0['arclen_um'][0]))
                _f_t0 = np.clip((line0['s_star_um'] - _al_min0)
                                / _al_span0, 0.0, 1.0).astype(np.float32)
                st['saved_bolus_movement'] = dict(
                    t_s=np.asarray(line0['t_s'],
                                   dtype=np.float32).copy(),
                    f_t=_f_t0.copy(),
                    n=int(_f_t0.size))
                self._log(f"[align] saved_bolus_movement stored "
                          f"({_f_t0.size} samples; f range "
                          f"[{float(_f_t0.min()):.3f}, "
                          f"{float(_f_t0.max()):.3f}])")
            except Exception as _e_sm:
                self._log(f"[align] saved_bolus_movement store failed: "
                          f"{_e_sm}")
            paths = st.get('vessel_paths') or []
            # Rebuild struct_2d matching what mip_bolus draws.
            try:
                mask, agg01 = _compute_structure_mask()
            except Exception as e:
                self._log(f"[align] mask failed:\n{_tb.format_exc()}")
                messagebox.showwarning("Align",
                    f"Cannot compute mask: {e}"); return
            try:
                agg01_disp = _smoothed_structure(agg01)
            except Exception as e:
                self._log(f"[align] smoothed_structure failed:\n"
                          f"{_tb.format_exc()}")
                messagebox.showwarning("Align",
                    f"Smoothed structure failed: {e}"); return
            # DISABLED: single full-frame coordinate system for align window
            # + montage — no crop offset possible.
            mask_c = mask; agg_c = agg01_disp
            x0_use = 0; y0_use = 0
            # Force rebuild for THIS frame so we render the same tube
            # `_render_mip_bolus` will show.
            st['vessel_paths'] = None
            st['_vessel_paths_shape'] = None
            try:
                struct_2d = _thickened_skeleton_rgb(
                    agg_c, mask_c,
                    mip_struct_hue_var.get(),
                    alpha=float(struct_alpha_var.get()))
            except Exception as e:
                self._log(f"[align] struct render failed:\n{_tb.format_exc()}")
                messagebox.showwarning("Align",
                    f"Could not render struct: {e}"); return
            if struct_2d is None:
                # Never leave the window with no background: fall back to
                # the smoothed grayscale so the user can still draw.
                self._log("[align] struct_2d is None — falling back to "
                          "grayscale background so the window still opens.")
                _g = np.clip(agg_c, 0.0, 1.0).astype(np.float32)
                struct_2d = np.stack([_g, _g, _g], axis=2)

            # Wrap window build + interactive setup so any error is
            # captured. `win` is nonlocal-visible to the outer function
            # scope so we can destroy it on hard failure if needed.
            try:
                win = tk.Toplevel(pw)
                win.title("Align bolus on rendered image")
                win.geometry("880x900")
                # Keep the window on top of the analyzer so it can never
                # be hidden behind a re-focused parent (which some users
                # perceive as the window "vanishing").
                try: win.transient(pw)
                except Exception: pass
                try: win.lift()
                except Exception: pass
                bot = ttk.Frame(win); bot.pack(side=tk.BOTTOM, fill=tk.X,
                                                 padx=3, pady=2)
                # Persistent error strip at the top of `bot` for callback
                # exceptions (populated by _align_safe wrappers).
                err_var = tk.StringVar(value="")
                err_lbl = tk.Label(bot, textvariable=err_var,
                                   fg='#c00000',
                                   font=('TkDefaultFont', 8, 'italic'),
                                   wraplength=780, justify=tk.LEFT)
                err_lbl.pack(side=tk.TOP, fill=tk.X, padx=2, pady=(0, 2))
                fig = Figure(figsize=(7.0, 7.0), dpi=110,
                              facecolor='white',
                              constrained_layout=True)
                ax = fig.add_subplot(111)
                ax.imshow(struct_2d, interpolation='nearest')
                ax.set_xticks([]); ax.set_yticks([])
                for s_ in ax.spines.values(): s_.set_visible(False)
                ax.set_title(
                    "Click / brush ≥ 2 points along the LONG STRAIGHT vessel "
                    "— saved bolus movement replays along your drawn line.",
                    fontsize=8)
                canvas = FigureCanvasTkAgg(fig, master=win)
                canvas.get_tk_widget().pack(side=tk.TOP, fill=tk.BOTH,
                                              expand=True)
            except Exception as _e_build:
                self._log(f"[align] window build failed:\n"
                          f"{_tb.format_exc()}")
                messagebox.showerror("Align",
                    f"Window build failed:\n"
                    f"{type(_e_build).__name__}: {_e_build}\n\n"
                    f"See log for full traceback.")
                try:
                    if win is not None: win.destroy()
                except Exception: pass
                return
            # Tracked arclength for live bolus preview. Guard against
            # missing/malformed line0 fields so the window still opens
            # with a usable canvas.
            try:
                s_star_um = np.asarray(line0['s_star_um'],
                                       dtype=np.float32)
                arclen_um = np.asarray(line0['arclen_um'],
                                       dtype=np.float32)
                al_min = float(arclen_um[0])
                al_span = max(1e-6,
                              float(arclen_um[-1] - arclen_um[0]))
            except Exception as _e_tr:
                self._log(f"[align] arclen prep failed: {_e_tr}\n"
                          f"{_tb.format_exc()}")
                err_var.set(f"[warn] arclen prep failed: {_e_tr}")
                s_star_um = np.zeros(0, dtype=np.float32)
                arclen_um = np.zeros(0, dtype=np.float32)
                al_min = 0.0; al_span = 1.0
            # ── EXTRACTED bolus movement (cyan): tracked s*(t) mapped
            # ONTO the drawn centerline's (x, y) via arclength lookup.
            try:
                _centers = line0.get('centers')
                _centers = (np.asarray(_centers, dtype=np.float32)
                            if _centers is not None else None)
                if (_centers is not None and _centers.shape[0] >= 2
                        and arclen_um.size == _centers.shape[0]):
                    _bxs, _bys = [], []
                    for _sv in s_star_um:
                        _ii = int(np.argmin(np.abs(arclen_um
                                                    - float(_sv))))
                        _bxs.append(float(_centers[_ii, 0]))
                        _bys.append(float(_centers[_ii, 1]))
                    ax.plot(_bxs, _bys, 'o', color='#00d0ff', ms=6,
                            mec='k', mew=0.5, alpha=0.85,
                            label='saved bolus movement')
            except Exception as _e_cy:
                self._log(f"[align] cyan overlay skipped: {_e_cy}")
                err_var.set(f"[warn] saved-movement overlay skipped: "
                            f"{_e_cy}")
            # Also draw the CURRENT rendered-polyline bolus trajectory if
            # a prior render cached vessel_paths — helps see the delta
            # between rendered-line placement and the extracted movement.
            try:
                if paths:
                    _pp0 = paths[0]
                    _dp = np.diff(_pp0, axis=0)
                    _sg = np.hypot(_dp[:, 0], _dp[:, 1])
                    _ar = np.concatenate([[0.0], np.cumsum(_sg)])
                    _total0 = float(_ar[-1])
                    if _total0 > 0:
                        _f0 = np.clip((s_star_um - al_min) / al_span,
                                      0.0, 1.0)
                        _cur_x = np.interp(_f0 * _total0, _ar,
                                            _pp0[:, 0])
                        _cur_y = np.interp(_f0 * _total0, _ar,
                                            _pp0[:, 1])
                        ax.plot(_cur_x, _cur_y, 'x', color='#999999',
                                ms=5, mew=1.0, alpha=0.55,
                                label='current bolus (rendered line)')
            except Exception as _e_cur:
                self._log(f"[align] current-bolus overlay skipped: "
                          f"{_e_cur}")
            try:
                ax.legend(loc='upper right', fontsize=6, frameon=False)
                canvas.draw_idle()
            except Exception: pass
            clicked = {'pts': [], 'poly_h': [], 'bolus_h': [],
                       'brush': False}

            def _refresh_impl():
                for h in clicked['poly_h']:
                    try: h.remove()
                    except Exception: pass
                clicked['poly_h'] = []
                for h in clicked['bolus_h']:
                    try: h.remove()
                    except Exception: pass
                clicked['bolus_h'] = []
                pts = clicked['pts']
                if pts:
                    xs_ = [p[0] for p in pts]
                    ys_ = [p[1] for p in pts]
                    h1, = ax.plot(xs_, ys_, 'o-', color='#ffe08a',
                                    ms=6, lw=1.5, mec='k', mew=0.5,
                                    zorder=3, label='drawn polyline')
                    clicked['poly_h'].append(h1)
                if len(pts) >= 2:
                    poly = np.asarray(pts, dtype=np.float32)
                    d = np.diff(poly, axis=0)
                    seg = np.hypot(d[:, 0], d[:, 1])
                    arc = np.concatenate([[0.0], np.cumsum(seg)])
                    total = float(arc[-1])
                    if total > 0:
                        # Replay saved bolus movement along drawn line.
                        sm = st.get('saved_bolus_movement')
                        if sm is not None and sm.get('f_t') is not None \
                                and sm.get('f_t').size >= 1:
                            f = np.asarray(sm['f_t'], dtype=np.float32)
                        else:
                            f = np.clip((s_star_um - al_min) / al_span,
                                         0.0, 1.0)
                        s_t = f * total
                        bxs = np.interp(s_t, arc, poly[:, 0])
                        bys = np.interp(s_t, arc, poly[:, 1])
                        h2, = ax.plot(bxs, bys, 'o', color='red',
                                        ms=6, mec='k', mew=0.5, zorder=4,
                                        label='bolus replay on drawn line')
                        clicked['bolus_h'].append(h2)
                canvas.draw_idle()

            def _refresh():
                _align_safe("refresh", _refresh_impl)

            # Track a dragged point across press → motion → release.
            drag_state = {'idx': None, 'grab_thr': 12.0}
            def _on_press_impl(evt):
                if evt.inaxes is not ax or evt.button != 1: return
                if evt.xdata is None or evt.ydata is None: return
                # Brush mode: shift-click starts a freehand stroke that
                # appends points on every motion sample.
                try:
                    key_shift = bool(getattr(evt, 'key', None)
                                     and 'shift' in evt.key)
                except Exception: key_shift = False
                if key_shift:
                    clicked['brush'] = True
                    clicked['pts'].append((float(evt.xdata),
                                            float(evt.ydata)))
                    _refresh(); return
                # If a click lands near an existing point, START DRAG.
                if clicked['pts']:
                    ex, ey = float(evt.xdata), float(evt.ydata)
                    pts_arr = np.asarray(clicked['pts'],
                                          dtype=np.float32)
                    d2 = ((pts_arr[:, 0] - ex) ** 2
                            + (pts_arr[:, 1] - ey) ** 2)
                    i_near = int(np.argmin(d2))
                    if float(np.sqrt(d2[i_near])) <= drag_state['grab_thr']:
                        drag_state['idx'] = i_near
                        return
                # Else: APPEND new point.
                clicked['pts'].append((float(evt.xdata),
                                          float(evt.ydata)))
                _refresh()
            def _on_press(evt):
                _align_safe("on_press", _on_press_impl, evt)

            def _on_motion_impl(evt):
                if evt.inaxes is not ax: return
                if evt.xdata is None or evt.ydata is None: return
                if clicked['brush']:
                    # Sparse-sample the brush so we don't accumulate 1000
                    # points; drop samples closer than 3 px from the last.
                    if clicked['pts']:
                        _lx, _ly = clicked['pts'][-1]
                        if (float(evt.xdata) - _lx) ** 2 \
                                + (float(evt.ydata) - _ly) ** 2 < 9.0:
                            return
                    clicked['pts'].append((float(evt.xdata),
                                            float(evt.ydata)))
                    _refresh(); return
                if drag_state['idx'] is None: return
                i = drag_state['idx']
                clicked['pts'][i] = (float(evt.xdata),
                                        float(evt.ydata))
                _refresh()
            def _on_motion(evt):
                _align_safe("on_motion", _on_motion_impl, evt)

            def _on_release_impl(evt):
                drag_state['idx'] = None
                clicked['brush'] = False
            def _on_release(evt):
                _align_safe("on_release", _on_release_impl, evt)

            try:
                fig.canvas.mpl_connect('button_press_event', _on_press)
                fig.canvas.mpl_connect('motion_notify_event', _on_motion)
                fig.canvas.mpl_connect('button_release_event', _on_release)
            except Exception as _e_conn:
                self._log(f"[align] mpl connect failed: {_e_conn}")
                err_var.set(f"[warn] mouse events unbound: {_e_conn}")

            def _undo_impl():
                if clicked['pts']: clicked['pts'].pop()
                _refresh()
            def _undo(): _align_safe("undo", _undo_impl)
            def _clr_impl():
                clicked['pts'] = []
                _refresh()
            def _clr(): _align_safe("clear", _clr_impl)
            def _apply_impl():
                if len(clicked['pts']) < 2:
                    messagebox.showwarning("Align",
                        "Click ≥ 2 points before Apply."); return
                arr = np.array(
                    [[p[0] + x0_use, p[1] + y0_use]
                     for p in clicked['pts']], dtype=np.float32)
                st['manual_vessel_line'] = arr
                self._log(f"[align] user aligned bolus on rendered image "
                          f"({len(arr)} pts, render-frame origin="
                          f"({x0_use},{y0_use}))")
                st['vessel_paths'] = None
                st['_vessel_paths_shape'] = None
                win.destroy()
            def _apply(): _align_safe("apply", _apply_impl)
            try:
                ttk.Button(bot, text="Undo point",
                            command=_undo).pack(side=tk.LEFT, padx=2)
                ttk.Button(bot, text="Clear",
                            command=_clr).pack(side=tk.LEFT, padx=2)
                tk.Label(bot, text="(hold Shift to brush)",
                          font=('TkDefaultFont', 8),
                          fg='#666').pack(side=tk.LEFT, padx=6)
                ttk.Button(bot, text="Apply",
                            command=_apply).pack(side=tk.RIGHT, padx=2)
                ttk.Button(bot, text="Cancel",
                            command=win.destroy).pack(side=tk.RIGHT,
                                                         padx=2)
            except Exception as _e_btn:
                self._log(f"[align] button build failed:\n"
                          f"{_tb.format_exc()}")
                err_var.set(f"[warn] buttons unavailable: {_e_btn}")

        def _on_frame(_v):
            st['current_t'] = int(t_var.get())
            t_lbl.config(text=f"t = {st['current_t']}/{T-1}  ({st['current_t']/fps_var.get():.3f} s)")
            _redraw()

        # ── DISPLAY-ONLY view transform ────────────────────────────────────
        # crop_box (in image-pixel coords) + per-axis flips + uniform zoom
        # scale + canvas pan offset map IMAGE pixels <-> CANVAS pixels both
        # forward and inverse. Centerline storage is always in the ORIGINAL
        # image-pixel frame, so picks/clicks while zoomed/cropped remain
        # consistent with unzoomed clicks (round-trip identity below).
        def _signal_bbox():
            """Return (x0, y0, x1, y1) tight bbox of the signal with a small
            margin. Prefer the user's centerline bbox when drawn; else use a
            percentile-thresholded time-MIP. Cached on st."""
            cached = st.get('signal_bbox_cached')
            if cached is not None:
                return cached
            cl = st.get('centerline')
            if cl is not None and len(cl) >= 2:
                cl = np.asarray(cl)
                margin = max(12, int(0.05 * max(int(W), int(H))))
                x0 = max(0, int(np.min(cl[:, 0])) - margin)
                x1 = min(int(W), int(np.max(cl[:, 0])) + margin + 1)
                y0 = max(0, int(np.min(cl[:, 1])) - margin)
                y1 = min(int(H), int(np.max(cl[:, 1])) + margin + 1)
            else:
                # Threshold the time-MIP. Robust percentile floor/ceiling.
                if st.get('proj') is None:
                    return (0, 0, int(W), int(H))
                mip = st['proj'].max(axis=0)
                v_lo = float(np.percentile(mip, 5.0))
                v_hi = float(np.percentile(mip, 99.0))
                thr = v_lo + 0.30 * max(v_hi - v_lo, 1e-9)
                m = mip > thr
                if not m.any():
                    return (0, 0, int(W), int(H))
                ys, xs = np.where(m)
                margin = max(12, int(0.05 * max(int(W), int(H))))
                x0 = max(0, int(xs.min()) - margin)
                x1 = min(int(W), int(xs.max()) + margin + 1)
                y0 = max(0, int(ys.min()) - margin)
                y1 = min(int(H), int(ys.max()) + margin + 1)
            if x1 - x0 < 8 or y1 - y0 < 8:               # degenerate
                return (0, 0, int(W), int(H))
            st['signal_bbox_cached'] = (x0, y0, x1, y1)
            return st['signal_bbox_cached']

        def _img_to_canvas(x_img, y_img):
            """Forward map: original-image pixel (x, y) -> canvas pixel.
            Uses the actual on-canvas rendering origin (which already accounts
            for centring vs pan), so the inverse is exact regardless of the
            current centring/pan branch chosen in _redraw."""
            x0, y0, x1, y1 = st['crop_box']
            cw_i, ch_i = max(x1 - x0, 1), max(y1 - y0, 1)
            x = float(x_img) - x0
            y = float(y_img) - y0
            if flip_h_var.get(): x = (cw_i - 1) - x
            if flip_v_var.get(): y = (ch_i - 1) - y
            s = float(st.get('zoom', 1.0))
            ox, oy = st.get('_render_origin', (0, 0))
            return (x * s + ox, y * s + oy)

        def _canvas_to_img(cx, cy):
            """Inverse map: canvas pixel -> original-image pixel (x, y)."""
            x0, y0, x1, y1 = st['crop_box']
            cw_i, ch_i = max(x1 - x0, 1), max(y1 - y0, 1)
            s = max(float(st.get('zoom', 1.0)), 1e-9)
            ox, oy = st.get('_render_origin', (0, 0))
            x = (float(cx) - ox) / s
            y = (float(cy) - oy) / s
            if flip_h_var.get(): x = (cw_i - 1) - x
            if flip_v_var.get(): y = (ch_i - 1) - y
            return (x + x0, y + y0)

        def _canvas_click(event):
            if st['drawing']:
                x_i, y_i = _canvas_to_img(event.x, event.y)
                st['temp_pts'].append([int(round(x_i)), int(round(y_i))])
                _redraw()
                return
            if st.get('picking_vessel', False):
                x_i, y_i = _canvas_to_img(event.x, event.y)
                st['manual_vessel_pts'].append(
                    [int(round(x_i)), int(round(y_i))])
                try:
                    status_v.set(f"Vessel line: {len(st['manual_vessel_pts'])} "
                                 f"point(s) picked. Double-click to finish.")
                except Exception: pass
                _redraw()
                return
            if demo_pick_mode.get('on', False):
                x_i, y_i = _canvas_to_img(event.x, event.y)
                demo_x0_var.set(int(round(x_i)))
                demo_y0_var.set(int(round(y_i)))
                demo_pick_mode['on'] = False
                status_v.set(f"Demotion feature point set to ({int(round(x_i))}, {int(round(y_i))}).")
                _redraw()
                return
            # Not drawing → start B1 pan-drag.
            st['_pan_start'] = (event.x, event.y, int(st['pan_x']), int(st['pan_y']))

        def _canvas_drag(event):
            if st['drawing']:                            # don't pan while drawing
                return
            start = st.get('_pan_start')
            if not start:
                return
            sx, sy, px, py = start
            st['pan_x'] = int(px + (event.x - sx))
            st['pan_y'] = int(py + (event.y - sy))
            _redraw()

        def _canvas_release(_event):
            st.pop('_pan_start', None)

        def _canvas_dblclick(_event):
            # Vessel-line pick mode takes priority when active.
            if st.get('picking_vessel', False):
                if len(st['manual_vessel_pts']) >= 2:
                    arr = np.array(st['manual_vessel_pts'],
                                     dtype=np.float32)
                    st['manual_vessel_line'] = arr
                    try:
                        status_v.set(f"Manual vessel line saved: "
                                     f"{len(arr)} pts.")
                    except Exception: pass
                st['picking_vessel'] = False
                st['manual_vessel_pts'] = []
                _redraw()
                return
            if not st['drawing']: return
            if len(st['temp_pts']) >= 2:
                a = int(st.get('active_line', 0))
                arr = np.array(st['temp_pts'], dtype=np.int32)
                st['centerlines'][a] = arr
                _sync_active_line()
                status_v.set(f"Line {a+1} saved: {len(arr)} pts")
                st['signal_bbox_cached'] = None          # centerline changed
            st['drawing'] = False; st['temp_pts'] = []
            _redraw()

        def _canvas_wheel(event):
            mul = 1.10 if event.delta > 0 else (1.0 / 1.10)
            view_zoom_var.set(max(0.25, min(8.0, float(view_zoom_var.get()) * mul)))
            _redraw()

        canvas.bind('<Button-1>',         _canvas_click)
        canvas.bind('<B1-Motion>',        _canvas_drag)
        canvas.bind('<ButtonRelease-1>',  _canvas_release)
        canvas.bind('<Double-Button-1>',  _canvas_dblclick)
        canvas.bind('<MouseWheel>',       _canvas_wheel)

        def _redraw():
            import traceback as _tb
            try:
                _redraw_inner()
            except Exception as _e:
                self._log(f"[_redraw] FAILED:\n{_tb.format_exc()}")
                try:
                    status_v.set(f"Redraw FAILED: {type(_e).__name__}: {_e}"[:180])
                except Exception: pass

        def _redraw_inner():
            if st['proj'] is None:
                return
            t = st['current_t']
            img = _display_frame(t)                     # honors "Apply enhancement"
            vmin, vmax = float(np.nanmin(img)), float(np.nanmax(img))
            arr = np.clip((img - vmin) / (vmax - vmin + 1e-9), 0, 1)
            # Saturation overlay (cyan tint) — paints sat pixels for QC.
            sat_rgb = None
            if sat_overlay_var.get() and st.get('proj') is not None:
                try:
                    sat = _ensure_sat()
                    sat_t = sat[min(int(t), sat.shape[0] - 1)]
                    if sat_t.any():
                        sat_rgb = sat_t
                except Exception as _e:
                    self._log(f"[bolus] sat overlay skipped: {_e}")
            # ── crop to signal bbox if "Fit to signal" is on (DISPLAY ONLY) ──
            if fit_signal_var.get():
                bx0, by0, bx1, by1 = _signal_bbox()
            else:
                bx0, by0, bx1, by1 = 0, 0, int(W), int(H)
            st['crop_box'] = (bx0, by0, bx1, by1)
            arr = arr[by0:by1, bx0:bx1]
            if sat_rgb is not None:
                sat_rgb = sat_rgb[by0:by1, bx0:bx1]
            # Flips (apply to the CROPPED frame)
            if flip_h_var.get():
                arr = arr[:, ::-1]
                if sat_rgb is not None: sat_rgb = sat_rgb[:, ::-1]
            if flip_v_var.get():
                arr = arr[::-1, :]
                if sat_rgb is not None: sat_rgb = sat_rgb[::-1, :]
            if sat_rgb is None:
                arr_u8 = (arr * 255).astype(np.uint8)
                pil = Image.fromarray(arr_u8, mode='L')
            else:
                base = (arr * 255).astype(np.uint8)
                rgb = np.stack([base, base, base], axis=-1)
                rgb_f = rgb.astype(np.float32)
                cyan = np.array([0, 220, 255], np.float32)
                m = sat_rgb.astype(np.float32)[..., None]
                rgb_f = rgb_f * (1 - 0.4 * m) + cyan * (0.4 * m)
                pil = Image.fromarray(np.clip(rgb_f, 0, 255).astype(np.uint8), mode='RGB')
            # ── effective scale: fit-to-canvas × user view_zoom ──
            cw = max(50, int(canvas.winfo_width()))
            ch = max(50, int(canvas.winfo_height()))
            crop_w, crop_h = max(arr.shape[1], 1), max(arr.shape[0], 1)
            fit_scale = min(cw / crop_w, ch / crop_h)
            view_zoom = max(0.25, min(8.0, float(view_zoom_var.get())))
            eff = max(0.05, fit_scale * view_zoom)
            st['zoom'] = eff
            zw = max(1, int(round(crop_w * eff)))
            zh = max(1, int(round(crop_h * eff)))
            pil = pil.resize((zw, zh), Image.LANCZOS)
            tkimg = ImageTk.PhotoImage(pil)
            canvas.delete('all')
            # Centre when image is smaller than canvas; else apply pan offset.
            base_x = max(0, (cw - zw) // 2)
            base_y = max(0, (ch - zh) // 2)
            ox = base_x + (st['pan_x'] if zw > cw else 0)
            oy = base_y + (st['pan_y'] if zh > ch else 0)
            # If image is smaller than canvas, we want pan to still be allowed
            # for the user but anchored at centre; in that case ignore pan
            # (offset = base). Otherwise just translate by the pan delta.
            if zw > cw:
                ox = max(min(0, st['pan_x']), cw - zw)
            if zh > ch:
                oy = max(min(0, st['pan_y']), ch - zh)
            canvas.create_image(int(ox), int(oy), anchor='nw', image=tkimg)
            # Save the rendering origin so overlays use the same anchor.
            st['_render_origin'] = (int(ox), int(oy))
            tk_img_ref[0] = tkimg
            view_status_var.set(
                f"zoom = {view_zoom:.2f}×   eff = {eff:.2f}×"
                + (f"   crop = {crop_w}×{crop_h}" if fit_signal_var.get() else "")
            )
            # overlays in CANVAS coords via the forward-transform helper.
            # _img_to_canvas reads st['_render_origin'] which is the actual
            # on-canvas image origin (centred or pan-clamped), so overlays
            # land exactly on the image in any view state.
            def _disp(p):
                return _img_to_canvas(p[0], p[1])
            # in-progress polyline
            if st['temp_pts']:
                for p in st['temp_pts']:
                    dx, dy = _disp(p)
                    canvas.create_oval(dx - 3, dy - 3, dx + 3, dy + 3,
                                       outline='yellow', width=1)
                for i in range(len(st['temp_pts']) - 1):
                    x0, y0 = _disp(st['temp_pts'][i])
                    x1, y1 = _disp(st['temp_pts'][i + 1])
                    canvas.create_line(x0, y0, x1, y1, fill='yellow', width=2)
            # Draw the OTHER defined lines (non-active) faintly first so the
            # active line overlays on top. Colors come from LINE_COLORS.
            _a = int(st.get('active_line', 0))
            for _li in range(MAX_LINES):
                if _li == _a: continue
                _pts_o = st['centerlines'][_li]
                if _pts_o is None or len(_pts_o) < 2: continue
                _col_o = LINE_COLORS[_li]
                for i in range(len(_pts_o) - 1):
                    x0, y0 = _disp(_pts_o[i]); x1, y1 = _disp(_pts_o[i + 1])
                    canvas.create_line(x0, y0, x1, y1, fill=_col_o, width=1,
                                        dash=(3, 3))
            # final polyline + N sample points + transverse profile rails
            if st['centerline'] is not None and len(st['centerline']) >= 2:
                pts = st['centerline']
                # Active-line color: kept as legacy red when line 1 is
                # active so single-line workflows look identical; otherwise
                # use the slot's assigned Okabe-Ito color.
                _act_col = '#ff5050' if _a == 0 else LINE_COLORS[_a]
                for i in range(len(pts) - 1):
                    x0, y0 = _disp(pts[i]); x1, y1 = _disp(pts[i + 1])
                    canvas.create_line(x0, y0, x1, y1, fill=_act_col, width=2)
                centers, tangents, arclen = _sample_along_polyline(pts, int(n_pts_var.get()))
                if centers is not None:
                    L = float(prof_len_var.get())
                    for c, tg in zip(centers, tangents):
                        cx, cy = _disp(c)
                        canvas.create_oval(cx - 3, cy - 3, cx + 3, cy + 3,
                                           outline='#00d2ff', width=1)
                        # perpendicular rail
                        px, py = -tg[1], tg[0]
                        rx0, ry0 = _disp(c + np.array([px, py]) * (L / 2.0))
                        rx1, ry1 = _disp(c - np.array([px, py]) * (L / 2.0))
                        canvas.create_line(rx0, ry0, rx1, ry1,
                                           fill='#00d2ff', width=1)

        # (MOTION pipeline helpers removed — superseded by Demotion (SWiFT-IR).
        # _invalidate_correction / _detect_motion / _show_motion_window /
        # _update_exclusion / _centerline_bbox / _resolve_ref_idx all dropped.
        # The two surviving callers, _corrected_proj() and _apply_exclusion(),
        # have been REWIRED to read Demotion + the manual deleted_frames set.)

        # (RESPIRATION breathing-removal helpers removed — auto frequency-
        # domain breathing removal abandoned. _resp_input_proj /
        # _resp_params_key / _resp_surrogate_args / _detect_breathing_peak /
        # _resolve_f_fund / _apply_resp_removal / _fig_resp_spectrum /
        # _resp_cleaned_proj all dropped together with their panel.)
        # ── BOLUS DYNAMICS helpers (only shared utilities kept) ───────────
        # _bolus_d_params_key / _bolus_flow_params_key / _invalidate_bolus_caches
        # / _ensure_D / _ensure_flow have been removed with the Bolus Dynamics
        # panel. The kept _bolus_proj / _ensure_sat / _reload_pctiles /
        # _raw_histogram are shared utilities used by other code paths
        # (canvas saturation overlay, manual pulse-differential, etc.).
        def _bolus_proj():
            """Working stack for bolus dynamics. Uses the MEASUREMENT basis
            (motion-corrected + linear+BG if recon_enhance is synced). When the
            user selects the 'linear' data path, the analyzer's underlying
            recon_volume has already been reloaded with the chosen pctiles;
            the same _proj_for_measurement() pipeline produces the linear
            stack as a side effect (st['_basis'] tracks which basis is in use)."""
            return _proj_for_measurement()

        def _ensure_sat():
            """Recompute saturation only when params change."""
            key = (path_mode_var.get(), sat_mode_var.get(), float(sat_pct_var.get()))
            if (st['sat_mask_THW'] is not None and
                    st.get('_sat_key') == key):
                return st['sat_mask_THW']
            proj = _bolus_proj()
            sat, per_f, total = detect_saturation(proj, mode=sat_mode_var.get(),
                                                    pct=float(sat_pct_var.get()))
            st['sat_mask_THW'] = sat; st['_sat_key'] = key
            st['sat_total_frac'] = float(total)
            sat_status_var.set(
                f"saturated: total {total*100:.2f}%, "
                f"per-frame peak {float(per_f.max())*100:.2f}%  ({proj.shape[0]} frames)")
            return sat

        def _reload_pctiles():
            """Pop a small dialog asking for (pct_lo, pct_hi); default 0/100."""
            top = tk.Toplevel(pw); top.title("Reload .mat with custom pctiles")
            top.geometry("440x180")
            ttk.Label(top, text="Re-load the same .mat file with new clip percentiles.\n"
                      "Default (0.0, 100.0) keeps every raw value — useful when bolus\n"
                      "interiors are being clipped at the top by the default 99.9 pct.",
                       wraplength=420, justify='left').pack(padx=10, pady=6)
            rr = ttk.Frame(top); rr.pack(fill=tk.X, padx=10, pady=4)
            ttk.Label(rr, text="pct_lo:").pack(side=tk.LEFT)
            plo = tk.DoubleVar(value=0.0)
            ttk.Entry(rr, textvariable=plo, width=8).pack(side=tk.LEFT, padx=4)
            ttk.Label(rr, text="pct_hi:").pack(side=tk.LEFT, padx=(10, 0))
            phi = tk.DoubleVar(value=100.0)
            ttk.Entry(rr, textvariable=phi, width=8).pack(side=tk.LEFT, padx=4)
            cur = getattr(self, 'recon_clip_pct_lo', 0.5), getattr(self, 'recon_clip_pct_hi', 99.9)
            ttk.Label(top, text=f"Current: pct=({cur[0]:.3f}, {cur[1]:.3f}); raw="
                      f"{getattr(self, 'recon_raw_min', '?')}.."
                      f"{getattr(self, 'recon_raw_max', '?')}; "
                      f"dtype={getattr(self, 'recon_raw_dtype', '?')}.",
                       font=('TkDefaultFont', 8), wraplength=420,
                       foreground='#555').pack(fill=tk.X, padx=10)
            def _go():
                ok = self._reload_with_pctiles(float(plo.get()), float(phi.get()))
                if ok:
                    path_mode_var.set('linear')
                    # invalidate everything that derived from the old volume
                    st['proj'] = None
                    st['sat_mask_THW'] = None     # _ensure_sat will recompute
                    st['proj_demotion'] = None    # demotion cache (if any)
                    _rebuild_proj()
                    self._log("[bolus] reload complete; analyzer rebuilt from new volume.")
                top.destroy()
            ttk.Button(top, text="Reload", command=_go).pack(side=tk.RIGHT, padx=10, pady=6)
            ttk.Button(top, text="Cancel", command=top.destroy).pack(side=tk.RIGHT, padx=4, pady=6)

        def _raw_histogram():
            """Re-read raw values from self.recon_mat_path (downsampled) and
            plot their histogram with sensor-ceiling + clip markers."""
            path = getattr(self, 'recon_mat_path', None) or self.recon_mat_var.get()
            if not path or not os.path.exists(path):
                messagebox.showwarning("Raw histogram",
                    "No .mat path stored. Use 'Load Recon .mat' first."); return
            status_v.set("Reading raw .mat for histogram..."); pw.update_idletasks()
            try:
                import scipy.io as sio
                try:
                    import h5py
                except ImportError:
                    h5py = None
                vol = None
                try:
                    mat = sio.loadmat(path)
                    for k in list(mat.keys()):
                        if k.startswith('__'): continue
                        v = mat[k]
                        if isinstance(v, np.ndarray) and v.ndim >= 2:
                            if vol is None or v.size > vol.size:
                                vol = v
                except Exception:
                    pass
                if vol is None and h5py is not None:
                    with h5py.File(path, 'r') as f:
                        best = None; bsz = 0
                        for k in f.keys():
                            v = f[k]
                            if isinstance(v, h5py.Dataset) and v.ndim >= 2:
                                if np.prod(v.shape) > bsz:
                                    bsz = int(np.prod(v.shape)); best = k
                        if best is not None:
                            ds = f[best]
                            # downsample without loading the full array
                            stride = max(1, int(np.prod(ds.shape) // 4_000_000))
                            flat = ds[()].astype(np.float32).ravel()[::stride]
                            vol = flat
                if vol is None:
                    messagebox.showerror("Raw histogram", "Could not read the .mat file."); return
                flat = vol.ravel()
                stride = max(1, flat.size // 4_000_000)
                sample = flat[::stride]
                rmin = float(np.nanmin(sample)); rmax = float(np.nanmax(sample))
            except Exception as _e:
                import traceback as _tb
                self._log(f"[bolus] raw histogram failed: {_e}\n{_tb.format_exc()}")
                messagebox.showerror("Raw histogram", str(_e)); return
            w = tk.Toplevel(pw); w.title("Raw histogram (pre-clip)"); w.geometry("900x520")
            with apply_nature_style():
                from matplotlib.figure import Figure
                fig = Figure(figsize=nature_figsize_in('double', 3.6), dpi=300,
                              facecolor='white')
                ax = fig.add_subplot(111)
                ax.hist(sample, bins=200, color=OKABE_ITO[5], alpha=0.85,
                         log=True, edgecolor='none')
                ax.set_xlabel("raw intensity")
                ax.set_ylabel("count (log)")
                # markers
                if getattr(self, 'recon_vmin_raw', None) is not None:
                    ax.axvline(self.recon_vmin_raw, color=OKABE_ITO[3], lw=1.0,
                                ls='--', label=f"clip lo ({self.recon_clip_pct_lo:.3f}%)")
                if getattr(self, 'recon_vmax_raw', None) is not None:
                    ax.axvline(self.recon_vmax_raw, color=OKABE_ITO[1], lw=1.0,
                                ls='--', label=f"clip hi ({self.recon_clip_pct_hi:.3f}%)")
                if getattr(self, 'recon_sensor_ceiling', None) is not None:
                    ax.axvline(self.recon_sensor_ceiling, color=OKABE_ITO[6], lw=1.0,
                                ls=':', label=f"dtype max ({self.recon_sensor_ceiling:g})")
                ax.legend(loc='upper right', frameon=False)
                despine_lr(ax)
                panel_letter(ax, 'a')
                fig.tight_layout()
                _embed_with_save(w, fig, "raw_histogram")
            self._log(f"[bolus] raw histogram: min={rmin:g} max={rmax:g}  "
                      f"clip=({self.recon_vmin_raw:g}, {self.recon_vmax_raw:g})  "
                      f"dtype={self.recon_raw_dtype}")

        # ── DISPLAY vs MEASUREMENT basis ───────────────────────────────────
        # Display: canvas / montage / projection panels   → may use enhanced
        # Measurement: kymo / FWHM / intensity / velocity → LINEAR + BG only
        # by default (CLAHE/gamma are non-linear and BIAS those numbers). The
        # user can opt in via "Measure on enhanced frames (not recommended)";
        # the chosen basis is recorded in st['_basis'] and the saved metrics.
        def _bg_only_settings(src):
            bg = dict(src or {})
            return dict(
                gamma=1.0, pct_lo=0.0, pct_hi=100.0,
                bg_mode=bg.get('bg_mode', 'none'),
                bg_pct=float(bg.get('bg_pct', 5.0)),
                bg_medsz=int(bg.get('bg_medsz', 15)),
                denoise_on=False, denoise_str=5,
                clahe_on=False, clahe_clip=2.0,
                mask_on=False, mask_cx=0, mask_cy=0, mask_r=0,
            )

        # ── DEMOTION (SWiFT-IR) helpers ───────────────────────────────────
        def _swiftir_import():
            """Try swiftir from the bundled D:\\NIR_SLIM\\demotion path; return
            the module or None (in which case _estimate_demotion_shifts falls
            back to skimage.registration.phase_cross_correlation)."""
            try:
                import swiftir as _swiftir
                return _swiftir
            except ImportError:
                import sys as _sys
                _candidates = [r"D:\NIR_SLIM\demotion", r"D:\NIR_SLIM2\demotion"]
                for p in _candidates:
                    if os.path.isdir(p) and p not in _sys.path:
                        _sys.path.insert(0, p)
                try:
                    import swiftir as _swiftir
                    return _swiftir
                except ImportError:
                    return None

        def _invalidate_demotion_cache(toggle_only=False):
            """Drop the cached demotioned proj so the next access recomputes.
            If toggle_only=True (e.g. the user just flicked Apply on/off), keep
            shift estimates but recompute the shifted stack."""
            st['proj_demotion'] = None
            st['demotion_key'] = None
            if not toggle_only:
                pass                                       # shifts stay; demotion-dict unchanged
            _redraw()

        def _estimate_demotion_shifts():
            """3-stage swim estimation on ref_tyx = recon_volume[:,:,z_ref,:].
            Stage 1: prelim target from mean of central frames + apodize.
            Stage 2: refine target by re-extracting after first-pass swim.
            Stage 3: per-frame swim → (dx, dy). Stores st['demotion']."""
            z_ref = int(demo_zref_var.get())
            x0    = int(demo_x0_var.get())
            y0    = int(demo_y0_var.get())
            W0    = int(demo_W0_var.get())
            half  = int(demo_central_var.get())
            if not (0 <= z_ref < int(D)):
                messagebox.showwarning("Demotion", f"z_ref out of range [0, {D-1}]."); return
            if W0 <= 8 or W0 > int(min(H, W)):
                messagebox.showwarning("Demotion",
                    f"W0 must satisfy 8 < W0 <= min(H,W) = {int(min(H, W))}."); return
            x0 = max(W0 // 2, min(int(W) - W0 // 2, x0))
            y0 = max(W0 // 2, min(int(H) - W0 // 2, y0))
            # Reference time-series (T, H, W) at z_ref
            ref_tyx = np.ascontiguousarray(
                self.recon_volume[:, :, z_ref, :].transpose(2, 0, 1).astype(np.float32))
            T_ = ref_tyx.shape[0]
            half = max(2, min(half, T_ // 2 - 1)) if T_ >= 6 else max(1, T_ // 4)
            t0 = max(0, T_ // 2 - half); t1 = min(T_, T_ // 2 + half)
            central = list(range(t0, t1))
            sw = _swiftir_import()
            method = 'swiftir' if sw is not None else 'pcc_fallback'
            status_v.set(f"Demotion: estimating ({method}, z={z_ref}, "
                         f"x0={x0}, y0={y0}, W0={W0}, central=[{t0},{t1}))...")
            pw.update_idletasks()

            shifts = np.zeros((T_, 2), np.float32)
            def _run_in_worker():
                nonlocal shifts
                try:
                    if sw is not None:
                        # Stage 1
                        img0 = ref_tyx[central].mean(0).astype(np.float32)
                        roi0 = sw.extractStraightWindow(img0, [x0, y0], W0)
                        roi0apo = sw.apodize(roi0)
                        # Stage 2 — refine target
                        rois = []
                        for t in central:
                            roi = sw.extractStraightWindow(ref_tyx[t], [x0, y0], W0)
                            (dx, dy, _, _, _) = sw.swim(roi0apo, roi)
                            roi_mv = sw.extractStraightWindow(ref_tyx[t],
                                                                [x0 + dx, y0 + dy], W0)
                            rois.append(roi_mv)
                        roi1 = np.mean(rois, axis=0).astype(np.float32)
                        roi1apo = sw.apodize(roi1)
                        # Stage 3 — per-frame
                        for t in range(T_):
                            roi = sw.extractStraightWindow(ref_tyx[t], [x0, y0], W0)
                            (dx, dy, _, _, _) = sw.swim(roi1apo, roi)
                            shifts[t] = (float(dx), float(dy))
                            if (t % 50) == 0:
                                status_v.set(
                                    f"Demotion ({method}): frame {t}/{T_-1}")
                                pw.update_idletasks()
                    else:
                        # Fallback: phase_cross_correlation on the same ROI window
                        from skimage.registration import phase_cross_correlation
                        def _roi(img):
                            cx = max(W0 // 2, min(int(W) - W0 // 2, x0))
                            cy = max(W0 // 2, min(int(H) - W0 // 2, y0))
                            return img[cy - W0 // 2:cy - W0 // 2 + W0,
                                        cx - W0 // 2:cx - W0 // 2 + W0]
                        img0 = ref_tyx[central].mean(0).astype(np.float32)
                        ref_roi = _roi(img0)
                        for t in range(T_):
                            mov_roi = _roi(ref_tyx[t])
                            try:
                                sh, _, _ = phase_cross_correlation(
                                    ref_roi, mov_roi, upsample_factor=10,
                                    normalization=None)
                                # phase_cross_correlation returns (dy, dx)
                                # and the convention is: ndi_shift(mov, shift) → ref.
                                # studymotion's swim returns (dx, dy) where
                                # extracting at [x0+dx, y0+dy] hits the feature in
                                # the moving frame — i.e. shifts[t] points from
                                # ref to moving's feature position. PCC returns the
                                # opposite sign, so negate.
                                shifts[t] = (float(-sh[1]), float(-sh[0]))
                            except Exception:
                                shifts[t] = (0.0, 0.0)
                            if (t % 50) == 0:
                                status_v.set(
                                    f"Demotion ({method}, PCC): frame {t}/{T_-1}")
                                pw.update_idletasks()
                except Exception as _e:
                    import traceback as _tb
                    self._log(f"[demotion] estimate FAILED: {_e}\n{_tb.format_exc()}")
                    messagebox.showerror("Demotion", str(_e))
                    return
            _run_in_worker()
            mag = np.hypot(shifts[:, 0], shifts[:, 1])
            st['demotion'] = dict(shifts=shifts, x0=x0, y0=y0, W0=W0,
                                   z_ref=z_ref, central_half=half,
                                   method=method)
            _invalidate_demotion_cache()
            demo_status_var.set(
                f"{method}: mean|shift|={float(np.mean(mag)):.2f} px  "
                f"max|shift|={float(np.max(mag)):.2f} px  "
                f"(T={T_}, x0={x0}, y0={y0}, W0={W0}, z={z_ref})")
            self._log(f"[demotion] {method}: T={T_} mean|sh|={float(np.mean(mag)):.2f}px "
                      f"max|sh|={float(np.max(mag)):.2f}px x0={x0} y0={y0} W0={W0} "
                      f"z_ref={z_ref}; central frames=[{t0},{t1})")

        def _demotioned_proj():
            """Lazy-cached demotion-applied proj for the CURRENT projection (slice
            or MIP). Single per-frame (dx, dy) is applied to ALL depths within the
            chosen z-range before projection — for single-slice mode that's just a
            shift of the (T,H,W) at z; for MIP it's max-over-z after per-depth
            shifts. Translation only (scipy.ndimage.shift, mode='nearest')."""
            if st.get('demotion') is None:
                return st['proj']
            key = (st['proj_mode'], st['z_sel'], st['z0'], st['z1'],
                    int(demo_spline_var.get()),
                    int(id(st['demotion']['shifts'])))
            if (st.get('proj_demotion') is not None and
                    st.get('demotion_key') == key):
                return st['proj_demotion']
            from scipy.ndimage import shift as _shift
            shifts = st['demotion']['shifts']
            spline = max(0, int(demo_spline_var.get()))
            T_ = self.recon_volume.shape[3]
            mode = st['proj_mode']
            if mode == 'slice':
                z = int(st['z_sel'])
                src = self.recon_volume[:, :, z, :].transpose(2, 0, 1).astype(np.float32)
                out = np.empty_like(src)
                for t in range(T_):
                    dy, dx = float(shifts[t, 1]), float(shifts[t, 0])
                    out[t] = _shift(src[t], shift=(-dy, -dx),
                                     order=spline, mode='nearest',
                                     prefilter=(spline > 1))
            else:                                          # 'mip'
                z0, z1 = int(st['z0']), int(st['z1'])
                Hh, Ww, _, _ = self.recon_volume.shape
                out = np.zeros((T_, Hh, Ww), np.float32)
                for z in range(z0, z1 + 1):
                    src_z = self.recon_volume[:, :, z, :].transpose(2, 0, 1).astype(np.float32)
                    for t in range(T_):
                        dy, dx = float(shifts[t, 1]), float(shifts[t, 0])
                        sh = _shift(src_z[t], shift=(-dy, -dx),
                                     order=spline, mode='nearest',
                                     prefilter=(spline > 1))
                        out[t] = np.maximum(out[t], sh)
            st['proj_demotion'] = out
            st['demotion_key'] = key
            return out

        def _fig_demotion_shifts():
            """Three-row figure: dx(t), dy(t), |shift|(t)."""
            d = st.get('demotion')
            if d is None:
                messagebox.showinfo("Demotion", "Run 'Estimate shifts' first."); return
            sh = d['shifts']; fps = float(fps_var.get())
            t_ax = np.arange(sh.shape[0]) / max(fps, 1e-9)
            w = tk.Toplevel(pw); w.title("Demotion shift trace"); w.geometry("1100x680")
            with apply_nature_style():
                from matplotlib.figure import Figure
                fig = Figure(figsize=nature_figsize_in('double', 4.6), dpi=300,
                              facecolor='white')
                axA = fig.add_subplot(311); axB = fig.add_subplot(312, sharex=axA)
                axC = fig.add_subplot(313, sharex=axA)
                axA.plot(t_ax, sh[:, 0], color=OKABE_ITO[5], lw=0.9); axA.set_ylabel("dx (px)")
                axB.plot(t_ax, sh[:, 1], color=OKABE_ITO[3], lw=0.9); axB.set_ylabel("dy (px)")
                mag = np.hypot(sh[:, 0], sh[:, 1])
                axC.plot(t_ax, mag, color=OKABE_ITO[1], lw=0.9); axC.set_ylabel("|shift| (px)")
                axC.set_xlabel("time (s)")
                for ax, l in zip((axA, axB, axC), ('a', 'b', 'c')):
                    despine_lr(ax); panel_letter(ax, l)
                fig.tight_layout()
                _embed_with_save(w, fig, "demotion_shifts")

        def _fig_demotion_roi():
            """Three image panels: roi0 (raw mean), roi1apo (refined target),
            roi-at-mid-frame after applying its shift (sanity)."""
            d = st.get('demotion')
            if d is None:
                messagebox.showinfo("Demotion", "Run 'Estimate shifts' first."); return
            sw = _swiftir_import()
            if sw is None:
                # PCC fallback can't reproduce extractStraightWindow exactly; use
                # a simple slice. Visualisation only.
                pass
            z_ref = int(d['z_ref']); x0 = int(d['x0']); y0 = int(d['y0']); W0 = int(d['W0'])
            shifts = d['shifts']; T_ = shifts.shape[0]
            ref_tyx = self.recon_volume[:, :, z_ref, :].transpose(2, 0, 1).astype(np.float32)
            half = int(d['central_half']); t0 = max(0, T_ // 2 - half); t1 = min(T_, T_ // 2 + half)
            img0 = ref_tyx[t0:t1].mean(0)
            def _xtract(img, cx, cy, w0):
                if sw is not None:
                    return sw.extractStraightWindow(img, [cx, cy], w0)
                y_lo = int(round(cy - w0 / 2)); x_lo = int(round(cx - w0 / 2))
                y_lo = max(0, min(img.shape[0] - w0, y_lo))
                x_lo = max(0, min(img.shape[1] - w0, x_lo))
                return img[y_lo:y_lo + w0, x_lo:x_lo + w0]
            roi0 = _xtract(img0, x0, y0, W0)
            # rebuild roi1 (refined target) by re-running stage 2 on central frames
            try:
                roi1apo_list = []
                for t in range(t0, t1):
                    if sw is not None:
                        roi = sw.extractStraightWindow(ref_tyx[t], [x0, y0], W0)
                        (dx, dy, _, _, _) = sw.swim(sw.apodize(roi0), roi)
                        roi1apo_list.append(sw.extractStraightWindow(
                            ref_tyx[t], [x0 + dx, y0 + dy], W0))
                    else:
                        roi1apo_list.append(_xtract(ref_tyx[t], x0, y0, W0))
                roi1 = np.mean(roi1apo_list, axis=0)
                roi1apo = sw.apodize(roi1) if sw is not None else roi1
            except Exception as _e:
                self._log(f"[demotion] roi1 rebuild skipped: {_e}")
                roi1apo = roi0
            # Mid-frame ROI after applying its own shift
            tm = T_ // 2
            dxm, dym = float(shifts[tm, 0]), float(shifts[tm, 1])
            roi_mid_shifted = _xtract(ref_tyx[tm], x0 + dxm, y0 + dym, W0)
            w = tk.Toplevel(pw); w.title("Demotion ROI (before / target / after)")
            w.geometry("1100x420")
            with apply_nature_style():
                from matplotlib.figure import Figure
                fig = Figure(figsize=nature_figsize_in('double', 3.4), dpi=300,
                              facecolor='white')
                for i, (img, ttl) in enumerate([
                        (roi0,            f"roi0  (raw mean, central={t1-t0} fr)"),
                        (roi1apo,         "roi1apo  (refined target)"),
                        (roi_mid_shifted, f"frame t={tm}  (after applied shift)")]):
                    ax = fig.add_subplot(1, 3, i + 1)
                    ax.imshow(img, cmap='gray', interpolation='nearest')
                    ax.text(0.02, 0.97, ttl, transform=ax.transAxes, fontsize=6,
                             color='white', va='top', ha='left',
                             bbox=dict(boxstyle='round,pad=0.15', fc='black',
                                       ec='none', alpha=0.55))
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                    panel_letter(ax, chr(ord('a') + i), x=-0.05, y=1.02)
                fig.tight_layout()
                _embed_with_save(w, fig, "demotion_roi")

        def _corrected_proj():
            """Now routes through the Demotion (SWiFT-IR) module: returns the
            demotioned proj when ``apply_demotion_var`` is ON and shifts have
            been estimated; else returns ``st['proj']``. The legacy auto
            translation correction (motion-panel exclusion path) has been
            removed; every existing caller (``_display_frame``,
            ``_proj_for_measurement``, downstream figures) keeps working
            unchanged because the name + signature are preserved."""
            if apply_demotion_var.get() and st.get('demotion') is not None:
                return _demotioned_proj()
            return st['proj']

        def _apply_exclusion(arr, time_axis=0):
            """Set NaN at MANUALLY-deleted frames along ``time_axis`` (default 0
            for (T,H,W); pass 1 for (N,T) kymographs). Returns a new array.

            The legacy auto motion-drop mask (``st['valid_mask']``) has been
            removed; the only source of excluded frames is now the user's
            manual scrubber/bulk deletions in ``st['deleted_frames']``."""
            deleted = st.get('deleted_frames')
            if not deleted:
                return arr
            out = np.asarray(arr, np.float32).copy()
            T_ = out.shape[time_axis]
            bad = np.zeros(T_, bool)
            for i in deleted:
                if 0 <= int(i) < T_:
                    bad[int(i)] = True
            if not bad.any():
                return out
            if time_axis == 0:
                out[bad] = np.nan
            elif time_axis == 1:
                out[:, bad] = np.nan
            else:
                idx = [slice(None)] * out.ndim; idx[time_axis] = bad
                out[tuple(idx)] = np.nan
            return out

        def _display_frame(t):
            """One frame from the display basis (fast path used by canvas + montage).
            Uses the motion-corrected proj as the base."""
            base = _corrected_proj()
            img = base[min(int(t), base.shape[0] - 1)]
            if apply_enh_var.get() and st.get('enh_settings'):
                from slim_recon.enhance import enhance_frame
                return enhance_frame(img, st['enh_settings'])
            return img

        def _proj_for_measurement():
            """Per-frame measurement-basis stack on the MOTION-CORRECTED proj.
            LINEAR + BG-only by default, full enhancement if user opted in.
            Records st['_basis']. Excluded frames are NaN'd by callers via
            ``_apply_exclusion`` on the resulting kymograph (NOT here, so the
            FWHM / band sampling sees real pixel data and the exclusion lives
            at the trace level)."""
            proj = _corrected_proj()
            src = st.get('enh_settings')
            from slim_recon.enhance import enhance_frame
            if measure_enh_var.get() and src:
                st['_basis'] = 'enhanced'
                out = np.empty_like(proj)
                for t in range(proj.shape[0]):
                    out[t] = enhance_frame(proj[t], src)
                return out
            if src:
                st['_basis'] = 'linear+bg'
                s_bg = _bg_only_settings(src)
                out = np.empty_like(proj)
                for t in range(proj.shape[0]):
                    out[t] = enhance_frame(proj[t], s_bg)
                return out
            st['_basis'] = 'linear'
            return proj

        # ── Analyses ──
        def _need_proj():
            if st['proj'] is None:
                _rebuild_proj()
            return st['proj']

        def _need_centerline():
            if st['centerline'] is None or len(st['centerline']) < 2:
                messagebox.showwarning("Centerline",
                    "Draw the vessel centerline first (click points, double-click).")
                return None
            return st['centerline']

        def _scale_bar_µm(ax, length_um, px_um, color='white'):
            """Draw a µm scale bar at lower-right of an image axes (data coords).
            Returns the [Rectangle, Text] artists so callers can toggle visibility."""
            xlo, xhi = ax.get_xlim(); ylo, yhi = ax.get_ylim()
            Wax = abs(xhi - xlo); Hax = abs(ylo - yhi)
            bar_px = float(length_um) / float(px_um)
            x0 = max(xlo, xhi) - 0.06 * Wax - bar_px
            y0 = max(ylo, yhi) - 0.08 * Hax
            from matplotlib.patches import Rectangle as _R
            _rect = _R((x0, y0), bar_px, 0.02 * Hax, color=color, ec='none')
            ax.add_patch(_rect)
            _txt = ax.text(x0 + bar_px / 2, y0 - 0.01 * Hax, f"{length_um:g} µm",
                           color=color, ha='center', va='bottom', fontsize=7)
            return [_rect, _txt]

        # frame montage
        def _fig_montage():
            proj = _need_proj()
            K = max(2, int(k_mont_var.get())); fps = float(fps_var.get())
            t_idx = np.unique(np.linspace(0, proj.shape[0] - 1, K).astype(int))
            w = tk.Toplevel(pw); w.title("Frame montage"); w.geometry(f"{260 * len(t_idx)}x320")
            with apply_nature_style():
                fig = Figure(figsize=(2.4 * len(t_idx), 3.0), dpi=300, facecolor='white')
                valid = st.get('valid_mask')
                for i, t in enumerate(t_idx):
                    ax = fig.add_subplot(1, len(t_idx), i + 1)
                    img = _display_frame(t)              # honors "Apply enhancement"
                    if flip_h_var.get(): img = img[:, ::-1]
                    if flip_v_var.get(): img = img[::-1, :]
                    ax.imshow(img, cmap='gray', interpolation='nearest')
                    if st['centerline'] is not None:
                        cl = st['centerline'].astype(float)
                        if flip_h_var.get(): cl[:, 0] = W - 1 - cl[:, 0]
                        if flip_v_var.get(): cl[:, 1] = H - 1 - cl[:, 1]
                        ax.plot(cl[:, 0], cl[:, 1], '-',
                                 color=OKABE_ITO[6], lw=1.0)
                    ax.text(0.02, 0.97, f"{t/fps:.2f} s", transform=ax.transAxes,
                             fontsize=6, color='white', va='top', ha='left',
                             bbox=dict(boxstyle='round,pad=0.15', fc='black',
                                       ec='none', alpha=0.55))
                    # EXCL badge if this frame is in an excluded region
                    if valid is not None and 0 <= int(t) < valid.size and not valid[int(t)]:
                        ax.text(0.98, 0.97, "EXCL", transform=ax.transAxes,
                                 fontsize=6, color='white', va='top', ha='right',
                                 bbox=dict(boxstyle='round,pad=0.15',
                                           fc='#cc0000', ec='none', alpha=0.85))
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                    panel_letter(ax, chr(ord('a') + i), x=-0.04, y=1.02)
                    if i == len(t_idx) - 1:
                        _scale_bar_µm(ax, _nice_bar_length_um(ax, float(px_var.get())), float(px_var.get()))
            fig.tight_layout()
            _embed_with_save(w, fig, "montage")

        def _shade_excluded(ax, fps):
            """Light-gray axvspan for every excluded interval."""
            for (s, e) in st.get('excluded_intervals', []):
                ax.axvspan(s / fps, (e + 1) / fps, color='#888888',
                            alpha=0.25, zorder=0)

        def _maybe_interp_for_display(trace):
            """Cosmetic-only: linearly interpolate across NaN gaps in a 1D trace
            if 'Interpolate across gaps (display only)' is on. Does NOT modify
            the source array; returns a new one."""
            if not interp_var.get():
                return trace
            t = np.asarray(trace, float).copy()
            nan = ~np.isfinite(t)
            if not nan.any() or nan.all():
                return t
            idx = np.arange(t.size)
            t[nan] = np.interp(idx[nan], idx[~nan], t[~nan])
            return t

        # diameter kymograph (+ optional MIP-vs-slice overlay)
        def _fig_diameter_kymo():
            proj_lin = _need_proj(); cl = _need_centerline()
            if cl is None: return
            proj = _proj_for_measurement()               # LINEAR + BG-only by default
            N = max(3, int(n_pts_var.get())); fps = float(fps_var.get())
            pxu = float(px_var.get())
            centers, tangents, arclen_px = _sample_along_polyline(cl, N)
            if centers is None:
                messagebox.showerror("Error", "Polyline too short."); return
            status_v.set(f"Diameter kymograph (basis={st['_basis']}, "
                         f"corr={apply_corr_var.get()}): "
                         f"{N} pts × {proj.shape[0]} frames ..."); pw.update_idletasks()
            diam_um = _diameter_kymograph(proj, centers, tangents,
                                          int(prof_len_var.get()),
                                          float(fwhm_frac_var.get()), pxu)
            diam_um = _apply_exclusion(diam_um, time_axis=1)   # NaN excluded cols
            arclen_um = arclen_px * pxu                    # cumulative arc-length in µm
            st['last_results']['diam_um'] = diam_um
            st['last_results']['arclen_um'] = arclen_um
            st['last_results']['centers'] = centers
            st['last_results']['tangents'] = tangents

            w = tk.Toplevel(pw); w.title("Diameter kymograph"); w.geometry("1200x620")
            with apply_nature_style():
                fig = Figure(figsize=nature_figsize_in('double', 4.0), dpi=300,
                              facecolor='white')
                ax = fig.add_subplot(111)
                extent = [0.0, proj.shape[0] / fps, arclen_um[-1], 0.0]
                # mask NaNs so cmap shows them transparent
                im = ax.imshow(np.ma.masked_invalid(diam_um),
                                aspect='auto', cmap='viridis',
                                extent=extent, interpolation='nearest')
                slim_colorbar(im, ax, "Diameter (µm)")
                ax.set_xlabel("time (s)"); ax.set_ylabel("distance along vessel (µm)")
                _shade_excluded(ax, fps)
                panel_letter(ax, 'a')
                # Mean-of-row overlay (single trace) on a secondary axis (right)
                mean_d = np.nanmean(diam_um, axis=0)
                t_ax = np.arange(proj.shape[0]) / fps
                ax2 = ax.twinx()
                ax2.plot(t_ax, _maybe_interp_for_display(mean_d),
                         color=OKABE_ITO[0], lw=0.9, alpha=0.85)
                ax2.set_ylabel("mean D (µm)")
                despine_lr(ax2)
                # Optional single-slice vs MIP comparison
                if overlay_var.get():
                    other_mode = 'mip' if st['proj_mode'] == 'slice' else 'slice'
                    if other_mode == 'mip':
                        other_raw = _recon_proj_2d(vol, 'mip', z_range=(st['z0'], st['z1']))
                    else:
                        other_raw = _recon_proj_2d(vol, 'slice', z_sel=st['z_sel'])
                    # apply same correction for fair comparison
                    if apply_corr_var.get() and st.get('motion') is not None:
                        other_raw = apply_shifts(other_raw, st['motion']['shifts'],
                                                  spline_order=int(spline_var.get()))
                    diam_alt = _diameter_kymograph(other_raw, centers, tangents,
                                                   int(prof_len_var.get()),
                                                   float(fwhm_frac_var.get()), pxu)
                    diam_alt = _apply_exclusion(diam_alt, time_axis=1)
                    mean_alt = np.nanmean(diam_alt, axis=0)
                    ax2.plot(t_ax, _maybe_interp_for_display(mean_alt),
                             color=OKABE_ITO[1], lw=0.9, alpha=0.85,
                             label=f"alt: {other_mode}")
                    ax2.legend(loc='upper right', frameon=False)
                    mask = np.isfinite(mean_d) & np.isfinite(mean_alt)
                    if mask.sum() > 3:
                        r = float(np.corrcoef(mean_d[mask], mean_alt[mask])[0, 1])
                        self._log(f"[diam kymo] Pearson r(single, MIP) = {r:+.3f}")
                fig.tight_layout()
                _embed_with_save(w, fig, "diameter_kymo")

        # intensity kymograph
        def _fig_intensity_kymo():
            proj_lin = _need_proj(); cl = _need_centerline()
            if cl is None: return
            proj = _proj_for_measurement()
            N = max(3, int(n_pts_var.get())); fps = float(fps_var.get())
            pxu = float(px_var.get())
            centers, tangents, arclen_px = _sample_along_polyline(cl, N)
            if centers is None: return
            intens = _intensity_kymograph_band(proj, centers, int(band_var.get()), pxu)
            intens = _apply_exclusion(intens, time_axis=1)
            arclen_um = arclen_px * pxu
            st['last_results']['intens'] = intens
            st['last_results']['arclen_um'] = arclen_um

            w = tk.Toplevel(pw); w.title("Intensity kymograph"); w.geometry("1200x620")
            with apply_nature_style():
                fig = Figure(figsize=nature_figsize_in('double', 4.0), dpi=300,
                              facecolor='white')
                ax = fig.add_subplot(111)
                extent = [0.0, proj.shape[0] / fps, arclen_um[-1], 0.0]
                im = ax.imshow(np.ma.masked_invalid(intens),
                                aspect='auto', cmap='gray',
                                extent=extent, interpolation='nearest')
                slim_colorbar(im, ax, "Intensity (a.u.)")
                ax.set_xlabel("time (s)"); ax.set_ylabel("distance along vessel (µm)")
                _shade_excluded(ax, float(fps_var.get()))
                panel_letter(ax, 'a')
                fig.tight_layout()
                _embed_with_save(w, fig, "intensity_kymo")

        # multi-point traces
        def _fig_multitraces():
            proj_lin = _need_proj(); cl = _need_centerline()
            if cl is None: return
            proj = _proj_for_measurement()
            N = max(3, int(n_pts_var.get())); fps = float(fps_var.get())
            pxu = float(px_var.get())
            centers, tangents, arclen_px = _sample_along_polyline(cl, N)
            if centers is None: return
            kind = trace_kind_var.get()
            if kind == 'diameter':
                kymo = _diameter_kymograph(proj, centers, tangents,
                                            int(prof_len_var.get()),
                                            float(fwhm_frac_var.get()), pxu)
                ylab = "diameter (µm)"
            else:
                kymo = _intensity_kymograph_band(proj, centers, int(band_var.get()), pxu)
                ylab = "intensity (a.u.)"
            kymo = _apply_exclusion(kymo, time_axis=1)
            st['last_results'][f"{kind}_traces"] = kymo
            arclen_um = arclen_px * pxu
            # show up to 8 evenly-spaced traces
            n_show = min(8, N)
            sel = np.linspace(0, N - 1, n_show).astype(int)
            t_ax = np.arange(proj.shape[0]) / fps
            valid = st.get('valid_mask')
            w = tk.Toplevel(pw); w.title(f"Multi-point {kind} traces"); w.geometry("1200x680")
            with apply_nature_style():
                fig = Figure(figsize=nature_figsize_in('double', 4.2), dpi=300,
                              facecolor='white')
                ax = fig.add_subplot(111)
                offsets = np.linspace(0, 1, n_show) * 0.8    # normalized stacked offset
                for k, i in enumerate(sel):
                    row = kymo[i]
                    if not np.isfinite(row).any(): continue
                    rng = np.nanmax(row) - np.nanmin(row)
                    if rng < 1e-9: continue
                    norm = (row - np.nanmin(row)) / rng
                    color = OKABE_ITO[k % len(OKABE_ITO)]
                    ax.plot(t_ax, _maybe_interp_for_display(norm) + offsets[k],
                            lw=1.0, color=color,
                            label=f"{arclen_um[i]:.0f} µm")
                    # gap-aware peak markers (skip peaks spanning excluded gaps)
                    metrics = _pulse_metrics_gap_aware(row, fps, valid_mask=valid,
                        hp_window_s=float(hp_s_var.get()),
                        prom_mult=float(prom_var.get()),
                        dist_s=float(dist_s_var.get()),
                        savgol_w=int(savgol_var.get()))
                    pk = metrics['peaks']
                    if len(pk):
                        ax.plot(t_ax[pk], (norm + offsets[k])[pk], 'v', ms=4,
                                color=color, mec='k', mew=0.5)
                _shade_excluded(ax, fps)
                ax.set_xlabel("time (s)"); ax.set_ylabel(f"{ylab} (normalized + offset)")
                ax.legend(loc='center left', bbox_to_anchor=(1.0, 0.5), frameon=False)
                panel_letter(ax, 'a')
                despine_lr(ax)
                fig.tight_layout()
                _embed_with_save(w, fig, f"multitraces_{kind}")

        # pulse metrics (+ propagation velocity both ways)
        def _fig_pulse_metrics():
            proj_lin = _need_proj(); cl = _need_centerline()
            if cl is None: return
            proj = _proj_for_measurement()
            N = max(3, int(n_pts_var.get())); fps = float(fps_var.get())
            pxu = float(px_var.get())
            centers, tangents, arclen_px = _sample_along_polyline(cl, N)
            if centers is None: return
            diam   = _diameter_kymograph(proj, centers, tangents,
                                          int(prof_len_var.get()),
                                          float(fwhm_frac_var.get()), pxu)
            intens = _intensity_kymograph_band(proj, centers, int(band_var.get()), pxu)
            diam   = _apply_exclusion(diam,   time_axis=1)
            intens = _apply_exclusion(intens, time_axis=1)
            arclen_um = arclen_px * pxu
            mean_diam = np.nanmean(diam, axis=0)
            mean_int  = np.nanmean(intens, axis=0)
            valid = st.get('valid_mask')
            # GAP-AWARE pulse metrics on the mean-diameter trace — peaks NEVER
            # span an excluded gap; intervals only within contiguous valid runs.
            metrics = _pulse_metrics_gap_aware(mean_diam, fps,
                                                valid_mask=valid,
                                                hp_window_s=float(hp_s_var.get()),
                                                prom_mult=float(prom_var.get()),
                                                dist_s=float(dist_s_var.get()),
                                                savgol_w=int(savgol_var.get()),
                                                min_run_s=2.0)
            t_ax = np.arange(proj.shape[0]) / fps
            pk = metrics['peaks']
            # ejection-fraction-style amplitude % per cycle (skip pairs that
            # would span an excluded gap by checking the valid_mask).
            amp_pct = []
            if len(pk) >= 2 and (valid is None or valid.all() or True):
                for k in range(len(pk) - 1):
                    a, b = int(pk[k]), int(pk[k + 1])
                    if valid is not None and not valid[a:b + 1].all():
                        continue
                    seg = mean_diam[a:b + 1]
                    if seg.size < 3: continue
                    d_max = float(np.nanmax(seg)); d_min = float(np.nanmin(seg))
                    if d_max > 1e-9 and np.isfinite(d_max) and np.isfinite(d_min):
                        amp_pct.append((d_max - d_min) / d_max * 100.0)
            amp_pct = np.array(amp_pct)
            # Propagation velocity:
            #   (i)  kymograph slope (uses gap-aware peak picker per row)
            #   (ii) x-corr on the LONGEST contiguous VALID run (per spec)
            spacing_um = float(arclen_um[1] - arclen_um[0]) if N >= 2 else float(pxu)
            v_slope, _resid, dir_slope = _velocity_from_kymograph(diam, fps, spacing_um)
            v_xcorr, lag_s, dir_xcorr, used_run = _velocity_from_xcorr_gap_aware(
                diam, valid_mask=valid if valid is not None else np.ones(proj.shape[0], bool),
                sep_um=arclen_um[-1], fps=fps, min_run_s=2.0)
            # Frequency-preservation guard: compare freq_after to freq_before
            freq_warn = ''
            if np.isfinite(st.get('freq_before', float('nan'))) and np.isfinite(metrics['freq_cpm']):
                fb = float(st['freq_before']); fa = float(metrics['freq_cpm'])
                if fb > 1e-6 and abs(fa - fb) / fb > 0.20:
                    freq_warn = (f" WARN: correction changed freq "
                                  f"{fb:.2f}→{fa:.2f} cpm ({(fa-fb)/fb*100:+.0f}%)")
                    self._log(f"[motion] {freq_warn}")
            # velocity sanity warn
            if np.isfinite(v_slope) and np.isfinite(v_xcorr) and abs(v_xcorr) < 1e9:
                mx = max(abs(v_slope), abs(v_xcorr))
                if mx > 1e-9 and abs(v_slope - v_xcorr) / mx > 0.30:
                    self._log(f"[pulse] WARN velocity discrepancy: slope={v_slope:.1f} "
                              f"vs xcorr={v_xcorr:.1f} µm/s (>30%)")
            st['last_results'].update({
                'mean_diam_um': mean_diam, 'mean_intens': mean_int, 't_s': t_ax,
                'peaks': pk, 'amp_pct': amp_pct, 'metrics': metrics,
                'v_slope_um_s': v_slope, 'v_xcorr_um_s': v_xcorr,
                'lag_xcorr_s': lag_s, 'spacing_um': spacing_um,
                'arclen_um_total': float(arclen_um[-1]),
                'xcorr_run_used': used_run,
                'n_excluded': metrics['n_excluded'],
                'n_runs': metrics['n_runs'],
                'valid_duration_s': metrics['valid_duration_s'],
                'freq_before_cpm': float(st.get('freq_before', float('nan'))),
            })

            w = tk.Toplevel(pw); w.title("Pulse metrics"); w.geometry("1200x800")
            with apply_nature_style():
                fig = Figure(figsize=nature_figsize_in('double', 5.6), dpi=300,
                              facecolor='white')
                axes = [fig.add_subplot(4, 1, i + 1) for i in range(4)]
                # P1 — signal + peaks + envelope
                axes[0].plot(t_ax, _maybe_interp_for_display(metrics['signal_hp']),
                              color=OKABE_ITO[5], lw=0.7, alpha=0.85)
                axes[0].plot(t_ax, _maybe_interp_for_display(metrics['envelope']),
                              color=OKABE_ITO[5], lw=1.0, label='envelope')
                if len(pk):
                    axes[0].plot(t_ax[pk], metrics['signal_hp'][pk], 'v',
                                  color=OKABE_ITO[6], ms=5,
                                  label=f"contractions ({len(pk)})")
                axes[0].set_ylabel("diameter (HP, µm)")
                axes[0].legend(loc='upper right', frameon=False)
                _shade_excluded(axes[0], fps)
                # P2 — rate
                if len(metrics['rates_bpm']) > 0:
                    axes[1].plot(metrics['peak_times_s'], metrics['rates_bpm'],
                                  'o-', color=OKABE_ITO[6], ms=3, lw=0.9)
                axes[1].set_ylabel("rate (cpm)")
                _shade_excluded(axes[1], fps)
                # P3 — amplitude %
                if amp_pct.size:
                    axes[2].bar(range(amp_pct.size), amp_pct,
                                 color=OKABE_ITO[3], edgecolor='none')
                    axes[2].axhline(float(np.mean(amp_pct)), color='#888888',
                                     ls='--', lw=0.75,
                                     label=f"mean {np.mean(amp_pct):.1f}%")
                    axes[2].legend(loc='upper right', frameon=False)
                axes[2].set_ylabel("amplitude (%)")
                # P4 — intervals
                if metrics['intervals'].size:
                    axes[3].bar(range(metrics['intervals'].size),
                                 metrics['intervals'],
                                 color=OKABE_ITO[7], edgecolor='none')
                    axes[3].axhline(float(metrics['interval_s_mean']),
                                     color='#888888', ls='--', lw=0.75,
                                     label=f"mean {metrics['interval_s_mean']:.2f} s")
                    axes[3].legend(loc='upper right', frameon=False)
                axes[3].set_ylabel("interval (s)"); axes[3].set_xlabel("cycle #")
                for ax, letter in zip(axes, ('a', 'b', 'c', 'd')):
                    despine_lr(ax); panel_letter(ax, letter)
                fig.tight_layout()
                _embed_with_save(w, fig, "pulse_metrics")
            # log summary (caption-style; no in-axes title)
            self._log(f"[pulse] freq={metrics['freq_cpm']:.2f} cpm  "
                      f"interval={metrics['interval_s_mean']:.2f} s  "
                      f"mean amp%={(np.mean(amp_pct) if amp_pct.size else float('nan')):.1f}  "
                      f"v_slope={v_slope:.1f}  v_xcorr={v_xcorr:.1f} µm/s  lag={lag_s:.2f}s  "
                      f"n_excluded={metrics['n_excluded']}  n_runs={metrics['n_runs']}  "
                      f"valid_dur={metrics['valid_duration_s']:.1f}s"
                      f"{freq_warn}")

        # time-color projection (display basis: matches viewer if "Apply enh" on)
        def _fig_time_color():
            _need_proj()
            base = _corrected_proj()                 # use motion-corrected proj
            if apply_enh_var.get() and st.get('enh_settings'):
                from slim_recon.enhance import enhance_frame
                proj = np.empty_like(base)
                for t in range(base.shape[0]):
                    proj[t] = enhance_frame(base[t], st['enh_settings'])
            else:
                proj = base
            # Excluded frames should not contribute to the argmax-over-time
            valid = st.get('valid_mask')
            if valid is not None and (~valid).any():
                proj = proj.copy()
                proj[~valid] = 0.0
            rgb = _time_color_projection(proj)
            if rgb is None:
                messagebox.showwarning("Time-color", "Need T >= 2."); return
            w = tk.Toplevel(pw); w.title("Time-color projection"); w.geometry("820x820")
            with apply_nature_style():
                fig = Figure(figsize=nature_figsize_in('single', 5.0), dpi=300,
                              facecolor='white')
                ax = fig.add_subplot(111)
                disp = rgb
                if flip_h_var.get(): disp = disp[:, ::-1]
                if flip_v_var.get(): disp = disp[::-1, :]
                ax.imshow(disp, interpolation='nearest')
                ax.set_xticks([]); ax.set_yticks([])
                for s_ in ax.spines.values(): s_.set_visible(False)
                _scale_bar_µm(ax, _nice_bar_length_um(ax, float(px_var.get())), float(px_var.get()))
                panel_letter(ax, 'a')
                _embed_with_save(w, fig, "time_color")

        # synthetic FWHM self-test
        def _self_test_fwhm():
            sigma = 4.0
            x = np.arange(81) - 40.0
            prof = np.exp(-x * x / (2 * sigma * sigma))
            true_fwhm = 2.0 * np.sqrt(2.0 * np.log(2.0)) * sigma
            est = _fwhm_from_profile(prof, 0.5)
            err = abs(est - true_fwhm) / true_fwhm * 100.0
            ok = err < 5.0
            self._log(f"[self-test FWHM] true={true_fwhm:.3f} px  est={est:.3f} px  "
                      f"err={err:.2f}%  {'OK' if ok else 'FAIL'}")
            messagebox.showinfo("FWHM self-test",
                f"True FWHM (σ=4): {true_fwhm:.3f} px\n"
                f"Estimated     : {est:.3f} px\n"
                f"Error         : {err:.2f}%  ({'OK' if ok else 'FAIL'} <5%)")

        # save data bundle
        def _save_data_bundle():
            r = dict(st['last_results'])
            if not r:
                messagebox.showwarning("Save",
                    "Run an analysis first (e.g. diameter kymograph or pulse metrics).")
                return
            # Build tidy long CSV
            diam = r.get('diam_um'); intens = r.get('intens')
            arclen_um = r.get('arclen_um')
            t_s = r.get('t_s')
            tidy = []
            if diam is not None and arclen_um is not None:
                T_ = diam.shape[1]; fps = float(fps_var.get())
                if t_s is None:
                    t_s = np.arange(T_) / fps
                for i in range(diam.shape[0]):
                    for t in range(T_):
                        row = {
                            'time_s': float(t_s[t]),
                            'position_um': float(arclen_um[i]),
                            'diameter_um': float(diam[i, t]) if np.isfinite(diam[i, t]) else float('nan'),
                            'intensity': float(intens[i, t]) if (intens is not None) else float('nan'),
                        }
                        tidy.append(row)
            metrics_rows = []
            if r.get('metrics') is not None:
                m = r['metrics']
                metrics_rows.append({
                    'frequency_cpm': m['freq_cpm'],
                    'amplitude_pct_mean': float(np.mean(r['amp_pct'])) if r.get('amp_pct') is not None and r['amp_pct'].size else float('nan'),
                    'interval_s_mean': m['interval_s_mean'],
                    'velocity_slope_um_s': r.get('v_slope_um_s', float('nan')),
                    'velocity_xcorr_um_s': r.get('v_xcorr_um_s', float('nan')),
                    'lag_xcorr_s': r.get('lag_xcorr_s', float('nan')),
                    'direction_slope_sign': int(np.sign(r.get('v_slope_um_s', 0)) or 0),
                    'direction_xcorr_sign': int(np.sign(r.get('lag_xcorr_s', 0)) or 0),
                    'n_contractions': int(len(r['metrics']['peaks'])),
                    'fps_hz': float(fps_var.get()),
                    'px_um': float(px_var.get()),
                    'proj_mode': st['proj_mode'],
                    'z_sel': st['z_sel'], 'z0': st['z0'], 'z1': st['z1'],
                    'hp_window_s': float(hp_s_var.get()),
                    'prom_mult': float(prom_var.get()),
                    'dist_s': float(dist_s_var.get()),
                    'savgol_w': int(savgol_var.get()),
                    'profile_len_px': int(prof_len_var.get()),
                    'fwhm_frac': float(fwhm_frac_var.get()),
                    'band_half_px': int(band_var.get()),
                    'n_pts': int(n_pts_var.get()),
                    'measurement_basis': st.get('_basis', 'linear'),
                    'apply_enhancement_display': bool(apply_enh_var.get()),
                    'enh_source': (st.get('enh_settings') or {}).get('__source__', None),
                    # ── Motion metadata ──
                    'motion_correction_applied': bool(apply_corr_var.get() and st.get('motion') is not None),
                    'motion_reference_idx': (st.get('motion') or {}).get('ref_idx', None),
                    'motion_reference_method': (st.get('motion') or {}).get('ref_method', None),
                    'motion_spline_order': int(spline_var.get()),
                    'motion_estimated_on_clahe': bool(clahe_var.get()),
                    'motion_roi_xyxy': str((st.get('motion') or {}).get('roi_xyxy', None)),
                    'exclusion_threshold_method': thr_mode_var.get(),
                    'exclusion_mad_k': float(k_var.get()),
                    'exclusion_pct': float(pct_var.get()),
                    'exclusion_quality_min': float(qmin_var.get()),
                    'exclusion_intervals': str(st.get('excluded_intervals', [])),
                    'n_excluded': int(np.sum(~(st['valid_mask']))) if st.get('valid_mask') is not None else 0,
                    'valid_duration_s': float(st.get('last_results', {}).get('valid_duration_s', float('nan'))),
                    'n_runs': int(st.get('last_results', {}).get('n_runs', 0)),
                    'freq_before_cpm': float(st.get('freq_before', float('nan'))),
                    'xcorr_run_used': str(st.get('last_results', {}).get('xcorr_run_used', None)),
                })
            arrays = {
                'proj': st['proj'],
                'proj_corrected': st.get('proj_corrected'),
                'centerline_xy': st['centerline'],
                'centers_xy': r.get('centers'),
                'tangents': r.get('tangents'),
                'arclen_um': arclen_um,
                'diam_um': diam,
                'intens': intens,
                't_s': t_s,
                'peaks': r.get('peaks'),
                'amp_pct': r.get('amp_pct'),
                # ── Motion arrays ──
                'motion_shifts': (st.get('motion') or {}).get('shifts'),
                'motion_quality': (st.get('motion') or {}).get('quality'),
                'valid_mask': st.get('valid_mask'),
                'excluded_intervals': (np.array(st.get('excluded_intervals') or [])
                                        if st.get('excluded_intervals') else None),
            }
            stem = _save_data_dialog(parent=pw, default_stem="lymphatic_pulse",
                                      arrays=arrays, tidy_csv=tidy or None,
                                      metrics_csv=metrics_rows or None)
            if stem:
                status_v.set(f"Saved: {os.path.basename(stem)}.npz/.csv/_metrics.csv")
                self._log(f"[save] {stem}.npz + .csv + _metrics.csv")

        # embed mpl figure with Save Fig + close
        def _embed_with_save(window, fig, default_stem):
            """Embed a Figure into a Toplevel + always-visible button bar.
            Bar packed at BOTTOM FIRST so it reserves its space; canvas fills
            the remainder. Also docks a matplotlib NavigationToolbar so users
            can pan/zoom and save frames without a hidden button bar."""
            from matplotlib.backends.backend_tkagg import (
                FigureCanvasTkAgg, NavigationToolbar2Tk)
            # Bottom button bar — reserved first so it can't be pushed off-screen
            bot = ttk.Frame(window)
            bot.pack(side=tk.BOTTOM, fill=tk.X, padx=3, pady=2)
            ttk.Button(bot, text="Save Fig (PDF/SVG/PNG)",
                       command=lambda: _save_fig_dialog(fig, parent=window,
                                                         default_stem=default_stem)
                       ).pack(side=tk.LEFT, padx=2)
            ttk.Button(bot, text="Close",
                       command=window.destroy).pack(side=tk.RIGHT, padx=2)
            # Canvas + optional navigation toolbar
            c = FigureCanvasTkAgg(fig, window); c.draw()
            try:
                tb_row = ttk.Frame(window)
                tb_row.pack(side=tk.BOTTOM, fill=tk.X)
                NavigationToolbar2Tk(c, tb_row, pack_toolbar=True).update()
            except Exception:
                pass                                    # non-fatal
            c.get_tk_widget().pack(side=tk.TOP,
                                     fill=tk.BOTH, expand=True)

        # layered export — shares the same helper used by the Movie Viewer.
        # The analyzer doesn't render its own depth_coded/depth_map at all
        # frames; it derives them from the same recon_volume + cmap the Movie
        # Viewer uses so the exported layers are visually consistent. Honors
        # the analyzer's "Apply enhancement" toggle for the grayscale layer.
        def _open_analyzer_layered_export():
            _need_proj()
            from slim_recon.layered_export import (
                export_layers as _exp_layers, parse_frame_spec as _pfs)
            chooser = tk.Toplevel(pw)
            chooser.title("Layered Export (analyzer)")
            chooser.geometry("540x380")
            lf = ttk.LabelFrame(chooser, text="Layers"); lf.pack(fill=tk.X, padx=8, pady=4)
            v_gray = tk.BooleanVar(value=True)
            v_col  = tk.BooleanVar(value=True)
            v_dpth = tk.BooleanVar(value=False)
            ttk.Checkbutton(lf, text="grayscale (analyzer proj, "
                            f"basis={'enhanced' if apply_enh_var.get() else 'linear'})",
                            variable=v_gray).pack(anchor='w', padx=6)
            ttk.Checkbutton(lf, text="depth-coded (turbo × MIP-intensity)",
                            variable=v_col ).pack(anchor='w', padx=6)
            ttk.Checkbutton(lf, text="depth-map (argmax-z, normalized)",
                            variable=v_dpth).pack(anchor='w', padx=6)
            ff = ttk.LabelFrame(chooser, text="Formats"); ff.pack(fill=tk.X, padx=8, pady=4)
            f_tif = tk.BooleanVar(value=True)
            f_svg = tk.BooleanVar(value=True)
            ttk.Checkbutton(ff, text="TIF (16-bit grayscale/depth, 8-bit RGB depth-coded)",
                            variable=f_tif).pack(anchor='w', padx=6)
            ttk.Checkbutton(ff, text="SVG (vector container + embedded PNG)",
                            variable=f_svg).pack(anchor='w', padx=6)
            ef = ttk.LabelFrame(chooser, text="Frames"); ef.pack(fill=tk.X, padx=8, pady=4)
            T_proj = st['proj'].shape[0] if st['proj'] is not None else 1
            spec_var = tk.StringVar(value=str(int(st['current_t'])))
            rr = ttk.Frame(ef); rr.pack(fill=tk.X, padx=6, pady=2)
            ttk.Label(rr, text="indices:").pack(side=tk.LEFT)
            ttk.Entry(rr, textvariable=spec_var, width=36).pack(side=tk.LEFT, padx=4)
            ttk.Button(rr, text="current",
                       command=lambda: spec_var.set(str(int(st['current_t'])))).pack(side=tk.LEFT, padx=2)
            ttk.Button(rr, text="all",
                       command=lambda: spec_var.set(f"0-{T_proj-1}")).pack(side=tk.LEFT, padx=2)
            ttk.Label(ef, text="syntax:  12   |   0,30,60   |   0-100   |   0-100:10   |   0..100/5",
                       font=('TkDefaultFont', 8)).pack(anchor='w', padx=6)
            br = ttk.Frame(chooser); br.pack(fill=tk.X, padx=8, pady=6)

            # depth layers are derived from recon_volume (vol) at the current
            # z-range so they match the Movie Viewer's depth-coded MIP exactly.
            import matplotlib.pyplot as _plt
            _cmap = _plt.colormaps.get_cmap('turbo')
            def _grayscale_t(t):
                """Use the analyzer's basis logic (display) for the grayscale layer."""
                return np.clip(_display_frame(t), 0, 1).astype(np.float32)

            def _depth_layers_t(t):
                if mode_var.get() == 'slice':
                    z = int(z_var.get())
                    z0, z1 = max(0, z), min(D - 1, z)
                else:
                    z0 = max(0, min(int(z0_var.get()), D - 1))
                    z1 = max(z0, min(int(z1_var.get()), D - 1))
                sub = vol[:, :, z0:z1 + 1, t]                # (H, W, nz)
                proj_val = sub.max(axis=2)
                idx = np.argmax(sub, axis=2)
                depth_idx = (z0 + idx).astype(np.float32)
                depth_norm = depth_idx / max(D - 1, 1)
                rgb = _cmap(depth_norm)[:, :, :3]
                depth_coded = (rgb * proj_val[:, :, None]).astype(np.float32)
                return depth_coded, depth_norm

            def _layers(t):
                out = {}
                out['grayscale'] = _grayscale_t(t)
                dc, dm = _depth_layers_t(t)
                out['depth_coded'] = dc
                out['depth_map']   = dm
                return out

            def _do():
                layers = [n for n, v in (('grayscale', v_gray), ('depth_coded', v_col),
                                          ('depth_map', v_dpth)) if v.get()]
                fmts   = [n for n, v in (('tif', f_tif), ('svg', f_svg)) if v.get()]
                frames = _pfs(spec_var.get(), T_proj)
                if not layers or not fmts or not frames:
                    messagebox.showwarning("Layered Export",
                        "Pick at least one layer, one format, and a valid frame spec."); return
                stem = filedialog.asksaveasfilename(
                    parent=chooser, title="Save stem (no extension)",
                    initialfile="lymphatic_export", defaultextension="")
                if not stem: return
                if '.' in os.path.basename(stem):
                    stem = os.path.splitext(stem)[0]
                self._log(f"[analyzer export] {len(frames)} frames × {len(layers)} "
                          f"layers × {len(fmts)} fmts -> {stem}_*")
                try:
                    files = _exp_layers(
                        layers=layers, formats=fmts, frames=frames,
                        get_layer_arrays=_layers,
                        out_stem=stem,
                        px_um=float(px_var.get()), fps=float(fps_var.get()),
                        settings=st.get('enh_settings'),
                        depth_index_range=(0, D - 1),
                        cmap_name='turbo',
                        scalebar_um=100.0,
                    )
                    self._log(f"[analyzer export] wrote {len(files)} files")
                    messagebox.showinfo("Layered Export",
                        f"Wrote {len(files)} files (stem: {os.path.basename(stem)})")
                except Exception as _e:
                    import traceback as _tb
                    self._log(f"[analyzer export] ERROR: {_e}\n{_tb.format_exc()}")
                    messagebox.showerror("Layered Export", str(_e))
                chooser.destroy()
            ttk.Button(br, text="Export", command=_do).pack(side=tk.RIGHT, padx=4)
            ttk.Button(br, text="Cancel", command=chooser.destroy).pack(side=tk.RIGHT, padx=4)

        # (BOLUS DYNAMICS figures + BOLUS BLOBS extraction + BOLUS
        # FEASIBILITY check helpers removed with their panels. The kept
        # Pulse-frame differential figure subsumes the per-pair differential
        # + arclength view on the manual deletion mask only.)

        # ── MANUAL BREATHING REMOVAL helpers ──────────────────────────────
        def _rebuild_clean_index_map():
            """Rebuild orig_to_cleaned / cleaned_to_orig from deleted_frames."""
            T_ = (st['proj'].shape[0] if st['proj'] is not None else int(T))
            deleted = st['deleted_frames']
            o2c = {}
            c2o = []
            j = 0
            for i in range(T_):
                if i in deleted:
                    o2c[i] = None
                else:
                    o2c[i] = j
                    c2o.append(i)
                    j += 1
            st['orig_to_cleaned'] = o2c
            st['cleaned_to_orig'] = np.asarray(c2o, int)
            kept = T_ - len(deleted)
            mbr_status_var.set(f"kept {kept} / {T_}   (deleted {len(deleted)})")

        def _apply_typed_deletions(spec):
            """Bulk-add deletions via parse_frame_spec syntax."""
            from slim_recon.layered_export import parse_frame_spec
            T_ = (st['proj'].shape[0] if st['proj'] is not None else int(T))
            new_idx = parse_frame_spec(spec, T_)
            if not new_idx:
                messagebox.showinfo("Bulk delete", "No frames parsed from input."); return
            before = set(st['deleted_frames'])
            st['del_undo_stack'].append(before)
            st['deleted_frames'] = before | set(int(i) for i in new_idx)
            _rebuild_clean_index_map()
            self._log(f"[manual-del] bulk added {len(new_idx)} frames "
                      f"({sorted(new_idx)[:10]}{'...' if len(new_idx)>10 else ''}) "
                      f"-> deleted total {len(st['deleted_frames'])}")

        def _undo_deletion():
            if not st['del_undo_stack']:
                self._log("[manual-del] undo stack empty"); return
            st['deleted_frames'] = set(st['del_undo_stack'].pop())
            _rebuild_clean_index_map()
            self._log(f"[manual-del] undo -> {len(st['deleted_frames'])} frames deleted")

        def _clear_all_deletions():
            if not st['deleted_frames']:
                self._log("[manual-del] nothing to clear"); return
            st['del_undo_stack'].append(set(st['deleted_frames']))
            st['deleted_frames'] = set()
            _rebuild_clean_index_map()
            self._log("[manual-del] cleared all deletions")

        def _open_breathing_scrubber():
            """Toplevel scrubber: image + slider + Prev/Next/Delete/Undo +
            timeline strip + go-to entry + keyboard bindings."""
            proj_lin = _need_proj()
            T_ = st['proj'].shape[0]
            sw = tk.Toplevel(pw); sw.title("Breathing-frame scrubber")
            sw.geometry("900x720")
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            # Layout: figure on top (image + timeline); controls below
            fig = Figure(figsize=(7.0, 5.0), dpi=120, facecolor='white')
            ax_im = fig.add_axes([0.04, 0.18, 0.92, 0.78])
            ax_tl = fig.add_axes([0.04, 0.06, 0.92, 0.06])
            ax_im.set_xticks([]); ax_im.set_yticks([])
            for s_ in ax_im.spines.values(): s_.set_visible(False)
            ax_tl.set_yticks([]); ax_tl.set_ylim(0, 1)
            ax_tl.set_xlim(-0.5, T_ - 0.5)
            ax_tl.set_xlabel("frame", fontsize=8)
            ax_tl.tick_params(labelsize=7)
            cur = {'t': int(st.get('current_t', 0))}
            im_h = ax_im.imshow(_display_frame(cur['t']), cmap='gray',
                                  vmin=0, vmax=1)
            tl_deleted_lines = []
            cur_line = ax_tl.axvline(cur['t'], color='k', lw=1.2)
            title_txt = ax_im.set_title("", fontsize=9, color='#333')
            canvas = FigureCanvasTkAgg(fig, sw); canvas.draw()
            canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)

            def _redraw_scrubber():
                t = cur['t']
                im_h.set_data(_display_frame(t))
                # title
                deleted = st['deleted_frames']
                cleaned_idx = st['orig_to_cleaned'].get(t) if st['orig_to_cleaned'] else None
                tot_cleaned = (st['cleaned_to_orig'].size
                               if st['cleaned_to_orig'] is not None else T_)
                is_del = t in deleted
                tag = ("  [DELETED]" if is_del else
                       (f"   (cleaned idx {cleaned_idx} / {tot_cleaned})"
                        if cleaned_idx is not None else ""))
                title_txt.set_text(f"frame {t} / {T_-1}{tag}")
                title_txt.set_color('#cc0000' if is_del else '#333')
                # timeline marks
                for ln in tl_deleted_lines: ln.remove()
                tl_deleted_lines.clear()
                if deleted:
                    for d in deleted:
                        tl_deleted_lines.append(
                            ax_tl.axvline(d, color='#cc0000', lw=0.9, alpha=0.7))
                cur_line.set_xdata([t, t])
                canvas.draw_idle()
                # mirror to analyzer canvas
                st['current_t'] = t

            # Slider
            from matplotlib.widgets import Slider, Button
            ax_sl = fig.add_axes([0.04, 0.0, 0.62, 0.04])
            sl = Slider(ax_sl, 'frame', 0, T_ - 1, valinit=cur['t'],
                         valstep=1, color='#4a90d9')
            def _on_slider(v):
                cur['t'] = int(v); _redraw_scrubber()
            sl.on_changed(_on_slider)
            # Buttons
            btn_frame = ttk.Frame(sw); btn_frame.pack(fill=tk.X, padx=6, pady=4)
            def _prev():
                cur['t'] = max(0, cur['t'] - 1); sl.set_val(cur['t'])
            def _next():
                cur['t'] = min(T_ - 1, cur['t'] + 1); sl.set_val(cur['t'])
            def _del_current():
                t = cur['t']
                if t in st['deleted_frames']:
                    self._log(f"[manual-del] frame {t} already deleted")
                    return
                st['del_undo_stack'].append(set(st['deleted_frames']))
                st['deleted_frames'] = st['deleted_frames'] | {int(t)}
                _rebuild_clean_index_map()
                self._log(f"[manual-del] deleted frame {t} -> total {len(st['deleted_frames'])}")
                _redraw_scrubber()
            def _undo_local():
                _undo_deletion()
                _redraw_scrubber()
            ttk.Button(btn_frame, text="◀ Prev",
                       command=_prev).pack(side=tk.LEFT, padx=2)
            ttk.Button(btn_frame, text="Next ▶",
                       command=_next).pack(side=tk.LEFT, padx=2)
            ttk.Button(btn_frame, text="Delete current",
                       command=_del_current).pack(side=tk.LEFT, padx=8)
            ttk.Button(btn_frame, text="Undo",
                       command=_undo_local).pack(side=tk.LEFT, padx=2)
            ttk.Label(btn_frame, text="  go to:").pack(side=tk.LEFT, padx=(8, 2))
            goto_var = tk.StringVar(value=str(cur['t']))
            ttk.Entry(btn_frame, textvariable=goto_var, width=6).pack(side=tk.LEFT)
            def _goto(_evt=None):
                try:
                    v = int(goto_var.get())
                except ValueError:
                    return
                cur['t'] = max(0, min(T_ - 1, v)); sl.set_val(cur['t'])
            ttk.Button(btn_frame, text="Go", command=_goto).pack(side=tk.LEFT, padx=2)
            ttk.Button(btn_frame, text="Done",
                       command=sw.destroy).pack(side=tk.RIGHT, padx=2)
            # Keyboard: left/right/del/u
            def _on_key(evt):
                k = (evt.key or '').lower()
                if k == 'left':       _prev()
                elif k == 'right':    _next()
                elif k == 'delete':   _del_current()
                elif k == 'u':        _undo_local()
            fig.canvas.mpl_connect('key_press_event', _on_key)
            # Initial paint
            _rebuild_clean_index_map()
            _redraw_scrubber()

        # ── Cleaned-volume I/O ────────────────────────────────────────────
        def _save_cleaned_volume():
            """Save the LINEAR cleaned data. Default .mat (4D H,W,D,T'); .tif
            of the analyzer's working proj stack optional (uint16)."""
            if not hasattr(self, 'recon_volume') or self.recon_volume is None:
                messagebox.showwarning("Save cleaned", "No recon_volume loaded."); return
            T_ = st['proj'].shape[0] if st['proj'] is not None else int(T)
            kept_orig = (st['cleaned_to_orig']
                          if st['cleaned_to_orig'] is not None
                          else np.arange(T_, dtype=int))
            if kept_orig.size == 0:
                messagebox.showwarning("Save cleaned",
                    "All frames are deleted — nothing to save."); return
            # Format chooser
            top = tk.Toplevel(pw); top.title("Save cleaned volume")
            top.geometry("440x220")
            ttk.Label(top, text=f"Cleaned: {kept_orig.size} / {T_} frames",
                       font=('TkDefaultFont', 9, 'bold')).pack(padx=10, pady=(8, 2))
            ttk.Label(top, text="LINEAR data only (no CLAHE/gamma).",
                       font=('TkDefaultFont', 8), foreground='#444',
                       wraplength=420, justify='left').pack(padx=10, pady=2)
            mat_var = tk.BooleanVar(value=True)
            tif_var = tk.BooleanVar(value=False)
            ttk.Checkbutton(top, text=".mat  (4D H × W × D × T', float32, "
                                       "key='recon_clean')",
                            variable=mat_var).pack(anchor='w', padx=12, pady=2)
            ttk.Checkbutton(top, text=".tif  (T' × H × W proj stack, uint16)",
                            variable=tif_var).pack(anchor='w', padx=12, pady=2)
            stem_var = tk.StringVar(value="")
            def _pick_stem():
                p = filedialog.asksaveasfilename(
                    parent=top, title="Save stem (no extension)",
                    initialfile="recon_clean", defaultextension="")
                if p:
                    if '.' in os.path.basename(p):
                        p = os.path.splitext(p)[0]
                    stem_var.set(p)
            sr = ttk.Frame(top); sr.pack(fill=tk.X, padx=10, pady=4)
            ttk.Label(sr, text="stem:").pack(side=tk.LEFT)
            ttk.Entry(sr, textvariable=stem_var, width=32).pack(side=tk.LEFT, padx=2)
            ttk.Button(sr, text="...", command=_pick_stem).pack(side=tk.LEFT)
            def _do():
                import json
                stem = stem_var.get().strip()
                if not stem:
                    _pick_stem(); stem = stem_var.get().strip()
                    if not stem: return
                files = []
                vol = self.recon_volume
                if mat_var.get():
                    try:
                        import scipy.io as _sio
                        vol_clean = np.ascontiguousarray(vol[:, :, :, kept_orig])
                        _sio.savemat(stem + ".mat",
                                      {'recon_clean': vol_clean.astype(np.float32),
                                       'kept_indices': kept_orig.astype(np.int32),
                                       'T_original': int(T_),
                                       'source_path': str(getattr(self, 'recon_mat_path', ''))},
                                      do_compression=True)
                        files.append(stem + ".mat")
                    except Exception as _e:
                        self._log(f"[save cleaned] .mat failed: {_e}")
                        messagebox.showerror("Save cleaned (.mat)", str(_e))
                if tif_var.get():
                    try:
                        import tifffile
                        # Use the analyzer's working proj stack (LINEAR + BG-only basis)
                        proj_lin = _proj_for_measurement()[kept_orig]
                        u16 = (np.clip(proj_lin, 0, 1) * 65535.0 + 0.5).astype(np.uint16)
                        tifffile.imwrite(
                            stem + ".tif", u16, photometric='minisblack',
                            resolution=(300, 300), resolutionunit='INCH',
                            description=json.dumps(dict(
                                kept_indices=kept_orig.tolist(),
                                T_original=int(T_),
                                px_um=float(px_var.get()),
                                fps_hz=float(fps_var.get()),
                                source_path=str(getattr(self, 'recon_mat_path', '')))))
                        files.append(stem + ".tif")
                    except Exception as _e:
                        self._log(f"[save cleaned] .tif failed: {_e}")
                        messagebox.showerror("Save cleaned (.tif)", str(_e))
                if files:
                    self._log(f"[save cleaned] wrote {files}")
                    messagebox.showinfo("Save cleaned",
                        f"Wrote {len(files)} files:\n" + "\n".join(files))
                top.destroy()
            br = ttk.Frame(top); br.pack(fill=tk.X, padx=10, pady=8)
            ttk.Button(br, text="Save", command=_do).pack(side=tk.RIGHT, padx=2)
            ttk.Button(br, text="Cancel", command=top.destroy).pack(side=tk.RIGHT, padx=2)

        def _save_deletion_list():
            """Write <stem>.json AND <stem>.csv with the deletion list."""
            import json as _json, csv as _csv
            T_ = st['proj'].shape[0] if st['proj'] is not None else int(T)
            stem = filedialog.asksaveasfilename(
                parent=pw, title="Save deletion list (stem; .json + .csv)",
                initialfile="deletion_list", defaultextension="")
            if not stem: return
            if '.' in os.path.basename(stem):
                stem = os.path.splitext(stem)[0]
            deleted = sorted(int(i) for i in st['deleted_frames'])
            kept = [i for i in range(T_) if i not in st['deleted_frames']]
            payload = {
                'source_path': str(getattr(self, 'recon_mat_path', '')),
                'T': int(T_),
                'deleted': deleted,
                'kept': kept,
            }
            with open(stem + ".json", "w") as f:
                _json.dump(payload, f, indent=2)
            with open(stem + ".csv", "w", newline="") as f:
                wcsv = _csv.writer(f)
                wcsv.writerow(['original_index', 'status'])
                for i in range(T_):
                    wcsv.writerow([i, ('deleted' if i in st['deleted_frames'] else 'kept')])
            self._log(f"[save deletion-list] {stem}.json + {stem}.csv  "
                      f"({len(deleted)} deleted / {T_})")

        def _load_deletion_list():
            import json as _json
            p = filedialog.askopenfilename(
                parent=pw, title="Load deletion list (.json)",
                filetypes=[("JSON", "*.json"), ("All", "*.*")])
            if not p: return
            try:
                with open(p, "r") as f:
                    payload = _json.load(f)
            except Exception as _e:
                messagebox.showerror("Load deletion list", str(_e)); return
            T_ = st['proj'].shape[0] if st['proj'] is not None else int(T)
            if int(payload.get('T', -1)) != int(T_):
                if not messagebox.askyesno("Load deletion list",
                        f"T mismatch: file T = {payload.get('T')} vs current T = {T_}.\n"
                        f"Apply anyway (clamped to current T)?"):
                    return
            deleted = set(int(i) for i in payload.get('deleted', []) if 0 <= int(i) < T_)
            st['del_undo_stack'].append(set(st['deleted_frames']))
            st['deleted_frames'] = deleted
            _rebuild_clean_index_map()
            self._log(f"[load deletion-list] applied {len(deleted)} deletions from {p}")

        # initialise the index map with the current (empty) deletion set
        _rebuild_clean_index_map()

        # ── MANUAL PULSE-FRAME DIFFERENTIAL helper ────────────────────────
        def _compute_pulse_arclength(cl_override=None):
            """Shared pipeline for the pulse-frame differential figure and the
            two peak-derived sibling figures (synthetic bolus + peak trajectory).
            Returns a dict with the ORIGINAL (unsuppressed) arclength kymograph
            and per-frame peak positions / amplitudes / FWHMs.
            Suppression is applied ONLY at plot time by callers; the returned
            arrays are always the LINEAR + BG-only quantitative signal.

            When ``cl_override`` is passed (np.ndarray of xy points), that
            centerline is used instead of ``st['centerline']`` — this is how
            per-line iterations over `st['centerlines']` reuse this pipeline
            without touching the legacy single-line alias."""
            from slim_recon.layered_export import parse_frame_spec
            proj_lin = _need_proj()
            T_ = st['proj'].shape[0]
            fps = float(fps_var.get()); pxu = float(px_var.get())
            raw = parse_frame_spec(pulse_frames_var.get(), T_)
            if not raw:
                messagebox.showwarning("Differential",
                    "Enter at least 2 frames in the 'frames' field."); return None
            if pulse_basis_var.get() == 'cleaned':
                if st['cleaned_to_orig'] is None or st['cleaned_to_orig'].size == 0:
                    messagebox.showwarning("Differential",
                        "No cleaned frames available."); return None
                c2o = st['cleaned_to_orig']
                raw_orig = [int(c2o[min(max(0, i), c2o.size - 1)]) for i in raw]
            else:
                raw_orig = list(raw)
            deleted = st['deleted_frames']
            valid_idx = (st['cleaned_to_orig'] if st['cleaned_to_orig'] is not None
                         else np.arange(T_, dtype=int))
            final = []; snapped = []
            for f in raw_orig:
                if f in deleted:
                    if not pulse_snap_var.get():
                        self._log(f"[pulse-diff] WARN: kept dropped pick t={f} (snap OFF)")
                        final.append(int(f)); continue
                    if valid_idx.size == 0: continue
                    j = int(np.argmin(np.abs(valid_idx - f)))
                    snapped.append((int(f), int(valid_idx[j])))
                    final.append(int(valid_idx[j]))
                else:
                    final.append(int(f))
            final = sorted(set(final))
            for src, dst in snapped:
                self._log(f"[pulse-diff] snapped deleted pick t={src} -> nearest kept t={dst}")
            if len(final) < 2:
                messagebox.showwarning("Differential",
                    f"Need ≥2 kept frames after snap (got {len(final)})."); return None
            try:
                sat = _ensure_sat()
                sat_frac = float(st.get('sat_total_frac') or 0.0)
            except Exception:
                sat = None; sat_frac = 0.0
            proj_meas = _proj_for_measurement()
            tau = max(1, int(pulse_tauwin_var.get()))
            if tau > 1:
                from scipy.ndimage import uniform_filter1d
                proj_meas = uniform_filter1d(proj_meas, size=tau,
                                                axis=0, mode='nearest')
            # DELEGATE the difference->arclength->s*/amp/fwhm math to the shared module core
            # (`pulse_arclength_core`) so the recon window and the manual batch run the IDENTICAL
            # pipeline. proj_meas is already tau-smoothed above, so tau=1 here (no double filter).
            cl = cl_override if cl_override is not None else st.get('centerline')
            _core = pulse_arclength_core(
                proj_meas, final, cl, n_pts=max(16, int(n_pts_var.get()) * 2),
                band_px=int(band_var.get()), pxu=pxu,
                mode=pulse_diff_mode_var.get(), ref_idx=int(pulse_ref_var.get()),
                sigma_xy=float(pulse_sigma_var.get()), tau=1, sat=sat, polarity='signed')
            present = _core['present']
            if not present:
                messagebox.showwarning("Differential",
                    "No difference frames available (consecutive mode skips first)."); return None
            return dict(
                fps=fps, pxu=pxu, T_original=T_,
                final=final, present=present, sat_frac=sat_frac, mode=_core['mode'],
                Dmap=_core['Dmap'], _sat_mask=_core['sat_mask'],
                cl=cl, have_cl=_core['have_cl'],
                centers=_core['centers'], tangents=_core['tangents'], arclen_um=_core['arclen_um'],
                b_profiles=_core['b_profiles'],
                s_star_um=_core['s_star_um'], amp_at_star=_core['amp_at_star'], fwhm_um=_core['fwhm_um'],
                B=_core['B'],
            )

        def _fwhm_of_arclength_profile(b, arclen_um, pk_i):
            """Delegates to the module-level `_fwhm_profile` (single implementation)."""
            return _fwhm_profile(b, arclen_um, pk_i)

        def _save_pulse_results():
            """Run the canonical pipeline for EACH user interval (the 'frames' field; ';' separates
            intervals) and write <stem>_pulseresults.json (+.csv) with the FULL provenance the Pulse
            Flow importer needs (schema recon_pulse_v1, frame_map, centerline prox->dist, image
            shape, normalization, drift_applied, direction convention, TIFF sha1)."""
            import json as _json, hashlib, csv as _csv
            from slim_recon.layered_export import parse_frame_spec
            cl = st.get('centerline')
            if cl is None or len(cl) < 2:
                messagebox.showwarning("Save pulse results", "Draw a centerline first."); return
            meta = getattr(self, '_recon_tiff_meta', None) or {}
            proj = _proj_for_measurement(); T = int(proj.shape[0])
            fmap = np.asarray(meta.get('frame_map') if meta.get('frame_map') is not None
                              else np.arange(T), np.int64)
            fps = float(meta.get('fps', fps_var.get()))
            # STAGE 4: identity frame_map + a built SOURCE MAP + a recognized source TIFF -> remap the
            # pulse's LOCAL frames to real ROOT frames via the source map, so per-file recon pulse
            # files (opened one at a time) still carry real acquisition time.
            _srcmap = getattr(self, '_pf_srcmap', None)
            _base0 = os.path.splitext(os.path.basename(meta.get('source_tiff', '') or ''))[0]
            _identity = bool(fmap.size == T and np.array_equal(fmap, np.arange(T, dtype=np.int64)))
            _root_override = None
            if _identity and _srcmap:
                _tag = next((nm.split('_')[-1] for nm, _n in SOURCE_FILES_DEFAULT
                             if _base0 == nm or _base0.startswith(nm)), None)
                if _tag is not None and _tag in _srcmap.get('offsets', {}):
                    _off = int(_srcmap['offsets'][_tag])
                    fmap = np.arange(T, dtype=np.int64) + _off
                    _root_override = dict(T=int(_srcmap['T']), boundaries=list(_srcmap['boundaries']))
                    self._log(f"[pulse] identity frame_map -> ROOT via SOURCE MAP: file '{_tag}' "
                              f"offset {_off}; root frames {_off}..{_off + T - 1} (root via source map)")
            specs = [s for s in pulse_frames_var.get().split(';') if s.strip()] or [pulse_frames_var.get()]
            intervals = []; sub_roots = []
            _bnds = (_root_override or meta.get('root') or {}).get('boundaries', [0, len(fmap)])
            for sp in specs:
                fr = parse_frame_spec(sp, T)
                if len(fr) < 2: continue
                intervals.append((min(fr), max(fr) + 1))
                sub_local = (min(fr), max(fr) + 1)                       # the frames the user cropped
                sub_root  = (int(fmap[sub_local[0]]), int(fmap[min(sub_local[1], len(fmap)) - 1]) + 1)
                sub_roots.append(sub_root)
                self._log(f"[pulse] interval local {sub_local} -> ROOT {sub_root} "
                          f"= {sub_root[0]/fps:.1f}-{sub_root[1]/fps:.1f}s "
                          f"file {file_index(_bnds, sub_root[0])}"
                          + ("  (identity frame_map: ROOT time UNCALIBRATED)"
                             if _identity and not _root_override else ""))
            if not intervals:
                messagebox.showwarning("Save pulse results",
                    "Enter >=2 frames (';' separates intervals)."); return
            path = filedialog.asksaveasfilename(defaultextension=".json",
                filetypes=[("JSON", "*.json")], title="Save pulse results")
            if not path: return
            stem = os.path.splitext(path)[0]
            sha = ''
            try:
                stif = meta.get('source_tiff')
                if stif and os.path.exists(stif):
                    h = hashlib.sha1()
                    with open(stif, 'rb') as fh:
                        for chunk in iter(lambda: fh.read(1 << 20), b''): h.update(chunk)
                    sha = h.hexdigest()
            except Exception:
                pass
            doc = build_pulse_results_doc(
                proj, intervals, np.asarray(cl, float),
                fps=fps, px_um=float(px_var.get()), N=max(16, int(n_pts_var.get()) * 2),
                band=int(band_var.get()), diff=pulse_diff_mode_var.get(),
                prom=float(fit_min_prom_var.get()), fit=fit_est_var.get(),
                frame_map=fmap, root=(_root_override or meta.get('root')),
                source_tiff=meta.get('source_tiff', ''),
                image_shape=meta.get('shape'), normalization=meta.get('normalization', 'as_in_tiff'),
                drift_applied=meta.get('drift_applied'), tiff_sha1=sha)
            for _i, _it in enumerate(doc.get('intervals', [])):   # STAGE 2: record cropped-sub-range ROOT pos
                if _i < len(sub_roots):
                    _it['sub_root_t0'] = int(sub_roots[_i][0]); _it['sub_root_t1'] = int(sub_roots[_i][1])
            if _root_override is not None:
                self._log("[pulse] saved JSON root_time_valid via source map (root via source map)")
            with open(stem + '_pulseresults.json', 'w') as fh:
                _json.dump(doc, fh, indent=2, default=float)
            with open(stem + '_pulseresults.csv', 'w', newline='') as fh:
                w = _csv.writer(fh)
                w.writerow(['idx', 'root_t0', 'root_t1', 't_peak_root', 'root_time_s', 'root_file',
                            'v_um_s', 'se', 'r2', 'n_used', 'n_kept', 'direction', 'transport_um'])
                for it in doc['intervals']:
                    w.writerow([it['idx'], it['root_t0'], it['root_t1'], it['t_peak_root'],
                                f"{it['t_peak_root']/fps:.4f}", it['root_file'],
                                f"{it['v_um_s']:.4g}", f"{it['se']:.4g}", f"{it['r2']:.4g}",
                                it['n_used'], it['n_kept'], it['direction'], f"{it['transport_um']:.4g}"])
            if not doc['root_time_valid']:
                self._log("[recon-save] WARNING: identity frame_map -> root_time_valid=false "
                          "(real acquisition times UNKNOWN; interval statistics withheld on import)")
            self._log(f"[recon-save] wrote {stem}_pulseresults.json/.csv "
                      f"({doc['n_intervals']} intervals); schema=recon_pulse_v1 "
                      f"root_time_valid={doc['root_time_valid']}")
            messagebox.showinfo("Save pulse results",
                f"Saved {doc['n_intervals']} interval(s) to\n{stem}_pulseresults.json (+.csv)")

        # ── Robust regression helpers (delegate to the module-level kernels) ─
        def _ransac_pure(t, s, thr, min_samples=3, max_trials=200, seed=0):
            """Delegates to the module-level `_ransac_line`."""
            return _ransac_line(t, s, thr, min_samples=min_samples,
                                max_trials=max_trials, seed=seed)

        def _fit_line(t, s, method):
            """Robust line fit dispatcher. Returns
            (slope, intercept, inlier_mask, method_used, residual_thr).
            Delegates to the module-level `_robust_line_fit`; identical behavior."""
            r = _robust_line_fit(np.asarray(t, float), np.asarray(s, float),
                                 method=method, thr=float(fit_ransac_thr_var.get()),
                                 min_samples=int(fit_ransac_min_var.get()),
                                 max_trials=int(fit_ransac_trials_var.get()))
            return r['slope'], r['intercept'], r['inliers'], r['method'], r['thr']

        def _robust_peak_fit(pk):
            """Peak-quality filter + robust regression on s*(t).
            Returns a dict summarizing the fit (used by the peak-trajectory
            figure AND the bolus-on-structure figure to drive s_fit(t))."""
            fps = float(pk['fps'])
            t_all = np.array([f / max(fps, 1e-9)
                                for f in pk['present']], dtype=float)
            s_all = pk['s_star_um'].astype(float)
            amp   = pk['amp_at_star']
            b_profiles = pk['b_profiles']
            n_total = int(t_all.size)
            # Quality gates
            min_prom = float(fit_min_prom_var.get())
            k_mad    = float(fit_kmad_var.get())
            pass_mask = np.ones(n_total, dtype=bool)
            for k, b in enumerate(b_profiles):
                b_arr = np.asarray(b, dtype=float)
                if b_arr.size == 0: pass_mask[k] = False; continue
                max_b = float(np.nanmax(b_arr))
                med   = float(np.median(b_arr))
                mad_b = float(np.median(np.abs(b_arr - med)))
                peak  = float(amp[k])
                if max_b <= 0:
                    pass_mask[k] = False; continue
                norm_prom = peak / (max_b + 1e-12)
                if norm_prom < min_prom:
                    pass_mask[k] = False; continue
                if mad_b > 0 and peak < med + k_mad * mad_b:
                    pass_mask[k] = False; continue
            t_kept = t_all[pass_mask]
            s_kept = s_all[pass_mask]
            n_kept = int(t_kept.size)
            method = fit_est_var.get()
            if n_kept < 3:
                if n_kept >= 2:
                    slope, intercept = np.polyfit(t_kept, s_kept, 1)
                else:
                    slope = float('nan'); intercept = float('nan')
                inlier_kept = np.ones(n_kept, dtype=bool)
                method_used = 'ols(fallback,n<3)'; thr = float('nan')
            else:
                slope, intercept, inlier_kept, method_used, thr = _fit_line(
                    t_kept, s_kept, method)
            # R² and residuals on INLIERS ONLY (honest reporting)
            if inlier_kept.any() and np.isfinite(slope):
                t_in = t_kept[inlier_kept]; s_in = s_kept[inlier_kept]
                s_hat = slope * t_in + intercept
                ss_res = float(np.sum((s_in - s_hat) ** 2))
                ss_tot = float(np.sum((s_in - np.mean(s_in)) ** 2))
                r2_in  = float(1.0 - ss_res / (ss_tot + 1e-12)) if ss_tot > 0 else float('nan')
                resid_std = float(np.std(s_in - s_hat))
                pear_r = (float(np.corrcoef(t_in, s_in)[0, 1])
                            if s_in.size >= 2 else float('nan'))
            else:
                r2_in = float('nan'); resid_std = float('nan'); pear_r = float('nan')
            n_inliers = int(inlier_kept.sum())
            inlier_frac = float(n_inliers / max(n_total, 1))
            direction = ('forward' if slope > 0 else
                          'reverse' if slope < 0 else 'still')
            low_conf = (
                (inlier_frac < float(fit_inlier_min_frac_var.get()))
                or (not np.isnan(r2_in)
                    and r2_in < float(fit_min_R2_var.get()))
                or n_inliers < 3)
            # Global inlier/outlier flags on ALL frames (rejected-by-gate → NOT inlier)
            inlier_all = np.zeros(n_total, dtype=bool)
            kept_positions = np.flatnonzero(pass_mask)
            for j, pos in enumerate(kept_positions):
                inlier_all[pos] = bool(inlier_kept[j])
            return dict(
                t=t_all, s=s_all,
                pass_mask=pass_mask,
                t_kept=t_kept, s_kept=s_kept,
                inlier_kept=inlier_kept,
                inlier_all=inlier_all,
                slope=float(slope), intercept=float(intercept),
                r2_inliers=float(r2_in), pearson_r=pear_r,
                residual_std=resid_std,
                n_total=n_total, n_kept=n_kept, n_inliers=n_inliers,
                inlier_frac=inlier_frac,
                direction=direction,
                estimator=method_used,
                residual_thr=float(thr),
                low_confidence=bool(low_conf),
            )

        def _peak_suppression_weights(arclen_um, s_star_um_k):
            """Per-column display weight w(s) = 1 inside |s-s*|<=w_um, cosine-taper
            over ``taper_um``, floor outside. Returns (S,) float32 in [0, 1]."""
            w_um    = max(0.0, float(pulse_supp_w_var.get()))
            taper   = max(0.0, float(pulse_supp_tap_var.get()))
            floor   = float(min(max(pulse_supp_flr_var.get(), 0.0), 1.0))
            d = np.abs(arclen_um - float(s_star_um_k))
            weight = np.ones_like(arclen_um, dtype=np.float32) * floor
            inside = d <= w_um
            weight[inside] = 1.0
            if taper > 0:
                trans = (d > w_um) & (d <= (w_um + taper))
                tt = (d[trans] - w_um) / taper                # 0 at inner edge, 1 at outer
                weight[trans] = floor + (1.0 - floor) * 0.5 * (1.0 + np.cos(np.pi * tt))
            return weight.astype(np.float32)

        # Visible-error wrapper for every pulse-diff button. Guarantees a
        # blank-window / silent-noop can never happen: any raised exception is
        # logged with a full traceback AND surfaced as a messagebox.
        def _pulse_run_safe(name, fn, *args, **kwargs):
            import traceback
            self._log(f"[pulse-diff] {name} start")
            try:
                fn(*args, **kwargs)
            except Exception as e:
                tb = traceback.format_exc()
                self._log(f"[pulse-diff] {name} FAIL:\n{tb}")
                try:
                    messagebox.showerror("Pulse-diff",
                        f"{name} failed:\n{type(e).__name__}: {e}\n\n"
                        f"See log for full traceback.")
                except Exception:
                    pass
                return
            self._log(f"[pulse-diff] {name} ok")

        def _fig_manual_pulse_differential():
            """Differential images between user-typed pulse frames on the LINEAR
            BG-only basis, between KEPT frames only. Optional arclength view if
            a centerline has been drawn. Panel (b) curves and panel (c)
            kymograph optionally suppress values away from each column's peak
            for cleaner ridge readability — DISPLAY ONLY; every reported number
            uses the ORIGINAL b_k(s)."""
            pk = _compute_pulse_arclength()
            if pk is None: return
            fps, pxu = pk['fps'], pk['pxu']
            T_ = pk['T_original']; final = pk['final']; present = pk['present']
            sat_frac = pk['sat_frac']
            Dmap = pk['Dmap']; _sat_mask = pk['_sat_mask']
            cl = pk['cl']; have_cl = pk['have_cl']
            arclen_um = pk['arclen_um']; b_profiles = pk['b_profiles']
            s_star_um = pk['s_star_um']; amp_at_star = pk['amp_at_star']
            fwhm_um = pk['fwhm_um']; B = pk['B']
            o2c = st['orig_to_cleaned']
            tau = max(1, int(pulse_tauwin_var.get()))
            if not have_cl:
                self._log("[pulse-diff] no centerline → skipping arclength view")
            self._log(f"[pulse-diff] picks (orig idx -> cleaned idx -> time s):")
            for f in final:
                ci = o2c.get(f) if o2c else None
                self._log(f"  t={f:>4d}  cleaned={ci}  ({f/max(fps,1e-9):.2f} s)")
            self._log(f"[pulse-diff] saturated_frac = {sat_frac*100:.2f}%, "
                      f"diff_mode={pulse_diff_mode_var.get()}, "
                      f"sigma_xy={pulse_sigma_var.get()}, tau_win={tau}, "
                      f"n_kept_after_snap={len(final)}, "
                      f"suppression={'ON' if pulse_supp_on_var.get() else 'OFF'} "
                      f"(display-only; quantification uses ORIGINAL b(s))")

            # ── Nature-styled figure ──
            from matplotlib.figure import Figure
            w = tk.Toplevel(pw); w.title("Pulse-frame differential")
            n_diff = len(present)
            fig_w_in = max(7.2, 1.6 * n_diff + 4.5)
            with apply_nature_style():
                fig = Figure(figsize=(fig_w_in, 6.0 if have_cl else 3.4),
                              dpi=300, facecolor='white')
                rows = 2 if have_cl else 1
                gs = fig.add_gridspec(rows, n_diff,
                                        height_ratios=[1.0] * rows,
                                        hspace=0.32, wspace=0.18)
                # (a) montage
                d_all = np.concatenate([
                    np.abs(np.nan_to_num(Dmap[t], nan=0.0)).ravel() for t in present])
                vmax_d = float(np.percentile(d_all, 99)) if d_all.size else 1.0
                if vmax_d <= 0: vmax_d = 1.0
                for i, t in enumerate(present):
                    ax = fig.add_subplot(gs[0, i])
                    d = _sat_mask(Dmap[t], t)
                    disp = d
                    if flip_h_var.get(): disp = disp[:, ::-1]
                    if flip_v_var.get(): disp = disp[::-1, :]
                    im = ax.imshow(np.ma.masked_invalid(disp), cmap='RdBu_r',
                                    vmin=-vmax_d, vmax=+vmax_d,
                                    interpolation='nearest')
                    if have_cl:
                        H_, W_ = d.shape
                        cl_d = cl.astype(float).copy()
                        if flip_h_var.get(): cl_d[:, 0] = W_ - 1 - cl_d[:, 0]
                        if flip_v_var.get(): cl_d[:, 1] = H_ - 1 - cl_d[:, 1]
                        ax.plot(cl_d[:, 0], cl_d[:, 1], '-', color=OKABE_ITO[6],
                                 lw=0.9, alpha=0.85)
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                    ci = o2c.get(t) if o2c else None
                    label = f"t={t}{' (c='+str(ci)+')' if ci is not None else ''}\n{t/max(fps,1e-9):.2f} s"
                    ax.text(0.02, 0.97, label, transform=ax.transAxes,
                             fontsize=6, color='white', va='top', ha='left',
                             bbox=dict(boxstyle='round,pad=0.15', fc='black',
                                       ec='none', alpha=0.55))
                    if i == 0:
                        panel_letter(ax, 'a', x=-0.05, y=1.02)
                    if i == n_diff - 1:
                        _scale_bar_µm(ax, _nice_bar_length_um(ax, pxu), pxu)
                        slim_colorbar(im, ax, "D (signed)")
                # (b) arclength view (only if centerline). Suppression is
                # DISPLAY-ONLY — peak positions / amplitudes / FWHM below still
                # come from the ORIGINAL b_k(s) held in `b_profiles`.
                if have_cl:
                    half = max(1, n_diff // 2)
                    axb = fig.add_subplot(gs[1, :half])
                    axc = fig.add_subplot(gs[1, half:])
                    supp_on = bool(pulse_supp_on_var.get())
                    offsets = np.linspace(0, 1, max(1, len(b_profiles))) * 0.5
                    for i, (b, t) in enumerate(zip(b_profiles, present)):
                        color = OKABE_ITO[i % len(OKABE_ITO)]
                        pk_i = int(np.argmax(b))              # ORIGINAL peak
                        # DISPLAY copy (may be suppressed for readability).
                        # Weight variable named `wgt` — do NOT reuse `w`, which
                        # is the Toplevel handle passed to _embed_with_save.
                        if supp_on:
                            wgt = _peak_suppression_weights(arclen_um, arclen_um[pk_i])
                            b_disp = b * wgt
                        else:
                            b_disp = b
                        bmax = max(np.nanmax(b_disp) - np.nanmin(b_disp), 1e-12)
                        norm = (b_disp - np.nanmin(b_disp)) / bmax
                        axb.plot(arclen_um, norm + offsets[i], color=color, lw=1.0,
                                  label=f"t={t}")
                        axb.plot(arclen_um[pk_i], (norm + offsets[i])[pk_i], 'v',
                                  color=color, ms=4, mec='k', mew=0.5)
                    axb.set_xlabel("arclength s (µm)")
                    axb.set_ylabel("b_k(s) (norm + offset)"
                                    + ("  [supp]" if supp_on else ""))
                    axb.legend(loc='upper right', frameon=False, fontsize=5)
                    despine_lr(axb); panel_letter(axb, 'b', x=-0.08, y=1.05)
                    B = np.stack(b_profiles, axis=1)                  # ORIGINAL
                    peak_si = np.array([int(np.argmax(b)) for b in b_profiles])
                    if supp_on:
                        W_mat = np.stack([
                            _peak_suppression_weights(arclen_um, arclen_um[pi])
                            for pi in peak_si], axis=1)
                        B_disp = B * W_mat
                    else:
                        B_disp = B
                    vmaxK = float(np.nanpercentile(B_disp, 99)) if B_disp.size else 1.0
                    if vmaxK <= 0: vmaxK = 1.0
                    imk = axc.imshow(B_disp, aspect='auto', cmap='viridis',
                                       vmin=0, vmax=vmaxK,
                                       extent=[0, n_diff, arclen_um[-1], 0],
                                       interpolation='nearest')
                    axc.plot(np.arange(n_diff) + 0.5, arclen_um[peak_si], 'o-',
                              color=OKABE_ITO[6], lw=0.9, ms=3, mec='k', mew=0.4)
                    axc.set_xticks(np.arange(n_diff) + 0.5)
                    axc.set_xticklabels([f"{t/max(fps,1e-9):.1f}" for t in present],
                                          rotation=45, ha='right')
                    axc.set_xlabel("time (s)"); axc.set_ylabel("arclength s (µm)")
                    slim_colorbar(imk, axc, ("b_k(s) [supp]" if supp_on else "b_k(s)"))
                    panel_letter(axc, 'c', x=-0.06, y=1.05)
                    if supp_on:
                        fig.text(0.99, 0.005,
                            "Panels b+c: peak-focused suppression (display only). "
                            "All peak positions / amplitudes / FWHM are on ORIGINAL b(s).",
                            ha='right', va='bottom', fontsize=5,
                            color='0.35', style='italic')
                fig.tight_layout()
                # Save CSV button (besides the standard Save Fig)
                def _save_csv():
                    import csv as _csv
                    pcsv = filedialog.asksaveasfilename(
                        parent=w, title="Save pulse picks CSV",
                        initialfile="pulse_diff_picks", defaultextension=".csv",
                        filetypes=[("CSV", "*.csv")])
                    if not pcsv: return
                    stem = os.path.splitext(pcsv)[0]
                    with open(stem + ".csv", "w", newline="") as f:
                        wcsv = _csv.writer(f)
                        wcsv.writerow(['frame_orig', 'frame_cleaned', 'time_s'])
                        for f_orig in final:
                            ci = (o2c.get(f_orig) if o2c else None)
                            wcsv.writerow([f_orig, ci,
                                            f_orig / max(fps, 1e-9)])
                    with open(stem + "_metrics.csv", "w", newline="") as f:
                        wcsv = _csv.writer(f)
                        wcsv.writerow(['diff_mode', 'ref_idx', 'sigma_xy', 'tau_win',
                                        'saturated_frac', 'n_deleted', 'T',
                                        'basis', 'snap_on', 'sat_thr_mode'])
                        wcsv.writerow([pulse_diff_mode_var.get(),
                                        int(pulse_ref_var.get()),
                                        float(pulse_sigma_var.get()),
                                        int(pulse_tauwin_var.get()),
                                        float(sat_frac),
                                        int(len(st['deleted_frames'])),
                                        int(T_),
                                        pulse_basis_var.get(),
                                        bool(pulse_snap_var.get()),
                                        sat_mode_var.get()])
                    self._log(f"[pulse-diff] saved {stem}.csv + _metrics.csv")
                _embed_with_save(w, fig, "pulse_diff_montage")
                bot = ttk.Frame(w); bot.pack(fill=tk.X, padx=3, pady=2)
                ttk.Button(bot, text="Save CSV (picks + metrics)",
                            command=_save_csv).pack(side=tk.LEFT, padx=2)

        # ── SYNTHETIC BOLUS from tracked peaks (measured FWHM). ────────
        # Never advertised as raw data — every panel carries a big red
        # watermark; saved filename + metadata mark it synthetic. Peaks
        # + FWHM come from ORIGINAL b_k(s).
        SYNTH_BOLUS_CAPTION = (
            "SYNTHETIC bolus — reconstructed from tracked peaks "
            "(size = measured FWHM), not raw fluorescence")

        def _fig_synthetic_bolus_from_peaks():
            pk = _compute_pulse_arclength()
            if pk is None: return
            if not pk['have_cl']:
                messagebox.showwarning(
                    "Synthetic bolus",
                    "Draw a centerline first — this view is arclength-based."); return
            present = pk['present']; K = len(present)
            if K == 0:
                messagebox.showwarning("Synthetic bolus",
                    "No differential frames to render."); return
            fps, pxu = pk['fps'], pk['pxu']
            Dmap = pk['Dmap']; _sat_mask = pk['_sat_mask']
            centers, tangents = pk['centers'], pk['tangents']
            arclen_um = pk['arclen_um']
            s_star_um, amp_at_star, fwhm_um = (
                pk['s_star_um'], pk['amp_at_star'], pk['fwhm_um'])
            # Frame shape from the first available D
            first_D = Dmap[present[0]]
            H, W = first_D.shape
            # Build one Gaussian blob per frame at the ORIGINAL peak location
            def _make_blob(k):
                # centerline point nearest s*_k
                ci = int(np.argmin(np.abs(arclen_um - s_star_um[k])))
                cy, cx = float(centers[ci][1]), float(centers[ci][0])
                fwhm = fwhm_um[k]
                if not np.isfinite(fwhm) or fwhm <= 0:
                    fwhm = 4.0 * pxu               # fallback: 4 µm
                sigma_um = float(fwhm) / 2.355
                sigma_px = max(1.0, sigma_um / max(pxu, 1e-9))
                yy, xx = np.mgrid[0:H, 0:W]
                g = np.exp(-((xx - cx) ** 2 + (yy - cy) ** 2)
                            / (2.0 * sigma_px * sigma_px))
                if bool(pulse_amp_on_var.get()):
                    a = float(amp_at_star[k])
                    if not np.isfinite(a) or a <= 0: a = 1.0
                    g = g * a
                return g, (cx, cy, sigma_px)
            synth = np.stack([_make_blob(k)[0] for k in range(K)], axis=0)
            # figure: 2 rows (raw D | synthetic) × K cols
            from matplotlib.figure import Figure
            with apply_nature_style():
                cols = min(K, 8)
                rows_needed = 2 * ((K + cols - 1) // cols)
                fig = Figure(figsize=(2.0 * cols, 2.0 * rows_needed),
                              dpi=200, facecolor='white')
                gs = fig.add_gridspec(rows_needed, cols,
                                       hspace=0.35, wspace=0.08)
                vmaxD = 0.0
                for k in range(K):
                    d = _sat_mask(Dmap[present[k]], present[k])
                    v = np.nanpercentile(np.abs(d), 99.0)
                    if np.isfinite(v): vmaxD = max(vmaxD, float(v))
                if vmaxD <= 0: vmaxD = 1.0
                vmaxS = float(np.nanpercentile(synth, 99.5)) if synth.size else 1.0
                if vmaxS <= 0: vmaxS = 1.0
                for k in range(K):
                    r_top = 2 * (k // cols); c_ = k % cols
                    ax_top = fig.add_subplot(gs[r_top, c_])
                    ax_bot = fig.add_subplot(gs[r_top + 1, c_])
                    d = _sat_mask(Dmap[present[k]], present[k])
                    ax_top.imshow(d, cmap='seismic', vmin=-vmaxD, vmax=vmaxD)
                    ax_top.set_title(f"D t={present[k]}\n"
                                       f"({present[k]/max(fps,1e-9):.2f} s)",
                                       fontsize=6)
                    ax_top.set_xticks([]); ax_top.set_yticks([])
                    im = ax_bot.imshow(synth[k], cmap='magma',
                                        vmin=0, vmax=vmaxS)
                    fw = fwhm_um[k]
                    ax_bot.set_title(
                        f"synth  s*={s_star_um[k]:.1f} µm\n"
                        f"FWHM={('%.1f' % fw) if np.isfinite(fw) else 'NaN'} µm",
                        fontsize=6)
                    ax_bot.set_xticks([]); ax_bot.set_yticks([])
                    # watermark on every panel
                    for ax in (ax_top, ax_bot):
                        ax.text(0.5, 0.02, SYNTH_BOLUS_CAPTION,
                                 ha='center', va='bottom',
                                 transform=ax.transAxes,
                                 fontsize=5, color='red', weight='bold',
                                 alpha=0.85,
                                 bbox=dict(boxstyle='round,pad=0.15',
                                             fc='white', ec='red',
                                             alpha=0.6))
                fig.suptitle(SYNTH_BOLUS_CAPTION,
                              color='red', fontsize=8, weight='bold', y=0.995)
                # explicit metadata caption at bottom
                fig.text(0.01, 0.005,
                          f"SYNTHETIC | K={K} frames  |  "
                          f"FWHM range=[{np.nanmin(fwhm_um):.2f}, "
                          f"{np.nanmax(fwhm_um):.2f}] µm  |  "
                          f"amp-weighted={bool(pulse_amp_on_var.get())}",
                          fontsize=5, color='0.35', style='italic')
                w = tk.Toplevel(pw); w.title("SYNTHETIC bolus (peaks + measured FWHM)")
                _embed_with_save(w, fig, "SYNTHETIC_bolus_from_peaks")
                bot = ttk.Frame(w); bot.pack(fill=tk.X, padx=3, pady=2)
                # opt-in GIF export
                def _export_gif():
                    from matplotlib.animation import FuncAnimation, PillowWriter
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Export SYNTHETIC bolus GIF",
                        initialfile="SYNTHETIC_bolus", defaultextension=".gif",
                        filetypes=[("GIF", "*.gif")])
                    if not p: return
                    from matplotlib.figure import Figure
                    from matplotlib.backends.backend_agg import FigureCanvasAgg
                    fig2 = Figure(figsize=(4.0, 4.0), dpi=150, facecolor='white')
                    FigureCanvasAgg(fig2)              # attach an offscreen canvas
                    ax2 = fig2.add_subplot(111)
                    im2 = ax2.imshow(synth[0], cmap='magma',
                                        vmin=0, vmax=vmaxS)
                    tt = ax2.set_title("", fontsize=8)
                    ax2.set_xticks([]); ax2.set_yticks([])
                    ax2.text(0.5, 0.02, SYNTH_BOLUS_CAPTION,
                              ha='center', va='bottom', transform=ax2.transAxes,
                              fontsize=6, color='red', weight='bold', alpha=0.9,
                              bbox=dict(boxstyle='round,pad=0.15',
                                          fc='white', ec='red', alpha=0.6))
                    def _upd(k):
                        im2.set_data(synth[k])
                        tt.set_text(f"SYNTHETIC t={present[k]} "
                                     f"({present[k]/max(fps,1e-9):.2f} s), "
                                     f"FWHM={fwhm_um[k]:.1f} µm")
                        return im2, tt
                    anim = FuncAnimation(fig2, _upd, frames=K,
                                          interval=250, blit=False)
                    anim.save(p, writer=PillowWriter(fps=4))
                    self._log(f"[synth-bolus] saved SYNTHETIC GIF → {p}")
                ttk.Button(bot,
                    text="Export SYNTHETIC GIF (marked)",
                    command=_export_gif).pack(side=tk.LEFT, padx=2)
                # opt-in MP4 export — same watermark + suptitle, same metadata
                def _export_mp4():
                    from matplotlib.animation import FuncAnimation
                    try:
                        from matplotlib.animation import FFMpegWriter
                    except Exception as e:
                        messagebox.showwarning(
                            "MP4 export",
                            f"ffmpeg writer unavailable: {e}\n"
                            "Falling back to GIF instead — same content, different container."); return
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Export SYNTHETIC bolus MP4",
                        initialfile="SYNTHETIC_bolus", defaultextension=".mp4",
                        filetypes=[("MP4", "*.mp4")])
                    if not p: return
                    from matplotlib.figure import Figure
                    from matplotlib.backends.backend_agg import FigureCanvasAgg
                    fig2 = Figure(figsize=(4.5, 4.5), dpi=150, facecolor='white')
                    FigureCanvasAgg(fig2)              # attach an offscreen canvas
                    ax2 = fig2.add_subplot(111)
                    im2 = ax2.imshow(synth[0], cmap='magma',
                                        vmin=0, vmax=vmaxS)
                    tt = ax2.set_title("", fontsize=8)
                    ax2.set_xticks([]); ax2.set_yticks([])
                    ax2.text(0.5, 0.02, SYNTH_BOLUS_CAPTION,
                              ha='center', va='bottom', transform=ax2.transAxes,
                              fontsize=6, color='red', weight='bold', alpha=0.9,
                              bbox=dict(boxstyle='round,pad=0.15',
                                          fc='white', ec='red', alpha=0.6))
                    fig2.suptitle(SYNTH_BOLUS_CAPTION,
                                    color='red', fontsize=8, weight='bold')
                    def _upd(k):
                        im2.set_data(synth[k])
                        tt.set_text(f"SYNTHETIC t={present[k]} "
                                     f"({present[k]/max(fps,1e-9):.2f} s), "
                                     f"FWHM={fwhm_um[k]:.1f} µm")
                        return im2, tt
                    anim = FuncAnimation(fig2, _upd, frames=K,
                                          interval=250, blit=False)
                    writer = FFMpegWriter(fps=4, bitrate=800,
                                            metadata=dict(
                                                title='SYNTHETIC bolus (peaks + measured FWHM)',
                                                artist='SLIM Lymphatic Pulse Analyzer',
                                                comment=SYNTH_BOLUS_CAPTION))
                    try:
                        anim.save(p, writer=writer)
                        self._log(f"[synth-bolus] saved SYNTHETIC MP4 → {p}")
                    except Exception as e:
                        messagebox.showwarning(
                            "MP4 export failed",
                            f"Could not save MP4: {e}")
                ttk.Button(bot,
                    text="Export SYNTHETIC MP4 (marked)",
                    command=_export_mp4).pack(side=tk.LEFT, padx=2)
                # opt-in JSON sidecar with the exact provenance
                def _save_synth_metadata():
                    import json as _json
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save SYNTHETIC bolus metadata JSON",
                        initialfile="SYNTHETIC_bolus_metadata",
                        defaultextension=".json",
                        filetypes=[("JSON", "*.json")])
                    if not p: return
                    meta = dict(
                        kind="SYNTHETIC_bolus_from_peaks",
                        caption=SYNTH_BOLUS_CAPTION,
                        fps=float(fps),
                        pxu_um_per_px=float(pxu),
                        K=int(K),
                        amp_weighted=bool(pulse_amp_on_var.get()),
                        frames_original=[int(x) for x in present],
                        time_s=[float(x/max(fps,1e-9)) for x in present],
                        s_star_um=[float(x) for x in s_star_um],
                        amp_at_star=[float(x) for x in amp_at_star],
                        fwhm_um=[(float(x) if np.isfinite(x) else None)
                                  for x in fwhm_um],
                        suppression_display_only=bool(pulse_supp_on_var.get()),
                        suppression_params=dict(
                            w_um=float(pulse_supp_w_var.get()),
                            taper_um=float(pulse_supp_tap_var.get()),
                            floor=float(pulse_supp_flr_var.get())),
                        peak_source="ORIGINAL b_k(s) (LINEAR + BG-only, unsuppressed)",
                        warning=("This dataset is SYNTHETIC. Do NOT combine "
                                  "with raw fluorescence data without keeping "
                                  "this metadata attached."),
                    )
                    with open(p, "w") as f:
                        _json.dump(meta, f, indent=2)
                    self._log(f"[synth-bolus] wrote metadata sidecar → {p}")
                ttk.Button(bot,
                    text="Save metadata JSON",
                    command=_save_synth_metadata).pack(side=tk.LEFT, padx=2)
                ttk.Label(bot,
                    text=SYNTH_BOLUS_CAPTION,
                    foreground='red').pack(side=tk.LEFT, padx=6)
                self._log(f"[synth-bolus] rendered K={K} frames "
                          f"(s* on ORIGINAL b(s); "
                          f"FWHM=[{np.nanmin(fwhm_um):.2f},"
                          f"{np.nanmax(fwhm_um):.2f}] µm; "
                          f"amp-weighted={bool(pulse_amp_on_var.get())})")

        # ── PEAK TRAJECTORY figure: s*(t), A(t), ds/dt(t), + aligned kymo ──
        def _fig_peak_trajectory_from_peaks():
            pk = _compute_pulse_arclength()
            if pk is None: return
            if not pk['have_cl']:
                messagebox.showwarning(
                    "Peak trajectory",
                    "Draw a centerline first — this view is arclength-based."); return
            fps = pk['fps']; present = pk['present']
            s_star = pk['s_star_um']; amp = pk['amp_at_star']
            arclen_um = pk['arclen_um']; b_profiles = pk['b_profiles']
            K = len(present)
            if K < 2:
                messagebox.showwarning("Peak trajectory",
                    "Need ≥2 frames for a trajectory."); return
            t_s = np.array([f / max(fps, 1e-9) for f in present], dtype=float)
            # ds/dt from centered finite differences
            ds_dt = np.gradient(s_star, t_s)
            # Robust regression on line 1 (main). Quality gates + RANSAC
            # (or configured estimator); R² reported on INLIERS only, with
            # n_inliers/n_total shown for transparency.
            rf = _robust_peak_fit(pk)
            m_s, b_s = rf['slope'], rf['intercept']
            r2 = rf['r2_inliers']
            inlier_all = rf['inlier_all']            # bool over ALL frames
            pass_all   = rf['pass_mask']             # frames that passed quality gate
            outlier_all = pass_all & ~inlier_all     # gate-passed but RANSAC-rejected
            gate_rejected = ~pass_all                # dropped by quality gate
            self._log(
                f"[peak-traj] robust fit ({rf['estimator']}): "
                f"slope={m_s:+.3f} µm/s  R²(inliers)={r2:.3f}  "
                f"n_inliers/n_total={rf['n_inliers']}/{rf['n_total']}  "
                f"gate-passed={rf['n_kept']}  "
                f"inlier_frac={rf['inlier_frac']:.2f}  "
                f"resid_std={rf['residual_std']:.2f} µm  "
                f"direction={rf['direction']}  "
                f"low_confidence={rf['low_confidence']}")
            if rf['low_confidence']:
                messagebox.showwarning(
                    "Low-confidence fit",
                    f"Fit is flagged low-confidence:\n\n"
                    f"estimator: {rf['estimator']}\n"
                    f"slope: {m_s:+.3f} µm/s ({rf['direction']})\n"
                    f"R²(inliers): {r2:.3f}\n"
                    f"n_inliers/n_total: {rf['n_inliers']}/{rf['n_total']}\n"
                    f"inlier_frac: {rf['inlier_frac']:.2f}\n\n"
                    f"Tune min-prom / k·MAD / RANSAC thr or pick more frames.")
            from matplotlib.figure import Figure
            with apply_nature_style():
                fig = Figure(figsize=(7.0, 6.0), dpi=150, facecolor='white')
                gs = fig.add_gridspec(4, 1, height_ratios=[1, 1, 1, 1.4],
                                       hspace=0.35)
                ax1 = fig.add_subplot(gs[0])
                ax2 = fig.add_subplot(gs[1], sharex=ax1)
                ax3 = fig.add_subplot(gs[2], sharex=ax1)
                ax4 = fig.add_subplot(gs[3], sharex=ax1)
                # (a) s*(t) + robust regression — inliers filled circles;
                # RANSAC-rejected outliers = open circles; quality-gated =
                # 'x'. Overlay robust fit line and honest annotation.
                _c_main = OKABE_ITO[0]
                ax1.plot(t_s[inlier_all], s_star[inlier_all], 'o',
                          color=_c_main, ms=4.5, mec='k', mew=0.4,
                          label=f"L1 inlier ({rf['n_inliers']}/{rf['n_total']})")
                if outlier_all.any():
                    ax1.plot(t_s[outlier_all], s_star[outlier_all], 'o',
                              mfc='none', mec=_c_main, ms=4.5, mew=1.0,
                              label='L1 outlier')
                if gate_rejected.any():
                    ax1.plot(t_s[gate_rejected], s_star[gate_rejected], 'x',
                              color=_c_main, ms=5, mew=1.0, alpha=0.7,
                              label='L1 gate-rejected')
                # Robust fit line
                if np.isfinite(m_s):
                    tt = np.linspace(t_s[0], t_s[-1], 100)
                    ax1.plot(tt, m_s * tt + b_s, '--',
                              color=OKABE_ITO[1], lw=1.1,
                              label=(f"L1 {rf['estimator']}: "
                                      f"{m_s:+.2f} µm/s  R²={r2:.3f}"))
                # Deletion gaps: connect only within contiguous KEPT runs
                # (otherwise the raw dashed connector below misleads).
                # We plot the raw s*(t) faintly to give shape context.
                ax1.plot(t_s, s_star, ':', color=_c_main, lw=0.6, alpha=0.35)
                # Extra lines: robust fit per line, overlay
                extra_fits = []
                incl_traj = st.get('include_lines', [True, False, False])
                for _li in range(MAX_LINES):
                    if _li == 0: continue
                    if not (_li < len(incl_traj) and incl_traj[_li]): continue
                    cl_i = st['centerlines'][_li]
                    if cl_i is None or len(cl_i) < 2: continue
                    pk_i = _compute_pulse_arclength(cl_override=cl_i)
                    if pk_i is None or not pk_i['have_cl']: continue
                    if len(pk_i['present']) < 2: continue
                    rf_i = _robust_peak_fit(pk_i)
                    t_i = rf_i['t']; s_i = rf_i['s']
                    inl_i = rf_i['inlier_all']
                    out_i = rf_i['pass_mask'] & ~inl_i
                    col = LINE_COLORS[_li]
                    ax1.plot(t_i[inl_i], s_i[inl_i], 'o', color=col,
                              ms=3.5, mec='k', mew=0.4,
                              label=f"L{_li+1} inlier ({rf_i['n_inliers']}/{rf_i['n_total']})")
                    if out_i.any():
                        ax1.plot(t_i[out_i], s_i[out_i], 'o', mfc='none',
                                  mec=col, ms=3.5, mew=0.9,
                                  label=f"L{_li+1} outlier")
                    if np.isfinite(rf_i['slope']):
                        tt_i = np.linspace(t_i[0], t_i[-1], 100)
                        ax1.plot(tt_i,
                                  rf_i['slope'] * tt_i + rf_i['intercept'],
                                  '--', color=col, lw=0.9,
                                  label=(f"L{_li+1} {rf_i['estimator']}: "
                                          f"{rf_i['slope']:+.2f} µm/s "
                                          f"R²={rf_i['r2_inliers']:.3f}"))
                    extra_fits.append(dict(
                        line=_li + 1, present=pk_i['present'],
                        t=t_i, s=s_i, amp=pk_i['amp_at_star'],
                        m=float(rf_i['slope']), b=float(rf_i['intercept']),
                        r2=float(rf_i['r2_inliers']),
                        inlier=inl_i, gate_pass=rf_i['pass_mask'],
                        n_inliers=rf_i['n_inliers'],
                        n_total=rf_i['n_total'],
                        residual_std=rf_i['residual_std'],
                        estimator=rf_i['estimator'],
                        direction=rf_i['direction'],
                        fwhm=pk_i['fwhm_um']))
                ax1.set_ylabel("s* (µm)")
                ax1.legend(loc='best', frameon=False, fontsize=5, ncol=2)
                despine_lr(ax1); panel_letter(ax1, 'a', x=-0.05, y=1.05)
                # honest annotation
                _ann = (f"{rf['estimator']}  |  "
                          f"slope={m_s:+.2f} µm/s ({rf['direction']})  "
                          f"R²(inliers)={r2:.3f}  "
                          f"n_in/n_tot={rf['n_inliers']}/{rf['n_total']}  "
                          f"resid_std={rf['residual_std']:.2f} µm")
                if rf['low_confidence']:
                    _ann += "  [LOW CONFIDENCE]"
                ax1.set_title(_ann, fontsize=6,
                                color=('red' if rf['low_confidence'] else '#333'))
                # (b) A(t)
                ax2.plot(t_s, amp, 's-', color=OKABE_ITO[2], lw=1.0, ms=4)
                ax2.set_ylabel("A (peak amp)")
                despine_lr(ax2); panel_letter(ax2, 'b', x=-0.05, y=1.05)
                # (c) ds/dt(t)
                ax3.plot(t_s, ds_dt, '^-', color=OKABE_ITO[3], lw=1.0, ms=4)
                ax3.axhline(0, color='0.6', lw=0.6, ls=':')
                ax3.set_ylabel("ds*/dt (µm/s)")
                despine_lr(ax3); panel_letter(ax3, 'c', x=-0.05, y=1.05)
                # (d) aligned ORIGINAL kymograph + s*(t) overlay
                B = np.stack(b_profiles, axis=1)
                vmax = float(np.nanpercentile(B, 99)) if B.size else 1.0
                if vmax <= 0: vmax = 1.0
                # extent: x=time, y=arclength
                imk = ax4.imshow(B, aspect='auto', cmap='viridis',
                                    vmin=0, vmax=vmax,
                                    extent=[t_s[0], t_s[-1],
                                              arclen_um[-1], 0],
                                    interpolation='nearest')
                # Raw s*(t) markers on the kymograph — inliers filled, outliers open
                ax4.plot(t_s[inlier_all], s_star[inlier_all], 'o',
                          color='w', ms=3.5, mec='k', mew=0.4,
                          label='s* inlier')
                if outlier_all.any():
                    ax4.plot(t_s[outlier_all], s_star[outlier_all], 'o',
                              mfc='none', mec='w', ms=3.5, mew=0.8,
                              label='s* outlier')
                if gate_rejected.any():
                    ax4.plot(t_s[gate_rejected], s_star[gate_rejected], 'x',
                              color='#ffe08a', ms=4, mew=1.0, alpha=0.85,
                              label='gate-rejected')
                # Robust fit line overlaid so the cleaned trajectory is
                # visible against the data.
                if np.isfinite(m_s):
                    tt_k = np.linspace(t_s[0], t_s[-1], 100)
                    s_hat = np.clip(m_s * tt_k + b_s,
                                     float(arclen_um[0]),
                                     float(arclen_um[-1]))
                    ax4.plot(tt_k, s_hat, '-', color='#FFB000', lw=1.2,
                              label=f"{rf['estimator']}")
                ax4.set_xlabel("time (s)"); ax4.set_ylabel("arclength (µm)")
                ax4.legend(loc='upper right', frameon=False, fontsize=6)
                slim_colorbar(imk, ax4, "b_k(s) (ORIGINAL)")
                panel_letter(ax4, 'd', x=-0.05, y=1.05)
                fig.text(0.99, 0.005,
                          "Peak positions, amplitudes, and derivatives are on "
                          "ORIGINAL b(s) (suppression is display-only).",
                          ha='right', va='bottom', fontsize=5,
                          color='0.35', style='italic')
                fig.tight_layout(rect=(0, 0.02, 1, 1))
                w = tk.Toplevel(pw); w.title("Peak trajectory (from tracked peaks)")
                _embed_with_save(w, fig, "peak_trajectory")
                bot = ttk.Frame(w); bot.pack(fill=tk.X, padx=3, pady=2)
                def _save_traj_csv():
                    import csv as _csv
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save peak trajectory CSV",
                        initialfile="peak_trajectory",
                        defaultextension=".csv",
                        filetypes=[("CSV", "*.csv")])
                    if not p: return
                    stem = os.path.splitext(p)[0]
                    with open(stem + ".csv", "w", newline="") as f:
                        wcsv = _csv.writer(f)
                        wcsv.writerow(['frame_orig', 'time_s',
                                        's_star_um', 'A_peak',
                                        'ds_dt_um_per_s',
                                        'FWHM_um',
                                        'gate_passed', 'inlier'])
                        for k, fi in enumerate(present):
                            wcsv.writerow([int(fi), float(t_s[k]),
                                            float(s_star[k]),
                                            float(amp[k]),
                                            float(ds_dt[k]),
                                            float(pk['fwhm_um'][k]),
                                            int(bool(pass_all[k])),
                                            int(bool(inlier_all[k]))])
                    with open(stem + "_fit.csv", "w", newline="") as f:
                        wcsv = _csv.writer(f)
                        wcsv.writerow(['estimator', 'slope_um_per_s',
                                        'intercept_um', 'R2_inliers',
                                        'pearson_r_inliers',
                                        'residual_std_um',
                                        'n_inliers', 'n_total',
                                        'inlier_frac',
                                        'residual_thr_um',
                                        'direction', 'low_confidence',
                                        'note'])
                        wcsv.writerow([rf['estimator'], m_s, b_s, r2,
                                        rf['pearson_r'], rf['residual_std'],
                                        rf['n_inliers'], rf['n_total'],
                                        rf['inlier_frac'],
                                        rf['residual_thr'],
                                        rf['direction'],
                                        int(rf['low_confidence']),
                                        "peaks on ORIGINAL b(s); "
                                        "R² and residuals on INLIERS only"])
                    self._log(f"[peak-traj] saved {stem}.csv + _fit.csv")
                ttk.Button(bot, text="Save trajectory CSV",
                            command=_save_traj_csv).pack(side=tk.LEFT, padx=2)
                # Per-line CSV (line_id, time, s, A, velocity, direction)
                def _save_per_line_csv():
                    import csv as _csv
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save per-line trajectory CSV",
                        initialfile="peak_trajectory_per_line",
                        defaultextension=".csv",
                        filetypes=[("CSV", "*.csv")])
                    if not p: return
                    stem = os.path.splitext(p)[0]
                    with open(stem + ".csv", "w", newline="") as f:
                        wcsv = _csv.writer(f)
                        wcsv.writerow(['line_id', 'frame_orig', 'time_s',
                                        's_star_um', 'A_peak',
                                        'ds_dt_um_per_s',
                                        'FWHM_um'])
                        # Line 1 rows
                        for k, fi in enumerate(present):
                            wcsv.writerow([1, int(fi), float(t_s[k]),
                                            float(s_star[k]),
                                            float(amp[k]),
                                            float(ds_dt[k]),
                                            float(pk['fwhm_um'][k])])
                        # Extras
                        for ef in extra_fits:
                            ds_i = np.gradient(ef['s'], ef['t'])
                            for k, fi in enumerate(ef['present']):
                                wcsv.writerow([ef['line'], int(fi),
                                                float(ef['t'][k]),
                                                float(ef['s'][k]),
                                                float(ef['amp'][k]),
                                                float(ds_i[k]),
                                                float(ef['fwhm'][k])
                                                if np.isfinite(ef['fwhm'][k])
                                                else ''])
                    with open(stem + "_fits.csv", "w", newline="") as f:
                        wcsv = _csv.writer(f)
                        wcsv.writerow(['line_id', 'slope_um_per_s',
                                        'intercept_um', 'R2',
                                        'direction'])
                        wcsv.writerow([1, m_s, b_s, r2,
                                        ('forward' if m_s > 0 else
                                         'reverse' if m_s < 0 else 'still')])
                        for ef in extra_fits:
                            wcsv.writerow([ef['line'], ef['m'], ef['b'],
                                            ef['r2'],
                                            ('forward' if ef['m'] > 0 else
                                             'reverse' if ef['m'] < 0 else 'still')])
                    self._log(f"[peak-traj] wrote per-line CSV → {stem}.csv "
                              f"+ _fits.csv (lines: 1 + {len(extra_fits)} sub)")
                ttk.Button(bot, text="Save per-line CSV",
                            command=_save_per_line_csv).pack(side=tk.LEFT, padx=2)
                # JSON metadata sidecar — same rules as synthetic bolus, so
                # this record is standalone-readable without the main GUI.
                def _save_traj_meta_json():
                    import json as _json
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save peak trajectory metadata JSON",
                        initialfile="peak_trajectory_meta",
                        defaultextension=".json",
                        filetypes=[("JSON", "*.json")])
                    if not p: return
                    meta = dict(
                        kind="peak_trajectory_from_peaks",
                        fps=float(fps),
                        K=int(K),
                        frames_original=[int(x) for x in present],
                        time_s=[float(x) for x in t_s.tolist()],
                        s_star_um=[float(x) for x in s_star.tolist()],
                        amp_at_star=[float(x) for x in amp.tolist()],
                        ds_dt_um_per_s=[float(x) for x in ds_dt.tolist()],
                        fwhm_um=[(float(x) if np.isfinite(x) else None)
                                  for x in pk['fwhm_um']],
                        linear_fit=dict(
                            slope_um_per_s=float(m_s),
                            intercept_um=float(b_s),
                            R2=float(r2),
                        ),
                        peak_source="ORIGINAL b_k(s) (LINEAR + BG-only)",
                        suppression_display_only=bool(pulse_supp_on_var.get()),
                        note=("Every quantity here is derived on the "
                                "ORIGINAL, unsuppressed b(s). Peak-focused "
                                "suppression, if enabled in the pulse "
                                "differential figure, is a display artifact "
                                "and never touches these numbers."),
                    )
                    with open(p, "w") as f:
                        _json.dump(meta, f, indent=2)
                    self._log(f"[peak-traj] wrote metadata sidecar → {p}")
                ttk.Button(bot, text="Save metadata JSON",
                            command=_save_traj_meta_json).pack(side=tk.LEFT, padx=2)
                self._log(f"[peak-traj] slope={m_s:.3f} µm/s  "
                          f"intercept={b_s:.2f} µm  R²={r2:.3f}  K={K}")

        # ── BEFORE/AFTER SUPPRESSION COMPARISON WINDOW ──────────────────
        # Diagnostic figure: same K frames, shown as (top row) ORIGINAL b(s)
        # curves, (middle row) suppressed b(s) curves, (bottom row) two-panel
        # kymograph (ORIGINAL | suppressed). Quantitative peak markers overlay
        # both rows so users can verify the display transform has not moved
        # the true peak position.
        def _fig_pulse_suppression_compare():
            pk = _compute_pulse_arclength()
            if pk is None: return
            if not pk['have_cl']:
                messagebox.showwarning(
                    "Suppression compare",
                    "Draw a centerline first — this view is arclength-based."); return
            b_profiles = pk['b_profiles']; arclen_um = pk['arclen_um']
            present = pk['present']; fps = pk['fps']
            s_star_um = pk['s_star_um']
            if not b_profiles:
                messagebox.showwarning("Suppression compare",
                    "No arclength profiles available."); return
            supp_w = float(pulse_supp_w_var.get())
            supp_t = float(pulse_supp_tap_var.get())
            supp_f = float(pulse_supp_flr_var.get())
            from matplotlib.figure import Figure
            with apply_nature_style():
                fig = Figure(figsize=(9.0, 6.0), dpi=150, facecolor='white')
                gs = fig.add_gridspec(3, 1, height_ratios=[1, 1, 1.4],
                                       hspace=0.5)
                axA = fig.add_subplot(gs[0])
                axB = fig.add_subplot(gs[1], sharex=axA)
                axC_par = fig.add_subplot(gs[2])
                axC_par.set_axis_off()
                gsC = axC_par.get_gridspec()[2].subgridspec(
                    1, 2, wspace=0.15)
                axC1 = fig.add_subplot(gsC[0, 0])
                axC2 = fig.add_subplot(gsC[0, 1], sharey=axC1)
                K = len(b_profiles)
                offsets = np.linspace(0, 1, max(1, K)) * 0.6
                # Top: ORIGINAL curves (quantitative basis)
                for i, (b, t) in enumerate(zip(b_profiles, present)):
                    color = OKABE_ITO[i % len(OKABE_ITO)]
                    bmax = max(np.nanmax(b) - np.nanmin(b), 1e-12)
                    norm = (b - np.nanmin(b)) / bmax
                    axA.plot(arclen_um, norm + offsets[i], color=color, lw=1.0,
                              label=f"t={t}")
                    pk_i = int(np.argmax(b))
                    axA.plot(arclen_um[pk_i], (norm + offsets[i])[pk_i], 'v',
                              color=color, ms=4, mec='k', mew=0.5)
                axA.set_ylabel("ORIGINAL\nb_k(s) (norm)")
                axA.legend(loc='upper right', frameon=False, fontsize=5,
                            ncol=2)
                despine_lr(axA); panel_letter(axA, 'a', x=-0.05, y=1.05)
                # Middle: SUPPRESSED curves (display copy only)
                for i, (b, t) in enumerate(zip(b_profiles, present)):
                    color = OKABE_ITO[i % len(OKABE_ITO)]
                    pk_i = int(np.argmax(b))
                    wgt = _peak_suppression_weights(arclen_um, arclen_um[pk_i])
                    b_supp = b * wgt
                    bmax = max(np.nanmax(b_supp) - np.nanmin(b_supp), 1e-12)
                    norm = (b_supp - np.nanmin(b_supp)) / bmax
                    axB.plot(arclen_um, norm + offsets[i],
                              color=color, lw=1.0)
                    axB.plot(arclen_um[pk_i], (norm + offsets[i])[pk_i], 'v',
                              color=color, ms=4, mec='k', mew=0.5)
                axB.set_xlabel("arclength s (µm)")
                axB.set_ylabel(f"SUPPRESSED (display)\n"
                                f"w={supp_w:.0f} taper={supp_t:.0f} "
                                f"floor={supp_f:.2f}")
                despine_lr(axB); panel_letter(axB, 'b', x=-0.05, y=1.05)
                # Bottom: ORIGINAL | SUPPRESSED kymos
                B = np.stack(b_profiles, axis=1)
                W_mat = np.stack([
                    _peak_suppression_weights(arclen_um, s_star_um[k])
                    for k in range(K)], axis=1)
                B_supp = B * W_mat
                vmax1 = float(np.nanpercentile(B, 99)) if B.size else 1.0
                if vmax1 <= 0: vmax1 = 1.0
                vmax2 = float(np.nanpercentile(B_supp, 99)) if B_supp.size else 1.0
                if vmax2 <= 0: vmax2 = 1.0
                # Preserve identical y-extent so overlays are comparable
                im1 = axC1.imshow(B, aspect='auto', cmap='viridis',
                                     vmin=0, vmax=vmax1,
                                     extent=[0, K, arclen_um[-1], 0],
                                     interpolation='nearest')
                im2 = axC2.imshow(B_supp, aspect='auto', cmap='viridis',
                                     vmin=0, vmax=vmax2,
                                     extent=[0, K, arclen_um[-1], 0],
                                     interpolation='nearest')
                peak_si = np.array([int(np.argmax(b)) for b in b_profiles])
                for ax in (axC1, axC2):
                    ax.plot(np.arange(K) + 0.5, arclen_um[peak_si], 'o-',
                             color=OKABE_ITO[6], lw=0.9, ms=3,
                             mec='k', mew=0.4)
                    ax.set_xticks(np.arange(K) + 0.5)
                    ax.set_xticklabels([f"{t/max(fps,1e-9):.1f}"
                                          for t in present],
                                          rotation=45, ha='right')
                axC1.set_title("ORIGINAL kymo", fontsize=7)
                axC1.set_ylabel("arclength s (µm)")
                axC2.set_title("SUPPRESSED kymo (display)", fontsize=7)
                slim_colorbar(im1, axC1, "b (orig)")
                slim_colorbar(im2, axC2, "b (supp)")
                panel_letter(axC1, 'c', x=-0.06, y=1.05)
                fig.suptitle(
                    "Suppression compare — peaks (▽) overlaid come from "
                    "ORIGINAL b(s) and must line up in BOTH rows.",
                    fontsize=8, y=0.998)
                w = tk.Toplevel(pw)
                w.title("Peak suppression compare (before / after)")
                _embed_with_save(w, fig, "pulse_suppression_compare")
                self._log(f"[supp-compare] K={K}, peaks OK on ORIGINAL basis; "
                          f"w={supp_w} taper={supp_t} floor={supp_f}")

        # ── WHOLE-RECORDING peak trajectory ─────────────────────────────
        # Runs the same s*(t) / A(t) / ds*/dt(t) pipeline as
        # `_fig_peak_trajectory_from_peaks`, but iterates over every KEPT
        # frame (subsampled by `pulse_whole_step_var`) instead of the picked
        # subset in the "frames" field. Uses a fixed reference frame
        # (`pulse_whole_ref_var`) so all D_k = f_k - f_ref share a baseline.
        def _fig_peak_trajectory_whole():
            from slim_recon.layered_export import parse_frame_spec
            proj_lin = _need_proj()
            T_ = st['proj'].shape[0]
            fps = float(fps_var.get()); pxu = float(px_var.get())
            cl = st.get('centerline')
            if cl is None or len(cl) < 2:
                messagebox.showwarning("Peak trajectory (whole)",
                    "Draw a centerline first."); return
            deleted = st['deleted_frames']
            valid_idx = (st['cleaned_to_orig'] if st['cleaned_to_orig'] is not None
                         else np.arange(T_, dtype=int))
            step = max(1, int(pulse_whole_step_var.get()))
            ref = int(pulse_whole_ref_var.get())
            if ref < 0 or ref >= T_:
                messagebox.showwarning("Peak trajectory (whole)",
                    f"ref={ref} out of range [0,{T_-1}]"); return
            if ref in deleted:
                if valid_idx.size == 0:
                    messagebox.showwarning("Peak trajectory (whole)",
                        "No kept frames available."); return
                new_ref = int(valid_idx[int(np.argmin(np.abs(valid_idx - ref)))])
                self._log(f"[peak-traj/whole] ref={ref} was deleted, "
                          f"snapped to nearest kept t={new_ref}")
                ref = new_ref
            kept = [int(f) for f in valid_idx.tolist() if int(f) != ref]
            kept = sorted(kept)[::step]
            if len(kept) < 2:
                messagebox.showwarning("Peak trajectory (whole)",
                    f"Need ≥2 kept frames after subsample (got {len(kept)})."); return
            self._log(f"[peak-traj/whole] ref={ref}, K={len(kept)} frames "
                      f"(step={step})")
            # Saturation once
            try:
                sat = _ensure_sat()
                sat_frac = float(st.get('sat_total_frac') or 0.0)
            except Exception:
                sat = None; sat_frac = 0.0
            proj_meas = _proj_for_measurement()
            tau = max(1, int(pulse_tauwin_var.get()))
            if tau > 1:
                from scipy.ndimage import uniform_filter1d
                proj_meas = uniform_filter1d(proj_meas, size=tau,
                                                axis=0, mode='nearest')
            def _sat_mask(d, t):
                if sat is None or t >= sat.shape[0]:
                    return d
                m = sat[min(t, sat.shape[0] - 1)]
                if not m.any(): return d
                out = d.astype(np.float32, copy=True); out[m] = np.nan
                return out
            N = max(16, int(n_pts_var.get()) * 2)
            centers, tangents, arclen_px = _sample_along_polyline(cl, N)
            arclen_um = arclen_px * pxu
            ref_img = proj_meas[ref].astype(np.float32)
            sigma = float(pulse_sigma_var.get())
            if sigma > 0:
                from scipy.ndimage import gaussian_filter
                ref_img = gaussian_filter(ref_img, sigma=sigma)
            s_star_um   = np.zeros(len(kept), dtype=np.float32)
            amp_at_star = np.zeros(len(kept), dtype=np.float32)
            fwhm_um_arr = np.full(len(kept), np.nan, dtype=np.float32)
            B_cols = []
            skipped = 0
            for k, t in enumerate(kept):
                img = proj_meas[t].astype(np.float32)
                if sigma > 0:
                    from scipy.ndimage import gaussian_filter
                    img = gaussian_filter(img, sigma=sigma)
                d = img - ref_img                              # simple ref-diff
                d = _sat_mask(d, t)
                # positive part on centerline arclength
                b = arclength_profile(np.maximum(np.nan_to_num(d, nan=0.0), 0),
                                        centers, tangents, pxu,
                                        cross_half_px=int(band_var.get()))
                if not np.isfinite(b).any() or float(np.nanmax(b)) <= 0:
                    B_cols.append(np.zeros_like(arclen_um, dtype=np.float32))
                    skipped += 1; continue
                pk_i = int(np.argmax(b))
                s_star_um[k]   = float(arclen_um[pk_i])
                amp_at_star[k] = float(b[pk_i])
                fwhm_um_arr[k] = _fwhm_of_arclength_profile(b, arclen_um, pk_i)
                B_cols.append(b.astype(np.float32, copy=False))
            if skipped:
                self._log(f"[peak-traj/whole] {skipped} frames had zero b(s) "
                          f"(likely noise-only diffs)")
            B = np.stack(B_cols, axis=1)
            t_s = np.array([f / max(fps, 1e-9) for f in kept], dtype=float)
            ds_dt = np.gradient(s_star_um.astype(float), t_s)
            valid_fit = np.isfinite(s_star_um) & (amp_at_star > 0)
            if valid_fit.sum() >= 2:
                coef = np.polyfit(t_s[valid_fit], s_star_um[valid_fit], 1)
                m_s, b_s = float(coef[0]), float(coef[1])
                resid = s_star_um[valid_fit] - (m_s * t_s[valid_fit] + b_s)
                r2 = float(1.0 - (np.var(resid)
                                    / (np.var(s_star_um[valid_fit]) + 1e-12)))
            else:
                m_s, b_s, r2 = float('nan'), float('nan'), float('nan')
            from matplotlib.figure import Figure
            with apply_nature_style():
                fig = Figure(figsize=(8.0, 6.5), dpi=150, facecolor='white')
                gs = fig.add_gridspec(4, 1, height_ratios=[1, 1, 1, 1.5],
                                       hspace=0.4)
                ax1 = fig.add_subplot(gs[0])
                ax2 = fig.add_subplot(gs[1], sharex=ax1)
                ax3 = fig.add_subplot(gs[2], sharex=ax1)
                ax4 = fig.add_subplot(gs[3], sharex=ax1)
                ax1.plot(t_s, s_star_um, '-', color=OKABE_ITO[0], lw=0.8,
                          label='s* (µm)')
                if np.isfinite(m_s):
                    tt = np.linspace(t_s[0], t_s[-1], 200)
                    ax1.plot(tt, m_s * tt + b_s, '--',
                              color=OKABE_ITO[1], lw=0.8,
                              label=f"fit {m_s:.2f} µm/s  R²={r2:.3f}")
                ax1.set_ylabel("s* (µm)")
                ax1.legend(loc='best', frameon=False, fontsize=6)
                despine_lr(ax1); panel_letter(ax1, 'a', x=-0.05, y=1.05)
                ax2.plot(t_s, amp_at_star, '-', color=OKABE_ITO[2], lw=0.8)
                ax2.set_ylabel("A (peak amp)")
                despine_lr(ax2); panel_letter(ax2, 'b', x=-0.05, y=1.05)
                ax3.plot(t_s, ds_dt, '-', color=OKABE_ITO[3], lw=0.8)
                ax3.axhline(0, color='0.6', lw=0.6, ls=':')
                ax3.set_ylabel("ds*/dt (µm/s)")
                despine_lr(ax3); panel_letter(ax3, 'c', x=-0.05, y=1.05)
                vmax = float(np.nanpercentile(B, 99)) if B.size else 1.0
                if vmax <= 0: vmax = 1.0
                imk = ax4.imshow(B, aspect='auto', cmap='viridis',
                                    vmin=0, vmax=vmax,
                                    extent=[t_s[0], t_s[-1],
                                              arclen_um[-1], 0],
                                    interpolation='nearest')
                ax4.plot(t_s, s_star_um, '-', color='w', lw=0.8, alpha=0.9,
                          label='s*(t)')
                ax4.set_xlabel("time (s)")
                ax4.set_ylabel("arclength (µm)")
                ax4.legend(loc='upper right', frameon=False, fontsize=6)
                slim_colorbar(imk, ax4, "b_k(s) (ORIGINAL)")
                panel_letter(ax4, 'd', x=-0.05, y=1.05)
                fig.suptitle(
                    f"Peak trajectory (whole recording)  "
                    f"ref t={ref}, step={step}, K={len(kept)}",
                    fontsize=8, y=0.995)
                fig.text(0.99, 0.005,
                          "All quantities on ORIGINAL b(s). "
                          "Suppression is display-only in the pulse "
                          "differential figure and never applied here.",
                          ha='right', va='bottom', fontsize=5,
                          color='0.35', style='italic')
                fig.tight_layout(rect=(0, 0.02, 1, 1))
                w = tk.Toplevel(pw)
                w.title("Peak trajectory (whole recording)")
                _embed_with_save(w, fig, "peak_trajectory_whole")
                bot = ttk.Frame(w); bot.pack(fill=tk.X, padx=3, pady=2)
                def _save_whole_csv():
                    import csv as _csv
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save whole-recording trajectory CSV",
                        initialfile="peak_trajectory_whole",
                        defaultextension=".csv",
                        filetypes=[("CSV", "*.csv")])
                    if not p: return
                    stem = os.path.splitext(p)[0]
                    with open(stem + ".csv", "w", newline="") as f:
                        wcsv = _csv.writer(f)
                        wcsv.writerow(['frame_orig', 'time_s',
                                        's_star_um', 'A_peak',
                                        'ds_dt_um_per_s', 'FWHM_um'])
                        for k, fi in enumerate(kept):
                            wcsv.writerow([int(fi), float(t_s[k]),
                                            float(s_star_um[k]),
                                            float(amp_at_star[k]),
                                            float(ds_dt[k]),
                                            (float(fwhm_um_arr[k])
                                             if np.isfinite(fwhm_um_arr[k])
                                             else '')])
                    with open(stem + "_fit.csv", "w", newline="") as f:
                        wcsv = _csv.writer(f)
                        wcsv.writerow(['slope_um_per_s', 'intercept_um',
                                        'R2', 'K',
                                        'ref_frame', 'step',
                                        'sigma_xy', 'tau_win',
                                        'saturated_frac'])
                        wcsv.writerow([m_s, b_s, r2, len(kept),
                                        int(ref), int(step),
                                        float(pulse_sigma_var.get()),
                                        int(pulse_tauwin_var.get()),
                                        float(sat_frac)])
                    self._log(f"[peak-traj/whole] saved {stem}.csv + _fit.csv")
                ttk.Button(bot, text="Save trajectory CSV (whole)",
                            command=_save_whole_csv).pack(side=tk.LEFT, padx=2)
                self._log(f"[peak-traj/whole] slope={m_s:.3f} µm/s "
                          f"intercept={b_s:.2f} µm  R²={r2:.3f}  "
                          f"K={len(kept)} (skipped={skipped})")

        # ── PEAK SANITY SUMMARY table window ────────────────────────────
        # A quick tabular dump of the picked-peak provenance for the frames
        # currently listed in "frames": t_orig, t_cleaned, time_s, s* (µm),
        # A, FWHM (µm), and a flag column noting any suppression setting that
        # was ON at the time this row was captured (so lab notes match the
        # exact numeric provenance downstream code will see in the CSVs).
        def _open_peak_sanity_summary():
            pk = _compute_pulse_arclength()
            if pk is None: return
            if not pk['have_cl']:
                messagebox.showwarning("Peak sanity summary",
                    "Draw a centerline first — this view is arclength-based."); return
            present = pk['present']
            fps = pk['fps']
            s_star = pk['s_star_um']; amp = pk['amp_at_star']
            fwhm = pk['fwhm_um']
            o2c = st['orig_to_cleaned']
            w = tk.Toplevel(pw); w.title("Peak sanity summary (ORIGINAL b(s))")
            hdr = ttk.Label(w,
                text=("Every row is on the ORIGINAL, unsuppressed b_k(s). "
                       "Suppression settings below apply to DISPLAY only."),
                foreground="#555", padding=(6, 4))
            hdr.pack(fill=tk.X)
            # Snapshot suppression state at capture time
            snap = ttk.Label(w,
                text=(f"suppression: "
                       f"{'ON' if pulse_supp_on_var.get() else 'OFF'}  "
                       f"w={float(pulse_supp_w_var.get()):.1f} µm  "
                       f"taper={float(pulse_supp_tap_var.get()):.1f} µm  "
                       f"floor={float(pulse_supp_flr_var.get()):.2f}  "
                       f"|  σ_xy={float(pulse_sigma_var.get()):.2f}  "
                       f"τ_win={int(pulse_tauwin_var.get())}  "
                       f"basis={pulse_basis_var.get()}"),
                foreground="#333", padding=(6, 0))
            snap.pack(fill=tk.X)
            cols = ("t_orig", "t_cleaned", "time_s",
                     "s_star_um", "A_peak", "FWHM_um")
            tv = ttk.Treeview(w, columns=cols, show='headings', height=14)
            for c, wpx in zip(cols, (60, 70, 70, 80, 80, 80)):
                tv.heading(c, text=c)
                tv.column(c, width=wpx, anchor='center')
            for k, fi in enumerate(present):
                ci = (o2c.get(fi) if o2c else None)
                tv.insert('', tk.END, values=(
                    int(fi),
                    ('' if ci is None else int(ci)),
                    f"{fi/max(fps,1e-9):.3f}",
                    f"{s_star[k]:.2f}",
                    f"{amp[k]:.4g}",
                    (f"{fwhm[k]:.2f}" if np.isfinite(fwhm[k]) else "NaN"),
                ))
            tv.pack(fill=tk.BOTH, expand=True, padx=6, pady=4)
            fin = ttk.Frame(w); fin.pack(fill=tk.X, padx=6, pady=(0, 6))
            def _copy_tsv():
                buf = ["\t".join(cols)]
                for iid in tv.get_children(''):
                    buf.append("\t".join(str(v) for v in tv.item(iid)['values']))
                tsv = "\n".join(buf)
                try:
                    w.clipboard_clear(); w.clipboard_append(tsv)
                    self._log(f"[peak-summary] copied {len(present)} rows to clipboard (TSV)")
                except Exception as e:
                    messagebox.showwarning("Clipboard",
                        f"Could not access clipboard: {e}")
            ttk.Button(fin, text="Copy TSV",
                        command=_copy_tsv).pack(side=tk.LEFT, padx=2)
            def _save_tsv():
                p = filedialog.asksaveasfilename(
                    parent=w, title="Save peak sanity TSV",
                    initialfile="peak_sanity", defaultextension=".tsv",
                    filetypes=[("TSV", "*.tsv"), ("CSV", "*.csv")])
                if not p: return
                sep = "," if p.lower().endswith(".csv") else "\t"
                with open(p, "w", newline="") as f:
                    f.write(sep.join(cols) + "\n")
                    for iid in tv.get_children(''):
                        f.write(sep.join(str(v)
                                    for v in tv.item(iid)['values']) + "\n")
                self._log(f"[peak-summary] wrote {p}")
            ttk.Button(fin, text="Save TSV/CSV",
                        command=_save_tsv).pack(side=tk.LEFT, padx=2)
            # Summary stats
            def _fmt(x):
                return f"{x:.3f}" if np.isfinite(x) else "n/a"
            fwhm_valid = fwhm[np.isfinite(fwhm)]
            stats_txt = (
                f"K={len(present)}  "
                f"s* range=[{np.min(s_star):.2f}, {np.max(s_star):.2f}] µm  "
                f"A range=[{np.min(amp):.3g}, {np.max(amp):.3g}]  "
                f"FWHM median={_fmt(float(np.median(fwhm_valid)) if fwhm_valid.size else float('nan'))} µm "
                f"(valid: {fwhm_valid.size}/{len(present)})"
            )
            ttk.Label(fin, text=stats_txt,
                        foreground="#333").pack(side=tk.RIGHT, padx=6)
            self._log("[peak-summary] " + stats_txt)

        # ── SELF-TEST for the new helpers ──────────────────────────────
        # Not tied to any button; called from the settings/save workflow so
        # the user can verify the display-suppression math + FWHM extraction
        # are correct on synthetic profiles. Never blocks the GUI.
        def _self_test_peak_helpers(verbose=False):
            errors = []
            # (1) _peak_suppression_weights: floor + plateau + smooth taper
            s = np.linspace(0.0, 300.0, 301, dtype=np.float32)   # µm
            old_w  = float(pulse_supp_w_var.get())
            old_tp = float(pulse_supp_tap_var.get())
            old_fl = float(pulse_supp_flr_var.get())
            try:
                pulse_supp_w_var.set(50.0)
                pulse_supp_tap_var.set(25.0)
                pulse_supp_flr_var.set(0.05)
                w_arr = _peak_suppression_weights(s, 150.0)
                # inside plateau
                mask_in = np.abs(s - 150.0) <= 50.0
                if not np.allclose(w_arr[mask_in], 1.0, atol=1e-6):
                    errors.append("plateau not exactly 1 inside |s-s*|<=w")
                # far outside taper
                mask_far = np.abs(s - 150.0) > (50.0 + 25.0 + 1e-3)
                if not np.allclose(w_arr[mask_far], 0.05, atol=1e-6):
                    errors.append("floor not respected outside taper region")
                # monotonic decrease across taper
                right = (s >= (150.0 + 50.0)) & (s <= (150.0 + 50.0 + 25.0))
                right_w = w_arr[right]
                if right_w.size >= 2 and np.any(np.diff(right_w) > 1e-6):
                    errors.append("right-taper is not monotonically decreasing")
                left = (s >= (150.0 - 50.0 - 25.0)) & (s <= (150.0 - 50.0))
                left_w = w_arr[left]
                if left_w.size >= 2 and np.any(np.diff(left_w) < -1e-6):
                    errors.append("left-taper is not monotonically increasing")
                # floor=0 edge-case: no NaNs from division-by-zero later
                pulse_supp_flr_var.set(0.0)
                w0 = _peak_suppression_weights(s, 150.0)
                if not np.isfinite(w0).all():
                    errors.append("floor=0 produced non-finite weights")
            finally:
                pulse_supp_w_var.set(old_w)
                pulse_supp_tap_var.set(old_tp)
                pulse_supp_flr_var.set(old_fl)
            # (2) _fwhm_of_arclength_profile: recover known FWHM from Gaussian
            for known_fwhm_um in (10.0, 25.0, 60.0):
                sigma = known_fwhm_um / 2.355
                arc = np.linspace(0.0, 300.0, 601, dtype=float)
                pk_i = int(np.argmin(np.abs(arc - 150.0)))
                b = np.exp(-((arc - 150.0) ** 2) / (2.0 * sigma * sigma))
                est = _fwhm_of_arclength_profile(b, arc, pk_i)
                if not np.isfinite(est):
                    errors.append(f"FWHM NaN on canonical Gaussian "
                                    f"(target={known_fwhm_um} µm)"); continue
                rel = abs(est - known_fwhm_um) / known_fwhm_um
                if rel > 0.03:
                    errors.append(
                        f"FWHM off by {rel*100:.1f}% "
                        f"(est={est:.2f}, target={known_fwhm_um:.2f})")
            # (3) FWHM sanity on constant profile (should be NaN)
            const = np.ones(100, dtype=float)
            arc2  = np.linspace(0.0, 100.0, 100, dtype=float)
            fw_const = _fwhm_of_arclength_profile(const, arc2, 50)
            if np.isfinite(fw_const):
                errors.append("FWHM on constant profile should be NaN")
            # (4) FWHM on asymmetric skewed peak: still within ±5%
            arc3 = np.linspace(0.0, 300.0, 601, dtype=float)
            sigma_L = 12.0 / 2.355; sigma_R = 20.0 / 2.355
            b_skew = np.where(arc3 <= 150.0,
                                np.exp(-((arc3 - 150.0) ** 2)
                                          / (2.0 * sigma_L * sigma_L)),
                                np.exp(-((arc3 - 150.0) ** 2)
                                          / (2.0 * sigma_R * sigma_R)))
            est = _fwhm_of_arclength_profile(b_skew, arc3,
                                                int(np.argmax(b_skew)))
            expected_skew = 0.5 * (12.0 + 20.0)
            if not np.isfinite(est) or abs(est - expected_skew) / expected_skew > 0.10:
                errors.append(
                    f"FWHM on skewed peak off (est={est:.2f}, "
                    f"expected≈{expected_skew:.2f})")
            # (5) FWHM off-center peak: still correct
            arc4 = np.linspace(0.0, 400.0, 801, dtype=float)
            sig = 15.0 / 2.355
            b_off = np.exp(-((arc4 - 300.0) ** 2) / (2.0 * sig * sig))
            est = _fwhm_of_arclength_profile(b_off, arc4,
                                                int(np.argmax(b_off)))
            if not np.isfinite(est) or abs(est - 15.0) / 15.0 > 0.03:
                errors.append(
                    f"FWHM off on off-center Gaussian (est={est:.2f}, target=15)")
            # (6) Weight math parameter sweep — sanity across parameter grid
            try:
                old_w  = float(pulse_supp_w_var.get())
                old_tp = float(pulse_supp_tap_var.get())
                old_fl = float(pulse_supp_flr_var.get())
                for w_um in (5.0, 20.0, 100.0, 200.0):
                    for taper in (0.0, 10.0, 40.0):
                        for floor in (0.0, 0.05, 0.5, 1.0):
                            pulse_supp_w_var.set(w_um)
                            pulse_supp_tap_var.set(taper)
                            pulse_supp_flr_var.set(floor)
                            wv = _peak_suppression_weights(s, 150.0)
                            if not np.all(np.isfinite(wv)):
                                errors.append(
                                    f"non-finite weight at "
                                    f"w={w_um}, taper={taper}, floor={floor}")
                            wmax = float(wv.max()); wmin = float(wv.min())
                            if wmax > 1.0 + 1e-6 or wmin < -1e-6:
                                errors.append(
                                    f"weight out of [0,1] at "
                                    f"w={w_um}, taper={taper}, floor={floor} "
                                    f"(min={wmin}, max={wmax})")
                            if floor == 1.0 and not np.allclose(wv, 1.0):
                                errors.append(
                                    f"floor=1.0 should give all-ones "
                                    f"(w={w_um}, taper={taper})")
            finally:
                pulse_supp_w_var.set(old_w)
                pulse_supp_tap_var.set(old_tp)
                pulse_supp_flr_var.set(old_fl)
            # (7) Empty / degenerate profile — must not crash, must return NaN
            fw_empty = _fwhm_of_arclength_profile(np.array([]),
                                                     np.array([]), 0)
            if np.isfinite(fw_empty):
                errors.append("FWHM on empty profile should be NaN")
            fw_tiny  = _fwhm_of_arclength_profile(np.array([0.0]),
                                                     np.array([0.0]), 0)
            if np.isfinite(fw_tiny):
                errors.append("FWHM on 1-sample profile should be NaN")
            # (8) Suppression identity: w >> profile range → all-plateau
            try:
                old_w  = float(pulse_supp_w_var.get())
                old_tp = float(pulse_supp_tap_var.get())
                pulse_supp_w_var.set(10000.0)
                pulse_supp_tap_var.set(0.0)
                w_all = _peak_suppression_weights(s, 150.0)
                if not np.allclose(w_all, 1.0):
                    errors.append("huge-w suppression should give all-ones")
            finally:
                pulse_supp_w_var.set(old_w)
                pulse_supp_tap_var.set(old_tp)
            if verbose or errors:
                self._log("[self-test peak helpers] "
                          + ("FAIL:\n  " + "\n  ".join(errors)
                              if errors else "OK (weights + FWHM + edge cases)"))
            return len(errors) == 0

        # Convenience runner: chain the peak-helpers self-test with the
        # existing _self_test_fwhm helper. Non-blocking: never raises even if
        # tests fail — errors are logged; the caller can inspect the log
        # console to see which subtests failed.
        def _run_all_peak_tests():
            self._log("[self-test] running peak-helpers + FWHM battery ...")
            ok_helpers = False; ok_fwhm = False
            try:
                ok_helpers = bool(_self_test_peak_helpers(verbose=True))
            except Exception as e:
                self._log(f"[self-test peak helpers] crash: {e}")
            try:
                ok_fwhm = bool(_self_test_fwhm())
            except Exception as e:
                self._log(f"[self-test FWHM] crash: {e}")
            msg = (f"[self-test] peak-helpers={'OK' if ok_helpers else 'FAIL'}  "
                    f"FWHM={'OK' if ok_fwhm else 'FAIL'}")
            self._log(msg)
            return ok_helpers and ok_fwhm

        # ── STRUCTURE MASK from demotioned data (DISPLAY-only) ──────────
        # Aggregate (mean|max) the demotioned working stack over a user
        # frame range, threshold (percentile OR Otsu) after a Gaussian
        # smooth, then morphology (close→open→optional fill→dilate). Keep
        # either the top-N largest CCs, or the CCs that overlap the drawn
        # centerline band. Result is (mask_bool, agg_float01). Quantitative
        # signals never see this — they always use _proj_for_measurement().
        _bosf_cache = {'key': None, 'mask': None, 'agg': None}

        def _bosf_frame_range():
            """Resolve `mask_frames_var` -> a list[int] of KEPT frame indices
            on the ORIGINAL basis (drops deleted frames automatically)."""
            from slim_recon.layered_export import parse_frame_spec
            T_ = st['proj'].shape[0]
            spec = (mask_frames_var.get() or '').strip()
            if spec:
                idx = parse_frame_spec(spec, T_)
            else:
                idx = list(range(T_))
            deleted = st['deleted_frames']
            idx = [int(i) for i in idx if int(i) not in deleted]
            return idx

        def _otsu_threshold(v01):
            """Bare-bones Otsu on a float [0,1] array — no skimage
            dependency. Returns the threshold in the same [0,1] range."""
            v = np.clip(v01.ravel(), 0.0, 1.0)
            hist, edges = np.histogram(v, bins=256, range=(0.0, 1.0))
            p = hist.astype(np.float64) / max(1, hist.sum())
            omega = np.cumsum(p)
            mu = np.cumsum(p * np.arange(256))
            muT = mu[-1]
            eps = 1e-12
            sigma_b2 = (muT * omega - mu) ** 2 / (omega * (1.0 - omega) + eps)
            k = int(np.nanargmax(sigma_b2))
            return float(edges[k])

        def _compute_structure_mask(force=False):
            """Return (mask_bool[H,W], agg_float01[H,W]) using the demotioned
            display basis. Cached; recompute when any control changes.
            Honors `mask_mode_var`: auto (threshold pipeline), manual (only
            the user-painted `st['manual_mask']`), or combined (union)."""
            from scipy.ndimage import (gaussian_filter, binary_closing,
                                          binary_opening, binary_fill_holes,
                                          binary_dilation, label as _label)
            proj = _corrected_proj()                # demotioned if enabled
            if proj is None:
                raise RuntimeError("no working projection (Rebuild proj first)")
            frames = _bosf_frame_range()
            if not frames:
                raise RuntimeError("no kept frames in the requested range")
            mode = mask_mode_var.get()
            manual = st.get('manual_mask')
            man_id = id(manual)                # invalidate on mutation
            key = (
                id(proj), tuple(frames[:2] + frames[-2:]), len(frames),
                mask_src_var.get(), mask_method_var.get(),
                float(mask_thr_var.get()), float(mask_smooth_var.get()),
                int(mask_close_var.get()), int(mask_open_var.get()),
                int(mask_dilate_var.get()), bool(mask_holes_var.get()),
                bool(mask_keepcl_var.get()), int(mask_maxcc_var.get()),
                int(band_var.get()), mode, man_id,
                id(st.get('erase_mask')),                # invalidate on paint
            )
            if not force and _bosf_cache['key'] == key:
                return _bosf_cache['mask'], _bosf_cache['agg']
            arr = proj[frames].astype(np.float32, copy=False)
            if mask_src_var.get() == 'max':
                agg = np.nanmax(arr, axis=0)
            else:
                agg = np.nanmean(arr, axis=0)
            lo, hi = float(np.nanmin(agg)), float(np.nanmax(agg))
            span = max(hi - lo, 1e-12)
            agg01 = np.clip((agg - lo) / span, 0.0, 1.0)
            sigma = max(0.0, float(mask_smooth_var.get()))
            smoothed = gaussian_filter(agg01, sigma=sigma) if sigma > 0 else agg01
            if mask_method_var.get() == 'otsu':
                thr = _otsu_threshold(smoothed)
            else:
                pct = float(np.clip(mask_thr_var.get(), 0.0, 100.0))
                thr = float(np.percentile(smoothed, pct))
            mask = smoothed >= thr
            k_close = max(0, int(mask_close_var.get()))
            k_open  = max(0, int(mask_open_var.get()))
            k_dil   = max(0, int(mask_dilate_var.get()))
            if k_close > 0:
                mask = binary_closing(mask, iterations=k_close)
            if k_open > 0:
                mask = binary_opening(mask, iterations=k_open)
            if bool(mask_holes_var.get()):
                mask = binary_fill_holes(mask)
            if k_dil > 0:
                mask = binary_dilation(mask, iterations=k_dil)
            # keep-CC selection
            lbl, ncc = _label(mask)
            if ncc == 0:
                pass
            elif bool(mask_keepcl_var.get()) and st.get('centerline') is not None:
                cl_ = st['centerline']
                band_mask = np.zeros_like(mask, dtype=bool)
                half = max(1, int(band_var.get()))
                # Expand centerline to a thick band using existing helper
                try:
                    band_pts = _expand_line(cl_, width=half)
                    for x, y in band_pts:
                        xi, yi = int(round(x)), int(round(y))
                        if 0 <= yi < band_mask.shape[0] and 0 <= xi < band_mask.shape[1]:
                            band_mask[yi, xi] = True
                except Exception:
                    for x, y in cl_:
                        xi, yi = int(round(x)), int(round(y))
                        if 0 <= yi < band_mask.shape[0] and 0 <= xi < band_mask.shape[1]:
                            band_mask[yi, xi] = True
                keep_ids = set(int(v) for v in np.unique(lbl[band_mask]) if v != 0)
                if not keep_ids:
                    self._log("[bosf] no CC overlapped centerline band — "
                              "falling back to top-N by area")
                    sizes = np.bincount(lbl.ravel())
                    keep_ids = set(int(i) for i in
                                    np.argsort(sizes[1:])[::-1][:max(1, int(mask_maxcc_var.get()))] + 1)
                mask = np.isin(lbl, list(keep_ids))
            else:
                sizes = np.bincount(lbl.ravel())
                keep_n = max(1, int(mask_maxcc_var.get()))
                keep_ids = set(int(i) for i in
                                np.argsort(sizes[1:])[::-1][:keep_n] + 1)
                mask = np.isin(lbl, list(keep_ids))
            # Blend manual mask according to `mask_mode_var`
            if mode == 'manual':
                if manual is None or manual.shape != agg01.shape:
                    self._log("[bosf] manual mode with empty/invalid "
                              "manual mask — using all-True fallback")
                    mask = np.ones_like(agg01, dtype=bool)
                else:
                    mask = manual.astype(bool, copy=False)
                # Apply post-morph on the manual mask for consistency
                if k_close > 0: mask = binary_closing(mask, iterations=k_close)
                if k_open > 0:  mask = binary_opening(mask, iterations=k_open)
                if bool(mask_holes_var.get()): mask = binary_fill_holes(mask)
                if k_dil > 0:  mask = binary_dilation(mask, iterations=k_dil)
            elif mode == 'combined':
                if manual is not None and manual.shape == agg01.shape:
                    mask = np.logical_or(mask, manual.astype(bool, copy=False))
            # Erase-region subtraction — user-painted artifacts removed from
            # the display mask. Never affects measurements.
            _erase = st.get('erase_mask')
            if _erase is not None and _erase.shape == mask.shape:
                mask = np.logical_and(mask, ~_erase.astype(bool, copy=False))
            _bosf_cache.update(key=key, mask=mask, agg=agg01)
            self._log(f"[bosf] mask: mode={mode} frames={len(frames)} "
                      f"agg={mask_src_var.get()} "
                      f"thr={mask_method_var.get()} val={thr:.4f} "
                      f"px_on={int(mask.sum())} "
                      f"({100.0*mask.mean():.2f}% of frame)")
            return mask, agg01

        def _open_structure_mask_tuner():
            """Preview window: aggregate | mask overlay | isolated structure.
            Uses the app's Figure()+_embed_with_save path (no pyplot)."""
            from matplotlib.figure import Figure
            mask, agg01 = _compute_structure_mask(force=True)
            floor = float(np.clip(bolus_bgfloor_var.get(), 0.0, 1.0))
            struct = _apply_mask_action(agg01, mask)
            w = tk.Toplevel(pw); w.title("Structure mask preview")
            with apply_nature_style():
                fig = Figure(figsize=(9.0, 3.6), dpi=200, facecolor='white')
                gs  = fig.add_gridspec(1, 3, wspace=0.05)
                ax1 = fig.add_subplot(gs[0])
                ax2 = fig.add_subplot(gs[1])
                ax3 = fig.add_subplot(gs[2])
                im1 = ax1.imshow(agg01, cmap='gray', vmin=0, vmax=1,
                                    interpolation='nearest')
                ax1.set_title("aggregate", fontsize=7)
                # overlay outline
                im2 = ax2.imshow(agg01, cmap='gray', vmin=0, vmax=1,
                                    interpolation='nearest')
                ax2.contour(mask.astype(float), levels=[0.5],
                              colors=[OKABE_ITO[4]], linewidths=0.6)
                ax2.set_title("mask outline", fontsize=7)
                im3 = ax3.imshow(struct, cmap='gray', vmin=0, vmax=1,
                                    interpolation='nearest')
                ax3.set_title(f"applied: {mask_action_var.get()}  "
                                f"(bg={floor:.2f})",
                                fontsize=7)
                for ax in (ax1, ax2, ax3):
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                pxu = float(px_var.get())
                _scale_bar_µm(ax3, 100.0, pxu)
                panel_letter(ax1, 'a'); panel_letter(ax2, 'b')
                panel_letter(ax3, 'c')
                fig.tight_layout()
                _embed_with_save(w, fig, "structure_mask_preview")

        # ── BOLUS ON STRUCTURE (Nature-quality montage + GIF/MP4 export) ─
        BOSF_CAPTION = (
            "Synthetic bolus (constant radius) advanced along the fitted "
            "peak trajectory over the extracted lymphatic-structure mask; "
            "not raw fluorescence.")

        # `_OKABE_MAP` is initialized UP-FRONT (right after the state init)
        # so every panel — including the accent-color combobox in bosf that
        # used to forward-ref this — can reference it safely.

        # ──────────────────────── Fig.2 analog helpers ───────────────────
        # Structure MIP + synthetic-bolus overlay (Fig.2a-left analog).
        # Reuses `line_infos`, mask, autocrop shift already applied by the
        # caller. Draws its own Figure and embeds via _embed_with_save.
        # Shared helper: build a data-derived "virtual structure" RGB image
        # from a cleaned aggregate + mask, tinted with a chosen hue.  Reused
        # by mip_bolus, trajectory (as background), and velocity_map so all
        # three modes share the same clean structure look.
        def _hex_to_rgb01(h):
            h = str(h).lstrip('#')
            if len(h) != 6: return np.array([0.0, 1.0, 1.0], np.float32)
            return np.array([
                int(h[0:2], 16) / 255.0,
                int(h[2:4], 16) / 255.0,
                int(h[4:6], 16) / 255.0], dtype=np.float32)

        # ── Vessel EXTRACTION (Feature 1) ───────────────────────────────
        # Inputs: (agg01_disp, mask_2d) — same shape (cropped or not).
        # Returns dict with `vessel_mask`, `soft_intensity`, `skeleton` (or
        # None), `params`. Caches on `st['vessel_extracted']`.
        def _extract_vessel(agg01_disp, mask_2d):
            from scipy.ndimage import (gaussian_filter,
                                          binary_closing, binary_opening,
                                          binary_fill_holes, binary_dilation,
                                          label as _ndlabel)
            # (a) Intensity gate — percentile inside the mask ROI.
            agg = np.clip(agg01_disp.astype(np.float32), 0.0, 1.0)
            gate_int = np.zeros_like(mask_2d, dtype=bool)
            if bool(vess_use_int_var.get()) and mask_2d.any():
                inside = agg[mask_2d]
                pct = float(np.clip(vess_int_thr_var.get(), 0.0, 100.0))
                thr_i = float(np.percentile(inside, pct)) if inside.size else 0.0
                gate_int = (agg >= thr_i) & mask_2d
            # (b) Vesselness — Frangi / Sato (skimage) with DoG fallback.
            gate_vess = np.zeros_like(mask_2d, dtype=bool)
            vess_soft = None
            if bool(vess_use_frangi_var.get()):
                try:
                    from skimage.filters import frangi as _fr
                    sigmas = [max(0.5, float(x))
                                for x in vess_sigmas_var.get().split(',')
                                if x.strip()]
                    if not sigmas: sigmas = [1.0, 2.0, 3.0]
                    resp = _fr(agg, sigmas=sigmas, black_ridges=False)
                    r_max = float(np.nanmax(resp)) if resp.size else 0.0
                    if r_max > 0: resp = resp / r_max
                    vess_soft = resp
                    thr_v = float(np.clip(vess_frangi_thr_var.get(),
                                             0.0, 1.0))
                    gate_vess = (resp >= thr_v) & mask_2d
                except Exception as _e:
                    self._log(f"[vessel] frangi unavailable ({_e}); "
                              "falling back to DoG ridge enhancement")
                    sigs = [1.0, 2.0]
                    try:
                        sigs = [max(0.5, float(x))
                                for x in vess_sigmas_var.get().split(',')
                                if x.strip()][:2] or sigs
                    except Exception: pass
                    s1, s2 = (sigs[0], sigs[-1]
                                if len(sigs) > 1 else sigs[0] * 2)
                    g1 = gaussian_filter(agg, sigma=s1)
                    g2 = gaussian_filter(agg, sigma=s2)
                    resp = np.clip(g1 - g2, 0.0, None)
                    r_max = float(np.nanmax(resp)) if resp.size else 0.0
                    if r_max > 0: resp = resp / r_max
                    vess_soft = resp
                    thr_v = float(np.clip(vess_frangi_thr_var.get(),
                                             0.0, 1.0))
                    gate_vess = (resp >= thr_v) & mask_2d
            # (c) Combine.
            if bool(vess_use_int_var.get()) and bool(vess_use_frangi_var.get()):
                if vess_combine_var.get() == 'and':
                    vessel_mask = gate_int & gate_vess
                else:
                    vessel_mask = gate_int | gate_vess
            elif bool(vess_use_int_var.get()):
                vessel_mask = gate_int
            elif bool(vess_use_frangi_var.get()):
                vessel_mask = gate_vess
            else:
                vessel_mask = mask_2d.copy()
            # (d) Morphology.
            k_close = max(0, int(vess_close_var.get()))
            k_open  = max(0, int(vess_open_var.get()))
            k_dil   = max(0, int(vess_dilate_var.get()))
            min_sz  = max(0, int(vess_min_size_var.get()))
            if k_close > 0:
                vessel_mask = binary_closing(vessel_mask,
                                                iterations=k_close)
            if k_open > 0:
                vessel_mask = binary_opening(vessel_mask,
                                                iterations=k_open)
            if bool(vess_fill_var.get()):
                vessel_mask = binary_fill_holes(vessel_mask)
            if min_sz > 0:
                try:
                    from skimage.morphology import remove_small_objects
                    vessel_mask = remove_small_objects(vessel_mask,
                                                          min_size=min_sz)
                except Exception:
                    lbl_arr, n = _ndlabel(vessel_mask)
                    sizes = np.bincount(lbl_arr.ravel())
                    keep = np.zeros_like(sizes, dtype=bool)
                    keep[1:] = sizes[1:] >= min_sz
                    vessel_mask = keep[lbl_arr]
            if k_dil > 0:
                vessel_mask = binary_dilation(vessel_mask,
                                                 iterations=k_dil)
            # (e) Keep CCs overlapping the (active) centerline band.
            if bool(vess_cc_cl_var.get()) and st.get('centerline') is not None:
                cl_ = st['centerline']
                band_mask = np.zeros_like(vessel_mask, dtype=bool)
                half = max(1, int(band_var.get()))
                try:
                    band_pts = _expand_line(cl_, width=half)
                    for x, y in band_pts:
                        xi, yi = int(round(x)), int(round(y))
                        if (0 <= yi < band_mask.shape[0]
                            and 0 <= xi < band_mask.shape[1]):
                            band_mask[yi, xi] = True
                except Exception:
                    for x, y in cl_:
                        xi, yi = int(round(x)), int(round(y))
                        if (0 <= yi < band_mask.shape[0]
                            and 0 <= xi < band_mask.shape[1]):
                            band_mask[yi, xi] = True
                lbl_arr, n = _ndlabel(vessel_mask)
                keep_ids = set(int(v) for v in
                                np.unique(lbl_arr[band_mask]) if v != 0)
                if keep_ids:
                    vessel_mask = np.isin(lbl_arr, list(keep_ids))
            # (f) Soft intensity image (for antialiased rendering).
            if vess_soft is None:
                vess_soft = agg.copy()
            soft = np.where(vessel_mask, vess_soft, 0.0)
            mx = float(np.nanmax(soft)) if soft.size else 1.0
            if mx > 0: soft = soft / mx
            soft = np.clip(soft * mask_2d.astype(np.float32), 0.0, 1.0)
            # (g) Skeleton (optional).
            skel = None
            if bool(vess_skeleton_var.get()):
                try:
                    from skimage.morphology import skeletonize
                    skel = skeletonize(vessel_mask.astype(bool))
                except Exception as _e:
                    self._log(f"[vessel] skeletonize skipped: {_e}")
                    skel = None
            params = dict(
                use_int=bool(vess_use_int_var.get()),
                int_pct=float(vess_int_thr_var.get()),
                use_frangi=bool(vess_use_frangi_var.get()),
                frangi_thr=float(vess_frangi_thr_var.get()),
                sigmas=vess_sigmas_var.get(),
                combine=vess_combine_var.get(),
                close=int(vess_close_var.get()),
                open=int(vess_open_var.get()),
                dilate=int(vess_dilate_var.get()),
                min_size=int(vess_min_size_var.get()),
                fill_holes=bool(vess_fill_var.get()),
                cc_centerline=bool(vess_cc_cl_var.get()),
                skeleton=bool(vess_skeleton_var.get()),
                blend=float(vess_blend_var.get()),
            )
            result = dict(
                vessel_mask=vessel_mask,
                soft_intensity=soft,
                skeleton=skel,
                agg01_disp=agg.copy(),
                params=params,
            )
            st['vessel_extracted'] = result
            self._log(f"[vessel] extracted: "
                      f"px_on={int(vessel_mask.sum())} "
                      f"({100.0*vessel_mask.mean():.2f}% of frame)  "
                      f"skeleton={skel is not None}")
            return result

        # Legacy tinted-aggregate background (fallback path). Renamed +
        # kept as-is for callers that specifically need it.
        def _tinted_aggregate_rgb(agg01_disp, mask_2d, hue_hex, alpha=1.0):
            hue = _hex_to_rgb01(hue_hex)
            base = np.clip(agg01_disp.astype(np.float32), 0.0, 1.0)
            base = base * mask_2d.astype(np.float32)
            rgb = np.zeros((*base.shape, 3), dtype=np.float32)
            for ch in range(3):
                rgb[..., ch] = base * hue[ch] * float(alpha)
            return rgb

        # ── Synthetic-tube renderer: skeleton + EDT-thickness -> soft
        # radial-shaded tubes.  Uses the extracted vessel; if skeleton
        # was not requested during extraction, we compute it here.
        def _synthetic_tube_rgb(agg01_disp, mask_2d, hue_hex, alpha=1.0):
            from scipy.ndimage import distance_transform_edt
            v = st.get('vessel_extracted') or {}
            vm = v.get('vessel_mask')
            if vm is None or vm.shape != agg01_disp.shape:
                # No extraction — build a rough vessel from the mask
                vm = mask_2d.astype(bool, copy=False)
            skel = v.get('skeleton')
            if skel is None or skel.shape != vm.shape:
                try:
                    from skimage.morphology import skeletonize
                    skel = skeletonize(vm.astype(bool))
                except Exception:
                    # cheap fallback: use the mask itself as the "skeleton"
                    skel = vm.astype(bool)
            # EDT-based thickness: distance to nearest vessel edge.
            edt = distance_transform_edt(vm)
            r_max = float(edt[skel].max()) if skel.any() else float(edt.max())
            r_max = max(r_max, 1.0)
            scale = float(np.clip(tube_width_var.get(), 0.2, 4.0))
            soft = float(np.clip(tube_softness_var.get(), 0.0, 1.0))
            shade = float(np.clip(tube_shading_var.get(), 0.0, 1.0))
            # Local thickness at each vessel pixel: scaled and normalized
            local_r = edt * scale
            # Radial intensity across the tube — brightest at the skeleton,
            # falling off towards the edge with cosine taper (soft edges).
            with np.errstate(divide='ignore', invalid='ignore'):
                r_norm = np.where(vm, edt / np.maximum(local_r, 1e-6), 0.0)
            r_norm = np.clip(r_norm, 0.0, 1.0)
            # Radial profile: bright core + cosine falloff.  `shade` amps
            # the contrast between core and edge.
            profile = np.clip(
                (1.0 - shade) + shade * (0.5 * (1.0 + np.cos(np.pi
                                             * np.clip(1.0 - r_norm, 0.0, 1.0)))),
                0.0, 1.0)
            # Edge softness: taper at the outer border of the mask.
            border = np.clip((edt - (1.0 - soft) * r_max)
                               / max(soft * r_max, 1e-6), 0.0, 1.0)
            edge_soft = np.where(vm, np.clip(border, 0.0, 1.0), 0.0)
            # Compose intensity + hue.
            hue = _hex_to_rgb01(hue_hex)
            inten = np.where(vm,
                               np.clip(profile * (0.6 + 0.4 * edge_soft),
                                          0.0, 1.0),
                               0.0)
            rgb = np.zeros((*vm.shape, 3), dtype=np.float32)
            for ch in range(3):
                rgb[..., ch] = inten * hue[ch] * float(alpha)
            # Brighten the skeleton so the vessel spine reads clearly.
            if skel is not None and skel.shape == vm.shape:
                for ch in range(3):
                    rgb[..., ch] = np.where(skel,
                                              np.clip(rgb[..., ch] + 0.15,
                                                        0.0, 1.0),
                                              rgb[..., ch])
            return rgb

        # ── Smooth continuous tube built from the DRAWN centerline
        # polylines.  Only the included lines contribute; the tube shares
        # the exact same crop-shifted geometry the bolus rides on, so
        # bolus + vessel line up by construction.
        # ── ONE polyline set is the single vessel geometry that drives
        # the render, the bolus, and the velocity map. Built from the
        # extracted skeleton via prune+bridge+top-N + resample + smooth.
        def _build_vessel_paths(agg01_disp, mask_2d,
                                   n_max=MAX_LINES,
                                   resample_n=64):
            """Robust vessel polylines: MASK-level bridging → skeletonize
            the connected mask → prune spurs → double-BFS longest through-
            path (walks through junctions) → resample + smooth.  Returns a
            list of (N, 2) (x, y) polylines in the render frame."""
            from scipy.ndimage import (binary_closing, binary_fill_holes,
                                          label as _ndlabel)
            from collections import deque
            H, W = agg01_disp.shape
            # ── SINGLE SOURCE OF TRUTH: the user's BRUSH MASK.
            # If the user painted a mask (`st['manual_mask']`), it IS the
            # vessel geometry — skeletonize it directly. The brush mask
            # and the rendered vessel then occupy the SAME pixels by
            # construction (they come from the same brush strokes), so
            # the bolus can never land off the vessel.
            try:
                _bm = st.get('manual_mask')
                if (_bm is not None and hasattr(_bm, 'shape')
                        and _bm.shape == (H, W)
                        and int(np.asarray(_bm).sum()) > 0):
                    mask_2d = _bm
                    self._log("[vessel-paths] using BRUSH MASK skeleton "
                              f"(painted area = {int(_bm.sum())} px)")
            except Exception as _e_bm:
                self._log(f"[vessel-paths] brush-mask override skipped: "
                          f"{_e_bm}")
            # Part A: build the line from the DRAWN brushed mask (mask_2d)
            # so the virtual vessel spans the FULL user-drawn extent — the
            # vesselness-filtered `vessel_extracted['vessel_mask']` is often
            # weaker at the top branch than what the user brushed.
            if mask_2d is None or not np.asarray(mask_2d).any():
                return []
            vm = np.asarray(mask_2d).astype(bool, copy=True)

            # 1) Fill holes + morphological closing to smooth + reconnect.
            try:
                vm = binary_fill_holes(vm)
            except Exception:
                pass
            close_iters = max(0, int(path_close_iter_var.get()))
            if close_iters > 0:
                vm = binary_closing(vm, iterations=close_iters)

            # 2) Drop CCs below min area.
            min_area = max(1, int(path_min_area_var.get()))
            lbl_arr, n_cc = _ndlabel(vm)
            if n_cc == 0: return []
            sizes = np.bincount(lbl_arr.ravel())
            keep_ids = [int(i) for i in range(1, len(sizes))
                         if sizes[i] >= min_area]
            if not keep_ids: return []
            vm = np.isin(lbl_arr, keep_ids)
            if not vm.any(): return []

            # 3) Skeletonize the bridged connected mask.
            try:
                from skimage.morphology import skeletonize
                skel = skeletonize(vm)
            except Exception:
                skel = vm.copy()
            if not skel.any(): return []

            # 4) Iterative spur pruning.
            ys, xs = np.where(skel)
            pts = set(zip(ys.tolist(), xs.tolist()))
            def _nbrs(y, x, S):
                out = []
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0: continue
                        p = (y + dy, x + dx)
                        if p in S: out.append(p)
                return out
            def _prune_once(min_twig):
                deg = {p: len(_nbrs(p[0], p[1], pts)) for p in pts}
                ends = [p for p, d in deg.items() if d == 1]
                remove = set()
                for e in ends:
                    if e in remove: continue
                    path = [e]; cur = e; prev = None
                    while True:
                        nbs = [n for n in _nbrs(cur[0], cur[1], pts)
                                if n != prev and n not in remove]
                        if not nbs: break
                        if len(nbs) >= 2: break     # junction
                        prev = cur; cur = nbs[0]; path.append(cur)
                        if len(path) > min_twig:
                            path = None; break
                    if path is not None and 1 <= len(path) <= min_twig:
                        remove.update(path)
                if not remove: return False
                for p in remove: pts.discard(p)
                return True
            min_twig = max(1, int(path_min_twig_var.get()))
            for _ in range(8):
                if not _prune_once(min_twig): break
            if not pts: return []

            # 5) Double-BFS to lift the longest through-path (walks
            # through junctions); repeat on residual pixels up to n_max.
            def _bfs(src, S):
                dist = {src: 0}; parent = {src: None}
                q = deque([src])
                while q:
                    y, x = q.popleft()
                    for n in _nbrs(y, x, S):
                        if n not in dist:
                            dist[n] = dist[(y, x)] + 1
                            parent[n] = (y, x)
                            q.append(n)
                return dist, parent
            def _reconstruct(parent, end):
                path = []; cur = end
                while cur is not None:
                    path.append(cur); cur = parent[cur]
                return path[::-1]
            try:
                from scipy.signal import savgol_filter as _sgol
            except Exception:
                _sgol = None
            paths = []
            for _ in range(int(n_max)):
                if not pts: break
                seed = next(iter(pts))
                d0, _p0 = _bfs(seed, pts)
                if not d0: break
                far1 = max(d0, key=d0.get)
                d1, p1 = _bfs(far1, pts)
                if not d1: break
                far2 = max(d1, key=d1.get)
                long_path = _reconstruct(p1, far2)
                if len(long_path) < 4: break
                # 6) Resample + Savitzky-Golay smooth.
                pts_yx = np.asarray(long_path, dtype=np.float32)
                dxy = np.diff(pts_yx, axis=0)
                seg = np.hypot(dxy[:, 0], dxy[:, 1])
                arc = np.concatenate([[0.0], np.cumsum(seg)])
                if arc[-1] <= 0: continue
                n_rs = max(8, int(resample_n))
                t_grid = np.linspace(0.0, arc[-1], n_rs)
                ys_rs = np.interp(t_grid, arc, pts_yx[:, 0])
                xs_rs = np.interp(t_grid, arc, pts_yx[:, 1])
                if _sgol is not None and n_rs >= 7:
                    try:
                        # Bigger smoothing window for a simpler continuous
                        # line — tunable via `cl_tube_smooth_var`.
                        w_req = int(cl_tube_smooth_var.get())
                        if w_req < 5: w_req = 5
                        if w_req % 2 == 0: w_req += 1
                        w = min(w_req, n_rs if n_rs % 2 == 1 else n_rs - 1)
                        if w < 5: w = 5
                        ys_rs = _sgol(ys_rs, window_length=w,
                                       polyorder=min(3, w - 1))
                        xs_rs = _sgol(xs_rs, window_length=w,
                                       polyorder=min(3, w - 1))
                    except Exception:
                        pass
                paths.append(np.stack([xs_rs, ys_rs],
                                          axis=1).astype(np.float32))
                # Remove this path's pixels + re-prune leftover twigs.
                for p in long_path: pts.discard(p)
                for _ in range(3):
                    if not _prune_once(min_twig): break
            try:
                self._log(f"[vessel-paths] built {len(paths)} clean "
                          f"line(s): lengths="
                          f"{[int(p.shape[0]) for p in paths]}")
            except Exception:
                pass
            return paths

        # ── CENTERLINE-DRIVEN vessel paths (guaranteed bolus alignment) ─
        # The LONGEST polyline = a polynomial-smoothed copy of the tracked
        # bolus centerline itself.  Because we ALSO overwrite
        # `line_infos[0]['centers']` with the same smoothed points, the
        # bolus (via `_arclen_to_xy`) and the rendered longest tube share
        # literal pixels — no snapping needed, no possible offset.
        # Additional branches come from the extraction (excluding the
        # longest extracted path).  Branch endpoints are pulled onto the
        # primary polyline so the whole vessel is one connected "k".
        # ── Transform helper for the manually-picked vessel line ──────
        # Applies (dx, dy) translation, rotation about centroid, "bow"
        # (perpendicular midpoint offset -> arc curvature), and length
        # scale. Returns a dense 48-point polyline (x, y) in image pixels.
        def _transform_manual_line(pts, x0_c=0, y0_c=0):
            arr = np.asarray(pts, dtype=np.float32)
            if arr.ndim != 2 or arr.shape[0] < 2 or arr.shape[1] < 2:
                return None
            # Shift into render frame (0,0 with autocrop off — Fig.2 path).
            arr = arr.copy()
            arr[:, 0] -= float(x0_c)
            arr[:, 1] -= float(y0_c)
            n_dense = 48
            t_dense = np.linspace(0.0, 1.0, n_dense, dtype=np.float32)
            # ── STRAIGHT-LINE fit via TLS (SVD) through the picked points.
            # Even if the user clicked curved picks, the main flow line is
            # ALWAYS straight. The bow slider can still bend it explicitly.
            centroid = arr.mean(axis=0)
            deltas = arr - centroid
            try:
                _U, _S, Vt = np.linalg.svd(deltas, full_matrices=False)
                direction = Vt[0]
                if direction[0] == 0 and direction[1] == 0:
                    direction = np.array([1.0, 0.0], dtype=np.float32)
            except Exception:
                p0, p1 = arr[0], arr[-1]
                v_dir = p1 - p0
                nrm = float(np.hypot(v_dir[0], v_dir[1])) or 1.0
                direction = v_dir / nrm
            # Project picks onto that line; extremes give the endpoints.
            t_proj = deltas @ direction
            t_min, t_max = float(t_proj.min()), float(t_proj.max())
            p_start = centroid + t_min * direction
            p_end   = centroid + t_max * direction
            xs = np.linspace(p_start[0], p_end[0], n_dense).astype(np.float32)
            ys = np.linspace(p_start[1], p_end[1], n_dense).astype(np.float32)
            poly = np.stack([xs, ys], axis=1).astype(np.float32)
            # Length scale about centroid.
            cx = float(np.mean(poly[:, 0])); cy = float(np.mean(poly[:, 1]))
            len_s = float(vessel_manual_len_var.get())
            if abs(len_s - 1.0) > 1e-6:
                poly[:, 0] = cx + (poly[:, 0] - cx) * len_s
                poly[:, 1] = cy + (poly[:, 1] - cy) * len_s
            # Bow: add perpendicular displacement peaking at midpoint.
            bow = float(vessel_manual_bow_var.get())
            if abs(bow) > 1e-3:
                ex, ey = float(poly[0, 0]), float(poly[0, 1])
                fx, fy = float(poly[-1, 0]), float(poly[-1, 1])
                dx0 = fx - ex; dy0 = fy - ey
                L = float(np.hypot(dx0, dy0))
                if L > 0:
                    # Perpendicular unit vector to chord.
                    nx, ny = -dy0 / L, dx0 / L
                    # Parabolic profile peaking at t=0.5
                    prof = 4.0 * t_dense * (1.0 - t_dense) * bow
                    poly[:, 0] = poly[:, 0] + nx * prof
                    poly[:, 1] = poly[:, 1] + ny * prof
            # Rotation about centroid.
            rot = float(vessel_manual_rot_var.get())
            if abs(rot) > 1e-3:
                th = np.deg2rad(rot)
                c, s = float(np.cos(th)), float(np.sin(th))
                xr = c * (poly[:, 0] - cx) - s * (poly[:, 1] - cy) + cx
                yr = s * (poly[:, 0] - cx) + c * (poly[:, 1] - cy) + cy
                poly = np.stack([xr, yr], axis=1).astype(np.float32)
            # Translation (calib dx / dy).
            try:
                dx = float(vessel_calib_dx_var.get())
                dy = float(vessel_calib_dy_var.get())
            except Exception:
                dx, dy = 0.0, 0.0
            if abs(dx) > 1e-6 or abs(dy) > 1e-6:
                poly = poly + np.array([[dx, dy]], dtype=np.float32)
            return poly

        # ── AUTO longest-straight main line from the DATA. Extracts the
        # skeleton's longest through-path (double-BFS in `_build_vessel_paths`)
        # and TLS-fits it to a straight line via SVD. Stashed as
        # `st['auto_main_line']` and picked up as fallback when no manual
        # line is drawn. Used by the "Re-extract main line" button.
        def _extract_auto_main_line(agg01_disp=None, mask_2d=None):
            try:
                if agg01_disp is None or mask_2d is None:
                    mask_2d, agg01 = _compute_structure_mask()
                    agg01_disp = _smoothed_structure(agg01)
                _paths = _build_vessel_paths(agg01_disp, mask_2d,
                                                n_max=1, resample_n=64)
                if not _paths or _paths[0].shape[0] < 2:
                    self._log("[main-line] auto extract: no skeleton path found")
                    return None
                arr = np.asarray(_paths[0], dtype=np.float32)
                centroid = arr.mean(axis=0)
                deltas = arr - centroid
                try:
                    _U, _S, Vt = np.linalg.svd(deltas, full_matrices=False)
                    direction = Vt[0]
                    if direction[0] == 0 and direction[1] == 0:
                        direction = np.array([1.0, 0.0], dtype=np.float32)
                except Exception:
                    v_dir = arr[-1] - arr[0]
                    nrm = float(np.hypot(v_dir[0], v_dir[1])) or 1.0
                    direction = v_dir / nrm
                t_proj = deltas @ direction
                t_min, t_max = float(t_proj.min()), float(t_proj.max())
                p_start = centroid + t_min * direction
                p_end   = centroid + t_max * direction
                xs = np.linspace(p_start[0], p_end[0], 48).astype(np.float32)
                ys = np.linspace(p_start[1], p_end[1], 48).astype(np.float32)
                line = np.stack([xs, ys], axis=1).astype(np.float32)
                st['auto_main_line'] = line
                # Store as picks-form (endpoints only) so
                # `_transform_manual_line` treats it identically to a user
                # draw; the TLS refit is a no-op on 2 collinear picks.
                pick_form = np.stack([p_start, p_end], axis=0).astype(np.float32)
                self._log(f"[main-line] auto-extracted longest straight "
                          f"({len(_paths[0])} skel pts → 48 straight pts, "
                          f"len={float(np.hypot(*(p_end - p_start))):.1f} px)")
                return pick_form
            except Exception as _e_al:
                self._log(f"[main-line] auto extract failed: {_e_al}")
                return None

        def _reextract_main_line():
            """User-visible button: recompute the auto main line from the
            current data and PROMOTE it to `manual_vessel_line` so the next
            render + align window use it. Clears any drawn line first."""
            picks = _extract_auto_main_line()
            if picks is None:
                messagebox.showwarning("Re-extract main line",
                    "Could not extract a longest-straight line from the "
                    "current mask. Adjust extraction params and retry."); return
            st['manual_vessel_line'] = picks
            st['vessel_paths'] = None
            st['_vessel_paths_shape'] = None
            try: status_v.set("Main line auto-extracted (longest straight).")
            except Exception: pass
            try: _redraw()
            except Exception: pass

        def _build_paths_from_centerline(line_infos, agg01_disp, mask_2d,
                                            apply_calib=True):
            if not line_infos: return []
            cn = np.asarray(line_infos[0]['centers'], dtype=np.float32)
            if cn.shape[0] < 2: return []
            # ── BRUSH-MASK-SKELETON short-circuit ────────────────────────
            # If the user painted a brush mask, the vessel IS the skeleton
            # of that mask. Skip the manual-line / polyfit branches and
            # return brush-mask-skeleton polylines directly, so the drawn
            # mask + the rendered vessel + the bolus all live at the SAME
            # pixels by construction.
            try:
                _bm = st.get('manual_mask')
                H_, W_ = agg01_disp.shape
                if (_bm is not None and hasattr(_bm, 'shape')
                        and _bm.shape == (H_, W_)
                        and int(np.asarray(_bm).sum()) > 0):
                    # ── PER-GROUP skeletonize (no intensity gating).
                    # Route: user-defined vessel-line groups > flat
                    # strokes as one group > straightest-continuation on
                    # merged mask. Guarantees mip_bolus / velocity_map /
                    # trajectory renders see the same N polylines the
                    # Build preview showed.
                    _groups_c = [g for g in
                                  (st.get('manual_mask_groups') or [])
                                  if g]
                    _bm_paths = []
                    if _groups_c:
                        for _gs in _groups_c:
                            _gm = np.zeros((H_, W_), dtype=bool)
                            for _sm in _gs:
                                try:
                                    _sm_a = np.asarray(_sm).astype(bool)
                                    if _sm_a.shape == (H_, W_):
                                        _gm |= _sm_a
                                except Exception: pass
                            if int(_gm.sum()) < 3: continue
                            _poly = _polyline_from_single_mask(
                                _gm, resample_n=64)
                            if _poly is not None:
                                _bm_paths.append(_poly)
                    if not _bm_paths:
                        _bm_paths = _paths_from_mask_direct(
                            np.asarray(_bm).astype(bool),
                            n_max=MAX_LINES, resample_n=64)
                    if _bm_paths:
                        # Choose the CHOSEN flow line if the user picked
                        # one (step 3); else default to longest. The
                        # centers rewrite and paths[0] both point at the
                        # same polyline so bolus + rendered vessel share
                        # pixels on the user's chosen branch.
                        _fpi_bm = st.get('flow_path_idx')
                        if (_fpi_bm is not None
                                and 0 <= int(_fpi_bm) < len(_bm_paths)):
                            _long = _bm_paths[int(_fpi_bm)]
                        else:
                            _long = max(_bm_paths,
                                         key=lambda _p: float(np.sum(
                                             np.hypot(*np.diff(_p, axis=0).T))))
                        al = np.asarray(line_infos[0]['arclen_um'],
                                        dtype=np.float32)
                        if al.size >= 2:
                            al_span = float(al[-1] - al[0])
                            if al_span > 0:
                                _dp = np.diff(_long, axis=0)
                                _sg = np.hypot(_dp[:, 0], _dp[:, 1])
                                _ar = np.concatenate(
                                    [[0.0], np.cumsum(_sg)])
                                _tot = float(_ar[-1])
                                if _tot > 0:
                                    _f = (al - al[0]) / al_span
                                    _s = np.clip(_f, 0.0, 1.0) * _tot
                                    _xs_cn = np.interp(_s, _ar,
                                                        _long[:, 0])
                                    _ys_cn = np.interp(_s, _ar,
                                                        _long[:, 1])
                                    line_infos[0]['centers'] = np.stack(
                                        [_xs_cn.astype(np.float32),
                                         _ys_cn.astype(np.float32)],
                                        axis=1).copy()
                        # Keep original order from `_build_vessel_paths`
                        # so `flow_path_idx` is stable across renders.
                        # The flow line (paths[flow_path_idx]) is what
                        # bolus + main-tube overlay both read.
                        self._log(f"[vessel-paths] BRUSH-mask skeleton "
                                  f"({len(_bm_paths)} path(s); flow_idx="
                                  f"{st.get('flow_path_idx')})")
                        return _bm_paths
            except Exception as _e_bm2:
                self._log(f"[vessel-paths] brush-skel short-circuit "
                          f"failed: {_e_bm2}")
            # ── Manual override: user picked a vessel line via canvas ──
            # If set, use it as the primary polyline. The bolus is placed
            # directly on this same polyline in `_bolus_xy_on_primary`, so
            # the rendered line and the bolus are literally the same
            # geometry — alignment is guaranteed by construction.
            _mv = st.get('manual_vessel_line')
            # Fall back to AUTO-extracted longest straight line if the
            # user hasn't drawn one — so the primary is always robust and
            # the main line always composites into the final vessel.
            if (_mv is None or len(_mv) < 2):
                _auto = st.get('auto_main_line')
                if _auto is None or len(_auto) < 2:
                    # Extract on demand the FIRST time so a robust main
                    # line exists even without any user interaction.
                    _auto = _extract_auto_main_line(agg01_disp, mask_2d)
                if _auto is not None and len(_auto) >= 2:
                    _mv = _auto
            if _mv is not None and len(_mv) >= 2:
                # Full-frame coord system — the align window stores the
                # manual line in image pixels with NO crop offset (autocrop
                # is disabled in the Fig.2 render path).  Ignore any stale
                # `_bosf_crop` so the main line lands EXACTLY where the
                # user drew it — this was the root cause of the "GREEN
                # main line dropped from final vessel" bug.
                x0_c, y0_c = 0, 0
                st['_bosf_crop'] = (0, 0)
                primary_manual = _transform_manual_line(_mv,
                                                          x0_c=x0_c,
                                                          y0_c=y0_c)
                if primary_manual is not None:
                    # Skip the polyfit fallback; use user geometry.
                    paths = [primary_manual]
                    # Rewrite line_infos[0]['centers'] to arclength-
                    # matched samples on the manual primary so
                    # `_arclen_to_xy(L0, s)` also returns points on it.
                    al = np.asarray(line_infos[0]['arclen_um'],
                                       dtype=np.float32)
                    if al.size >= 2:
                        al_span = float(al[-1] - al[0])
                        if al_span > 0:
                            _dp = np.diff(primary_manual, axis=0)
                            _sg = np.hypot(_dp[:, 0], _dp[:, 1])
                            _ar = np.concatenate([[0.0], np.cumsum(_sg)])
                            _tot = float(_ar[-1])
                            if _tot > 0:
                                _f = (al - al[0]) / al_span
                                _s = np.clip(_f, 0.0, 1.0) * _tot
                                _xs_cn = np.interp(_s, _ar,
                                                        primary_manual[:, 0])
                                _ys_cn = np.interp(_s, _ar,
                                                        primary_manual[:, 1])
                                line_infos[0]['centers'] = np.stack(
                                    [_xs_cn.astype(np.float32),
                                     _ys_cn.astype(np.float32)],
                                    axis=1).copy()
                    # Add extracted branches (excluding longest) below.
                    try:
                        _ext_m = _build_vessel_paths(agg01_disp, mask_2d,
                                                       n_max=MAX_LINES,
                                                       resample_n=64)
                    except Exception:
                        _ext_m = []
                    if _ext_m:
                        def _plen_m(p):
                            d = np.diff(p, axis=0)
                            return float(np.sum(np.hypot(d[:, 0], d[:, 1])))
                        _lens_m = [_plen_m(p) for p in _ext_m]
                        _long_m = int(np.argmax(_lens_m))
                        for _i, _p in enumerate(_ext_m):
                            if _i == _long_m: continue
                            _b = _p.astype(np.float32).copy()
                            # Snap endpoints onto the primary_manual.
                            for _ei in (0, -1):
                                _ex = float(_b[_ei, 0])
                                _ey = float(_b[_ei, 1])
                                _d2 = ((primary_manual[:, 0] - _ex) ** 2
                                        + (primary_manual[:, 1] - _ey) ** 2)
                                _j = int(np.argmin(_d2))
                                if float(np.sqrt(_d2[_j])) < 40.0:
                                    _b[_ei, 0] = float(primary_manual[_j, 0])
                                    _b[_ei, 1] = float(primary_manual[_j, 1])
                            paths.append(_b)
                    return paths
            # (1) Polynomial-smooth the centerline into a clean primary.
            n_src = cn.shape[0]
            t = np.arange(n_src, dtype=np.float32) / max(1, n_src - 1)
            n_dense = max(48, int(1.8 * n_src))
            t_dense = np.linspace(0.0, 1.0, n_dense).astype(np.float32)
            # Degree-1 polyfit = straight line through the centerline
            # points; guarantees NO dents/concavities on the primary.
            deg = 1
            try:
                px = np.polyfit(t, cn[:, 0], deg)
                py = np.polyfit(t, cn[:, 1], deg)
                xs_s = np.polyval(px, t_dense).astype(np.float32)
                ys_s = np.polyval(py, t_dense).astype(np.float32)
                primary = np.stack([xs_s, ys_s], axis=1).astype(np.float32)
            except Exception:
                primary = cn.copy()
            # (2) Apply user calib (dx, dy).
            dx, dy = 0.0, 0.0
            if apply_calib:
                try:
                    dx = float(vessel_calib_dx_var.get())
                    dy = float(vessel_calib_dy_var.get())
                except Exception: pass
            if abs(dx) > 1e-6 or abs(dy) > 1e-6:
                primary = primary + np.array([[dx, dy]], dtype=np.float32)
            # (3) Rewrite line_infos[0]['centers'] to points ON the primary
            # sampled by arclength fraction so `_arclen_to_xy` returns
            # positions that lie EXACTLY on the rendered primary polyline.
            al = np.asarray(line_infos[0]['arclen_um'], dtype=np.float32)
            if al.size >= 2:
                al_span = float(al[-1] - al[0])
                if al_span > 0:
                    _d = np.diff(primary, axis=0)
                    _seg = np.hypot(_d[:, 0], _d[:, 1])
                    _arc = np.concatenate([[0.0], np.cumsum(_seg)])
                    _total = float(_arc[-1])
                    if _total > 0:
                        _f = (al - al[0]) / al_span
                        _s = np.clip(_f, 0.0, 1.0) * _total
                        _xs = np.interp(_s, _arc, primary[:, 0])
                        _ys = np.interp(_s, _arc, primary[:, 1])
                        line_infos[0]['centers'] = np.stack(
                            [_xs.astype(np.float32),
                             _ys.astype(np.float32)], axis=1).copy()
            paths = [primary]
            # (4) Extracted branches (skip the longest — that role now
            # belongs to the centerline-driven primary).
            try:
                ext = _build_vessel_paths(agg01_disp, mask_2d,
                                            n_max=MAX_LINES, resample_n=64)
            except Exception:
                ext = []
            if ext:
                def _plen(p):
                    d = np.diff(p, axis=0)
                    return float(np.sum(np.hypot(d[:, 0], d[:, 1])))
                lens = [_plen(p) for p in ext]
                _long = int(np.argmax(lens))
                for i, p in enumerate(ext):
                    if i == _long: continue
                    b = p.astype(np.float32).copy()
                    if abs(dx) > 1e-6 or abs(dy) > 1e-6:
                        b = b + np.array([[dx, dy]], dtype=np.float32)
                    # (5) Snap branch endpoints to the primary so the k
                    # merges into one connected component.
                    for end_idx in (0, -1):
                        ex, ey = float(b[end_idx, 0]), float(b[end_idx, 1])
                        d2 = ((primary[:, 0] - ex) ** 2
                                + (primary[:, 1] - ey) ** 2)
                        j = int(np.argmin(d2))
                        if float(np.sqrt(d2[j])) < 40.0:
                            b[end_idx, 0] = float(primary[j, 0])
                            b[end_idx, 1] = float(primary[j, 1])
                    paths.append(b)
            return paths

        def _rasterize_paths(paths, H, W):
            """Rasterize the vessel polylines into a bool mask with dense
            per-segment sampling + one closing pass so consecutive samples
            connect with no visible seams between segments or branches."""
            from scipy.ndimage import binary_closing as _bc
            m = np.zeros((H, W), dtype=bool)
            for p in paths:
                if p.shape[0] < 2: continue
                for i in range(len(p) - 1):
                    x0, y0 = float(p[i, 0]), float(p[i, 1])
                    x1, y1 = float(p[i + 1, 0]), float(p[i + 1, 1])
                    seg_len = max(1.0, float(np.hypot(x1 - x0, y1 - y0)))
                    # Dense sampling: 4× per pixel — no gaps
                    n_step = max(4, int(seg_len * 4))
                    for tt in np.linspace(0.0, 1.0, n_step):
                        xi = int(round(x0 + tt * (x1 - x0)))
                        yi = int(round(y0 + tt * (y1 - y0)))
                        if 0 <= yi < H and 0 <= xi < W:
                            m[yi, xi] = True
            # One closing pass to weld any tiny seams left at junctions.
            if m.any():
                try:
                    m = _bc(m, iterations=1)
                except Exception:
                    pass
            return m

        # ── DECISIVE: ONE vessel geometry = simplified polylines built
        # from the skeleton, rasterized + EDT-tapered into anti-aliased
        # tubes. The bolus is snapped to the SAME polyline pixels, so
        # vessel and bolus share literally the same pixels.
        def _thickened_skeleton_rgb(agg01_disp, mask_2d, hue_hex, alpha=1.0):
            from scipy.ndimage import (distance_transform_edt,
                                          binary_closing)
            H, W = agg01_disp.shape
            v = st.get('vessel_extracted')
            if (v is None or v.get('vessel_mask') is None
                    or v['vessel_mask'].shape != (H, W)):
                try:
                    _extract_vessel(agg01_disp, mask_2d)
                    v = st.get('vessel_extracted')
                except Exception as _e:
                    self._log(f"[vessel] thickened-skel auto-extract "
                              f"failed: {_e}")
                    return np.zeros((H, W, 3), dtype=np.float32)
            if v is None:
                return np.zeros((H, W, 3), dtype=np.float32)
            # Use the CACHED polylines if they match the render frame,
            # otherwise build them from the skeleton right now on this
            # exact shape and cache.
            paths = st.get('vessel_paths')
            if not paths or any(p.shape[1] != 2 for p in paths):
                paths = None
            if paths is None:
                paths = _build_vessel_paths(agg01_disp, mask_2d,
                                              n_max=MAX_LINES,
                                              resample_n=64)
                st['vessel_paths'] = paths
                st['_vessel_paths_shape'] = (H, W)
            elif st.get('_vessel_paths_shape') != (H, W):
                paths = _build_vessel_paths(agg01_disp, mask_2d,
                                              n_max=MAX_LINES,
                                              resample_n=64)
                st['vessel_paths'] = paths
                st['_vessel_paths_shape'] = (H, W)
            if not paths:
                return np.zeros((H, W, 3), dtype=np.float32)
            # Rasterize polylines densely -> binary mask -> EDT cosine
            # tube. This IS the vessel; nothing else is composited.
            # First: explicitly bridge polyline endpoints at the junction
            # so the closing pass produces ONE connected component (a "k"),
            # not fragments the dilation can't quite meet.
            line_mask = _rasterize_paths(paths, H, W)
            try:
                # Collect endpoints of each polyline (start + end).
                eps = []
                for _pi, _p in enumerate(paths):
                    if _p.shape[0] < 2: continue
                    eps.append((_pi, 0,  float(_p[0,  0]), float(_p[0,  1])))
                    eps.append((_pi, -1, float(_p[-1, 0]), float(_p[-1, 1])))
                # For every pair of endpoints from DIFFERENT polylines that
                # are within `junction_thr` pixels, draw a straight raster
                # segment between them so they connect.
                junction_thr = max(4.0,
                                     float(cl_tube_radius_var.get()) * 1.5)
                for i in range(len(eps)):
                    for j in range(i + 1, len(eps)):
                        if eps[i][0] == eps[j][0]: continue  # same polyline
                        dx_ = eps[i][2] - eps[j][2]
                        dy_ = eps[i][3] - eps[j][3]
                        d_e = float(np.hypot(dx_, dy_))
                        if d_e > junction_thr: continue
                        n_step = max(4, int(d_e * 4))
                        for tt in np.linspace(0.0, 1.0, n_step):
                            xi = int(round(eps[j][2]
                                              + tt * (eps[i][2] - eps[j][2])))
                            yi = int(round(eps[j][3]
                                              + tt * (eps[i][3] - eps[j][3])))
                            if 0 <= yi < H and 0 <= xi < W:
                                line_mask[yi, xi] = True
            except Exception as _e_j:
                self._log(f"[vessel] junction bridge skipped: {_e_j}")
            # Merge into ONE connected component: dilate + closing.
            from scipy.ndimage import (binary_dilation as _bd,
                                          binary_closing as _bc,
                                          label as _lbl_cc)
            try:
                line_mask = _bd(line_mask, iterations=2)
                line_mask = _bc(line_mask, iterations=3)
            except Exception:
                pass
            # Log connected-component count so we can verify the "k" is one
            # piece (or the intended count).
            try:
                _, _n_cc = _lbl_cc(line_mask)
                self._log(f"[vessel-tube] connected components = {_n_cc}")
            except Exception: pass
            # ── AESTHETIC: SUPERSAMPLE the tube profile then downsample
            # via block-mean for crisp anti-aliased edges at 300 dpi.
            # Cost = O(super**2) memory + EDT; capped to super ≤ 3.
            try:
                _super = int(np.clip(vessel_super_var.get(), 1, 3))
            except Exception:
                _super = 2
            r_tube_native = max(0.5, float(cl_tube_radius_var.get()))
            # ── VARYING THICKNESS from the painted BRUSH MASK.
            # At every image pixel, `local_r = distance_transform_edt(mask)`
            # gives the mask's local half-width. Scaled by
            # `vessel_thick_scale` this becomes the per-pixel tube radius,
            # so the rendered vessel looks as thick as the painted mask
            # locally — natural variation like a real vessel.
            local_r_native = None
            try:
                if (mask_2d is not None
                        and hasattr(mask_2d, 'shape')
                        and mask_2d.shape == (H, W)
                        and bool(np.any(mask_2d))):
                    _mask_bool = np.asarray(mask_2d).astype(bool)
                    _mask_edt = distance_transform_edt(_mask_bool)
                    _scale = float(vessel_thick_scale.get() or 1.0)
                    local_r_native = np.clip(
                        _mask_edt * _scale, 0.5,
                        max(2.0, r_tube_native * 4.0)
                    ).astype(np.float32)
                    self._log("[vessel-tube] using MASK-WIDTH varying "
                              f"thickness (mean r={float(local_r_native[_mask_bool].mean()):.2f}px, "
                              f"max={float(local_r_native.max()):.2f}px, "
                              f"scale={_scale:.2f})")
            except Exception as _e_lr:
                self._log(f"[vessel-tube] mask-width thickness "
                          f"skipped: {_e_lr}")
            def _per_pix_r_ss(shape_ss, dist_ss):
                # Supersampled per-pixel radius, in ss-pixel units.
                if local_r_native is None:
                    return None
                try:
                    from scipy.ndimage import zoom as _zoom
                    lr_ss = _zoom(local_r_native, zoom=_super,
                                    order=1) * float(_super)
                    if lr_ss.shape != shape_ss:
                        lr2 = np.full(shape_ss, r_tube_native
                                      * float(_super), dtype=np.float32)
                        lr2[:min(lr2.shape[0], lr_ss.shape[0]),
                            :min(lr2.shape[1], lr_ss.shape[1])] = \
                            lr_ss[:lr2.shape[0], :lr2.shape[1]]
                        lr_ss = lr2
                    return lr_ss
                except Exception:
                    return None
            if _super > 1:
                try:
                    from scipy.ndimage import zoom as _zoom
                    line_mask_ss = _zoom(line_mask.astype(np.uint8),
                                          zoom=_super, order=0) > 0
                    dist_ss = distance_transform_edt(~line_mask_ss)
                    lr_ss = _per_pix_r_ss(dist_ss.shape, dist_ss)
                    if lr_ss is not None:
                        r_norm_ss = np.clip(1.0 - dist_ss / lr_ss,
                                             0.0, 1.0)
                    else:
                        r_tube_ss = r_tube_native * float(_super)
                        r_norm_ss = np.clip(1.0 - dist_ss / r_tube_ss,
                                             0.0, 1.0)
                except Exception as _e_ss:
                    self._log(f"[vessel-tube] supersample skipped: "
                              f"{_e_ss}")
                    _super = 1
                    dist = distance_transform_edt(~line_mask)
                    if local_r_native is not None:
                        r_norm = np.clip(1.0 - dist / local_r_native,
                                          0.0, 1.0)
                    else:
                        r_norm = np.clip(1.0 - dist / r_tube_native,
                                          0.0, 1.0)
            else:
                dist = distance_transform_edt(~line_mask)
                if local_r_native is not None:
                    r_norm = np.clip(1.0 - dist / local_r_native,
                                      0.0, 1.0)
                else:
                    r_norm = np.clip(1.0 - dist / r_tube_native,
                                      0.0, 1.0)
            # ── AESTHETIC: brighter compact CORE fading to a soft edge.
            # cos^p profile gives a rounder cross-section than the
            # raised-cosine and lets us bias the core sharpness.
            try:
                _core = float(np.clip(vessel_core_var.get(), 0.0, 1.0))
            except Exception:
                _core = 0.65
            _p = 1.0 + 3.0 * _core                # exponent in [1..4]
            if _super > 1:
                base_prof_ss = np.cos(0.5 * np.pi
                                * np.clip(1.0 - r_norm_ss, 0.0, 1.0))
                profile_ss = (np.clip(base_prof_ss, 0.0, 1.0) ** _p
                              * (r_norm_ss > 0))
                # Downsample the profile via block-mean AA.
                try:
                    from scipy.ndimage import zoom as _zoom
                    profile = _zoom(profile_ss.astype(np.float32),
                                     zoom=1.0 / _super, order=1)
                except Exception:
                    profile = profile_ss[::_super, ::_super]
                # Guard against off-by-one from zoom rounding.
                if profile.shape != (H, W):
                    profile = np.zeros((H, W), dtype=np.float32)
                    profile[:min(H, profile_ss.shape[0]),
                             :min(W, profile_ss.shape[1])] = \
                        profile_ss[:H, :W]
            else:
                base_prof = np.cos(0.5 * np.pi
                                    * np.clip(1.0 - r_norm, 0.0, 1.0))
                profile = np.clip(base_prof, 0.0, 1.0) ** _p
                profile = profile * (r_norm > 0)
            hue = _hex_to_rgb01(hue_hex)
            # ── AESTHETIC: gently DESATURATE by pulling toward the
            # per-channel mean — cinematic, less-harsh cyan/red.
            _mean_hue = float(np.mean(hue))
            hue = tuple(0.85 * c + 0.15 * _mean_hue for c in hue)
            r_tube = r_tube_native
            # ── DEPTH map: argmax(D) of a time-MIP of recon_volume, per
            # (H, W) pixel, normalized to [0, 1] then modulated by a
            # user weight `vessel_depth_var`. Adds a gentle
            # brightness/hue shift along the vessel so it reads as 3D.
            depth01 = None
            try:
                _dw = float(np.clip(vessel_depth_var.get(), 0.0, 1.0))
                if _dw > 0.01:
                    _rv = getattr(self, 'recon_volume', None)
                    if _rv is not None and _rv.ndim == 4 and _rv.shape[:2] == (H, W):
                        _tmip = np.max(_rv, axis=3)         # (H, W, D)
                        _z_arg = np.argmax(_tmip, axis=2)   # (H, W)
                        D_ = int(_rv.shape[2])
                        if D_ > 1:
                            depth01 = (_z_arg.astype(np.float32)
                                        / max(1.0, D_ - 1.0))
                            self._log("[vessel-tube] depth shading "
                                      f"active (D={D_}, w={_dw:.2f})")
            except Exception as _e_dp:
                self._log(f"[vessel-tube] depth shading skipped: "
                          f"{_e_dp}")
            rgb = np.zeros((H, W, 3), dtype=np.float32)
            for ch in range(3):
                rgb[..., ch] = profile * hue[ch] * float(alpha)
            # ── REVERTED — the three additive "aesthetic" blocks below
            # (depth-brightness modulation, 3D directional specular
            # highlight, gaussian-blur bloom) were removed because the
            # blurred/highlighted copies pile up at branch junctions and
            # read as a diffuse "blotch/stain" inside the tube. The clean
            # cos^p tube + main-line overlay is the intended look. Kept
            # commented so it's easy to restore if desired.
            #
            # if depth01 is not None:
            #     _dw = float(np.clip(vessel_depth_var.get(), 0.0, 1.0))
            #     _mod = 1.0 - _dw * (depth01 - 0.5)
            #     for ch in range(3):
            #         rgb[..., ch] = np.clip(rgb[..., ch] * _mod, 0.0, 1.0)
            # try:
            #     _sh = float(np.clip(vessel_shade_var.get(), 0.0, 1.0))
            #     if _sh > 0.01 and profile.shape == (H, W):
            #         yy, xx = np.mgrid[:H, :W].astype(np.float32)
            #         _diag = ((yy / max(1, H - 1))
            #                   + (xx / max(1, W - 1))) * 0.5
            #         highlight = np.clip(1.0 - _diag, 0.0, 1.0) * profile * _sh
            #         for ch in range(3):
            #             rgb[..., ch] = np.clip(
            #                 rgb[..., ch] + highlight * 0.35, 0.0, 1.0)
            # except Exception as _e_sh:
            #     self._log(f"[vessel-tube] shade skipped: {_e_sh}")
            # try:
            #     _glow = float(np.clip(vessel_glow_var.get(), 0.0, 1.0))
            #     if _glow > 0.01:
            #         from scipy.ndimage import gaussian_filter as _gf
            #         _sigma = max(1.0, r_tube * 0.9)
            #         bloom = _gf(profile.astype(np.float32), sigma=_sigma) * _glow
            #         for ch in range(3):
            #             rgb[..., ch] = np.clip(
            #                 rgb[..., ch] + bloom * hue[ch] * float(alpha), 0.0, 1.0)
            # except Exception as _e_glow:
            #     self._log(f"[vessel-tube] bloom skipped: {_e_glow}")
            # ── MAIN LINE overlay (paths[0]) — ALWAYS composited into the
            # final virtual vessel with a thicker tube, drawn LAST (on top)
            # so it's clearly the flow line. Same hue → seamless np.maximum
            # composite (no seam, no color mismatch). Root cause fix for
            # "GREEN main line shows in preview but drops from final vessel".
            try:
                # Highlight the USER-picked flow line (step 3) at 1.5×
                # tube radius so the branch the bolus rides reads clearly.
                # Fallback to paths[0] when nothing was picked.
                _fpi_r = st.get('flow_path_idx')
                if _fpi_r is not None and 0 <= int(_fpi_r) < len(paths):
                    _p_main = paths[int(_fpi_r)]
                else:
                    _p_main = paths[0]
                if paths and _p_main is not None and _p_main.shape[0] >= 2:
                    main_mask = _rasterize_paths([_p_main], H, W)
                    try:
                        main_mask = _bd(main_mask, iterations=2)
                    except Exception: pass
                    dist_m = distance_transform_edt(~main_mask)
                    r_main = max(0.5, r_tube * 1.5)
                    rn_m = np.clip(1.0 - dist_m / r_main, 0.0, 1.0)
                    # Match the same brighter-core profile the base tube
                    # uses so the flow line reads as a continuous piece.
                    prof_m = np.cos(0.5 * np.pi
                                * np.clip(1.0 - rn_m, 0.0, 1.0))
                    prof_m = np.clip(prof_m, 0.0, 1.0) ** _p
                    prof_m = prof_m * (rn_m > 0)
                    rgb_main = np.zeros((H, W, 3), dtype=np.float32)
                    for ch in range(3):
                        rgb_main[..., ch] = prof_m * hue[ch] * float(alpha)
                    rgb = np.maximum(rgb, rgb_main)
                    self._log("[vessel-tube] main line (paths[0]) "
                              f"composited (r_main={r_main:.1f}px)")
            except Exception as _e_ml:
                self._log(f"[vessel-tube] main-line overlay skipped: {_e_ml}")
            return rgb

        # ── AESTHETIC helpers (display-only). Callers opt in; none of
        # these change geometry or measurements. Provided so any render
        # can drop in a Nature-quality tube gradient / bolus glow / arrow.

        def _bolus_glow_rgba(shape, cx, cy, radius_px, hue_hex,
                              glow=None, alpha=1.0):
            """Return an (H, W, 4) additive RGBA glow — bright compact
            core fading to a soft halo. Anti-aliased. `radius_px` sets
            the core; halo extends further via a gaussian blur. Uses the
            current `bolus_glow_var` unless overridden."""
            H, W = shape[:2]
            if glow is None:
                try:
                    glow = float(np.clip(bolus_glow_var.get(),
                                           0.0, 1.0))
                except Exception:
                    glow = 0.55
            hue = _hex_to_rgb01(hue_hex)
            yy, xx = np.mgrid[:H, :W].astype(np.float32)
            r2 = (xx - float(cx)) ** 2 + (yy - float(cy)) ** 2
            # Gaussian bright core.
            sig_core = max(1.0, float(radius_px) * 0.55)
            core = np.exp(-r2 / (2.0 * sig_core * sig_core))
            # Wider soft halo for the fluorescent look.
            sig_halo = max(2.5, float(radius_px) * 1.6)
            halo = np.exp(-r2 / (2.0 * sig_halo * sig_halo)) * glow
            intensity = np.clip(core + halo, 0.0, 1.0)
            rgba = np.zeros((H, W, 4), dtype=np.float32)
            # Bright center biased toward white (hot look).
            white_bias = 0.35 * core
            for ch in range(3):
                rgba[..., ch] = np.clip(
                    intensity * hue[ch] + white_bias, 0.0, 1.0)
            rgba[..., 3] = np.clip(intensity * float(alpha), 0.0, 1.0)
            return rgba

        def _bolus_trail_rgba(shape, xs, ys, radius_px, hue_hex,
                               n_trail=None, alpha=1.0):
            """Optional short comet trail: fading gaussian blobs at the
            last `n_trail` previous bolus positions along the flow. `xs`,
            `ys` are arrays of past bolus centers (most recent LAST)."""
            if n_trail is None:
                try: n_trail = int(bolus_trail_var.get())
                except Exception: n_trail = 3
            n_trail = max(0, int(n_trail))
            if n_trail == 0 or len(xs) < 2:
                return np.zeros((*shape[:2], 4), dtype=np.float32)
            H, W = shape[:2]
            out = np.zeros((H, W, 4), dtype=np.float32)
            hue = _hex_to_rgb01(hue_hex)
            take = min(n_trail, len(xs) - 1)
            for k in range(take):
                idx = len(xs) - 2 - k
                if idx < 0: break
                fade = (1.0 - (k + 1) / (take + 1)) * 0.55
                if fade <= 0.02: continue
                yy, xx = np.mgrid[:H, :W].astype(np.float32)
                r2 = ((xx - float(xs[idx])) ** 2
                        + (yy - float(ys[idx])) ** 2)
                sig = max(2.0, float(radius_px) * (0.9 - 0.15 * k))
                g = np.exp(-r2 / (2.0 * sig * sig)) * fade
                for ch in range(3):
                    out[..., ch] = np.maximum(
                        out[..., ch], g * hue[ch] * float(alpha))
                out[..., 3] = np.maximum(out[..., 3],
                                         g * float(alpha))
            return out

        def _velocity_gradient_rgb(paths, s_dense, v_dense,
                                     flow_idx=None,
                                     cmap_name=None, alpha=1.0):
            """Color the tube of the CHOSEN flow polyline continuously by
            v(s) — a smooth per-arclength gradient with no discrete bands.
            Untracked branches stay the current dim vessel hue (unchanged
            call site keeps `_thickened_skeleton_rgb` for context)."""
            import matplotlib as _mpl
            if not paths: return None
            if flow_idx is None:
                flow_idx = st.get('flow_path_idx')
                if flow_idx is None: flow_idx = 0
            flow_idx = int(np.clip(flow_idx, 0, len(paths) - 1))
            p = paths[flow_idx]
            if p is None or p.shape[0] < 2: return None
            # Sample the tube geometry: for each pixel near p, find the
            # nearest arclength on the polyline, then look up v(s).
            H = W = None
            for _p in paths:
                if _p is None: continue
                H = max(int(np.max(_p[:, 1])) + 8, H or 0)
                W = max(int(np.max(_p[:, 0])) + 8, W or 0)
            if H is None: return None
            from scipy.ndimage import distance_transform_edt as _dedt
            line_mask = _rasterize_paths([p], H, W)
            try:
                from scipy.ndimage import binary_dilation as _bd
                line_mask = _bd(line_mask, iterations=2)
            except Exception: pass
            # For every pixel, its nearest arclength index (via EDT+argmin).
            dist, (ind_y, ind_x) = _dedt(~line_mask,
                                              return_indices=True)
            # Map (ind_y, ind_x) -> nearest arclength via 1-D interp of s.
            # Build a per-pixel lookup: nearest polyline vertex index →
            # nearest arclength.
            xs_p, ys_p = p[:, 0], p[:, 1]
            arc = np.concatenate(
                [[0.0], np.cumsum(np.hypot(np.diff(xs_p), np.diff(ys_p)))])
            # For each pixel, find nearest vertex by scanning distances.
            # Faster: cKDTree.
            try:
                from scipy.spatial import cKDTree as _KDT
                tr = _KDT(np.stack([xs_p, ys_p], axis=1))
                pix = np.stack([ind_x.ravel(), ind_y.ravel()], axis=1)
                _, nn = tr.query(pix)
                nearest_s = arc[nn].reshape(dist.shape)
            except Exception:
                nearest_s = np.zeros_like(dist)
            v_at_pix = np.interp(nearest_s, s_dense, v_dense,
                                  left=v_dense[0], right=v_dense[-1])
            # Radial profile (same as tube) for lightness modulation.
            r_tube = max(0.5, float(cl_tube_radius_var.get()))
            r_norm = np.clip(1.0 - dist / r_tube, 0.0, 1.0)
            profile = np.cos(0.5 * np.pi
                              * np.clip(1.0 - r_norm, 0.0, 1.0)) ** 1.5
            profile = profile * (r_norm > 0)
            cname = cmap_name or velocity_cmap_var.get()
            cmap = _mpl.colormaps.get_cmap(cname)
            v_lo = float(np.nanmin(v_dense))
            v_hi = float(np.nanmax(v_dense))
            v_norm = (v_at_pix - v_lo) / max(1e-9, v_hi - v_lo)
            v_norm = np.clip(v_norm, 0.0, 1.0)
            rgba = cmap(v_norm)                          # (H,W,4)
            rgb = rgba[..., :3].astype(np.float32) * profile[..., None]
            return np.clip(rgb * float(alpha), 0.0, 1.0)

        def _draw_tapered_arrow(ax, p0, p1, color='#ffffff',
                                  lw=1.4, mut=8, alpha=0.9):
            """Draw a clean, tapered arrow from p0 to p1 using
            FancyArrowPatch — thin shaft, small elegant head."""
            try:
                from matplotlib.patches import FancyArrowPatch
                _ap = FancyArrowPatch(
                    posA=(float(p0[0]), float(p0[1])),
                    posB=(float(p1[0]), float(p1[1])),
                    arrowstyle='-|>', mutation_scale=float(mut),
                    lw=lw, color=color, alpha=alpha,
                    shrinkA=1.0, shrinkB=1.0,
                    joinstyle='round', capstyle='round', zorder=6)
                ax.add_patch(_ap)
                return _ap
            except Exception:
                return None

        # ── LONGEST-polyline bolus position helper ─────────────────────
        # Given a fraction f in [0, 1], returns the (x, y) point on the
        # LONGEST polyline in `st['vessel_paths']` at fraction f of its
        # total arclength. Densely interpolates so intermediate values
        # produce smooth end-to-end motion along one continuous line.
        # ── Bolus xy on the PRIMARY (index 0) polyline of vessel_paths ──
        # The primary is guaranteed to be the smoothed centerline (built by
        # `_build_paths_from_centerline`), so placing the bolus by
        # arclength fraction on THIS polyline gives an exact match with
        # the rendered background — no `_arclen_to_xy` / L['centers']
        # round-trip that could get out of sync.
        def _bolus_xy_on_primary(f):
            paths = st.get('vessel_paths') or []
            if not paths: return (0.0, 0.0)
            # Honor the USER-picked flow line (step 3). Fallback to
            # paths[0] only if the user hasn't picked one.
            _fpi = st.get('flow_path_idx')
            if _fpi is None or not (0 <= int(_fpi) < len(paths)):
                idx = 0
            else:
                idx = int(_fpi)
            poly = paths[idx]
            if poly is None or poly.shape[0] < 2:
                return (0.0, 0.0)
            d = np.diff(poly, axis=0)
            seg = np.hypot(d[:, 0], d[:, 1])
            arc = np.concatenate([[0.0], np.cumsum(seg)])
            total = float(arc[-1])
            if total <= 0:
                return (float(poly[0, 0]), float(poly[0, 1]))
            s_t = float(np.clip(f, 0.0, 1.0)) * total
            x = float(np.interp(s_t, arc, poly[:, 0]))
            y = float(np.interp(s_t, arc, poly[:, 1]))
            return (x, y)

        def _bolus_xy_on_longest(f):
            paths = st.get('vessel_paths') or []
            if not paths: return (0.0, 0.0)
            def _poly_arc(p):
                d = np.diff(p, axis=0)
                seg = np.hypot(d[:, 0], d[:, 1])
                return np.concatenate([[0.0], np.cumsum(seg)])
            arcs = [_poly_arc(p) for p in paths]
            lens = [float(a[-1]) for a in arcs]
            # Priority: USER-picked flow line (step 3) > manual line
            # override > argmax length (auto). The auto-longest fallback
            # is only used if neither the user nor the manual pick chose.
            _fpi = st.get('flow_path_idx')
            if _fpi is not None and 0 <= int(_fpi) < len(paths):
                idx = int(_fpi)
            elif st.get('manual_vessel_line') is not None:
                idx = 0
            else:
                idx = int(np.argmax(lens))
            poly = paths[idx]
            arc = arcs[idx]
            total = lens[idx]
            if total <= 0 or poly.shape[0] < 2:
                return (float(poly[0, 0]), float(poly[0, 1]))
            f_c = float(np.clip(f, 0.0, 1.0))
            s_t = f_c * total
            x = float(np.interp(s_t, arc, poly[:, 0]))
            y = float(np.interp(s_t, arc, poly[:, 1]))
            return (x, y)

        # Reassign every tracked line's centers to points on its target
        # polyline (longest for line 0; nearest for others) using the same
        # fraction-of-arclength math. This REPLACES the old per-point
        # nearest-neighbour snap so the bolus never jumps branches.
        def _snap_line_infos_to_skeleton(line_infos, agg01_disp, mask_2d):
            H, W = agg01_disp.shape
            v = st.get('vessel_extracted')
            if (v is None or v.get('vessel_mask') is None
                    or v['vessel_mask'].shape != (H, W)):
                try:
                    _extract_vessel(agg01_disp, mask_2d)
                    v = st.get('vessel_extracted')
                except Exception:
                    return
            if v is None: return
            # Snap onto the same POLYLINE the render uses. Ensure paths
            # are built for the current shape, rasterize, then snap.
            paths = st.get('vessel_paths')
            need_build = (
                not paths
                or st.get('_vessel_paths_shape') != (H, W))
            if need_build:
                paths = _build_vessel_paths(agg01_disp, mask_2d,
                                              n_max=MAX_LINES,
                                              resample_n=64)
                st['vessel_paths'] = paths
                st['_vessel_paths_shape'] = (H, W)
            if not paths: return
            # ── Fraction-along-longest-polyline mapping ────────────────
            # Rewrites each tracked line's centers so they lie ON a single
            # continuous polyline (monotonic end-to-end).  For each L,
            # pick the polyline with min mean distance to L['centers']
            # (primary line -> longest, secondary -> its nearest); then
            # map by NORMALIZED ARCLENGTH so s* traverses that polyline
            # smoothly from one end to the other.
            def _poly_arc(p):
                d = np.diff(p, axis=0)
                seg = np.hypot(d[:, 0], d[:, 1])
                return np.concatenate([[0.0], np.cumsum(seg)])
            path_arcs = [_poly_arc(p) for p in paths]
            path_lens = [float(a[-1]) for a in path_arcs]
            longest_idx = int(np.argmax(path_lens)) if path_arcs else -1
            def _mean_dist(cn, poly):
                # cn (N, 2), poly (M, 2); for each cn point find nearest poly point
                d2 = ((cn[:, None, :] - poly[None, :, :]) ** 2).sum(-1)
                return float(np.mean(np.min(d2, axis=1)))
            for L_idx_bosf, L in enumerate(line_infos):
                cn = np.asarray(L['centers'], dtype=np.float32)
                al = np.asarray(L['arclen_um'], dtype=np.float32)
                if cn.ndim != 2 or cn.shape[1] < 2: continue
                if al.size < 2: continue
                # Primary tracked line -> longest; others -> their nearest.
                if L_idx_bosf == 0 and longest_idx >= 0:
                    tgt = longest_idx
                else:
                    dists = [_mean_dist(cn, p) for p in paths]
                    tgt = int(np.argmin(dists)) if dists else longest_idx
                poly = paths[tgt]
                arc = path_arcs[tgt]
                total_p = path_lens[tgt]
                if total_p <= 0 or poly.shape[0] < 2: continue
                al_min, al_max = float(al[0]), float(al[-1])
                al_span = al_max - al_min
                if al_span <= 0: continue
                # Fraction f in [0, 1] for each tracked center -> arclength
                # on the target polyline -> (x, y) via np.interp.
                f = np.clip((al - al_min) / al_span, 0.0, 1.0)
                s_target = f * total_p
                xs_new = np.interp(s_target, arc, poly[:, 0])
                ys_new = np.interp(s_target, arc, poly[:, 1])
                L['centers'] = np.stack(
                    [xs_new.astype(np.float32),
                     ys_new.astype(np.float32)], axis=1).copy()

        def _smooth_centerline_tube_rgb(agg01_disp, mask_2d, hue_hex,
                                           alpha=1.0):
            from scipy.ndimage import distance_transform_edt
            try:
                from scipy.signal import savgol_filter as _sgol
            except Exception:
                _sgol = None
            H, W = agg01_disp.shape
            # Pull the crop-shifted centerlines cached by
            # `_fig_bolus_on_structure`; fall back to computing them here
            # if the caller is the standalone lymphatic-2D window.
            lines = st.get('_bosf_lines_shifted')
            if not lines:
                lines = []
                x0_c, y0_c = st.get('_bosf_crop', (0, 0))
                incl = st.get('include_lines', [True, False, False])
                for i in range(MAX_LINES):
                    if i < len(incl) and incl[i]:
                        cl = st['centerlines'][i]
                        if cl is not None and len(cl) >= 2:
                            arr = cl.astype(np.float32).copy()
                            arr[:, 0] -= float(x0_c)
                            arr[:, 1] -= float(y0_c)
                            lines.append(arr)
            if not lines:
                cl = st.get('centerline')
                if cl is not None and len(cl) >= 2:
                    lines = [np.asarray(cl, dtype=np.float32)]
            line_mask = np.zeros((H, W), dtype=bool)
            if lines:
                sm_k = max(3, int(cl_tube_smooth_var.get()))
                if sm_k % 2 == 0: sm_k += 1
                for cl in lines:
                    xs = cl[:, 0].astype(np.float32)
                    ys = cl[:, 1].astype(np.float32)
                    if _sgol is not None and xs.size >= sm_k:
                        try:
                            xs = _sgol(xs, window_length=min(sm_k, xs.size - 1
                                        if xs.size % 2 == 0 else xs.size),
                                        polyorder=min(3, sm_k - 1))
                            ys = _sgol(ys, window_length=min(sm_k, ys.size - 1
                                        if ys.size % 2 == 0 else ys.size),
                                        polyorder=min(3, sm_k - 1))
                        except Exception:
                            pass
                    # Densely sample connected segments so no gaps.
                    for i in range(len(xs) - 1):
                        x0, y0 = float(xs[i]), float(ys[i])
                        x1, y1 = float(xs[i + 1]), float(ys[i + 1])
                        seg_len = max(1.0, float(np.hypot(x1 - x0, y1 - y0)))
                        n_step = max(2, int(seg_len * 2))
                        for tt in np.linspace(0.0, 1.0, n_step):
                            xi = int(round(x0 + tt * (x1 - x0)))
                            yi = int(round(y0 + tt * (y1 - y0)))
                            if 0 <= yi < H and 0 <= xi < W:
                                line_mask[yi, xi] = True
            if not line_mask.any():
                # Degenerate: no line — return black canvas.
                return np.zeros((H, W, 3), dtype=np.float32)
            # EDT gives distance from every pixel to nearest centerline
            # sample; radial profile builds a smooth anti-aliased tube.
            dist = distance_transform_edt(~line_mask)
            r_tube = max(0.5, float(cl_tube_radius_var.get()))
            # normalized inward distance: 1 at centerline, 0 at outer edge
            r_norm = np.clip(1.0 - dist / r_tube, 0.0, 1.0)
            # cosine radial falloff so edges taper smoothly
            profile = 0.5 * (1.0 + np.cos(np.pi
                                            * np.clip(1.0 - r_norm, 0.0, 1.0)))
            profile = profile * (r_norm > 0)
            hue = _hex_to_rgb01(hue_hex)
            inten = profile
            rgb = np.zeros((H, W, 3), dtype=np.float32)
            for ch in range(3):
                rgb[..., ch] = inten * hue[ch] * float(alpha)
            return rgb

        # ── Branch-context tubes: render the extracted vessel's OTHER
        # branches (not the drawn centerlines) as clean anti-aliased tubes
        # underneath the centerline vessel.  Bridges signal gaps and drops
        # tiny twigs so the 3/5-o'clock branches read as clean vessels.
        def _branch_context_rgb(agg01_disp, mask_2d, hue_hex, alpha=0.55):
            from scipy.ndimage import (distance_transform_edt,
                                          binary_closing,
                                          label as _ndlabel,
                                          binary_dilation)
            H, W = agg01_disp.shape
            v = st.get('vessel_extracted') or {}
            vm = v.get('vessel_mask')
            if vm is None or vm.shape != (H, W):
                return np.zeros((H, W, 3), dtype=np.float32)
            # 1) gap-bridge via morphological closing.
            k_close = max(0, int(branch_ctx_close_var.get()))
            if k_close > 0:
                vm2 = binary_closing(vm, iterations=k_close)
            else:
                vm2 = vm.copy()
            # 2) exclude pixels close to the drawn centerlines so we render
            # only the CONTEXT branches (not a duplicate of the main vessel).
            lines = st.get('_bosf_lines_shifted') or []
            if lines:
                cl_mask = np.zeros((H, W), dtype=bool)
                for cl in lines:
                    xs = cl[:, 0]; ys = cl[:, 1]
                    for i in range(len(xs) - 1):
                        x0, y0 = float(xs[i]), float(ys[i])
                        x1, y1 = float(xs[i + 1]), float(ys[i + 1])
                        seg_len = max(1.0, float(np.hypot(x1 - x0, y1 - y0)))
                        n_step = max(2, int(seg_len * 2))
                        for tt in np.linspace(0.0, 1.0, n_step):
                            xi = int(round(x0 + tt * (x1 - x0)))
                            yi = int(round(y0 + tt * (y1 - y0)))
                            if 0 <= yi < H and 0 <= xi < W:
                                cl_mask[yi, xi] = True
                excl_r = max(0, int(branch_ctx_exclude_var.get()))
                if excl_r > 0:
                    cl_mask = binary_dilation(cl_mask, iterations=excl_r)
                vm2 = vm2 & ~cl_mask
            # 3) drop tiny twigs.
            min_a = max(0, int(branch_ctx_min_area_var.get()))
            if min_a > 0:
                lbl_arr, n_cc = _ndlabel(vm2)
                if n_cc > 0:
                    sizes = np.bincount(lbl_arr.ravel())
                    keep = np.zeros_like(sizes, dtype=bool)
                    keep[1:] = sizes[1:] >= min_a
                    vm2 = keep[lbl_arr]
            if not vm2.any():
                return np.zeros((H, W, 3), dtype=np.float32)
            # 4) skeletonize + render as EDT-based anti-aliased tubes.
            try:
                from skimage.morphology import skeletonize
                skel = skeletonize(vm2)
            except Exception:
                skel = vm2
            edt = distance_transform_edt(~skel)
            r_tube = max(0.5, float(branch_ctx_r_var.get()))
            r_norm = np.clip(1.0 - edt / r_tube, 0.0, 1.0)
            profile = 0.5 * (1.0 + np.cos(np.pi
                                            * np.clip(1.0 - r_norm, 0.0, 1.0)))
            profile = profile * (r_norm > 0)
            hue = _hex_to_rgb01(hue_hex)
            rgb = np.zeros((H, W, 3), dtype=np.float32)
            for ch in range(3):
                rgb[..., ch] = profile * hue[ch] * float(alpha)
            return rgb

        # ── Trace up to `n_max` longest simple branches through the
        # extracted skeleton.  Each branch is a list of (y, x) pixels from
        # an endpoint to a junction (or another endpoint).
        # ── Skeleton → up-to-3 longest MAIN branch paths ───────────────
        # Rewrites the naive endpoint→junction stub extractor. Three-stage
        # pipeline: (1) pre-clean = bridge nearby endpoints + prune spurs;
        # (2) BFS pairwise geodesic to find the diameter; (3) trace the
        # longest simple path continuing STRAIGHT through junctions, then
        # remove those pixels and repeat up to `n_max` times.
        def _extract_skeleton_branches(skel, n_max=MAX_LINES,
                                          bridge_max_px=8, min_twig_len=8):
            if skel is None or not skel.any():
                return []
            H, W = skel.shape

            # Work on a mutable set of (y, x) skeleton pixels.
            ys0, xs0 = np.where(skel)
            pts = set(zip(ys0.tolist(), xs0.tolist()))

            def _nbrs(y, x, S):
                out = []
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0: continue
                        ny, nx = y + dy, x + dx
                        if (ny, nx) in S:
                            out.append((ny, nx))
                return out

            # ── (1a) Bridge nearby endpoints with a straight raster line
            # so fragmented main branches reconnect before path finding.
            def _draw_line(a, b, S):
                y0, x0 = a; y1, x1 = b
                dx = x1 - x0; dy = y1 - y0
                steps = max(1, int(max(abs(dx), abs(dy))))
                for i in range(steps + 1):
                    t = i / steps
                    yi = int(round(y0 + t * dy))
                    xi = int(round(x0 + t * dx))
                    if 0 <= yi < H and 0 <= xi < W:
                        S.add((yi, xi))
            deg = {p: len(_nbrs(p[0], p[1], pts)) for p in pts}
            endpoints = [p for p, d in deg.items() if d == 1]
            if bridge_max_px > 0 and len(endpoints) >= 2:
                # Pair every close endpoint (once)
                used = set()
                # sort by y then x for determinism
                ends_sorted = sorted(endpoints)
                for i, a in enumerate(ends_sorted):
                    if a in used: continue
                    best_j = -1; best_d = float('inf')
                    for j in range(i + 1, len(ends_sorted)):
                        b = ends_sorted[j]
                        if b in used: continue
                        d_e = float(np.hypot(a[0] - b[0], a[1] - b[1]))
                        if d_e < best_d and d_e <= bridge_max_px:
                            best_d = d_e; best_j = j
                    if best_j >= 0:
                        _draw_line(a, ends_sorted[best_j], pts)
                        used.add(a); used.add(ends_sorted[best_j])
                # Recompute degrees
                deg = {p: len(_nbrs(p[0], p[1], pts)) for p in pts}

            # ── (1b) Prune spurs shorter than `min_twig_len`. Repeat until
            # no more spurs. A spur is a path from an endpoint that reaches
            # a junction (or ends) in < min_twig_len pixels.
            def _prune_once():
                nonlocal deg
                ends = [p for p, d in deg.items() if d == 1]
                removed_any = False
                to_remove = set()
                for e in ends:
                    if e in to_remove: continue
                    path = [e]; cur = e
                    prev = None
                    while True:
                        nbs = [n for n in _nbrs(cur[0], cur[1], pts)
                                if n != prev and n not in to_remove]
                        if not nbs: break
                        if len(nbs) >= 2:
                            # junction: stop; do not include junction pixel
                            break
                        prev = cur; cur = nbs[0]; path.append(cur)
                        if len(path) > min_twig_len:
                            path = None; break
                    if path is not None and 1 <= len(path) <= min_twig_len:
                        to_remove.update(path)
                        removed_any = True
                if to_remove:
                    for p in to_remove:
                        pts.discard(p)
                    deg = {p: len(_nbrs(p[0], p[1], pts)) for p in pts}
                return removed_any
            for _ in range(6):
                if not _prune_once(): break

            # ── (2) BFS geodesic between endpoints. Returns dict of
            # {endpoint: (dist_to_farthest, farthest_endpoint, parent_map)}.
            def _bfs(src, S):
                from collections import deque
                dist = {src: 0}; parent = {src: None}
                q = deque([src])
                while q:
                    y, x = q.popleft()
                    for n in _nbrs(y, x, S):
                        if n not in dist:
                            dist[n] = dist[(y, x)] + 1
                            parent[n] = (y, x)
                            q.append(n)
                return dist, parent

            def _reconstruct(parent, end):
                path = []; cur = end
                while cur is not None:
                    path.append(cur)
                    cur = parent[cur]
                path.reverse()
                return path

            # ── (3) Trace the top-`n_max` longest simple paths. Each pass:
            # find the diameter of the current skeleton graph via
            # double-BFS, record the path, then remove its pixels + any
            # now-orphaned twig fragments and repeat on what's left.
            branches = []
            for _ in range(int(n_max)):
                if not pts: break
                ends = [p for p, d in deg.items() if d == 1]
                if not ends:
                    # No endpoints — pick any node as seed
                    seed = next(iter(pts))
                else:
                    seed = ends[0]
                d0, _ = _bfs(seed, pts)
                if not d0: break
                far1 = max(d0, key=d0.get)
                d1, p1 = _bfs(far1, pts)
                if not d1: break
                far2 = max(d1, key=d1.get)
                longest_path = _reconstruct(p1, far2)
                if len(longest_path) < 4:
                    break
                branches.append(longest_path)
                # Remove those pixels from the working set
                for p in longest_path:
                    pts.discard(p)
                # Prune again to drop leftover spurs at the removal points
                deg = {p: len(_nbrs(p[0], p[1], pts)) for p in pts}
                for _ in range(3):
                    if not _prune_once(): break

            branches.sort(key=len, reverse=True)
            return branches[:int(n_max)]

        def _seed_centerlines_from_extraction():
            v = st.get('vessel_extracted')
            if not v or v.get('vessel_mask') is None:
                messagebox.showwarning(
                    "Seed centerlines",
                    "Run 'Extract vessel + preview' first."); return
            skel = v.get('skeleton')
            if skel is None:
                try:
                    from skimage.morphology import skeletonize
                    skel = skeletonize(v['vessel_mask'].astype(bool))
                except Exception:
                    skel = v['vessel_mask']
            branches = _extract_skeleton_branches(skel, n_max=MAX_LINES)
            if not branches:
                messagebox.showwarning(
                    "Seed centerlines",
                    "No branch skeleton segments found. Adjust extraction "
                    "params (frangi thr / min-size / gap-close) and retry.")
                return
            # The extraction is on the CROPPED basis — undo the crop offset
            # so the polylines live in the original image frame like the
            # ones the user draws by hand.
            x0_c, y0_c = st.get('_bosf_crop', (0, 0))
            n_target = min(len(branches), MAX_LINES)
            for i in range(MAX_LINES):
                if i < n_target:
                    path = branches[i]           # list[(y, x)]
                    # Subsample to ~24 evenly spaced points along the path
                    n_pts = min(len(path), 24)
                    idxs = np.linspace(0, len(path) - 1, n_pts).astype(int)
                    pts = np.array(
                        [(int(path[k][1]) + int(x0_c),
                          int(path[k][0]) + int(y0_c))
                         for k in idxs], dtype=np.int32)
                    st['centerlines'][i] = pts
                    st['include_lines'][i] = True
                else:
                    # leave prior lines beyond the seeded set intact
                    pass
            _sync_active_line()
            _redraw()
            # Update the include-lines checkboxes so the new lines render.
            try:
                for i in range(min(n_target, MAX_LINES)):
                    _incl_line_vars[i].set(True)
            except Exception: pass
            self._log(f"[seed] populated {n_target} centerline slot(s) "
                      f"from extraction "
                      f"(branch lengths: "
                      f"{[len(b) for b in branches[:n_target]]} px)")
            messagebox.showinfo(
                "Seed centerlines",
                f"Seeded {n_target} centerline(s) from extraction.\n"
                f"Toggle 'overlay centerline' to verify placement, "
                f"then run 'Bolus on structure' to render tubes.")

        # Expose for velocity_map: the current tube mask + per-pixel
        # nearest-centerline distance (so vessel colouring maps velocity
        # continuously along the smoothed centerline).
        def _smooth_centerline_tube_geom(agg01_disp):
            """Return (line_mask, dist) for the current include-lines set on
            the same coordinate frame as `agg01_disp`.  Used by
            velocity_map to colour the tube along its length."""
            from scipy.ndimage import distance_transform_edt
            H, W = agg01_disp.shape
            lines = st.get('_bosf_lines_shifted') or []
            line_mask = np.zeros((H, W), dtype=bool)
            for cl in lines:
                xs = cl[:, 0]; ys = cl[:, 1]
                for i in range(len(xs) - 1):
                    x0, y0 = float(xs[i]), float(ys[i])
                    x1, y1 = float(xs[i + 1]), float(ys[i + 1])
                    seg_len = max(1.0, float(np.hypot(x1 - x0, y1 - y0)))
                    n_step = max(2, int(seg_len * 2))
                    for tt in np.linspace(0.0, 1.0, n_step):
                        xi = int(round(x0 + tt * (x1 - x0)))
                        yi = int(round(y0 + tt * (y1 - y0)))
                        if 0 <= yi < H and 0 <= xi < W:
                            line_mask[yi, xi] = True
            dist = distance_transform_edt(~line_mask) if line_mask.any() else np.full_like(agg01_disp, np.inf)
            return line_mask, dist

        # ── SHARED background helper: dispatches to centerline-tube (new
        # default), data-based, or synthetic-tube renderer per
        # `vessel_bg_mode_var`.  Falls back to the tinted aggregate ONLY
        # when NO extraction/centerline is available.
        # Layer 1: full extracted skeleton (the "K" context) rendered as
        # thin same-hue tubes. Used underneath the straight main flow line.
        def _extracted_skeleton_tube_rgb(mask_2d, hue_hex, alpha=1.0):
            from scipy.ndimage import distance_transform_edt as _dedt
            v = st.get('vessel_extracted')
            if v is None or v.get('vessel_mask') is None: return None
            H, W = mask_2d.shape
            if v['vessel_mask'].shape != (H, W): return None
            skel = v.get('skeleton')
            if skel is None or skel.shape != (H, W):
                try:
                    from skimage.morphology import skeletonize
                    skel = skeletonize(v['vessel_mask'].astype(bool))
                except Exception:
                    skel = v['vessel_mask'].astype(bool)
            if not skel.any(): return None
            dist = _dedt(~skel)
            # Layer 1 tube slightly thinner than main line so it reads
            # as context rather than dominating the composite.
            r_tube = max(0.5, float(cl_tube_radius_var.get()) * 0.6)
            r_norm = np.clip(1.0 - dist / r_tube, 0.0, 1.0)
            profile = 0.5 * (1.0 + np.cos(np.pi
                                            * np.clip(1.0 - r_norm, 0.0, 1.0)))
            profile = profile * (r_norm > 0)
            hue = _hex_to_rgb01(hue_hex)
            rgb = np.zeros((H, W, 3), dtype=np.float32)
            for ch in range(3):
                rgb[..., ch] = profile * hue[ch] * float(alpha)
            return rgb

        def _virtual_structure_rgb(agg01_disp, mask_2d, hue_hex, alpha=1.0):
            mode = vessel_bg_mode_var.get()
            # ── A1: 'real_mip' — authentic single-hue fluorescence.
            # Real aggregate intensity, percentile-stretched + gentle
            # gamma + feathered mask edge so the vessel dissolves into
            # black without a hard synthetic boundary.
            if mode == 'real_mip':
                from scipy.ndimage import gaussian_filter as _gf_r
                hue = _hex_to_rgb01(hue_hex)
                a = np.clip(agg01_disp.astype(np.float32), 0.0, 1.0)
                _mb = np.asarray(mask_2d, dtype=bool)
                inside = a[_mb] if _mb.any() else a.ravel()
                if inside.size:
                    p_lo = float(np.percentile(inside, 1.0))
                    p_hi = float(np.percentile(inside, 99.5))
                else:
                    p_lo, p_hi = 0.0, 1.0
                a = np.clip((a - p_lo) / max(p_hi - p_lo, 1e-6),
                            0.0, 1.0)
                a = a ** 0.85
                soft_edge = np.clip(_gf_r(
                    mask_2d.astype(np.float32), sigma=2.0), 0.0, 1.0)
                a = a * soft_edge
                rgb = np.zeros((*a.shape, 3), dtype=np.float32)
                for ch in range(3):
                    rgb[..., ch] = a * hue[ch] * float(alpha)
                return rgb
            # ── A2: 'depth' — depth-coded MIP (hue = axial depth,
            # brightness = MIP, saturation = confidence). Exploits the
            # SLIM volumetric reconstruction; recommended hero rendering.
            if mode == 'depth':
                import matplotlib.cm as _cm_d
                import matplotlib.colors as _mcol_d
                from scipy.ndimage import gaussian_filter as _gf_d
                a = np.clip(agg01_disp.astype(np.float32), 0.0, 1.0)
                _rv = getattr(self, 'recon_volume', None)
                if (_rv is not None and _rv.ndim == 4
                        and _rv.shape[:2] == agg01_disp.shape):
                    _tmip = np.max(_rv, axis=3)
                    z_arg = np.argmax(_tmip, axis=2).astype(np.float32)
                    D_ = max(1.0, float(_rv.shape[2] - 1))
                    depth01 = z_arg / D_
                else:
                    depth01 = np.zeros_like(a)
                _mb = np.asarray(mask_2d, dtype=bool)
                inside = a[_mb] if _mb.any() else a.ravel()
                if inside.size:
                    p_lo = float(np.percentile(inside, 1.0))
                    p_hi = float(np.percentile(inside, 99.5))
                else:
                    p_lo, p_hi = 0.0, 1.0
                val = (np.clip((a - p_lo) / max(p_hi - p_lo, 1e-6),
                                0.0, 1.0)) ** 0.85
                v_ext = st.get('vessel_extracted')
                soft = (v_ext.get('soft_intensity')
                        if (v_ext is not None
                            and v_ext.get('soft_intensity') is not None
                            and v_ext['soft_intensity'].shape == a.shape)
                        else None)
                conf = np.clip(soft if soft is not None else val, 0.0, 1.0)
                sat = 0.35 + 0.65 * conf
                try:
                    _cmap_name = str(vessel_depth_cmap_var.get())
                except Exception:
                    _cmap_name = 'turbo'
                depth_cmap = _cm_d.get_cmap(_cmap_name)
                base_rgb = depth_cmap(
                    np.clip(depth01, 0.0, 1.0))[..., :3].astype(np.float32)
                hsv = _mcol_d.rgb_to_hsv(base_rgb)
                hsv[..., 1] = np.clip(hsv[..., 1] * sat, 0.0, 1.0)
                hsv[..., 2] = val
                rgb = _mcol_d.hsv_to_rgb(hsv).astype(np.float32)
                soft_edge = np.clip(_gf_d(
                    mask_2d.astype(np.float32), sigma=1.5), 0.0, 1.0)
                rgb = rgb * soft_edge[..., None] * float(alpha)
                self._log(f"[vessel-bg] depth-coded MIP "
                          f"(cmap={_cmap_name}, D={depth01.shape})")
                return rgb.astype(np.float32)
            if mode == 'centerline':
                # TWO-LAYER seamless composite:
                #   Layer 1 = extracted-skeleton "K" (context, all branches)
                #   Layer 2 = straight main line (the flow the bolus rides)
                # Element-wise MAX so the two same-hue layers merge with no
                # seam and no double-brightness edge.
                main_layer = _thickened_skeleton_rgb(agg01_disp, mask_2d,
                                                        hue_hex, alpha)
                skel_layer = _extracted_skeleton_tube_rgb(mask_2d, hue_hex,
                                                            alpha)
                if skel_layer is not None:
                    return np.maximum(main_layer, skel_layer)
                return main_layer
            v = st.get('vessel_extracted')
            if (v is not None
                    and v.get('vessel_mask') is not None
                    and v['vessel_mask'].shape == agg01_disp.shape):
                if vessel_bg_mode_var.get() == 'synthetic':
                    return _synthetic_tube_rgb(agg01_disp, mask_2d,
                                                  hue_hex, alpha)
                # 'data' path (data-based extraction).
                hue = _hex_to_rgb01(hue_hex)
                soft = v.get('soft_intensity')
                if soft is None or soft.shape != agg01_disp.shape:
                    soft = v['vessel_mask'].astype(np.float32)
                blend = float(np.clip(vess_blend_var.get(), 0.0, 1.0))
                agg_layer = np.clip(agg01_disp.astype(np.float32),
                                      0.0, 1.0) * mask_2d.astype(np.float32)
                inten = blend * soft + (1.0 - blend) * agg_layer
                rgb = np.zeros((*inten.shape, 3), dtype=np.float32)
                for ch in range(3):
                    rgb[..., ch] = inten * hue[ch] * float(alpha)
                skel = v.get('skeleton')
                if skel is not None and skel.shape == agg01_disp.shape:
                    for ch in range(3):
                        rgb[..., ch] = np.where(skel,
                                                  np.clip(rgb[..., ch]
                                                            + 0.30, 0.0, 1.0),
                                                  rgb[..., ch])
                return rgb
            # Fallback: tinted aggregate — logged.
            if v is None:
                self._log("[vessel] no extraction cached — using tinted "
                          "aggregate. Click 'Extract vessel + preview' "
                          "for the Fig.2-style clean vessel background.")
            return _tinted_aggregate_rgb(agg01_disp, mask_2d, hue_hex, alpha)

        # Draw the drawn centerline on top of any rendered figure axes so
        # the user can VISUALLY verify the bolus rides on the centerline.
        def _draw_centerline_overlay(ax):
            """Draw the dashed centerline(s). Returns the list of Line2D artists
            created (empty if the overlay is off) so callers can toggle them."""
            _arts = []
            if not bool(centerline_overlay_var.get()): return _arts
            lines = st.get('_bosf_lines_shifted') or []
            if not lines:
                x0_c, y0_c = st.get('_bosf_crop', (0, 0))
                incl = st.get('include_lines', [True, False, False])
                for i in range(MAX_LINES):
                    if i < len(incl) and incl[i]:
                        cl = st['centerlines'][i]
                        if cl is not None and len(cl) >= 2:
                            arr = cl.astype(np.float32).copy()
                            arr[:, 0] -= float(x0_c)
                            arr[:, 1] -= float(y0_c)
                            lines.append(arr)
            for cl in lines:
                _ln = ax.plot(cl[:, 0], cl[:, 1], '--',
                              color='#ffd54a', lw=1.0, alpha=0.9)
                _arts += list(_ln)
            return _arts

        # ── SHARED arclength → (x, y) pixel mapping used by ALL modes so
        # the SAME s* always lands at the SAME pixel.  Reads the crop-
        # shifted `L['centers']` set once by autocrop in
        # `_fig_bolus_on_structure`; every renderer (highlight / mip_bolus /
        # velocity_map / trajectory / …) MUST route through this to keep
        # bolus positions consistent.
        def _arclen_to_xy(L, s_um):
            _al = L['arclen_um']; _cn = L['centers']
            i = int(np.argmin(np.abs(_al - float(s_um))))
            return (float(_cn[i, 0]), float(_cn[i, 1]))

        # ── DISPLAY-ONLY tight-zoom: set axes limits to the vessel bbox
        # (+ pad) so the vessel fills the panel. Nothing moves in the
        # arrays; `imshow` still shows pixel (x0, y0) at data coordinate
        # (x0, y0) — the axes are just cropped. `_scale_bar_µm` reads
        # `ax.get_xlim/ylim` so its physical length stays correct.
        def _zoom_axes_to_vessel(ax, mask_bool, pad_frac=None):
            try:
                if not bool(tight_zoom_var.get()): return
            except Exception: return
            _mb = np.asarray(mask_bool, dtype=bool)
            if not _mb.any(): return
            ys, xs = np.where(_mb)
            if pad_frac is None:
                try:
                    pad_frac = float(np.clip(
                        tight_zoom_pad_var.get(), 0.0, 0.5))
                except Exception:
                    pad_frac = 0.10
            y0, y1 = int(ys.min()), int(ys.max())
            x0, x1 = int(xs.min()), int(xs.max())
            py = int(round((y1 - y0 + 1) * pad_frac)) + 1
            px = int(round((x1 - x0 + 1) * pad_frac)) + 1
            cx, cy = 0.5 * (x0 + x1), 0.5 * (y0 + y1)
            half = 0.5 * max((x1 - x0) + 2 * px,
                              (y1 - y0) + 2 * py)
            ax.set_xlim(cx - half, cx + half)
            ax.set_ylim(cy + half, cy - half)  # inverted-y (image coords)

        # ── Mini-variant that computes the velocity-colored flow-line
        # RGB WITHOUT opening a window (Task 1a). Same math as the
        # standalone `_render_velocity_map`: restrict to the picked
        # flow line's tube, densified centerline lookup, regression
        # v(s) via smoothing-spline on inliers, colormap. `_compute_flow_
        # velocity_rgb` returns (vel_rgb HxWx3, tube_a HxW FLOAT alpha,
        # v_lo, v_hi, cmap_name) — the 2nd value is a feathered per-pixel
        # alpha (was a bool mask) so callers composite the tube softly.
        # ═══ Shared layer-compositing helpers (DISPLAY-only) ═══════════════
        def _alpha_over(base_rgb, top_rgb, alpha):
            # base/top: HxWx3 float in [0,1]; alpha: HxW float in [0,1]
            # (already scaled by the global opacity). Standard "over" blend.
            a = np.clip(alpha, 0.0, 1.0)[..., None]
            return np.clip(base_rgb * (1.0 - a) + top_rgb * a,
                            0.0, 1.0).astype(np.float32)

        def _open_opacity_preview(fig, axes_images, layers, opacity_specs,
                                    default_stem, win=None, on_saved=None):
            """Interactive opacity preview/save. Re-blends CACHED per-panel
            layers (no re-tracking / re-fit) so dragging is instant and the
            SAVED file equals the previewed composite. z-order per panel:
            frame -> struct -> velocity -> bolus, each layer's per-pixel
            alpha multiplied by its global slider opacity. Pass `win` to
            build the controls into an already-created Toplevel."""
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            if win is None:
                win = tk.Toplevel(pw)
                win.title(f"Opacity preview — {default_stem}")
                win.geometry("1180x900")
            bot = ttk.Frame(win); bot.pack(side=tk.BOTTOM, fill=tk.X,
                                             padx=4, pady=3)
            sld = ttk.Frame(win); sld.pack(side=tk.BOTTOM, fill=tk.X,
                                             padx=4, pady=2)
            canvas = FigureCanvasTkAgg(fig, win)
            canvas.get_tk_widget().pack(side=tk.TOP, fill=tk.BOTH, expand=True)

            def _base_like():
                for Lk in layers:
                    for _key in ('frame', 'struct', 'vel', 'bolus'):
                        if _key in Lk and Lk[_key] is not None:
                            return np.zeros_like(Lk[_key], dtype=np.float32)
                return None

            def _recomposite():
                opac = {key: float(var.get())
                        for (key, _lab, _df, var) in opacity_specs}
                for k, img in enumerate(axes_images):
                    Lk = layers[k]
                    if 'frame' in Lk and Lk['frame'] is not None:
                        base = (np.clip(Lk['frame'], 0.0, 1.0)
                                * opac.get('frame', 1.0)).astype(np.float32)
                    else:
                        base = _base_like()
                        if base is None:
                            continue
                    if Lk.get('struct') is not None and Lk.get('struct_a') is not None:
                        base = _alpha_over(base, Lk['struct'],
                                            Lk['struct_a'] * opac.get('struct', 1.0))
                    if Lk.get('vel') is not None and Lk.get('vel_a') is not None:
                        base = _alpha_over(base, Lk['vel'],
                                            Lk['vel_a'] * opac.get('vel', 1.0))
                    if Lk.get('bolus') is not None and Lk.get('bolus_a') is not None:
                        base = _alpha_over(base, Lk['bolus'],
                                            Lk['bolus_a'] * opac.get('bolus', 1.0))
                    img.set_data(np.clip(base, 0.0, 1.0))
                canvas.draw_idle()

            # debounced recomposite so dragging stays smooth
            _pending = {'id': None}
            def _schedule(*_a):
                if _pending['id'] is not None:
                    try: win.after_cancel(_pending['id'])
                    except Exception: pass
                _pending['id'] = win.after(60, _recomposite)

            for (key, label, dflt, var) in opacity_specs:
                row = ttk.Frame(sld); row.pack(fill=tk.X, pady=1)
                ttk.Label(row, text=label, width=18).pack(side=tk.LEFT)
                s = ttk.Scale(row, from_=0.0, to=1.0, variable=var,
                                orient=tk.HORIZONTAL, command=_schedule)
                s.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=4)
            def _save_fig_and_data():
                p = _save_fig_dialog(fig, parent=win, default_stem=default_stem)
                if p and on_saved is not None:
                    try:
                        on_saved(os.path.splitext(p)[0])
                    except Exception as _e:
                        messagebox.showwarning("Source Data export failed",
                                               f"Figure saved, but Source Data failed: {_e}")
            ttk.Button(bot, text=("Save (PDF/SVG/PNG + Source Data)"
                                  if on_saved is not None else "Save (PDF/SVG/PNG)"),
                       command=_save_fig_and_data).pack(side=tk.LEFT, padx=2)
            ttk.Button(bot, text="Close",
                       command=win.destroy).pack(side=tk.RIGHT, padx=2)
            _recomposite()
            canvas.draw()
            return win

        # ══ SHARED velocity core (single source of truth for v(s) -> per-pixel
        #    -> normalization). Used by BOTH _render_velocity_map (standalone)
        #    and _compute_flow_velocity_rgb (MIP+bolus merge) so they agree. ══
        def _vel_curves_for_line(L):
            """v(s) for one line: robust s(t) smoothing-spline -> analytic derivative -> v(s)
            grid, plus the display-smoothed grid and the per-arclength confidence.
            Returns (s_grid, v_grid, v_disp_grid, fb_const) or None if < 3 usable points.
            Stashes L['_conf_grid'], L['_vcurve'], L['_fb_const'], L['_vdisplay_dense'].
            This is the ONLY place v(s) is built."""
            try:
                from scipy.ndimage import gaussian_filter1d as _gf1
            except Exception:
                _gf1 = None
            try:
                from scipy.interpolate import make_smoothing_spline as _mss
            except Exception:
                _mss = None
            t_  = np.asarray(L['t_s'], dtype=float)
            s_  = np.asarray(L['s_star_um'], dtype=float)
            inl = np.asarray(L.get('inlier_mask', np.ones(t_.shape, bool)), dtype=bool)
            m_slope  = float(L.get('m_s', 0.0))
            # C1: v_floor is the physical clamp; the legacy |slope| clamp is opt-in.
            v_floor  = float(vel_floor_var.get())
            fallback = max(v_floor, abs(m_slope)) if vel_clamp_to_slope_var.get() else v_floor
            fb_const = max(v_floor, abs(m_slope))      # only for the too-few-points case
            L['_fb_const'] = fb_const
            ti = t_[inl]; si = s_[inl]
            order = np.argsort(ti); ti = ti[order]; si = si[order]
            if ti.size < 3:
                L['_conf_grid'] = None; L['_vcurve'] = None
                return None
            n_dense = 400
            t_dense = np.linspace(float(ti[0]), float(ti[-1]), n_dense)
            s_dense = None; v_dense = None
            if _mss is not None:
                try:
                    spl = _mss(ti, si); s_dense = spl(t_dense); v_dense = spl.derivative()(t_dense)
                except Exception:
                    s_dense = None
            if s_dense is None:
                deg = 2 if ti.size < 6 else 3
                try:
                    coef = np.polyfit(ti, si, deg); p = np.poly1d(coef)
                    s_dense = p(t_dense); v_dense = np.polyder(p)(t_dense)
                except Exception:
                    L['_conf_grid'] = None; L['_vcurve'] = None
                    return None
            # Speed = local d(arclength)/dt consistent with the fitted slope; NO vel_floor floor and
            # NO 1/slope. The only clamp is the display-only [0.25,4]×|fit| inside the shared helper.
            v_dense = _local_speed_from_arclength(t_dense, s_dense, m_slope, float(L.get('r2', 0.0)))
            if _gf1 is not None:
                v_dense = _gf1(np.asarray(v_dense, dtype=float), sigma=1.0)
            so = np.argsort(s_dense)
            s_sorted = np.asarray(s_dense)[so]; v_sorted = np.asarray(v_dense)[so]
            keep = np.concatenate(([True], np.diff(s_sorted) > 1e-6))
            s_grid = s_sorted[keep].astype(np.float32); v_grid = v_sorted[keep].astype(np.float32)
            self._log(f"[velmap] low-end clamp = {fallback:.2f} µm/s "
                      f"(legacy |slope| clamp {'ON' if vel_clamp_to_slope_var.get() else 'OFF'}); "
                      f"raw v range [{np.nanmin(v_grid):.1f}, {np.nanmax(v_grid):.1f}] µm/s")
            # DISPLAY ONLY: smooth the color-lookup v(s) along arclength.
            v_display_grid = v_grid
            try:
                _sd, _vi, _vd, _dmeta = _smooth_velocity_for_display(
                    s_grid, v_grid, smooth_um=float(vel_display_smooth_um_var.get()),
                    dense_step_um=float(vel_dense_step_um_var.get()))
                if _sd is not None:
                    v_display_grid = np.interp(s_grid, _sd, _vd).astype(np.float32)
                    L['_vdisplay_dense'] = (_sd, _vi, _vd, _dmeta)
            except Exception as _e_sd:
                self._log(f"[velmap] display smoothing skipped: {_e_sd}")
                v_display_grid = v_grid
            # per-arclength confidence from residuals of raw inlier points vs the fit.
            try:
                resid = np.abs(si - np.interp(ti, t_dense, s_dense))
                rstd = float(L.get('resid_std', np.std(resid) + 1e-6)) or 1e-6
                conf_pts = np.exp(-(resid / (2.0 * rstd)) ** 2)
                so_i = np.argsort(si)
                conf_s = np.interp(s_grid, si[so_i], conf_pts[so_i], left=0.4, right=0.4)
                conf_s = np.clip(conf_s, 0.25, 1.0)
                if _gf1 is not None:
                    conf_s = _gf1(conf_s, sigma=2.0)
                L['_conf_grid'] = (s_grid.copy(), conf_s.astype(np.float32))
            except Exception:
                L['_conf_grid'] = None
            L['_vcurve'] = (s_grid, v_grid, v_display_grid, float(fallback))
            return (s_grid, v_grid, v_display_grid, fb_const)

        def _vel_pixels_from_s(L, nearest_s):
            """Per-pixel velocity for one line via `_extend_v_of_s` (pixels outside the picked
            span get a slope-continuous extension, never a flat constant).
            Returns (v_raw_px, v_disp_px, extrap_conf_px, measured_px). The residual confidence
            (L['_conf_grid']) is folded in separately by each caller's HSV step."""
            ns = np.asarray(nearest_s)
            npx = int(ns.size)
            s_s, v_s, v_disp_grid, fb = L['_vcurve']
            s_full_lo = float(np.nanmin(ns)); s_full_hi = float(np.nanmax(ns))
            _emode = str(vel_extrap_mode_var.get())
            _tau   = float(vel_extrap_taper_um_var.get())
            _step  = max(0.25, float(vel_dense_step_um_var.get()))
            _hmax  = float(np.nanmax(v_s)) * 3.0 if np.isfinite(np.nanmax(v_s)) else None
            _sdR, _vdR, _cdR = _extend_v_of_s(s_s, v_s, s_full_lo, s_full_hi, mode=_emode,
                                              taper_um=_tau, floor=0.0,   # color path: no vel_floor
                                              step_um=_step, hard_max=_hmax)
            _sdD, _vdD, _cdD = _extend_v_of_s(s_s, v_disp_grid, s_full_lo, s_full_hi, mode=_emode,
                                              taper_um=_tau, floor=0.0,   # color path: no vel_floor
                                              step_um=_step, hard_max=_hmax)
            if _sdR is None:
                v_raw_px = np.full(npx, fb, np.float32); v_disp_px = v_raw_px.copy()
                extrap_conf_px = np.ones(npx, np.float32); measured_px = np.ones(npx, bool)
            else:
                v_raw_px = np.interp(ns, _sdR, _vdR).astype(np.float32)
                v_disp_px = np.interp(ns, _sdD, _vdD).astype(np.float32)
                extrap_conf_px = np.interp(ns, _sdR, _cdR).astype(np.float32)
                measured_px = (ns >= s_s[0]) & (ns <= s_s[-1])
            if _emode == 'none':
                _nanmask = ~np.isfinite(v_raw_px)
                self._log(f"[velmap] extrap='none': {int(_nanmask.sum())} px left uncolored")
            self._log(f"[velmap] v(s) extended over s=[{s_full_lo:.1f},{s_full_hi:.1f}] µm "
                      f"(measured span [{s_s[0]:.1f},{s_s[-1]:.1f}] µm, mode={_emode}, τ={_tau:.0f} µm); "
                      f"{100.0*measured_px.mean():.1f}% of colored px are measured")
            return v_raw_px, v_disp_px, extrap_conf_px, measured_px

        def _vel_color_norm(v_raw_px, measured_px, line_infos):
            """Colorbar range. Honors vel_max_var (explicit cap wins), vel_norm_mode_var
            (robust|percentile|local|absolute) and vel_norm_measured_only_var. Range is from the
            RAW velocity. Sets st['_velmap_norm_meta']. Returns (v_lo, v_hi, norm_label, norm_mode)."""
            combined_all = v_raw_px[np.isfinite(v_raw_px)]
            if vel_norm_measured_only_var.get() and measured_px is not None and np.any(measured_px):
                _vv = v_raw_px[np.asarray(measured_px, bool)]
                combined = _vv[np.isfinite(_vv)]
                if combined.size < 16: combined = combined_all
            else:
                combined = combined_all
            _n_measured = int(combined.size)
            vmax_ui = float(vel_max_var.get())
            norm_mode = str(vel_norm_mode_var.get())
            _slope_max = max((abs(float(L.get('m_s', 0.0))) for L in line_infos), default=0.0)
            if vmax_ui > 0:
                v_lo, v_hi = 0.0, vmax_ui
                norm_label = f"absolute fixed 0..{vmax_ui:.1f} (vel max)"
            elif norm_mode == 'percentile':
                if combined.size:
                    v_lo = float(np.nanpercentile(combined, 2))
                    v_hi = float(np.nanpercentile(combined, 98))
                else:
                    v_lo, v_hi = 0.0, 100.0
                norm_label = "display range P2-P98 of raw velocity"
            elif norm_mode == 'local':
                if combined.size:
                    v_lo = float(np.nanmin(combined)); v_hi = float(np.nanmax(combined))
                else:
                    v_lo, v_hi = 0.0, 100.0
                norm_label = "local contrast, exploratory display only"
            elif norm_mode == 'robust':
                if combined.size:
                    v_lo = float(np.nanpercentile(combined, 2))
                    v_hi = float(np.nanpercentile(combined, 98))
                    _span_min = max(1.0, 0.05 * max(abs(v_hi), 1.0))
                    if (v_hi - v_lo) < _span_min:
                        _mid = 0.5 * (v_hi + v_lo)
                        v_lo, v_hi = _mid - 0.5 * _span_min, _mid + 0.5 * _span_min
                else:
                    v_lo, v_hi = 0.0, 100.0
                norm_label = f"robust display range P2-P98 = [{v_lo:.1f}, {v_hi:.1f}] µm/s"
            else:   # 'absolute' auto
                if combined.size:
                    _p98 = float(np.nanpercentile(combined, 98)); _fmax = float(np.nanmax(combined))
                    v_lo, v_hi = 0.0, max(_p98, _slope_max, _fmax)
                else:
                    v_lo, v_hi = 0.0, 100.0
                norm_label = f"absolute auto 0..max(P98,|slope|,finite max) = {v_hi:.1f}"
            if not np.isfinite(v_lo): v_lo = 0.0
            if not np.isfinite(v_hi) or v_hi <= v_lo: v_hi = v_lo + 1.0
            st['_velmap_norm_meta'] = dict(norm_mode=norm_mode, vmin=float(v_lo), vmax=float(v_hi),
                                           label=norm_label, n_measured=int(_n_measured),
                                           measured_only=bool(vel_norm_measured_only_var.get()),
                                           extrap_mode=str(vel_extrap_mode_var.get()),
                                           extrap_taper_um=float(vel_extrap_taper_um_var.get()),
                                           legacy_slope_clamp=bool(vel_clamp_to_slope_var.get()))
            return float(v_lo), float(v_hi), norm_label, norm_mode

        def _compute_flow_velocity_rgb(struct_2d, mask_2d, agg01_disp,
                                          line_infos):
            from scipy.ndimage import (distance_transform_edt,
                                          gaussian_filter1d as _gf1)
            import matplotlib.cm as _cm
            from matplotlib.colors import Normalize as _Norm
            _paths_v = st.get('vessel_paths')
            if (not _paths_v
                    or st.get('_vessel_paths_shape') != mask_2d.shape):
                _paths_v = _build_vessel_paths(agg01_disp, mask_2d,
                                                n_max=MAX_LINES,
                                                resample_n=64)
                st['vessel_paths'] = _paths_v
                st['_vessel_paths_shape'] = mask_2d.shape
            _fpi = st.get('flow_path_idx')
            if _fpi is None and _paths_v:
                _fpi = int(np.argmax([len(p) for p in _paths_v]))
                st['flow_path_idx'] = _fpi
            if not (_paths_v and _fpi is not None
                    and 0 <= int(_fpi) < len(_paths_v)):
                H, W = mask_2d.shape
                return (np.zeros((H, W, 3), dtype=np.float32),
                        np.zeros((H, W), dtype=np.float32),
                        0.0, 1.0, velocity_cmap_var.get())
            # ── Smooth the flow polyline before rasterizing so the tube
            # centerline is a clean spline (~600 pts), not a 64-node
            # zigzag. Geometry only — the tracked path is unchanged.
            _flow_poly = np.asarray(_paths_v[int(_fpi)], dtype=np.float32)
            try:
                from scipy.interpolate import splprep as _splprep, splev as _splev
                if _flow_poly.shape[0] >= 4:
                    _tck, _u = _splprep([_flow_poly[:, 0], _flow_poly[:, 1]],
                                          s=float(_flow_poly.shape[0]) * 0.5, k=3)
                    _uu = np.linspace(0.0, 1.0, 600)
                    _sx, _sy = _splev(_uu, _tck)
                    _flow_poly = np.stack([_sx, _sy], axis=1).astype(np.float32)
            except Exception:
                pass
            _lm = _rasterize_paths([_flow_poly], *mask_2d.shape)
            _tube_dist = distance_transform_edt(~_lm)
            r_tube_lim = max(1.0, float(cl_tube_radius_var.get()))
            vessel_mask = _tube_dist <= r_tube_lim
            # Feathered smoothstep alpha (~1.5 px band) instead of a hard
            # cutout so the tube edge is soft; caller composites with it.
            edge_soft = 1.5
            _ta = np.clip((r_tube_lim - _tube_dist) / max(edge_soft, 1e-6),
                            0.0, 1.0)
            tube_a = (_ta * _ta * (3.0 - 2.0 * _ta)).astype(np.float32)
            soft_intensity = np.clip(
                1.0 - (_tube_dist / r_tube_lim), 0.0, 1.0
                ).astype(np.float32)
            ys_v, xs_v = np.where(vessel_mask)
            n_px = int(ys_v.size)
            H, W = mask_2d.shape
            if n_px == 0:
                return (np.zeros((H, W, 3), dtype=np.float32),
                        np.zeros((H, W), dtype=np.float32), 0.0, 1.0,
                        velocity_cmap_var.get())
            # Densified per-pixel nearest arclength on the FLOW line.
            try:
                from scipy.spatial import cKDTree as _KDT
            except Exception:
                _KDT = None
            L0 = None
            for L in line_infos:
                if int(L.get('line_idx', 0)) == int(_fpi):
                    L0 = L; break
            if L0 is None:
                L0 = line_infos[0] if line_infos else None
            if L0 is None:
                return (np.zeros((H, W, 3), dtype=np.float32),
                        tube_a, 0.0, 1.0,
                        velocity_cmap_var.get())
            cn = np.asarray(L0['centers'],
                             dtype=np.float32)[:, :2]
            al = np.asarray(L0['arclen_um'], dtype=np.float32)
            if cn.shape[0] >= 2 and al.size == cn.shape[0]:
                al_d = np.linspace(float(al[0]), float(al[-1]),
                                     1200).astype(np.float32)
                cx_d = np.interp(al_d, al,
                                  cn[:, 0]).astype(np.float32)
                cy_d = np.interp(al_d, al,
                                  cn[:, 1]).astype(np.float32)
                cn_lookup = np.stack([cx_d, cy_d], axis=1)
                al_lookup = al_d
            else:
                cn_lookup, al_lookup = cn, al
            px_query = np.stack([xs_v, ys_v],
                                 axis=1).astype(np.float32)
            if _KDT is not None:
                tree = _KDT(cn_lookup)
                _, idx = tree.query(px_query)
            else:
                diff = px_query[:, None, :] - cn_lookup[None, :, :]
                idx = np.argmin((diff * diff).sum(-1), axis=1)
            nearest_s = al_lookup[idx]
            # ── SHARED CORE: identical v(s) -> per-pixel -> norm as the standalone
            # velocity map, so the merged flow line renders the SAME.
            curves = _vel_curves_for_line(L0)
            if curves is None:
                fb = max(float(vel_floor_var.get()), abs(float(L0.get('m_s', 0.0))))
                v_raw_px = np.full(n_px, fb, np.float32); v_disp_px = v_raw_px.copy()
                conf_px = np.ones(n_px, np.float32); measured_px = np.ones(n_px, bool)
            else:
                v_raw_px, v_disp_px, _ecp, measured_px = _vel_pixels_from_s(L0, nearest_s)
                # Fold the extrapolation confidence with the residual confidence
                # (L0['_conf_grid']) exactly as the standalone map's HSV step does.
                _res = np.ones(n_px, np.float32)
                _cg = L0.get('_conf_grid')
                if _cg is not None:
                    _sg, _cv = _cg
                    _res = np.clip(np.interp(nearest_s, _sg, _cv,
                                             left=float(_cv[0]), right=float(_cv[-1])).astype(np.float32),
                                   0.25, 1.0)
                conf_px = np.clip(_ecp * _res, 0.0, 1.0).astype(np.float32)
            v_lo, v_hi, _nlabel, _nmode = _vel_color_norm(v_raw_px, measured_px, [L0])
            cmap_name = vel_cmap_var.get()
            cmap = _cm.get_cmap(cmap_name)
            norm = _Norm(vmin=v_lo, vmax=v_hi)
            # COLOR with the display-smoothed field; the RANGE came from the raw field.
            v_rgba = cmap(norm(np.clip(v_disp_px, v_lo, v_hi)))
            # Confidence -> HSV saturation (Value untouched), identical to the standalone map.
            import matplotlib.colors as _mcol_v
            _rgb3 = np.asarray(v_rgba[:, :3], np.float32)
            _hsv = _mcol_v.rgb_to_hsv(_rgb3)
            _hsv[:, 1] = np.clip(_hsv[:, 1] * np.clip(conf_px, 0.0, 1.0), 0.0, 1.0)
            _rgb3 = _mcol_v.hsv_to_rgb(_hsv).astype(np.float32)
            self._log(f"[flowvel] merged: v=[{v_lo:.1f},{v_hi:.1f}] µm/s cmap={cmap_name} "
                      f"norm={_nmode} measured={100.0*measured_px.mean():.1f}%")
            vel_rgb = np.zeros((H, W, 3), dtype=np.float32)
            vel_rgb[ys_v, xs_v, 0] = _rgb3[:, 0]
            vel_rgb[ys_v, xs_v, 1] = _rgb3[:, 1]
            vel_rgb[ys_v, xs_v, 2] = _rgb3[:, 2]
            return (vel_rgb, tube_a,
                    float(v_lo), float(v_hi), cmap_name)

        # ── FAITHFUL Recon-Viewer BASE — the real reconstructed grayscale
        # image (raw time-MIP of the demotioned projection, linearly
        # normalized to [0, 1]) with NO analyzer smoothing/CLAHE/unsharp
        # baked in. If the user has "apply enhancement" ON with
        # `st['enh_settings']`, reuse `slim_recon.enhance.enhance_frame`
        # so the overlay looks identical to what the Recon Viewer shows.
        # Kept `_highlight_struct_base` as an alias so any lingering
        # caller doesn't NameError.
        def _recon_viewer_base():
            _m, _agg01 = _compute_structure_mask()
            base = np.clip(np.asarray(_agg01, dtype=np.float32),
                            0.0, 1.0)
            try:
                if bool(apply_enh_var.get()) and st.get('enh_settings'):
                    from slim_recon.enhance import enhance_frame
                    base = enhance_frame(base, st['enh_settings'])
                    base = np.clip(np.asarray(base, dtype=np.float32),
                                    0.0, 1.0)
            except Exception as _e_rv:
                self._log(f"[overlay] recon enhancement skipped: "
                          f"{_e_rv}")
            return np.stack([base, base, base],
                            axis=-1).astype(np.float32)
        # Alias so any residual reference still resolves.
        def _highlight_struct_base(agg01_disp, mask_2d):
            return _recon_viewer_base()

        # ── VESSEL PREVIEW / TUNING window ──────────────────────────────
        def _open_vessel_preview():
            import traceback as _tb
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            win = tk.Toplevel(pw); win.title("Vessel extraction preview")
            win.geometry("880x780")
            bot = ttk.Frame(win); bot.pack(side=tk.BOTTOM, fill=tk.X,
                                             padx=3, pady=2)
            try:
                mask, agg01 = _compute_structure_mask()
                agg01_disp = _smoothed_structure(agg01)
                res = _extract_vessel(agg01_disp, mask)
                # Render panel 3 STRICTLY from `res` (skeleton -> EDT tube
                # -> tinted hue) so it matches panel 2's extracted vessel
                # exactly. Never dispatches through _virtual_structure_rgb
                # (which would read the global centerline mode).
                def _edt_tube_from_res(_res, hue_hex,
                                          alpha=1.0, r_tube_px=None):
                    from scipy.ndimage import distance_transform_edt
                    src = _res.get('skeleton')
                    if src is None or not src.any():
                        src = _res.get('vessel_mask')
                    if src is None or not src.any():
                        return np.zeros((*agg01_disp.shape, 3),
                                          dtype=np.float32)
                    dist = distance_transform_edt(~src)
                    r_tube = float(r_tube_px if r_tube_px is not None
                                     else max(0.5,
                                               float(cl_tube_radius_var.get())))
                    r_norm = np.clip(1.0 - dist / r_tube, 0.0, 1.0)
                    profile = 0.5 * (1.0 + np.cos(np.pi
                                     * np.clip(1.0 - r_norm, 0.0, 1.0)))
                    profile = profile * (r_norm > 0)
                    hue = _hex_to_rgb01(hue_hex)
                    rgb_l = np.zeros((*src.shape, 3), dtype=np.float32)
                    for ch in range(3):
                        rgb_l[..., ch] = profile * hue[ch] * float(alpha)
                    return rgb_l
                fig = Figure(figsize=(7.5, 7.5), dpi=110,
                              facecolor='white',
                              constrained_layout=True)
                gs = fig.add_gridspec(1, 3, wspace=0.06)
                ax1 = fig.add_subplot(gs[0])
                ax2 = fig.add_subplot(gs[1])
                ax3 = fig.add_subplot(gs[2])
                ax1.imshow(agg01_disp, cmap='gray', vmin=0, vmax=1,
                             interpolation='nearest')
                ax1.contour(mask.astype(float), levels=[0.5],
                              colors=['#00d2ff'], linewidths=0.7)
                ax1.set_title("aggregate + mask outline", fontsize=7)
                ax2.imshow(res['soft_intensity'], cmap='gray',
                             vmin=0, vmax=1, interpolation='nearest')
                ax2.contour(res['vessel_mask'].astype(float),
                              levels=[0.5], colors=['#ff5050'],
                              linewidths=0.8)
                ax2.set_title("vesselness + vessel outline",
                                fontsize=7)
                # Route panel 3 through the SAME simplified-line pipeline
                # the render uses. Invalidate the polyline cache so this
                # build reflects THIS extraction.
                st['vessel_paths'] = None
                st['_vessel_paths_shape'] = None
                rgb = _thickened_skeleton_rgb(
                    agg01_disp, mask,
                    mip_struct_hue_var.get(),
                    alpha=float(struct_alpha_var.get()))
                ax3.imshow(rgb, interpolation='nearest')
                _pv = st.get('vessel_paths') or []
                for _pv_p in _pv:
                    ax3.plot(_pv_p[:, 0], _pv_p[:, 1],
                              '-', color='w', lw=0.6, alpha=0.85)
                ax3.set_title(
                    f"virtual vessel  (clean lines: {len(_pv)})",
                    fontsize=7)
                for ax in (ax1, ax2, ax3):
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values():
                        s_.set_visible(False)
                canvas = FigureCanvasTkAgg(fig, master=win); canvas.draw()
                canvas.get_tk_widget().pack(side=tk.TOP, fill=tk.BOTH,
                                              expand=True)
                def _re_extract():
                    try:
                        mask2, agg2 = _compute_structure_mask()
                        agg2_disp = _smoothed_structure(agg2)
                        res2 = _extract_vessel(agg2_disp, mask2)
                        ax2.clear(); ax3.clear()
                        ax2.imshow(res2['soft_intensity'], cmap='gray',
                                     vmin=0, vmax=1,
                                     interpolation='nearest')
                        ax2.contour(res2['vessel_mask'].astype(float),
                                      levels=[0.5], colors=['#ff5050'],
                                      linewidths=0.8)
                        ax2.set_title("vesselness + vessel outline",
                                         fontsize=7)
                        # Route panel 3 through the shared pipeline again
                        # so preview and render show the same clean line.
                        st['vessel_paths'] = None
                        st['_vessel_paths_shape'] = None
                        rgb2 = _thickened_skeleton_rgb(
                            agg2_disp, mask2,
                            mip_struct_hue_var.get(),
                            alpha=float(struct_alpha_var.get()))
                        ax3.imshow(rgb2, interpolation='nearest')
                        _pv2 = st.get('vessel_paths') or []
                        for _pv_p in _pv2:
                            ax3.plot(_pv_p[:, 0], _pv_p[:, 1],
                                      '-', color='w', lw=0.6, alpha=0.85)
                        ax3.set_title(
                            f"virtual vessel  (clean lines: {len(_pv2)})",
                            fontsize=7)
                        for ax in (ax2, ax3):
                            ax.set_xticks([]); ax.set_yticks([])
                            for s_ in ax.spines.values():
                                s_.set_visible(False)
                        canvas.draw_idle()
                    except Exception as _e:
                        self._log("[vessel] re-extract FAILED:\n"
                                  + _tb.format_exc())
                        messagebox.showwarning("Vessel",
                            f"Re-extract failed: {_e}")
                ttk.Button(bot, text="Re-extract",
                            command=_re_extract).pack(side=tk.LEFT, padx=2)
                def _save_vessel():
                    import datetime as _dt, json as _json
                    p = filedialog.asksaveasfilename(
                        parent=win, title="Save extracted vessel (stem)",
                        initialfile=(f"vessel_extracted_"
                                     f"{_dt.datetime.now().strftime('%Y%m%d-%H%M%S')}"),
                        defaultextension=".tif",
                        filetypes=[("TIF", "*.tif")])
                    if not p: return
                    stem = os.path.splitext(p)[0]
                    try:
                        from PIL import Image as _PIL
                        cur = st.get('vessel_extracted') or res
                        v_u8 = (cur['vessel_mask'].astype(np.uint8) * 255)
                        _PIL.fromarray(v_u8, mode='L').save(
                            stem + "_vessel.tif", compression='tiff_lzw')
                        s_u8 = (np.clip(cur['soft_intensity'], 0, 1)
                                  * 255).astype(np.uint8)
                        _PIL.fromarray(s_u8, mode='L').save(
                            stem + "_vessel_soft.tif",
                            compression='tiff_lzw')
                        if cur.get('skeleton') is not None:
                            k_u8 = (cur['skeleton'].astype(np.uint8) * 255)
                            _PIL.fromarray(k_u8, mode='L').save(
                                stem + "_vessel_skel.tif",
                                compression='tiff_lzw')
                        with open(stem + "_vessel_params.json", "w") as f:
                            _json.dump(cur['params'], f, indent=2)
                        self._log(f"[vessel] saved {stem}_vessel.tif + "
                                  f"soft/skel + _vessel_params.json")
                    except Exception as _es:
                        self._log("[vessel] save FAILED:\n"
                                  + _tb.format_exc())
                        messagebox.showwarning("Save vessel",
                            f"Save failed: {_es}")
                ttk.Button(bot, text="Save extracted (TIF + JSON)",
                            command=_save_vessel).pack(side=tk.LEFT, padx=2)
                ttk.Button(bot, text="Close",
                            command=win.destroy).pack(side=tk.RIGHT, padx=2)
            except Exception as _e:
                self._log("[vessel] preview FAILED:\n" + _tb.format_exc())
                ttk.Label(win,
                    text=f"Vessel extraction failed: "
                         f"{type(_e).__name__}: {_e}",
                    foreground='#a00'
                    ).pack(fill=tk.BOTH, expand=True, padx=8, pady=8)
                messagebox.showerror("Vessel",
                    f"{type(_e).__name__}: {_e}\nSee log for full "
                    f"traceback.")

        # Physically-valid corrected speed helper.  Given per-line raw peak
        # arclength s*(t) and the robust slope m_s (µm/s), return a POSITIVE
        # speed array (µm/s):
        #   1. raw v_raw = smoothed ds/dt
        #   2. component along propagation dir = v_raw * sign(m_s)
        #   3. where that is > 0: keep as-is (real raw magnitude, physical)
        #   4. where <= 0 (raw noise flips backward): blend |v_raw| with |m_s|
        #      via `vel_blend_var`, then clamp to `vel_floor_var`.
        # Returns (v_pos, v_raw, direction_sign).
        def _corrected_speed(t_s, s_star_um, m_s_slope):
            t = np.asarray(t_s, dtype=float)
            s = np.asarray(s_star_um, dtype=float)
            if t.size < 2:
                return (np.zeros_like(t), np.zeros_like(t), 0)
            sm = max(1, int(vel_smooth_var.get()))
            if sm > 1 and s.size >= sm:
                kern = np.ones(sm, dtype=float) / float(sm)
                s_sm = np.convolve(s, kern, mode='same')
            else:
                s_sm = s
            v_raw = np.gradient(s_sm, t)
            dirn = 1 if m_s_slope > 0 else (-1 if m_s_slope < 0 else 1)
            v_dir = v_raw * dirn
            v_abs_raw = np.abs(v_raw)
            blend = float(np.clip(vel_blend_var.get(), 0.0, 1.0))
            m_abs = abs(float(m_s_slope))
            fallback = blend * m_abs + (1.0 - blend) * v_abs_raw
            v_pos = np.where(v_dir > 0, v_dir, fallback)
            floor = max(0.0, float(vel_floor_var.get()))
            v_pos = np.maximum(v_pos, floor)
            return (v_pos.astype(np.float32),
                     v_raw.astype(np.float32), int(dirn))

        def _render_mip_bolus(fig_seed, struct_2d, mask_2d, agg01_disp,
                                line_infos, x0_c, y0_c, fps, pxu,
                                K, r2, m_s):
            from matplotlib.figure import Figure
            import matplotlib.cm as _cm
            H, W = struct_2d.shape
            src_mode = mip_source_var.get()          # max | mean
            view_mode = mip_view_var.get()           # xy | xy+xz
            def _hex_to_rgb(h):
                h = h.lstrip('#')
                if len(h) != 6: return np.array([1.0, 0.0, 0.0], np.float32)
                return np.array([
                    int(h[0:2], 16) / 255.0,
                    int(h[2:4], 16) / 255.0,
                    int(h[4:6], 16) / 255.0], dtype=np.float32)
            hue_struct = _hex_to_rgb(mip_struct_hue_var.get())
            hue_bolus  = _hex_to_rgb(mip_bolus_hue_var.get())
            # Structure MIP as a normalized [0,1] grayscale then tinted.
            # For xy we already have `agg01_disp` (mean/max of the working
            # proj); to honor the src_mode we recompute from the working
            # proj across time.
            proj = _corrected_proj()
            if proj is None:
                raise RuntimeError("no working projection (Rebuild proj first)")
            arr = proj.astype(np.float32, copy=False)
            xy_stack = (np.nanmax(arr, axis=0) if src_mode == 'max'
                          else np.nanmean(arr, axis=0))
            xy_stack = xy_stack[y0_c:y0_c + H, x0_c:x0_c + W]
            lo, hi = float(np.nanmin(xy_stack)), float(np.nanmax(xy_stack))
            xy_norm = np.clip((xy_stack - lo) / max(hi - lo, 1e-9), 0.0, 1.0)
            # apply the smoothing pipeline for a clean MIP background
            xy_norm = _smoothed_structure(xy_norm)
            # x-z view: project along y (axis=0) then across T (axis=0)
            xz_stack = xz_norm = None
            xz_H = xz_W = None
            axial_um = float(mip_axial_um_var.get()) or float(pxu)
            if view_mode == 'xy+xz':
                # Need the raw 4D volume for a proper axial MIP
                if hasattr(self, 'recon_volume') and self.recon_volume is not None:
                    vol4 = self.recon_volume        # (H, W, D, T)
                    Hv, Wv, Dv, Tv = vol4.shape
                    if Dv <= 1:
                        self._log("[mip_bolus] xy+xz requested but D<=1; "
                                  "showing xy only")
                        view_mode = 'xy'
                    else:
                        vol4_max_t = (np.nanmax(vol4, axis=3)
                                        if src_mode == 'max'
                                        else np.nanmean(vol4, axis=3))
                        # vol4_max_t: (H, W, D). Project along H (axis=0)
                        xz_stack = (np.nanmax(vol4_max_t, axis=0)
                                      if src_mode == 'max'
                                      else np.nanmean(vol4_max_t, axis=0))
                        # xz_stack shape: (W, D). Transpose to (D, W).
                        xz_stack = xz_stack.T
                        lo, hi = float(np.nanmin(xz_stack)), float(np.nanmax(xz_stack))
                        xz_norm = np.clip((xz_stack - lo)
                                            / max(hi - lo, 1e-9), 0.0, 1.0)
                        xz_H, xz_W = xz_norm.shape
                else:
                    self._log("[mip_bolus] xy+xz requested but no recon_volume; "
                              "showing xy only")
                    view_mode = 'xy'
            # ── Build figure ──
            n_show = max(2, int(bolus_nframes_var.get()))
            t_show_l = np.linspace(min(L['t_s'][0] for L in line_infos),
                                    max(L['t_s'][-1] for L in line_infos),
                                    n_show)
            use_fit = bool(bolus_use_fit_var.get())
            # NO snapping.  The bolus/vessel geometry is set by
            # `_fig_bolus_on_structure` via _build_paths_from_centerline —
            # line_infos[0]['centers'] and vessel_paths[0] share the same
            # smoothed polyline pixels.  We just verify the alignment.
            # Verify: log bolus↔polyline distance at the first panel time.
            if bool(verify_align_var.get()):
                try:
                    _paths_v = st.get('vessel_paths') or []
                    if _paths_v and line_infos:
                        _lm = _rasterize_paths(_paths_v, *mask_2d.shape)
                        _ys, _xs = np.where(_lm)
                        if _ys.size:
                            L0v = line_infos[0]
                            s0 = float(L0v['s_star_um'][0])
                            bx, by = _arclen_to_xy(L0v, s0)
                            d2 = (_xs - bx) ** 2 + (_ys - by) ** 2
                            _i = int(np.argmin(d2))
                            self._log(
                                f"[align mip_bolus L1] s*={s0:.1f}µm "
                                f"bolus=({bx:.1f},{by:.1f})  "
                                f"nearest_path=({float(_xs[_i]):.1f},"
                                f"{float(_ys[_i]):.1f})  "
                                f"distance={float(np.sqrt(d2[_i])):.2f}px")
                except Exception as _e_va:
                    self._log(f"[mip_bolus] align check failed: {_e_va}")
            # For every panel, precompute per-line s_show + centers_show.
            # CRITICAL: for line 0 (the tracked line whose bolus is drawn)
            # we place directly on `vessel_paths[0]` — the SAME polyline
            # the background renders — via arclength fraction. This
            # bypasses `_arclen_to_xy(L, s)` (which would depend on
            # L['centers'] staying in sync) and guarantees alignment.
            for _L_idx_ms, L in enumerate(line_infos):
                s_show_L = ((L['m_s'] * t_show_l + L['b_s']) if use_fit
                              else np.interp(t_show_l, L['t_s'],
                                              L['s_star_um']))
                s_show_L = np.clip(s_show_L, float(L['arclen_um'][0]),
                                     float(L['arclen_um'][-1]))
                L['s_show'] = s_show_L
                if _L_idx_ms == 0:
                    al = np.asarray(L['arclen_um'], dtype=np.float32)
                    al_span = float(al[-1] - al[0])
                    if al_span > 0:
                        _fracs = (s_show_L - al[0]) / al_span
                        L['centers_show'] = [
                            _bolus_xy_on_primary(float(_f))
                            for _f in _fracs]
                    else:
                        L['centers_show'] = [_arclen_to_xy(L, s)
                                                for s in s_show_L]
                else:
                    L['centers_show'] = [_arclen_to_xy(L, s)
                                            for s in s_show_L]
            # ── SLEEK BOLUS SPRITE — shared with velocity_map. Reads
            # `bolus_shape_var` (default ellipse), `bolus_minor_var`,
            # `bolus_glow_var`; ellipse major axis follows the local
            # flow tangent. Bright compact core + soft halo (additive).
            # Replaces the old hard-disc blob.
            radius_um = max(1e-3, float(bolus_radius_var.get()))
            radius_px = radius_um / max(pxu, 1e-9)
            sigma_px  = max(0.5, radius_px *
                              float(np.clip(bolus_softness_var.get(),
                                              0.0, 2.0)))
            yy_g, xx_g = np.mgrid[0:H, 0:W]
            _bshape_mip = bolus_shape_var.get()
            _bminor_mip = float(np.clip(bolus_minor_var.get(),
                                         0.05, 1.0))
            try:
                _bglow_mip = float(np.clip(bolus_glow_var.get(),
                                             0.0, 1.0))
            except Exception:
                _bglow_mip = 0.55
            def _draw_bolus_sprite(cx, cy, tangent=None):
                dx = xx_g - cx; dy = yy_g - cy
                if _bshape_mip == 'ellipse':
                    if tangent is None or not np.any(tangent):
                        tangent = np.array([1.0, 0.0], dtype=np.float32)
                    tx, ty = float(tangent[0]), float(tangent[1])
                    tn = np.hypot(tx, ty) + 1e-9
                    tx /= tn; ty /= tn
                    u =  dx * tx + dy * ty
                    v = -dx * ty + dy * tx
                    a = radius_px
                    b_ax = max(1.0, a * _bminor_mip)
                    q_core = (u / (a * 0.55)) ** 2 + (v / (b_ax * 0.55)) ** 2
                    core = np.exp(-0.5 * q_core)
                    q_halo = (u / (a * 1.6)) ** 2 + (v / (b_ax * 1.6)) ** 2
                    halo = np.exp(-0.5 * q_halo) * _bglow_mip
                    b = np.clip(core + halo, 0.0, 1.0)
                elif _bshape_mip == 'gaussian':
                    r_sq = dx * dx + dy * dy
                    core = np.exp(-r_sq / (2.0 * (radius_px * 0.55) ** 2))
                    halo = np.exp(-r_sq / (2.0 * (radius_px * 1.6) ** 2)) * _bglow_mip
                    b = np.clip(core + halo, 0.0, 1.0)
                else:               # 'disk' or fallback (still soft edge)
                    r_sq = dx * dx + dy * dy
                    inside = r_sq <= radius_px ** 2
                    soft = np.exp(-r_sq / (2.0 * sigma_px ** 2))
                    core = np.where(inside, 1.0, soft)
                    halo = np.exp(-r_sq / (2.0 * (radius_px * 1.6) ** 2)) * _bglow_mip
                    b = np.clip(core + halo, 0.0, 1.0)
                if bool(bolus_clip_var.get()):
                    b = b * mask_2d.astype(np.float32)
                return b.astype(np.float32)
            _blob_disc = _draw_bolus_sprite   # backcompat alias
            # Layout: xy grid (n_show cells) — optional xz row below
            cols = min(n_show, 4)
            rows = int(np.ceil(n_show / cols)) + (1 if xz_norm is not None else 0)
            with apply_nature_style():
                fig = Figure(figsize=(7.20, 2.3 * rows),
                              dpi=300, facecolor='white',
                              constrained_layout=True)
                gs = fig.add_gridspec(rows, cols, figure=fig,
                                        wspace=0.02, hspace=0.06)
                # Route through the SHARED dispatcher — centerline mode
                # produces the ONLY vessel background. The extracted
                # skeleton is deliberately NOT composited here.
                xy_bg = _virtual_structure_rgb(
                    xy_norm, mask_2d,
                    mip_struct_hue_var.get(),
                    alpha=float(struct_alpha_var.get()))
                # ── OVERLAY ON ORIGINAL DATA is now PER-TIMEPOINT: each
                # panel sits on the real recon frame at its own time (built
                # below, before the panel loop) instead of one static MIP.
                # ── Task 1b: MERGE velocity color onto the flow line
                # (Fig.2a-R merged into Fig.2a-L). Replaces the cyan
                # structure pixels of the flow-line tube with velocity-
                # coded color; bolus still draws on top per panel.
                _vel_cb = None; _vel_range = None
                vel_rgb = None; vel_a = None
                if bool(mip_show_velocity_var.get()):
                    try:
                        # 2nd return is now a per-pixel FLOAT alpha (tube_a),
                        # composited softly per-panel over the real frame.
                        vel_rgb, vel_a, v_lo_m, v_hi_m, _vc_name = (
                            _compute_flow_velocity_rgb(
                                struct_2d, mask_2d, agg01_disp,
                                line_infos))
                        if vel_a is not None and bool((vel_a > 0).any()):
                            # keep vel_rgb/vel_a in scope; composited
                            # per-panel so it lands on top of the real
                            # time-matched frame, not baked into xy_bg.
                            _vel_cb = _vc_name
                            _vel_range = (v_lo_m, v_hi_m)
                            self._log("[mip_bolus] velocity merged "
                                      f"onto flow line "
                                      f"[{v_lo_m:.1f},"
                                      f"{v_hi_m:.1f}] µm/s "
                                      f"(cmap={_vc_name})")
                    except Exception as _e_vm:
                        import traceback as _tb_vm
                        self._log("[mip_bolus] velocity merge "
                                  f"skipped:\n{_tb_vm.format_exc()}")
                # Per-timepoint "overlay on original": each panel sits on the REAL recon
                # frame at that panel's time, honoring "Apply enhancement" (enh_settings
                # synced from the Recon Viewer) exactly like _display_frame does.
                # NOTE: if apply_enh_var is OFF the background is the linear motion-
                # corrected frame (still per-timepoint); enhancement is NOT forced.
                _bg_frames_rgb = None
                if bool(overlay_orig_var.get()):
                    try:
                        _Tproj = int(_corrected_proj().shape[0])
                        _f_show = [int(np.clip(round(float(_t) * float(fps)), 0, _Tproj - 1))
                                   for _t in t_show_l]
                        # grab each enhanced frame, cropped to the render window
                        _raw = [np.asarray(_display_frame(_f), dtype=np.float32)
                                              [y0_c:y0_c + H, x0_c:x0_c + W]
                                for _f in _f_show]
                        _stack = np.stack(_raw, axis=0)
                        # ONE common normalization across the shown frames so brightness is
                        # consistent panel-to-panel (real intensity changes stay visible;
                        # no per-frame auto-scale flicker).
                        _lo = float(np.nanpercentile(_stack, 1.0))
                        _hi = float(np.nanpercentile(_stack, 99.5))
                        _gain = float(np.clip(orig_bright_var.get(), 0.0, 3.0))
                        _bg_frames_rgb = []
                        for _fr in _raw:
                            g = np.clip((_fr - _lo) / max(_hi - _lo, 1e-6), 0.0, 1.0)
                            if _gain != 1.0:
                                g = np.clip(g * _gain, 0.0, 1.0)
                            _bg_frames_rgb.append(np.stack([g, g, g], axis=-1).astype(np.float32))
                        self._log(f"[mip_bolus] overlay-on-original = per-timepoint enhanced "
                                  f"recon frames {_f_show} "
                                  f"(enh={'on' if apply_enh_var.get() else 'off'}, gain={_gain:.2f})")
                    except Exception as _e_ov:
                        import traceback as _tb_ov
                        self._log(f"[mip_bolus] per-frame overlay skipped:\n{_tb_ov.format_exc()}")
                        _bg_frames_rgb = None
                # ── Build each panel from NAMED, alpha-composited layers
                # (frame -> struct -> velocity -> bolus) so opacity is live-
                # adjustable in the preview window and the SAVED file equals
                # what's shown. `struct_a` = the cyan structure's own
                # luminance so it only tints where the vessel is.
                struct_a = np.clip(xy_bg.max(axis=-1), 0.0, 1.0).astype(np.float32)
                _black = np.zeros_like(xy_bg, dtype=np.float32)
                _bolus_rgb = np.empty_like(xy_bg, dtype=np.float32)
                _bolus_rgb[..., 0] = hue_bolus[0]
                _bolus_rgb[..., 1] = hue_bolus[1]
                _bolus_rgb[..., 2] = hue_bolus[2]
                _vel_rgb_f = (vel_rgb.astype(np.float32)
                              if (_vel_range is not None and vel_rgb is not None)
                              else None)
                _vel_a_f = (np.clip(vel_a, 0.0, 1.0).astype(np.float32)
                            if (_vel_range is not None and vel_a is not None)
                            else None)
                op_frame0  = float(np.clip(op_frame_var.get(),  0.0, 1.0))
                op_struct0 = float(np.clip(op_struct_var.get(), 0.0, 1.0))
                imgs = []; layers = []
                for k in range(n_show):
                    r_ = k // cols; c_ = k % cols
                    ax = fig.add_subplot(gs[r_, c_])
                    frame_layer = (_bg_frames_rgb[k].astype(np.float32)
                                    if _bg_frames_rgb is not None else _black)
                    # bolus layer: accumulate per-line sprite alpha; hue const
                    alpha_bl = float(np.clip(bolus_alpha_var.get(), 0.0, 1.0))
                    bolus_a = np.zeros(xy_bg.shape[:2], dtype=np.float32)
                    for L in line_infos:
                        cx, cy = L['centers_show'][k]
                        # Local tangent for ellipse alignment.
                        _tan = None
                        try:
                            _tgs = L.get('tangents')
                            _cn = L.get('centers')
                            if (_tgs is not None
                                    and _cn is not None
                                    and len(_tgs) >= 2):
                                _d2 = ((_cn[:, 0] - cx) ** 2
                                        + (_cn[:, 1] - cy) ** 2)
                                _ii = int(np.argmin(_d2))
                                _tan = np.asarray(
                                    _tgs[_ii], dtype=np.float32)
                        except Exception: pass
                        b = _draw_bolus_sprite(cx, cy, tangent=_tan)
                        bolus_a = np.clip(bolus_a + b, 0.0, 1.0)
                    Lk = {'frame': frame_layer,
                          'struct': xy_bg.astype(np.float32),
                          'struct_a': struct_a,
                          'bolus': _bolus_rgb, 'bolus_a': bolus_a}
                    if _vel_rgb_f is not None and _vel_a_f is not None:
                        Lk['vel'] = _vel_rgb_f; Lk['vel_a'] = _vel_a_f
                    # Initial composite — matches the preview's z-order and
                    # default opacities (velocity at full alpha, no slider).
                    comp = (np.clip(frame_layer, 0.0, 1.0)
                            * op_frame0).astype(np.float32)
                    comp = _alpha_over(comp, xy_bg.astype(np.float32),
                                        struct_a * op_struct0)
                    if 'vel' in Lk:
                        comp = _alpha_over(comp, Lk['vel'], Lk['vel_a'])
                    comp = _alpha_over(comp, _bolus_rgb, bolus_a * alpha_bl)
                    im_h = ax.imshow(comp, interpolation='bilinear')
                    imgs.append(im_h); layers.append(Lk)
                    # Task 2b: zoom axes to the vessel bbox (display-only).
                    _zoom_axes_to_vessel(ax, mask_2d)
                    _draw_centerline_overlay(ax)
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                    # ── ZERO-BASED time label so the first panel reads
                    # t = 0.00 s. `zero_time_var` default ON; disable to
                    # get absolute frame->seconds.
                    _t_disp = (float(t_show_l[k] - t_show_l[0])
                                if bool(zero_time_var.get())
                                else float(t_show_l[k]))
                    ax.text(0.02, 0.98,
                             f"t={_t_disp:.2f} s",
                             transform=ax.transAxes, ha='left', va='top',
                             fontsize=5, color='white',
                             bbox=dict(boxstyle='round,pad=0.15',
                                         fc='black', ec='none', alpha=0.5))
                    if k == 0: panel_letter(ax, 'a')
                    if k == n_show - 1:
                        _scale_bar_µm(ax, _nice_bar_length_um(ax, pxu), pxu)
                # x-z panel spans the extra row
                if xz_norm is not None:
                    ax_z = fig.add_subplot(gs[rows - 1, :])
                    tinted_xz = np.zeros((xz_H, xz_W, 3), dtype=np.float32)
                    for ch in range(3):
                        tinted_xz[..., ch] = xz_norm * hue_struct[ch]
                    # aspect: axial µm/slice vs lateral pxu
                    aspect_z = max(1e-6, axial_um / max(pxu, 1e-9))
                    ax_z.imshow(tinted_xz, interpolation='bilinear',
                                  aspect=aspect_z)
                    ax_z.set_xticks([]); ax_z.set_yticks([])
                    for s_ in ax_z.spines.values(): s_.set_visible(False)
                    _scale_bar_µm(ax_z, 100.0, pxu)
                    ax_z.text(0.02, 0.98, "x-z MIP (axial)",
                                 transform=ax_z.transAxes, ha='left',
                                 va='top', fontsize=6, color='white',
                                 bbox=dict(boxstyle='round,pad=0.15',
                                             fc='black', ec='none',
                                             alpha=0.5))
                    panel_letter(ax_z, 'b')
                # Task 1b: slim velocity colorbar when merged.
                if _vel_range is not None:
                    try:
                        import matplotlib.cm as _cm_mb
                        from matplotlib.colors import Normalize as _N_mb
                        sm_mb = _cm_mb.ScalarMappable(
                            cmap=_cm_mb.get_cmap(_vel_cb),
                            norm=_N_mb(vmin=_vel_range[0],
                                        vmax=_vel_range[1]))
                        sm_mb.set_array([])
                        cbar_mb = fig.colorbar(
                            sm_mb, ax=fig.axes,
                            fraction=0.025, pad=0.02,
                            shrink=0.6, location='right')
                        _tt = np.linspace(_vel_range[0],
                                           _vel_range[1], 5)
                        try:
                            cbar_mb.set_ticks(_tt)
                            cbar_mb.set_ticklabels(
                                [f"{t:.0f}" for t in _tt])
                        except Exception: pass
                        cbar_mb.set_label(
                            "pulse velocity (µm/s)", fontsize=6)
                        cbar_mb.ax.tick_params(labelsize=5,
                                                 length=2, width=0.4)
                        cbar_mb.outline.set_linewidth(0.5)
                    except Exception: pass
                _suptitle = (
                    f"Structure MIP + synthetic bolus  |  src={src_mode}  "
                    f"hue: struct={mip_struct_hue_var.get()} / "
                    f"bolus={mip_bolus_hue_var.get()}  |  N={n_show}")
                if _vel_range is not None:
                    _suptitle += "  |  flow-line v-coded"
                if bool(overlay_orig_var.get()):
                    _suptitle += "  |  overlay: per-t enhanced recon frame"
                fig.suptitle(_suptitle, fontsize=7, y=0.995)
                fig.text(0.5, 0.005,
                          "Structure MIP = real data. Bolus = SYNTHETIC "
                          "(constant radius, along fitted trajectory); "
                          "not raw fluorescence.",
                          ha='center', va='bottom', fontsize=5,
                          color='#a00', style='italic')
                # Opacity preview/save replaces the plain embed for this
                # mode: re-blends the cached per-panel layers live so the
                # user tunes frame / structure / bolus opacity, and the
                # SAVED figure equals the previewed composite.
                _spec = [('frame', 'frame opacity', 1.0, op_frame_var),
                         ('struct', 'structure opacity', 0.85, op_struct_var),
                         ('bolus', 'bolus opacity', 0.9, bolus_alpha_var)]
                w = _open_opacity_preview(fig, imgs, layers, _spec,
                                            "MIP_bolus_Fig2a-L")
                def _save_svg_tif():
                    import datetime as _dt
                    ts = _dt.datetime.now().strftime("%Y%m%d-%H%M%S")
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save MIP+bolus (SVG + TIF)",
                        initialfile=f"MIP_bolus_{ts}",
                        defaultextension=".svg",
                        filetypes=[("SVG", "*.svg")])
                    if not p: return
                    stem = os.path.splitext(p)[0]
                    try:
                        fig.savefig(stem + ".svg", format='svg',
                                     bbox_inches='tight')
                        fig.savefig(stem + ".tif", format='tiff', dpi=300,
                                     bbox_inches='tight',
                                     pil_kwargs={'compression': 'tiff_lzw'})
                        self._log(f"[mip_bolus] wrote {stem}.svg + .tif")
                    except Exception as e:
                        messagebox.showwarning("Export failed",
                            f"Could not save: {e}")
                ttk.Button(w, text="Save MIP+bolus (SVG/TIF)",
                            command=_save_svg_tif).pack(side=tk.BOTTOM,
                                                         padx=2, pady=2)
                self._log(f"[mip_bolus] rendered N={n_show}  view={view_mode}  "
                          f"src={src_mode}")

        # Velocity map: track color-coded by RAW instantaneous speed with
        # a physically-valid POSITIVE correction. Always opens a window
        # (blank if data is thin) with a visible traceback on any failure.
        # Standalone lymphatic-2D structure preview / export. Uses the same
        # mask, autocrop, and `_virtual_structure_rgb` as the Fig.2 modes so
        # every mode shows the same underlying geometry.
        def _fig_lymphatic_2d():
            import traceback as _tb
            from matplotlib.figure import Figure
            w = tk.Toplevel(pw)
            w.title("Lymphatic 2D structure (from mask)")
            bot = ttk.Frame(w); bot.pack(side=tk.BOTTOM, fill=tk.X,
                                            padx=3, pady=2)
            try:
                mask, agg01 = _compute_structure_mask()
                H0, W0 = agg01.shape
                # Same autocrop math as `_fig_bolus_on_structure`.
                do_crop = bool(autocrop_var.get()) and mask.any()
                if do_crop:
                    ys, xs = np.where(mask)
                    pad_frac = float(np.clip(autocrop_pad_var.get(),
                                                0.0, 1.0))
                    y0m, y1m = int(ys.min()), int(ys.max())
                    x0m, x1m = int(xs.min()), int(xs.max())
                    pad_y = int(round((y1m - y0m + 1) * pad_frac))
                    pad_x = int(round((x1m - x0m + 1) * pad_frac))
                    y0_c = max(0, y0m - pad_y)
                    y1_c = min(H0, y1m + pad_y + 1)
                    x0_c = max(0, x0m - pad_x)
                    x1_c = min(W0, x1m + pad_x + 1)
                    agg01_c = agg01[y0_c:y1_c, x0_c:x1_c]
                    mask_c  = mask[y0_c:y1_c, x0_c:x1_c]
                else:
                    agg01_c, mask_c = agg01, mask
                # DISPLAY-only enhancement (bilateral / CLAHE / unsharp /
                # gamma / brightness / contrast). Quantitative arrays never
                # touched.
                agg01_disp = _smoothed_structure(agg01_c)
                struct_alpha = float(np.clip(struct_alpha_var.get(),
                                                0.0, 1.0))
                rgb = _virtual_structure_rgb(
                    agg01_disp, mask_c,
                    mip_struct_hue_var.get(),
                    alpha=struct_alpha)
                # Cache on `st` for reuse (session I/O, other panels)
                st['lymph_struct_2d'] = dict(
                    rgb=rgb.copy(),
                    mask=mask_c.copy(),
                    agg01_disp=agg01_disp.copy(),
                    y0=int(y0_c if do_crop else 0),
                    x0=int(x0_c if do_crop else 0),
                    hue=mip_struct_hue_var.get(),
                    alpha=float(struct_alpha),
                )
                pxu = float(px_var.get())
                with apply_nature_style():
                    fig = Figure(figsize=(5.2, 5.2), dpi=300,
                                  facecolor='white',
                                  constrained_layout=True)
                    ax = fig.add_subplot(111)
                    ax.imshow(rgb, interpolation='nearest')
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                    _scale_bar_µm(ax, _nice_bar_length_um(ax, pxu), pxu)
                    panel_letter(ax, 'a')
                    fig.suptitle(
                        f"Lymphatic 2D structure (from mask)  |  "
                        f"crop={'on' if do_crop else 'off'}  "
                        f"hue={mip_struct_hue_var.get()}  "
                        f"px_on={int(mask_c.sum())}",
                        fontsize=6.5, y=0.995)
                    fig.text(0.5, 0.005,
                              "Data-derived structure (real). Display-only "
                              "brightness/contrast/gamma; measurements "
                              "unchanged.",
                              ha='center', va='bottom', fontsize=5,
                              color='0.35', style='italic')
                    _embed_with_save(w, fig, "lymphatic_2d_structure")
                    def _save_svg_tif():
                        import datetime as _dt
                        ts = _dt.datetime.now().strftime("%Y%m%d-%H%M%S")
                        p = filedialog.asksaveasfilename(
                            parent=w, title="Save lymphatic 2D (SVG + TIF)",
                            initialfile=f"lymphatic_2d_{ts}",
                            defaultextension=".svg",
                            filetypes=[("SVG", "*.svg")])
                        if not p: return
                        stem = os.path.splitext(p)[0]
                        try:
                            fig.savefig(stem + ".svg", format='svg',
                                         bbox_inches='tight')
                            fig.savefig(stem + ".tif", format='tiff',
                                         dpi=300, bbox_inches='tight',
                                         pil_kwargs={'compression':
                                                       'tiff_lzw'})
                            self._log(f"[lymph2d] wrote {stem}.svg + .tif")
                        except Exception as _es:
                            self._log(f"[lymph2d] export FAILED:\n"
                                      f"{_tb.format_exc()}")
                            messagebox.showwarning("Export failed",
                                f"Could not save: {_es}")
                    ttk.Button(bot,
                        text="Save lymphatic 2D (SVG/TIF)",
                        command=_save_svg_tif
                        ).pack(side=tk.LEFT, padx=2)
                    self._log(f"[lymph2d] rendered mask_px={int(mask_c.sum())}  "
                              f"crop={'on' if do_crop else 'off'}")
            except Exception as _e:
                self._log(f"[lymph2d] FAILED:\n{_tb.format_exc()}")
                ttk.Label(w,
                    text=f"Render failed: {type(_e).__name__}: {_e}",
                    foreground='#a00'
                    ).pack(fill=tk.BOTH, expand=True, padx=8, pady=8)
                messagebox.showerror("Render lymphatic 2D",
                    f"{type(_e).__name__}: {_e}\nSee log for full "
                    f"traceback.")

        def _render_velocity_map(struct_2d, mask_2d, agg01_disp,
                                    line_infos, x0_c, y0_c, fps, pxu):
            import traceback as _tb
            from matplotlib.figure import Figure
            from matplotlib.collections import LineCollection
            from matplotlib.colors import Normalize as _Norm
            import matplotlib.cm as _cm
            w = tk.Toplevel(pw)
            w.title("Velocity map (Fig.2a-R analog)")
            bot = ttk.Frame(w); bot.pack(side=tk.BOTTOM, fill=tk.X,
                                            padx=3, pady=2)
            try:
                H, W = struct_2d.shape
                cmap_name = vel_cmap_var.get()
                # Ensure a matching-shape vessel extraction so we can paint
                # the vessel itself with the continuous gradient.
                v_ext = st.get('vessel_extracted')
                if (v_ext is None or v_ext.get('vessel_mask') is None
                        or v_ext['vessel_mask'].shape != mask_2d.shape):
                    _extract_vessel(agg01_disp, mask_2d)
                    v_ext = st.get('vessel_extracted')
                vessel_mask = (v_ext['vessel_mask'] if v_ext is not None
                                 else mask_2d.copy())
                soft_intensity = (v_ext.get('soft_intensity')
                                    if v_ext is not None else None)
                if (soft_intensity is None
                        or soft_intensity.shape != vessel_mask.shape):
                    soft_intensity = vessel_mask.astype(np.float32)
                # Per-line velocity series (RAW + corrected positive).
                for L in line_infos:
                    t_ = L['t_s'].astype(float)
                    s_ = L['s_star_um'].astype(float)
                    if t_.size < 2:
                        L['v_pos'] = np.array([]); L['v_raw'] = np.array([])
                        L['v_pts'] = []; L['v_dir'] = 0
                        continue
                    # Colour by the SAME propagation speed the pulse pipeline reports:
                    # local d(arclength)/dt consistent with the fit (NOT 1/slope, NOT floored).
                    v_line = _local_speed_from_arclength(L['t_s'], L['s_star_um'], L['m_s'], L['r2'])
                    L['v_pos'] = v_line; L['v_raw'] = v_line
                    L['v_dir'] = 1 if float(L['m_s']) >= 0 else -1
                    # SHARED helper: identical arclength->pixel mapping.
                    L['v_pts'] = np.array(
                        [_arclen_to_xy(L, s) for s in s_], dtype=float)
                # DECISIVE unify: colour ONLY the picked flow line's tube,
                # so no branch that isn't the flow line can ever carry
                # velocity color. Reuses `st['vessel_paths']` (indexed by
                # the pick-flow-line step) and rasterizes exactly ONE
                # polyline into `_lm`.
                if vessel_bg_mode_var.get() == 'centerline':
                    from scipy.ndimage import distance_transform_edt
                    _paths_v = st.get('vessel_paths')
                    if (not _paths_v
                            or st.get('_vessel_paths_shape') != mask_2d.shape):
                        _paths_v = _build_vessel_paths(agg01_disp, mask_2d,
                                                          n_max=MAX_LINES,
                                                          resample_n=64)
                        st['vessel_paths'] = _paths_v
                        st['_vessel_paths_shape'] = mask_2d.shape
                    _flow_idx_vm = st.get('flow_path_idx')
                    if _flow_idx_vm is None and _paths_v:
                        # Default to longest polyline; persist for later.
                        _flow_idx_vm = int(np.argmax(
                            [len(p) for p in _paths_v]))
                        st['flow_path_idx'] = _flow_idx_vm
                        self._log(f"[velmap] flow_path_idx unset -> "
                                  f"defaulted to longest polyline "
                                  f"({_flow_idx_vm})")
                    if (_paths_v and _flow_idx_vm is not None
                            and 0 <= int(_flow_idx_vm) < len(_paths_v)):
                        _flow_only = [_paths_v[int(_flow_idx_vm)]]
                        self._log(f"[velmap] restricting vessel_mask to "
                                  f"flow-line tube ONLY "
                                  f"(idx={int(_flow_idx_vm)})")
                    elif _paths_v:
                        _flow_only = _paths_v
                    else:
                        _flow_only = []
                    if _flow_only:
                        _lm = _rasterize_paths(_flow_only, *mask_2d.shape)
                    else:
                        _lm = mask_2d.astype(bool)
                    _tube_dist = distance_transform_edt(~_lm)
                    r_tube_lim = max(1.0, float(cl_tube_radius_var.get()))
                    vessel_mask = _tube_dist <= r_tube_lim
                    soft_intensity = np.clip(
                        1.0 - (_tube_dist / r_tube_lim), 0.0, 1.0
                        ).astype(np.float32)
                # ── Per-vessel-pixel continuous velocity via nearest
                # centerline lookup (owning line + local arclength). ──
                ys_v, xs_v = np.where(vessel_mask)
                n_px = int(ys_v.size)
                if n_px == 0:
                    raise RuntimeError(
                        "Extracted vessel is empty. Adjust vessel-"
                        "extraction params (int pct / frangi thr / "
                        "sigmas / morphology) then re-run.")
                try:
                    from scipy.spatial import cKDTree as _KDT
                except Exception:
                    _KDT = None
                px_query = np.stack([xs_v, ys_v], axis=1).astype(np.float32)
                best_dist = np.full(n_px, np.inf, dtype=np.float32)
                owning = np.full(n_px, -1, dtype=np.int32)
                nearest_s = np.zeros(n_px, dtype=np.float32)
                for L_idx, L in enumerate(line_infos):
                    cn = np.asarray(L['centers'], dtype=np.float32)[:, :2]
                    al = np.asarray(L['arclen_um'], dtype=np.float32)
                    # ── DENSIFY the centerline before the nearest-node
                    # lookup so `nearest_s` is near-continuous. The raw
                    # ~64-node polyline quantizes many adjacent pixels
                    # to the same node -> visible color bands. Resample
                    # by arclength to ~1200 nodes so the per-pixel v(s)
                    # gradient reads as smooth.
                    if cn.shape[0] >= 2 and al.size == cn.shape[0]:
                        _total_um = float(al[-1] - al[0])
                        n_dense_al = int(np.clip(_total_um / 0.25, 1200, 20000))   # <= 0.25 µm per node
                        al_d = np.linspace(float(al[0]),
                                            float(al[-1]),
                                            n_dense_al).astype(np.float32)
                        cx_d = np.interp(al_d, al,
                                          cn[:, 0]).astype(np.float32)
                        cy_d = np.interp(al_d, al,
                                          cn[:, 1]).astype(np.float32)
                        cn_lookup = np.stack([cx_d, cy_d], axis=1)
                        al_lookup = al_d
                    else:
                        cn_lookup, al_lookup = cn, al
                    if _KDT is not None:
                        tree = _KDT(cn_lookup)
                        d, idx = tree.query(px_query)
                    else:
                        # numpy fallback: O(N*Npx) — fine at typical sizes
                        diff = px_query[:, None, :] - cn_lookup[None, :, :]
                        d2 = (diff * diff).sum(-1)
                        idx = np.argmin(d2, axis=1)
                        d = np.sqrt(d2[np.arange(n_px), idx])
                    better = d < best_dist
                    if better.any():
                        best_dist[better] = d[better].astype(np.float32)
                        owning[better] = L_idx
                        nearest_s[better] = al_lookup[idx[better]]
                # ── v(s) per line via the SHARED core (single source of truth).
                # Stashes L['_vcurve'] / L['_conf_grid'] / L['_fb_const'] for the
                # per-pixel fill below; None == too-few-points ('const' case).
                for L in line_infos:
                    _vel_curves_for_line(L)
                # Reliability gate: colour a line's pixels ONLY if its
                # track meets R² and inlier thresholds. Unreliable lines
                # leave their pixels NaN → rendered as neutral structure.
                r2_thr  = float(vel_min_r2_var.get())
                n_in_thr = int(vel_min_inliers_var.get())
                reliable = []
                for L in line_infos:
                    _r2 = float(L.get('r2', 0.0))
                    _ni = int(L.get('n_inliers', L.get('K', 0)) or 0)
                    ok = (np.isfinite(_r2) and _r2 >= r2_thr
                            and _ni >= n_in_thr)
                    reliable.append(bool(ok))
                    if not ok:
                        self._log(f"[velmap] L{L['line_idx']+1} "
                                  f"unreliable (R²={_r2:.3f}, "
                                  f"n_in={_ni}) → not coloured")
                v_pixel = np.full(n_px, np.nan, dtype=np.float32)
                # DISPLAY-ONLY per-pixel velocity used SOLELY for coloring;
                # `v_pixel` (raw-fit) still drives the normalization range.
                v_pixel_display = np.full(n_px, np.nan, dtype=np.float32)
                # reset extrapolation stashes so a too-few-points flow line
                # cannot reuse a previous render's confidence/measured masks.
                st['_velmap_extrap_conf'] = None
                st['_velmap_measured_px'] = None
                measured_full = np.zeros(n_px, bool)   # per-pixel "is measured" for the norm step
                # ── FLOW-LINE-ONLY gating (STRICT). Only pixels owned
                # by the picked flow line get colored; every other line
                # stays uncolored. If `flow_path_idx` is unset, pick the
                # LONGEST line deterministically so the gate is always
                # active — no silent multi-line fallback that rainbow-
                # paints every branch.
                _flow_L = st.get('flow_path_idx')
                if _flow_L is None:
                    def _plen_v(_L):
                        _cn = np.asarray(_L.get('centers'),
                                          dtype=np.float32)
                        if _cn is None or _cn.shape[0] < 2: return 0.0
                        _d = np.diff(_cn, axis=0)
                        return float(np.sum(np.hypot(_d[:, 0], _d[:, 1])))
                    _lens = [_plen_v(_L) for _L in line_infos]
                    _flow_L = int(np.argmax(_lens)) if _lens else 0
                    st['flow_path_idx'] = _flow_L
                    self._log(f"[velmap] flow_path_idx unset -> "
                              f"defaulted to longest line idx={_flow_L}")
                for L_idx in range(len(line_infos)):
                    if not reliable[L_idx]: continue
                    if int(_flow_L) != int(L_idx):
                        continue
                    m = owning == L_idx
                    if not m.any(): continue
                    L = line_infos[L_idx]
                    if L.get('_vcurve') is None:            # too-few-points ('const' case)
                        fbc = float(L.get('_fb_const', float(vel_floor_var.get())))
                        v_pixel[m] = fbc; v_pixel_display[m] = fbc
                    else:
                        # SHARED per-pixel fill (extension + extrap confidence).
                        _vr, _vd, _ecp, _mpx = _vel_pixels_from_s(L, nearest_s[m])
                        v_pixel[m] = _vr; v_pixel_display[m] = _vd
                        measured_full[m] = _mpx
                        st['_velmap_extrap_conf'] = (m.copy(), _ecp)
                        st['_velmap_measured_px'] = (m.copy(), _mpx)
                self._log(f"[velmap] velocity gated to flow-line "
                          f"idx={int(_flow_L)}; all other lines "
                          f"uncolored (black in raw map)")
                # ── AESTHETIC: normalize to the ACTUAL range of colored
                # speeds so a narrow band spreads across the FULL
                # colormap and a gradient is visible. When the user hasn't
                # forced `vel_max_var`, use 2nd/98th percentile as robust
                # bounds; fall back to nanmin/nanmax if percentiles
                # collapse. Only clamps to [0, ∞) if the user override is
                # set, preserving prior behavior when explicit.
                # ── Color NORMALIZATION via the SHARED core (range from RAW
                # velocity, measured-pixel-only percentiles). Sets
                # st['_velmap_norm_meta']; mirror it into the local var the
                # export block below already reads.
                v_lo, v_hi, norm_label, norm_mode = _vel_color_norm(
                    v_pixel, measured_full, line_infos)
                _velmap_norm_meta = st['_velmap_norm_meta']
                self._log(f"[velocity] color range = [{v_lo:.2f}, {v_hi:.2f}] "
                          f"µm/s  |  norm='{norm_mode}': {norm_label}  "
                          f"(range from RAW velocity; display smoothing does "
                          f"NOT affect it)")
                norm = _Norm(vmin=v_lo, vmax=v_hi)
                cmap = _cm.get_cmap(cmap_name)
                # ── Publication compositing: the REAL recon frame is the
                # base layer (its own opacity, dim context), the velocity
                # tube is a soft-edged colored layer on top. Velocity
                # values are unchanged — only rendering differs.
                try:
                    _rvb = _recon_viewer_base()
                    if _rvb.shape[:2] == mask_2d.shape:
                        frame_layer = _rvb.astype(np.float32)
                    else:
                        frame_layer = np.zeros((*mask_2d.shape, 3),
                                                dtype=np.float32)
                    self._log("[velmap] background = real recon frame "
                              "(velocity tube composited on top)")
                except Exception as _e_vov:
                    self._log(f"[velmap] recon base skipped: {_e_vov}")
                    frame_layer = np.zeros((*mask_2d.shape, 3),
                                            dtype=np.float32)
                # Part E (display-only): dim the grayscale background with a
                # P1/P99.5 stretch so the colored velocity tube pops. Non-
                # flow branches stay neutral gray (never rainbow-colored).
                try:
                    _bgd = float(np.clip(vel_bg_dim_var.get(), 0.0, 1.0))
                    _lum = frame_layer.mean(axis=-1)
                    _lo1, _hi1 = np.percentile(_lum, (1.0, 99.5))
                    _stq = np.clip((_lum - _lo1) / max(_hi1 - _lo1, 1e-6), 0, 1)
                    frame_layer = (np.stack([_stq, _stq, _stq], axis=-1)
                                   * _bgd).astype(np.float32)
                except Exception:
                    frame_layer = (frame_layer * float(
                        np.clip(vel_bg_dim_var.get(), 0, 1))).astype(np.float32)
                # DISPLAY-ONLY: color from the arclength-smoothed velocity
                # (`v_pixel_display`); the normalization range above came
                # from RAW `v_pixel`, so the colorbar stays honest.
                v_rgba = cmap(norm(np.clip(v_pixel_display, v_lo, v_hi)))
                conf_px_full = None    # kept for confidence-α (Part A)
                # ── B2: fade SATURATION where the regression and raw
                # data disagree (per-pixel `_conf_grid` from the flow
                # line). Low confidence → muted color, high confidence
                # → full saturation. `適當 (적당히)`: nothing is deleted;
                # unreliable stretches just read softer.
                try:
                    _flow_L_conf = None
                    _fpi_c = st.get('flow_path_idx')
                    for L in line_infos:
                        if L.get('_conf_grid') is None: continue
                        _flow_L_conf = L; break
                    if _flow_L_conf is not None:
                        _sg, _cg = _flow_L_conf['_conf_grid']
                        conf_px = np.interp(nearest_s, _sg, _cg,
                                              left=float(_cg[0]),
                                              right=float(_cg[-1]))
                        conf_px = np.clip(conf_px.astype(np.float32),
                                           0.25, 1.0)
                        # Stage 6: fold EXTRAPOLATION confidence into SATURATION so the
                        # extrapolated vessel stays gradient-colored but visibly desaturated.
                        # Value stays = MIP; only saturation carries confidence.
                        if st.get('_velmap_extrap_conf') is not None:
                            _em, _ec = st['_velmap_extrap_conf']
                            _full_ec = np.ones(conf_px.size, np.float32)
                            if _em is not None and _em.size == conf_px.size:
                                _full_ec[_em] = _ec
                            conf_px = conf_px * _full_ec
                        conf_px_full = conf_px      # reuse for confidence-α
                        import matplotlib.colors as _mcol_v
                        _rgb3 = v_rgba[:, :3].astype(np.float32)
                        _hsv = _mcol_v.rgb_to_hsv(_rgb3)
                        _hsv[:, 1] = np.clip(
                            _hsv[:, 1] * conf_px, 0.0, 1.0)
                        _rgb3 = _mcol_v.hsv_to_rgb(_hsv).astype(np.float32)
                        v_rgba = np.concatenate(
                            [_rgb3,
                             v_rgba[:, 3:4].astype(np.float32)],
                            axis=1)
                except Exception as _e_cf:
                    self._log(f"[velmap] confidence fade skipped: "
                              f"{_e_cf}")
                # Colored velocity LAYER at FULL value + a feathered
                # (smoothstep of soft_intensity) per-pixel alpha, so the
                # tube edge is soft instead of a hard stair-stepped cutout.
                # Only finite-v pixels are colored; the rest stay transparent
                # and show the real recon frame beneath.
                vel_layer = np.zeros((*mask_2d.shape, 3), dtype=np.float32)
                vel_a = np.zeros(mask_2d.shape, dtype=np.float32)
                _fin = np.isfinite(v_pixel)
                if _fin.any():
                    _yy = ys_v[_fin]; _xx = xs_v[_fin]
                    _rgba_f = v_rgba[_fin]
                    vel_layer[_yy, _xx, 0] = _rgba_f[:, 0]
                    vel_layer[_yy, _xx, 1] = _rgba_f[:, 1]
                    vel_layer[_yy, _xx, 2] = _rgba_f[:, 2]
                    _si = np.clip(soft_intensity[_yy, _xx].astype(np.float32),
                                   0.0, 1.0)
                    _feather = _si * _si * (3.0 - 2.0 * _si)
                    # Part A: confidence-α — reduce OPACITY (not the measured
                    # value) where the regression/raw residual confidence is
                    # low. Display-only; numbers are never removed.
                    if bool(vel_conf_alpha_var.get()) and conf_px_full is not None:
                        _feather = _feather * conf_px_full[_fin]
                    vel_a[_yy, _xx] = _feather
                # Optional tasteful outer bloom (fluorescence-like halo):
                # a low-weight blurred alpha of the tube, same colors,
                # merged under the crisp tube. Off by default.
                vel_a_eff = vel_a
                if bool(vel_glow_var.get()):
                    try:
                        from scipy.ndimage import gaussian_filter as _gf_g
                        _glow_a = np.clip(_gf_g(vel_a, sigma=2.0) * 0.5,
                                           0.0, 1.0).astype(np.float32)
                        vel_a_eff = np.clip(np.maximum(vel_a, _glow_a),
                                             0.0, 1.0).astype(np.float32)
                    except Exception:
                        vel_a_eff = vel_a
                # Part A: `vel α` caps the maximum tube opacity (display-only).
                vel_a_eff = (vel_a_eff
                             * float(np.clip(vel_alpha_var.get(), 0.0, 1.0))
                             ).astype(np.float32)
                # Composite: frame (× op_frame) -> velocity tube (× op_vel).
                op_frame0 = float(np.clip(op_frame_var.get(), 0.0, 1.0))
                op_vel0   = float(np.clip(op_vel_var.get(),   0.0, 1.0))
                rgb = _alpha_over((frame_layer * op_frame0).astype(np.float32),
                                    vel_layer, vel_a_eff * op_vel0)
                _vm_layers = [{'frame': frame_layer,
                                'vel': vel_layer, 'vel_a': vel_a_eff}]
                # NOTE: previously we painted no_motion pixels with the
                # structure hue — REMOVED per user request. Non-flow /
                # no-motion pixels are now left uncolored (black in the
                # raw map; dim grayscale when overlay_orig is on).
                # Untracked branch tubes: composite drawn INCLUDED lines
                # that aren't the tracked (owning) line as dim uncoloured
                # tubes underneath, so the user sees them but they stay
                # neutral (no track). NO extracted-skeleton composite.
                # (line_infos already contains only the tracked line(s);
                # any drawn but not-tracked lines will still render via
                # `_smooth_centerline_tube_rgb`, which reads
                # `st['_bosf_lines_shifted']` = all included centerlines.)
                with apply_nature_style():
                    fig = Figure(figsize=(7.20, 5.4), dpi=300,
                                  facecolor='white',
                                  constrained_layout=True)
                    ax = fig.add_subplot(111)
                    # Anti-alias: lanczos resampling removes the pixel
                    # staircase on the ~300 px tube at 300 DPI without
                    # changing pixel coordinates (arrows/scale bar stay put).
                    _vm_img = ax.imshow(rgb, interpolation='lanczos')
                    # Task 2b: zoom to vessel bbox in the velocity map.
                    _zoom_axes_to_vessel(ax, mask_2d)
                    # ── Per-element overlay REGISTRY (Stage 4): every artist is
                    # drawn unconditionally and tracked so it can be toggled live.
                    _ov = {'flowline': [], 'arrow': [], 'label': [], 'points': [],
                           'scalebar': [], 'letter': [], 'colorbar': []}
                    _ov['flowline'] += (_draw_centerline_overlay(ax) or [])
                    # Direction arrow per line + line label.
                    n_drawn = 0
                    for L in line_infos:
                        pts = L.get('v_pts')
                        if pts is None or len(pts) < 2: continue
                        dirn = int(L.get('v_dir', 0))
                        if dirn != 0:
                            i0 = 0 if dirn > 0 else -2
                            i1 = 1 if dirn > 0 else -1
                            _ov['arrow'].append(ax.annotate("",
                                          xy=(pts[i1][0], pts[i1][1]),
                                          xytext=(pts[i0][0], pts[i0][1]),
                                          arrowprops=dict(arrowstyle='-|>',
                                                            color='white',
                                                            lw=1.5,
                                                            mutation_scale=14,
                                                            alpha=0.95)))
                        x0p, y0p = pts[0]
                        _col_l = L.get('color_hex', '#ffffff')
                        _ov['label'].append(ax.text(x0p + 3, y0p - 3,
                                 f"L{L['line_idx']+1}",
                                 color=_col_l, fontsize=6, weight='bold',
                                 bbox=dict(boxstyle='round,pad=0.1',
                                             fc='white', ec=_col_l,
                                             lw=0.6, alpha=0.7)))
                        n_drawn += 1
                    # RAW measured peak positions — drawn ALWAYS and registered;
                    # visibility is gated live by vel_show_raw_ticks_var.
                    for L in line_infos:
                        rp = L.get('v_pts')
                        if rp is None or len(rp) < 1: continue
                        rp = np.asarray(rp, float)
                        _ov['points'].append(ax.scatter(rp[:, 0], rp[:, 1], s=3.0, c='white',
                                       edgecolors='k', linewidths=0.2,
                                       alpha=0.9, zorder=6))
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                    _bar_um = _nice_bar_length_um(ax, pxu)
                    _ov['scalebar'] += (_scale_bar_µm(ax, _bar_um, pxu) or [])
                    self._log(f"[velmap] px_um={pxu:.1f} µm/px, scale bar = {_bar_um:g} µm")
                    panel_letter(ax, 'a'); _ov['letter'].append(ax.texts[-1])
                    # ── B3: cleaner Nature-style thin colorbar with
                    # 5 evenly-spaced ticks, µm/s label, small font.
                    sm = _cm.ScalarMappable(cmap=cmap, norm=norm)
                    sm.set_array([])
                    cb = fig.colorbar(sm, ax=ax, shrink=0.55, pad=0.015,
                                         fraction=0.028)
                    _ov['colorbar'].append(cb.ax)
                    _ticks = np.linspace(float(norm.vmin), float(norm.vmax), 6)
                    try:
                        cb.set_ticks(_ticks)
                        cb.set_ticklabels(
                            [f"{t:.0f}" for t in _ticks])
                        cb.ax.minorticks_on()
                    except Exception: pass
                    cb.set_label(f"velocity (µm/s)   [{norm.vmin:.0f}–{norm.vmax:.0f}]",
                                  fontsize=6)
                    cb.ax.tick_params(labelsize=5, length=2, width=0.4)
                    cb.outline.set_linewidth(0.5)
                    per_line = "  ".join(
                        f"L{L['line_idx']+1}: robust "
                        f"v={L['m_s']:+.2f} µm/s  R²={L['r2']:.3f}"
                        for L in line_infos)
                    fig.suptitle(
                        f"Velocity map over virtual structure  |  "
                        f"cmap={cmap_name}  norm={norm_mode}  "
                        f"range=[{v_lo:.1f},{v_hi:.1f}] µm/s  |  "
                        f"{per_line}  |  tracks drawn: {n_drawn}",
                        fontsize=6.5, y=0.995)
                    _sm_um = float(vel_display_smooth_um_var.get())
                    _fl = (line_infos[int(_flow_L)]
                           if 0 <= int(_flow_L) < len(line_infos) else line_infos[0])
                    _prov_note = (
                        f"Speed = local d(arclength)/dt consistent with the fitted propagation "
                        f"velocity (v = {_fl['m_s']:.0f} µm/s, R²={_fl['r2']:.2f}); display clamped "
                        f"to [0.25-4]×fit for rendering only. "
                        "Background: real recon frame (data). "
                        f"Norm: {norm_label}."
                        + (f" Rendered gradient: display-only Gaussian "
                           f"smoothing along arclength, σ={_sm_um:.0f} µm "
                           f"(measured velocities unchanged)."
                           if _sm_um > 0 else ""))
                    fig.text(0.5, 0.005, _prov_note,
                              ha='center', va='bottom', fontsize=5,
                              color='0.35', style='italic')
                    # Opacity preview/save: tune frame vs velocity opacity
                    # live; the SAVED file equals the previewed composite.
                    def _write_velmap_source_data(stem):
                        """Source Data for the velocity-map panel:
                        (1) v(s) colour curve, (2) tracked peaks, (3) fit summary, (4) provenance."""
                        import csv as _csv, json as _json
                        _nm = _velmap_norm_meta
                        _sm_um = float(vel_display_smooth_um_var.get())
                        # (1) velocity vs arclength — exactly what the colour encodes
                        with open(stem + "_SourceData_velocity_vs_arclength.csv", "w", newline="") as f:
                            wc = _csv.writer(f)
                            wc.writerow(['line', 's_um', 'v_raw_um_s', 'v_display_um_s'])
                            for L in line_infos:
                                dd = L.get('_vdisplay_dense')
                                if dd is None: continue
                                _sd, _vi, _vd, _dm = dd
                                for j in range(len(_sd)):
                                    wc.writerow([L['line_idx'] + 1, f"{float(_sd[j]):.3f}",
                                                 f"{float(_vi[j]):.4f}", f"{float(_vd[j]):.4f}"])
                        # (2) tracked peaks — the primary measurement
                        with open(stem + "_SourceData_tracked_peaks.csv", "w", newline="") as f:
                            wc = _csv.writer(f)
                            wc.writerow(['line', 'frame_orig', 'time_s', 's_star_um',
                                         'v_raw_um_s', 'v_local_um_s', 'inlier'])
                            for L in line_infos:
                                pres = L.get('present', []); t_ = L.get('t_s', [])
                                s_ = L.get('s_star_um', []); vr = L.get('v_raw', []); vp = L.get('v_pos', [])
                                inl = np.asarray(L.get('inlier_mask', np.ones(len(pres), bool)), bool)
                                for k, fi in enumerate(pres):
                                    wc.writerow([L['line_idx'] + 1, int(fi), f"{float(t_[k]):.5f}",
                                                 f"{float(s_[k]):.3f}",
                                                 (f"{float(vr[k]):.4f}" if k < len(vr) else ''),
                                                 (f"{float(vp[k]):.4f}" if k < len(vp) else ''),
                                                 (int(inl[k]) if k < len(inl) else 1)])
                        # (3) fit summary + display settings (reported numbers live here)
                        with open(stem + "_SourceData_fit_summary.csv", "w", newline="") as f:
                            wc = _csv.writer(f)
                            wc.writerow(['line', 'robust_slope_um_s', 'R2_inliers', 'n_inliers', 'n_total',
                                         'residual_std_um', 'direction_sign', 'cmap', 'norm_mode',
                                         'vmin_um_s', 'vmax_um_s', 'display_smooth_um', 'fps', 'px_um'])
                            for L in line_infos:
                                wc.writerow([L['line_idx'] + 1, f"{float(L['m_s']):.4f}",
                                             f"{float(L['r2']):.4f}", int(L.get('n_inliers', 0)),
                                             int(L.get('K', len(L.get('present', [])))),
                                             f"{float(L.get('resid_std', 0.0)):.3f}", int(L.get('v_dir', 0)),
                                             cmap_name, _nm['norm_mode'], f"{float(_nm['vmin']):.3f}",
                                             f"{float(_nm['vmax']):.3f}", f"{_sm_um:.1f}",
                                             f"{float(fps):.4f}", f"{float(pxu):.4f}"])
                        # (4) provenance JSON — same content as before
                        _prov = dict(
                            note="display smoothing only; quantitative metrics unchanged",
                            display_smooth_um=_sm_um,
                            dense_step_um=float(vel_dense_step_um_var.get()),
                            tube_radius_px=float(vel_tube_radius_px_var.get()),
                            tube_soft_px=float(vel_tube_soft_px_var.get()),
                            alpha=float(vel_alpha_var.get()),
                            confidence_alpha=bool(vel_conf_alpha_var.get()),
                            norm_mode=_nm['norm_mode'], vmin=_nm['vmin'], vmax=_nm['vmax'],
                            norm_label=_nm['label'], cmap=cmap_name, fps=float(fps), px_um=float(pxu),
                            lines={})
                        for L in line_infos:
                            pres = L.get('present', [])
                            inl = np.asarray(L.get('inlier_mask', np.ones(len(pres), bool)), bool).tolist()
                            dd = L.get('_vdisplay_dense')
                            _prov['lines'][int(L['line_idx']) + 1] = dict(
                                raw=dict(s_raw_um=[float(x) for x in L.get('s_star_um', [])],
                                         v_raw_um_s=[float(x) for x in L.get('v_raw', [])],
                                         time_s=[float(x) for x in L.get('t_s', [])],
                                         frame=[int(x) for x in pres], inlier=inl),
                                display=(dict(s_dense_um=[float(x) for x in dd[0]],
                                              v_interp_um_s=[float(x) for x in dd[1]],
                                              v_display_um_s=[float(x) for x in dd[2]])
                                         if dd is not None else None))
                        with open(stem + "_velmap_provenance.json", "w") as f:
                            _json.dump(_prov, f, indent=2, default=str)
                        self._log(f"[velocity_map] Source Data written: {stem}_SourceData_*.csv "
                                  f"+ _velmap_provenance.json")
                    _vm_spec = [('frame', 'frame opacity', 1.0, op_frame_var),
                                ('vel', 'velocity opacity', 1.0, op_vel_var)]
                    _open_opacity_preview(fig, [_vm_img], _vm_layers,
                                            _vm_spec, "velocity_map_Fig2a-R",
                                            win=w, on_saved=_write_velmap_source_data)
                    # ── Live per-element overlay toggles. Because they mutate the
                    # SAME Figure, a Save afterwards serializes exactly what's shown.
                    _ov_vars = {'flowline': vm_ov_flowline_var, 'arrow': vm_ov_arrow_var,
                                'label': vm_ov_label_var, 'points': vel_show_raw_ticks_var,
                                'scalebar': vm_ov_scalebar_var, 'letter': vm_ov_letter_var,
                                'colorbar': vm_ov_colorbar_var}
                    def _apply_overlays():
                        for _k, _var in _ov_vars.items():
                            _vis = bool(_var.get())
                            for _a in _ov[_k]:
                                try: _a.set_visible(_vis)
                                except Exception: pass
                        try: fig.canvas.draw_idle()
                        except Exception: pass
                        self._log("[velmap] overlays: " + " ".join(
                            f"{_k}={int(_v.get())}" for _k, _v in _ov_vars.items()))
                    _ovbar = ttk.Frame(w); _ovbar.pack(side=tk.BOTTOM, fill=tk.X, padx=2)
                    ttk.Label(_ovbar, text="overlays:").pack(side=tk.LEFT)
                    for _k, _v in _ov_vars.items():
                        ttk.Checkbutton(_ovbar, text=_k, variable=_v,
                                        command=_apply_overlays).pack(side=tk.LEFT, padx=1)
                    _apply_overlays()
                    def _save_svg_tif():
                        import datetime as _dt
                        ts = _dt.datetime.now().strftime("%Y%m%d-%H%M%S")
                        p = filedialog.asksaveasfilename(
                            parent=w, title="Save velocity map (SVG + TIF + Source Data)",
                            initialfile=f"velocity_map_{ts}",
                            defaultextension=".svg",
                            filetypes=[("SVG", "*.svg")])
                        if not p: return
                        stem = os.path.splitext(p)[0]
                        try:
                            fig.savefig(stem + ".svg", format='svg', bbox_inches='tight')
                            fig.savefig(stem + ".tif", format='tiff', dpi=300, bbox_inches='tight',
                                         pil_kwargs={'compression': 'tiff_lzw'})
                            _write_velmap_source_data(stem)
                            self._log(f"[velocity_map] wrote {stem}.svg + .tif + Source Data")
                        except Exception as e:
                            messagebox.showwarning("Export failed", f"Could not save: {e}")
                    ttk.Button(w, text="Save velocity map (SVG/TIF + Source Data)",
                                command=_save_svg_tif).pack(side=tk.BOTTOM, padx=2, pady=2)
                    self._log(f"[velocity_map] rendered vmax={v_hi:.1f} µm/s "
                              f"cmap={cmap_name} tracks={n_drawn}")
            except Exception as _e:
                self._log(f"[velocity_map] FAILED:\n{_tb.format_exc()}")
                ttk.Label(w,
                    text=f"velocity_map failed: {type(_e).__name__}: {_e}",
                    foreground='#a00').pack(fill=tk.BOTH, expand=True,
                                                padx=8, pady=8)
                messagebox.showerror("Velocity map",
                    f"{type(_e).__name__}: {_e}\nSee log for full traceback.")

        def _fig_bolus_on_structure():
            from matplotlib.figure import Figure
            from scipy.ndimage import binary_dilation
            # ── Enumerate selected lines (from `st['include_lines']`) ──
            # Backward compatible: if only line 1 is set + selected, this
            # collapses to the original single-line behavior byte-for-byte.
            incl = st.get('include_lines', [True, False, False])
            line_pool = [(i, st['centerlines'][i]) for i in range(MAX_LINES)
                          if (i < len(incl)) and incl[i]
                          and st['centerlines'][i] is not None
                          and len(st['centerlines'][i]) >= 2]
            if not line_pool:
                cl_active = st.get('centerline')
                if cl_active is None or len(cl_active) < 2:
                    messagebox.showwarning("Bolus on structure",
                        "Draw a centerline first (line 1 minimum)."); return
                line_pool = [(int(st.get('active_line', 0)), cl_active)]
            line_infos = []
            for line_idx, cl_arr in line_pool:
                pk_L = _compute_pulse_arclength(cl_override=cl_arr)
                if pk_L is None: continue
                if not pk_L['have_cl'] or len(pk_L['present']) < 2:
                    self._log(f"[bosf] skip line {line_idx + 1}: "
                              f"no arclength/peaks available"); continue
                s_star_L = pk_L['s_star_um']
                present_L = pk_L['present']
                fps_L = pk_L['fps']; pxu_L = pk_L['pxu']
                t_s_L = np.array([f / max(fps_L, 1e-9)
                                    for f in present_L], dtype=float)
                # Robust regression drives s_fit(t) so outliers don't drag
                # the synthetic bolus off its path.
                rf_L = _robust_peak_fit(pk_L)
                m_L, b_L = rf_L['slope'], rf_L['intercept']
                r2_L    = rf_L['r2_inliers']
                self._log(f"[bosf] L{line_idx+1} robust fit "
                          f"({rf_L['estimator']}): slope={m_L:+.2f} µm/s  "
                          f"R²(inliers)={r2_L:.3f}  "
                          f"n_in/n_tot={rf_L['n_inliers']}/{rf_L['n_total']}  "
                          f"low_conf={rf_L['low_confidence']}")
                col_hex = LINE_COLORS[line_idx]
                accent_rgb_L = np.array([
                    int(col_hex[1:3], 16) / 255.0,
                    int(col_hex[3:5], 16) / 255.0,
                    int(col_hex[5:7], 16) / 255.0], dtype=np.float32)
                # B1/B2: expose the robust-fit inlier mask + residual
                # std so `_render_velocity_map` can regress a smooth
                # s(t) on inliers only and compute per-point confidence.
                _inl_mask = np.asarray(
                    rf_L.get('inlier_all',
                              np.ones(len(present_L), dtype=bool)),
                    dtype=bool)
                line_infos.append(dict(
                    line_idx=line_idx, cl_arr=cl_arr,
                    centers=pk_L['centers'], tangents=pk_L['tangents'],
                    arclen_um=pk_L['arclen_um'], s_star_um=s_star_L,
                    present=present_L, t_s=t_s_L,
                    m_s=m_L, b_s=b_L, r2=r2_L,
                    n_inliers=int(rf_L.get('n_inliers',
                                              rf_L.get('K', 0)) or 0),
                    K=int(len(present_L)),
                    Dmap=pk_L['Dmap'], _sat_mask=pk_L['_sat_mask'],
                    color_hex=col_hex, accent_rgb=accent_rgb_L,
                    inlier_mask=_inl_mask,
                    resid_std=float(rf_L.get('residual_std', 0.0) or 0.0),
                ))
            if not line_infos:
                messagebox.showwarning("Bolus on structure",
                    "No usable lines / tracked peaks."); return
            # Line 0 (first selected) sets the shared timing + Dmap
            L0 = line_infos[0]
            fps = float(fps_var.get()); pxu = float(px_var.get())
            K = len(L0['present'])
            t_s = L0['t_s']; s_star_um = L0['s_star_um']
            m_s, b_s, r2 = L0['m_s'], L0['b_s'], L0['r2']
            # Aggregated time span across ALL selected lines
            t_min = min(L['t_s'][0]  for L in line_infos)
            t_max = max(L['t_s'][-1] for L in line_infos)
            mask, agg01 = _compute_structure_mask()
            H, W = agg01.shape
            floor = float(np.clip(bolus_bgfloor_var.get(), 0.0, 1.0))
            # DISPLAY-only structure enhancement (bilateral / CLAHE / unsharp /
            # gamma) applied to the aggregate before masking so the dim
            # structure layer looks cleaner without touching measurements.
            agg01_disp = _smoothed_structure(agg01)
            # "Overlay on original" now means "composite onto the
            # HIGHLIGHT-mode vessel structure" (masked + dimmed vessel),
            # NOT the raw tissue MIP. Keep `struct` = masked vessel in
            # BOTH branches so the highlight/structure modes always
            # render the vessel-only dim canvas the user asked for. The
            # actual overlay composite happens in `_render_mip_bolus`
            # and `_render_velocity_map` via `_highlight_struct_base`.
            overlay_orig = bool(overlay_orig_var.get())
            struct = _apply_mask_action(agg01_disp, mask)
            # DISABLED — Fig.2 / align/velocity/mip_bolus paths all live in
            # ONE full-frame coordinate system so background, centerlines,
            # manual line, and bolus can never drift by a crop offset. Set
            # autocrop off unconditionally here (the user's autocrop toggle
            # still affects other panels, but not this render path).
            do_crop = False
            x0_c = y0_c = 0
            if do_crop:
                ys, xs = np.where(mask)
                pad_frac = float(np.clip(autocrop_pad_var.get(), 0.0, 1.0))
                y0m, y1m = int(ys.min()), int(ys.max())
                x0m, x1m = int(xs.min()), int(xs.max())
                pad_y = int(round((y1m - y0m + 1) * pad_frac))
                pad_x = int(round((x1m - x0m + 1) * pad_frac))
                y0_c = max(0, y0m - pad_y); y1_c = min(H, y1m + pad_y + 1)
                x0_c = max(0, x0m - pad_x); x1_c = min(W, x1m + pad_x + 1)
                struct = struct[y0_c:y1_c, x0_c:x1_c]
                mask   = mask[y0_c:y1_c, x0_c:x1_c]
                agg01_disp = agg01_disp[y0_c:y1_c, x0_c:x1_c]
                H, W = mask.shape
            # ── Ensure the extracted vessel matches the current render
            # basis (post-autocrop). If nothing is cached, or its shape
            # doesn't match, auto-extract on the fly so every mode uses
            # the extracted vessel as its background, never the tinted-
            # aggregate blob.
            _v_cached = st.get('vessel_extracted')
            _need_extract = (
                _v_cached is None
                or _v_cached.get('vessel_mask') is None
                or _v_cached['vessel_mask'].shape != mask.shape)
            if _need_extract:
                try:
                    _extract_vessel(agg01_disp, mask)
                    self._log("[bosf] auto-extracted vessel to match "
                              f"render basis ({H}x{W}).  Adjust params "
                              "under 'Extract vessel + preview' for fine "
                              "tuning.")
                except Exception as _e_ve:
                    import traceback as _tb_ve
                    self._log(f"[bosf] auto-extract FAILED:\n"
                              f"{_tb_ve.format_exc()}")
                    messagebox.showwarning(
                        "Vessel extraction",
                        "Vessel auto-extraction failed. Click "
                        "'Extract vessel + preview' to tune the params "
                        "manually, or the render will fall back to the "
                        "tinted-aggregate blob.")
            motion_mode = motion_mode_var.get()
            reveal_w_um = max(1.0, float(reveal_win_var.get()))
            struct_dim = float(np.clip(struct_dim_var.get(), 0.0, 1.0))
            tcmap_name = time_cmap_var.get()

            # ────────────────── Fig.2 analog: MIP + bolus ──────────────────
            # Structure MIP in a single hue (default cyan) + synthetic bolus
            # rendered at N representative times in a contrasting hue (red).
            # Multi-line aware. Optional x-z (axial) MIP panel.
            if motion_mode == 'mip_bolus':
                _render_mip_bolus(fig_seed=None,
                                    struct_2d=struct, mask_2d=mask,
                                    agg01_disp=agg01_disp,
                                    line_infos=line_infos,
                                    x0_c=x0_c, y0_c=y0_c,
                                    fps=fps, pxu=pxu,
                                    K=K, r2=r2, m_s=m_s)
                return

            # ────────────────── Fig.2 analog: velocity map ─────────────────
            # Per-line tracked path over a dim structure, color-coded by
            # |v(t)| through a perceptually-uniform colormap + labeled bar.
            if motion_mode == 'velocity_map':
                _render_velocity_map(struct_2d=struct, mask_2d=mask,
                                       agg01_disp=agg01_disp,
                                       line_infos=line_infos,
                                       x0_c=x0_c, y0_c=y0_c,
                                       fps=fps, pxu=pxu)
                return
            heat_cmap_name = heat_cmap_var.get()
            heat_gain = max(0.0, float(heat_gain_var.get()))
            heat_thr  = float(np.clip(heat_thr_var.get(), 0.0, 1.0))
            show_synth = bool(show_synth_var.get())
            # Bolus alpha for overlay compositing
            bolus_alpha = float(np.clip(bolus_alpha_var.get(), 0.0, 1.0))
            use_single_accent = bool(bolus_use_single_var.get())
            single_hex = _OKABE_MAP.get(bolus_col_var.get(), OKABE_ITO[1])
            single_accent_rgb = np.array([
                int(single_hex[1:3], 16) / 255.0,
                int(single_hex[3:5], 16) / 255.0,
                int(single_hex[5:7], 16) / 255.0], dtype=np.float32)
            bolus_use_cmap = bool(bolus_cmap_on_var.get())
            # Panels: N frames evenly across trajectory time span
            N_show = max(2, int(bolus_nframes_var.get()))
            t_show = np.linspace(t_min, t_max, N_show)
            frames_show = [int(round(t * max(fps, 1e-9))) for t in t_show]
            use_fit = bool(bolus_use_fit_var.get())
            radius_um  = max(1e-3, float(bolus_radius_var.get()))
            radius_px  = radius_um / max(pxu, 1e-9)
            softness   = float(np.clip(bolus_softness_var.get(), 0.0, 2.0))
            sigma_px   = max(0.5, radius_px * softness)
            # (yy/xx/clip_mask now built AFTER autocrop so they match the
            # cropped H, W.)
            # Auto-crop: shift per-line centers so downstream position math
            # uses the cropped coordinate frame.
            if do_crop and (x0_c != 0 or y0_c != 0):
                for L in line_infos:
                    L['centers'] = L['centers'].astype(np.float32).copy()
                    L['centers'][:, 0] -= x0_c
                    L['centers'][:, 1] -= y0_c
                    if L.get('cl_arr') is not None:
                        _cl = L['cl_arr'].astype(np.float32).copy()
                        _cl[:, 0] -= x0_c; _cl[:, 1] -= y0_c
                        L['cl_arr'] = _cl
            # Cache crop offset + crop-shifted DRAWN centerlines so the
            # centerline-tube renderer + centerline overlay use the exact
            # same geometry the bolus rides on. Any drift here is the root
            # cause of "bolus lands on wrong branch".
            st['_bosf_crop'] = (int(x0_c), int(y0_c))
            _shifted = []
            for L in line_infos:
                if L.get('cl_arr') is not None and len(L['cl_arr']) >= 2:
                    _shifted.append(np.asarray(L['cl_arr'],
                                                  dtype=np.float32))
            st['_bosf_lines_shifted'] = _shifted
            # CENTERLINE-DRIVEN paths: the longest polyline is the bolus's
            # own smoothed centerline; branches come from extraction. This
            # rewrites line_infos[0]['centers'] to points ON the primary
            # polyline, so the bolus and vessel share literal pixels.
            st['vessel_paths'] = None
            st['_vessel_paths_shape'] = None
            try:
                _new_paths = _build_paths_from_centerline(
                    line_infos, agg01_disp, mask, apply_calib=True)
                st['vessel_paths'] = _new_paths
                st['_vessel_paths_shape'] = mask.shape
                self._log(f"[vessel-paths] centerline-driven build: "
                          f"{len(_new_paths)} path(s)")
            except Exception as _e_ct:
                self._log(f"[bosf] centerline-driven build skipped: {_e_ct}")
            # Cache line-0 tracked arclength info so the interactive align
            # window can compute bolus positions along a user-drawn line.
            try:
                st['_bosf_line0_info'] = dict(
                    s_star_um=np.asarray(line_infos[0]['s_star_um'],
                                             dtype=np.float32).copy(),
                    arclen_um=np.asarray(line_infos[0]['arclen_um'],
                                             dtype=np.float32).copy(),
                    t_s=np.asarray(line_infos[0]['t_s'],
                                       dtype=np.float32).copy(),
                    m_s=float(line_infos[0]['m_s']),
                    b_s=float(line_infos[0]['b_s']),
                )
            except Exception: pass
            # Alignment self-check: log bolus↔polyline distance per line.
            if bool(verify_align_var.get()):
                try:
                    paths_v = st.get('vessel_paths') or []
                    if paths_v:
                        # Collect all path pixels once for a KDTree query.
                        _lm = _rasterize_paths(paths_v, *mask.shape)
                        ys_v, xs_v = np.where(_lm)
                        _pp = np.stack([xs_v, ys_v], axis=1).astype(np.float32)
                        try:
                            from scipy.spatial import cKDTree as _KDT
                            _tr = _KDT(_pp)
                        except Exception:
                            _tr = None
                        for L in line_infos:
                            if L['s_star_um'].size < 2: continue
                            s_mid = float(0.5 * (L['s_star_um'][0]
                                                    + L['s_star_um'][-1]))
                            bx, by = _arclen_to_xy(L, s_mid)
                            q = np.array([[bx, by]], dtype=np.float32)
                            if _tr is not None:
                                d, i = _tr.query(q)
                                d_val = float(d[0]); i_val = int(i[0])
                            else:
                                d2 = ((_pp - q) ** 2).sum(-1)
                                i_val = int(np.argmin(d2))
                                d_val = float(np.sqrt(d2[i_val]))
                            nx, ny = float(_pp[i_val, 0]), float(_pp[i_val, 1])
                            self._log(
                                f"[align L{L['line_idx']+1}] "
                                f"s*={s_mid:.1f}µm  bolus=({bx:.1f},{by:.1f})  "
                                f"nearest_polyline=({nx:.1f},{ny:.1f})  "
                                f"distance={d_val:.2f}px")
                except Exception as _e_va:
                    self._log(f"[align] check failed: {_e_va}")
            # Regenerate yy, xx grids matching cropped H, W
            yy, xx = np.mgrid[0:H, 0:W]
            clip_mask = mask.copy()
            if bool(bolus_clip_var.get()):
                clip_mask = binary_dilation(mask, iterations=1)
            # Resolve per-line s_show and centers_show.  For line 0 the
            # bolus is placed DIRECTLY on the rendered vessel_paths[0] via
            # arclength fraction — SAME polyline the background shows.
            for _L_idx_hl, L in enumerate(line_infos):
                s_show_L = ((L['m_s'] * t_show + L['b_s']) if use_fit
                             else np.interp(t_show,
                                             L['t_s'], L['s_star_um']))
                s_show_L = np.clip(s_show_L,
                                     float(L['arclen_um'][0]),
                                     float(L['arclen_um'][-1]))
                L['s_show'] = s_show_L
                if _L_idx_hl == 0:
                    al_hl = np.asarray(L['arclen_um'], dtype=np.float32)
                    al_span_hl = float(al_hl[-1] - al_hl[0])
                    if al_span_hl > 0:
                        _fr_hl = (s_show_L - al_hl[0]) / al_span_hl
                        L['centers_show'] = [
                            _bolus_xy_on_primary(float(_f))
                            for _f in _fr_hl]
                    else:
                        L['centers_show'] = [_arclen_to_xy(L, s)
                                                for s in s_show_L]
                else:
                    L['centers_show'] = [_arclen_to_xy(L, s)
                                            for s in s_show_L]
            # Line 1's arclength / s_show for backwards-compat label + arrow
            arclen_um = L0['arclen_um']
            centers = L0['centers']; tangents = L0['tangents']
            s_show = L0['s_show']; centers_show = L0['centers_show']
            accent_hex = _OKABE_MAP.get(bolus_col_var.get(), OKABE_ITO[1])
            # Bolus shape dispatcher. Signature: (cx, cy) → (H,W) float in
            # [0,1]. `_L_extra` allows callers (per-line iteration) to pass
            # the local tangent for the ellipse / vessel-capsule variants.
            _bshape = bolus_shape_var.get()
            _minor_ratio = float(np.clip(bolus_minor_var.get(), 0.05, 1.0))
            def _blob_at(cx, cy, tangent=None, arclen_img_L=None, s_here=None):
                shape = _bshape
                if shape == 'disk':
                    r_sq = (xx - cx) ** 2 + (yy - cy) ** 2
                    inside = r_sq <= radius_px ** 2
                    soft = np.exp(-r_sq / (2.0 * sigma_px ** 2))
                    b = np.where(inside, 1.0, soft)
                elif shape == 'gaussian':
                    r_sq = (xx - cx) ** 2 + (yy - cy) ** 2
                    b = np.exp(-r_sq / (2.0 * (radius_px * 0.85) ** 2))
                elif shape == 'ellipse':
                    # ── AESTHETIC: soft Gaussian ellipse (bright compact
                    # core + halo) with major axis along the local flow
                    # tangent, minor = `bolus_minor_var` × major. Adds a
                    # gentle halo controlled by `bolus_glow_var`. Reads
                    # as a sleek fluorescent bolus, not a hard oval.
                    if tangent is None or not np.any(tangent):
                        tangent = np.array([1.0, 0.0], dtype=np.float32)
                    tx, ty = float(tangent[0]), float(tangent[1])
                    tn = np.hypot(tx, ty) + 1e-9
                    tx /= tn; ty /= tn
                    dx = xx - cx; dy = yy - cy
                    u =  dx * tx + dy * ty        # along-axis
                    v = -dx * ty + dy * tx        # across-axis
                    a = radius_px
                    b_ax = max(1.0, a * _minor_ratio)
                    # Bright compact core.
                    q_core = (u / (a * 0.55)) ** 2 + (v / (b_ax * 0.55)) ** 2
                    core = np.exp(-0.5 * q_core)
                    # Wider soft halo.
                    try:
                        _bg = float(np.clip(bolus_glow_var.get(),
                                             0.0, 1.0))
                    except Exception:
                        _bg = 0.55
                    q_halo = (u / (a * 1.6)) ** 2 + (v / (b_ax * 1.6)) ** 2
                    halo = np.exp(-0.5 * q_halo) * _bg
                    b = np.clip(core + halo, 0.0, 1.0)
                elif shape == 'capsule':
                    # Vessel-shaped bobsleigh: arclength window intersected
                    # with the mask, feathered. Requires a per-line arclength
                    # image; fall back to a disk if not provided.
                    if arclen_img_L is None or s_here is None:
                        r_sq = (xx - cx) ** 2 + (yy - cy) ** 2
                        b = np.exp(-r_sq / (2.0 * (radius_px * 0.85) ** 2))
                    else:
                        half_w = 0.5 * max(1.0, float(flow_L_var.get()))
                        feather = max(0.0, float(flow_feather_var.get()))
                        d = np.abs(arclen_img_L - s_here)
                        b = np.zeros_like(arclen_img_L, dtype=np.float32)
                        plateau = d <= half_w
                        b[plateau] = 1.0
                        if feather > 0:
                            trans = (d > half_w) & (d <= (half_w + feather))
                            tt = (d[trans] - half_w) / feather
                            b[trans] = 0.5 * (1.0 + np.cos(np.pi * tt))
                        b = np.where(np.isnan(arclen_img_L), 0.0, b)
                        b = b * mask.astype(np.float32)
                else:
                    r_sq = (xx - cx) ** 2 + (yy - cy) ** 2
                    b = np.exp(-r_sq / (2.0 * sigma_px ** 2))
                if bool(bolus_clip_var.get()):
                    b = b * clip_mask.astype(np.float32)
                return b.astype(np.float32)
            # trail buffer of prior centers (soft dimming)
            trail_n = max(0, int(bolus_trail_var.get()))
            def _pos_at(s_um):
                i = int(np.argmin(np.abs(arclen_um - s_um)))
                return float(centers[i, 0]), float(centers[i, 1])
            # Nature width — double column (183 mm ≈ 7.20 in). Two rows if N>=6.
            cols = min(N_show, 4)
            rows = int(np.ceil(N_show / cols))
            fig_w_in = 7.20
            fig_h_in = 2.05 * rows + 0.55
            # structure_motion + flow_in_structure both get an extra row for
            # a summary panel (time-color-of-max D, or time-color-along-
            # arclength for flow).
            extra_row = 1 if motion_mode in ('structure_motion',
                                                'flow_in_structure') else 0
            if extra_row:
                fig_h_in += 2.30
            with apply_nature_style():
                fig = Figure(figsize=(fig_w_in, fig_h_in),
                              dpi=300, facecolor='white')
                if extra_row:
                    gs = fig.add_gridspec(rows + 1, cols,
                                            hspace=0.06, wspace=0.02,
                                            height_ratios=[1.0] * rows + [1.35])
                else:
                    gs = fig.add_gridspec(rows, cols,
                                            hspace=0.06, wspace=0.02)
                # Build a grayscale-luminance RGB base from `struct` once
                base_rgb = np.stack([struct, struct, struct], axis=-1)
                # Dim base for the "motion highlight" mode
                dim_rgb = base_rgb * struct_dim
                accent_rgb = np.array([
                    int(accent_hex[1:3], 16) / 255.0,
                    int(accent_hex[3:5], 16) / 255.0,
                    int(accent_hex[5:7], 16) / 255.0], dtype=np.float32)
                # Precompute an arclength-map image so 'reveal' can gate by
                # arclength: for each centerline point i, mark px within a
                # small band as arclen_um[i]. Used by BOTH `reveal` and the
                # new `flow_in_structure` mode; the latter needs a per-line
                # map (wider band to cover vessel width) which we compute
                # into each `L['arclen_img']`.
                arclen_img = np.full((H, W), np.nan, dtype=np.float32)
                if motion_mode == 'progressive_reveal':
                    band_px_half = max(1, int(round(radius_px * 1.5)))
                    for i in range(len(centers)):
                        cx_i, cy_i = float(centers[i, 0]), float(centers[i, 1])
                        y0, y1 = int(max(0, cy_i - band_px_half)), int(min(H, cy_i + band_px_half + 1))
                        x0, x1 = int(max(0, cx_i - band_px_half)), int(min(W, cx_i + band_px_half + 1))
                        if y1 <= y0 or x1 <= x0: continue
                        arclen_img[y0:y1, x0:x1] = np.where(
                            np.isnan(arclen_img[y0:y1, x0:x1]),
                            float(arclen_um[i]),
                            arclen_img[y0:y1, x0:x1])
                # flow-in-structure OR capsule-shape bolus: per-line
                # arclength map covering the full mask (vessel width) so the
                # "shape bolus" flows through the actual geometry.
                if motion_mode == 'flow_in_structure' or _bshape == 'capsule':
                    for L in line_infos:
                        arclen_L = np.full((H, W), np.nan, dtype=np.float32)
                        # Wide half-band = enough to cover typical vessel radius
                        band_L_half = max(2, int(round(radius_px * 3.0)))
                        _cn = L['centers']; _al = L['arclen_um']
                        for i in range(len(_cn)):
                            cx_i = float(_cn[i, 0]); cy_i = float(_cn[i, 1])
                            y0, y1 = int(max(0, cy_i - band_L_half)), int(min(H, cy_i + band_L_half + 1))
                            x0, x1 = int(max(0, cx_i - band_L_half)), int(min(W, cx_i + band_L_half + 1))
                            if y1 <= y0 or x1 <= x0: continue
                            # keep the nearest arclength if multiple candidates
                            block = arclen_L[y0:y1, x0:x1]
                            arclen_L[y0:y1, x0:x1] = np.where(
                                np.isnan(block), float(_al[i]), block)
                        L['arclen_img'] = arclen_L
                    flow_L_um = max(1.0, float(flow_L_var.get()))
                    flow_ft_um = max(0.0, float(flow_feather_var.get()))
                # Time-encoded single-frame path (colormap)
                import matplotlib.cm as _cm
                tcmap = _cm.get_cmap(tcmap_name)
                # Handle the "time_encoded" mode as a single global panel and
                # then break — we build ONE axes instead of N.
                if motion_mode == 'time_encoded':
                    ax = fig.add_subplot(gs[0, 0]) if rows * cols > 1 else fig.add_subplot(111)
                    # Very dim base
                    ax.imshow(base_rgb * struct_dim, interpolation='nearest')
                    # Draw the trajectory as colored line segments
                    n_seg = 128
                    t_line = np.linspace(t_s[0], t_s[-1], n_seg)
                    s_line = ((m_s * t_line + b_s) if use_fit
                                else np.interp(t_line, t_s, s_star_um))
                    s_line = np.clip(s_line,
                                       float(arclen_um[0]),
                                       float(arclen_um[-1]))
                    line_pts = [_pos_at(s) for s in s_line]
                    from matplotlib.collections import LineCollection
                    segs = [[line_pts[i], line_pts[i + 1]]
                            for i in range(len(line_pts) - 1)]
                    colors = tcmap(np.linspace(0, 1, len(segs)))
                    lc = LineCollection(segs, colors=colors, linewidths=1.6)
                    ax.add_collection(lc)
                    # Tracked-peak markers
                    peak_pts = [_pos_at(s) for s in s_star_um]
                    tt_norm = (t_s - t_s[0]) / max(t_s[-1] - t_s[0], 1e-9)
                    for (cx_p, cy_p), tn in zip(peak_pts, tt_norm):
                        ax.plot(cx_p, cy_p, 'o', ms=4,
                                 mfc=tcmap(tn), mec='k', mew=0.5)
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                    _scale_bar_µm(ax, _nice_bar_length_um(ax, pxu), pxu)
                    panel_letter(ax, 'a')
                    # Time colorbar
                    from matplotlib.colors import Normalize as _Norm
                    sm = _cm.ScalarMappable(cmap=tcmap,
                                              norm=_Norm(vmin=float(t_s[0]),
                                                          vmax=float(t_s[-1])))
                    sm.set_array([])
                    cb = fig.colorbar(sm, ax=ax, shrink=0.6, pad=0.02)
                    cb.set_label("time (s)", fontsize=6)
                    cb.ax.tick_params(labelsize=5)
                    # Skip the per-panel loop entirely
                    N_show = 1
                # Precompute time-of-max map for structure_motion (used by
                # per-panel heat AND the summary panel).
                Dpresent_sorted = None; heat_cmap_obj = None
                arg_time_s = None; heat_amp = None
                if motion_mode == 'structure_motion':
                    # Stack |D_t| across present frames; per-pixel argmax
                    # gives the time each pixel peaks.
                    _sat_mask_fn = L0['_sat_mask']
                    Dmap = L0['Dmap']; present0 = L0['present']
                    stack = np.zeros((len(present0), H, W), dtype=np.float32)
                    for i, t_ in enumerate(present0):
                        d = _sat_mask_fn(Dmap[t_], t_).astype(np.float32)
                        d = np.abs(np.nan_to_num(d, nan=0.0))
                        # Dmap is full-frame; if autocrop shrank (H, W),
                        # crop d to match before assigning. No-op when crop
                        # is off (y0_c=x0_c=0 and shapes already match).
                        if d.shape[:2] != (H, W):
                            d = d[y0_c:y0_c + H, x0_c:x0_c + W]
                        stack[i] = d
                    mx = float(np.nanmax(stack)) if stack.size else 1.0
                    if mx > 0: stack /= mx
                    Dpresent_sorted = stack                # normalized [0,1]
                    heat_cmap_obj = _cm.get_cmap(heat_cmap_name)
                    # argmax time + amplitude
                    ai = np.argmax(Dpresent_sorted, axis=0)
                    heat_amp = np.max(Dpresent_sorted, axis=0)
                    t_present = np.array([t_/max(fps,1e-9) for t_ in present0])
                    arg_time_s = t_present[ai]
                for k in range(N_show if motion_mode != 'time_encoded' else 0):
                    r_ = k // cols; c_ = k % cols
                    ax = fig.add_subplot(gs[r_, c_])
                    # ── Base image for this frame per motion mode ──
                    if motion_mode == 'trajectory_only':
                        # Data-derived virtual structure as the background
                        # (no more plain black) so the bolus visibly passes
                        # THROUGH the vessel.  Alpha adjustable.
                        _v_bg = _virtual_structure_rgb(
                            agg01_disp, mask,
                            mip_struct_hue_var.get(),
                            alpha=float(np.clip(struct_alpha_var.get(),
                                                  0.0, 1.0)))
                        frame = _v_bg.copy()
                    elif motion_mode == 'motion_highlight':
                        frame = dim_rgb.copy()
                    elif motion_mode == 'structure_motion':
                        # Full structure at low alpha (dim), motion heat overlaid
                        frame = dim_rgb.copy()
                    elif motion_mode == 'flow_in_structure':
                        # Dim structure + per-line "shape bolus" (arclength
                        # window intersected with mask, feathered).
                        frame = dim_rgb.copy()
                        half_w = 0.5 * flow_L_um
                        for L in line_infos:
                            al_L = L.get('arclen_img')
                            if al_L is None: continue
                            s_here = float(L['s_show'][k])
                            d = np.abs(al_L - s_here)
                            # inside plateau (1.0), feather (cosine), outside (0)
                            w = np.zeros_like(al_L, dtype=np.float32)
                            plateau = d <= half_w
                            w[plateau] = 1.0
                            if flow_ft_um > 0:
                                trans = (d > half_w) & (d <= (half_w + flow_ft_um))
                                tt = (d[trans] - half_w) / flow_ft_um
                                w[trans] = 0.5 * (1.0 + np.cos(np.pi * tt))
                            # gate by NaN arclength and mask
                            w = np.where(np.isnan(al_L), 0.0, w)
                            w = w * mask.astype(np.float32)
                            L_accent = L['accent_rgb']
                            for ch in range(3):
                                frame[..., ch] = np.clip(
                                    frame[..., ch] * (1.0 - w)
                                    + w * L_accent[ch], 0.0, 1.0)
                            # Add a bright leading front along the centerline
                            # so the direction is visible: strongest at s_here.
                            fx, fy = int(round(L['centers_show'][k][0])), int(round(L['centers_show'][k][1]))
                            if 0 <= fy < H and 0 <= fx < W:
                                # small bright accent disc for the front
                                r_fr = max(2, int(radius_px * 0.4))
                                y0, y1 = max(0, fy - r_fr), min(H, fy + r_fr + 1)
                                x0, x1 = max(0, fx - r_fr), min(W, fx + r_fr + 1)
                                yy_l, xx_l = np.mgrid[y0:y1, x0:x1]
                                d_l = (xx_l - fx) ** 2 + (yy_l - fy) ** 2
                                a_front = np.exp(-d_l / (2.0 * (r_fr * 0.6) ** 2))
                                for ch in range(3):
                                    frame[y0:y1, x0:x1, ch] = np.clip(
                                        frame[y0:y1, x0:x1, ch] * (1.0 - a_front)
                                        + a_front * min(1.0, L_accent[ch] + 0.35),
                                        0.0, 1.0)
                    elif motion_mode == 'progressive_reveal':
                        # Reveal only pixels whose arclength is within a window
                        # centered on the current s* (± reveal_w_um/2).
                        s_here = float(s_show[k])
                        half = 0.5 * reveal_w_um
                        vis = np.abs(arclen_img - s_here) <= half
                        vis = np.where(np.isnan(arclen_img), False, vis)
                        frame = dim_rgb.copy()
                        for ch in range(3):
                            frame[..., ch] = np.where(
                                vis, base_rgb[..., ch], frame[..., ch])
                    else:
                        frame = base_rgb.copy()
                    # ── structure_motion: heat overlay for THIS panel time ──
                    if motion_mode == 'structure_motion' and Dpresent_sorted is not None:
                        # Nearest present index for t_show[k]
                        idx_t = int(np.argmin(np.abs(t_present - t_show[k])))
                        d_here = Dpresent_sorted[idx_t] * heat_gain
                        # noise floor + mask
                        d_here = np.where(mask, d_here, 0.0)
                        d_here = np.where(d_here >= heat_thr, d_here, 0.0)
                        d_here = np.clip(d_here, 0.0, 1.0)
                        heat_rgba = heat_cmap_obj(d_here)         # H, W, 4
                        alpha = d_here                              # alpha ∝ signal
                        for ch in range(3):
                            frame[..., ch] = np.clip(
                                frame[..., ch] * (1.0 - alpha)
                                + heat_rgba[..., ch] * alpha, 0.0, 1.0)
                    # ── Trajectory path so far (trajectory_only + others show it faintly) ──
                    if motion_mode == 'trajectory_only':
                        for L in line_infos:
                            _m, _b, _t_s = L['m_s'], L['b_s'], L['t_s']
                            _al, _cn = L['arclen_um'], L['centers']
                            n_seg = max(2, int(round(60 * (k + 1) / N_show)))
                            t_line = np.linspace(_t_s[0], t_show[k], n_seg)
                            s_line = ((_m * t_line + _b) if use_fit
                                        else np.interp(t_line, _t_s,
                                                        L['s_star_um']))
                            s_line = np.clip(s_line, float(_al[0]),
                                                float(_al[-1]))
                            for i, s_ in enumerate(s_line):
                                ci = int(np.argmin(np.abs(_al - s_)))
                                cx_p, cy_p = float(_cn[ci, 0]), float(_cn[ci, 1])
                                xi, yi = int(round(cx_p)), int(round(cy_p))
                                if 0 <= yi < H and 0 <= xi < W:
                                    col = tcmap(i / max(len(s_line) - 1, 1))
                                    for ch in range(3):
                                        frame[yi, xi, ch] = col[ch]
                    # ── Per-line trails + current bolus ──
                    # For structure_motion, respect `show_synth_var`: if off,
                    # skip synth bolus so ONLY the real motion heat is shown.
                    # For flow_in_structure, the shape rendering above already
                    # covers position + front; draw a light fading-SHAPE
                    # trail instead of the standard disc trail.
                    draw_synth = (motion_mode != 'structure_motion') or show_synth
                    if motion_mode == 'flow_in_structure':
                        # Fading shape-trail (no disc)
                        half_w2 = 0.5 * flow_L_um
                        for L in line_infos:
                            al_L = L.get('arclen_img')
                            if al_L is None: continue
                            for j in range(1, trail_n + 1):
                                idx = k - j
                                if idx < 0: break
                                s_j = float(L['s_show'][idx])
                                d_j = np.abs(al_L - s_j)
                                w_j = np.zeros_like(al_L, dtype=np.float32)
                                plateau_j = d_j <= half_w2
                                w_j[plateau_j] = 1.0
                                if flow_ft_um > 0:
                                    trans_j = (d_j > half_w2) & (d_j <= (half_w2 + flow_ft_um))
                                    tt_j = (d_j[trans_j] - half_w2) / flow_ft_um
                                    w_j[trans_j] = 0.5 * (1.0 + np.cos(np.pi * tt_j))
                                w_j = np.where(np.isnan(al_L), 0.0, w_j)
                                w_j = w_j * mask.astype(np.float32)
                                alpha_j = 0.30 * (1.0 - j / (trail_n + 1))
                                w_j = w_j * alpha_j
                                L_accent = L['accent_rgb']
                                for ch in range(3):
                                    frame[..., ch] = np.clip(
                                        frame[..., ch] * (1.0 - w_j)
                                        + w_j * L_accent[ch], 0.0, 1.0)
                        # Skip the standard disc drawing below for this mode
                        draw_synth = False
                    if draw_synth:
                        # Optional cmap-based colouring so `heat_cmap_var`
                        # actually drives the highlight bolus look.
                        _bcmap = (_cm.get_cmap(heat_cmap_name)
                                    if bolus_use_cmap else None)
                        for L in line_infos:
                            L_show = L['centers_show']
                            # Accent color: per-line by default; overridden
                            # by the single-accent combobox when requested.
                            L_accent = (single_accent_rgb
                                          if use_single_accent
                                          else L['accent_rgb'])
                            L_al_img = L.get('arclen_img')
                            L_tang = L.get('tangents')
                            L_al = L['arclen_um']
                            # helper: nearest-arclen index → tangent
                            def _tan_at(s_um, _tg=L_tang, _al=L_al):
                                i = int(np.argmin(np.abs(_al - s_um)))
                                return (_tg[i] if _tg is not None and i < len(_tg)
                                          else np.array([1.0, 0.0], np.float32))
                            def _mix(dst, w_kernel, accent):
                                # cmap: shade by kernel intensity so the
                                # bolus body varies through the colormap
                                # (visible even for pure disks).
                                if _bcmap is not None:
                                    col_rgba = _bcmap(np.clip(w_kernel, 0, 1))
                                    src_r = col_rgba[..., 0]
                                    src_g = col_rgba[..., 1]
                                    src_b = col_rgba[..., 2]
                                else:
                                    src_r = accent[0]; src_g = accent[1]
                                    src_b = accent[2]
                                a = w_kernel * bolus_alpha
                                dst[..., 0] = np.clip(
                                    dst[..., 0] * (1.0 - a) + a * src_r,
                                    0.0, 1.0)
                                dst[..., 1] = np.clip(
                                    dst[..., 1] * (1.0 - a) + a * src_g,
                                    0.0, 1.0)
                                dst[..., 2] = np.clip(
                                    dst[..., 2] * (1.0 - a) + a * src_b,
                                    0.0, 1.0)
                                return dst
                            # trail
                            for j in range(1, trail_n + 1):
                                idx = k - j
                                if idx < 0: break
                                cx_j, cy_j = L_show[idx]
                                s_j = float(L['s_show'][idx])
                                alpha_j = 0.55 * (1.0 - j / (trail_n + 1))
                                b_j = _blob_at(cx_j, cy_j,
                                                 tangent=_tan_at(s_j),
                                                 arclen_img_L=L_al_img,
                                                 s_here=s_j) * alpha_j
                                frame = _mix(frame, b_j, L_accent)
                            # current bolus
                            cx, cy = L_show[k]
                            s_now = float(L['s_show'][k])
                            b_now = _blob_at(cx, cy,
                                              tangent=_tan_at(s_now),
                                              arclen_img_L=L_al_img,
                                              s_here=s_now)
                            frame = _mix(frame, b_now, L_accent)
                    ax.imshow(frame, interpolation='nearest')
                    # Task 2b: zoom axes to vessel bbox (display-only).
                    try: _zoom_axes_to_vessel(ax, mask)
                    except Exception: pass
                    _draw_centerline_overlay(ax)
                    ax.set_xticks([]); ax.set_yticks([])
                    for s_ in ax.spines.values(): s_.set_visible(False)
                    _t_disp2 = (float(t_show[k] - t_show[0])
                                if bool(zero_time_var.get())
                                else float(t_show[k]))
                    ax.text(0.02, 0.98,
                             f"t={_t_disp2:.2f} s\n"
                             f"s*={s_show[k]:.1f} µm",
                             transform=ax.transAxes, ha='left', va='top',
                             fontsize=5, color='white',
                             bbox=dict(boxstyle='round,pad=0.15', fc='black',
                                        ec='none', alpha=0.5))
                    if k == 0:
                        panel_letter(ax, 'a')
                    if k == N_show - 1:
                        _scale_bar_µm(ax, _nice_bar_length_um(ax, pxu), pxu)
                    if bool(bolus_arrow_var.get()) and k < N_show - 1:
                        cx1, cy1 = centers_show[k]
                        cx2, cy2 = centers_show[min(k + 1, N_show - 1)]
                        ax.annotate("", xy=(cx2, cy2), xytext=(cx1, cy1),
                                     arrowprops=dict(arrowstyle='->',
                                                      color='white', lw=0.8,
                                                      alpha=0.85))
                # ── structure_motion summary panel: time-color-of-max |D| ──
                if motion_mode == 'structure_motion' and extra_row \
                        and heat_amp is not None and arg_time_s is not None:
                    ax_sum = fig.add_subplot(gs[rows, :])
                    # Base: dim structure so context stays
                    ax_sum.imshow(dim_rgb, interpolation='nearest')
                    # Time-colored overlay where signal > threshold
                    vis = (heat_amp >= heat_thr) & mask
                    from matplotlib.colors import Normalize as _Norm
                    norm = _Norm(vmin=float(t_present.min()),
                                   vmax=float(t_present.max()))
                    time_rgba = tcmap(norm(arg_time_s))
                    rgb_sum = dim_rgb.copy()
                    alpha_sum = np.where(vis,
                                            np.clip(heat_amp * heat_gain, 0.0, 1.0),
                                            0.0)
                    for ch in range(3):
                        rgb_sum[..., ch] = np.clip(
                            rgb_sum[..., ch] * (1.0 - alpha_sum)
                            + time_rgba[..., ch] * alpha_sum, 0.0, 1.0)
                    ax_sum.imshow(rgb_sum, interpolation='nearest')
                    # Overlay each selected line's centerline for context
                    for L in line_infos:
                        cl_ = L['cl_arr'].astype(float)
                        ax_sum.plot(cl_[:, 0], cl_[:, 1],
                                     '-', color=L['color_hex'],
                                     lw=1.0, alpha=0.8,
                                     label=f"line {L['line_idx']+1}")
                    ax_sum.legend(loc='upper right',
                                    frameon=False, fontsize=5)
                    ax_sum.set_xticks([]); ax_sum.set_yticks([])
                    for s_ in ax_sum.spines.values(): s_.set_visible(False)
                    _scale_bar_µm(ax_sum, 100.0, pxu)
                    panel_letter(ax_sum, chr(ord('a') + rows))
                    sm2 = _cm.ScalarMappable(cmap=tcmap, norm=norm)
                    sm2.set_array([])
                    cb2 = fig.colorbar(sm2, ax=ax_sum,
                                         shrink=0.6, pad=0.02)
                    cb2.set_label("time of |D| peak (s)  — frame-difference signal",
                                    fontsize=6)
                    cb2.ax.tick_params(labelsize=5)
                # ── flow_in_structure summary: for each in-mask pixel,
                # color by the TIME at which that pixel's arclength (per its
                # closest line) matches s_fit(t). Shows the full passage in
                # one panel. ──
                if motion_mode == 'flow_in_structure' and extra_row:
                    ax_sum = fig.add_subplot(gs[rows, :])
                    ax_sum.imshow(dim_rgb, interpolation='nearest')
                    from matplotlib.colors import Normalize as _Norm
                    norm = _Norm(vmin=float(t_show[0]),
                                   vmax=float(t_show[-1]))
                    rgb_sum = dim_rgb.copy()
                    alpha_accum = np.zeros((H, W), dtype=np.float32)
                    for L in line_infos:
                        al_L = L.get('arclen_img')
                        if al_L is None: continue
                        # Invert: pixel arclength -> time (via fit)
                        if use_fit and abs(L['m_s']) > 1e-9:
                            t_map = (al_L - L['b_s']) / L['m_s']
                        else:
                            # raw peaks: piecewise-linear inverse via s_star
                            # sort s_star for monotone interp
                            order = np.argsort(L['s_star_um'])
                            s_sorted = L['s_star_um'][order]
                            t_sorted = L['t_s'][order]
                            t_map = np.interp(al_L, s_sorted, t_sorted,
                                                left=np.nan, right=np.nan)
                        valid = (~np.isnan(al_L)) & (~np.isnan(t_map)) \
                                & mask & (t_map >= t_show[0]) & (t_map <= t_show[-1])
                        col_rgba = tcmap(norm(t_map))
                        w = 0.7 * valid.astype(np.float32)
                        for ch in range(3):
                            rgb_sum[..., ch] = np.clip(
                                rgb_sum[..., ch] * (1.0 - w)
                                + col_rgba[..., ch] * w, 0.0, 1.0)
                        alpha_accum = np.maximum(alpha_accum, w)
                    ax_sum.imshow(rgb_sum, interpolation='nearest')
                    # Overlay centerlines
                    for L in line_infos:
                        cl_ = L['cl_arr'].astype(float)
                        ax_sum.plot(cl_[:, 0], cl_[:, 1],
                                     '-', color=L['color_hex'],
                                     lw=1.0, alpha=0.85,
                                     label=f"line {L['line_idx']+1}")
                    ax_sum.legend(loc='upper right',
                                    frameon=False, fontsize=5)
                    ax_sum.set_xticks([]); ax_sum.set_yticks([])
                    for s_ in ax_sum.spines.values(): s_.set_visible(False)
                    _scale_bar_µm(ax_sum, 100.0, pxu)
                    panel_letter(ax_sum, chr(ord('a') + rows))
                    sm3 = _cm.ScalarMappable(cmap=tcmap, norm=norm)
                    sm3.set_array([])
                    cb3 = fig.colorbar(sm3, ax=ax_sum,
                                         shrink=0.6, pad=0.02)
                    cb3.set_label("time along fitted trajectory (s)  "
                                    "— synthetic bolus position",
                                    fontsize=6)
                    cb3.ax.tick_params(labelsize=5)
                per_line_str = "  ".join(
                    f"L{L['line_idx']+1}: v={L['m_s']:+.2f} µm/s  R²={L['r2']:.3f}"
                    for L in line_infos)
                fig.suptitle(
                    f"Bolus on structure  |  mode={motion_mode}  "
                    f"r={radius_um:.1f} µm  "
                    f"trajectory: {('fit' if use_fit else 'raw')}  "
                    f"lines={len(line_infos)}  "
                    f"{per_line_str}  |  "
                    f"K(L1)={K} tracked peaks",
                    fontsize=6.5, y=0.995)
                fig.text(0.5, 0.008, BOSF_CAPTION,
                          ha='center', va='bottom', fontsize=5,
                          color='0.35', style='italic')
                fig.tight_layout(rect=(0.0, 0.02, 1.0, 0.965))
                w = tk.Toplevel(pw)
                w.title("Bolus on structure (SYNTHETIC — Nature style)")
                # Reserve the extra button bar at BOTTOM FIRST so the SVG /
                # TIF / GIF buttons can never get pushed off-screen by the
                # large canvas above.
                bot = ttk.Frame(w)
                bot.pack(side=tk.BOTTOM, fill=tk.X, padx=3, pady=2)
                _embed_with_save(w, fig, "SYNTHETIC_bolus_on_structure")
                # Illustrator-editable exports: layered SVG + TIFF @ 300 dpi
                # Filename encodes mode + timestamp; metadata records params.
                def _save_editable():
                    import datetime as _dt
                    ts = _dt.datetime.now().strftime("%Y%m%d-%H%M%S")
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save figure (SVG + TIF)",
                        initialfile=f"SYNTHETIC_bolus_on_structure_"
                                     f"{motion_mode}_{ts}",
                        defaultextension=".svg",
                        filetypes=[("SVG", "*.svg")])
                    if not p: return
                    stem = os.path.splitext(p)[0]
                    svg_p = stem + ".svg"; tif_p = stem + ".tif"
                    md = {
                        'Title': 'SYNTHETIC bolus on structure',
                        'Description': BOSF_CAPTION,
                        'motion_mode': motion_mode,
                        'shape': str(_bshape),
                        'radius_um': f"{radius_um:.3f}",
                        'lines': ",".join(
                            str(L['line_idx'] + 1) for L in line_infos),
                    }
                    try:
                        fig.savefig(svg_p, format='svg',
                                     bbox_inches='tight',
                                     metadata=md)
                        fig.savefig(tif_p, format='tiff', dpi=300,
                                     bbox_inches='tight',
                                     pil_kwargs={'compression': 'tiff_lzw'})
                        self._log(f"[bosf] saved editable SVG → {svg_p}")
                        self._log(f"[bosf] saved 300 dpi TIFF → {tif_p}")
                    except Exception as e:
                        messagebox.showwarning("Export failed",
                            f"Could not save: {e}")
                ttk.Button(bot, text="Save figure (SVG/TIF)…",
                            command=_save_editable).pack(side=tk.LEFT, padx=2)
                # GIF export — reuse the fixed Figure/FigureCanvasAgg pattern
                def _export_gif():
                    from matplotlib.animation import FuncAnimation, PillowWriter
                    from matplotlib.backends.backend_agg import FigureCanvasAgg
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Export bolus-on-structure GIF",
                        initialfile="SYNTHETIC_bolus_on_structure",
                        defaultextension=".gif",
                        filetypes=[("GIF", "*.gif")])
                    if not p: return
                    n_anim = max(N_show, 24)                  # smoother anim
                    t_anim = np.linspace(t_s[0], t_s[-1], n_anim)
                    s_anim = ((m_s * t_anim + b_s) if use_fit
                                else np.interp(t_anim, t_s, s_star_um))
                    s_anim = np.clip(s_anim, float(arclen_um[0]),
                                       float(arclen_um[-1]))
                    centers_anim = [_pos_at(s) for s in s_anim]
                    fig2 = Figure(figsize=(4.5, 4.5), dpi=200,
                                    facecolor='white')
                    FigureCanvasAgg(fig2)
                    ax2 = fig2.add_subplot(111)
                    ax2.set_xticks([]); ax2.set_yticks([])
                    for s_ in ax2.spines.values(): s_.set_visible(False)
                    im2 = ax2.imshow(base_rgb.copy(),
                                        interpolation='nearest')
                    tt = ax2.text(0.02, 0.98, "",
                                    transform=ax2.transAxes, ha='left',
                                    va='top', fontsize=6, color='white',
                                    bbox=dict(boxstyle='round,pad=0.15',
                                                fc='black', ec='none',
                                                alpha=0.5))
                    ax2.text(0.5, 0.02, BOSF_CAPTION,
                              transform=ax2.transAxes, ha='center',
                              va='bottom', fontsize=5, color='0.35',
                              style='italic')
                    _scale_bar_µm(ax2, 100.0, pxu)
                    def _upd(k):
                        frame = base_rgb.copy()
                        for j in range(1, trail_n + 1):
                            idx = k - j
                            if idx < 0: break
                            cx_j, cy_j = centers_anim[idx]
                            alpha = 0.55 * (1.0 - j / (trail_n + 1))
                            b_j = _blob_at(cx_j, cy_j) * alpha
                            for ch in range(3):
                                frame[..., ch] = np.clip(
                                    frame[..., ch] * (1.0 - b_j)
                                    + b_j * accent_rgb[ch], 0.0, 1.0)
                        cx, cy = centers_anim[k]
                        b_now = _blob_at(cx, cy)
                        for ch in range(3):
                            frame[..., ch] = np.clip(
                                frame[..., ch] * (1.0 - b_now)
                                + b_now * accent_rgb[ch], 0.0, 1.0)
                        im2.set_data(frame)
                        tt.set_text(f"t={t_anim[k]:.2f} s\n"
                                     f"s*={s_anim[k]:.1f} µm")
                        return im2, tt
                    anim = FuncAnimation(fig2, _upd, frames=n_anim,
                                          interval=150, blit=False)
                    anim.save(p, writer=PillowWriter(fps=10))
                    self._log(f"[bosf] saved SYNTHETIC bolus-on-structure GIF → {p}")
                ttk.Button(bot, text="Export GIF (SYNTHETIC)",
                            command=_export_gif).pack(side=tk.LEFT, padx=2)
                # metadata JSON sidecar
                def _save_meta():
                    import json as _json
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save bolus-on-structure metadata JSON",
                        initialfile="SYNTHETIC_bolus_on_structure_meta",
                        defaultextension=".json",
                        filetypes=[("JSON", "*.json")])
                    if not p: return
                    meta = dict(
                        kind="SYNTHETIC_bolus_on_structure",
                        caption=BOSF_CAPTION,
                        fps=float(fps), pxu_um_per_px=float(pxu),
                        radius_um=float(radius_um),
                        softness=float(softness),
                        bg_floor=float(floor),
                        clip_to_mask=bool(bolus_clip_var.get()),
                        trajectory=('fit' if use_fit else 'raw'),
                        fit=dict(slope_um_per_s=float(m_s),
                                  intercept_um=float(b_s),
                                  R2=float(r2), K=int(K)),
                        panel_times_s=[float(x) for x in t_show],
                        panel_s_um=[float(x) for x in s_show],
                        panel_frames=[int(x) for x in frames_show],
                        mask_params=dict(
                            src=mask_src_var.get(),
                            method=mask_method_var.get(),
                            threshold=float(mask_thr_var.get()),
                            smooth_sigma_px=float(mask_smooth_var.get()),
                            close=int(mask_close_var.get()),
                            open=int(mask_open_var.get()),
                            dilate=int(mask_dilate_var.get()),
                            fill_holes=bool(mask_holes_var.get()),
                            keep_cc_centerline=bool(mask_keepcl_var.get()),
                            max_cc=int(mask_maxcc_var.get()),
                            frames_used=len(_bosf_frame_range()),
                        ),
                        warning=("This dataset is SYNTHETIC. The blob is "
                                  "constant-radius and its motion follows "
                                  "the fitted peak-trajectory line; the "
                                  "structure mask is display-only and never "
                                  "touches quantification."),
                    )
                    with open(p, "w") as f:
                        _json.dump(meta, f, indent=2)
                    self._log(f"[bosf] wrote metadata sidecar → {p}")
                ttk.Button(bot, text="Save metadata JSON",
                            command=_save_meta).pack(side=tk.LEFT, padx=2)
                ttk.Label(bot, text=BOSF_CAPTION,
                            foreground='#555').pack(side=tk.LEFT, padx=6)
                self._log(f"[bosf] rendered N={N_show}  "
                          f"radius={radius_um:.1f}µm  "
                          f"trajectory={'fit' if use_fit else 'raw'}  "
                          f"v={m_s:+.2f}µm/s  R²={r2:.3f}")

        # ── One-click "Nature figure suite" ──────────────────────────────
        # Assembles a multi-panel publication figure from the already
        # extracted data. Panels are pickable via checkboxes; each panel is
        # ALSO saved individually as SVG + TIF for lab-notebook use. Reuses
        # existing figure functions where they exist (montage, kymo,
        # peak-trajectory), and per-line-aware where relevant.
        NATURE_SUITE_CAPTION = (
            "Real-data panels use ORIGINAL b(s) / D(t); synthetic panels "
            "(labeled) reconstruct from the fitted peak trajectory.")

        def _fig_nature_suite():
            import datetime as _dt
            from matplotlib.figure import Figure
            from matplotlib.collections import LineCollection
            import matplotlib.cm as _cm
            # Ask the user which panels to include
            picker = tk.Toplevel(pw); picker.title("Nature figure suite — panels")
            picker.geometry("360x360")
            _incl_a = tk.BooleanVar(value=True)     # context: structure + centerlines
            _incl_b = tk.BooleanVar(value=True)     # b(s,t) kymograph
            _incl_c = tk.BooleanVar(value=True)     # peak trajectory
            _incl_d = tk.BooleanVar(value=True)     # kinematics histograms
            _incl_e = tk.BooleanVar(value=True)     # velocity-vs-arclength
            _incl_f = tk.BooleanVar(value=True)     # differential montage OR flow-in-structure hero
            _incl_g = tk.BooleanVar(value=True)     # summary stats table
            for txt, v in [
                ("(a) Structure + centerlines (context)", _incl_a),
                ("(b) b(s,t) space-time map + robust peak track", _incl_b),
                ("(c) Peak trajectory s*(t) + robust fit", _incl_c),
                ("(d) Per-event kinematics histograms", _incl_d),
                ("(e) Velocity vs arclength (per line)", _incl_e),
                ("(f) Representative differential / flow hero", _incl_f),
                ("(g) Summary stats table", _incl_g),
            ]:
                ttk.Checkbutton(picker, text=txt, variable=v
                                 ).pack(anchor='w', padx=8, pady=2)
            proceed = {'ok': False}
            def _ok(): proceed['ok'] = True; picker.destroy()
            btnf = ttk.Frame(picker); btnf.pack(fill=tk.X, padx=8, pady=8)
            ttk.Button(btnf, text="Generate", command=_ok
                        ).pack(side=tk.RIGHT, padx=2)
            ttk.Button(btnf, text="Cancel",
                        command=picker.destroy).pack(side=tk.RIGHT, padx=2)
            picker.wait_window()
            if not proceed['ok']: return
            incl_flags = dict(a=_incl_a.get(), b=_incl_b.get(),
                                c=_incl_c.get(), d=_incl_d.get(),
                                e=_incl_e.get(), f=_incl_f.get(),
                                g=_incl_g.get())
            # ── Enumerate selected lines and per-line robust fits ──
            incl = st.get('include_lines', [True, False, False])
            line_pool = [(i, st['centerlines'][i]) for i in range(MAX_LINES)
                          if (i < len(incl)) and incl[i]
                          and st['centerlines'][i] is not None
                          and len(st['centerlines'][i]) >= 2]
            if not line_pool:
                cl_active = st.get('centerline')
                if cl_active is None or len(cl_active) < 2:
                    messagebox.showwarning("Nature suite",
                        "Draw a centerline first."); return
                line_pool = [(int(st.get('active_line', 0)), cl_active)]
            line_infos = []
            for line_idx, cl_arr in line_pool:
                pk_L = _compute_pulse_arclength(cl_override=cl_arr)
                if pk_L is None or not pk_L['have_cl']: continue
                if len(pk_L['present']) < 2: continue
                rf_L = _robust_peak_fit(pk_L)
                t_s_L = np.array(
                    [f / max(pk_L['fps'], 1e-9) for f in pk_L['present']],
                    dtype=float)
                line_infos.append(dict(
                    line_idx=line_idx, cl_arr=cl_arr, pk=pk_L, rf=rf_L,
                    t=t_s_L, s=pk_L['s_star_um'],
                    amp=pk_L['amp_at_star'],
                    fwhm=pk_L['fwhm_um'],
                    color=LINE_COLORS[line_idx],
                    b_profiles=pk_L['b_profiles'],
                    arclen_um=pk_L['arclen_um'],
                    present=pk_L['present'],
                    Dmap=pk_L['Dmap'], _sat_mask=pk_L['_sat_mask'],
                    tangents=pk_L['tangents'], centers=pk_L['centers'],
                ))
            if not line_infos:
                messagebox.showwarning("Nature suite",
                    "No usable peaks to build panels from."); return
            fps = float(fps_var.get()); pxu = float(px_var.get())
            # Layout: Nature double column (7.20 in) with variable rows.
            with apply_nature_style():
                # Panel-key list preserves story order a→g regardless of
                # which panels the user selected; grid re-flows so nothing
                # overlaps and letters stay contiguous.
                panel_defs = [k for k in ('a', 'b', 'c', 'd', 'e', 'f', 'g')
                               if incl_flags[k]]
                if not panel_defs:
                    messagebox.showwarning("Nature suite",
                        "No panels selected."); return
                rows = (len(panel_defs) + 1) // 2         # 2 per row
                # constrained_layout=True gives automatic per-axes spacing so
                # colorbars / legends / panel letters / titles never overlap
                # regardless of which subset the user chose.
                fig = Figure(figsize=(7.20, 3.0 * rows),
                              dpi=300, facecolor='white',
                              constrained_layout=True)
                gs = fig.add_gridspec(rows, 2, figure=fig)
                # Panel-letter counter re-maps to whatever the user picked so
                # they stay a, b, c, … in visual order.
                pos = 0
                _letter_map = dict(zip(panel_defs,
                                          'abcdefg'[:len(panel_defs)]))
                def _place():
                    r_, c_ = pos // 2, pos % 2
                    return fig.add_subplot(gs[r_, c_])

                # (a) Structure + centerlines (context)
                if incl_flags['a']:
                    ax = _place()
                    try:
                        mask_ctx, agg_ctx = _compute_structure_mask()
                        agg_ctx_disp = _smoothed_structure(agg_ctx)
                        struct_ctx = _apply_mask_action(agg_ctx_disp,
                                                          mask_ctx)
                        ax.imshow(struct_ctx, cmap='gray', vmin=0, vmax=1,
                                    interpolation='nearest')
                        # centerline overlays per line
                        for L in line_infos:
                            cl_ = L['cl_arr'].astype(float)
                            ax.plot(cl_[:, 0], cl_[:, 1], '-',
                                     color=L['color'], lw=1.2, alpha=0.9,
                                     label=f"L{L['line_idx']+1}")
                        ax.set_xticks([]); ax.set_yticks([])
                        for s_ in ax.spines.values(): s_.set_visible(False)
                        _scale_bar_µm(ax, _nice_bar_length_um(ax, pxu), pxu)
                        ax.legend(loc='upper right', frameon=False,
                                    fontsize=5)
                    except Exception as _e:
                        ax.text(0.5, 0.5, f"(a) skipped: {_e}",
                                  ha='center', va='center',
                                  transform=ax.transAxes, color='#a00')
                    panel_letter(ax, _letter_map['a'], x=-0.02, y=1.05)
                    pos += 1

                # (b) b(s,t) kymograph for line 1 with robust track overlay
                if incl_flags['b']:
                    ax = _place()
                    L = line_infos[0]
                    B = np.stack(L['b_profiles'], axis=1)
                    vmax = float(np.nanpercentile(B, 99)) if B.size else 1.0
                    if vmax <= 0: vmax = 1.0
                    im = ax.imshow(B, aspect='auto', cmap='viridis',
                                     vmin=0, vmax=vmax,
                                     extent=[L['t'][0], L['t'][-1],
                                               L['arclen_um'][-1], 0],
                                     interpolation='nearest')
                    m_L = L['rf']['slope']; b_L = L['rf']['intercept']
                    if np.isfinite(m_L):
                        tt = np.linspace(L['t'][0], L['t'][-1], 100)
                        s_hat = np.clip(m_L * tt + b_L,
                                          float(L['arclen_um'][0]),
                                          float(L['arclen_um'][-1]))
                        ax.plot(tt, s_hat, '-', color='#FFB000', lw=1.2,
                                 label=f"robust {m_L:+.1f} µm/s")
                    # inlier peaks
                    ax.plot(L['t'][L['rf']['inlier_all']],
                             L['s'][L['rf']['inlier_all']],
                             'o', color='w', ms=3, mec='k', mew=0.4)
                    ax.set_xlabel("time (s)"); ax.set_ylabel("arclength s (µm)")
                    ax.legend(loc='upper right', frameon=False, fontsize=5)
                    fig.colorbar(im, ax=ax,
                                    fraction=0.045, pad=0.03).set_label(
                        "b(s,t) (ORIGINAL)", fontsize=6)
                    panel_letter(ax, _letter_map['b'], x=-0.10, y=1.05)
                    pos += 1

                # (c) Peak trajectory + robust fit (all included lines)
                if incl_flags['c']:
                    ax = _place()
                    for L in line_infos:
                        rf = L['rf']; col = L['color']
                        inl = rf['inlier_all']
                        ax.plot(L['t'][inl], L['s'][inl], 'o',
                                 color=col, ms=3.5, mec='k', mew=0.4,
                                 label=f"L{L['line_idx']+1} inlier "
                                       f"({rf['n_inliers']}/{rf['n_total']})")
                        out = rf['pass_mask'] & ~inl
                        if out.any():
                            ax.plot(L['t'][out], L['s'][out], 'o',
                                     mfc='none', mec=col, ms=3.5, mew=0.9)
                        if np.isfinite(rf['slope']):
                            tt = np.linspace(L['t'][0], L['t'][-1], 100)
                            ax.plot(tt, rf['slope']*tt + rf['intercept'],
                                     '--', color=col, lw=0.9,
                                     label=(f"L{L['line_idx']+1} "
                                              f"{rf['slope']:+.2f} µm/s  "
                                              f"R²={rf['r2_inliers']:.3f}"))
                    ax.set_xlabel("time (s)"); ax.set_ylabel("s* (µm)")
                    ax.legend(loc='best', frameon=False, fontsize=5, ncol=1)
                    despine_lr(ax); panel_letter(ax, _letter_map['c'],
                                                    x=-0.10, y=1.05)
                    pos += 1

                # (d) Kinematics histograms: v_i (fit slopes), ISI, distance
                if incl_flags['d']:
                    ax = _place()
                    v_list = []; isi_list = []; dist_list = []
                    for L in line_infos:
                        rf = L['rf']
                        if np.isfinite(rf['slope']):
                            v_list.append(rf['slope'])
                        inl_t = L['t'][rf['inlier_all']]
                        if inl_t.size >= 2:
                            isi_list.extend(np.diff(inl_t).tolist())
                            dist_list.append(float(L['s'].max() - L['s'].min()))
                    if v_list:
                        ax.hist(v_list, bins=max(5, len(v_list)//2 or 5),
                                 color=OKABE_ITO[3], alpha=0.75,
                                 edgecolor='k', linewidth=0.5,
                                 label=f"velocities (n={len(v_list)})")
                    if isi_list:
                        ax2 = ax.twinx()
                        ax2.hist(isi_list, bins=8, color=OKABE_ITO[6],
                                  alpha=0.55, edgecolor='k', linewidth=0.4,
                                  label=f"ISI (n={len(isi_list)})")
                        ax2.set_ylabel("ISI count", color=OKABE_ITO[6],
                                          fontsize=6)
                    ax.set_xlabel("velocity (µm/s)  |  ISI (s)")
                    ax.set_ylabel("velocity count", color=OKABE_ITO[3],
                                       fontsize=6)
                    ax.legend(loc='upper right', frameon=False, fontsize=5)
                    despine_lr(ax); panel_letter(ax, _letter_map['d'],
                                                    x=-0.10, y=1.05)
                    pos += 1

                # (e) Velocity vs arclength (binned mean±SD along the vessel)
                if incl_flags['e']:
                    ax = _place()
                    for L in line_infos:
                        # per-frame ds*/dt (raw); bin by s
                        t_ = L['t']; s_ = L['s']
                        if t_.size < 3: continue
                        ds_dt = np.gradient(s_, t_)
                        # bin along arclength
                        nbins = min(12, max(4, t_.size // 3))
                        s_min, s_max = float(s_.min()), float(s_.max())
                        edges = np.linspace(s_min, s_max, nbins + 1)
                        centers_b = 0.5 * (edges[:-1] + edges[1:])
                        means = np.full(nbins, np.nan)
                        stds  = np.full(nbins, np.nan)
                        for bi in range(nbins):
                            mm = (s_ >= edges[bi]) & (s_ < edges[bi + 1])
                            if mm.any():
                                means[bi] = float(np.nanmean(ds_dt[mm]))
                                stds[bi]  = float(np.nanstd(ds_dt[mm]))
                        col = L['color']
                        ax.errorbar(centers_b, means, yerr=stds, marker='o',
                                     ms=3.5, lw=0.9, color=col, capsize=1.5,
                                     label=f"L{L['line_idx']+1}")
                    ax.axhline(0, color='0.6', lw=0.6, ls=':')
                    ax.set_xlabel("arclength (µm)")
                    ax.set_ylabel("ds*/dt (µm/s)")
                    ax.legend(loc='best', frameon=False, fontsize=5)
                    despine_lr(ax); panel_letter(ax, _letter_map['e'],
                                                    x=-0.10, y=1.05)
                    pos += 1

                # (f) Representative differential montage (line 1) — the
                # "SYNTHETIC hero" alt-panel was folded into a single slot
                # since publishing space is scarce; users get the flow-hero
                # from the standalone bolus-on-structure window.
                if incl_flags['f']:
                    ax = _place()
                    L = line_infos[0]
                    Dmap = L['Dmap']; present = L['present']
                    _sat_fn = L['_sat_mask']
                    n_show = min(6, len(present))
                    idxs = np.linspace(0, len(present) - 1, n_show).astype(int)
                    # Build a horizontal filmstrip of D_t stitched together
                    strips = []
                    for j in idxs:
                        d = _sat_fn(Dmap[present[j]], present[j])
                        d = np.nan_to_num(d, nan=0.0)
                        v = float(np.percentile(np.abs(d), 99)) if d.size else 1.0
                        if v <= 0: v = 1.0
                        strips.append(np.clip((d + v) / (2 * v), 0.0, 1.0))
                    if strips:
                        strip = np.concatenate(strips, axis=1)
                        ax.imshow(strip, cmap='seismic', vmin=0, vmax=1,
                                     interpolation='nearest')
                        # overlay line1 centerline on each strip
                        H_s, w_each = strips[0].shape
                        for k, j in enumerate(idxs):
                            cl_ = L['cl_arr'].astype(float)
                            ax.plot(cl_[:, 0] + k * w_each, cl_[:, 1],
                                     '-', color=L['color'], lw=0.7, alpha=0.85)
                            ax.text(2 + k * w_each, 6,
                                     f"t={present[j]/max(fps,1e-9):.2f}s",
                                     fontsize=5, color='white',
                                     bbox=dict(boxstyle='round,pad=0.1',
                                                 fc='black', ec='none',
                                                 alpha=0.5))
                        ax.set_xticks([]); ax.set_yticks([])
                        for s_ in ax.spines.values(): s_.set_visible(False)
                        _scale_bar_µm(ax, _nice_bar_length_um(ax, pxu), pxu)
                    panel_letter(ax, _letter_map['f'], x=-0.02, y=1.05)
                    pos += 1

                # (g) Summary stats table
                if incl_flags['g']:
                    ax = _place()
                    ax.set_axis_off()
                    rows_txt = [["line", "K", "v (µm/s)",
                                   "R²(inl)", "n_in/n_tot", "dir", "flag"]]
                    for L in line_infos:
                        rf = L['rf']
                        rows_txt.append([
                            f"L{L['line_idx']+1}",
                            f"{rf['n_total']}",
                            f"{rf['slope']:+.2f}" if np.isfinite(rf['slope']) else "n/a",
                            f"{rf['r2_inliers']:.3f}" if np.isfinite(rf['r2_inliers']) else "n/a",
                            f"{rf['n_inliers']}/{rf['n_total']}",
                            rf['direction'],
                            "LOW" if rf['low_confidence'] else "OK",
                        ])
                    tbl = ax.table(cellText=rows_txt, loc='center',
                                     cellLoc='center')
                    tbl.auto_set_font_size(False)
                    tbl.set_fontsize(6)
                    tbl.scale(1.0, 1.2)
                    # Bold header
                    for c in range(len(rows_txt[0])):
                        tbl[(0, c)].set_text_props(weight='bold')
                    panel_letter(ax, _letter_map['g'], x=-0.02, y=1.05)
                    pos += 1

                fig.suptitle(
                    f"Nature figure suite  |  lines={len(line_infos)}  "
                    f"panels={''.join(panel_defs)}",
                    fontsize=7, y=0.995)
                fig.text(0.5, 0.005, NATURE_SUITE_CAPTION,
                          ha='center', va='bottom', fontsize=5,
                          color='0.35', style='italic')
                # constrained_layout handles spacing automatically; skip
                # tight_layout to avoid overriding it and causing overlap.
                w = tk.Toplevel(pw)
                w.title("Nature figure suite")
                _embed_with_save(w, fig, "nature_figure_suite")
                bot = ttk.Frame(w); bot.pack(fill=tk.X, padx=3, pady=2)
                def _save_suite():
                    import datetime as _dt2
                    ts = _dt2.datetime.now().strftime("%Y%m%d-%H%M%S")
                    p = filedialog.asksaveasfilename(
                        parent=w, title="Save suite (SVG + TIF)",
                        initialfile=f"nature_figure_suite_{ts}",
                        defaultextension=".svg",
                        filetypes=[("SVG", "*.svg")])
                    if not p: return
                    stem = os.path.splitext(p)[0]
                    try:
                        fig.savefig(stem + ".svg", format='svg',
                                     bbox_inches='tight',
                                     metadata={'Title': 'Nature figure suite',
                                                'Description': NATURE_SUITE_CAPTION})
                        fig.savefig(stem + ".tif", format='tiff', dpi=300,
                                     bbox_inches='tight',
                                     pil_kwargs={'compression': 'tiff_lzw'})
                        # Per-panel individual export: save each subplot's
                        # bbox alone. Reuses the same figure to keep the look
                        # identical to the composite.
                        try:
                            for ax_i, letter in zip(fig.axes,
                                                       ''.join(panel_defs)):
                                bbox = ax_i.get_tightbbox(fig.canvas.get_renderer())
                                bbox_disp = bbox.transformed(
                                    fig.dpi_scale_trans.inverted())
                                fig.savefig(f"{stem}_panel_{letter}.svg",
                                             format='svg',
                                             bbox_inches=bbox_disp)
                                fig.savefig(f"{stem}_panel_{letter}.tif",
                                             format='tiff', dpi=300,
                                             bbox_inches=bbox_disp,
                                             pil_kwargs={'compression': 'tiff_lzw'})
                        except Exception as _ep:
                            self._log(f"[nature-suite] per-panel export "
                                      f"skipped: {_ep}")
                        # Kinematics CSV
                        import csv as _csv
                        with open(stem + "_kinematics.csv", "w", newline="") as f:
                            wcsv = _csv.writer(f)
                            wcsv.writerow(['line', 'estimator', 'slope_um_per_s',
                                            'R2_inliers', 'n_inliers', 'n_total',
                                            'direction', 'residual_std_um',
                                            'inlier_frac', 'low_confidence'])
                            for L in line_infos:
                                rf = L['rf']
                                wcsv.writerow([L['line_idx'] + 1,
                                                rf['estimator'],
                                                rf['slope'],
                                                rf['r2_inliers'],
                                                rf['n_inliers'],
                                                rf['n_total'],
                                                rf['direction'],
                                                rf['residual_std'],
                                                rf['inlier_frac'],
                                                int(rf['low_confidence'])])
                        self._log(f"[nature-suite] saved {stem}.svg + .tif + "
                                  f"_kinematics.csv")
                    except Exception as e:
                        messagebox.showwarning("Export failed",
                            f"Could not save: {e}")
                ttk.Button(bot, text="Save suite (SVG/TIF + kinematics CSV)",
                            command=_save_suite).pack(side=tk.LEFT, padx=2)
                ttk.Label(bot, text=NATURE_SUITE_CAPTION,
                            foreground='#555').pack(side=tk.LEFT, padx=6)
                self._log(f"[nature-suite] rendered panels={''.join(panel_defs)}  "
                          f"lines={len(line_infos)}")

        # ── LIVE mask preview with debounced parameter updates ───────────
        # Aggregate is cached separately from threshold+morph so that slider
        # tweaks only recompute the fast half (thr+morph). The aggregate is
        # rebuilt only when source (mean/max), frame spec, or centerline
        # changes. Rebuild via [Rebuild aggregate] button too.
        _live_state = {'agg_key': None, 'agg': None, 'after_id': None,
                        'win': None, 'canvas': None, 'ax': None,
                        'im': None, 'contours': [], 'stat_var': None,
                        'traces': []}

        def _bosf_agg_key():
            return (id(_corrected_proj()),
                     mask_src_var.get(),
                     (mask_frames_var.get() or '').strip(),
                     int(band_var.get()))

        def _build_agg_cached(force=False):
            key = _bosf_agg_key()
            if not force and _live_state['agg_key'] == key and _live_state['agg'] is not None:
                return _live_state['agg']
            proj = _corrected_proj()
            if proj is None:
                raise RuntimeError("no working projection (Rebuild proj first)")
            frames = _bosf_frame_range()
            if not frames:
                raise RuntimeError("no kept frames in the requested range")
            arr = proj[frames].astype(np.float32, copy=False)
            agg = (np.nanmax(arr, axis=0) if mask_src_var.get() == 'max'
                    else np.nanmean(arr, axis=0))
            lo, hi = float(np.nanmin(agg)), float(np.nanmax(agg))
            span = max(hi - lo, 1e-12)
            agg01 = np.clip((agg - lo) / span, 0.0, 1.0)
            _live_state.update(agg_key=key, agg=agg01)
            return agg01

        def _apply_mask_only(agg01):
            """Threshold + morph only — uses the SAME code path as
            _compute_structure_mask but takes the pre-computed aggregate."""
            from scipy.ndimage import (gaussian_filter, binary_closing,
                                         binary_opening, binary_fill_holes,
                                         binary_dilation, label as _label)
            sigma = max(0.0, float(mask_smooth_var.get()))
            smoothed = gaussian_filter(agg01, sigma=sigma) if sigma > 0 else agg01
            if mask_method_var.get() == 'otsu':
                thr = _otsu_threshold(smoothed)
            else:
                pct = float(np.clip(mask_thr_var.get(), 0.0, 100.0))
                thr = float(np.percentile(smoothed, pct))
            mask = smoothed >= thr
            k_close = max(0, int(mask_close_var.get()))
            k_open  = max(0, int(mask_open_var.get()))
            k_dil   = max(0, int(mask_dilate_var.get()))
            if k_close > 0: mask = binary_closing(mask, iterations=k_close)
            if k_open > 0:  mask = binary_opening(mask, iterations=k_open)
            if bool(mask_holes_var.get()): mask = binary_fill_holes(mask)
            if k_dil > 0:   mask = binary_dilation(mask, iterations=k_dil)
            lbl, ncc = _label(mask)
            if ncc > 0:
                if bool(mask_keepcl_var.get()) and st.get('centerline') is not None:
                    cl_ = st['centerline']
                    band_mask = np.zeros_like(mask, dtype=bool)
                    half = max(1, int(band_var.get()))
                    try:
                        band_pts = _expand_line(cl_, width=half)
                        for x, y in band_pts:
                            xi, yi = int(round(x)), int(round(y))
                            if (0 <= yi < band_mask.shape[0]
                                and 0 <= xi < band_mask.shape[1]):
                                band_mask[yi, xi] = True
                    except Exception:
                        for x, y in cl_:
                            xi, yi = int(round(x)), int(round(y))
                            if (0 <= yi < band_mask.shape[0]
                                and 0 <= xi < band_mask.shape[1]):
                                band_mask[yi, xi] = True
                    keep_ids = set(int(v) for v in np.unique(lbl[band_mask]) if v != 0)
                    if not keep_ids:
                        sizes = np.bincount(lbl.ravel())
                        keep_ids = set(int(i) for i in
                            np.argsort(sizes[1:])[::-1][:max(1, int(mask_maxcc_var.get()))] + 1)
                    mask = np.isin(lbl, list(keep_ids))
                else:
                    sizes = np.bincount(lbl.ravel())
                    keep_n = max(1, int(mask_maxcc_var.get()))
                    keep_ids = set(int(i) for i in
                        np.argsort(sizes[1:])[::-1][:keep_n] + 1)
                    mask = np.isin(lbl, list(keep_ids))
            # Blend manual mask per current mode
            mode = mask_mode_var.get()
            manual = st.get('manual_mask')
            if mode == 'manual' and manual is not None and manual.shape == agg01.shape:
                mask = manual.astype(bool, copy=False)
                if k_close > 0: mask = binary_closing(mask, iterations=k_close)
                if k_open > 0:  mask = binary_opening(mask, iterations=k_open)
                if bool(mask_holes_var.get()): mask = binary_fill_holes(mask)
                if k_dil > 0:  mask = binary_dilation(mask, iterations=k_dil)
            elif mode == 'combined' and manual is not None and manual.shape == agg01.shape:
                mask = np.logical_or(mask, manual.astype(bool, copy=False))
            lbl2, ncc2 = _label(mask)
            return mask, ncc2, thr

        # ── ACTION: how the mask modifies the display image ─────────────
        # cutout       : outside = 0 (hard crop)
        # bg_suppress  : outside = inside_val * bg_floor (dim, keeps context)
        # dc_reduce    : subtract a large-σ background estimate + optional
        #                light Gaussian denoise; clamped to [0,1]
        def _smoothed_structure(img01):
            """DISPLAY-only edge-preserving enhancement of the structure
            background: bilateral / median / CLAHE / unsharp mask / gamma.
            Never touches the measurement pipeline; called on the aggregate
            image right before `_apply_mask_action`."""
            a = np.clip(np.asarray(img01, np.float32), 0.0, 1.0)
            try:
                import cv2 as _cv2
                if bool(bg_bilat_on_var.get()):
                    d = max(1, int(bg_bilat_d_var.get()))
                    sc = max(1, int(bg_bilat_sc_var.get()))
                    ss = max(1, int(bg_bilat_ss_var.get()))
                    a_u8 = (np.clip(a, 0, 1) * 255).astype(np.uint8)
                    a_u8 = _cv2.bilateralFilter(a_u8, d, sc, ss)
                    a = a_u8.astype(np.float32) / 255.0
                mk = int(bg_median_k_var.get())
                if mk >= 3:
                    if mk % 2 == 0: mk += 1
                    a_u8 = (np.clip(a, 0, 1) * 255).astype(np.uint8)
                    a_u8 = _cv2.medianBlur(a_u8, mk)
                    a = a_u8.astype(np.float32) / 255.0
                if bool(bg_clahe_var.get()):
                    a_u8 = (np.clip(a, 0, 1) * 255).astype(np.uint8)
                    clahe = _cv2.createCLAHE(
                        clipLimit=float(bg_clahe_clip_var.get()),
                        tileGridSize=(8, 8))
                    a = clahe.apply(a_u8).astype(np.float32) / 255.0
            except Exception as _e:
                self._log(f"[bosf-bg] cv2-based smoothing skipped: {_e}")
            # unsharp mask
            u_amt = float(bg_unsharp_amt_var.get())
            if u_amt > 0.0:
                try:
                    from scipy.ndimage import gaussian_filter
                    rad = max(0.5, float(bg_unsharp_rad_var.get()))
                    blurred = gaussian_filter(a, sigma=rad)
                    a = np.clip(a + u_amt * (a - blurred), 0.0, 1.0)
                except Exception as _e:
                    self._log(f"[bosf-bg] unsharp mask skipped: {_e}")
            # gamma
            g = float(bg_gamma_var.get())
            if g != 1.0 and g > 0:
                a = np.clip(a, 0.0, 1.0) ** g
            # brightness (multiplicative gain) + contrast around 0.5 midpoint
            bright = float(bg_bright_var.get())
            contrast = float(bg_contrast_var.get())
            if bright != 1.0:
                a = a * bright
            if contrast != 1.0:
                a = (a - 0.5) * contrast + 0.5
            return np.clip(a, 0.0, 1.0).astype(np.float32)

        def _apply_mask_action(img01, mask):
            from scipy.ndimage import gaussian_filter
            action = mask_action_var.get()
            floor = float(np.clip(bolus_bgfloor_var.get(), 0.0, 1.0))
            base = np.clip(img01.astype(np.float32, copy=False), 0.0, 1.0)
            if action == 'cutout':
                out = np.where(mask, base, 0.0)
            elif action == 'dc_reduce':
                sig_dc = max(1.0, float(dc_sigma_var.get()))
                bg = gaussian_filter(base, sigma=sig_dc)
                out = np.clip(base - bg, 0.0, 1.0)
                sig_dn = max(0.0, float(dc_denoise_var.get()))
                if sig_dn > 0:
                    out = gaussian_filter(out, sigma=sig_dn)
                # renormalize inside mask to [0,1] so dim structure shows
                mx = float(np.nanmax(out[mask])) if mask.any() else float(np.nanmax(out))
                if mx > 1e-6:
                    out = out / mx
                # outside gets bg_floor scaled version, so context stays if desired
                out = np.where(mask, out, out * floor)
            else:                                    # bg_suppress
                out = np.where(mask, base, base * floor)
            return np.clip(out, 0.0, 1.0)

        # ── MANUAL MASK EDITOR (polygon / brush / from-centerline) ──────
        # ── ERASE REGION EDITOR (polygon / brush / circle) ──────────────
        # `st['erase_mask']` is SUBTRACTED from the final structure mask in
        # `_compute_structure_mask`. Purpose: remove focal artifacts (bright
        # blobs / vignetted corners) that the auto threshold picked up.
        def _open_erase_editor():
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            agg01 = _build_agg_cached(force=False)
            H, W = agg01.shape
            if (st.get('erase_mask') is None
                    or st['erase_mask'].shape != (H, W)):
                st['erase_mask'] = np.zeros((H, W), dtype=bool)
                st['erase_undo'] = []
            _tool = {'tool': 'brush', 'brush_r': 10,
                      'poly': [], 'painting': False,
                      'last_xy': None,
                      'circle_start': None}
            win = tk.Toplevel(pw); win.title("Erase-region editor")
            win.geometry("880x780")
            tools = ttk.Frame(win); tools.pack(fill=tk.X, padx=4, pady=2)
            tool_var = tk.StringVar(value='brush')
            for txt, val in [("brush", 'brush'),
                              ("polygon (dbl-click closes)", 'polygon'),
                              ("circle (drag)", 'circle')]:
                rb = ttk.Radiobutton(tools, text=txt,
                                        variable=tool_var, value=val,
                                        command=lambda: _tool.update(
                                            tool=tool_var.get(),
                                            poly=[], painting=False,
                                            circle_start=None))
                rb.pack(side=tk.LEFT, padx=2)
            ttk.Label(tools, text="brush r (px):").pack(side=tk.LEFT, padx=(6, 1))
            brush_e = ttk.Entry(tools, width=4)
            brush_e.insert(0, "10"); brush_e.pack(side=tk.LEFT)
            def _sync_brush(*_a):
                try: _tool['brush_r'] = max(1, int(brush_e.get()))
                except Exception: pass
            brush_e.bind('<KeyRelease>', _sync_brush)
            ttk.Button(tools, text="Undo",
                        command=lambda: _undo()).pack(side=tk.LEFT, padx=(6, 2))
            ttk.Button(tools, text="Clear erase",
                        command=lambda: _clear()).pack(side=tk.LEFT, padx=2)
            ttk.Button(tools, text="Invert",
                        command=lambda: _invert()).pack(side=tk.LEFT, padx=2)
            fig = Figure(figsize=(7.5, 7.5), dpi=100, facecolor='white')
            ax  = fig.add_subplot(111)
            ax.set_xticks([]); ax.set_yticks([])
            for s_ in ax.spines.values(): s_.set_visible(False)
            # base image: mask outline on the aggregate so users see what's
            # ALREADY masked before erasing more.
            im_bg = ax.imshow(agg01, cmap='gray', vmin=0, vmax=1,
                                 interpolation='nearest')
            try:
                mask_prev, _ = _compute_structure_mask(force=False)
                ax.contour(mask_prev.astype(float), levels=[0.5],
                             colors=['#00d2ff'], linewidths=0.7)
            except Exception:
                pass
            def _erase_overlay(em):
                rgba = np.zeros((*em.shape, 4), dtype=np.float32)
                # bright red overlay for erase pixels
                rgba[..., 0] = 1.0
                rgba[..., 3] = np.where(em, 0.55, 0.0)
                return rgba
            im_er = ax.imshow(_erase_overlay(st['erase_mask']),
                                 interpolation='nearest')
            poly_pts, = ax.plot([], [], 'o-', color='#ffd54a',
                                   ms=4, lw=1.0, mec='k', mew=0.5)
            circle_gh, = ax.plot([], [], '-', color='#ffd54a', lw=1.0)
            canvas_e = FigureCanvasTkAgg(fig, master=win)
            canvas_e.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            stat_var = tk.StringVar(value="ready")
            ttk.Label(win, textvariable=stat_var,
                        foreground='#333').pack(fill=tk.X, padx=4)

            def _push_undo():
                st['erase_undo'].append(st['erase_mask'].copy())
                if len(st['erase_undo']) > 20:
                    st['erase_undo'].pop(0)

            def _refresh():
                im_er.set_data(_erase_overlay(st['erase_mask']))
                area = int(st['erase_mask'].sum())
                pct  = 100.0 * st['erase_mask'].mean()
                stat_var.set(f"tool={_tool['tool']}  "
                                f"r={_tool['brush_r']}  "
                                f"erased={area} px ({pct:.2f}% FOV)  "
                                f"undo-depth={len(st['erase_undo'])}")
                canvas_e.draw_idle()

            def _stamp_disc(cx, cy, r):
                r = max(1, int(r))
                y0, y1 = max(0, cy - r), min(H, cy + r + 1)
                x0, x1 = max(0, cx - r), min(W, cx + r + 1)
                if y1 <= y0 or x1 <= x0: return
                yy, xx = np.mgrid[y0:y1, x0:x1]
                d = (xx - cx) ** 2 + (yy - cy) ** 2
                inside = d <= r * r
                st['erase_mask'][y0:y1, x0:x1] |= inside

            def _stamp_line(cx0, cy0, cx1, cy1, r):
                dx, dy = cx1 - cx0, cy1 - cy0
                steps = max(1, int(max(abs(dx), abs(dy))))
                for i in range(steps + 1):
                    t = i / max(steps, 1)
                    _stamp_disc(int(round(cx0 + t * dx)),
                                 int(round(cy0 + t * dy)), r)

            def _rasterize_poly(pts):
                from PIL import Image as PILImage, ImageDraw
                im_p = PILImage.new('L', (W, H), 0)
                d = ImageDraw.Draw(im_p)
                d.polygon([(float(x), float(y)) for x, y in pts], fill=255)
                return np.asarray(im_p, dtype=np.uint8) > 0

            def _on_press(evt):
                if evt.inaxes is not ax or evt.button != 1: return
                cx, cy = int(round(evt.xdata)), int(round(evt.ydata))
                if _tool['tool'] == 'polygon':
                    if evt.dblclick and len(_tool['poly']) >= 3:
                        _push_undo()
                        pmask = _rasterize_poly(_tool['poly'])
                        st['erase_mask'] |= pmask
                        _tool['poly'] = []
                        poly_pts.set_data([], []); _refresh(); return
                    _tool['poly'].append((cx, cy))
                    xs, ys = zip(*_tool['poly'])
                    poly_pts.set_data(list(xs), list(ys))
                    canvas_e.draw_idle(); return
                if _tool['tool'] == 'circle':
                    _tool['circle_start'] = (cx, cy)
                    _tool['painting'] = True
                    return
                # brush
                _push_undo()
                _tool['painting'] = True
                _tool['last_xy'] = (cx, cy)
                _stamp_disc(cx, cy, _tool['brush_r'])
                _refresh()

            def _on_motion(evt):
                if not _tool['painting'] or evt.inaxes is not ax: return
                cx, cy = int(round(evt.xdata)), int(round(evt.ydata))
                if _tool['tool'] == 'brush':
                    lx, ly = _tool['last_xy'] or (cx, cy)
                    _stamp_line(lx, ly, cx, cy, _tool['brush_r'])
                    _tool['last_xy'] = (cx, cy)
                    _refresh()
                elif _tool['tool'] == 'circle' and _tool['circle_start'] is not None:
                    x0c, y0c = _tool['circle_start']
                    r = int(round(np.hypot(cx - x0c, cy - y0c)))
                    theta = np.linspace(0, 2 * np.pi, 96)
                    circle_gh.set_data(x0c + r * np.cos(theta),
                                          y0c + r * np.sin(theta))
                    canvas_e.draw_idle()

            def _on_release(evt):
                if _tool['tool'] == 'circle' and _tool['circle_start'] is not None:
                    if evt.inaxes is ax and evt.xdata is not None:
                        cx, cy = int(round(evt.xdata)), int(round(evt.ydata))
                        x0c, y0c = _tool['circle_start']
                        r = int(round(np.hypot(cx - x0c, cy - y0c)))
                        if r > 0:
                            _push_undo()
                            _stamp_disc(x0c, y0c, r)
                            _refresh()
                    circle_gh.set_data([], [])
                    _tool['circle_start'] = None
                _tool['painting'] = False
                _tool['last_xy'] = None

            fig.canvas.mpl_connect('button_press_event', _on_press)
            fig.canvas.mpl_connect('motion_notify_event', _on_motion)
            fig.canvas.mpl_connect('button_release_event', _on_release)

            def _undo():
                if not st['erase_undo']: return
                st['erase_mask'] = st['erase_undo'].pop()
                _refresh()
            def _clear():
                _push_undo()
                st['erase_mask'][:] = False
                _tool['poly'] = []; poly_pts.set_data([], [])
                _refresh()
            def _invert():
                _push_undo()
                st['erase_mask'] = ~st['erase_mask']
                _refresh()
            _refresh()
            _bosf_cache['key'] = None                # force mask recompute
            # Bottom button bar sits at BOTTOM first so it's never hidden.
            bot = ttk.Frame(win); bot.pack(side=tk.BOTTOM, fill=tk.X,
                                              padx=3, pady=2)
            def _apply_close():
                # Bump erase_mask identity so the mask cache invalidates on
                # the next figure regeneration.
                st['erase_mask'] = st['erase_mask'].copy()
                _bosf_cache['key'] = None
                win.destroy()
            ttk.Button(bot, text="Apply + Close",
                        command=_apply_close).pack(side=tk.RIGHT, padx=2)

        def _open_manual_mask_editor():
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            agg01 = _build_agg_cached(force=False)
            H, W = agg01.shape
            if (st.get('manual_mask') is None
                or st['manual_mask'].shape != (H, W)):
                st['manual_mask'] = np.zeros((H, W), dtype=bool)
                st['manual_mask_undo'] = []
                st['manual_mask_strokes'] = []
            # Ensure the per-stroke list exists (session may have loaded a
            # merged mask without stroke history).
            if st.get('manual_mask_strokes') is None:
                st['manual_mask_strokes'] = []
            # Stroke GROUPS: each group = list of stroke deltas that
            # together define ONE vessel line. First open initializes
            # one empty active group; "New vessel line" appends another.
            if not st.get('manual_mask_groups'):
                st['manual_mask_groups'] = [[]]
            st.setdefault('active_group', 0)
            _tool = {'tool': 'brush',   # brush | polygon | erase
                      'brush_r': 8,
                      'poly': [],
                      'painting': False,
                      'last_xy': None,
                      'stroke_before': None,   # bool[H,W] snapshot at press
                      'stroke_is_add': False}  # True if this stroke ADDS
            win = tk.Toplevel(pw); win.title("Manual mask editor")
            win.geometry("880x780")
            tools = ttk.Frame(win); tools.pack(fill=tk.X, padx=4, pady=2)
            tool_var = tk.StringVar(value='brush')
            for txt, val in [("brush", 'brush'),
                              ("erase", 'erase'),
                              ("polygon (dbl-click closes)", 'polygon')]:
                rb = ttk.Radiobutton(tools, text=txt,
                                        variable=tool_var, value=val,
                                        command=lambda: _tool.update(
                                            tool=tool_var.get(),
                                            poly=[],
                                            painting=False))
                rb.pack(side=tk.LEFT, padx=2)
            ttk.Label(tools, text="brush r (px):").pack(side=tk.LEFT, padx=(6, 1))
            brush_e = ttk.Entry(tools, width=4)
            brush_e.insert(0, "8"); brush_e.pack(side=tk.LEFT)
            def _sync_brush(*_a):
                try: _tool['brush_r'] = max(1, int(brush_e.get()))
                except Exception: pass
            brush_e.bind('<KeyRelease>', _sync_brush)
            ttk.Label(tools, text="centerline w (px):").pack(side=tk.LEFT, padx=(6, 1))
            cl_w_var = tk.IntVar(value=6)
            ttk.Entry(tools, textvariable=cl_w_var, width=4).pack(side=tk.LEFT)
            ttk.Button(tools, text="From centerline",
                        command=lambda: _from_centerline()).pack(side=tk.LEFT, padx=4)
            ttk.Button(tools, text="Undo",
                        command=lambda: _undo()).pack(side=tk.LEFT, padx=2)
            ttk.Button(tools, text="Clear",
                        command=lambda: _clear()).pack(side=tk.LEFT, padx=2)
            ttk.Button(tools, text="Invert",
                        command=lambda: _invert()).pack(side=tk.LEFT, padx=2)
            # ── Vessel-line GROUPING controls ──────────────────────────
            # Strokes drawn together form ONE vessel line. Click "New
            # vessel line" to close the current group and start another
            # so subsequent strokes go into the new line.
            group_lbl_var = tk.StringVar(value="")
            def _new_vessel_line():
                cur = st.get('manual_mask_groups') or [[]]
                if cur and not cur[-1]:
                    return   # already empty active group
                cur.append([])
                st['manual_mask_groups'] = cur
                st['active_group'] = len(cur) - 1
                _refresh_group_label()
                self._log(f"[mask-editor] new vessel-line group "
                          f"#{st['active_group'] + 1} started")
            def _refresh_group_label():
                g = st.get('manual_mask_groups') or [[]]
                idx = int(st.get('active_group', 0))
                n_strokes = len(g[idx]) if 0 <= idx < len(g) else 0
                group_lbl_var.set(
                    f"drawing vessel line #{idx + 1}  "
                    f"({n_strokes} stroke{'s' if n_strokes != 1 else ''}"
                    f"; {len(g)} line{'s' if len(g) != 1 else ''} total)")
            ttk.Button(tools, text="New vessel line",
                        command=_new_vessel_line).pack(
                            side=tk.LEFT, padx=(8, 2))
            ttk.Label(tools, textvariable=group_lbl_var,
                        foreground='#036',
                        font=('TkDefaultFont', 8, 'bold')).pack(
                            side=tk.LEFT, padx=(6, 2))
            _refresh_group_label()
            fig = Figure(figsize=(7.5, 7.5), dpi=100, facecolor='white')
            ax  = fig.add_subplot(111)
            ax.set_xticks([]); ax.set_yticks([])
            for s_ in ax.spines.values(): s_.set_visible(False)
            im_bg = ax.imshow(agg01, cmap='gray', vmin=0, vmax=1,
                                 interpolation='nearest')
            # RGBA overlay of the mask (semi-transparent accent color)
            def _mask_overlay(mask):
                rgba = np.zeros((*mask.shape, 4), dtype=np.float32)
                # Okabe-Ito vermillion = OKABE_ITO[6]
                rgba[..., 0] = int(OKABE_ITO[6][1:3], 16) / 255.0
                rgba[..., 1] = int(OKABE_ITO[6][3:5], 16) / 255.0
                rgba[..., 2] = int(OKABE_ITO[6][5:7], 16) / 255.0
                rgba[..., 3] = np.where(mask, 0.45, 0.0)
                return rgba
            im_mk = ax.imshow(_mask_overlay(st['manual_mask']),
                                 interpolation='nearest')
            # polygon vertex markers
            poly_pts, = ax.plot([], [], 'o-', color=OKABE_ITO[4],
                                   ms=4, lw=1.0, mec='k', mew=0.5)
            canvas = FigureCanvasTkAgg(fig, master=win)
            canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            stat_var = tk.StringVar(value="ready")
            ttk.Label(win, textvariable=stat_var,
                        foreground='#333').pack(fill=tk.X, padx=4)

            def _push_undo():
                st['manual_mask_undo'].append(st['manual_mask'].copy())
                if len(st['manual_mask_undo']) > 20:
                    st['manual_mask_undo'].pop(0)

            def _refresh():
                im_mk.set_data(_mask_overlay(st['manual_mask']))
                area = int(st['manual_mask'].sum())
                pct  = 100.0 * st['manual_mask'].mean()
                stat_var.set(f"tool={_tool['tool']}  "
                                f"r={_tool['brush_r']}  "
                                f"painted={area} px ({pct:.2f}% FOV)  "
                                f"undo-depth={len(st['manual_mask_undo'])}")
                canvas.draw_idle()

            def _stamp_disc(cx, cy, value):
                r = max(1, int(_tool['brush_r']))
                y0, y1 = max(0, cy - r), min(H, cy + r + 1)
                x0, x1 = max(0, cx - r), min(W, cx + r + 1)
                if y1 <= y0 or x1 <= x0: return
                yy, xx = np.mgrid[y0:y1, x0:x1]
                d = (xx - cx) ** 2 + (yy - cy) ** 2
                inside = d <= r * r
                if value:
                    st['manual_mask'][y0:y1, x0:x1] |= inside
                else:
                    st['manual_mask'][y0:y1, x0:x1] &= ~inside

            def _stamp_line(cx0, cy0, cx1, cy1, value):
                # Bresenham-lite: interpolate discs along the segment so a
                # fast drag produces a continuous line.
                dx, dy = cx1 - cx0, cy1 - cy0
                steps = max(1, int(max(abs(dx), abs(dy))))
                for i in range(steps + 1):
                    t = i / max(steps, 1)
                    _stamp_disc(int(round(cx0 + t * dx)),
                                 int(round(cy0 + t * dy)),
                                 value)

            def _rasterize_poly(pts):
                from PIL import Image as PILImage, ImageDraw
                im_p = PILImage.new('L', (W, H), 0)
                d = ImageDraw.Draw(im_p)
                d.polygon([(float(x), float(y)) for x, y in pts], fill=255)
                return np.asarray(im_p, dtype=np.uint8) > 0

            def _finalize_stroke_delta():
                """If the just-finished action ADDED pixels to the mask,
                append the delta (bool[H,W]) both to the flat strokes
                list AND into the currently active vessel-line group."""
                if not _tool.get('stroke_is_add'): return
                before = _tool.get('stroke_before')
                if before is None: return
                delta = st['manual_mask'] & ~before
                if int(delta.sum()) > 0:
                    st['manual_mask_strokes'].append(delta.copy())
                    # Append into the ACTIVE group so this stroke
                    # contributes to that vessel line's mask on Build.
                    groups = st.get('manual_mask_groups') or [[]]
                    if not groups: groups = [[]]
                    ai = int(st.get('active_group', 0))
                    if not (0 <= ai < len(groups)):
                        ai = len(groups) - 1
                        st['active_group'] = ai
                    groups[ai].append(delta.copy())
                    st['manual_mask_groups'] = groups
                    self._log("[mask-editor] recorded stroke "
                              f"#{len(st['manual_mask_strokes'])} "
                              f"in group #{ai + 1} "
                              f"({int(delta.sum())} px)")
                    try: _refresh_group_label()
                    except Exception: pass
                _tool['stroke_before'] = None
                _tool['stroke_is_add'] = False

            def _on_press(evt):
                if evt.inaxes is not ax or evt.button != 1: return
                cx, cy = int(round(evt.xdata)), int(round(evt.ydata))
                if _tool['tool'] == 'polygon':
                    if evt.dblclick and len(_tool['poly']) >= 3:
                        _push_undo()
                        _tool['stroke_before'] = st['manual_mask'].copy()
                        _tool['stroke_is_add'] = True
                        pmask = _rasterize_poly(_tool['poly'])
                        st['manual_mask'] |= pmask
                        _tool['poly'] = []
                        poly_pts.set_data([], [])
                        _finalize_stroke_delta()
                        _refresh()
                        return
                    _tool['poly'].append((cx, cy))
                    xs, ys = zip(*_tool['poly'])
                    poly_pts.set_data(list(xs), list(ys))
                    canvas.draw_idle()
                    return
                # brush / erase — press stamps a single disc, drag continues
                _push_undo()
                val = (_tool['tool'] == 'brush')
                # Snapshot BEFORE this stroke so on release we can record
                # the delta as one stroke = one future vessel polyline.
                _tool['stroke_before'] = st['manual_mask'].copy()
                _tool['stroke_is_add'] = bool(val)
                _tool['painting'] = True
                _tool['last_xy'] = (cx, cy)
                _stamp_disc(cx, cy, val); _refresh()

            def _on_motion(evt):
                if not _tool['painting'] or evt.inaxes is not ax: return
                cx, cy = int(round(evt.xdata)), int(round(evt.ydata))
                lx, ly = _tool['last_xy'] or (cx, cy)
                val = (_tool['tool'] == 'brush')
                _stamp_line(lx, ly, cx, cy, val)
                _tool['last_xy'] = (cx, cy)
                _refresh()

            def _on_release(_evt):
                _tool['painting'] = False
                _tool['last_xy'] = None
                _finalize_stroke_delta()

            fig.canvas.mpl_connect('button_press_event', _on_press)
            fig.canvas.mpl_connect('motion_notify_event', _on_motion)
            fig.canvas.mpl_connect('button_release_event', _on_release)

            def _from_centerline():
                cl_ = st.get('centerline')
                if cl_ is None or len(cl_) < 2:
                    messagebox.showwarning("From centerline",
                        "Draw a centerline first."); return
                _push_undo()
                half = max(1, int(cl_w_var.get()))
                try:
                    band_pts = _expand_line(cl_, width=half)
                except Exception:
                    band_pts = list(cl_)
                for x, y in band_pts:
                    xi, yi = int(round(x)), int(round(y))
                    if 0 <= yi < H and 0 <= xi < W:
                        st['manual_mask'][yi, xi] = True
                _refresh()

            def _undo():
                if not st['manual_mask_undo']: return
                st['manual_mask'] = st['manual_mask_undo'].pop()
                # Drop the last stroke from BOTH the flat list AND the
                # active group so grouping stays in sync with the mask.
                if st.get('manual_mask_strokes'):
                    st['manual_mask_strokes'].pop()
                groups = st.get('manual_mask_groups') or []
                if groups:
                    # Find the last non-empty group and pop from it.
                    for gi in range(len(groups) - 1, -1, -1):
                        if groups[gi]:
                            groups[gi].pop()
                            break
                    st['manual_mask_groups'] = groups
                try: _refresh_group_label()
                except Exception: pass
                _refresh()

            def _clear():
                _push_undo()
                st['manual_mask'][:] = False
                st['manual_mask_strokes'] = []
                st['manual_mask_groups'] = [[]]
                st['active_group'] = 0
                _tool['poly'] = []; poly_pts.set_data([], [])
                try: _refresh_group_label()
                except Exception: pass
                _refresh()

            def _invert():
                _push_undo()
                st['manual_mask'] = ~st['manual_mask']
                # Invert breaks stroke-per-vessel semantics; drop stroke
                # history so downstream falls back to merged-mask decomp.
                st['manual_mask_strokes'] = []
                st['manual_mask_groups'] = [[]]
                st['active_group'] = 0
                try: _refresh_group_label()
                except Exception: pass
                _refresh()

            _refresh()
            # invalidate mask cache so previews reflect edits
            _bosf_cache['key'] = None

        def _open_mask_preview_live():
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            # Rebuild aggregate up-front (fast if cached)
            agg01 = _build_agg_cached(force=True)
            win = tk.Toplevel(pw); win.title("Structure mask — live preview")
            top = ttk.Frame(win); top.pack(fill=tk.BOTH, expand=True)
            _live_state['win'] = win
            fig = Figure(figsize=(6.5, 5.5), dpi=110, facecolor='white')
            ax  = fig.add_subplot(111)
            im  = ax.imshow(agg01, cmap='gray', vmin=0, vmax=1,
                             interpolation='nearest')
            ax.set_xticks([]); ax.set_yticks([])
            for s_ in ax.spines.values(): s_.set_visible(False)
            canvas = FigureCanvasTkAgg(fig, master=top)
            canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            _live_state.update(canvas=canvas, ax=ax, im=im, contours=[])
            stat_var = tk.StringVar(value="—")
            _live_state['stat_var'] = stat_var
            stat_bar = ttk.Frame(win); stat_bar.pack(fill=tk.X, padx=4, pady=2)
            ttk.Label(stat_bar, textvariable=stat_var,
                        foreground='#333').pack(side=tk.LEFT)
            btns = ttk.Frame(win); btns.pack(fill=tk.X, padx=4, pady=2)
            ttk.Button(btns, text="Rebuild aggregate",
                        command=lambda: _pulse_run_safe(
                            "Rebuild aggregate", _rebuild_agg_click)
                        ).pack(side=tk.LEFT, padx=2)
            ttk.Button(btns, text="Apply mask (cache)",
                        command=lambda: _pulse_run_safe(
                            "Apply mask", _apply_mask_click)
                        ).pack(side=tk.LEFT, padx=2)
            ttk.Button(btns, text="Close",
                        command=win.destroy).pack(side=tk.RIGHT, padx=2)

            def _redraw_now():
                agg = _live_state['agg']
                if agg is None: return
                try:
                    mask, ncc, thr = _apply_mask_only(agg)
                except Exception as e:
                    stat_var.set(f"ERROR: {e}"); return
                _live_state['im'].set_data(agg)
                # Clear old contour collections
                for coll in _live_state['contours']:
                    try: coll.remove()
                    except Exception: pass
                _live_state['contours'] = []
                cs = ax.contour(mask.astype(float), levels=[0.5],
                                  colors=[OKABE_ITO[6]], linewidths=0.9)
                _live_state['contours'].extend(cs.collections)
                area_px = int(mask.sum())
                area_pct = 100.0 * mask.mean()
                stat_var.set(
                    f"thr={('Otsu ' if mask_method_var.get() == 'otsu' else 'pct ')}"
                    f"= {thr:.4f}  |  area={area_px} px "
                    f"({area_pct:.2f}% FOV)  |  CCs={ncc}")
                canvas.draw_idle()

            def _debounced(*_a):
                if _live_state['after_id'] is not None:
                    try: win.after_cancel(_live_state['after_id'])
                    except Exception: pass
                _live_state['after_id'] = win.after(150, _redraw_now)

            def _rebuild_agg_click():
                _build_agg_cached(force=True)
                _live_state['im'].set_data(_live_state['agg'])
                _redraw_now()

            def _apply_mask_click():
                # Prime _bosf_cache so subsequent figures skip recomputation
                mask, agg = _compute_structure_mask(force=True)
                stat_var.set(
                    f"applied — cached mask: area={int(mask.sum())} px "
                    f"({100.0*mask.mean():.2f}%), agg key updated")

            # Trace every mask var so ANY change triggers a debounced redraw.
            trace_ids = []
            for v in (mask_src_var, mask_frames_var, mask_method_var,
                       mask_thr_var, mask_smooth_var, mask_close_var,
                       mask_open_var, mask_dilate_var, mask_holes_var,
                       mask_keepcl_var, mask_maxcc_var):
                trace_ids.append((v, v.trace_add('write', _debounced)))
            _live_state['traces'] = trace_ids

            def _on_close():
                for v, tid in trace_ids:
                    try: v.trace_remove('write', tid)
                    except Exception: pass
                _live_state.update(win=None, canvas=None, ax=None,
                                     im=None, contours=[], stat_var=None,
                                     traces=[])
                win.destroy()
            win.protocol("WM_DELETE_WINDOW", _on_close)
            _redraw_now()

        # ── SAVE / LOAD MASK BUNDLE (TIF + overlay PNG + params JSON) ────
        def _save_mask_bundle():
            from PIL import Image as PILImage
            from matplotlib.figure import Figure
            import json as _json, datetime as _dt
            mask, agg01 = _compute_structure_mask(force=False)
            p = filedialog.asksaveasfilename(
                parent=pw, title="Save mask bundle (stem)",
                initialfile="structure_mask", defaultextension=".tif",
                filetypes=[("TIF", "*.tif")])
            if not p: return
            stem = os.path.splitext(p)[0]
            tif_p = stem + "_mask.tif"
            png_p = stem + "_mask_overlay.png"
            js_p  = stem + "_mask_params.json"
            # Binary mask as uint8 0/255 TIF
            u8 = (mask.astype(np.uint8) * 255)
            PILImage.fromarray(u8, mode='L').save(tif_p,
                                                    compression='tiff_lzw')
            # Overlay PNG via Figure (Nature-styled, no pyplot)
            with apply_nature_style():
                fig = Figure(figsize=(5.5, 5.5), dpi=200, facecolor='white')
                ax  = fig.add_subplot(111)
                ax.imshow(agg01, cmap='gray', vmin=0, vmax=1,
                            interpolation='nearest')
                ax.contour(mask.astype(float), levels=[0.5],
                             colors=[OKABE_ITO[6]], linewidths=0.9)
                ax.set_xticks([]); ax.set_yticks([])
                for s_ in ax.spines.values(): s_.set_visible(False)
                pxu = float(px_var.get())
                _scale_bar_µm(ax, _nice_bar_length_um(ax, pxu), pxu)
                fig.tight_layout()
                fig.savefig(png_p, bbox_inches='tight')
            # Params JSON
            frames = _bosf_frame_range()
            src_path = st.get('_source_path') or st.get('source_path')
            meta = dict(
                kind="structure_mask",
                iso_time=_dt.datetime.now().isoformat(timespec='seconds'),
                source_path=str(src_path) if src_path else None,
                shape=[int(mask.shape[0]), int(mask.shape[1])],
                T=int(st['proj'].shape[0]),
                px_um=float(px_var.get()),
                fps=float(fps_var.get()),
                params=dict(
                    aggregate=mask_src_var.get(),
                    frames_used=len(frames),
                    frame_spec=(mask_frames_var.get() or '').strip(),
                    threshold_method=mask_method_var.get(),
                    threshold_value=float(mask_thr_var.get()),
                    smooth_sigma_px=float(mask_smooth_var.get()),
                    close=int(mask_close_var.get()),
                    open=int(mask_open_var.get()),
                    dilate=int(mask_dilate_var.get()),
                    fill_holes=bool(mask_holes_var.get()),
                    keep_cc_centerline=bool(mask_keepcl_var.get()),
                    max_cc=int(mask_maxcc_var.get()),
                    band_px=int(band_var.get()),
                    bg_floor=float(bolus_bgfloor_var.get()),
                ),
                area_px=int(mask.sum()),
                area_frac=float(mask.mean()),
                note=("Mask is DISPLAY-only; quantitative signals never "
                       "read it. Reload with 'Load mask…' → TIF (uses the "
                       "binary as-is) or JSON (re-derives from current data)."),
            )
            with open(js_p, "w") as f:
                _json.dump(meta, f, indent=2)
            self._log(f"[mask] saved bundle:\n  {tif_p}\n  {png_p}\n  {js_p}")

        def _load_mask_bundle():
            from PIL import Image as PILImage
            import json as _json
            p = filedialog.askopenfilename(
                parent=pw, title="Load mask (TIF or params JSON)",
                filetypes=[("Mask TIF or params JSON", "*.tif;*.tiff;*.json"),
                            ("TIF", "*.tif;*.tiff"), ("JSON", "*.json")])
            if not p: return
            ext = os.path.splitext(p)[1].lower()
            H, W = st['proj'].shape[1:3]
            if ext in ('.tif', '.tiff'):
                arr = np.array(PILImage.open(p))
                if arr.shape[:2] != (H, W):
                    messagebox.showwarning(
                        "Load mask",
                        f"Shape mismatch: file {arr.shape[:2]} vs "
                        f"current data {(H, W)}. Not applied."); return
                mask = (arr > 0)
                _bosf_cache.update(key=('loaded_tif', os.path.abspath(p)),
                                     mask=mask,
                                     agg=_build_agg_cached(force=True))
                self._log(f"[mask] loaded TIF directly → cached ({int(mask.sum())} px on)")
            elif ext == '.json':
                with open(p) as f:
                    meta = _json.load(f)
                pr = meta.get('params', {})
                # Apply params to the Tk vars
                if 'aggregate' in pr:         mask_src_var.set(pr['aggregate'])
                if 'frame_spec' in pr:        mask_frames_var.set(pr.get('frame_spec', ''))
                if 'threshold_method' in pr:  mask_method_var.set(pr['threshold_method'])
                if 'threshold_value' in pr:   mask_thr_var.set(float(pr['threshold_value']))
                if 'smooth_sigma_px' in pr:   mask_smooth_var.set(float(pr['smooth_sigma_px']))
                if 'close' in pr:             mask_close_var.set(int(pr['close']))
                if 'open' in pr:              mask_open_var.set(int(pr['open']))
                if 'dilate' in pr:            mask_dilate_var.set(int(pr['dilate']))
                if 'fill_holes' in pr:        mask_holes_var.set(bool(pr['fill_holes']))
                if 'keep_cc_centerline' in pr:mask_keepcl_var.set(bool(pr['keep_cc_centerline']))
                if 'max_cc' in pr:            mask_maxcc_var.set(int(pr['max_cc']))
                if 'bg_floor' in pr:          bolus_bgfloor_var.set(float(pr['bg_floor']))
                # Re-derive mask from current data using those params
                mask, agg = _compute_structure_mask(force=True)
                sh = meta.get('shape')
                if sh and tuple(sh) != mask.shape:
                    self._log(f"[mask] WARN: params saved at shape {sh} but "
                              f"current data is {mask.shape}. Re-derived on current data.")
                self._log(f"[mask] loaded params JSON, re-derived: "
                          f"area={int(mask.sum())} px "
                          f"({100.0*mask.mean():.2f}%)")
            else:
                messagebox.showwarning("Load mask",
                    f"Unsupported extension '{ext}'"); return
            # Refresh live preview if open
            if _live_state.get('win') is not None:
                try:
                    _live_state['im'].set_data(_bosf_cache['agg'])
                    for coll in _live_state['contours']:
                        try: coll.remove()
                        except Exception: pass
                    _live_state['contours'] = []
                    cs = _live_state['ax'].contour(
                        _bosf_cache['mask'].astype(float),
                        levels=[0.5], colors=[OKABE_ITO[6]], linewidths=0.9)
                    _live_state['contours'].extend(cs.collections)
                    _live_state['canvas'].draw_idle()
                except Exception:
                    pass

        # ── SAVE / LOAD DIFFERENTIAL FRAME LIST (JSON + CSV) ─────────────
        def _save_diff_frames():
            import json as _json, csv as _csv, datetime as _dt
            spec = (pulse_frames_var.get() or '').strip()
            if not spec:
                messagebox.showwarning("Save diff frames",
                    "The 'frames' entry is empty."); return
            from slim_recon.layered_export import parse_frame_spec
            T_ = st['proj'].shape[0]
            resolved = parse_frame_spec(spec, T_)
            if not resolved:
                messagebox.showwarning("Save diff frames",
                    "No valid frame indices in the current spec."); return
            o2c = st['orig_to_cleaned']
            if pulse_basis_var.get() == 'cleaned':
                c2o = st['cleaned_to_orig']
                if c2o is None:
                    messagebox.showwarning("Save diff frames",
                        "No cleaned index map."); return
                resolved_orig = [int(c2o[min(max(0, i), c2o.size - 1)])
                                   for i in resolved]
            else:
                resolved_orig = list(resolved)
            # Resolve cleaned indices carefully — deleted frames are
            # o2c[f] is None, and o2c itself may be None/empty. Never call
            # int(None); null values propagate as JSON null / empty CSV.
            def _safe_c(f):
                if not o2c: return None
                v = o2c.get(f) if hasattr(o2c, 'get') else None
                if v is None: return None
                try: return int(v)
                except Exception: return None
            resolved_cleaned = [_safe_c(f) for f in resolved_orig]
            fps = float(fps_var.get()); pxu = float(px_var.get())
            # `ref` is only meaningful for the vs-ref diff mode.
            def _safe_ref():
                if pulse_diff_mode_var.get() != 'vs_ref':
                    return None
                try:
                    v = pulse_ref_var.get()
                    return int(v) if v is not None else None
                except Exception:
                    return None
            ref_val = _safe_ref()
            p = filedialog.asksaveasfilename(
                parent=pw, title="Save differential frames (stem)",
                initialfile="diff_frames", defaultextension=".json",
                filetypes=[("JSON", "*.json")])
            if not p: return
            stem = os.path.splitext(p)[0]
            js_p = stem + "_diffframes.json"
            csv_p = stem + "_diffframes.csv"
            name = os.path.basename(stem)
            entry = dict(
                name=name,
                iso_time=_dt.datetime.now().isoformat(timespec='seconds'),
                spec=spec,
                basis=pulse_basis_var.get(),
                mode=pulse_diff_mode_var.get(),
                ref=ref_val,                             # may be null
                fps=fps, px_um=pxu, T=int(T_),
                resolved_orig=[int(x) for x in resolved_orig],
                resolved_cleaned=resolved_cleaned,       # may contain nulls
                snap_on=bool(pulse_snap_var.get()),
                sigma_xy=float(pulse_sigma_var.get()),
                tau_win=int(pulse_tauwin_var.get()),
            )
            with open(js_p, "w") as f:
                _json.dump(entry, f, indent=2)
            with open(csv_p, "w", newline="") as f:
                w_ = _csv.writer(f)
                w_.writerow(['name', 'basis', 'mode', 'ref',
                              'fps', 'px_um', 'T', 'spec'])
                w_.writerow([name, entry['basis'], entry['mode'],
                              ('' if ref_val is None else ref_val),
                              fps, pxu, T_, spec])
                w_.writerow([])
                w_.writerow(['index_orig', 'index_cleaned', 'time_s'])
                for oi, ci in zip(resolved_orig, resolved_cleaned):
                    w_.writerow([int(oi),
                                  ('' if ci is None else int(ci)),
                                  oi / max(fps, 1e-9)])
            # Add to in-memory history (dedupe by stem name)
            st['pulse_sets'] = [e for e in st['pulse_sets']
                                 if e.get('name') != name]
            st['pulse_sets'].append(dict(name=name, spec=spec,
                                          basis=entry['basis'],
                                          mode=entry['mode'],
                                          ref=ref_val))
            if callable(st.get('pulse_hist_refresh')):
                st['pulse_hist_refresh']()
            self._log(f"[pulse-diff] saved frames bundle:\n  {js_p}\n  {csv_p}")

        def _load_diff_frames():
            import json as _json, csv as _csv
            p = filedialog.askopenfilename(
                parent=pw, title="Load differential frames (JSON or CSV)",
                filetypes=[("Diff frames", "*.json;*.csv"),
                            ("JSON", "*.json"), ("CSV", "*.csv")])
            if not p: return
            ext = os.path.splitext(p)[1].lower()
            spec = None; basis = None; mode = None; ref = None; name = None
            if ext == '.json':
                with open(p) as f:
                    entry = _json.load(f)
                spec = entry.get('spec')
                basis = entry.get('basis'); mode = entry.get('mode')
                ref = entry.get('ref'); name = entry.get('name')
            elif ext == '.csv':
                with open(p) as f:
                    rows = list(_csv.reader(f))
                if rows and len(rows) >= 2 and rows[0] and rows[0][0] == 'name':
                    hdr = rows[0]; vals = rows[1]
                    d = dict(zip(hdr, vals))
                    spec = d.get('spec')
                    basis = d.get('basis'); mode = d.get('mode')
                    raw_ref = d.get('ref', '')
                    try:
                        ref = int(raw_ref) if str(raw_ref).strip() else None
                    except Exception:
                        ref = None
                    name = d.get('name')
                else:
                    idxs = []
                    for r in rows:
                        if r and r[0].isdigit():
                            idxs.append(r[0])
                    spec = ",".join(idxs); name = os.path.basename(p)
            else:
                messagebox.showwarning("Load diff frames",
                    f"Unsupported extension '{ext}'"); return
            if not spec:
                messagebox.showwarning("Load diff frames",
                    "Could not parse a `spec` from the file."); return
            pulse_frames_var.set(spec)
            if basis: pulse_basis_var.set(basis)
            if mode:  pulse_diff_mode_var.set(mode)
            if ref is not None:
                try: pulse_ref_var.set(int(ref))
                except Exception: pass
            if name:
                st['pulse_sets'] = [e for e in st['pulse_sets']
                                     if e.get('name') != name]
                st['pulse_sets'].append(dict(name=name, spec=spec,
                                              basis=basis or 'orig',
                                              mode=mode or 'consecutive',
                                              ref=ref))
                if callable(st.get('pulse_hist_refresh')):
                    st['pulse_hist_refresh']()
            self._log(f"[pulse-diff] loaded frames: name='{name}' "
                      f"spec='{spec}'")

