        def _pf_left_inner_cfg(_evt):
            pf_canvas_left.configure(scrollregion=pf_canvas_left.bbox('all'))
        def _pf_left_canvas_cfg(evt):
            pf_canvas_left.itemconfigure(_pf_left_win_id, width=evt.width)
        left.bind('<Configure>', _pf_left_inner_cfg)
        pf_canvas_left.bind('<Configure>', _pf_left_canvas_cfg)
        # Wheel scrolls the column ONLY while the pointer hovers it, so the image canvas's own
        # widget-level <MouseWheel> binding (frame scrubbing) is untouched.
        def _pf_wheel(evt):
            d = getattr(evt, 'delta', 0)
            if d:
                step = int(-1 * (d / 120)) if abs(d) >= 120 else int(-1 * d)
                if step == 0: step = -1 if d > 0 else 1
                pf_canvas_left.yview_scroll(step, 'units')
        def _pf_wheel_up(_e):  pf_canvas_left.yview_scroll(-1, 'units')
        def _pf_wheel_dn(_e):  pf_canvas_left.yview_scroll( 1, 'units')
        def _pf_bind_wheel(_e):
            pf_canvas_left.bind_all('<MouseWheel>', _pf_wheel)
            pf_canvas_left.bind_all('<Button-4>', _pf_wheel_up)
            pf_canvas_left.bind_all('<Button-5>', _pf_wheel_dn)
        def _pf_unbind_wheel(_e):
            pf_canvas_left.unbind_all('<MouseWheel>')
            pf_canvas_left.unbind_all('<Button-4>')
            pf_canvas_left.unbind_all('<Button-5>')
        pf_canvas_left.bind('<Enter>', _pf_bind_wheel)
        pf_canvas_left.bind('<Leave>', _pf_unbind_wheel)

        right = ttk.Frame(pw)
        right.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

