        # ── Controls: four tabs (Setup / Preprocess / Segments / Analysis) ──
        def _collapsible(parent, title, start_open=False):
            """A titled checkbutton that shows/hides an inner frame. Returns the inner frame."""
            holder = ttk.Frame(parent); holder.pack(fill=tk.X, padx=2, pady=1)
            ov = tk.BooleanVar(value=bool(start_open)); inner = ttk.Frame(holder)
            def _tog():
                if ov.get(): inner.pack(fill=tk.X, padx=8, pady=1)
                else: inner.forget()
            ttk.Checkbutton(holder, text='▸ ' + title, variable=ov, command=_tog).pack(anchor='w')
            if start_open: inner.pack(fill=tk.X, padx=8, pady=1)
            return inner
        nb = ttk.Notebook(left); nb.pack(fill=tk.BOTH, expand=True, padx=2, pady=2)
        tab_setup = ttk.Frame(nb); nb.add(tab_setup, text='Setup')
        tab_pre = ttk.Frame(nb); nb.add(tab_pre, text='Preprocess')
        tab_seg = ttk.Frame(nb); nb.add(tab_seg, text='Segments')
