        bk_frame = ttk.LabelFrame(tab_ana, text="Bolus Kinetics params (recon)")
        bk_frame.pack(fill=tk.X, padx=3, pady=3)
        bk_npts_var = tk.IntVar(value=120); bk_band_var = tk.IntVar(value=4)
