        bk_target_lo_var = tk.IntVar(value=8); bk_target_hi_var = tk.IntVar(value=12)
        bk_v_lo_var = tk.DoubleVar(value=0.0); bk_v_hi_var = tk.DoubleVar(value=0.0)   # 0 = unset
        agg_stat_var = tk.StringVar(value='mean'); agg_weight_var = tk.StringVar(value='none')
        agg_ci_var = tk.StringVar(value='t'); agg_boot_var = tk.IntVar(value=10000)
        agg_outlier_var = tk.StringVar(value='none'); agg_mad_k_var = tk.DoubleVar(value=3.0)
