        # ── Segment Batch (recon pipeline): manual ~10 intervals -> identical processing ──
        sbf = ttk.LabelFrame(tab_seg, text="Segment Batch (recon pipeline)")
        sbf.pack(fill=tk.X, padx=3, pady=3)
        prof_hash_var = tk.StringVar(value='(run to stamp)')
        sbr0 = ttk.Frame(sbf); sbr0.pack(fill=tk.X, padx=2, pady=1)
        ttk.Label(sbr0, text="profile_hash:").pack(side=tk.LEFT)
