        ttk.Checkbutton(sbr0, text="Lock profile", variable=seg_lock_var).pack(side=tk.RIGHT, padx=2)
        sbr1 = ttk.Frame(sbf); sbr1.pack(fill=tk.X, padx=2, pady=1)
        ttk.Label(sbr1, text="diam len px:").pack(side=tk.LEFT)
        ttk.Spinbox(sbr1, from_=5, to=101, width=4, textvariable=seg_diam_len_var).pack(side=tk.LEFT, padx=1)
        ttk.Label(sbr1, text="diam frac:").pack(side=tk.LEFT)
        ttk.Spinbox(sbr1, from_=0.1, to=0.9, increment=0.05, width=4,
                    textvariable=seg_diam_frac_var).pack(side=tk.LEFT, padx=1)
        ttk.Checkbutton(sbr1, text="allow heterogeneous processing",
                        variable=seg_allow_hetero_var).pack(side=tk.LEFT, padx=4)
        sbrs = ttk.Frame(sbf); sbrs.pack(fill=tk.X, padx=2, pady=1)
        ttk.Label(sbrs, text="diff step:").pack(side=tk.LEFT)
        ttk.Combobox(sbrs, textvariable=step_mode_var, width=11, state='readonly',
                     values=('fixed_step', 'fixed_count')).pack(side=tk.LEFT, padx=1)
        ttk.Label(sbrs, text="step:").pack(side=tk.LEFT)
        ttk.Spinbox(sbrs, from_=1, to=50, width=3, textvariable=bk_step_var).pack(side=tk.LEFT, padx=1)
        ttk.Label(sbrs, text="n target:").pack(side=tk.LEFT)
        ttk.Spinbox(sbrs, from_=5, to=400, width=4, textvariable=bk_ntarget_var).pack(side=tk.LEFT, padx=1)
        # Stage 5 (D4): detection scope drives the HONEST frequency denominator; Stage 2 (D5): FG lock.
        sbr_ds = ttk.Frame(sbf); sbr_ds.pack(fill=tk.X, padx=2, pady=1)
        ttk.Label(sbr_ds, text="detection scope:").pack(side=tk.LEFT)
        ttk.Combobox(sbr_ds, textvariable=detection_scope_var, width=13, state='readonly',
                     values=('', 'exhaustive', 'windows_only')).pack(side=tk.LEFT, padx=1)
        ttk.Label(sbr_ds, text="doublet <s:").pack(side=tk.LEFT)
        ttk.Spinbox(sbr_ds, from_=0.5, to=60.0, increment=0.5, width=4,
                    textvariable=doublet_s_var).pack(side=tk.LEFT, padx=1)
        ttk.Checkbutton(sbr_ds, text="Lock FG", variable=fg_lock_var).pack(side=tk.LEFT, padx=6)
        sbr2 = ttk.Frame(sbf); sbr2.pack(fill=tk.X, padx=2, pady=1)
        ttk.Button(sbr2, text="Segment editor…",
                   command=lambda: _pf_run_safe("Segment editor", _segment_editor)).pack(side=tk.LEFT, expand=True, fill=tk.X, padx=1)
        ttk.Button(sbr2, text="Run batch",
                   command=lambda: _pf_run_safe("Run batch", _run_batch_smart)).pack(side=tk.LEFT, expand=True, fill=tk.X, padx=1)
        ttk.Button(sbr2, text="Analyze on ROOT",
                   command=lambda: _pf_run_safe("Analyze on ROOT", _analyze_on_root)).pack(side=tk.LEFT, expand=True, fill=tk.X, padx=1)
        sbr3 = ttk.Frame(sbf); sbr3.pack(fill=tk.X, padx=2, pady=1)
        ttk.Button(sbr3, text="Self-test (batch)",
                   command=lambda: _pf_run_safe("Segment batch self-test", _self_test_segment_batch)).pack(side=tk.LEFT, expand=True, fill=tk.X, padx=1)
        # Profile lock: while a batch RESULT exists and Lock is on, changing any processing
        # widget is refused (reverted to the locked snapshot) so the ~10 repeats stay identical.
        _lockmap = dict(N=bk_npts_var, band=bk_band_var, diff=bk_diff_mode_var, pos=bk_pos_est_var,
                        fit=bk_fit_var, min_prom=bk_min_prom_var, min_r2=bk_min_r2_var,
                        min_gated=bk_min_gated_var, diam_len_px=seg_diam_len_var,
                        diam_frac=seg_diam_frac_var)
        _lock_reent = {'b': False}
        def _seg_update_hash():
            try: prof_hash_var.set(_profile_hash(_seg_profile()))
            except Exception: pass
        def _on_bk_change(*_a):
            if _lock_reent['b']: return
            lp = state.get('_seg_locked_profile')
            if seg_lock_var.get() and lp is not None and state.get('_seg_batch'):
                _lock_reent['b'] = True
                try:
                    for kk, vv in _lockmap.items():
                        if kk in lp:
                            try: vv.set(lp[kk])
                            except Exception: pass
                finally:
                    _lock_reent['b'] = False
                messagebox.showwarning("Profile locked",
                    "A batch result exists and the profile is locked. Untick 'Lock profile' (or run a "
                    "fresh batch) before changing processing parameters — the ~10 intervals must be "
                    "processed identically.")
            _seg_update_hash()
        for _v in _lockmap.values():
            _v.trace_add('write', _on_bk_change)
        pw.after(900, _seg_update_hash)

        # ── Lymphatic Pulse Batch (recon-style centerline workflow) ───────
        # Interprets the shared FG line ROI as the lymphatic centerline
        # (proximal -> distal) and runs the headless
        # `run_lymphatic_pulse_batch_core` on the LINEAR (optionally
        # drift-corrected) stack. Additive — existing analyses untouched.
        lymph_frame = ttk.LabelFrame(tab_ana, text="Lymphatic Pulse Batch")
        lymph_frame.pack(fill=tk.X, padx=3, pady=3)
        lymph_cycle_mode = tk.StringVar(value='file_boundary')
        lymph_use_bg_var = tk.BooleanVar(value=True)
        lymph_diam_var   = tk.BooleanVar(value=True)
        lcr = ttk.Frame(lymph_frame); lcr.pack(fill=tk.X, padx=2)
        ttk.Label(lcr, text="cycles:").pack(side=tk.LEFT)
        ttk.Combobox(lcr, textvariable=lymph_cycle_mode, width=13, state='readonly',
                     values=('file_boundary', 'auto_peaks')).pack(side=tk.LEFT, padx=2)
        ttk.Checkbutton(lymph_frame, text="Background-correct (use BG ROI)",
                        variable=lymph_use_bg_var).pack(fill=tk.X, padx=2)
        ttk.Checkbutton(lymph_frame, text="Diameter kymograph (FWHM)",
                        variable=lymph_diam_var).pack(fill=tk.X, padx=2)
        ttk.Button(lymph_frame, text="Run Lymphatic Pulse Batch Analysis",
                   command=lambda: _run_lymph_batch()).pack(fill=tk.X, padx=2, pady=1)
        ttk.Button(lymph_frame, text="Save Batch Data (CSV/NPZ/JSON)",
                   command=lambda: _save_lymph_batch()).pack(fill=tk.X, padx=2, pady=1)
        ttk.Button(lymph_frame, text="Nature Main Figure — Lymphatic Batch",
                   command=lambda: _fig_lymph_batch()).pack(fill=tk.X, padx=2, pady=1)

        status_v = tk.StringVar(value="Ready")
        ttk.Label(pw, textvariable=status_v, relief=tk.SUNKEN).pack(fill=tk.X, padx=3, pady=1)

        # ── Helper: expanded line ROI ──
        def _expand_line(pts, width):
            if pts is None or len(pts) < 2: return None
            hw = width // 2
            upper, lower = [], []
            for i in range(len(pts)-1):
                dx = pts[i+1][0]-pts[i][0]; dy = pts[i+1][1]-pts[i][1]
                L = np.sqrt(dx**2+dy**2)
                if L == 0: continue
                nx, ny = -dy/L*hw, dx/L*hw
                upper.append([int(pts[i][0]+nx), int(pts[i][1]+ny)])
                lower.append([int(pts[i][0]-nx), int(pts[i][1]-ny)])
            if not upper: return None
            upper.append([int(pts[-1][0]+nx), int(pts[-1][1]+ny)])
            lower.append([int(pts[-1][0]-nx), int(pts[-1][1]-ny)])
            return np.array(upper+lower[::-1], dtype=np.int32)

        # ── File loading ──
        def _load_files():
            """Load multiple TIF/RAW files and concatenate into one video.
            Select up to 11 files — they'll be joined in the order selected."""
            import tifffile

            paths = filedialog.askopenfilenames(
                title="Select TIF files to concatenate (select multiple, in order)",
                filetypes=[("TIF","*.tif *.tiff"),("RAW","*.raw"),("All","*.*")])
            if not paths: return

            n = len(paths)
            if n > 11:
                messagebox.showwarning("Warning", f"Selected {n} files. Max 11. Using first 11.")
                paths = paths[:11]
                n = 11

            status_v.set(f"Loading {n} files...")
            pw.update_idletasks()

            # Show file list in log
            self._log(f"\n{'='*40}")
            self._log(f"Loading {n} files for concatenation:")
            for i, p in enumerate(paths):
                self._log(f"  [{i+1}] {os.path.basename(p)}")

            stacks = []
            bounds = [0]
            total_frames = 0

            with _Progress("Loading files", total=n) as _p:
                for i, p in enumerate(paths):
                    _p.step(i, note=os.path.basename(p))
                    self._log(f"Loading {i+1}/{n}: {os.path.basename(p)}...")
                    try:
                        if p.lower().endswith('.raw'):
                            from slim_recon import data_io
                            im = data_io.load_raw(p)
                            # im is (H, W, T) — transpose to (T, H, W)
                            s = im.transpose(2, 0, 1).astype(np.float32)
                        elif p.lower().endswith(('.tif', '.tiff')):
                            # Use tifffile for fast loading
                            s = tifffile.imread(p).astype(np.float32)
                            if s.ndim == 2:
                                s = s[np.newaxis]  # single frame
                            elif s.ndim == 3:
                                # Could be (T,H,W) or (H,W,C)
                                if s.shape[2] <= 4 and s.shape[0] > s.shape[2]:
                                    # (T, H, W) — correct
                                    pass
                                elif s.shape[0] <= 4:
                                    # (C, H, W) — convert to grayscale
                                    s = np.mean(s, axis=0)[np.newaxis]
                            if s.ndim == 4:
                                # (T, H, W, C) — convert to grayscale
                                s = np.mean(s, axis=3)
                        else:
                            # Fallback: PIL
                            img = Image.open(p)
                            frames = []
                            try:
                                while True:
                                    f = np.array(img, dtype=np.float32)
                                    if f.ndim == 3: f = np.mean(f, axis=2)
                                    frames.append(f)
                                    img.seek(img.tell()+1)
                            except EOFError:
                                pass
                            s = np.array(frames)

                        stacks.append(s)
                        bounds.append(bounds[-1] + s.shape[0])
                        total_frames += s.shape[0]
                        self._log(f"  -> {s.shape[0]} frames, shape {s.shape[1:]}")

                    except Exception as e:
                        self._log(f"  ERROR loading {p}: {e}")
                        messagebox.showerror("Error", f"Load failed:\n{p}\n{e}")
                        return
                _p.step(n)

            # Check dimensions match
            shapes = set(s.shape[1:] for s in stacks)
            if len(shapes) > 1:
                self._log(f"ERROR: mismatched dimensions: {shapes}")
                messagebox.showerror("Error",
                    f"Files have different spatial dimensions:\n{shapes}\n"
                    f"All files must have the same height and width.")
                return

            # Concatenate
            state['stack'] = np.concatenate(stacks, axis=0)
            state['files'] = list(paths)
            state['boundaries'] = bounds
            T = state['stack'].shape[0]
            # ── install the frame-provenance contract: this concatenation IS the ROOT ──
            state['stack_orig'] = None
            state['root'] = dict(files=list(paths), boundaries=list(bounds), T=int(T),
                                 fps=float(fps_var.get()), px_um=float(px_var.get()))
            state['provenance'] = [dict(level=0, parent_uid=None, n_in=int(T), n_out=int(T),
                                        segments=[], note='load_files (root)')]
            state['photo'] = None                              # a fresh ROOT: no prior photometry
            _on_stack_changed(make_root_map(T), root=state['root'], boundaries=bounds,
                              note='load_files', remap=True, carry=False)
            frame_scale.configure(to=T-1)
            frame_var.set(0); state['current_frame'] = 0
            frame_lbl.config(text=f"0/{T-1}")
            file_info.set(f"{n} files, {T} total frames, {state['stack'].shape[1]}x{state['stack'].shape[2]}")

            # Update file list display
            file_listbox.delete(0, tk.END)
            for i, p in enumerate(paths):
                nf = stacks[i].shape[0]
                f0 = bounds[i]
                f1 = bounds[i+1] - 1
                file_listbox.insert(tk.END, f"[{i+1}] {os.path.basename(p)} "
                                     f"({nf}f, frames {f0}-{f1})")

            self._log(f"\nConcatenated: {n} files -> {T} total frames")
            self._log(f"File boundaries: {bounds}")
            self._log(f"[load] {state['stack'].shape} {state['stack'].dtype} "
                      f"{state['stack'].nbytes/1e9:.2f} GB")

            # Recall ROIs
            key = "|".join(paths)
            if key in roi_db:
                e = roi_db[key]
                # store plain lists so both writers (canvas handler + this loader) agree on type
                if 'fg' in e: state['fg_roi'] = np.array(e['fg'], np.int32).tolist()
                if 'bg1' in e: state['bg_roi_1'] = np.array(e['bg1'], np.int32).tolist()
                if 'bg2' in e: state['bg_roi_2'] = np.array(e['bg2'], np.int32).tolist()

            _display()
            status_v.set(f"Loaded {n} files, {T} total frames — ready for analysis")

        # ── Display ──
        def _corrected_frame(t):
            """Return frame t, optionally warped by -d[t] so the ANATOMY sits at the anchor
            position. 'track' mode never warps the stack, so the viewer must warp the single
            displayed frame — otherwise the user sees drift and concludes demotion failed."""
            fr = state['stack'][t]
            d = _disp()
            if bool(disp_corrected_var.get()) and d is not None and t < len(d):
                from scipy.ndimage import shift as ndshift
                fr = ndshift(np.asarray(fr, np.float32),
                             (-float(d[t, 0]), -float(d[t, 1])), order=1, mode='nearest')
            fr = np.asarray(fr, np.float32)
            if bool(disp_photo_var.get()) and state.get('photo') is not None:
                fr = _photo_map_frame(fr, t)                # LUT into reference units: no brightness jump
            return fr

        def _goto(t):
            if state['stack'] is None: return
            T = state['stack'].shape[0]
            t = int(np.clip(t, 0, T - 1))
            state['current_frame'] = t; frame_var.set(t)
            frame_lbl.config(text=f"{t}/{T-1}")
            _display()

        def _step(n): _goto(state['current_frame'] + int(n))

        def _add_cycle_mark():
            state.setdefault('cycle_marks', [])
            cm = sorted(set(list(state['cycle_marks']) + [int(state['current_frame'])]))
            state['cycle_marks'] = cm
            marker_lbl.set(f"cycle marks ({len(cm)}): {cm[:12]}{'…' if len(cm) > 12 else ''}")
            self._log(f"[nav] cycle marks = {cm}")

        def _clear_cycle_marks():
            state['cycle_marks'] = []
            marker_lbl.set("Markers: none")

        def _display():
            if state['stack'] is None: return
            T = state['stack'].shape[0]
            t = int(state['current_frame'])
            frame = _corrected_frame(t)
            mn, mx = min_v.get(), max_v.get()
            if bool(disp_fixedrange_var.get()):
                if state.get('_disp_range') is None:
                    _si = np.linspace(0, T-1, min(T, 120)).astype(int)
                    _md = np.median(np.stack([np.asarray(state['stack'][i], np.float32)
                                              for i in _si], 0), 0)
                    state['_disp_range'] = tuple(np.percentile(_md, (1.0, 99.5)))
                _lo, _hi = state['_disp_range']
                fd = np.clip((np.asarray(frame, np.float32) - _lo) / (_hi - _lo + 1e-8), 0, 1)
            else:
                fmax = frame.max()
                fd = frame / fmax if fmax > 0 else frame
            fd = np.clip(fd, mn, mx)
            fd = ((fd-mn)/(mx-mn+1e-8)*255).astype(np.uint8)
            disp = cv2.cvtColor(fd, cv2.COLOR_GRAY2RGB) if fd.ndim == 2 else fd

            overlay = disp.copy()
            for roi, color in [(state['bg_roi_1'], (0,255,0)),
                                (state['bg_roi_2'], (0,200,100)),
                                (state['fg_roi'], (255,50,50))]:
                if roi is not None and len(roi) >= 2:
                    w = bg_w.get() if color[0] == 0 else fg_w.get()
                    exp = _expand_line(roi, w)
                    if exp is not None: cv2.fillPoly(overlay, [exp], color)
                    for j in range(len(roi)-1):
                        cv2.line(overlay, tuple(roi[j]), tuple(roi[j+1]), color, 2)
            disp = cv2.addWeighted(overlay, 0.3, disp, 0.7, 0)

            # When NOT showing the corrected frame but drift exists, draw the ROI
            # translated by +d[t] so the user sees where sampling actually happens.
            d = _disp()
            if d is not None and t < len(d) and not bool(disp_corrected_var.get()):
                _dy = int(round(float(d[t, 0]))); _dx = int(round(float(d[t, 1])))
                for roi, color in [(state['fg_roi'], (255,180,0)), (state['bg_roi_1'], (0,255,255))]:
                    if roi is not None and len(roi) >= 2:
                        pts = np.asarray(roi, int) + np.array([_dx, _dy])
                        for j in range(len(pts)-1):
                            cv2.line(disp, tuple(pts[j]), tuple(pts[j+1]), color, 1)

            for bi in state['boundaries'][1:-1]:
                if state['current_frame'] in (bi, bi-1):
                    cv2.putText(disp, "| FILE BOUNDARY |", (10,30),
                                cv2.FONT_HERSHEY_SIMPLEX, 0.7, (255,255,0), 2)

            # HUD line
            fps = float(fps_var.get()); m = state.get('drift'); cyc = '-'
            for _kk, _cw in enumerate(state.get('_cyc_windows') or []):
                if _cw['t0'] <= t < _cw['t1']: cyc = _kk; break
            bolus_here = bool(m is not None and m.get('bolus') is not None
                              and t < len(m['bolus']) and m['bolus'][t])
            hud = (f"f {t}/{T-1}  t={t/max(fps,1e-9):.2f}s  cycle #{cyc}"
                   + ("  BOLUS" if bolus_here else ""))
            cv2.putText(disp, hud, (8, disp.shape[0]-10),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255,255,0), 1)

            pil = Image.fromarray(disp)
            z = state['zoom']
            if z != 1.0:
                pil = pil.resize((int(pil.width*z), int(pil.height*z)), Image.LANCZOS)
            tk_img_ref[0] = ImageTk.PhotoImage(pil)
            canvas.delete("all")
            canvas.create_image(0, 0, anchor=tk.NW, image=tk_img_ref[0])

        def _on_frame(v):
            state['current_frame'] = int(float(v))
            T = state['stack'].shape[0] if state['stack'] is not None else 0
            frame_lbl.config(text=f"{state['current_frame']}/{T-1}")
            _display()

        def _set_marker(which):
            if which == 'start': state['start_marker'] = state['current_frame']
            else: state['end_marker'] = state['current_frame']
            s = state['start_marker'] if state['start_marker'] is not None else '?'
            e = state['end_marker'] if state['end_marker'] is not None else '?'
            marker_lbl.set(f"[{s} - {e}]")
            _save_settings()

        def _get_range():
            if state['stack'] is None: return 0, 0
            T = state['stack'].shape[0]
            s = state['start_marker'] if state['start_marker'] is not None else 0
            e = state['end_marker'] if state['end_marker'] is not None else T-1
            return max(0,min(s,T-1)), max(s,min(e,T-1))

        # ── Progress / ETA / Cancel ────────────────────────────────────────
        class _Cancelled(Exception):
            """Raised inside a long loop when the user clicks Cancel."""
            pass

        _prog_stack = []

        def _fmt_hms(sec):
            if not np.isfinite(sec): return "—"
            sec = max(0.0, float(sec))
            h = int(sec // 3600); m = int((sec % 3600) // 60); s = int(sec % 60)
            return f"{h}:{m:02d}:{s:02d}" if h else f"{m:d}:{s:02d}"

        class _Progress:
            """Modal progress window with percent, elapsed, ETA, throughput and Cancel.

            Uses win.update() (NOT update_idletasks) so the Cancel button actually receives
            clicks. grab_set() makes it modal, preventing re-entrant analysis runs.
            Nested instances reuse the outermost window (no window stacking) but still honour
            Cancel. Updates are throttled to `min_interval` seconds so step() is cheap enough
            to call every iteration.
            """
            def __init__(self, title, total=None, min_interval=0.12):
                self.title = title
                self.total = int(total) if total else None
                self.min_interval = float(min_interval)
                self.t0 = time.perf_counter(); self.last = 0.0
                self._cancel = False; self.win = None
                self.elapsed = 0.0
                self.nested = len(_prog_stack) > 0

            def __enter__(self):
                _prog_stack.append(self)
                if self.nested: return self
                self.win = tk.Toplevel(pw); self.win.title(self.title)
                self.win.geometry("470x160"); self.win.transient(pw); self.win.resizable(False, False)
                self.win.protocol("WM_DELETE_WINDOW", self._on_cancel)
                ttk.Label(self.win, text=self.title,
                          font=('Segoe UI', 10, 'bold')).pack(pady=(12, 4))
                self.bar = ttk.Progressbar(
                    self.win, length=430, maximum=100,
                    mode=('determinate' if self.total else 'indeterminate'))
                self.bar.pack(padx=18, pady=4)
                if not self.total: self.bar.start(12)
                self.lbl = ttk.Label(self.win, text="starting…"); self.lbl.pack(pady=2)
                self.eta = ttk.Label(self.win, text="", foreground='#555'); self.eta.pack(pady=1)
                ttk.Button(self.win, text="Cancel", command=self._on_cancel).pack(pady=8)
                try: self.win.grab_set()
                except Exception: pass
                self.win.update()
                return self

            def _on_cancel(self):
                top = _prog_stack[0] if _prog_stack else self
                top._cancel = True
                try: top.lbl.config(text="cancelling…")
                except Exception: pass

            @property
            def cancelled(self):
                return (_prog_stack[0]._cancel if _prog_stack else self._cancel)

            def step(self, done, note=""):
                if self.cancelled: raise _Cancelled(self.title)
                if self.nested or self.win is None: return
                now = time.perf_counter()
                final = (self.total is not None and done >= self.total)
                if (now - self.last) < self.min_interval and not final: return
                self.last = now
                el = now - self.t0
                if self.total:
                    frac = min(1.0, done / max(1, self.total))
                    self.bar['value'] = 100.0 * frac
                    rate = (done / el) if (el > 1e-6 and done > 0) else 0.0
                    eta = ((self.total - done) / rate) if rate > 0 else float('nan')
                    self.lbl.config(text=f"{done:,} / {self.total:,}   ({100*frac:.1f}%)   {note}")
                    self.eta.config(text=f"elapsed {_fmt_hms(el)}    ETA {_fmt_hms(eta)}"
                                         f"    {rate:,.0f}/s")
                else:
                    self.lbl.config(text=note or "working…")
                    self.eta.config(text=f"elapsed {_fmt_hms(el)}")
                try: self.win.update()
                except tk.TclError: pass

            def __exit__(self, et, ev, tb):
                self.elapsed = time.perf_counter() - self.t0
                if _prog_stack and _prog_stack[-1] is self: _prog_stack.pop()
                if self.win is not None:
                    try:
                        if not self.total: self.bar.stop()
                        self.win.grab_release()
                    except Exception: pass
                    try: self.win.destroy()
                    except Exception: pass
                return False

        def _probe_eta(n_probe, total, fn_one, label):
            """Time `n_probe` iterations to predict total runtime; ask the user before
            committing to anything longer than 10 minutes. Returns True to proceed."""
            t = time.perf_counter()
            for i in range(int(n_probe)): fn_one(i)
            per = (time.perf_counter() - t) / max(1, int(n_probe))
            est = per * int(total)
            self._log(f"[{label}] probe: {per*1e3:.1f} ms/frame -> estimated {_fmt_hms(est)} "
                      f"for {int(total):,} frames")
            if est > 600:
                return messagebox.askokcancel(
                    label, f"Estimated runtime: {_fmt_hms(est)} for {int(total):,} frames.\n"
                           f"({per*1e3:.1f} ms/frame)\n\nProceed?")
            return True

        def _pf_run_safe(name, fn, *args, **kwargs):
            import traceback as _tb
            _t0 = time.perf_counter()
            try:
                out = fn(*args, **kwargs)
                el = time.perf_counter() - _t0
                self._log(f"[PulseFlow:{name}] done in {_fmt_hms(el)} ({el:.2f} s)")
                try: status_v.set(f"{name}: done in {_fmt_hms(el)}")
                except Exception: pass
                return out
            except _Cancelled:
                el = time.perf_counter() - _t0
                self._log(f"[PulseFlow:{name}] CANCELLED after {_fmt_hms(el)}")
                try: status_v.set(f"{name}: cancelled after {_fmt_hms(el)}")
                except Exception: pass
                return None
            except Exception as _e:
                el = time.perf_counter() - _t0
                self._log(f"[PulseFlow:{name}] FAILED after {_fmt_hms(el)}:\n{_tb.format_exc()}")
                try: status_v.set(f"{name} FAILED: {type(_e).__name__}: {_e}"[:180])
                except Exception: pass
                messagebox.showerror(name, f"{type(_e).__name__}: {_e}\n\nSee Log for full traceback.")
                return None

        # ── ROI drawing ──
        def _start_draw(mode):
            state['drawing_mode'] = mode
            state['temp_points'] = []
            status_v.set(f"Draw {mode.upper()} — click points, double-click finish")

        def _clear_rois():
            state['fg_roi'] = state['bg_roi_1'] = state['bg_roi_2'] = None
            _display()

        def _canvas_click(event):
            if state['drawing_mode'] is None: return
            x = int(event.x / state['zoom'])
            y = int(event.y / state['zoom'])
            state['temp_points'].append([x, y])
            _display()
            if len(state['temp_points']) >= 2:
                for i in range(len(state['temp_points'])-1):
                    p1, p2 = state['temp_points'][i], state['temp_points'][i+1]
                    canvas.create_line(p1[0]*state['zoom'], p1[1]*state['zoom'],
                                        p2[0]*state['zoom'], p2[1]*state['zoom'],
                                        fill='yellow', width=2)

        def _canvas_dblclick(event):
            if state['drawing_mode'] is None or len(state['temp_points']) < 2: return
            pts = np.array(state['temp_points'], dtype=np.int32)
            m = state['drawing_mode']
            if m == 'bg1': state['bg_roi_1'] = pts
            elif m == 'bg2': state['bg_roi_2'] = pts
            elif m == 'fg':
                # ONE FG must be valid across all segments (unified by demotion). Refuse an FG edit
                # while a locked batch exists — a different FG line samples different anatomy.
                if bool(fg_lock_var.get()) and state.get('segments') and \
                   any(s.get('result') for s in state['segments']):
                    state['drawing_mode'] = None; state['temp_points'] = []
                    messagebox.showwarning("FG locked",
                        "The FG line is LOCKED because a batch result exists. A different FG samples "
                        "different anatomy across the 866 s of root time. Clear the segment results "
                        "(or untick 'Lock FG') before editing the FG.")
                    _display(); return
                state['fg_roi'] = pts
            state['drawing_mode'] = None; state['temp_points'] = []
            _save_settings(); _display()
            status_v.set("ROI saved")

        def _canvas_wheel(event):
            state['zoom'] *= 1.1 if event.delta > 0 else 1/1.1
            state['zoom'] = max(0.1, min(10, state['zoom']))
            _display()

        canvas.bind('<Button-1>', _canvas_click)
        canvas.bind('<Double-Button-1>', _canvas_dblclick)
        canvas.bind('<MouseWheel>', _canvas_wheel)

        # ── Signal extraction ──
        def _extract():
            stk = state['stack']
            if stk is None or state['fg_roi'] is None or state['bg_roi_1'] is None:
                return None, None
            s, e = _get_range()
            H, W = stk.shape[1], stk.shape[2]
            fg_mask = np.zeros((H,W), dtype=np.uint8)
            exp = _expand_line(state['fg_roi'], fg_w.get())
            if exp is not None: cv2.fillPoly(fg_mask, [exp], 1)
            bg_mask = np.zeros((H,W), dtype=np.uint8)
            for bg in [state['bg_roi_1'], state['bg_roi_2']]:
                if bg is not None:
                    exp = _expand_line(bg, bg_w.get())
                    if exp is not None: cv2.fillPoly(bg_mask, [exp], 1)
            fg_px, bg_px = fg_mask>0, bg_mask>0
            if fg_px.sum()==0 or bg_px.sum()==0: return None, None
            nf = e-s+1
            fg_sig = np.zeros(nf); bg_sig = np.zeros(nf)
            _photo = state.get('photo') is not None
            with _Progress("Extracting signal", total=nf) as _p:
                for i, fi in enumerate(range(s, e+1)):
                    _p.step(i + 1)
                    if fi >= len(stk): break
                    f = stk[fi]
                    if f.ndim == 3: f = np.mean(f, axis=2)
                    fgv = f[fg_px]; bgv = f[bg_px]
                    if _photo:
                        fgv = _photo_map_px(fgv, fi); bgv = _photo_map_px(bgv, fi)
                    fg_sig[i] = np.mean(fgv); bg_sig[i] = np.mean(bgv)
            return fg_sig, bg_sig

        # ── Per-file ROI storage ──
        # Dict: file_index -> {'fg': np.array, 'bg1': np.array, 'bg2': np.array}
        per_file_rois = {}

        def _setup_per_file_rois():
            """Interactive per-file ROI setup in a SINGLE persistent window.
            Double-click = save current ROI + advance to next.
            Flow: FG file1 → FG file2 → ... → BG1 file1 → ... → BG2 file1 → ...
            Previous file's ROI shown as cyan reference."""
            if state['stack'] is None or len(state['files']) == 0:
                messagebox.showwarning("Warning", "Load files first")
                return

            n_files = len(state['files'])
            bounds = state['boundaries']

            # State: FG per-file, then BG1 once, BG2 once
            roi_state = {
                'phase': 0,        # 0=FG (per file), 1=BG1 (once), 2=BG2 (once)
                'file_idx': 0,
                'temp_pts': [],
                'done': False,
            }
            phase_names = ['FG', 'BG1', 'BG2']
            phase_colors = ['red', 'green', 'lime']
            shared_bg = {'bg1': None, 'bg2': None}  # BG drawn once, shared

            def _get_frame(fi):
                f0 = bounds[fi]; f1 = bounds[fi + 1] - 1
                mid = (f0 + f1) // 2
                frame = state['stack'][mid]
                if frame.ndim == 3: frame = np.mean(frame, axis=2)
                vmin, vmax = np.percentile(frame, [1, 99.5])
                return np.clip((frame - vmin) / (vmax - vmin + 1e-8), 0, 1)

            # Create the persistent window
            roi_win = tk.Toplevel(pw)
            roi_win.title("Per-File ROI Setup")
            roi_win.geometry("900x900")

            top_info = tk.StringVar(value="")
            ttk.Label(roi_win, textvariable=top_info, font=('TkDefaultFont', 10),
                       wraplength=850).pack(fill=tk.X, padx=5, pady=3)

            roi_canvas = tk.Canvas(roi_win, bg='black')
            roi_canvas.pack(fill=tk.BOTH, expand=True)
            roi_tk_img = [None]

            def _redraw():
                fi = roi_state['file_idx']
                phase = roi_state['phase']
                disp = _get_frame(fi)
                H, W = disp.shape

                # Convert to RGB for overlays
                rgb = np.stack([disp, disp, disp], axis=-1)
                rgb = (np.clip(rgb, 0, 1) * 255).astype(np.uint8)
                overlay = rgb.copy()

                pname = phase_names[phase]
                fname = os.path.basename(state['files'][fi])

                # Draw previous file's ROIs as cyan reference
                if fi > 0 and (fi - 1) in per_file_rois:
                    prev = per_file_rois[fi - 1]
                    for rk, clr in [('fg', (0, 255, 255)), ('bg1', (255, 0, 255)),
                                     ('bg2', (200, 0, 200))]:
                        r = prev.get(rk)
                        if r is not None and len(r) >= 2:
                            for j in range(len(r) - 1):
                                cv2.line(overlay, tuple(r[j]), tuple(r[j+1]), clr, 1,
                                          lineType=cv2.LINE_AA)

                # Draw already-saved ROIs for this file
                if fi in per_file_rois:
                    cur = per_file_rois[fi]
                    for rk, clr in [('fg', (255, 50, 50)), ('bg1', (50, 255, 50)),
                                     ('bg2', (50, 200, 50))]:
                        r = cur.get(rk)
                        if r is not None and len(r) >= 2:
                            for j in range(len(r) - 1):
                                cv2.line(overlay, tuple(r[j]), tuple(r[j+1]), clr, 2,
                                          lineType=cv2.LINE_AA)

                # Draw current temp points
                pts = roi_state['temp_pts']
                pc = {'FG': (255, 80, 80), 'BG1': (80, 255, 80), 'BG2': (80, 200, 80)}[pname]
                if len(pts) >= 2:
                    for j in range(len(pts) - 1):
                        cv2.line(overlay, tuple(pts[j]), tuple(pts[j+1]), pc, 2,
                                  lineType=cv2.LINE_AA)
                for p in pts:
                    cv2.circle(overlay, tuple(p), 3, (255, 255, 0), -1)

                rgb_blend = cv2.addWeighted(overlay, 0.5, rgb, 0.5, 0)

                pil = Image.fromarray(rgb_blend)
                # Scale to fit canvas
                cw = roi_canvas.winfo_width() or 800
                ch = roi_canvas.winfo_height() or 800
                scale = min(cw / W, ch / H, 2.0)
                if scale != 1.0:
                    pil = pil.resize((int(W * scale), int(H * scale)), Image.LANCZOS)

                roi_tk_img[0] = ImageTk.PhotoImage(pil)
                roi_canvas.delete("all")
                roi_canvas.create_image(0, 0, anchor=tk.NW, image=roi_tk_img[0])

                if phase == 0:
                    info = (f"FG — File {fi+1}/{n_files}: {fname}  |  "
                            f"Points: {len(pts)}  |  "
                            f"Click points, Dbl-click = SAVE & next file  |  "
                            f"Cyan = prev file")
                elif phase == 1:
                    info = (f"BG1 (shared, drawn once) — on File 1  |  "
                            f"Points: {len(pts)}  |  "
                            f"Click points, Dbl-click = SAVE & next  |  "
                            f"Red = FG")
                else:
                    info = (f"BG2 (shared, drawn once) — on File 1  |  "
                            f"Points: {len(pts)}  |  "
                            f"Click points, Dbl-click = SAVE & RUN ANALYSIS")
                top_info.set(info)

            def _on_click(event):
                if roi_state['done']:
                    return
                fi = roi_state['file_idx']
                disp = _get_frame(fi)
                H, W = disp.shape
                cw = roi_canvas.winfo_width() or 800
                ch = roi_canvas.winfo_height() or 800
                scale = min(cw / W, ch / H, 2.0)
                x = int(event.x / scale)
                y = int(event.y / scale)
                x = max(0, min(W - 1, x))
                y = max(0, min(H - 1, y))
                roi_state['temp_pts'].append([x, y])
                _redraw()

            def _on_dblclick(event):
                if roi_state['done']:
                    return
                fi = roi_state['file_idx']
                phase = roi_state['phase']
                pname = phase_names[phase]

                pts = roi_state['temp_pts']
                pts_arr = None
                if len(pts) >= 2:
                    pts_arr = np.array(pts, dtype=np.int32)

                if phase == 0:
                    # FG — per file
                    if pts_arr is not None:
                        if fi not in per_file_rois:
                            per_file_rois[fi] = {}
                        per_file_rois[fi]['fg'] = pts_arr
                        self._log(f"  FG file {fi+1}: {len(pts_arr)} pts")
                    elif fi > 0 and (fi - 1) in per_file_rois:
                        if fi not in per_file_rois:
                            per_file_rois[fi] = {}
                        prev = per_file_rois[fi - 1].get('fg')
                        if prev is not None:
                            per_file_rois[fi]['fg'] = prev.copy()
                            self._log(f"  FG file {fi+1}: reused prev")

                    roi_state['temp_pts'] = []
                    roi_state['file_idx'] += 1

                    if roi_state['file_idx'] >= n_files:
                        # FG done for all files — move to BG1 (once)
                        roi_state['phase'] = 1
                        roi_state['file_idx'] = 0
                        self._log("  FG done for all files. Now draw BG1 (once, shared).")

                elif phase == 1:
                    # BG1 — once, shared across all files
                    if pts_arr is not None:
                        shared_bg['bg1'] = pts_arr
                        self._log(f"  BG1 (shared): {len(pts_arr)} pts")
                    roi_state['temp_pts'] = []
                    roi_state['phase'] = 2
                    self._log("  Now draw BG2 (once, shared).")

                elif phase == 2:
                    # BG2 — once, shared
                    if pts_arr is not None:
                        shared_bg['bg2'] = pts_arr
                        self._log(f"  BG2 (shared): {len(pts_arr)} pts")
                    roi_state['temp_pts'] = []

                    # Apply shared BG to all files
                    for fi_a in range(n_files):
                        if fi_a not in per_file_rois:
                            per_file_rois[fi_a] = {}
                        if shared_bg['bg1'] is not None:
                            per_file_rois[fi_a]['bg1'] = shared_bg['bg1']
                        if shared_bg['bg2'] is not None:
                            per_file_rois[fi_a]['bg2'] = shared_bg['bg2']

                    # All done — auto-run analysis
                    roi_state['done'] = True
                    top_info.set("All ROIs set! Running analysis...")
                    self._log(f"\n=== Per-file ROI setup complete ===")
                    for fi_s in sorted(per_file_rois):
                        r = per_file_rois[fi_s]
                        self._log(f"  File {fi_s+1}: "
                                   f"FG={len(r.get('fg',[]))}pts "
                                   f"BG={len(r.get('bg1',[]))}+{len(r.get('bg2',[]))}pts")
                    status_v.set("Extracting signals...")
                    roi_win.after(200, lambda: (pulse_scope_var.set('per file'), _pulse_analysis()))
                    return

                _redraw()

            roi_canvas.bind('<Button-1>', _on_click)
            roi_canvas.bind('<Double-Button-1>', _on_dblclick)

            # Initial draw after window is visible
            roi_win.after(100, _redraw)

        def _extract_per_file():
            """Extract signals using per-file ROIs. Returns concatenated diff signal."""
            stk = state['stack']
            if stk is None or len(per_file_rois) == 0:
                return None, None, None
            bounds = state['boundaries']
            n_files = len(state['files'])
            H, W = stk.shape[1], stk.shape[2]
            fw = fg_w.get(); bw = bg_w.get()

            all_fg = []; all_bg = []; file_tags = []
            total_T = stk.shape[0]
            processed = 0

            self._log("Extracting signals with per-file ROIs...")
            status_v.set("Extracting signals...")

            with _Progress("Extract per-file", total=bounds[-1]) as _p:
                for fi in range(n_files):
                    rois = per_file_rois.get(fi)
                    if rois is None:
                        rois = {'fg': state['fg_roi'], 'bg1': state['bg_roi_1'],
                                'bg2': state['bg_roi_2']}
                    fg_r = rois.get('fg')
                    if fg_r is None or (hasattr(fg_r, '__len__') and len(fg_r) < 2):
                        self._log(f"  File {fi+1}: skipped (no FG ROI)")
                        continue

                    f0, f1 = bounds[fi], bounds[fi + 1]

                    fg_mask = np.zeros((H, W), dtype=np.uint8)
                    exp = _expand_line(fg_r, fw)
                    if exp is not None: cv2.fillPoly(fg_mask, [exp], 1)

                    bg_mask = np.zeros((H, W), dtype=np.uint8)
                    for bg_key in ['bg1', 'bg2']:
                        bg = rois.get(bg_key)
                        if bg is not None and len(bg) >= 2:
                            exp = _expand_line(bg, bw)
                            if exp is not None: cv2.fillPoly(bg_mask, [exp], 1)

                    fg_px = fg_mask > 0
                    bg_px = bg_mask > 0
                    if fg_px.sum() == 0 or bg_px.sum() == 0:
                        self._log(f"  File {fi+1}: skipped (empty mask)")
                        continue

                    n_file_frames = f1 - f0
                    _bn = os.path.basename(state['files'][fi]) if fi < len(state['files']) else ""
                    self._log(f"  File {fi+1}/{n_files}: extracting {n_file_frames} frames...")
                    _photo = state.get('photo') is not None
                    for frame_idx in range(f0, f1):
                        if frame_idx >= len(stk): break
                        f = stk[frame_idx]
                        if f.ndim == 3: f = np.mean(f, axis=2)
                        fgv = f[fg_px]; bgv = f[bg_px]
                        if _photo:
                            fgv = _photo_map_px(fgv, frame_idx); bgv = _photo_map_px(bgv, frame_idx)
                        all_fg.append(np.mean(fgv))
                        all_bg.append(np.mean(bgv))
                        file_tags.append(fi)
                        processed += 1
                        _p.step(processed, note=_bn)

            self._log(f"  Extraction complete: {processed} frames total")
            status_v.set(f"Extracted {processed} frames — computing pulse analysis...")
            pw.update_idletasks()

            if not all_fg:
                return None, None, None
            return np.array(all_fg), np.array(all_bg), np.array(file_tags)

        def _run_pulse_on_signal(diff, file_tags=None):
            """Core pulse analysis on a difference signal."""
            fps = fps_var.get()
            n = len(diff)
            t_ax = np.arange(n) / fps

            if n > 7:
                diff_sm = savgol_filter(diff, min(7, n | 1), 3)
            else:
                diff_sm = diff.copy()
            hp = max(5, int(fps * 2))
            diff_hp = diff_sm - ndimage.uniform_filter1d(diff_sm, size=hp)

            peaks, _ = find_peaks(diff_hp, distance=max(3, int(fps * 0.3)),
                                   prominence=np.std(diff_hp) * 0.5)
            # discard peaks within G frames of any interior file boundary (transient/step artifact)
            _G = int(state.get('_bnd_guard', 0))
            _interior = [int(b) for b in (state.get('boundaries') or [])[1:-1]]
            if _G > 0 and _interior and len(peaks):
                _keep = np.array([min(abs(int(p) - b) for b in _interior) >= _G for p in peaks])
                _nd = int((~_keep).sum())
                if _nd:
                    self._log(f"[pulse] discarded {_nd} peak(s) within {_G} frames of a boundary")
                peaks = peaks[_keep]
            env = np.abs(hilbert(diff_hp))

            if len(peaks) >= 2:
                intervals = np.diff(peaks) / fps
                rates = 60.0 / intervals
                amps = diff_hp[peaks[:-1]]
                ptimes = t_ax[peaks[:-1]]
            else:
                intervals = rates = amps = ptimes = np.array([])

            w = tk.Toplevel(pw); w.title("Pulse Analysis (Per-File ROIs)")
            w.geometry("1200x800")
            fig = Figure(figsize=(11, 7), dpi=150, facecolor='white')
            axes = [fig.add_subplot(4, 1, i+1) for i in range(4)]

            # P1: signal + peaks + file boundaries
            axes[0].plot(t_ax, diff_hp, color='#2166ac', lw=0.5, alpha=0.6)
            axes[0].plot(t_ax, env, color='#2166ac', lw=1.0, label='Envelope')
            if len(peaks) > 0:
                axes[0].plot(t_ax[peaks], diff_hp[peaks], 'v', color='#d62728', ms=5,
                              label=f'Pulses ({len(peaks)})')
            # File boundaries (yellow line + grey guard band of width G)
            bounds = state.get('boundaries', [])
            _G = int(state.get('_bnd_guard', 0))
            for bi in bounds[1:-1]:
                bt = bi / fps
                if 0 <= bt <= t_ax[-1]:
                    axes[0].axvline(bt, color='#e0e040', lw=1, ls='--', alpha=0.7)
                    if _G > 0:
                        axes[0].axvspan((bi - _G) / fps, (bi + _G) / fps, color='0.6', alpha=0.18, lw=0)
            # Color-code by file
            if file_tags is not None:
                n_files = len(set(file_tags))
                colors = plt.cm.tab10(np.linspace(0, 1, max(n_files, 1)))
                for fi_u in sorted(set(file_tags)):
                    mask = file_tags == fi_u
                    axes[0].fill_between(t_ax, diff_hp.min(), diff_hp.max(),
                                          where=mask, alpha=0.05,
                                          color=colors[fi_u % len(colors)])
            axes[0].set_ylabel('Signal (HP)')
            axes[0].set_title(f'Pulse Detection — {len(peaks)} pulses '
                               f'(yellow lines = file boundaries)', fontweight='bold')
            axes[0].legend(fontsize=7)

            # P2-P4 same as before
            if len(rates) > 0:
                axes[1].plot(ptimes, rates, 'o-', color='#d62728', ms=3, lw=0.8)
                if len(rates) > 3:
                    z = np.polyfit(ptimes, rates, 1)
                    axes[1].plot(ptimes, np.polyval(z, ptimes), '--', color='#888', lw=1,
                                  label=f'Trend: {z[0]:+.2f} bpm/s')
                    axes[1].legend(fontsize=7)
            axes[1].set_ylabel('Rate (bpm)'); axes[1].set_title('Pulse Rate')

            if len(amps) > 0:
                axes[2].plot(ptimes, amps, 's-', color='#1b7837', ms=3, lw=0.8)
                if len(amps) > 3:
                    z = np.polyfit(ptimes, amps, 1)
                    axes[2].plot(ptimes, np.polyval(z, ptimes), '--', color='#888', lw=1,
                                  label=f'Trend: {z[0]:+.4f}/s')
                    axes[2].legend(fontsize=7)
            axes[2].set_ylabel('Amplitude'); axes[2].set_title('Pulse Amplitude')

            if len(intervals) > 0:
                axes[3].bar(range(len(intervals)), intervals * 1000, color='#8060c0')
                axes[3].axhline(np.mean(intervals) * 1000, color='#888', ls='--', lw=0.8,
                                 label=f'Mean: {np.mean(intervals)*1000:.0f}ms')
                axes[3].legend(fontsize=7)
            axes[3].set_ylabel('Interval (ms)'); axes[3].set_xlabel('Pulse #')
            axes[3].set_title('Inter-Pulse Intervals')

            for ax in axes:
                ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
                ax.tick_params(labelsize=7)
            fig.tight_layout()

            bot = ttk.Frame(w); bot.pack(fill=tk.X, padx=3, pady=2)
            def _sv():
                p = filedialog.asksaveasfilename(defaultextension=".pdf",
                    filetypes=[("PDF","*.pdf"),("PNG","*.png")])
                if p: fig.savefig(p, dpi=300, bbox_inches='tight')
            def _sd():
                p = filedialog.asksaveasfilename(defaultextension=".npz",
                    filetypes=[("NPZ","*.npz")])
                if p: np.savez(p, signal=diff_hp, envelope=env, peaks=peaks,
                               intervals=intervals, rates=rates, amps=amps,
                               time=t_ax, fps=fps, file_tags=file_tags)
            ttk.Button(bot, text="Save Fig", command=_sv).pack(side=tk.LEFT, padx=2)
            ttk.Button(bot, text="Save Data", command=_sd).pack(side=tk.LEFT, padx=2)
            c = FigureCanvasTkAgg(fig, w); c.draw(); c.get_tk_widget().pack(fill=tk.BOTH, expand=True)

            self._log(f"\nPULSE (per-file ROIs): {len(peaks)} pulses in {n/fps:.1f}s")
            if len(rates) > 0:
                self._log(f"  Rate: {np.mean(rates):.1f} bpm")
                if len(rates) > 3:
                    z = np.polyfit(ptimes, rates, 1)
                    self._log(f"  Trend: {z[0]:+.2f} bpm/s ({'slowing' if z[0]<0 else 'accel'})")

        # ── Smart extract: tries per-file first, falls back to shared ──
        def _smart_extract():
            """Try tracked ROI (drift), then per-file ROIs, then shared ROIs. Photometric
            harmonization (if state['photo'] is set) is applied to fg/bg before returning, so every
            downstream metric (diff signal, pulse analysis) sees a common photometric scale."""
            # Extractors already map pixel values into reference units (pixel-level, the only
            # correct path for nonlinear photometric models), so do NOT correct again here.
            if _tracking_on():
                fg, bg, tags = _extract_tracked()
                if fg is not None:
                    return fg, bg
            if len(per_file_rois) > 0:
                fg, bg, tags = _extract_per_file()
                if fg is not None:
                    return fg, bg
            fg, bg = _extract()
            return fg, bg

        # ── Diff signal ──
        def _diff_signal():
            status_v.set("Computing difference signal...")
            pw.update_idletasks()
            fg, bg = _smart_extract()
            if fg is None:
                messagebox.showwarning("Warning", "Draw ROIs first (shared or per-file)")
                return
            diff = fg - bg
            fps = fps_var.get()
            t = np.arange(len(diff)) / fps
            status_v.set("Plotting...")
            w = tk.Toplevel(pw); w.title("Difference Signal"); w.geometry("1000x400")
            fig = Figure(figsize=(9, 3), dpi=150, facecolor='white')
            ax = fig.add_subplot(111)
            ax.plot(t, diff, color='#2166ac', lw=0.7)
            # File boundaries
            bounds = state.get('boundaries', [])
            s0, _ = _get_range()
            for bi in bounds[1:-1]:
                bt = (bi - s0) / fps
                if 0 <= bt <= t[-1]:
                    ax.axvline(bt, color='#e0e040', lw=0.8, ls='--', alpha=0.6)
            ax.set_xlabel('Time (s)'); ax.set_ylabel('FG - BG')
            ax.set_title(f'Difference Signal ({len(diff)} frames)', fontweight='bold')
            ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
            fig.tight_layout()
            c = FigureCanvasTkAgg(fig, w); c.draw()
            c.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            def _sv():
                p = filedialog.asksaveasfilename(defaultextension=".pdf",
                    filetypes=[("PDF","*.pdf"),("PNG","*.png")])
                if p: fig.savefig(p, dpi=300, bbox_inches='tight')
            ttk.Button(w, text="Save", command=_sv).pack(pady=2)
            status_v.set(f"Diff signal: {len(diff)} frames")
            self._log(f"Diff signal plotted: {len(diff)} frames")

        # ── Kymography ──
        def _kymography():
            """Quick-look kymograph viewer. Mode (kymo_mode_var): intensity | diameter | difference."""
            mode = kymo_mode_var.get() if 'kymo_mode_var' in dir() else 'intensity'
            # Find FG ROI — try per-file (file 0) first, then shared
            roi = None
            if 0 in per_file_rois and per_file_rois[0].get('fg') is not None:
                roi = per_file_rois[0]['fg']
            elif state['fg_roi'] is not None:
                roi = state['fg_roi']
            if state['stack'] is None or roi is None:
                messagebox.showwarning("Warning", "Load + draw FG ROI first")
                return

            s, e = _get_range()
            stk = state['stack']; fps = fps_var.get()
            total_len = sum(np.sqrt((roi[i+1][0]-roi[i][0])**2 +
                                     (roi[i+1][1]-roi[i][1])**2)
                            for i in range(len(roi)-1))
            n_pos = max(1, int(total_len)); nf = e - s + 1

            status_v.set(f"Computing kymograph ({nf} frames)...")
            pw.update_idletasks()
            self._log(f"Kymograph: {n_pos} positions x {nf} frames...")

            kymo = np.zeros((nf, n_pos))
            for fi_i, fi in enumerate(range(s, e + 1)):
                if fi >= len(stk): break
                f = stk[fi]
                if f.ndim == 3: f = np.mean(f, axis=2)
                for pi in range(n_pos):
                    frac = pi / max(n_pos - 1, 1)
                    td = frac * total_len; cd = 0
                    cx, cy = roi[-1][0], roi[-1][1]
                    for si_r in range(len(roi) - 1):
                        dx = roi[si_r+1][0] - roi[si_r][0]
                        dy = roi[si_r+1][1] - roi[si_r][1]
                        sl = np.sqrt(dx**2 + dy**2)
                        if cd + sl >= td:
                            t_l = (td - cd) / (sl + 1e-8)
                            cx = int(roi[si_r][0] + t_l * dx)
                            cy = int(roi[si_r][1] + t_l * dy)
                            break
                        cd += sl
                    r = max(1, fg_w.get() // 2)
                    H, W = f.shape[:2]
                    patch = f[max(0, cy-r):min(H, cy+r+1), max(0, cx-r):min(W, cx+r+1)]
                    kymo[fi_i, pi] = np.mean(patch) if patch.size > 0 else 0

                if fi_i % 50 == 0:
                    pct = int(fi_i / nf * 100)
                    status_v.set(f"Kymograph: {fi_i}/{nf} frames ({pct}%)")
                    pw.update_idletasks()

            disp_kymo = kymo; cmap = 'gray'; mtitle = 'intensity'
            if mode == 'difference':
                disp_kymo = np.abs(np.diff(kymo, axis=0, prepend=kymo[:1])); cmap = 'magma'; mtitle = 'difference |dI/dt|'
            elif mode == 'diameter':
                # perpendicular FWHM per position/frame using the module kernels
                cc, tng, apx = _sample_along_polyline(np.asarray(roi, float), n_pos)
                diam = np.full((nf, n_pos), np.nan)
                for fi_i, fi in enumerate(range(s, e + 1)):
                    if fi >= len(stk): break
                    f = np.asarray(stk[fi], np.float32)
                    if f.ndim == 3: f = f.mean(axis=2)
                    for pi in range(n_pos):
                        prof = _perp_profile(f, cc[pi], tng[pi], max(11, int(fg_w.get()) * 3))
                        wpx = _fwhm_from_profile(prof, 0.5)
                        if wpx == wpx: diam[fi_i, pi] = wpx * px_var.get()
                disp_kymo = diam; cmap = 'viridis'; mtitle = 'diameter FWHM (um)'
            status_v.set("Plotting kymograph...")
            w = tk.Toplevel(pw); w.title(f"Kymograph ({mtitle})"); w.geometry("1100x600")
            fig = Figure(figsize=(10, 5), dpi=150, facecolor='white')
            ax = fig.add_subplot(111)
            ax.imshow(disp_kymo, aspect='auto', cmap=cmap,
                       extent=[0, total_len * px_var.get(), nf / fps, 0])
            ax.set_xlabel('Position (um)'); ax.set_ylabel('Time (s)')
            ax.set_title(f'Kymograph — {mtitle} ({nf} frames)', fontweight='bold')
            for bi in state.get('boundaries', []):
                if s <= bi <= e:
                    ax.axhline((bi - s) / fps, color='yellow', lw=0.5, ls='--', alpha=0.7)
            fig.tight_layout()
            c = FigureCanvasTkAgg(fig, w); c.draw()
            c.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            def _sv():
                p = filedialog.asksaveasfilename(defaultextension=".pdf",
                    filetypes=[("PDF","*.pdf"),("PNG","*.png"),("SVG","*.svg")])
                if p: fig.savefig(p, dpi=300, bbox_inches='tight')
            ttk.Button(w, text="Save", command=_sv).pack(pady=2)
            status_v.set(f"Kymograph done ({nf} frames)")
            self._log(f"Kymograph plotted: {n_pos}x{nf}")

        # ── Pulse analysis ──
        def _pulse_analysis():
            """Quick-look pulse metrics. Scope (pulse_scope_var): whole | per file | per segment."""
            scope = pulse_scope_var.get() if 'pulse_scope_var' in dir() else 'whole'
            if scope == 'per file':
                fg, bg, tags = _extract_per_file()
                if fg is None:
                    messagebox.showwarning("Pulse metrics",
                        "Set per-file ROIs first (or draw shared ROIs)."); return
                _run_pulse_on_signal(np.asarray(fg, float) - np.asarray(bg, float), tags); return
            if scope == 'per segment':
                segs = _seg_included()
                if not segs:
                    messagebox.showwarning("Pulse metrics", "No included segments — use the Segment editor."); return
                fg, bg = _smart_extract()
                if fg is None:
                    messagebox.showwarning("Pulse metrics", "Draw ROIs first."); return
                d = np.asarray(fg, float) - np.asarray(bg, float)
                s0, _e = _get_range()
                parts = []; tags = []
                for k, sg in enumerate(sorted(segs, key=lambda s: s['t0'])):
                    a = int(sg['t0']) - s0; b = int(sg['t1']) - s0
                    if 0 <= a < b <= len(d):
                        parts.append(d[a:b]); tags.extend([k] * (b - a))
                if not parts:
                    messagebox.showwarning("Pulse metrics", "Segments fall outside the extracted range."); return
                _run_pulse_on_signal(np.concatenate(parts), np.array(tags)); return
            status_v.set("Extracting signals for pulse analysis...")
            pw.update_idletasks()
            fg, bg = _smart_extract()
            if fg is None or bg is None:
                messagebox.showwarning("Pulse Analysis", "Draw ROIs first (shared or per-file)."); return
            fg = np.asarray(fg, float); bg = np.asarray(bg, float)
            if fg.size == 0 or fg.size != bg.size:
                messagebox.showwarning("Pulse Analysis",
                    "Extraction returned an EMPTY signal.\n\nLikely cause: per-file ROIs are set for "
                    "only some files — files without an FG ROI are skipped. Set an FG ROI for every "
                    "file, or Clear ROIs and use a single shared FG+BG ROI.")
                self._log("[Pulse Analysis] empty signal from _smart_extract (per-file ROIs incomplete?)")
                return
            diff = fg - bg; fps = fps_var.get(); n = len(diff)
            if n < 3:
                messagebox.showwarning("Pulse Analysis", f"Only {n} frames after extraction — need >= 3.")
                return
            if not np.all(np.isfinite(diff)):
                diff = np.nan_to_num(diff, nan=float(np.nanmean(diff)))
            self._log(f"Pulse analysis: {n} frames ({n/fps:.1f}s)")
            status_v.set(f"Analyzing {n} frames...")
            t_ax = np.arange(n)/fps
            t_end = float(t_ax[-1])          # define AFTER t_ax; use t_end everywhere instead of t_ax[-1]

            # Cardiac-tuned defaults (hp=2 s, savgol=7, prom=0.5, dist=0.3 s).
            # Behavior preserved by routing through the shared helper.
            _metrics_pa = _pulse_metrics_from_trace(diff, fps, hp_window_s=2.0,
                                                    prom_mult=0.5, dist_s=0.3,
                                                    savgol_w=7)
            diff_hp = _metrics_pa['signal_hp']
            env     = _metrics_pa['envelope']
            peaks   = _metrics_pa['peaks']
            intervals = _metrics_pa['intervals']
            rates     = _metrics_pa['rates_bpm']
            amps      = _metrics_pa['amps']
            ptimes    = _metrics_pa['peak_times_s']
            # discard peaks within G frames of an interior boundary, then recompute the derived
            # arrays with the same convention as the helper (pk[:-1])
            _s0, _ = _get_range()
            _G = int(state.get('_bnd_guard', 0))
            _interior = [int(b) for b in (state.get('boundaries') or [])[1:-1]]
            if _G > 0 and _interior and len(peaks):
                _keep = np.array([min(abs((_s0 + int(p)) - b) for b in _interior) >= _G for p in peaks])
                _nd = int((~_keep).sum())
                if _nd:
                    self._log(f"[pulse] discarded {_nd} peak(s) within {_G} frames of a boundary")
                peaks = peaks[_keep]
                if len(peaks) >= 2:
                    intervals = np.diff(peaks) / fps; rates = 60.0 / intervals
                    amps = diff_hp[peaks[:-1]]; ptimes = t_ax[peaks[:-1]]
                else:
                    intervals = rates = amps = ptimes = np.array([])

            # Plot
            w = tk.Toplevel(pw); w.title("Pulse Analysis"); w.geometry("1200x800")
            fig = Figure(figsize=(11,7), dpi=150, facecolor='white')
            axes = [fig.add_subplot(4,1,i+1) for i in range(4)]

            # P1: signal + peaks
            axes[0].plot(t_ax, diff_hp, color='#2166ac', lw=0.5, alpha=0.6)
            axes[0].plot(t_ax, env, color='#2166ac', lw=1.0, label='Envelope')
            if len(peaks)>0:
                axes[0].plot(t_ax[peaks], diff_hp[peaks], 'v', color='#d62728', ms=5,
                              label=f'Pulses ({len(peaks)})')
            s0, _ = _get_range()
            _Gpa = int(state.get('_bnd_guard', 0))
            for bi in state.get('boundaries', []):
                bt = (bi-s0)/fps
                if 0 <= bt <= t_end:
                    axes[0].axvline(bt, color='#888', lw=0.5, ls=':', alpha=0.5)
                    if _Gpa > 0 and bi not in (state.get('boundaries')[0], state.get('boundaries')[-1]):
                        axes[0].axvspan((bi - _Gpa - s0) / fps, (bi + _Gpa - s0) / fps,
                                        color='0.6', alpha=0.18, lw=0)
            axes[0].set_ylabel('Signal (HP)'); axes[0].set_title(f'Pulse Detection ({len(peaks)} pulses)', fontweight='bold')
            axes[0].legend(fontsize=7)

            # P2: rate
            if len(rates)>0:
                axes[1].plot(ptimes, rates, 'o-', color='#d62728', ms=3, lw=0.8)
                if len(rates)>3:
                    z = np.polyfit(ptimes, rates, 1)
                    axes[1].plot(ptimes, np.polyval(z, ptimes), '--', color='#888', lw=1,
                                  label=f'Trend: {z[0]:+.2f} bpm/s')
                    axes[1].legend(fontsize=7)
            axes[1].set_ylabel('Rate (bpm)'); axes[1].set_title('Pulse Rate')

            # P3: amplitude
            if len(amps)>0:
                axes[2].plot(ptimes, amps, 's-', color='#1b7837', ms=3, lw=0.8)
                if len(amps)>3:
                    z = np.polyfit(ptimes, amps, 1)
                    axes[2].plot(ptimes, np.polyval(z, ptimes), '--', color='#888', lw=1,
                                  label=f'Trend: {z[0]:+.4f}/s')
                    axes[2].legend(fontsize=7)
            axes[2].set_ylabel('Amplitude'); axes[2].set_title('Pulse Amplitude')

            # P4: intervals
            if len(intervals)>0:
                axes[3].bar(range(len(intervals)), intervals*1000, color='#8060c0')
                axes[3].axhline(np.mean(intervals)*1000, color='#888', ls='--', lw=0.8,
                                 label=f'Mean: {np.mean(intervals)*1000:.0f}ms')
                axes[3].legend(fontsize=7)
            axes[3].set_ylabel('Interval (ms)'); axes[3].set_xlabel('Pulse #')
            axes[3].set_title('Inter-Pulse Intervals')

            for ax in axes:
                ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
                ax.tick_params(labelsize=7)
            fig.tight_layout()

            bot = ttk.Frame(w); bot.pack(fill=tk.X, padx=3, pady=2)
            def _sv_fig():
                p = filedialog.asksaveasfilename(defaultextension=".pdf",
                    filetypes=[("PDF","*.pdf"),("PNG","*.png")])
                if p: fig.savefig(p, dpi=300, bbox_inches='tight')
            def _sv_data():
                p = filedialog.asksaveasfilename(defaultextension=".npz",
                    filetypes=[("NPZ","*.npz")])
                if p: np.savez(p, signal=diff_hp, envelope=env, peaks=peaks,
                               intervals=intervals, rates=rates, amps=amps,
                               time=t_ax, fps=fps)
            ttk.Button(bot, text="Save Fig", command=_sv_fig).pack(side=tk.LEFT, padx=2)
            ttk.Button(bot, text="Save Data", command=_sv_data).pack(side=tk.LEFT, padx=2)

            c = FigureCanvasTkAgg(fig, w); c.draw(); c.get_tk_widget().pack(fill=tk.BOTH, expand=True)

            # Summary
            self._log(f"\nPULSE ANALYSIS: {len(peaks)} pulses in {n/fps:.1f}s")
            if len(rates)>0:
                self._log(f"  Rate: {np.mean(rates):.1f} bpm [{rates.min():.1f}-{rates.max():.1f}]")
                if len(rates)>3:
                    z = np.polyfit(ptimes, rates, 1)
                    self._log(f"  Rate trend: {z[0]:+.2f} bpm/s ({'slowing' if z[0]<0 else 'accel'})")
            if len(amps)>0:
                self._log(f"  Amplitude: {np.mean(amps):.4f}")
                if len(amps)>3:
                    z = np.polyfit(ptimes, amps, 1)
                    self._log(f"  Amp trend: {z[0]:+.6f}/s ({'weakening' if z[0]<0 else 'stronger'})")
            status_v.set(f"Pulse analysis done: {len(peaks)} pulses")

        # ============ Drift correction (translation-only, demotion analog) ============
        def _apodize2d(a):
            """Hann window + DC removal (mirrors swiftir.apodize); kills FFT edge artifacts."""
            a = np.asarray(a, np.float32)
            a = a - float(a.mean())
            wy = np.hanning(a.shape[0])[:, None]; wx = np.hanning(a.shape[1])[None, :]
            return a * (wy * wx)

        def _prep_win(w2d):
            """Estimation-only preprocessing: robust [0,1] scale -> CLAHE -> apodize."""
            w = np.asarray(w2d, np.float32)
            lo, hi = np.percentile(w, (1.0, 99.5))
            n01 = np.clip((w - lo) / (hi - lo + 1e-9), 0.0, 1.0)
            if drift_clahe_var.get():
                n01 = _clahe_u8(n01).astype(np.float32) / 255.0
                return _apodize2d(n01)
            return _apodize2d(n01)

        def _vessel_bbox():
            fg_r = state.get('fg_roi')
            if fg_r is None or len(fg_r) < 2: return None
            a = np.asarray(fg_r); pad = 25
            return (int(a[:,0].min())-pad, int(a[:,1].min())-pad,
                    int(a[:,0].max())+pad, int(a[:,1].max())+pad)

        def _rect_geom(frame_shape):
            """Estimation-window geometry. 'landmark' -> the picked rect.
            'full_masked' -> the whole frame (the vessel bbox is zeroed by _mask_vessel_win)."""
            H, W = int(frame_shape[0]), int(frame_shape[1])
            if drift_mode_var.get() == 'full_masked':
                return 0, 0, max(8, H // 2), max(8, W // 2)
            r = state.get('drift_rect')
            if r is None:
                raise RuntimeError(
                    "No landmark rectangle. Either click 'Pick landmark rect…' and drag a box "
                    "over a STATIC, TEXTURED, sample-fixed structure (the rect is saved as soon "
                    "as you release the mouse), or switch the mode to "
                    "'Full frame minus vessel (no landmark)'.")
            x0, y0, x1, y1 = r
            return int(y0), int(x0), max(8, (y1 - y0) // 2), max(8, (x1 - x0) // 2)

        def _win_at(frame, oy, ox, hh, hw):
            """Crop a 2hh x 2hw window with origin (oy,ox), clamped to the frame.
            Returns (window, oy_eff, ox_eff) so the caller knows the ACTUAL origin."""
            H, W = frame.shape[0], frame.shape[1]
            oy = int(max(0, min(int(oy), H - 2 * hh)))
            ox = int(max(0, min(int(ox), W - 2 * hw)))
            return np.asarray(frame[oy:oy + 2 * hh, ox:ox + 2 * hw], np.float32), oy, ox

        def _mask_vessel_win(win, oy, ox):
            """Zero the vessel bbox inside a window whose origin is (oy, ox). Only used in
            'full_masked' mode so the moving bolus cannot drive the estimate."""
            if drift_mode_var.get() != 'full_masked': return win
            bb = _vessel_bbox()
            if bb is None: return win
            out = win.copy(); h, w_ = out.shape
            y0 = max(0, bb[1] - oy); y1 = min(h, bb[3] - oy)
            x0 = max(0, bb[0] - ox); x1 = min(w_, bb[2] - ox)
            if y1 > y0 and x1 > x0: out[y0:y1, x0:x1] = 0.0
            return out

        def _landmark_score(med, sub_stack, rect):
            """Rate a candidate landmark box. Returns a dict.

            structure   : mean gradient magnitude inside the box, normalized by the frame's
                          global dynamic range. Phase correlation needs edges; ~0 means the box
                          is featureless and the correlation peak will be noise.
            pulse_corr  : |Pearson r| between the box's mean intensity over time and a pulse
                          proxy (FG-ROI mean, else frame mean). High => the box brightens with
                          the bolus and is NOT static.
            overlap     : fraction of the box lying inside the vessel bbox (must be ~0).
            score       : structure * (1 - pulse_corr) * (1 - overlap)
            """
            x0, y0, x1, y1 = (int(v) for v in rect)
            win = np.asarray(med[y0:y1, x0:x1], np.float32)
            if win.size < 64:
                return dict(structure=0.0, pulse_corr=1.0, overlap=1.0, score=0.0,
                            ok=False, verdict="box too small")
            gy, gx = np.gradient(win)
            rng = float(np.percentile(med, 99.5) - np.percentile(med, 1.0)) + 1e-6
            structure = float(np.sqrt((gx * gx + gy * gy).mean())) / rng

            wt = np.asarray(sub_stack[:, y0:y1, x0:x1], np.float32).mean(axis=(1, 2))
            proxy = None
            fg_r = state.get('fg_roi')
            if fg_r is not None and len(fg_r) >= 2:
                try:
                    H, W = med.shape
                    m = np.zeros((H, W), np.uint8)
                    exp = _expand_line(fg_r, int(fg_w.get()))
                    if exp is not None: cv2.fillPoly(m, [exp], 1)
                    if (m > 0).sum() > 0:
                        proxy = np.asarray(sub_stack, np.float32)[:, m > 0].mean(axis=1)
                except Exception:
                    proxy = None
            if proxy is None:
                proxy = np.asarray(sub_stack, np.float32).mean(axis=(1, 2))
            a = wt - wt.mean(); b = proxy - proxy.mean()
            den = (np.linalg.norm(a) * np.linalg.norm(b)) + 1e-9
            pulse_corr = float(abs(float(a @ b) / den))

            overlap = 0.0
            bb = _vessel_bbox()
            if bb is not None:
                ix0, iy0 = max(x0, bb[0]), max(y0, bb[1])
                ix1, iy1 = min(x1, bb[2]), min(y1, bb[3])
                if ix1 > ix0 and iy1 > iy0:
                    overlap = float((ix1 - ix0) * (iy1 - iy0)) / float((x1 - x0) * (y1 - y0))

            score = structure * (1.0 - pulse_corr) * (1.0 - overlap)
            ok = (structure >= 0.02) and (pulse_corr < 0.5) and (overlap < 0.10)
            if structure < 0.02:
                verdict = "FEATURELESS — phase correlation will return noise; pick textured tissue"
            elif overlap >= 0.10:
                verdict = "OVERLAPS THE VESSEL — the bolus will drive the estimate"
            elif pulse_corr >= 0.5:
                verdict = "PULSE-CORRELATED — this box brightens with the bolus; not static"
            else:
                verdict = "OK"
            return dict(structure=structure, pulse_corr=pulse_corr, overlap=overlap,
                        score=score, ok=ok, verdict=verdict)

        def _suggest_landmarks(med, sub_stack, box=96, stride=32, top_k=3):
            """Slide `box` over the frame, score every candidate, return the top-k
            non-overlapping boxes as [(rect, score_dict), ...]."""
            H, W = med.shape
            b = int(box); st_ = int(stride)
            cands = []
            for y in range(0, max(1, H - b), st_):
                for x in range(0, max(1, W - b), st_):
                    r = (x, y, x + b, y + b)
                    sc = _landmark_score(med, sub_stack, r)
                    if sc['structure'] > 0: cands.append((r, sc))
            cands.sort(key=lambda t: -t[1]['score'])
            chosen = []
            for r, sc in cands:
                if all(not (r[0] < c[0][2] and c[0][0] < r[2] and
                            r[1] < c[0][3] and c[0][1] < r[3]) for c in chosen):
                    chosen.append((r, sc))
                if len(chosen) >= top_k: break
            return chosen

        def _pick_landmark():
            """Pick a STATIC, TEXTURED, sample-fixed landmark. The rect is saved the moment the
            drag ends — no 'Accept' click is required (the old Accept button was pushed off the
            window by the canvas and was unreachable)."""
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            import matplotlib.patches as mp
            base = state.get('stack_orig') if state.get('stack_orig') is not None else state.get('stack')
            if base is None:
                messagebox.showwarning("Landmark", "Load files first."); return
            T = base.shape[0]
            idx = np.linspace(0, T - 1, min(T, 120)).astype(int)
            with _Progress("Building median frame", total=len(idx)) as _p:
                frames = []
                for k, i in enumerate(idx):
                    _p.step(k + 1); frames.append(np.asarray(base[i], np.float32))
            sub_stack = np.stack(frames, 0)
            med = np.median(sub_stack, 0)

            w = tk.Toplevel(pw); w.title("Pick landmark — STATIC, TEXTURED, sample-fixed")
            w.geometry("1000x860")
            # Pack the controls FIRST, anchored to the bottom, so the canvas can never squeeze
            # them out of the window (that is the bug this rewrite fixes).
            bar = ttk.Frame(w); bar.pack(side=tk.BOTTOM, fill=tk.X, pady=3)
            info = ttk.Label(w, text="Drag a box over static TISSUE structure "
                                     "(not the vessel, not the aperture edge).",
                             foreground='#333')
            info.pack(side=tk.BOTTOM, fill=tk.X, padx=4)

            fig = Figure(figsize=(8.0, 6.2), dpi=100, facecolor='white')
            ax = fig.add_subplot(111)
            lo, hi = np.percentile(med, (1, 99.5))
            ax.imshow(med, cmap='gray', vmin=lo, vmax=hi)
            bb = _vessel_bbox()
            if bb is not None:
                ax.add_patch(mp.Rectangle((bb[0], bb[1]), bb[2] - bb[0], bb[3] - bb[1],
                                          fill=False, ec='#d62728', lw=1.0, ls='--'))
                ax.text(bb[0], bb[1] - 4, 'vessel (avoid)', color='#d62728', fontsize=7)
            cur = state.get('drift_rect')
            if cur:
                ax.add_patch(mp.Rectangle((cur[0], cur[1]), cur[2] - cur[0], cur[3] - cur[1],
                                          fill=False, ec='cyan', lw=1.2))
            ax.set_xticks([]); ax.set_yticks([])

            # Create the REAL canvas BEFORE the selector (required on matplotlib < 3.6).
            canvas = FigureCanvasTkAgg(fig, w); canvas.draw()
            canvas.get_tk_widget().pack(side=tk.TOP, fill=tk.BOTH, expand=True)
            from matplotlib.widgets import RectangleSelector

            def _commit(rect):
                sc = _landmark_score(med, sub_stack, rect)
                state['drift_rect'] = rect
                state['drift'] = None; state['stack_corrected'] = None
                drift_lm_lbl.config(text=f"landmark {rect}  score={sc['score']:.3f}",
                                    foreground=('#1b7837' if sc['ok'] else '#b35c00'))
                info.config(text=(f"rect={rect}   structure={sc['structure']:.3f}   "
                                  f"pulse|r|={sc['pulse_corr']:.2f}   "
                                  f"vessel overlap={100*sc['overlap']:.0f}%   ->  {sc['verdict']}"),
                            foreground=('#1b7837' if sc['ok'] else '#b35c00'))
                self._log(f"[drift] landmark rect={rect} structure={sc['structure']:.4f} "
                          f"pulse_corr={sc['pulse_corr']:.3f} overlap={sc['overlap']:.3f} "
                          f"score={sc['score']:.4f} -> {sc['verdict']}")
                canvas.draw_idle()

            def _onsel(ep, er):
                if None in (ep.xdata, ep.ydata, er.xdata, er.ydata):
                    info.config(text="Drag ended outside the image — try again.",
                                foreground='#b35c00'); return
                x0, x1 = sorted((int(ep.xdata), int(er.xdata)))
                y0, y1 = sorted((int(ep.ydata), int(er.ydata)))
                if (x1 - x0) < 16 or (y1 - y0) < 16:
                    info.config(text=f"Box too small ({x1-x0}x{y1-y0} px); need >= 16x16.",
                                foreground='#b35c00'); return
                _commit((x0, y0, x1, y1))

            _sel_kw = dict(useblit=False, button=[1], interactive=True,
                           minspanx=8, minspany=8, spancoords='pixels')
            try:
                rs = RectangleSelector(ax, _onsel,
                                       props=dict(facecolor='none', edgecolor='cyan', lw=1.2),
                                       **_sel_kw)
            except TypeError:                       # matplotlib < 3.5 used `rectprops`
                rs = RectangleSelector(ax, _onsel,
                                       rectprops=dict(facecolor='none', edgecolor='cyan', lw=1.2),
                                       **_sel_kw)
            w._rs = rs                               # keep a strong reference alive

            def _do_suggest():
                with _Progress("Scoring landmark candidates", total=None) as _p:
                    _p.step(0, note="sliding window")
                    top = _suggest_landmarks(med, sub_stack)
                if not top:
                    info.config(text="No candidate found."); return
                for k, (r, sc) in enumerate(top):
                    ax.add_patch(mp.Rectangle((r[0], r[1]), r[2] - r[0], r[3] - r[1],
                                              fill=False, ec='#00e5ff', lw=1.0, ls=':'))
                    ax.text(r[0], r[1] - 3, f"#{k+1} {sc['score']:.3f}",
                            color='#00e5ff', fontsize=7)
                    self._log(f"[drift] candidate #{k+1} {r} score={sc['score']:.4f} "
                              f"({sc['verdict']})")
                _commit(top[0][0])
                info.config(text=f"Best candidate #1 selected. Drag your own box to override.")

            def _clear():
                state['drift_rect'] = None; state['drift'] = None
                drift_lm_lbl.config(text="(no landmark)", foreground='#888')
                info.config(text="Landmark cleared.", foreground='#333')

            ttk.Button(bar, text="Suggest landmarks",
                       command=lambda: _pf_run_safe("Suggest landmarks", _do_suggest)).pack(side=tk.LEFT, padx=3)
            ttk.Button(bar, text="Clear", command=_clear).pack(side=tk.LEFT, padx=3)
            ttk.Label(bar, text="(the rect is saved as soon as you finish a drag)",
                      foreground='#666').pack(side=tk.LEFT, padx=8)
            ttk.Button(bar, text="Close", command=w.destroy).pack(side=tk.RIGHT, padx=3)

        def _swiftir_try():
            if not drift_swift_var.get(): return None
            import sys, os
            try:
                import swiftir as _s; return _s
            except Exception: pass
            for cand in (r"D:\NIR_SLIM\demotion", r"D:\NIR_SLIM2\demotion"):
                if os.path.isdir(cand) and cand not in sys.path:
                    sys.path.insert(0, cand)
            try:
                import swiftir as _s; return _s
            except Exception:
                return None

        def _estimate_disp_tracked(base, t0, ref, oy0, ox0, hh, hw, prog=None):
            """Anchor-based PREDICTIVE TRACKING (mirrors _RWISLAD.py re-extraction).
            For frame t, extract the window at the origin predicted from the neighbour's
            displacement, then measure the residual against the FIXED anchor reference.

              window origin used: e = clamp(round(anchor_origin + d_pred))
              inside that window the anatomy is offset by (d_t - (e - anchor_origin))
              phase_cross_correlation(ref, win) -> r  with  shift(win, r) ~= ref
              =>  r = -(d_t - (e - anchor_origin))   =>   d_t = (e - anchor_origin) - r

            Because `ref` is fixed at the anchor, the estimate is SELF-CORRECTING: an error in
            d_pred appears in r and cancels. Cumulative drift can be arbitrarily large.
            """
            from skimage.registration import phase_cross_correlation
            T = base.shape[0]
            d = np.zeros((T, 2), np.float32); q = np.zeros(T, np.float32)
            sw = _swiftir_try()

            def _one(t, d_pred):
                win, ey, ex = _win_at(base[t], oy0 + d_pred[0], ox0 + d_pred[1], hh, hw)
                e = np.array([ey - oy0, ex - ox0], np.float32)
                mov = _mask_vessel_win(_prep_win(win), ey, ex)
                try:
                    if sw is not None:
                        dx_, dy_, sx, sy, snr = sw.swim(ref, mov)
                        r = np.array([-float(dy_), -float(dx_)], np.float32)
                        qq = float(np.clip(snr / 10.0, 0, 1))
                    else:
                        r, err, _ = phase_cross_correlation(
                            ref, mov, upsample_factor=10, normalization='phase')
                        r = np.asarray(r, np.float32); qq = float(np.clip(1.0 - float(err), 0, 1))
                except Exception:
                    r = np.zeros(2, np.float32); qq = 0.0
                return (e - r).astype(np.float32), qq

            done = 0
            d[t0] = (0.0, 0.0); q[t0] = 1.0
            for t in range(t0 + 1, T):
                d[t], q[t] = _one(t, d[t - 1]); done += 1
                if prog is not None: prog.step(done)
                elif (t % 500) == 0:
                    status_v.set(f"Drift fwd {t}/{T}"); pw.update_idletasks()
            for t in range(t0 - 1, -1, -1):
                d[t], q[t] = _one(t, d[t + 1]); done += 1
                if prog is not None: prog.step(done)
                elif (t % 500) == 0:
                    status_v.set(f"Drift bwd {t}"); pw.update_idletasks()
            return d, q

        def _postprocess_shifts(shifts, quality, fps):
            """Reject low-quality/outlier frames, interpolate, then LOW-PASS.
            Drift is slow; bolus + breathing are fast. Smoothing isolates the drift."""
            from scipy.ndimage import median_filter
            from scipy.signal import savgol_filter
            sh = np.array(shifts, float)
            valid = auto_motion_mask(sh, method='mad', k=4.0, quality=quality, qmin=0.05)
            if valid.sum() < 3: valid[:] = True
            t = np.arange(len(sh))
            for a in (0,1):
                sh[~valid, a] = np.interp(t[~valid], t[valid], sh[valid, a])
            ws = float(drift_smooth_var.get())
            if ws > 0:
                w = int(round(ws*float(fps))) | 1; w = max(3, min(w, (len(sh)-1) | 1))
                for a in (0,1):
                    sh[:,a] = median_filter(sh[:,a], size=w, mode='nearest')
                    if len(sh) > w >= 5:
                        sh[:,a] = savgol_filter(sh[:,a], w, 2)
            return sh.astype(np.float32), valid

        def _apply_shifts_chunked(base, shifts, chunk=128):
            """Translation applied to the FULL frame, dtype PRESERVED (no float32 blowup)."""
            from scipy.ndimage import shift as _shift
            out = np.empty(base.shape, base.dtype)
            is_int = np.issubdtype(base.dtype, np.integer)
            info = np.iinfo(base.dtype) if is_int else None
            T = base.shape[0]
            with _Progress("Warping stack", total=T) as _p:
                for t0 in range(0, T, chunk):
                    t1 = min(t0+chunk, T)
                    for k in range(t0, t1):
                        dy, dx = float(shifts[k,0]), float(shifts[k,1])
                        if abs(dy) < 1e-3 and abs(dx) < 1e-3:
                            out[k] = base[k]; continue
                        s = _shift(np.asarray(base[k], np.float32), (dy,dx),
                                   order=1, mode='nearest', prefilter=False)
                        if is_int: s = np.clip(np.rint(s), info.min, info.max)
                        out[k] = s.astype(base.dtype)
                    _p.step(t1, note="warping")
            return out

        # ══════════ Vessel-based, bolus-gated, bin-median drift estimator ══════════
        def _field_geometry(med):
            """Does this FOV have a bright illuminated field whose boundary lies INSIDE the image
            (an aperture/vignette edge), or is it a dark background with sparse bright structure?

            A brightness threshold alone cannot tell these apart. On a *_sas.tif frame the
            'bright' mask is just the vessel (~2% of pixels); eroding it destroys it and every ROI
            then looks 'outside the support'. That produced the spurious aperture verdict.
            Otsu's bright fraction separates the regimes: recon disc ~0.38, SAS vessel ~0.02.
            """
            m = np.asarray(med, np.float32)
            try:
                from skimage.filters import threshold_otsu
                thr = float(threshold_otsu(m))
            except Exception:
                thr = float(np.percentile(m, 60))
            bright = m > thr
            bf = float(bright.mean())
            edge = np.zeros_like(bright)
            edge[0, :] = edge[-1, :] = True; edge[:, 0] = edge[:, -1] = True
            border_bright = float(bright[edge].mean())
            # aperture := a large bright field, bounded inside the frame (dark border)
            has_aperture = (0.25 < bf < 0.95) and (border_bright < 0.5)
            return dict(thr=thr, bright=bright, bright_frac=bf,
                        border_bright=border_bright, has_aperture=has_aperture)

        def _auto_reg_rect(med):
            from scipy.ndimage import binary_erosion
            H, W = med.shape
            fg = _field_geometry(med)
            bb = _vessel_bbox()
            bdr = int(reg_border_px_var.get())
            mode = reg_roi_mode_var.get()
            if mode == 'manual' and state.get('reg_rect'):
                return tuple(state['reg_rect'])
            if fg['has_aperture'] and mode in ('auto', 'full'):
                er = int(max(1, reg_erode_px_var.get()))
                sup_e = binary_erosion(fg['bright'], iterations=er, border_value=0)
                if sup_e.sum() >= 64:
                    ys, xs = np.nonzero(sup_e)
                    x0, x1 = int(xs.min()), int(xs.max()) + 1
                    y0, y1 = int(ys.min()), int(ys.max()) + 1
                    for _ in range(300):
                        if (sup_e[y0, x0] and sup_e[y0, x1-1] and
                            sup_e[y1-1, x0] and sup_e[y1-1, x1-1]): break
                        x0 += 2; x1 -= 2; y0 += 2; y1 -= 2
                        if x1 - x0 < 64 or y1 - y0 < 64: break
                    self._log(f"[drift] aperture detected (bright_frac={fg['bright_frac']:.3f}); "
                              f"auto ROI inside eroded support = {(x0,y0,x1,y1)}")
                    return (x0, y0, x1, y1)
                self._log("[drift] aperture support vanished after erosion; "
                          "falling back to a vessel-centred ROI.")
            if mode == 'vessel_box' and bb is not None:
                mar = int(reg_margin_px_var.get())
                rect = (max(bdr, bb[0]-mar), max(bdr, bb[1]-mar),
                        min(W-bdr, bb[2]+mar), min(H-bdr, bb[3]+mar))
                self._log(f"[drift] ROI mode=vessel_box -> {rect}  "
                          f"(WARNING: a tight ROI discards the tissue texture that constrains the "
                          f"along-vessel component; 'full' is usually 3-9x more accurate)")
                return rect
            rect = (bdr, bdr, W - bdr, H - bdr)
            self._log(f"[drift] no aperture (bright_frac={fg['bright_frac']:.3f}); "
                      f"ROI = FULL frame minus {bdr}px = {rect}")
            return rect

        def _reg_roi_score(med, rect):
            from scipy.ndimage import binary_erosion, gaussian_filter
            x0, y0, x1, y1 = (int(v) for v in rect)
            fg = _field_geometry(med)
            touches = False
            if fg['has_aperture']:
                er = int(max(1, reg_erode_px_var.get()))
                sup_e = binary_erosion(fg['bright'], iterations=er, border_value=0)
                touches = bool(sup_e[y0:y1, x0:x1].mean() < 0.98)
            hp = float(reg_hp_sigma_var.get())
            hpf = (med - gaussian_filter(med, hp)) if hp > 0 else (med - float(med.mean()))
            noise = 1.4826 * float(np.median(np.abs(hpf - np.median(hpf)))) + 1e-9
            snr = float(np.std(hpf[y0:y1, x0:x1])) / noise      # texture ABOVE the noise floor
            bb = _vessel_bbox()
            Hm, Wm = med.shape
            contains = True if bb is None else (x0 <= bb[0] and bb[2] <= x1 and
                                                y0 <= bb[1] and bb[3] <= y1)
            too_small = (x1 - x0) < 64 or (y1 - y0) < 64
            too_tight = ((x1 - x0) * (y1 - y0) < 0.25 * Hm * Wm) and (not fg['has_aperture'])
            ok = (not touches) and contains and (snr >= 3.0) and (not too_small)
            if touches:      verdict = "APERTURE EDGE INSIDE ROI — PCC will lock onto it (zero shift)"
            elif too_small:  verdict = "ROI TOO SMALL (<64 px on a side)"
            elif not contains: verdict = "ROI DOES NOT CONTAIN THE VESSEL"
            elif snr < 3.0:  verdict = f"ROI HAS ALMOST NO TEXTURE (high-pass SNR={snr:.1f})"
            elif too_tight:  verdict = "ROI IS SMALL FOR AN APERTURE-FREE FOV — consider ROI mode 'full'"
            else:            verdict = "OK" + ("" if fg['has_aperture'] else " (no aperture in this FOV)")
            return dict(touches_aperture=touches, contains=contains, snr=snr,
                        too_small=too_small, too_tight=too_tight, has_aperture=fg['has_aperture'],
                        bright_frac=fg['bright_frac'], ok=ok, verdict=verdict)

        def _prep_reg_crop(crop):
            """high-pass -> DC removal -> TUKEY apodize.

            A Hann window zeroes the ROI edges and discards ~half the window energy — exactly
            where the faint tissue texture that constrains the along-vessel drift lives. A Tukey
            window (flat top, tapered rim) keeps the interior intact while still suppressing FFT
            edge artefacts. Measured: per-bin error 7.19 px (Hann) -> 2.74 px (Tukey) on a tight
            ROI; 1.02 -> 0.81 px on the full frame.
            (No CLAHE: it amplifies photon noise.)
            """
            from scipy.ndimage import gaussian_filter
            a = np.asarray(crop, np.float32)
            hp = float(reg_hp_sigma_var.get())
            if hp > 0: a = a - gaussian_filter(a, hp)
            a = a - float(a.mean())
            alpha = float(np.clip(reg_taper_var.get(), 0.0, 1.0))
            if alpha <= 0: return a
            try:
                from scipy.signal.windows import tukey as _tk
            except Exception:
                from scipy.signal import tukey as _tk
            wy = _tk(a.shape[0], alpha).astype(np.float32)[:, None]
            wx = _tk(a.shape[1], alpha).astype(np.float32)[None, :]
            return a * (wy * wx)

        def _prep_reg(img, rect):
            x0, y0, x1, y1 = rect
            return _prep_reg_crop(np.asarray(img, np.float32)[y0:y1, x0:x1])

        def _reg_precision_null(base, rect, bol, bin_n, n_probe=6, prog=None):
            """Per-bin registration noise, measured from the data itself.

            For several bins, split the QUIET frames into two INTERLEAVED halves and build two
            independent super-frames of the SAME epoch. Their true relative displacement is zero
            (interleaving cancels the intra-bin drift), so whatever the registration returns is
            pure noise. The median |error| is the per-bin sigma. This is the number that exposes a
            bad ROI or window; it needs no ground truth and costs a few seconds.
            """
            from skimage.registration import phase_cross_correlation
            T = base.shape[0]; x0, y0, x1, y1 = rect
            nb = int(np.ceil(T / bin_n)); up = int(reg_upsample_var.get())
            probes = np.unique(np.linspace(0, nb - 1, min(n_probe, nb)).astype(int))
            errs = []
            for k, b in enumerate(probes):
                if prog is not None: prog.step(k + 1, note=f"probe bin {b}")
                b0, b1 = b * bin_n, min((b + 1) * bin_n, T)
                idx = np.nonzero(~bol[b0:b1])[0] + b0
                if idx.size < 8: continue
                A_ = np.median(np.stack([np.asarray(base[i], np.float32)[y0:y1, x0:x1]
                                         for i in idx[0::2]]), 0)
                B_ = np.median(np.stack([np.asarray(base[i], np.float32)[y0:y1, x0:x1]
                                         for i in idx[1::2]]), 0)
                s, _, _ = phase_cross_correlation(_prep_reg_crop(A_), _prep_reg_crop(B_),
                                                  upsample_factor=up, normalization='phase')
                errs.append(float(np.hypot(float(s[0]), float(s[1]))))
            return (float(np.median(errs)) if errs else float('nan')), len(errs)

        def _structure_tensor_report(ref_prepped):
            """Anisotropy A -> 1 means the ROI is effectively 1-D (a bare line) and the drift
            component along that line is unobservable. Report it; do not silently trust it."""
            gy, gx = np.gradient(np.asarray(ref_prepped, np.float32))
            J = np.array([[float((gx*gx).sum()), float((gx*gy).sum())],
                          [float((gx*gy).sum()), float((gy*gy).sum())]])
            w_, v_ = np.linalg.eigh(J)
            A = float((w_[1] - w_[0]) / (w_[1] + w_[0] + 1e-12))
            soft = np.degrees(np.arctan2(v_[1, 0], v_[0, 0]))
            return A, float(soft)

        def _vessel_g(base, prog=None):
            """g(t) = mean intensity inside the vessel (FG) mask, over the whole stack.
            Same mask logic as the legacy _bolus_mask. Returns (g[T], (ys,xs))."""
            T, H, W = base.shape[0], base.shape[1], base.shape[2]
            fg_r = state.get('fg_roi')
            m = None
            if fg_r is not None and len(fg_r) >= 2:
                m = np.zeros((H, W), np.uint8)
                exp = _expand_line(fg_r, int(fg_w.get()))
                if exp is not None: cv2.fillPoly(m, [exp], 1)
                m = m > 0
            if m is None or m.sum() == 0:
                _si = np.linspace(0, T-1, min(T, 100)).astype(int)
                med = np.median(np.stack([np.asarray(base[i], np.float32) for i in _si], 0), 0)
                m = med >= np.percentile(med, 99.0)
            ys, xs = np.nonzero(m)
            g = np.empty(T, np.float32)
            for t in range(T):
                g[t] = float(np.asarray(base[t])[ys, xs].mean())
                if prog is not None and (t % 200) == 0: prog.step(t, note="bolus scan")
            return g, (ys, xs)

        def _auto_boundary_guard(g):
            """How many frames after a restart are transient? For each interior boundary, compare
            the first K frames of the new file against that file's own robust baseline; G = the
            first offset at which |g - baseline| falls below 2*sigma for 3 consecutive frames.
            Return the median G over boundaries, clipped to [1, 20]."""
            bounds = list(state.get('boundaries') or [0, len(g)])
            T = len(g); Gs = []
            Kmax = 24
            for bi in bounds[1:-1]:
                f_i = file_index(bounds, bi)                # the file that STARTS at bi
                f0, f1 = bounds[f_i], bounds[f_i + 1]
                seg = np.asarray(g[f0:f1], float)
                if seg.size < 6: continue
                med = float(np.median(seg)); sig = 1.4826 * float(np.median(np.abs(seg - med))) + 1e-9
                K = min(Kmax, seg.size - 3)
                gk = None; run = 0
                for k in range(K):
                    if abs(seg[k] - med) < 2.0 * sig:
                        run += 1
                        if run >= 3: gk = max(0, k - 2); break
                    else:
                        run = 0
                Gs.append(int(gk) if gk is not None else 1)
            G = int(np.clip(int(np.median(Gs)) if Gs else 1, 1, 20))
            return G

        def _quiet_mask_per_file(base, prog=None):
            """Bolus mask with a PER-FILE robust baseline. There is no gain/offset step inside a
            file, so this is correct even before harmonization — this breaks the circular
            dependency. Also marks +/- G frames around every boundary as INVALID (usable for
            neither bolus nor quiet stats). Returns (bol[T] bool, invalid[T] bool, g[T] float)."""
            T = base.shape[0]
            bounds = list(state.get('boundaries') or [0, T])
            g, _px = _vessel_g(base, prog=prog)
            k = float(bolus_k_var.get()); pad = int(bolus_pad_var.get())
            bol = np.zeros(T, bool)
            glob_med = float(np.median(g)); glob_mad = 1.4826 * float(np.median(np.abs(g - glob_med))) + 1e-9
            glob_bol = g > (glob_med + k * glob_mad)
            # Robust baseline is PER ROOT FILE (frames from the same original TIF share photometry);
            # after an extraction the local boundaries are segment junctions, not files.
            rf = np.array([_root_file(t) for t in range(T)], int)
            for fi in np.unique(rf):
                idx = np.where(rf == fi)[0]
                seg = g[idx]
                if seg.size == 0: continue
                med = float(np.median(seg)); mad = 1.4826 * float(np.median(np.abs(seg - med))) + 1e-9
                bseg = seg > (med + k * mad)
                bol[idx] = bseg
                self._log(f"[bnd] root file {fi} ({seg.size} frames): median={med:.4g} mad={mad:.4g} "
                          f"bolus {100.0*bseg.mean():.1f}% (global-threshold would flag "
                          f"{100.0*glob_bol[idx].mean():.1f}%)")
            if pad > 0:
                kk = np.ones(2 * pad + 1, np.uint8)
                bol = np.convolve(bol.astype(np.uint8), kk, mode='same') > 0
            G = int(bnd_guard_var.get()) if int(bnd_guard_var.get()) > 0 else _auto_boundary_guard(g)
            state['_bnd_guard'] = G
            invalid = np.zeros(T, bool)
            invalid[:G] = True; invalid[max(0, T - G):] = True
            for bi in bounds[1:-1]:
                invalid[max(0, bi - G):min(T, bi + G)] = True
            self._log(f"[bnd] boundary guard G={G} frames; invalid frames "
                      f"{int(invalid.sum()):,}/{T:,} ({100.0*invalid.mean():.2f}%)  "
                      f"(global-threshold total bolus {100.0*glob_bol.mean():.1f}% vs "
                      f"per-file {100.0*bol.mean():.1f}%)")
            return bol, invalid, g

        def _bolus_mask(base, prog=None):
            """Flag the ~5% of frames containing a pulse. Delegates to the PER-FILE robust
            baseline when `bolus_perfile_var` is set (correct across gain/offset steps); otherwise
            the legacy GLOBAL median/MAD path. Returns (bolus_bool[T], g[T]); stashes the
            boundary-guard invalid mask in state['_invalid_frames']."""
            T = base.shape[0]
            if bool(bolus_perfile_var.get()):
                bol, invalid, g = _quiet_mask_per_file(base, prog=prog)
                state['_invalid_frames'] = invalid
                self._log(f"[drift] bolus frames (per-file): {int(bol.sum()):,}/{T:,} "
                          f"({100.0*bol.mean():.1f}%)")
                if bol.mean() > 0.30:
                    self._log("[drift] WARNING: >30% flagged as bolus — raise 'bolus k' or check the FG ROI.")
                return bol, g
            g, _px = _vessel_g(base, prog=prog)
            med_g = float(np.median(g))
            mad = float(np.median(np.abs(g - med_g))) * 1.4826 + 1e-9
            bol = g > (med_g + float(bolus_k_var.get()) * mad)
            pad = int(bolus_pad_var.get())
            if pad > 0:
                k = np.ones(2*pad + 1, bool)
                bol = np.convolve(bol.astype(np.uint8), k.astype(np.uint8), mode='same') > 0
            state['_invalid_frames'] = np.zeros(T, bool)
            self._log(f"[drift] bolus frames: {int(bol.sum()):,}/{T:,} "
                      f"({100.0*bol.mean():.1f}%)  baseline={med_g:.4g} mad={mad:.4g}")
            if bol.mean() > 0.30:
                self._log("[drift] WARNING: >30% flagged as bolus — raise 'bolus k' or check the FG ROI.")
            return bol, g

        def _photo_file(t):
            """Photometry is per ROOT FILE. After an extraction the local `boundaries` are segment
            junctions, so we must resolve the file via _root_file (frame_map + root['boundaries']).
            Clamped to the number of stored LUTs so an out-of-range root file never IndexErrors."""
            p = state.get('photo') or {}
            n = len(p.get('a', p.get('xk', [])))
            i = _root_file(int(t))
            return int(min(max(i, 0), n - 1)) if n > 0 else 0

        def _photo_ab(t):
            p = state.get('photo')
            if not p or 'a' not in p: return (1.0, 0.0)
            i = _photo_file(t)
            return (float(p['a'][i]), float(p['b'][i]))

        def _photo_map_px(vals, t):
            """Map PIXEL VALUES of frame t into reference intensity units. This is the only correct
            entry point for a nonlinear model: mean(g(x)) != g(mean(x))."""
            p = state.get('photo')
            if not p or p.get('model') == 'off': return np.asarray(vals, np.float32)
            i = _photo_file(t)
            return _apply_lut(vals, np.asarray(p['xk'][i]), np.asarray(p['yk'][i]))

        def _photo_map_frame(fr, t, rect=None):
            """LUT-map a whole frame (or a crop given by `rect`=(x0,y0,x1,y1)) into reference units."""
            fr = np.asarray(fr, np.float32)
            p = state.get('photo')
            if not p or p.get('model') == 'off': return fr
            i = _photo_file(t)
            xk = np.asarray(p['xk'][i]); yk = np.asarray(p['yk'][i])
            if rect is None:
                return _apply_lut(fr, xk, yk)
            x0, y0, x1, y1 = rect
            out = fr.copy(); out[y0:y1, x0:x1] = _apply_lut(fr[y0:y1, x0:x1], xk, yk)
            return out

        # ════════════ Per-frame photometry (BACKGROUND-restricted) ════════════
        def _background_mask(H, W):
            """Pixels used to estimate per-frame photometry: the registration ROI MINUS the vessel
            (FG mask dilated by 3*fg_w) MINUS any structure traced by the BG ROIs. Must contain no
            bolus signal. Falls back to reg-minus-FG if the strict mask is too small."""
            rect = state.get('reg_rect')
            if rect is None:
                bd = int(reg_border_px_var.get()); rect = (bd, bd, W - bd, H - bd)
            x0, y0, x1, y1 = rect
            m = np.zeros((H, W), bool); m[max(0, y0):min(H, y1), max(0, x0):min(W, x1)] = True
            fg = _roi_pts('fg_roi'); fgm = np.zeros((H, W), np.uint8)
            if fg is not None:
                exp = _expand_line(fg.astype(np.int32), int(fg_w.get()) * 3)
                if exp is not None: cv2.fillPoly(fgm, [exp], 1)
            m_fg = m & ~(fgm > 0)
            m_strict = m_fg.copy()
            for key in ('bg_roi_1', 'bg_roi_2'):
                b = _roi_pts(key)
                if b is not None:
                    bm = np.zeros((H, W), np.uint8); exp = _expand_line(b.astype(np.int32), int(bg_w.get()))
                    if exp is not None: cv2.fillPoly(bm, [exp], 1); m_strict &= ~(bm > 0)
            return m_strict if int(m_strict.sum()) >= 200 else m_fg

        def _fp_quiet_g():
            """Cached (quiet_mask[T], g[T]) for the whole stack (vessel signal + quiet frames)."""
            base = _bk_base(); T = base.shape[0]
            if state.get('_fp_quiet') is not None and len(state['_fp_quiet']) == T:
                return state['_fp_quiet'], state['_fp_g']
            try:
                _bol, _inv, _g = _quiet_mask_per_file(base); qm = (~_bol) & (~_inv)
            except Exception:
                qm = np.ones(T, bool); _g = np.zeros(T)
            state['_fp_quiet'] = qm; state['_fp_g'] = np.asarray(_g, float)
            return qm, state['_fp_g']

        def _frame_photometry(t0, t1, prog=None):
            """Per-frame photometric correction for ONE segment, estimated on BACKGROUND pixels only
            and low-passed in time. REFUSED (identity) if a_t/b_t correlate with the vessel signal
            g(t) beyond fphoto_maxcorr — a correction that tracks the pulse is measuring the bolus.
            Estimated in the SAME (file-LUT-mapped) units it is applied to."""
            mode = fphoto_mode_var.get()
            base = _bk_base(); T, H, W = base.shape[0], base.shape[1], base.shape[2]
            fps = float(fps_var.get()); t0 = int(t0); t1 = int(t1); n = t1 - t0
            ident = dict(a=None, b=None, xk=None, yk=None, mode='off', r_a=0.0, r_b=0.0,
                         rejected=False, t0=t0, t1=t1)
            if mode == 'off' or n < 3:
                return ident
            bm = _background_mask(H, W); ys, xs = np.nonzero(bm)
            if ys.size < 50:
                self._log("[fphoto] background mask < 50 px — skipping per-frame photometry."); return ident
            if ys.size > 4000:
                sel = np.linspace(0, ys.size - 1, 4000).astype(int); ys = ys[sel]; xs = xs[sel]
            d = _disp()
            def _bgpx(t):
                fr = np.asarray(base[t], np.float32)
                if d is not None and t < len(d):
                    from scipy.ndimage import shift as nds
                    fr = nds(fr, (-float(d[t, 0]), -float(d[t, 1])), order=1, mode='nearest')
                return _photo_map_px(fr[ys, xs], t)            # SAME units as application (after LUT)
            qm, gfull = _fp_quiet_g()
            seg_q = np.nonzero(qm[t0:t1])[0] + t0
            if seg_q.size < 3:
                self._log(f"[fphoto] seg [{t0},{t1}): <3 quiet frames; reference taken from the "
                          f"first 10 frames (pulse-only stack?)")
                seg_q = np.arange(t0, min(t1, t0 + 10))
            ref_px = np.median(np.stack([_bgpx(t) for t in seg_q], 0), 0); ref_med = float(np.median(ref_px))
            a = np.ones(n); b = np.zeros(n); xk_list = [None] * n; yk_list = [None] * n
            for k, t in enumerate(range(t0, t1)):
                px = _bgpx(t)
                if mode == 'offset_bg':
                    a[k] = 1.0; b[k] = float(np.median(px) - ref_med)
                elif mode == 'lut_bg':
                    xk_list[k], yk_list[k] = _monotone_lut(px, ref_px, K=16)
                    a[k], b[k] = _qq_affine(ref_px, px)                    # guard proxy
                else:                                          # affine_bg
                    # DISTRIBUTION-based (quantile) fit: robust to the lack of per-pixel structure
                    # in background and drift-insensitive. Paired huber would need texture spread.
                    a[k], b[k] = _qq_affine(ref_px, px)
                if prog is not None: prog.step(k + 1)
            a_raw = a.copy(); b_raw = b.copy()             # keep RAW for the anti-leak inspection
            win = max(3, int(round(float(fphoto_smooth_s_var.get()) * fps))) | 1
            if n > win >= 5:
                try:
                    from scipy.signal import savgol_filter
                    a = savgol_filter(a, win, 2); b = savgol_filter(b, win, 2)   # remove the fast bolus
                except Exception:
                    pass
            # ANTI-LEAK GUARD. The low-pass above is the primary protection (it strips the fast
            # bolus from a_t/b_t). g(t) itself carries the SLOW illumination, so a raw corr(a_t,g)
            # would always be high; we therefore inspect the FAST component only: detrend g (deg-2)
            # to the pulse template, and measure how much of that pulse LEAKED into the RAW per-
            # frame estimate (a leaked-fraction gate), then report Pearson |r| against the pulse.
            g_seg = np.asarray(gfull[t0:t1], float)
            def _detr(x):
                x = np.asarray(x, float); tt = np.arange(x.size)
                return x - np.polyval(np.polyfit(tt, x, 2), tt) if x.size >= 5 else (x - x.mean())
            gb = _detr(g_seg); gbn = gb / (np.linalg.norm(gb) + 1e-9)
            def _leak(v_raw, scale):
                dv = _detr(v_raw); frac = abs(float(dv @ gbn)) / (abs(scale) + 1e-9)
                if frac < 0.03 or np.std(gb) < 1e-9 or np.std(dv) < 1e-9:
                    return 0.0, frac                        # negligible leak -> a is not the bolus
                return abs(float(np.corrcoef(dv, gb)[0, 1])), frac
            r_a, f_a = _leak(a_raw, np.mean(a_raw)); r_b, f_b = _leak(b_raw, ref_med)
            thr = float(fphoto_maxcorr_var.get())
            if r_a > thr or r_b > thr:
                self._log(f"[fphoto] REFUSED seg [{t0},{t1}): a_t/b_t track the pulse "
                          f"(|r_a|={r_a:.2f} leaked={f_a*100:.1f}%, |r_b|={r_b:.2f} leaked={f_b*100:.1f}%) "
                          f"> {thr:.2f} — using identity and marking the segment rejected.")
                return dict(ident, r_a=r_a, r_b=r_b, rejected=True)
            return dict(a=a, b=b, xk=xk_list, yk=yk_list, mode=mode, r_a=r_a, r_b=r_b,
                        rejected=False, t0=t0, t1=t1)

        def _frame_photo_apply(fr, t, fp):
            """Apply the per-frame correction to an already file-harmonized frame (map into ref)."""
            fr = np.asarray(fr, np.float32)
            if not fp or fp.get('mode', 'off') == 'off' or fp.get('rejected'):
                return fr
            t0 = fp.get('t0')
            if t0 is None: return fr
            k = int(t) - int(t0)
            if k < 0 or fp.get('a') is None or k >= len(fp['a']): return fr
            if fp['mode'] == 'lut_bg' and fp.get('xk') is not None and fp['xk'][k] is not None:
                return _apply_lut(fr, fp['xk'][k], fp['yk'][k])
            a = float(fp['a'][k]); b = float(fp['b'][k])
            return (fr - b) / max(a, 1e-6)

        def _fig_frame_photo(t0, t1, fp):
            """QC figure for the per-frame background photometry of one segment."""
            import matplotlib.pyplot as plt
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            base = _bk_base(); H, W = base.shape[1], base.shape[2]; fps = float(fps_var.get())
            t0 = int(t0); t1 = int(t1); tt = np.arange(t0, t1)
            bm = _background_mask(H, W); ys, xs = np.nonzero(bm)
            if ys.size > 4000:
                sel = np.linspace(0, ys.size - 1, 4000).astype(int); ys = ys[sel]; xs = xs[sel]
            fg = _roi_pts('fg_roi'); d = _disp()
            fys = fxs = None
            if fg is not None:
                fys, fxs = _mask_coords(fg.astype(np.int32), fg_w.get(), H, W)
                fys = fys.astype(np.int32); fxs = fxs.astype(np.int32)
            qm, gfull = _fp_quiet_g()
            bg_raw = np.empty(len(tt)); bg_cor = np.empty(len(tt))
            dff_raw = np.empty(len(tt)); dff_cor = np.empty(len(tt))
            wd_raw = []; wd_cor = []
            try:
                from scipy.stats import wasserstein_distance as _wd
            except Exception:
                _wd = None
            prev_r = prev_c = None
            from scipy.ndimage import shift as nds
            for i, t in enumerate(tt):
                fr = np.asarray(base[t], np.float32)
                if d is not None and t < len(d):
                    fr = nds(fr, (-float(d[t, 0]), -float(d[t, 1])), order=1, mode='nearest')
                lut = _photo_map_frame(fr, t)
                cor = _frame_photo_apply(lut, t, fp)
                bpx_r = lut[ys, xs]; bpx_c = cor[ys, xs]
                bg_raw[i] = float(np.median(bpx_r)); bg_cor[i] = float(np.median(bpx_c))
                if fys is not None:
                    dff_raw[i] = float(np.mean(lut[fys, fxs])); dff_cor[i] = float(np.mean(cor[fys, fxs]))
                else:
                    dff_raw[i] = dff_cor[i] = np.nan
                if _wd is not None and prev_r is not None:
                    hb = np.linspace(min(bpx_r.min(), prev_r.min()), max(bpx_r.max(), prev_r.max()), 65)
                    wd_raw.append(_wd(np.histogram(prev_r, hb)[0], np.histogram(bpx_r, hb)[0]))
                    wd_cor.append(_wd(np.histogram(prev_c, hb)[0], np.histogram(bpx_c, hb)[0]))
                prev_r, prev_c = bpx_r, bpx_c
            bolm = qm[t0:t1] == False
            b0r = float(np.percentile(dff_raw[np.isfinite(dff_raw)], 10)) if np.isfinite(dff_raw).any() else 0.0
            b0c = float(np.percentile(dff_cor[np.isfinite(dff_cor)], 10)) if np.isfinite(dff_cor).any() else 0.0
            amp_raw = float(np.nanmax(dff_raw) - b0r); amp_cor = float(np.nanmax(dff_cor) - b0c)
            pct = 100.0 * abs(amp_cor - amp_raw) / (abs(amp_raw) + 1e-9)
            self._log(f"[fphoto] QC seg [{t0},{t1}): dF/F0 pulse amplitude change = {pct:.2f}% "
                      f"({'OK <2%' if pct < 2 else 'WARN >2% — correction eating signal'}); "
                      f"|corr(a,g)|={fp.get('r_a', 0):.2f} rejected={fp.get('rejected')}")
            with apply_nature_style():
                plt.rcParams['svg.fonttype'] = 'none'
                fig = Figure(figsize=nature_figsize_in('double', height_in=5.2), dpi=170, facecolor='white')
                axA = fig.add_subplot(2, 2, 1); axB = fig.add_subplot(2, 2, 2)
                axC = fig.add_subplot(2, 2, 3); axD = fig.add_subplot(2, 2, 4)
                ts = tt / fps
                axA.plot(ts, bg_raw, color='0.6', lw=0.6, label='raw (after LUT)')
                axA.plot(ts, bg_cor, color='#0072B2', lw=0.8, label='corrected')
                axA.fill_between(ts, np.minimum(bg_raw.min(), bg_cor.min()),
                                 np.maximum(bg_raw.max(), bg_cor.max()), where=bolm, color='#f4a582', alpha=0.25, lw=0)
                axA.legend(fontsize=5, frameon=False); axA.set_title('(a) background median/frame', fontsize=7)
                axA.set_xlabel('s')
                if fp.get('a') is not None:
                    axB.plot(ts, fp['a'], color='#D55E00', lw=0.9, label='a_t')
                    axB.plot(ts, fp['b'] / (np.max(np.abs(fp['b'])) + 1e-9), color='#009E73', lw=0.9, label='b_t (norm)')
                axB.fill_between(ts, -1, 1, where=bolm, color='#f4a582', alpha=0.25, lw=0)
                axB.legend(fontsize=5, frameon=False)
                axB.set_title(f"(b) a_t,b_t (flat over pulse); |r|={fp.get('r_a', 0):.2f}", fontsize=7)
                if wd_raw:
                    axC.plot(ts[1:], wd_raw, color='0.6', lw=0.6, label='raw')
                    axC.plot(ts[1:], wd_cor, color='#0072B2', lw=0.8, label='corrected')
                    axC.legend(fontsize=5, frameon=False)
                axC.set_title('(c) frame-to-frame bg W1 distance', fontsize=7); axC.set_xlabel('s')
                axD.plot(ts, dff_raw - b0r, color='0.6', lw=0.6, label='raw')
                axD.plot(ts, dff_cor - b0c, color='#0072B2', lw=0.8, label='corrected')
                axD.legend(fontsize=5, frameon=False)
                axD.set_title(f"(d) dF/F0: amplitude change {pct:.2f}% ({'OK' if pct < 2 else 'WARN'})", fontsize=7)
                axD.set_xlabel('s')
                for ax in (axA, axB, axC, axD):
                    ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
                fig.suptitle(f"Frame photometry QC — seg [{t0},{t1}) mode={fp.get('mode')} "
                             f"rejected={fp.get('rejected')}", fontsize=8)
                fig.tight_layout()
            win = tk.Toplevel(pw); win.title("Frame photometry QC"); win.geometry("1180x720")
            bar = ttk.Frame(win); bar.pack(side=tk.BOTTOM, fill=tk.X, padx=4, pady=3)
            ttk.Button(bar, text="Save Fig", command=lambda: _save_fig_dialog(fig, parent=win,
                       default_stem="frame_photometry_qc")).pack(side=tk.LEFT, padx=2)
            c = FigureCanvasTkAgg(fig, win); c.draw(); c.get_tk_widget().pack(fill=tk.BOTH, expand=True)

        def _photo_correct_sig(sig, t_index):
            """(sig - b_i)/a_i over ABSOLUTE frame indices — VALID ONLY for off/offset/affine. For
            any nonlinear model this is wrong (mean(g(x)) != g(mean(x))); log an ERROR and raise so
            callers switch to pixel-level mapping (_photo_map_px / _photo_map_frame)."""
            sig = np.asarray(sig, float)
            p = state.get('photo')
            if not p: return sig
            if p.get('model') not in ('off', 'offset', 'affine'):
                self._log(f"[photo] ERROR: _photo_correct_sig called with nonlinear model "
                          f"'{p.get('model')}'; mean(g(x)) != g(mean(x)) — use pixel-level mapping.")
                raise RuntimeError(f"_photo_correct_sig invalid for nonlinear model {p.get('model')}")
            bounds = state['boundaries']
            fi = np.array([file_index(bounds, int(t)) for t in np.asarray(t_index, int)])
            a = np.asarray(p['a'], float); b = np.asarray(p['b'], float)
            return (sig - b[fi]) / np.maximum(a[fi], 1e-6)

        def _photo_g_corr(g, bounds):
            """Harmonized g(t): for affine/offset use the scalar law; for nonlinear map the FG-mask
            pixels per frame then average (the correct path)."""
            p = state.get('photo')
            if not p or p.get('model') == 'off':
                return np.asarray(g, float)
            if p.get('model') in ('offset', 'affine'):
                return _photo_correct_sig(g, np.arange(len(g)))
            base = _bk_base(); H, W = base.shape[1], base.shape[2]
            fg_r = state.get('fg_roi')
            if fg_r is None or len(fg_r) < 2: return np.asarray(g, float)
            ys, xs = _mask_coords(fg_r, fg_w.get(), H, W)
            yi = ys.astype(np.int32); xi = xs.astype(np.int32)
            out = np.empty(len(g), float)
            for t in range(len(g)):
                out[t] = float(np.mean(_photo_map_px(np.asarray(base[t], np.float32)[yi, xi], t)))
            return out

        def _photo_samples(fi, quiet, bounds, nq, anchor_align=True):
            """STRATIFIED pixel samples for file `fi`: EQUAL counts (~10k) from vessel pixels (FG
            mask dilated by fg_w, plus the brightest 1% of the file's quiet median frame) and from
            background (remaining ROI pixels). Drift-aligned (warp by -d[t]) so all files sample the
            SAME anatomy. Returns a 1-D float array."""
            base = _bk_base(); T, H, W = base.shape[0], base.shape[1], base.shape[2]
            d = _disp() if anchor_align else None
            G = int(state.get('_bnd_guard', 1))
            f0, f1 = bounds[fi], bounds[fi + 1]
            idx = np.nonzero(quiet[f0:f1])[0] + f0
            if idx.size == 0:
                idx = np.arange(f0 + G, f1 - G) if (f1 - f0) > 2 * G else np.arange(f0, f1)
            if idx.size > nq:
                idx = idx[np.linspace(0, idx.size - 1, nq).astype(int)]
            if idx.size == 0: return np.array([])
            frs = []
            for t in idx:
                fr = np.asarray(base[t], np.float32)
                if d is not None and t < len(d):
                    from scipy.ndimage import shift as nds
                    fr = nds(fr, (-float(d[t, 0]), -float(d[t, 1])), order=1, mode='nearest')
                frs.append(fr)
            stackq = np.stack(frs, 0); med = np.median(stackq, 0)
            rect = state.get('reg_rect')
            if rect is None:
                bd = int(reg_border_px_var.get()); rect = (bd, bd, W - bd, H - bd)
            x0, y0, x1, y1 = rect
            roi = np.zeros((H, W), bool); roi[y0:y1, x0:x1] = True
            fg_r = state.get('fg_roi'); vmask = np.zeros((H, W), bool)
            if fg_r is not None and len(fg_r) >= 2:
                mm = np.zeros((H, W), np.uint8); exp = _expand_line(fg_r, int(fg_w.get()))
                if exp is not None:
                    cv2.fillPoly(mm, [exp], 1); vmask = mm > 0
            if roi.any():
                thr = float(np.percentile(med[roi], 99.0)); vmask = (vmask | (med >= thr)) & roi
            bmask = roi & (~vmask)
            vy, vx = np.nonzero(vmask); by, bx = np.nonzero(bmask)
            rng = np.random.default_rng(0)
            def _pull(ys, xs, n=10000):
                if ys.size == 0: return np.array([])
                fsel = rng.integers(0, stackq.shape[0], size=n)
                psel = rng.integers(0, ys.size, size=n)
                return stackq[fsel, ys[psel], xs[psel]]
            vs = _pull(vy, vx); bs = _pull(by, bx)
            out = np.concatenate([vs, bs]) if (vs.size or bs.size) else np.array([])
            return out

        def _boundary_step_metric(map_fn, quiet, bounds, pulse_amp, Kframes=10):
            """Residual boundary step MEASURED ON THE FG MASK. For each interior boundary: last K
            quiet frames of file i vs first K quiet frames of file i+1 (clear of the guard); map
            their FG pixels with map_fn(vals, file_idx), average per frame, median each side;
            step = |median_after - median_before|. Returns median(step)/median(pulse amplitude)."""
            base = _bk_base(); H, W = base.shape[1], base.shape[2]; d = _disp()
            G = int(state.get('_bnd_guard', 1)); fg_r = state.get('fg_roi')
            if fg_r is None or len(fg_r) < 2: return float('nan')
            ys, xs = _mask_coords(fg_r, fg_w.get(), H, W)
            def _side_median(fi, first):
                f0, f1 = bounds[fi], bounds[fi + 1]
                idx = np.nonzero(quiet[f0:f1])[0] + f0
                if (f1 - f0) > 2 * G:
                    idx = idx[(idx >= f0 + G) & (idx < f1 - G)]
                if idx.size == 0: return np.nan
                idx = idx[:Kframes] if first else idx[-Kframes:]
                vals = []
                for t in idx:
                    fr = np.asarray(base[t], np.float32)
                    dy, dx = (float(d[t, 0]), float(d[t, 1])) if (d is not None and t < len(d)) else (0.0, 0.0)
                    yi = np.clip(np.rint(ys + dy).astype(np.int32), 0, H - 1)
                    xi = np.clip(np.rint(xs + dx).astype(np.int32), 0, W - 1)
                    vals.append(float(np.mean(map_fn(fr[yi, xi], fi))))
                return float(np.median(vals)) if vals else np.nan
            steps = []
            for b in bounds[1:-1]:
                li = file_index(bounds, b - 1); ri = file_index(bounds, b)
                mb = _side_median(li, first=False); ma = _side_median(ri, first=True)
                if np.isfinite(mb) and np.isfinite(ma): steps.append(abs(ma - mb))
            return float(np.median(steps) / max(pulse_amp, 1e-9)) if steps else float('nan')

        def _photometric_align(prog=None):
            """Fit a LADDER of models (off -> offset -> affine -> quantileK -> histmatch) on
            STRATIFIED vessel+background samples and let the data pick the simplest sufficient one.
            Scalar correction is kept ONLY for affine/offset; nonlinear maps are applied per-pixel.
            Stores state['photo'] = dict(model, xk, yk, ref, score, ladder, guard, K, a, b)."""
            base = state.get('stack_orig') if state.get('stack_orig') is not None else state.get('stack')
            if base is None:
                messagebox.showwarning("Photometric", "Load files first."); return
            T, H, W = base.shape[0], base.shape[1], base.shape[2]
            bounds = list(state.get('boundaries') or [0, T]); n_files = len(bounds) - 1
            ref = int(photo_ref_var.get())
            if ref < 0:
                ref = file_index(bounds, int(np.clip(int(drift_anchor_var.get()), 0, T - 1)))
            ref = int(np.clip(ref, 0, n_files - 1))
            _bol, invalid, g = _quiet_mask_per_file(base, prog=prog)
            quiet = (~_bol) & (~invalid)
            G = int(state.get('_bnd_guard', 1)); K = int(photo_K_var.get())
            nq = int(photo_nquiet_var.get())
            pulse_amp = float(np.median([max(1e-9, float(np.max(g[bounds[i]:bounds[i + 1]]) -
                             np.median(g[bounds[i]:bounds[i + 1]]))) for i in range(n_files)]))
            self._log(f"[photo] stratified sampling (vessel+background), ref file = {ref}, "
                      f"pulse amp ~ {pulse_amp:.4g}, guard = {G}")
            samp = [_photo_samples(fi, quiet, bounds, nq) for fi in range(n_files)]
            for fi in range(n_files):
                self._log(f"[photo] file {fi}: {samp[fi].size} stratified samples")
            ref_s = samp[ref]
            LO, HI = 0.0, float(max(1.0, np.percentile(ref_s, 99.99) if ref_s.size else 1.0))

            def _build(model):
                """Return list of (xk, yk) per file for a model, each with linear tails so
                bolus-bright pixels beyond the quiet range are extrapolated, not clamped."""
                out = []
                for fi in range(n_files):
                    si = samp[fi]
                    if fi == ref or model == 'off' or si.size < 8 or ref_s.size < 8:
                        out.append((np.array([LO, HI]), np.array([LO, HI]))); continue
                    if model == 'offset':
                        db = float(np.median(ref_s) - np.median(si))
                        xk, yk = np.array([LO, HI]), np.array([LO + db, HI + db])
                    elif model == 'affine':
                        a, b = _qq_affine(si, ref_s)
                        xk = np.array([float(np.percentile(si, 0.5)), float(np.percentile(si, 99.9))])
                        yk = a * xk + b
                    elif model == 'histmatch':
                        xk, yk = _monotone_lut(si, ref_s, K=256)
                    else:                                   # 'quantile'
                        xk, yk = _monotone_lut(si, ref_s, K=K)
                    out.append(_extend_knots(xk, yk))
                return out

            ladder = ['off', 'offset', 'affine', f'quantile{K}', 'histmatch']
            base_models = ['off', 'offset', 'affine', 'quantile', 'histmatch']
            results = {}
            for name, mdl in zip(ladder, base_models):
                knots = _build(mdl)
                gains = [_lut_local_gain(xk, yk) for (xk, yk) in knots]
                gmin = min(gg[0] for gg in gains); gmax = max(gg[1] for gg in gains)
                map_fn = (lambda vals, fi, kn=knots: _apply_lut(vals, kn[fi][0], kn[fi][1]))
                score = _boundary_step_metric(map_fn, quiet, bounds, pulse_amp)
                ok_gain = (gmin >= 0.2) and (gmax <= 5.0)
                results[name] = dict(mdl=mdl, knots=knots, score=score, gmin=gmin, gmax=gmax, ok_gain=ok_gain)
                self._log(f"[photo] ladder {name:12s}: step={score*100:6.2f}% of pulse amp  "
                          f"local_gain=[{gmin:.3f},{gmax:.3f}]  gain_ok={ok_gain}")
            target = float(photo_target_var.get())
            want = photo_model_var.get()
            chosen = None
            if want == 'auto':
                for name in ladder:
                    r = results[name]
                    if r['ok_gain'] and np.isfinite(r['score']) and r['score'] < target:
                        chosen = name; break
                if chosen is None:                          # nothing met target -> best gain-valid score
                    valid = [(results[n]['score'], n) for n in ladder
                             if results[n]['ok_gain'] and np.isfinite(results[n]['score'])]
                    chosen = min(valid)[1] if valid else 'off'
                    self._log(f"[photo] no model met target {target*100:.1f}% — using best valid '{chosen}'.")
            else:
                nm = {'off': 'off', 'offset': 'offset', 'affine': 'affine',
                      'quantile': f'quantile{K}', 'histmatch': 'histmatch'}.get(want, want)
                chosen = nm if nm in results else 'off'
                if not results[chosen]['ok_gain']:
                    self._log(f"[photo] WARNING: requested '{chosen}' local gain "
                              f"[{results[chosen]['gmin']:.3f},{results[chosen]['gmax']:.3f}] "
                              f"outside [0.2,5.0].")
            R = results[chosen]; knots = R['knots']; mdl = R['mdl']
            xk = [np.asarray(k[0], float).tolist() for k in knots]
            yk = [np.asarray(k[1], float).tolist() for k in knots]
            photo = dict(model=mdl, xk=xk, yk=yk, ref=ref, score=float(R['score']),
                         ladder={n: dict(score=results[n]['score'], gmin=results[n]['gmin'],
                                         gmax=results[n]['gmax'], ok_gain=results[n]['ok_gain'])
                                 for n in ladder},
                         guard=G, K=K, r2=[1.0] * n_files)
            if mdl in ('off', 'offset', 'affine'):          # keep scalar a,b for backward compat
                a = np.ones(n_files); b = np.zeros(n_files)
                for fi in range(n_files):
                    x0k, x1k = knots[fi][0][0], knots[fi][0][-1]
                    y0k, y1k = knots[fi][1][0], knots[fi][1][-1]
                    a[fi] = (y1k - y0k) / max(x1k - x0k, 1e-9); b[fi] = y0k - a[fi] * x0k
                photo['a'] = a.tolist(); photo['b'] = b.tolist()
            state['photo'] = photo
            self._log(f"[photo] SELECTED model = {mdl}  (score {R['score']*100:.2f}% of pulse amp, "
                      f"local gain [{R['gmin']:.3f},{R['gmax']:.3f}])")
            if mdl not in ('off', 'offset', 'affine'):
                self._log("[photo] WARNING: a NONLINEAR photometric model was selected — intensity "
                          "linearity is no longer preserved; report dF/F0, not raw F.")
            status_v.set(f"Harmonized {n_files} files -> ref {ref} ({mdl}, {R['score']*100:.1f}%).")
            return state['photo']

        def _run_auto_guard():
            base = _bk_base()
            if base is None:
                messagebox.showwarning("Auto guard", "Load files first."); return
            with _Progress("Auto guard: g(t)", total=base.shape[0]) as _p:
                g, _px = _vessel_g(base, prog=_p)
            G = _auto_boundary_guard(g)
            bnd_guard_var.set(int(G)); state['_bnd_guard'] = int(G)
            self._log(f"[bnd] auto boundary guard G = {G} frames (per-boundary transient length)")
            status_v.set(f"Auto boundary guard = {G} frames.")

        def _fig_boundary_qc():
            """QC figure proving the boundary artifact is gone and quantifying the residual step."""
            import matplotlib.pyplot as plt
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            base = _bk_base()
            if base is None:
                messagebox.showwarning("Boundary QC", "Load files first."); return
            T = base.shape[0]; bounds = list(state.get('boundaries') or [0, T])
            fps = float(fps_var.get()); n_files = len(bounds) - 1
            if n_files < 2:
                messagebox.showwarning("Boundary QC", "Need at least 2 files."); return
            with _Progress("Boundary QC: g(t)", total=T) as _p:
                g, _px = _vessel_g(base, prog=_p)
            gcorr = _photo_g_corr(g, bounds)               # correct for any model (incl. nonlinear)
            gmed = np.array([float(np.median(g[bounds[i]:bounds[i + 1]])) for i in range(n_files)])
            pulse_amp = float(np.median([max(1e-9, float(np.max(g[bounds[i]:bounds[i + 1]]) -
                             np.median(g[bounds[i]:bounds[i + 1]]))) for i in range(n_files)]))
            interior = [int(b) for b in bounds[1:-1]]
            sb, sa = [], []
            for bi in interior:
                li = file_index(bounds, bi - 1); ri = file_index(bounds, bi)
                sb.append(abs(gmed[li] - gmed[ri]))
                sa.append(abs(float(np.median(gcorr[bounds[li]:bounds[li + 1]])) -
                              float(np.median(gcorr[bounds[ri]:bounds[ri + 1]]))))
            bsi = float(np.median(sa) / pulse_amp) if interior else 0.0
            passed = bsi < 0.05
            # rectified difference mass: boundary stencils vs interior stencils
            ys, xs = _px
            def _mass(t):
                if t <= 0 or t >= T - 1: return np.nan
                D = np.asarray(base[t + 1], np.float32)[ys, xs] - np.asarray(base[t - 1], np.float32)[ys, xs]
                return float(np.sum(np.maximum(D, 0.0)))
            bnd_mass = [m for m in (_mass(bi) for bi in interior) if np.isfinite(m)]
            rng = np.random.default_rng(0); inter_t = []
            for i in range(n_files):
                cand = np.arange(bounds[i] + 2, bounds[i + 1] - 2)
                if cand.size:
                    inter_t.extend(cand[rng.integers(0, cand.size, min(cand.size, 40))].tolist())
            inter_mass = [m for m in (_mass(t) for t in inter_t) if np.isfinite(m)]
            p = state.get('photo')
            with apply_nature_style():
                plt.rcParams['svg.fonttype'] = 'none'
                fig = Figure(figsize=nature_figsize_in('double', height_in=6.6), dpi=180, facecolor='white')
                axA = fig.add_subplot(2, 3, 1); axB = fig.add_subplot(2, 3, 2); axC = fig.add_subplot(2, 3, 3)
                axD = fig.add_subplot(2, 3, 4); axE = fig.add_subplot(2, 3, 5); axF = fig.add_subplot(2, 3, 6)
                tg = np.arange(T) / fps
                axA.plot(tg, g, color='0.6', lw=0.4, label='raw')
                axA.plot(tg, gcorr, color='#0072B2', lw=0.4, label='harmonized')
                for bi in interior: axA.axvline(bi / fps, color='#e0e040', lw=0.6, ls='--')
                axA.legend(fontsize=5, frameon=False); axA.set_title('(a) g(t) raw vs harmonized', fontsize=7)
                axA.set_xlabel('s')
                axB.plot(gmed, [float(np.median(gcorr[bounds[i]:bounds[i + 1]])) for i in range(n_files)],
                         'o', color='#0072B2', ms=4)
                _rr = [gmed.min(), gmed.max()]
                axB.plot(_rr, [gmed[p['ref']] if p else gmed[0]] * 2, '--', color='#d62728', lw=0.8)
                axB.set_xlabel('baseline before'); axB.set_ylabel('baseline after')
                axB.set_title('(b) per-file baseline collapse', fontsize=7)
                if p:
                    xf = np.arange(n_files)
                    model = str(p.get('model', 'off'))
                    a = np.asarray(p.get('a', np.ones(n_files)), float)
                    b = np.asarray(p.get('b', np.zeros(n_files)), float)
                    if model in ('off', 'offset', 'affine'):
                        axC.bar(xf - 0.2, a, 0.4, color='#0072B2', label='a_i')
                        axC.bar(xf + 0.2, b / (np.abs(b).max() + 1e-9), 0.4,
                                color='#D55E00', label='b_i (norm)')
                        r2 = p.get('r2')
                        if r2 is not None:
                            for i in xf: axC.text(i, a[i], f"{float(r2[i]):.2f}", fontsize=4, ha='center')
                        axC.set_title(f'(c) per-file a_i, b_i  [{model}]', fontsize=7)
                    else:
                        # nonlinear LUT: report the local-gain range per file instead of a_i/b_i
                        lo = np.ones(n_files); hi = np.ones(n_files)
                        for i in range(n_files):
                            try: lo[i], hi[i] = _lut_local_gain(p['xk'][i], p['yk'][i])
                            except Exception: pass
                        axC.bar(xf - 0.2, lo, 0.4, color='#0072B2', label='min dy/dx')
                        axC.bar(xf + 0.2, hi, 0.4, color='#D55E00', label='max dy/dx')
                        axC.axhline(1.0, color='k', lw=0.5, ls='--')
                        axC.set_title(f'(c) per-file local gain  [{model}]', fontsize=7)
                    axC.legend(fontsize=5, frameon=False)
                axC.set_xlabel('file')
                xb = np.arange(len(interior))
                axD.bar(xb - 0.2, np.array(sb) / pulse_amp * 100, 0.4, color='0.6', label='before')
                axD.bar(xb + 0.2, np.array(sa) / pulse_amp * 100, 0.4, color='#0072B2', label='after')
                axD.axhline(5.0, color='#d62728', ls='--', lw=0.8)
                axD.legend(fontsize=5, frameon=False); axD.set_xlabel('interior boundary')
                axD.set_ylabel('step (% pulse amp)'); axD.set_title('(d) boundary step before/after', fontsize=7)
                if inter_mass:
                    axE.hist(inter_mass, bins=20, color='0.6', alpha=0.7, label='interior')
                if bnd_mass:
                    for m in bnd_mass: axE.axvline(m, color='#d62728', lw=1.0)
                axE.legend(fontsize=5, frameon=False); axE.set_xlabel('rectified diff mass')
                axE.set_title('(e) boundary (red) vs interior stencils', fontsize=7)
                axF.axis('off')
                axF.text(0.02, 0.9, f"boundary_step_index = {bsi*100:.2f}%\n(target < 5%)\n\n"
                         f"{'PASS' if passed else 'FAIL'}", fontsize=11,
                         color=('#1b7837' if passed else '#d62728'), va='top',
                         fontweight='bold', transform=axF.transAxes)
                axF.text(0.02, 0.4, f"pulse amp ~ {pulse_amp:.3g}\nfiles = {n_files}\n"
                         f"ref = {p['ref'] if p else 'n/a'}  mode = {p.get('model', 'none') if p else 'none'}\n"
                         f"guard G = {state.get('_bnd_guard', 'n/a')}", fontsize=7,
                         va='top', transform=axF.transAxes)
                for ax in (axA, axB, axC, axD, axE):
                    ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
                fig.suptitle("File-boundary QC", fontsize=9); fig.tight_layout()
            self._log(f"[QC] boundary_step_index = {bsi*100:.2f}% of pulse amp -> "
                      f"{'PASS' if passed else 'FAIL'} (target < 5%)")
            win = tk.Toplevel(pw); win.title("Boundary QC"); win.geometry("1300x800")
            bar = ttk.Frame(win); bar.pack(side=tk.BOTTOM, fill=tk.X, padx=4, pady=3)
            ttk.Button(bar, text="Save Fig", command=lambda: _save_fig_dialog(fig, parent=win,
                       default_stem="boundary_qc")).pack(side=tk.LEFT, padx=2)
            c = FigureCanvasTkAgg(fig, win); c.draw(); c.get_tk_widget().pack(fill=tk.BOTH, expand=True)

        def _self_test_photometric():
            """Synthesize a second 'file' from file 0 with a KNOWN (a=1.35, b=+40), append it with
            a synthetic boundary, and verify recovery, harmonized step, frame-guard, and that the
            per-file mask does NOT flag the boundary (whereas a global threshold does)."""
            base = _bk_base()
            if base is None:
                messagebox.showwarning("Self-test", "Load files first."); return
            bounds = list(state.get('boundaries') or [0, base.shape[0]])
            n0 = min(bounds[1] if len(bounds) > 1 else base.shape[0], 300)
            if n0 < 20:
                messagebox.showwarning("Self-test", "Need >=20 frames in file 0."); return
            A_TRUE, B_TRUE = 1.35, 40.0
            f0 = np.stack([np.asarray(base[t], np.float32) for t in range(n0)], 0)
            f1 = A_TRUE * f0 + B_TRUE
            synth = np.concatenate([f0, f1], 0)
            drange = float(np.percentile(f0, 99) - np.percentile(f0, 1)) + 1e-9
            # ---- swap in synthetic state ----
            save = {k: state.get(k) for k in ('stack', 'stack_orig', 'boundaries', 'photo',
                                              '_invalid_frames', '_bnd_guard', 'drift',
                                              'frame_map', 'stack_uid', 'root', 'provenance', '_invmap_cache')}
            msgs = []; ok = True
            try:
                state['stack'] = synth; state['stack_orig'] = None
                state['boundaries'] = [0, n0, 2 * n0]
                _on_stack_changed(make_root_map(synth.shape[0]), boundaries=[0, n0, 2 * n0],
                                  remap=False, note='selftest_photometric')
                state['photo'] = None; state['drift'] = None
                state['_invalid_frames'] = None; state['_bnd_guard'] = 0
                photo = _photometric_align()
                a_rec = float(photo.get('a', [1.0, 1.0])[1]); b_rec = float(photo.get('b', [0.0, 0.0])[1])
                da = abs(a_rec - A_TRUE) / A_TRUE * 100.0
                db = abs(b_rec - B_TRUE) / drange * 100.0
                c1 = da <= 2.0 and db <= 2.0
                msgs.append(f"model={photo['model']} recover a={a_rec:.3f} (true {A_TRUE}, err {da:.2f}%), "
                            f"b={b_rec:+.2f} (true {B_TRUE}, err {db:.2f}% of range) -> {'OK' if c1 else 'FAIL'}")
                ok &= c1
                g, _px = _vessel_g(synth)
                gcorr = _photo_g_corr(g, [0, n0, 2 * n0])
                pa = max(1e-9, float(np.max(g[:n0]) - np.median(g[:n0])))
                step_after = abs(float(np.median(gcorr[:n0]) - np.median(gcorr[n0:]))) / pa * 100.0
                c2 = step_after < 1.0
                msgs.append(f"harmonized boundary step = {step_after:.3f}% of pulse amp -> "
                            f"{'OK' if c2 else 'FAIL'} (<1%)"); ok &= c2
                # frame-guard: exactly the straddling central stencils dropped (guard=0)
                tlist, dropped = _valid_diff_frames(0, 2 * n0, 'central', 1, guard=0)
                expected = [t for t in range(1, 2 * n0 - 1) if not same_file([0, n0, 2 * n0], t - 1, t, t + 1)]
                c3 = (dropped == len(expected)) and all(t not in tlist for t in expected)
                msgs.append(f"valid_diff dropped {dropped} straddling stencils "
                            f"(expected {len(expected)}: {expected}) -> {'OK' if c3 else 'FAIL'}"); ok &= c3
                # per-file mask must NOT flag the boundary as bolus; global threshold does
                bol, invalid, gg = _quiet_mask_per_file(synth)
                perfile_bnd = bool(bol[n0]) or bool(bol[n0 - 1])
                gm = float(np.median(gg)); gmad = 1.4826 * float(np.median(np.abs(gg - gm))) + 1e-9
                glob = gg > (gm + float(bolus_k_var.get()) * gmad)
                global_bnd = bool(glob[n0:].mean() > 0.5)
                c4 = (not perfile_bnd) and global_bnd
                msgs.append(f"per-file flags boundary as bolus = {perfile_bnd} (want False); "
                            f"global flags file-2 = {global_bnd} (want True) -> {'OK' if c4 else 'FAIL'}")
                ok &= c4
            finally:
                for k, v in save.items():
                    (state.__setitem__(k, v) if v is not None else state.pop(k, None))
            report = "PHOTOMETRIC SELF-TEST: " + ("PASS" if ok else "FAIL") + "\n\n" + "\n".join(msgs)
            self._log("[selftest] " + report.replace("\n", "\n[selftest] "))
            (messagebox.showinfo if ok else messagebox.showerror)("Photometric self-test", report)

        def _self_test_photo_lut():
            """Duplicate file 0 and apply a KNOWN monotone NONLINEAR map (y=0.8x+4e-4 x²). The
            ladder must skip 'affine' (score>target), pick quantile/histmatch, drive the FG step
            <1%, make _photo_correct_sig RAISE, and show mean(g(x)) != g(mean(x)) by >1%."""
            base = _bk_base()
            if base is None:
                messagebox.showwarning("Self-test", "Load files first."); return
            if state.get('fg_roi') is None or len(state['fg_roi']) < 2:
                messagebox.showwarning("Self-test", "Draw the FG line ROI first."); return
            bounds0 = list(state.get('boundaries') or [0, base.shape[0]])
            n0 = min(bounds0[1] if len(bounds0) > 1 else base.shape[0], 300)
            if n0 < 20:
                messagebox.showwarning("Self-test", "Need >=20 frames in file 0."); return
            f0 = np.stack([np.asarray(base[t], np.float32) for t in range(n0)], 0)
            f1 = 0.8 * f0 + 4e-4 * f0 ** 2                  # monotone increasing for f0>=0
            synth = np.concatenate([f0, f1], 0)
            save = {k: state.get(k) for k in ('stack', 'stack_orig', 'boundaries', 'photo',
                                              '_invalid_frames', '_bnd_guard', 'drift',
                                              'frame_map', 'stack_uid', 'root', 'provenance', '_invmap_cache')}
            old_model = photo_model_var.get(); old_ref = photo_ref_var.get()
            msgs = []; ok = True
            try:
                state['stack'] = synth; state['stack_orig'] = None
                state['boundaries'] = [0, n0, 2 * n0]
                _on_stack_changed(make_root_map(synth.shape[0]), boundaries=[0, n0, 2 * n0],
                                  remap=False, note='selftest_photo_lut')
                state['photo'] = None; state['drift'] = None
                state['_invalid_frames'] = None; state['_bnd_guard'] = 0
                photo_model_var.set('auto'); photo_ref_var.set(0)
                photo = _photometric_align()
                lad = photo['ladder']; target = float(photo_target_var.get())
                aff = lad.get('affine', {}).get('score', float('nan'))
                c1 = not (np.isfinite(aff) and aff < target)
                msgs.append(f"affine step={aff*100:.2f}% must exceed target {target*100:.1f}% "
                            f"-> {'OK' if c1 else 'FAIL'}"); ok &= c1
                c2 = photo['model'] in ('quantile', 'histmatch')
                msgs.append(f"selected model={photo['model']} in (quantile,histmatch) "
                            f"-> {'OK' if c2 else 'FAIL'}"); ok &= c2
                g, _px = _vessel_g(synth); gcorr = _photo_g_corr(g, [0, n0, 2 * n0])
                pa = max(1e-9, float(np.max(g[:n0]) - np.median(g[:n0])))
                step = abs(float(np.median(gcorr[:n0]) - np.median(gcorr[n0:]))) / pa * 100.0
                c3 = step < 1.0
                msgs.append(f"residual FG step={step:.3f}% (<1%) -> {'OK' if c3 else 'FAIL'}"); ok &= c3
                raised = False
                try:
                    _photo_correct_sig(g, np.arange(len(g)))
                except Exception:
                    raised = True
                msgs.append(f"_photo_correct_sig raises on nonlinear = {raised} "
                            f"-> {'OK' if raised else 'FAIL'}"); ok &= raised
                H, W = synth.shape[1], synth.shape[2]
                ys, xs = _mask_coords(state['fg_roi'], fg_w.get(), H, W)
                yi = ys.astype(np.int32); xi = xs.astype(np.int32); tt = n0 + n0 // 2
                px = np.asarray(synth[tt], np.float32)[yi, xi]
                pix_then_mean = float(np.mean(_photo_map_px(px, tt)))
                mean_then_map = float(_apply_lut(np.array([px.mean()]),
                                      np.asarray(photo['xk'][1]), np.asarray(photo['yk'][1]))[0])
                rel = abs(pix_then_mean - mean_then_map) / max(abs(pix_then_mean), 1e-9) * 100.0
                c5 = rel > 1.0
                msgs.append(f"mean(g(x)) vs g(mean(x)) differ by {rel:.2f}% (>1%) "
                            f"-> {'OK' if c5 else 'FAIL'}"); ok &= c5
            finally:
                for k, v in save.items():
                    (state.__setitem__(k, v) if v is not None else state.pop(k, None))
                photo_model_var.set(old_model); photo_ref_var.set(old_ref)
            report = "PHOTO LUT SELF-TEST: " + ("PASS" if ok else "FAIL") + "\n\n" + "\n".join(msgs)
            self._log("[selftest] " + report.replace("\n", "\n[selftest] "))
            (messagebox.showinfo if ok else messagebox.showerror)("Photo LUT self-test", report)

        # ════════════ Unified segment store (single source of truth) ════════════
        def _roi_pts(key):
            """ROI points as an (N,2) float ndarray, or None. `state[key]` is written as a python
            list by the canvas handler and as an np.int32 array by the ROI-set loader; every reader
            must go through here. Never put a raw ndarray in a boolean context."""
            v = state.get(key)
            if v is None: return None
            a = np.asarray(v, dtype=float)
            return a if a.ndim == 2 and a.shape[0] >= 2 else None

        def _segments():
            return state['segments']

        def _seg_reindex():
            for i, s in enumerate(state['segments']): s['idx'] = i

        # ════════════ Frame-provenance contract (root map + stack identity) ════════════
        def _fmap():
            return state.get('frame_map')

        def _uid():
            return state.get('stack_uid', '')

        def _to_root(i):
            fm = _fmap()
            return int(fm[int(i)]) if fm is not None else int(i)

        def _root_T():
            r = state.get('root') or {}
            fm = _fmap()
            return int(r.get('T', (int(fm.max()) + 1 if (fm is not None and len(fm)) else 0)))

        def _to_local(r):
            """root index -> local index (via cached invert_map), or -1 if absent."""
            fm = _fmap()
            if fm is None: return int(r)
            cache = state.get('_invmap_cache')
            if not cache or cache.get('uid') != _uid():
                rootT = max(_root_T(), int(fm.max()) + 1 if len(fm) else 0)
                cache = dict(uid=_uid(), inv=invert_map(fm, rootT))
                state['_invmap_cache'] = cache
            inv = cache['inv']; r = int(r)
            return int(inv[r]) if 0 <= r < len(inv) else -1

        def _root_fps():
            return float((state.get('root') or {}).get('fps') or fps_var.get())

        def _root_time(i):
            return _to_root(i) / _root_fps()

        def _root_file(i):
            rb = (state.get('root') or {}).get('boundaries')
            if rb is None:
                return file_index(list(state.get('boundaries') or [0, 1]), _to_root(i))
            return file_index(rb, _to_root(i))

        def _bump_uid():
            from uuid import uuid4
            state['stack_uid'] = uuid4().hex[:12]
            return state['stack_uid']

        def _on_stack_changed(new_map, root=None, boundaries=None, note='', remap=True, uid=None,
                              carry=True, local_idx=None):
            """Single choke point for installing a stack: set frame_map, bump stack_uid (or set the
            given `uid` when restoring a sidecar), CARRY demotion (drift) and photometry through the
            extraction, reset only the truly index-tied caches, update the slider, and offer to REMAP
            the existing segments (never silently keep stale indices).

            Drift `d` is a displacement relative to an anchor frame, so `d[local_idx]` re-anchored is
            EXACT. Photometry is keyed by ROOT FILE (via `_root_file`), so `state['photo']` survives
            an extraction untouched — it must NOT be reset here."""
            old_drift = state.get('drift'); old_uid = _uid()
            state['frame_map'] = np.asarray(new_map, np.int64)
            if uid is not None:
                state['stack_uid'] = str(uid)
            else:
                _bump_uid()
            if root is not None: state['root'] = root
            if boundaries is not None: state['boundaries'] = list(boundaries)
            # ── carry demotion (drift): subset per-frame arrays by local_idx, then RE-ANCHOR ──
            if carry and old_drift is not None and local_idx is not None:
                li = np.asarray(local_idx, np.int64); n = int(li.size)
                d = np.asarray(old_drift['d'], np.float32)[li]
                a_local = int(np.argmin(np.abs(li - int(old_drift.get('anchor', 0)))))
                d = d - d[a_local]                                   # exact re-anchoring
                nd = dict(old_drift)
                nd['bins'] = None                                    # root-space bin structure no longer valid
                nd.update(d=d.astype(np.float32), shifts=(-d).astype(np.float32),
                          anchor=a_local, carried_from=old_uid,
                          base_shape=(n,) + tuple(old_drift.get('base_shape', (n,))[1:]))
                for k in ('quality', 'valid', 'bolus', 'gsig'):
                    v = old_drift.get(k)
                    if v is not None and len(np.asarray(v)) == len(li) + 0 or \
                       (v is not None and np.asarray(v).ndim >= 1 and np.asarray(v).shape[0] >= (int(li.max()) + 1)):
                        try: nd[k] = np.asarray(v)[li]
                        except Exception: nd[k] = None
                state['drift'] = nd
                dmag = np.hypot(d[:, 0], d[:, 1])
                self._log(f"[stack] drift carried: n={n}, anchor local {a_local}, "
                          f"|d| range {float(dmag.min()):.1f}..{float(dmag.max()):.1f} px "
                          f"(from uid {old_uid[:8]})")
            else:
                state['drift'] = None
                if old_drift is not None:
                    self._log("[stack] drift reset (no parent / carry off) — one FG will sample "
                              "DIFFERENT anatomy across root time without demotion.")
                else:
                    self._log("[stack] drift reset (no parent).")
            state['stack_corrected'] = None
            # NOTE: state['photo'] is NOT reset — it is keyed by ROOT FILE and survives extraction.
            state['_bk_cache'] = {}; state['_disp_range'] = None
            state['_invalid_frames'] = None; state['_fp_quiet'] = None; state['_fp_g'] = None
            state['_fp_current'] = None; state['_invmap_cache'] = None
            state['provenance'] = state.get('provenance') or []
            T = int(len(state['frame_map']))
            try:
                frame_scale.configure(to=max(0, T - 1)); frame_var.set(0)
                state['current_frame'] = 0; frame_lbl.config(text=f"0/{max(0, T-1)}")
            except Exception:
                pass
            _lo = int(state['frame_map'].min()) if T else 0
            _hi = int(state['frame_map'].max()) + 1 if T else 0
            self._log(f"[prov] stack changed ({note}): uid={_uid()} T={T} "
                      f"root_span=[{_lo},{_hi}) level={len(state.get('provenance') or [])}")
            if remap and state.get('segments'):
                _remap_segments_to_current()

        def _seg_included():
            """Refuse stale segments (defined in a different stack) instead of indexing OOB."""
            segs = [s for s in state['segments'] if s.get('include', True)]
            bad = [s for s in segs if s.get('uid') != _uid()]
            if bad:
                raise RuntimeError(
                    f"{len(bad)} segment(s) were defined in a different stack "
                    f"(uid {bad[0].get('uid')} vs current {_uid()}). "
                    f"Use 'Remap segments to current stack' or reload the matching frame map.")
            return segs

        def _remap_segments_to_current(auto=False):
            """Map every segment's ROOT indices into the current local space (invert_map). Segments
            present-and-contiguous -> one remapped segment; present-but-split -> contiguous runs
            (each keeps root_idx); fewer than min_dur frames survive -> dropped. Shows a before/after
            table and requires confirm unless `auto`."""
            segs = list(state.get('segments') or [])
            if not segs: return True
            fm = _fmap()
            if fm is None: return True
            rootT = max(_root_T(), int(fm.max()) + 1 if len(fm) else 0)
            inv = invert_map(fm, rootT)
            fps = float(fps_var.get()); min_frames = max(3, int(float(seg_min_dur_s_var.get()) * fps))
            new_segments = []; lines = []
            for s in segs:
                if s.get('root_idx') is not None:
                    root_idx = np.asarray(s['root_idx'], np.int64)
                else:
                    root_idx = np.arange(int(s.get('root_t0', s['t0'])),
                                         int(s.get('root_t1', s['t1'])), dtype=np.int64)
                nb = int(root_idx.size)
                local = np.array([inv[r] if 0 <= r < len(inv) else -1 for r in root_idx], np.int64)
                present = np.sort(local[local >= 0])
                rr0 = int(root_idx[0]); rr1 = int(root_idx[-1]) + 1
                if present.size < min_frames:
                    lines.append(f"  seg#{s.get('idx')} root[{rr0},{rr1}) N={nb} -> DROP "
                                 f"(only {present.size} frames present)")
                    continue
                runs = runs_from_root(present)          # runs of contiguous LOCAL indices
                for ri, (l0, l1) in enumerate(runs):
                    if l1 - l0 < min_frames:
                        lines.append(f"  seg#{s.get('idx')} run local[{l0},{l1}) -> DROP (< min_dur)")
                        continue
                    rslice = fm[l0:l1]; contig = bool(np.all(np.diff(rslice) == 1))
                    ns = dict(s); ns.update(t0=int(l0), t1=int(l1), t_peak=int((l0 + l1) // 2),
                                            uid=_uid(), root_t0=int(rslice[0]), root_t1=int(rslice[-1]) + 1,
                                            t_peak_root=int(fm[(l0 + l1) // 2]),
                                            root_idx=(None if contig else rslice.astype(np.int64).tolist()),
                                            result=None)
                    new_segments.append(ns)
                    tag = '' if len(runs) == 1 else f' [split {ri+1}/{len(runs)}]'
                    lines.append(f"  seg#{s.get('idx')} root[{rr0},{rr1}) N={nb} -> "
                                 f"local[{l0},{l1}) N={l1-l0}{tag}")
                if len(runs) > 1:
                    self._log(f"[remap] seg#{s.get('idx')} split into {len(runs)} runs by the extraction.")
            table = (f"Remap {len(segs)} segment(s) to current stack (uid {_uid()}):\n\n"
                     + "\n".join(lines) + f"\n\nResult: {len(new_segments)} segment(s).")
            self._log("[remap]\n" + table)
            if not auto:
                if not messagebox.askokcancel("Remap segments to current stack", table):
                    return False
            for i, s in enumerate(new_segments): s['idx'] = i
            state['segments'] = new_segments
            self._log(f"[remap] committed {len(new_segments)} segment(s) at uid {_uid()}.")
            return True

        # ════════════ Concat extraction that composes (with sidecars) ════════════
        def _concat_extract(segments, note=''):
            """Build a new stack from the selected segments of the CURRENT stack. The new frame_map
            still points at the ROOT (compose_map), so repeated extractions compose automatically.
            Each extracted segment becomes a 'file' (boundary) of the new stack."""
            base = _bk_base()
            if base is None:
                messagebox.showwarning("Extract", "Load files first."); return
            segs = sorted(segments, key=lambda s: int(s['t0']))
            if not segs:
                messagebox.showwarning("Extract", "No segments selected."); return
            local_idx = np.concatenate([np.arange(int(s['t0']), int(s['t1'])) for s in segs]).astype(np.int64)
            new_stack = np.asarray(base[local_idx], np.float32)                 # materialize (copy)
            new_map = compose_map(state['frame_map'], local_idx)
            lens = [int(s['t1']) - int(s['t0']) for s in segs]
            new_bounds = list(np.concatenate([[0], np.cumsum(lens)]).astype(int))
            state['provenance'] = state.get('provenance') or []
            lvl = _stack_level() + 1
            drift_in = state.get('drift') is not None
            photo_in = str((state.get('photo') or {}).get('model', 'off')) != 'off'
            state['provenance'].append(dict(
                level=lvl, parent_uid=_uid(), n_in=int(base.shape[0]), n_out=int(len(local_idx)),
                segments=[(int(s.get('root_t0', s['t0'])), int(s.get('root_t1', s['t1']))) for s in segs],
                drift_carried=bool(drift_in), photo_carried=bool(photo_in),
                note=note, ts=__import__('datetime').datetime.now().isoformat(timespec='seconds')))
            state['stack'] = new_stack; state['stack_orig'] = None
            _on_stack_changed(new_map, root=state.get('root'), boundaries=new_bounds,
                              note=f'extract L{lvl}', remap=True, carry=True, local_idx=local_idx)
            self._log(f"[extract] level {lvl}: {int(base.shape[0])} -> {int(len(local_idx))} frames "
                      f"from {len(segs)} segments; per-segment N = {lens}, TOTAL = {int(len(local_idx))} "
                      f"(root ranges "
                      f"{[(int(s.get('root_t0', s['t0'])), int(s.get('root_t1', s['t1']))) for s in segs]})")
            status_v.set(f"Extracted level {lvl}: {int(len(local_idx))} frames ({len(segs)} segments)")
            try: _display()
            except Exception: pass

        def _export_concat(path_stem):
            """Write <stem>.tif + <stem>_framemap.json + <stem>_framemap.csv (reversible/auditable)."""
            import tifffile, json as _json, hashlib, csv as _csv
            base = _bk_base(); fm = _fmap()
            if base is None or fm is None:
                messagebox.showwarning("Export", "Nothing to export."); return
            tif = path_stem + '.tif'
            tifffile.imwrite(tif, np.asarray(base, np.float32))
            sha = hashlib.sha1(open(tif, 'rb').read()).hexdigest()
            root = state.get('root') or {}; prov = state.get('provenance') or []
            bounds = list(state.get('boundaries') or [0, int(base.shape[0])])
            fps = float(fps_var.get())
            doc = dict(schema='frame_provenance/2', uid=_uid(),
                       parent_uid=(prov[-1].get('parent_uid') if prov else None),
                       level=(prov[-1].get('level') if prov else 0),
                       fps=fps, px_um=float(px_var.get()),
                       root=dict(files=root.get('files'), boundaries=root.get('boundaries'), T=root.get('T')),
                       boundaries=bounds, frame_map=[int(x) for x in fm],
                       segments=[(int(s.get('root_t0', s['t0'])), int(s.get('root_t1', s['t1'])))
                                 for s in state.get('segments', [])],
                       provenance=prov, sha1=sha)
            # ── carry demotion (drift) + photometry into the sidecar so the extraction is portable ──
            dr = state.get('drift')
            if dr is not None:
                import base64
                dd = np.asarray(dr['d'], np.float16)
                doc['drift'] = True
                doc['drift_d'] = base64.b64encode(dd.tobytes()).decode('ascii')
                doc['drift_shape'] = list(dd.shape)
                doc['drift_anchor'] = int(dr.get('anchor', 0))
                doc['drift_mode'] = str(dr.get('mode', ''))
                doc['drift_carried_from'] = dr.get('carried_from')
            else:
                doc['drift'] = False
            ph = state.get('photo')
            doc['photo'] = str((ph or {}).get('model', 'off'))
            doc['photo_full'] = ph                                # a/b/xk/yk per ROOT file (JSON-serialisable)
            with open(path_stem + '_framemap.json', 'w') as f:
                _json.dump(doc, f, indent=2, default=str)
            with open(path_stem + '_framemap.csv', 'w', newline='') as f:
                w = _csv.writer(f)
                w.writerow(['local_index', 'root_index', 'root_time_s', 'root_file', 'segment_id'])
                for i in range(len(fm)):
                    r = int(fm[i])
                    w.writerow([i, r, f"{r/fps:.4f}", _root_file(i), file_index(bounds, i)])
            self._log(f"[export] {tif} + _framemap.json + _framemap.csv (uid {_uid()}, sha1 {sha[:8]})")
            status_v.set(f"Exported concatenated stack + sidecars ({len(fm)} frames).")

        def _export_corrected_tiff(path_stem, apply_drift=True, apply_photo=True,
                                   subpixel=True, prog=None):
            """Write a TIFF whose PIXELS are demotion-corrected (each frame warped by -d[t] into the
            anchor frame), plus <stem>_framemap.json / .csv. Unlike `_export_concat` (which stores
            RAW pixels and keeps drift in the sidecar), here the vessel is actually stationary in the
            file — suitable for viewing or for re-opening in the recon window.

            To prevent DOUBLE correction on re-import, the sidecar records
            `pixels_drift_corrected=True` and `drift=False` (there is no residual drift to apply);
            it still keeps `applied_drift_d` for provenance. Photometry, if applied, is likewise
            baked and flagged `pixels_photometry_applied=True`, `photo='off'`."""
            import tifffile, json as _json, hashlib, base64, csv as _csv
            from scipy.ndimage import shift as ndshift
            base = _bk_base(); fm = _fmap()
            if base is None or fm is None:
                messagebox.showwarning("Export", "Nothing to export."); return
            T, H, W = base.shape[0], base.shape[1], base.shape[2]
            d = _disp() if apply_drift else None
            order = 1 if subpixel else 0
            out = np.empty((T, H, W), np.float32)
            with (_Progress("Baking corrected TIFF", total=T) if prog is None else prog) as _p:
                for t in range(T):
                    _p.step(t + 1)
                    fr = np.asarray(base[t], np.float32)
                    if d is not None and t < len(d):
                        fr = ndshift(fr, (-float(d[t, 0]), -float(d[t, 1])), order=order,
                                     mode='nearest')
                    if apply_photo:
                        fr = _photo_map_frame(fr, t)          # per-file LUT -> reference units
                    out[t] = fr
            tif = path_stem + '.tif'
            tifffile.imwrite(tif, out)                        # already (T,H,W)
            sha = hashlib.sha1(open(tif, 'rb').read()).hexdigest()
            root = state.get('root') or {}; prov = state.get('provenance') or []
            bounds = list(state.get('boundaries') or [0, T]); fps = float(fps_var.get())
            dr = state.get('drift')
            doc = dict(schema='frame_provenance/2', uid=_uid(),
                       parent_uid=(prov[-1].get('parent_uid') if prov else None),
                       level=(prov[-1].get('level') if prov else 0),
                       fps=fps, px_um=float(px_var.get()),
                       root=dict(files=root.get('files'), boundaries=root.get('boundaries'),
                                 T=root.get('T')),
                       boundaries=bounds, frame_map=[int(x) for x in fm],
                       segments=[(int(s.get('root_t0', s['t0'])), int(s.get('root_t1', s['t1'])))
                                 for s in state.get('segments', [])],
                       provenance=prov, sha1=sha,
                       # the crucial flags so re-import does NOT correct again
                       pixels_drift_corrected=bool(apply_drift and dr is not None),
                       pixels_photometry_applied=bool(apply_photo and state.get('photo') is not None),
                       drift=False, drift_applied=bool(apply_drift and dr is not None),
                       photo='off')
            if apply_drift and dr is not None:
                doc['applied_drift_d'] = base64.b64encode(
                    np.asarray(dr['d'], np.float16).tobytes()).decode('ascii')
                doc['applied_drift_shape'] = list(np.asarray(dr['d']).shape)
                doc['applied_drift_anchor'] = int(dr.get('anchor', 0))
            if apply_photo and state.get('photo') is not None:
                doc['applied_photo'] = state.get('photo')
            with open(path_stem + '_framemap.json', 'w') as f:
                _json.dump(doc, f, indent=2, default=str)
            with open(path_stem + '_framemap.csv', 'w', newline='') as f:
                w = _csv.writer(f)
                w.writerow(['local_index', 'root_index', 'root_time_s', 'root_file', 'segment_id'])
                for i in range(T):
                    r = int(fm[i])
                    w.writerow([i, r, f"{r/fps:.4f}", _root_file(i), file_index(bounds, i)])
            self._log(f"[export] CORRECTED {tif} (drift={'baked' if apply_drift and dr is not None else 'no'}, "
                      f"photo={'baked' if apply_photo and state.get('photo') is not None else 'no'}, "
                      f"subpixel={subpixel}) + sidecars; sha1 {sha[:8]}")
            status_v.set(f"Exported demotion-corrected TIFF ({T} frames).")

        def _load_concat(tif_path):
            """Load a concatenated TIFF + its sidecar (same stem, else ask). Verify frame count and
            sha1. Install frame_map/root/boundaries + restore uid. No sidecar -> refuse by default;
            offer 'Treat as root' (loud warning: ROOT TIMING UNRECOVERABLE)."""
            import tifffile, json as _json, hashlib, os
            stem = os.path.splitext(tif_path)[0]; side = stem + '_framemap.json'
            stk = np.asarray(tifffile.imread(tif_path), np.float32); T = int(stk.shape[0])
            if not os.path.exists(side):
                side = filedialog.askopenfilename(title="Select the _framemap.json sidecar",
                                                  filetypes=[("JSON", "*.json")]) or ''
            if not side or not os.path.exists(side):
                if messagebox.askyesno("No sidecar",
                        "No frame-map sidecar found.\n\nTreat this TIFF as a ROOT stack?\n"
                        "WARNING: ROOT TIMING WILL BE UNRECOVERABLE — every interval/frequency "
                        "result from this stack will be WRONG."):
                    state['stack'] = stk; state['stack_orig'] = None; state['files'] = [tif_path]
                    state['root'] = dict(files=[tif_path], boundaries=[0, T], T=T,
                                         fps=float(fps_var.get()), px_um=float(px_var.get()))
                    state['provenance'] = [dict(level=0, parent_uid=None, n_in=T, n_out=T,
                                                segments=[], note='load_concat treat-as-root')]
                    _on_stack_changed(make_root_map(T), root=state['root'], boundaries=[0, T],
                                      note='treat_as_root', remap=False)
                    self._log("[load] WARNING: loaded WITHOUT sidecar as ROOT — root timing is "
                              "UNRECOVERABLE; interval/frequency results will be WRONG.")
                return
            doc = _json.load(open(side))
            sha = hashlib.sha1(open(tif_path, 'rb').read()).hexdigest()
            if doc.get('sha1') and sha != doc['sha1']:
                messagebox.showerror("Tampered TIFF",
                    f"tif sha1 mismatch: {sha[:8]} != {doc['sha1'][:8]}. Refusing to load."); return
            fm = np.asarray(doc['frame_map'], np.int64)
            if len(fm) != T:
                messagebox.showerror("Frame count",
                    f"sidecar frame_map has {len(fm)} entries but the TIFF has {T} frames."); return
            state['stack'] = stk; state['stack_orig'] = None; state['files'] = [tif_path]
            rd = doc.get('root') or {}
            state['root'] = dict(files=rd.get('files'), boundaries=rd.get('boundaries'), T=rd.get('T'),
                                 fps=doc.get('fps'), px_um=doc.get('px_um'))
            state['provenance'] = doc.get('provenance') or [dict(level=doc.get('level', 0),
                                        parent_uid=doc.get('parent_uid'), n_in=T, n_out=T,
                                        segments=doc.get('segments', []), note='loaded')]
            # restore photometry (keyed by ROOT file) BEFORE the choke point (which won't reset it)
            if doc.get('pixels_photometry_applied'):
                state['photo'] = None
                self._log("[load] pixels already photometry-applied; not re-applying photometry")
            else:
                state['photo'] = doc.get('photo_full') if doc.get('photo_full') else None
            _on_stack_changed(fm, root=state['root'], boundaries=doc.get('boundaries', [0, T]),
                              note='load_concat', remap=False, uid=doc.get('uid'), carry=False)
            # restore demotion (drift) from the sidecar; warn LOUDLY when absent
            if doc.get('pixels_drift_corrected'):
                state['drift'] = None
                self._log("[load] pixels already drift-corrected; not re-applying drift")
            elif doc.get('drift') and doc.get('drift_d'):
                import base64
                shp = tuple(doc.get('drift_shape', [T, 2]))
                d = np.frombuffer(base64.b64decode(doc['drift_d']), np.float16).astype(np.float32).reshape(shp)
                state['drift'] = dict(d=d, shifts=(-d).astype(np.float32),
                                      quality=np.ones(shp[0], np.float32), valid=np.ones(shp[0], bool),
                                      anchor=int(doc.get('drift_anchor', 0)),
                                      mode=str(doc.get('drift_mode', 'loaded')),
                                      base_shape=(shp[0],) + tuple(stk.shape[1:]),
                                      carried_from=doc.get('drift_carried_from'))
                self._log(f"[load] demotion RESTORED from sidecar (anchor {doc.get('drift_anchor')}, "
                          f"{shp[0]} frames).")
            else:
                state['drift'] = None
                self._log("[load] WARNING: NO demotion in the sidecar — the single FG line will "
                          "sample DIFFERENT anatomy across root time. Re-estimate drift or reload "
                          "the matching set.")
            self._log(f"[load] concatenated stack: {T} frames, uid={_uid()}, level="
                      f"{doc.get('level')}, root frames {int(fm.min())}..{int(fm.max())} "
                      f"(sidecar sha1 {sha[:8]} verified); photo={doc.get('photo', 'off')}.")
            status_v.set(f"Loaded concatenated stack ({T} frames, root timing recovered).")
            try: _display()
            except Exception: pass

        def _fig_provenance():
            """Show the extraction chain level by level (n_in/n_out + segment root ranges)."""
            prov = state.get('provenance') or []
            win = tk.Toplevel(pw); win.title("Provenance (extraction chain)"); win.geometry("820x460")
            txt = tk.Text(win, wrap='none'); txt.pack(fill=tk.BOTH, expand=True, padx=4, pady=4)
            root = state.get('root') or {}
            txt.insert('end', f"current uid = {_uid()}   T = {len(_fmap()) if _fmap() is not None else 0}\n")
            txt.insert('end', f"root: {len(root.get('files') or [])} files, T={root.get('T')}, "
                              f"fps={root.get('fps')}, boundaries={root.get('boundaries')}\n\n")
            cur_drift = 'yes' if state.get('drift') is not None else 'no'
            cur_photo = 'yes' if str((state.get('photo') or {}).get('model', 'off')) != 'off' else 'no'
            txt.insert('end', f"CURRENT: drift carried: {cur_drift}, photo carried: {cur_photo}\n\n")
            for p in prov:
                dc = ('yes' if p.get('drift_carried') else 'no') if 'drift_carried' in p else '-'
                pc = ('yes' if p.get('photo_carried') else 'no') if 'photo_carried' in p else '-'
                txt.insert('end', f"level {p.get('level')}  {p.get('note','')}  "
                                  f"[{p.get('ts','')}]\n")
                txt.insert('end', f"    parent_uid={p.get('parent_uid')}  "
                                  f"n_in={p.get('n_in')} -> n_out={p.get('n_out')}  "
                                  f"drift carried: {dc}  photo carried: {pc}\n")
                for rr in (p.get('segments') or []):
                    txt.insert('end', f"      root range {tuple(rr)}\n")
                txt.insert('end', "\n")
            txt.configure(state='disabled')

        def _seg_clear():
            state['segments'] = []

        def _seg_del(i):
            state['segments'] = [s for s in state['segments'] if s.get('idx') != i]
            _seg_reindex()

        def _seg_stamp_root(s):
            """Attach the ROOT provenance to a segment defined in the CURRENT local space.
            Idempotent. On the root stack `frame_map` is the identity, so root_* == t0/t1."""
            fm = _fmap()
            t0, t1 = int(s['t0']), int(s['t1'])
            if fm is None:
                s.setdefault('root_t0', t0); s.setdefault('root_t1', t1)
                s.setdefault('t_peak_root', int(s.get('t_peak', (t0 + t1) // 2)))
                s.setdefault('root_idx', None)
            else:
                rs = np.asarray(fm[t0:t1], np.int64)
                contiguous = bool(rs.size) and bool(np.all(np.diff(rs) == 1))
                s['root_t0'] = int(rs[0]); s['root_t1'] = int(rs[-1]) + 1
                s['root_idx'] = (None if contiguous else rs.tolist())
                tp = int(np.clip(int(s.get('t_peak', (t0 + t1) // 2)), t0, max(t0, t1 - 1)))
                s['t_peak_root'] = int(fm[tp])
                if not contiguous:
                    self._log(f"[seg] idx {s.get('idx')}: root indices are NOT contiguous "
                              f"({rs[0]}..{rs[-1]}, n={rs.size}); root_idx stored explicitly.")
            s['uid'] = _uid()
            return s

        def _seg_add(t0, t1, source='manual', note='', t_peak=None, ov=None):
            """Validate then append a segment. Returns (ok, reason). Enforces single-file,
            guard-clear, duration >= seg_min_dur_s, and len(segments) < max_seg_var."""
            base = _bk_base()
            if base is None: return (False, "load files first")
            T = base.shape[0]
            t0 = int(max(0, min(int(t0), T - 1))); t1 = int(max(0, min(int(t1), T)))
            if t1 <= t0: return (False, "empty interval")
            bounds = list(state.get('boundaries') or [0, T])
            if not same_file(bounds, t0, t1 - 1):
                return (False, "straddles a file boundary")
            fi = file_index(bounds, t0); f0, f1 = bounds[fi], bounds[fi + 1]
            G = int(state.get('_bnd_guard', 1))
            if t0 < f0 + G or t1 > f1 - G:
                return (False, f"inside the boundary guard (G={G})")
            fps = float(fps_var.get())
            if (t1 - t0) < max(3, int(float(seg_min_dur_s_var.get()) * fps)):
                return (False, f"shorter than min duration {float(seg_min_dur_s_var.get()):.2f}s")
            if len(state['segments']) >= int(max_seg_var.get()):
                return (False, f"already at cap {int(max_seg_var.get())}")
            fm = _fmap()
            root_slice = fm[t0:t1] if fm is not None else np.arange(t0, t1, dtype=np.int64)
            contiguous = bool(fm is None) or bool(np.all(np.diff(root_slice) == 1))
            tp = int((t0 + t1) // 2 if t_peak is None else t_peak)
            state['segments'].append(dict(idx=len(state['segments']), t0=t0, t1=t1, t_peak=tp,
                                          include=True, source=source, note=note, ov=ov, result=None,
                                          uid=_uid(), root_t0=int(root_slice[0]),
                                          root_t1=int(root_slice[-1]) + 1, t_peak_root=_to_root(tp),
                                          root_idx=(None if contiguous else root_slice.astype(np.int64).tolist())))
            _seg_reindex(); return (True, "")

        # ════════════ Processing Profile (identical-processing guarantee) ════════════
        def _seg_profile():
            """Freeze every parameter that affects a segment result into one dict."""
            _fg = _roi_pts('fg_roi')
            return dict(N=int(bk_npts_var.get()), band=int(bk_band_var.get()),
                        diff=str(bk_diff_mode_var.get()), pos=str(bk_pos_est_var.get()),
                        fit=str(bk_fit_var.get()), min_prom=float(bk_min_prom_var.get()),
                        min_r2=float(bk_min_r2_var.get()), min_gated=int(bk_min_gated_var.get()),
                        step_mode=str(step_mode_var.get()), step=int(bk_step_var.get()),
                        n_target=int(bk_ntarget_var.get()), guard=int(state.get('_bnd_guard') or 1),
                        fps=float(fps_var.get()), px_um=float(px_var.get()),
                        drift=bool(_tracking_on()),
                        photo=str((state.get('photo') or {}).get('model', 'off')),
                        diam_len_px=int(seg_diam_len_var.get()), diam_frac=float(seg_diam_frac_var.get()),
                        fphoto=str(fphoto_mode_var.get()),
                        fg_roi=([[float(x), float(y)] for x, y in _fg] if _fg is not None else []))

        def _profile_hash(p):
            import hashlib, json
            return hashlib.sha1(json.dumps(p, sort_keys=True, default=float).encode()).hexdigest()[:12]

        def _verify_identical_processing(rows, allow_heterogeneous=False):
            """Every included segment must carry the same profile_hash. Otherwise log a per-segment
            table of the differing keys and REFUSE the primary aggregate unless the user explicitly
            allows heterogeneous processing. Returns (ok, hash_or_list).

            IDENTICAL PROCESSING means the same step_mode + n_target (both in the profile hash),
            NOT the same derived per-segment step. Under 'fixed_count' the difference step is
            deliberately per-segment: n_target=24 over the 51–153-frame manual segments gives
            step 2–6 (Δt 0.07–0.20 s at 30 fps), i.e. each segment is sampled with the SAME
            NUMBER of difference frames, mirroring 'pick a fixed count of frames per cycle'. The
            regression uses REAL times, so a per-segment step leaves the velocity slope unbiased."""
            # Stage 4: step table — expose the derived step so 'identical processing' is auditable.
            self._log("[batch] step table (step_mode governs identity, derived step may vary):")
            self._log("[batch]   seg | n_frames | step | n_diff_frames | passed")
            for r in rows:
                nf = int(r.get('t1', 0)) - int(r.get('t0', 0))
                self._log(f"[batch]   #{r.get('idx'):>3} | {nf:>8} | {int(r.get('step', 1)):>4} | "
                          f"{int(r.get('n_diff_frames', 0)):>13} | {'PASS' if r.get('passed') else 'FAIL'}")
            hashes = [r.get('profile_hash') for r in rows]
            uniq = sorted(set(h for h in hashes if h))
            if len(uniq) <= 1:
                return (True, uniq[0] if uniq else None)
            self._log(f"[batch] HETEROGENEOUS PROCESSING: {len(uniq)} distinct profile hashes:")
            ref_h = hashes[0]; ref_p = next((r.get('profile') for r in rows if r.get('profile')), {}) or {}
            for r in rows:
                h = r.get('profile_hash'); p = r.get('profile') or {}
                if h == ref_h: continue
                diffk = sorted(k for k in set(list(ref_p) + list(p)) if ref_p.get(k) != p.get(k))
                self._log(f"[batch]   seg#{r.get('idx')}: hash {h} differs from {ref_h} in {diffk}")
            if allow_heterogeneous or bool(seg_allow_hetero_var.get()):
                self._log("[batch] WARNING: proceeding with heterogeneous processing (user override).")
                return (True, None)
            return (False, uniq)

        def _auto_suggest_segments(k=None):
            """Rank candidate flow intervals (per-file bolus runs padded by cyc_pad, clipped to a
            single file and clear of the guard) by R2_probe * mass and keep the best <= k."""
            base = _bk_base()
            if base is None:
                messagebox.showwarning("Segments", "Load files first."); return
            if state.get('fg_roi') is None or len(state['fg_roi']) < 2:
                messagebox.showwarning("Segments", "Draw the FG line ROI first."); return
            k = int(max_seg_var.get()) if k is None else int(k)
            fps = float(fps_var.get()); T = base.shape[0]
            bounds = list(state.get('boundaries') or [0, T])
            _bol, invalid, g = _quiet_mask_per_file(base)
            gcorr = _photo_g_corr(g, bounds)
            G = int(state.get('_bnd_guard', 1)); pad = int(round(float(cyc_pad_s_var.get()) * fps))
            min_len = max(3, int(float(seg_min_dur_s_var.get()) * fps))
            baseline = np.zeros(T)
            for fi in range(len(bounds) - 1):
                f0, f1 = bounds[fi], bounds[fi + 1]; baseline[f0:f1] = np.median(gcorr[f0:f1])
            cands = []
            for (r0, r1) in contiguous_runs(_bol):          # r1 inclusive
                fi = file_index(bounds, r0); f0, f1 = bounds[fi], bounds[fi + 1]
                a = max(f0 + G, r0 - pad); b = min(f1 - G, r1 + 1 + pad)
                if b - a < min_len or not same_file(bounds, a, b - 1): continue
                mass = float(np.sum(np.clip(gcorr[a:b] - baseline[a:b], 0, None)))
                dur = b - a; stp = max(1, dur // 40); r2p = 0.0
                try:
                    B, tix, al = _diff_profiles(a, b, step=stp)
                    if B is not None and B.shape[1] >= 2:
                        s_, am, fw, ga = _track_bolus(B, al); gi = ga & np.isfinite(s_)
                        if gi.sum() >= 2:
                            fr = _robust_line_fit((tix / fps)[gi], s_[gi], method=bk_fit_var.get())
                            r2p = max(0.0, float(fr['r2']))
                except Exception:
                    r2p = 0.0
                tp = a + int(np.argmax(gcorr[a:b]))
                cands.append(dict(t0=a, t1=b, t_peak=tp, mass=mass, r2=r2p, score=r2p * mass))
            cands.sort(key=lambda c: -c['score'])
            self._log(f"[seg] {len(cands)} candidate runs (score = R2_probe * mass):")
            for i, c in enumerate(cands[:20]):
                self._log(f"[seg]  cand {i}: [{c['t0']},{c['t1']}) dur={(c['t1']-c['t0'])/fps:.2f}s "
                          f"r2={c['r2']:.2f} mass={c['mass']:.4g} score={c['score']:.4g}")
            chosen = []
            for c in cands:
                if any(not (c['t1'] <= s['t0'] or c['t0'] >= s['t1']) for s in chosen): continue
                chosen.append(c)
                if len(chosen) >= k: break
            chosen.sort(key=lambda c: c['t0'])
            state['segments'] = [dict(idx=i, t0=c['t0'], t1=c['t1'], t_peak=c['t_peak'],
                                      include=True, source='auto', note='', ov=None, result=None)
                                 for i, c in enumerate(chosen)]
            for s in state['segments']: _seg_stamp_root(s)
            self._log(f"[seg] selected {len(chosen)} non-overlapping segments (<= {k}).")
            status_v.set(f"Auto-suggested {len(chosen)} flow segments.")
            return state['segments']

        def _seg_dff(t0, t1):
            tr = _cycle_intensity_trace(t0, t1)
            if tr is None or tr.size < 3: return float('nan')
            b0 = float(np.percentile(tr, 10)); return float((np.max(tr) - b0) / (b0 + 1e-9))

        def _out_bolus_kinetics(rows, prof):
            """OUTPUT (from the old _bolus_kinetics): forest of per-segment bolus velocity + pooled."""
            if not rows: return
            aggrows = [dict(idx=r['idx'], slope=r['v_bolus'], se=r['se'], include=True,
                            _flag=r.get('_flag')) for r in rows]
            agg = _aggregate_slopes(aggrows); _fig_forest(aggrows, agg)
            self._log(f"[out:bolus] v = {agg['mean']:+.1f} +/- {agg['sd']:.1f} um/s, "
                      f"CV={agg['cv']:.1f}%, n={agg['n_used']}")

        def _out_intensity_ensemble(rows, prof):
            """OUTPUT (from the old _cycle_ensemble_stats): dF/F0(phase) ensemble from rows[i]['I']."""
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            ph = np.linspace(0, 1, 100); segs = []
            for r in rows:
                I = r.get('I')
                if I is None: continue
                tr = np.nanmean(I, axis=0); b0 = float(np.percentile(tr, 10))
                segs.append(np.interp(ph, np.linspace(0, 1, len(tr)), (tr - b0) / (b0 + 1e-9)))
            if not segs:
                messagebox.showwarning("Intensity ensemble", "No intensity kymographs in the rows."); return
            M = np.array(segs); mu = M.mean(0); sd = M.std(0, ddof=1) if M.shape[0] > 1 else np.zeros(M.shape[1])
            w = tk.Toplevel(pw); w.title("Intensity ensemble (dF/F0)"); w.geometry("780x540")
            fig = Figure(figsize=(6.6, 4.5), dpi=130, facecolor='white'); ax = fig.add_subplot(111)
            for s_ in segs: ax.plot(ph, s_, color='0.75', lw=0.4, alpha=0.6)
            ax.plot(ph, mu, color='#D55E00', lw=1.6); ax.fill_between(ph, mu - sd, mu + sd, color='#D55E00', alpha=0.25, lw=0)
            ax.set_xlabel('phase'); ax.set_ylabel('dF/F0'); ax.set_title(f'Intensity ensemble (n={len(segs)})')
            ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False); fig.tight_layout()
            c = FigureCanvasTkAgg(fig, w); c.draw(); c.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            self._log(f"[out:intensity] dF/F0 ensemble over {len(segs)} segments")

        def _out_diameter_ef(rows, prof):
            """OUTPUT (diameter physiology): EDD/ESD/EF/FPF + D(phase) ensemble from rows[i]['D']."""
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            ph = np.linspace(0, 1, 100); segs = []; efs = []; edds = []; esds = []
            for r in rows:
                Dm = r.get('Dmed')
                if Dm is None or np.isfinite(Dm).sum() < 3: continue
                segs.append(np.interp(ph, np.linspace(0, 1, len(Dm)), np.nan_to_num(Dm, nan=float(np.nanmean(Dm)))))
                efs.append(r.get('EF')); edds.append(r.get('EDD')); esds.append(r.get('ESD'))
            if not segs:
                messagebox.showwarning("Diameter & EF", "No diameter kymographs in the rows."); return
            M = np.array(segs); mu = M.mean(0); sd = M.std(0, ddof=1) if M.shape[0] > 1 else np.zeros(M.shape[1])
            ef = float(np.nanmean(efs)); edd = float(np.nanmean(edds)); esd = float(np.nanmean(esds))
            w = tk.Toplevel(pw); w.title("Diameter & EF (2D projected ESTIMATE)"); w.geometry("780x540")
            fig = Figure(figsize=(6.6, 4.5), dpi=130, facecolor='white'); ax = fig.add_subplot(111)
            ax.plot(ph, mu, color='#0072B2', lw=1.6); ax.fill_between(ph, mu - sd, mu + sd, color='#0072B2', alpha=0.25, lw=0)
            ax.axhline(edd, color='0.4', ls=':', lw=0.8); ax.axhline(esd, color='0.4', ls=':', lw=0.8)
            ax.text(0.02, edd, 'EDD', fontsize=7, va='bottom'); ax.text(0.02, esd, 'ESD', fontsize=7, va='top')
            ax.set_xlabel('phase'); ax.set_ylabel('diameter (um)')
            ax.set_title(f'D(phase): EDD={edd:.1f} ESD={esd:.1f} EF={ef:.3f} (est., n={len(segs)})')
            ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False); fig.tight_layout()
            c = FigureCanvasTkAgg(fig, w); c.draw(); c.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            self._log(f"[out:diameter] EDD={edd:.1f} ESD={esd:.1f} EF={ef:.3f} (2D projected estimate)")

        def _out_kymo_velocity(rows, prof):
            """OUTPUT (from the old _kymo_pulse_cycles): regression slope vs cross-correlation
            velocity agreement (scatter + Bland-Altman)."""
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            vs = np.array([r['v_bolus'] for r in rows], float)
            vx = np.array([r.get('vxcorr', np.nan) for r in rows], float)
            m = np.isfinite(vs) & np.isfinite(vx)
            if m.sum() < 1:
                messagebox.showwarning("Kymograph velocity", "No cross-correlation velocities."); return
            vs2 = vs[m]; vx2 = vx[m]; d = vs2 - vx2
            bias = float(np.mean(d)); sdd = float(np.std(d, ddof=1)) if d.size >= 2 else float('nan')
            w = tk.Toplevel(pw); w.title("Kymograph velocity (fit vs xcorr)"); w.geometry("960x480")
            fig = Figure(figsize=(8.4, 4.2), dpi=130, facecolor='white')
            ax1 = fig.add_subplot(1, 2, 1); ax2 = fig.add_subplot(1, 2, 2)
            lim = [min(vs2.min(), vx2.min()), max(vs2.max(), vx2.max())]
            ax1.plot(lim, lim, '--', color='0.6', lw=0.8); ax1.plot(vx2, vs2, 'o', color='#0072B2', ms=4)
            ax1.set_xlabel('v_xcorr (um/s)'); ax1.set_ylabel('v_fit (um/s)'); ax1.set_title('agreement')
            mean_v = 0.5 * (vs2 + vx2)
            ax2.axhline(bias, color='#D55E00', lw=1.0)
            if np.isfinite(sdd):
                ax2.axhline(bias + 1.96 * sdd, color='0.5', ls='--', lw=0.8)
                ax2.axhline(bias - 1.96 * sdd, color='0.5', ls='--', lw=0.8)
            ax2.plot(mean_v, d, 'o', color='#333', ms=4)
            ax2.set_xlabel('mean velocity (um/s)'); ax2.set_ylabel('v_fit - v_xcorr')
            ax2.set_title(f'Bland-Altman bias={bias:+.1f}')
            for ax in (ax1, ax2): ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
            fig.tight_layout(); c = FigureCanvasTkAgg(fig, w); c.draw(); c.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            self._log(f"[out:kymo] fit vs xcorr bias={bias:+.1f} um/s (n={int(m.sum())})")

        _SEG_EXAMPLE = ("2783-3293\n3650-4150\n6355-6855\n9947-10447\n12021-12521\n"
                        "16729-17229\n20549-21549\n21609-22109\n22689-23189\n28580-29080\n")

        def _self_test_frame_ranges():
            """Feed parse_frame_ranges/validate_frame_ranges the exact 10-line example and assert."""
            T = 28978; msgs = []; ok = True
            r = parse_frame_ranges(_SEG_EXAMPLE, half_open=True)
            ns = [t1 - t0 for t0, t1, _ in r]
            c1 = (len(r) == 10 and ns == [510, 500, 500, 500, 500, 500, 1000, 500, 500, 500])
            msgs.append(f"parsed 10 rows, N={ns} -> {'OK' if c1 else 'FAIL'}"); ok &= c1
            v = validate_frame_ranges(r, T, [0, T], guard=0, min_dur=1, max_n=10)
            c2 = ('out_of_range' in v[9]['flags'])
            msgs.append(f"row 10 out_of_range -> {'OK' if c2 else 'FAIL'}"); ok &= c2
            c3 = ('duration_outlier' in v[6]['flags'] and 'duration_outlier' in v[0]['flags'])
            msgs.append(f"rows 7 & 1 duration_outlier (z={v[6]['z']:.0f}, {v[0]['z']:.1f}) "
                        f"-> {'OK' if c3 else 'FAIL'}"); ok &= c3
            rc = list(r); rc[9] = (28580, 28978, '')
            vc = validate_frame_ranges(rc, T, [0, T])
            c4 = (vc[9]['n'] == 398 and 'duration_outlier' in vc[9]['flags'])
            msgs.append(f"clamp row10 -> N={vc[9]['n']} + duration_outlier -> {'OK' if c4 else 'FAIL'}"); ok &= c4
            rcl = parse_frame_ranges(_SEG_EXAMPLE, half_open=False)
            c5 = all((b - a) == n + 1 for (a, b, _), n in zip(rcl, ns))
            msgs.append(f"'[start, end]' -> N+1 for every row -> {'OK' if c5 else 'FAIL'}"); ok &= c5
            vb = validate_frame_ranges([(90, 210, '')], 300, [0, 100, 300], guard=0)
            c6 = ('crosses_boundary' in vb[0]['flags'])
            msgs.append(f"boundary-straddling row -> crosses_boundary -> {'OK' if c6 else 'FAIL'}"); ok &= c6
            # ── resolution (Stage 2) ──
            rr = parse_frame_ranges('2783-3293', True)
            rc7 = resolve_frame_ranges(rr, 29000, [0, 3000, 29000], guard=3, policy='clip')
            c7 = (len(rc7) == 1 and (rc7[0]['t0'], rc7[0]['t1']) == (2783, 2997)
                  and 'clip_boundary' in rc7[0]['actions'] and rc7[0]['orig'] == (2783, 3293))
            msgs.append(f"clip 2783-3293 -> {(rc7[0]['t0'], rc7[0]['t1'])} {rc7[0]['actions']} "
                        f"(N 510->{rc7[0]['n']}) -> {'OK' if c7 else 'FAIL'}"); ok &= c7
            rs = resolve_frame_ranges(rr, 29000, [0, 3000, 29000], guard=3, policy='split')
            pts = [(d['t0'], d['t1']) for d in rs]
            c8 = ((2783, 2997) in pts and (3003, 3293) in pts)
            msgs.append(f"split 2783-3293 -> {pts} -> {'OK' if c8 else 'FAIL'}"); ok &= c8
