                                                     coverage_fraction=A.get('coverage'),
                                                     searched_frames=(A.get('timeline') or {}).get('searched_frames'),
                                                     root_T_frames=(A.get('timeline') or {}).get('root_T'),
                                                     n_windows=(A.get('timeline') or {}).get('n_windows'),
                                                     windows_with_event=(A.get('timeline') or {}).get('windows_with_event'),
