        def _fig_root_timeline(rows, stats):
            """Stage 6: physiology laid out on the ROOT recording clock (not the concatenated /
            virtual index). Six panels: (a) full timeline of pulses on the whole recording with
            the searched windows shaded; (b) ISI sequence + distribution from the SORTED root
            peaks; (c) bolus velocity vs root time with a trend + 95% CI band; (d) EF / amplitude
            vs root time; (e) forest of per-event velocity; (f) honest-denominator summary table.
            The frequency shown is WITHHELD unless detection scope is 'exhaustive'."""
            import matplotlib.pyplot as plt
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            VERM, BLUE, GREEN, GREY = '#D55E00', '#0072B2', '#009E73', '#888888'
            rs = stats.get('rows_sorted') or sorted(rows, key=lambda r: float(r.get('t_peak_root', 0)))
            rfps = stats['rfps']; rec_s = stats['rec_s']
            tpk = np.array([float(r.get('t_peak_root', 0)) / rfps for r in rs], float)   # root seconds
            isi = stats['isi']
            with apply_nature_style():
                plt.rcParams['svg.fonttype'] = 'none'
                fig = Figure(figsize=nature_figsize_in('double', height_in=6.8), dpi=200, facecolor='white')
                axA = fig.add_subplot(3, 2, 1); axB = fig.add_subplot(3, 2, 2)
                axC = fig.add_subplot(3, 2, 3); axD = fig.add_subplot(3, 2, 4)
                axE = fig.add_subplot(3, 2, 5); axF = fig.add_subplot(3, 2, 6)
                # (a) full timeline -----------------------------------------------------------
                for (r0, r1) in stats.get('windows') or []:
                    axA.axvspan(r0 / rfps, r1 / rfps, color=GREY, alpha=0.18, lw=0)
                for i, r in enumerate(rs):
                    axA.axvline(tpk[i], color=VERM, lw=1.0)
                    axA.text(tpk[i], 1.02, f"#{r.get('idx_orig', r.get('idx'))}", rotation=90,
                             fontsize=4, ha='center', va='bottom', color=VERM)
                _idx_pos = {int(r.get('idx')): tpk[i] for i, r in enumerate(rs)}
                for d in stats.get('doublets') or []:
                    xa = _idx_pos.get(int(d['a'])); xb = _idx_pos.get(int(d['b']))
                    if xa is not None and xb is not None:
                        axA.plot([xa, xb], [0.5, 0.5], color=BLUE, lw=1.5, marker='|')
                        axA.text((xa + xb) / 2, 0.55, f"doublet {d['isi_s']:.1f}s",
                                 fontsize=4, ha='center', va='bottom', color=BLUE)
                axA.set_xlim(0, rec_s if np.isfinite(rec_s) else (tpk.max() if tpk.size else 1))
                axA.set_ylim(0, 1.15); axA.set_yticks([])
                axA.set_title(f"(a) pulses on ROOT recording (shaded = searched {100.0*stats['coverage']:.1f}%)", fontsize=7)
                axA.set_xlabel('root time (s)')
                # (b) ISI sequence + distribution --------------------------------------------
                if isi.size:
                    axB.plot(np.arange(1, isi.size + 1), isi, 'o-', color=BLUE, ms=3, lw=0.8)
                    axB.axhline(stats['isi_mean'], color='0.4', ls='--', lw=0.8)
                    if np.isfinite(stats['doublet_s']):
                        axB.axhline(stats['doublet_s'], color=VERM, ls=':', lw=0.8)
                        axB.text(0.02, stats['doublet_s'], 'doublet', color=VERM, fontsize=4, va='bottom')
                    for j in range(isi.size):
                        if isi[j] < stats['doublet_s']:
                            axB.plot([j + 1], [isi[j]], 'o', color=VERM, ms=5, mfc='none')
                axB.set_title(f"(b) ISI seq  mean={stats['isi_mean']:.1f}±{stats['isi_sd']:.1f}s CV {stats['isi_cv']:.0f}%", fontsize=7)
                axB.set_xlabel('interval #'); axB.set_ylabel('ISI (s)')
                # (c) velocity vs root time with trend + CI ----------------------------------
                vv = np.array([float(r.get('v_bolus', np.nan)) for r in rs], float)
                se = np.array([float(r.get('se', np.nan)) for r in rs], float)
                good = np.isfinite(tpk) & np.isfinite(vv)
                axC.errorbar(tpk[good], vv[good], yerr=1.96 * np.nan_to_num(se[good]),
                             fmt='o', color=BLUE, ms=3, lw=0.7, capsize=2)
                if good.sum() >= 2:
                    x = tpk[good]; y = vv[good]
                    A_ = np.vstack([x, np.ones_like(x)]).T
                    coef, *_ = np.linalg.lstsq(A_, y, rcond=None)
                    xf = np.linspace(x.min(), x.max(), 50); yf = coef[0] * xf + coef[1]
                    axC.plot(xf, yf, color=VERM, lw=1.0)
                    resid = y - (coef[0] * x + coef[1])
                    s_err = np.sqrt(np.sum(resid ** 2) / max(len(x) - 2, 1))
                    xm = x.mean(); sxx = np.sum((x - xm) ** 2) + 1e-12
                    ci = 1.96 * s_err * np.sqrt(1.0 / len(x) + (xf - xm) ** 2 / sxx)
                    axC.fill_between(xf, yf - ci, yf + ci, color=VERM, alpha=0.2, lw=0)
                axC.set_title('(c) v_bolus vs root time (trend±95% CI)', fontsize=7)
                axC.set_xlabel('root time (s)'); axC.set_ylabel('v_bolus (um/s)')
                # (d) EF / amplitude vs root time --------------------------------------------
                ef = np.array([float(r.get('EF', np.nan)) for r in rs], float)
                axD.plot(tpk, ef, 'o-', color=GREEN, ms=3, lw=0.8)
                axD.set_title('(d) EF vs root time (2D projected estimate)', fontsize=7)
                axD.set_xlabel('root time (s)'); axD.set_ylabel('EF (est.)')
                # (e) forest of per-event velocity -------------------------------------------
                yy = np.arange(len(rs))[::-1]
                for i, r in enumerate(rs):
                    axE.errorbar([vv[i]], [yy[i]], xerr=[1.96 * (se[i] if np.isfinite(se[i]) else 0)],
                                 fmt='o', color='#333', ms=3, lw=0.8, capsize=2)
                    axE.text(axE.get_xlim()[0], yy[i], f" #{r.get('idx_orig', r.get('idx'))}", fontsize=4, va='center')
                axE.set_yticks([]); axE.set_title('(e) per-event v_bolus (root order)', fontsize=7)
                axE.set_xlabel('v_bolus (um/s)')
                # (f) honest summary table ----------------------------------------------------
                axF.axis('off')
                freq_txt = (f"{stats['freq_cpm']:.2f} cpm" if np.isfinite(stats['freq_cpm'])
                            else f"WITHHELD ({stats['scope'] or 'unset'})")
                s9 = stats.get('sensitivity') or {}
                tb = [['quantity', 'value'],
                      ['n events', f"{stats['n_events']}"],
                      ['detection scope', stats['scope'] or '(unset)'],
                      ['recording (s)', f"{rec_s:.1f}"],
                      ['coverage', f"{100.0*stats['coverage']:.1f}% ({stats['searched_frames']}/{stats['root_T']})"],
                      ['frequency', freq_txt],
                      ['  (biased, do NOT report)', f"{stats['biased_cpm']:.2f} cpm"],
                      ['ISI mean±SD', f"{stats['isi_mean']:.1f}±{stats['isi_sd']:.1f}s"],
                      ['ISI CV', f"{stats['isi_cv']:.0f}%"],
                      ['windows (with event)', f"{stats['n_windows']} ({stats['windows_with_event']})"],
                      ['events/window hist', f"{stats['hist']}"],
                      ['doublets (<%.0fs)' % stats['doublet_s'], f"{len(stats.get('doublets') or [])}"],
                      ['n=%d one/window' % s9.get('n_events', 0),
                       f"ISI {s9.get('isi_mean', float('nan')):.1f}s" +
                       (f", {s9.get('freq_cpm'):.2f} cpm" if np.isfinite(s9.get('freq_cpm', float('nan'))) else "")]]
                t = axF.table(cellText=tb, loc='center', cellLoc='left')
                t.auto_set_font_size(False); t.set_fontsize(4.6); t.scale(1, 1.15)
                axF.set_title('(f) honest-denominator summary', fontsize=7)
                for ax, L in ((axA, 'a'), (axB, 'b'), (axC, 'c'), (axD, 'd'), (axE, 'e'), (axF, 'f')):
                    panel_letter(ax, L)
                fig.suptitle(f"ROOT-time physiology -- {stats['n_events']} events, freq {freq_txt}, "
                             f"coverage {100.0*stats['coverage']:.1f}%   "
                             f"[frequency withheld unless detection is exhaustive]", fontsize=7)
                fig.tight_layout()
            win = tk.Toplevel(pw); win.title("ROOT-time physiology"); win.geometry("1200x840")
            bar = ttk.Frame(win); bar.pack(fill=tk.X, padx=4, pady=3)
            ttk.Button(bar, text="Save Fig", command=lambda: _save_fig_dialog(fig, parent=win, default_stem="root_timeline")).pack(side=tk.LEFT, padx=2)
            c = FigureCanvasTkAgg(fig, win); c.draw(); c.get_tk_widget().pack(fill=tk.BOTH, expand=True)

        def _analyze_segments():
            """Thin wrapper -- ONE analysis implementation is the batch runner."""
            return _segment_batch_run()

        def _self_test_segment_batch():
            """Synthesize 10 IDENTICAL contractions (bolus at 80 um/s; EDD=60/ESD=42 um -> EF=0.510)
            with Poisson noise + a drift ramp, and verify the batch recovers them as repeats."""
            import numpy as _np
            save = {k: state.get(k) for k in ('stack', 'stack_orig', 'boundaries', 'photo',
                    '_invalid_frames', '_bnd_guard', 'drift', 'fg_roi', 'segments', 'current_frame',
                    'frame_map', 'stack_uid', 'root', 'provenance', '_invmap_cache')}
            old_fps = fps_var.get(); old_px = px_var.get()
            old_N = bk_npts_var.get(); old_band = bk_band_var.get(); old_dl = seg_diam_len_var.get()
            msgs = []; ok = True
            try:
                fps = 100.0; px_um = 2.0; v_true = 80.0; EDD_t, ESD_t = 60.0, 42.0
                EF_true = (EDD_t ** 2 - ESD_t ** 2) / EDD_t ** 2
                # frame must be tall enough that the perpendicular diameter window reaches the true
                # baseline (>= 3*sigma each side); _fwhm_from_profile uses min(profile) as baseline.
                H, Wd = 120, 460; cy = 60.0; x_lo, x_hi = 40.0, 420.0
                sig_edd = EDD_t / (2.3548 * px_um); sig_esd = ESD_t / (2.3548 * px_um)
                Lc = 70; gap = 20; ncon = 10; per = Lc + gap; T = per * ncon
                rng = _np.random.default_rng(3)
                stack = _np.zeros((T, H, Wd), _np.float32); peaks = []
                xs = _np.arange(Wd)[None, :]; ys = _np.arange(H)[:, None]
                for c in range(ncon):
                    c0 = c * per
                    for kf in range(per):
                        t = c0 + kf; frac = kf / (Lc - 1) if kf < Lc else 1.0
                        bump = _np.exp(-((frac - 0.5) ** 2) / (2 * 0.16 ** 2)) if kf < Lc else 0.0
                        sig_y = sig_edd - (sig_edd - sig_esd) * bump
                        vessel = 800.0 * _np.exp(-((ys - cy) ** 2) / (2.0 * sig_y ** 2)) * _np.ones((1, Wd))
                        img = 40.0 + vessel
                        if kf < Lc:
                            xc = x_lo + (v_true / px_um) * (kf / fps)
                            if xc <= x_hi:
                                img = img + 1400.0 * _np.exp(-(((xs - xc) ** 2) + ((ys - cy) ** 2)) / (2.0 * 3.0 ** 2))
                        stack[t] = rng.poisson(_np.clip(img, 0, None)).astype(_np.float32)
                    peaks.append(c0 + Lc // 2)
                state['stack'] = stack; state['stack_orig'] = stack
                state['boundaries'] = [0, T]
                state['root'] = dict(files=['synthetic'], boundaries=[0, T], T=int(T), fps=fps, px_um=px_um)
                _on_stack_changed(make_root_map(T), root=state['root'], boundaries=[0, T],
                                  remap=False, note='selftest_batch', carry=False)
                state['photo'] = None; state['drift'] = None
                state['_invalid_frames'] = None; state['_bnd_guard'] = 2; state['current_frame'] = 0
                state['fg_roi'] = [[float(x_lo), float(cy)], [float(x_hi), float(cy)]]
                fps_var.set(fps); px_var.set(px_um)
                bk_npts_var.set(120); bk_band_var.set(4); seg_diam_len_var.set(81)
                state['_bk_cache'] = {}
                state['segments'] = []
                for c in range(ncon):
                    c0 = c * per
                    okc, why = _seg_add(c0 + 3, c0 + Lc - 2, source='auto', t_peak=peaks[c])
                    if not okc: msgs.append(f"seg add {c} rejected: {why}")
                prof = _seg_profile()
                rows = [_recon_block(s, prof) for s in _seg_included()]
                vs = _np.array([r['v_bolus'] for r in rows]); efs = _np.array([r['EF'] for r in rows])
                verr = _np.abs(vs - v_true) / v_true * 100.0
                c1 = bool(_np.all(verr < 10.0))
                msgs.append(f"per-segment v within 10% of {v_true}: max err {float(_np.nanmax(verr)):.1f}% "
                            f"-> {'OK' if c1 else 'FAIL'}"); ok &= c1
                cv = 100.0 * float(_np.std(vs, ddof=1)) / (abs(float(_np.mean(vs))) + 1e-9)
                c2 = cv < 5.0
                msgs.append(f"velocity CV across segments = {cv:.2f}% (<5%) -> {'OK' if c2 else 'FAIL'}"); ok &= c2
                ef_err = _np.abs(_np.nanmean(efs) - EF_true) / EF_true * 100.0
                c3 = ef_err < 10.0
                msgs.append(f"mean EF={float(_np.nanmean(efs)):.3f} vs {EF_true:.3f} (err {ef_err:.1f}%<10%) "
                            f"-> {'OK' if c3 else 'FAIL'}"); ok &= c3
                hashes = set(r['profile_hash'] for r in rows)
                c4 = len(hashes) == 1
                msgs.append(f"all {len(rows)} profile hashes identical ({len(hashes)}) -> {'OK' if c4 else 'FAIL'}"); ok &= c4
                inc = _seg_included(); inc[0]['ov'] = dict(pos='peak')
                rows_h = [_recon_block(s, prof) for s in inc]
                verdict, _hi = _verify_identical_processing(rows_h, allow_heterogeneous=False)
                c5 = (verdict is False)
                msgs.append(f"one ov override -> verify REFUSES aggregate = {not verdict} -> {'OK' if c5 else 'FAIL'}"); ok &= c5
                inc[0]['ov'] = None
                mid = per * 5
                state['boundaries'] = [0, mid, T]
                tl, dropped = _valid_diff_frames(mid - 6, mid + 6, 'central', 1, guard=2)
                c6 = dropped > 0 and all((tt not in tl) for tt in range(mid - 1, mid + 2))
                msgs.append(f"boundary stencils excluded by _valid_diff_frames: dropped {dropped} "
                            f"-> {'OK' if c6 else 'FAIL'}"); ok &= c6
            except Exception as _e:
                import traceback as _tb; msgs.append("EXCEPTION: " + repr(_e)); ok = False
                self._log("[selftest] " + _tb.format_exc())
            finally:
                for k, v in save.items():
                    (state.__setitem__(k, v) if v is not None else state.pop(k, None))
                fps_var.set(old_fps); px_var.set(old_px); bk_npts_var.set(old_N)
                bk_band_var.set(old_band); seg_diam_len_var.set(old_dl); state['_bk_cache'] = {}
            report = "SEGMENT BATCH SELF-TEST: " + ("PASS" if ok else "FAIL") + "\n\n" + "\n".join(msgs)
            self._log("[selftest] " + report.replace("\n", "\n[selftest] "))
