                state['frame_map'] = _np.arange(T, dtype=_np.int64)
                state['root'] = dict(files=['synthetic'], boundaries=[0, T], T=T, fps=30.0, px_um=1.0)
                state['stack_uid'] = 'selftest_root'; state['boundaries'] = [0, T]; state['provenance'] = []
                state['drift'] = dict(d=d_full.copy(), shifts=-d_full.copy(), anchor=0, mode='rigid',
                                      base_shape=(T, 32, 32), quality=_np.ones(T, _np.float32),
                                      valid=_np.ones(T, bool), label='selftest')
                photo_sentinel = dict(model='poly', xk=[1.0, 2.0], yk=[0.5, 1.5], a=[1.0], b=[0.0], ref=0, score=0.9)
                state['photo'] = photo_sentinel
                old_uid = state['stack_uid']
                local_idx = _np.arange(10, 40, dtype=_np.int64)          # extract frames 10..39
                new_map = state['frame_map'][local_idx]
                _on_stack_changed(new_map, root=state['root'], boundaries=[0, len(local_idx)],
                                  note='selftest_carry', remap=False, carry=True, local_idx=local_idx)
                dr = state.get('drift')
