                msgs.append(f"windows_only REFUSES frequency (NaN, valid=False) -> {'OK' if c else 'FAIL'}"); ok &= c
                c = _np.isfinite(st2['biased_cpm']) and st2['biased_cpm'] > st['freq_cpm']
                msgs.append(f"biased_cpm = {st2['biased_cpm']:.2f} > honest {st['freq_cpm']:.2f} (never reported as freq) -> {'OK' if c else 'FAIL'}"); ok &= c
                detection_scope_var.set('')
