            report = "SEGMENT-SETS SELF-TEST: " + ("PASS" if ok else "FAIL") + "\n\n" + "\n".join(msgs)
            self._log("[selftest] " + report.replace("\n", "\n[selftest] "))
            (messagebox.showinfo if ok else messagebox.showerror)("Segment-sets self-test", report)

