                state['root'] = dict(files=['synthetic'], boundaries=[0, T], T=int(T), fps=fps, px_um=px_um)
                _on_stack_changed(make_root_map(T), root=state['root'], boundaries=[0, T],
                                  remap=False, note='parity', carry=False)
                state['photo'] = None; state['drift'] = None; state['_invalid_frames'] = None
                state['_bnd_guard'] = 2; state['current_frame'] = 0; state['fg_roi'] = cl.tolist()
                fps_var.set(fps); px_var.set(px_um); bk_npts_var.set(80); bk_band_var.set(4)
                seg_diam_len_var.set(80)                    # padc large -> crop == full frame (exact parity)
                bk_diff_mode_var.set('consecutive'); bk_fit_var.set('ransac'); bk_min_prom_var.set(0.10)
                step_mode_var.set('fixed_count'); bk_ntarget_var.set(24); state['_bk_cache'] = {}
                prof = _seg_profile()
                nt = max(2, int(prof['n_target'])); sel = _np.unique(_np.linspace(0, T - 1, min(nt, T)).astype(int)).tolist()
                res_ref = pulse_arclength_core(proj, sel, cl, n_pts=int(prof['N']), band_px=int(prof['band']),
                                               pxu=px_um, mode=str(prof['diff']), sigma_xy=0.0, sat=None)
                vel_ref = recon_velocity_from_arclength(res_ref, fps, method=str(prof['fit']), prom=float(prof['min_prom']))
                v_ref = vel_ref['slope_um_s']
                seg = dict(idx=0, t0=0, t1=T, root_t0=0, root_t1=T, include=True, uid=_uid())
                rb = _recon_block(seg, prof); v_batch = rb['v_bolus']
